window.HADITH_CHUNKS['13_1'] = [{"id": 6866, "bookId": 13, "volNo": "1", "hadithNo": 1, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "اعمال کا دار ومدار نیتوں پر ہے", "arabic": "عَنْ اَمِیْرِ الْمُؤمِنِیْن اَبِيْ حَفْصٍ عُمَرَ بْنِ الْخَطَّابِ رَضِیَ الله عَنْہ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُوْلُ: ’’اِنَّـمَا الْاَعْمَالُ بِالنِّيَّاتِ وَ اِنَّمَا لِكُلِّ امْرِئٍ مَّا نَوٰى فَمَنْ كَانَتْ هِجْرَتُهٗ اِلَی اللهِ وَرَسُوْلِهٖ فَهِجْرَتُهٗ اِلَى اللهِ وَرَسُوْلِهٖ وَمَنْ كَانَتْ هِجْرَتُهٗ لِدُنْـيَا يُصِيْبُهَا اَوِ امْرَأَةٍ يَّنْكِحُهَا فَهِجْرَتُهٗ اِلٰى مَا هَاجَرَ اِلَيْهِ. ‘‘ (رَوَاهُ اِمَامَا الْمُحَدِّثِيْنَ اَبُوْعَبْدِاللهِ مُحَمَّدِ بْنِ اِسْمَاعِيْلَ بْنِ اِبْرَاهِيْمَ بْنِ الْمُغِيْرَةِ بْنِ بَرْدِزْبَہُ الْبُخَارِیِّ وَاَبُوْ الْحُسَيْنِ مُسْلِمُ بْنُ الْحَجَّاجِ بْنِ مُسْلِمِ الْقُشَیْریُّ النَّيْسَابُوْرِیُّ فِیْ صَحِيْحَيْهِمَا اللَّذَيْنِ هُمَا اَصَحُّ الْكُتُبِ الْمُصَنَّفَةِ)", "urdu": "امیر المؤمنین حضرت سیِّدُنا ابوحفص عُمَر بن خَطّاب رضی الله عنہ بیان کرتے ہیں کہ میں نے رسولُ الله صلّی اللّٰہ علیہ واٰلہٖ وسلّم کو ارشاد فرماتے سنا: ”بےشک اعمال کا دارومدار نیتوں پر ہے اور ہر شخص کے لئے وہی ہے جس کی اس نے نیت کی پس جس کی ہجرت الله پاک اور اس کے رسول صلّی الله علیہ واٰلہٖ وسلّم کی طرف ہو تو اس کی ہجرت الله ورسول ہی کی طرف ہے اور جس کی ہجرت دنیا حاصل کرنےیا کسی عورت سے نکاح کرنے کے لئے ہو تو اس کی ہجرت اسی طرف ہے جس کی طرف اس نے ہجرت کی۔“(بخاری، كتاب الايمان، باب ما جاء ان الاعمال بالنیة والحسبة...الخ، ۱/ ۳۴، حدیث:۵۴۔ مسلم، کتاب الامارة، باب انما الاعمال بالنيات، ص۸۱۳، حدیث:۴۹۲۷، ’’ینکحھا‘‘ بدلہ ’’یتزوجھا‘‘)", "roman": "Ameer-ul-Momineen Hazrat Sayyiduna Abu Hafs Umar bin Khattab RadiyAllahu Anhu bayan karte hain ke main ne Rasoolullah Sallallahu Alaihi Wasallam ko irshad farmate suna: \"Beshak aamaal ka daromadar niyyaton par hai aur har Shakhs ke liye wahi hai jis ki us ne niyyat ki, pas jis ki hijrat Allah Paak aur us ke Rasool Sallallahu Alaihi Wasallam ki taraf ho to us ki hijrat Allah wa Rasool hi ki taraf hai aur jis ki hijrat dunya hasil karne ya kisi Aurat se Nikah karne ke liye ho to us ki hijrat usi taraf hai jis ki taraf us ne hijrat ki.\" (Bukhari, Kitaab-ul-Iman, Baab Ma Jaa Annal A'maala Bin-Niyyati Wal-Hisbah... ilkh, 1/34, Hadees: 54. Muslim, Kitaab-ul-Imarah, Baab Innama al-A'maalu bin-Niyyaat, p. 813, Hadees: 4927, \"Yankihuha\" badle \"Yatazawwajuha\")", "explanation": "¥مذکورہ حدیث شریف کی اہمیت وفضیلت:\n حضرت سیِّدُنا امام اعظم ابوحنیفہ رحمۃُ اللّٰہ علیہ نے اپنے صاحبزادے حضرت حماد رحمۃُ اللّٰہ علیہ کو 20 باتوں کی نصیحت فرمائی، انیسویں یہ تھی کہ میں نے پانچ لاکھ حدیثوں میں سے پانچ حدیثیں منتخب کی ہیں ان پر اعتماد کرنا مذکورہ حدیث پاک بھی ان پانچ میں سے ایک ہے۔ (ماخوذ از بشیر القاری، ص 65)\n حضرت سیِّدُنا امام محمد بن ادریس شافعی رحمۃُ اللّٰہ علیہ فرماتے ہیں: یہ حدیث پاک فقہ کے ستر ابواب کو شامل ہے۔\n(شرح مسلم للنووی، کتاب الامارة، باب قولہ صلی اللّٰہ علیہ وسلم: انما الاعمال بالنیة، ۱۳/ ۵۳)\n مُحَدِّثِیْنِ کرام رحمۃُ اللّٰہ علیہم کتاب کی ابتدا عموماً اس حدیث پاک سے کرتے ہیں اس سے ان کی مراد اخلاص اور اللّٰہ پاک کی رضا ہے۔ (فیوض الباری شرح صحیح البخاری، تحت الحدیث:1، 1/78،ملخصاً)\n حضرت سیِّدُنا حافظ اِبْنِ مہدی رحمۃُ اللّٰہ علیہ فرماتے ہیں کہ کتاب لکھنے والے کو چاہئے کہ اپنی کتاب کی ابتدا اس حدیث پاک سے کرے۔(فیوض الباری شرح صحیح البخاری، تحت الحدیث:1، 1/78، مفہوماً)\nحدیث شریف میں ارشاد ہوا: (بےشک اعمال کا دارومدار نیتوں پر ہے)\n¥نیت کی تعریف:\n نِیَّت دل کے پختہ اِرادے کوکہتے ہیں خواہ وہ کسی چیزکاہواورشریعت میں عبادت کے ارادے کونِیَّت کہا جاتا ہے۔\n(ماخوذ از نزہۃ القاری شرح صحیح بخاری، تحت الحدیث:1، 1/224)\n علامہ بدرُالدین محمود بن احمد عینی رحمۃُ اللّٰہ علیہ فرماتے ہیں کہ مذکورہ حدیث شریف میں نیت کا بیان ہے اور منقول ہے کہ نیت تہائی اسلام ہے کیونکہ احکام کی بجاآوری تین طرح سے ہوتی ہے: قول سے، فعل سے اور نیت سے تو یوں نیت ایک تہائی اسلام ہے۔(عمدة القاری ،کتاب بدءالوحی ،باب کیف کان بدءالوحی ،۱/۴۹ ،تحت الحدیث:۱)\n نیز نیت کبھی خود مستقل عبادت ہوتی ہے جبکہ دوسرے اعمال اس کے محتاج، ایک حدیث شریف میں ہے کہ ’’مومن کی نیت اس کے عمل سے بہتر ہے۔‘‘ (معجم کبیر، ۶/ ۱۸۵، حدیث:۵۹۴۲)\n¥عزم، قصد اور نیت میں فرق:\n اہْلِ تحقیق نے نیت اور عزم میں فرق کیا ہے، وہ کہتے ہیں کہ عزم وہ ارادہ ہے جو کام سے پہلے کیا جائے اور قصد وہ ارادہ ہے جو کام کے وقت اور اس کے ساتھ پایا جائے جبکہ نیت وہ ارادہ ہے جو عمل کے ساتھ ملا ہوا ہو اور یہ بھی معلوم ہو کہ یہ کام کس لئے کیا جا رہا ہے،مثلاً: حج کا ارادہ کیا تو سفر شروع کرنے تک عزم، سفر شروع ہونے کے بعد قصد اور اگر اس میں یہ بھی پیش نظر ہو کہ یہ حج کا سفر ہے تو یہ نیت ہے۔(ماخوذ از نزہۃ القاری شرح صحیح بخاری، تحت الحدیث:1، 1/224)\n¥عمل کی مقبولیت کا معیار:\n اعمال عمل کی جمع ہے اور عمل کی مقبولیت کے لئے چند چیزیں ضروری ہیں۔ چنانچہ اللّٰہ پاک قرآنِ مجید میں ارشاد فرماتا ہے:\nوَ مَنْ اَرَادَ الْاٰخِرَةَ وَ سَعٰى لَهَا سَعْیَهَا وَ هُوَ مُؤْمِنٌ فَاُولٰٓىٕكَ كَانَ سَعْیُهُمْ مَّشْكُوْرًا(19)\n(پ ۱۵، بنی اسرائیل:۱۹) \nترجمہ کنزالایمان: اور جو آخرت چاہے اور اس کی سی کوشش کرے اور ہو ایمان والا تو انھیں کی کوشش ٹھکانے لگی۔\n صدر الافاضل سیِّد محمد نعیم الدین مراد آبادی رحمۃُ اللّٰہ علیہ اس آیت مبارکہ کے تحت فرماتے ہیں: اس آیت سے معلوم ہوا کہ عمل کی مقبولیت کے لئے تین چیزیں درکار ہیں: ایک تو‏طالب آخرت ہونا یعنی نیت نیک ، دوسرے سعی یعنی عمل کو باہتمام اس کے حقوق کے ساتھ ادا کرنا،‏تیسری ایمان جو سب سے زیادہ ضروری ہے۔\n(خزائن العرفان،پ15، بنی اسرائیل، تحت الآیۃ: 19(\n¥نیت کے متفرق احکام:\n عبادت کی دو قسمیں ہیں: (1)…عبادت مقصودہ اور (2)… غیر مقصودہ۔\n عبادت مقصودہ کی تعریف: وہ عبادت جو خود بالذات مقصود ہوں کسی دوسری عبادت کے لئے وسیلہ نہ ہوں۔ (بہارشریعت، حصہ5، 1/ 1015 ) ان میں نیت ہونا ضروری ہے کہ بغیر نیت کے وہ عبادت ہی پائی جائے گی جیسا کہ نماز کہ اگر کوئی شخص نماز جیسے افعال کرے مگر مطلق نماز کی نیت نہ ہو تو اسے نماز ہی نہ کہا جائے گا۔ ’’پھر فرض نماز میں فرض کی نیت بھی ضروری ہے۔ مثلاً دل میں یہ نیت ہو کہ آج کی ظہر کی فرض نماز پڑھتا ہوں۔اَصَح (یعنی زیادہ درست) یہ ہے کہ نفل، سنت اور تراویح میں مطلق نماز کی نیت کافی ہے مگر احتیاط یہ ہے کہ تراویح میں تراویح یا سنت وقت کی نیت کرے اور باقی سنتوں میں سنت سرکار صلّی اللّٰہ علیہ واٰلہٖ وسلّم کی متابعت (یعنی پیروی) کی نیت کرے، اس لئے کہ بعض مشایخ رحمۃُ اللّٰہ علیہم اِن میں مطلق نماز کی نیت کو ناکافی قرار دیتے ہیں۔‘‘(نماز کے احکام، ص199)\n عبادتِ غیرمقصودہ کی تعریف: وہ عبادات جوخودبالذات مقصودنہ ہوں بلکہ کسی دوسری عبادت کے لئے وسیلہ ہوں۔ ان میں نیت کرنا ضروری نہیں کہ بغیر نیت کے بھی وہ عبادت پائی جائے گی البتہ اس کا ثواب نہیں ملے گا۔ مثلاً وضو کہ اس میں نیت کرنا سنت ہے، اگر کوئی شخص بغیر نیت کے اعضائے وضو کو دھولے یا دھل گئے تو اس کا وضو تو ہو جائے گا لیکن نیت نہ ہونے کی وجہ سے اسے ثواب نہیں ملے گا۔ (ماخوذ از بہارشریعت، حصہ2، 1/ 292)\n یاد رہے مباح یعنی وہ کام جس کا کرنا نہ کرنا برابر ہو کہ کرنے سے نہ ثواب اور نہ کرنے سے گناہ نہ ہو اگر اچھی نیت سے کیا جائے تو مستحب ہو جاتا ہے۔ جیسےکھانا پینا، سونا،مال ودولت جمع کرنا، تحفہ دینا،عمدہ یا زائد لباس پہننا وغیرہ۔ چنانچہ سیِّدی اعلیٰ حضرت امامِ اہلسنّت، مولانا شاہ امام احمد رضاخان رحمۃُ اللّٰہ علیہ فرماتے ہیں: ’’ہرمباح نیت حسن (یعنی اچھی نیّت) سے مستحب ہو جاتاہے۔‘‘ ( فتاویٰ رضویہ، 8/ 452)\n فقہائے کرام رحمۃُ اللّٰہ علیہم فرماتے ہیں: ’’مباحات(یعنی ایسے جائز کام جن پر نہ ثوا ب ہو نہ گناہ ان) کاحکم الگ الگ نیتوں کے اِعتبار سے مختلف ہوجاتاہے،اس لئے جب مباح سے عبادات پر قوت حاصل کرنا یاعبادات تک پہنچنا مقصود ہو تو یہ مُباحات یعنی جائز چیزیں بھی عبادات ہوں گی۔ مثلاً کھانا پینا،سونا،حُصولِ مال (وغیرہ)۔‘‘ ( فتاویٰ رضویہ، 7/ 189، ملخصاً)\n لہٰذا مناسب یہی ہے کہ بندہ ہرچیز میں کچھ نہ کچھ اچھی نیت کرے حتّٰی کہ کھانے، پینے، پہننے، سونے اور‏نکاح وغیرہ میں بھی کیوں کہ ان تما م کا تعلق ان اعمال سے ہے جن کے بارے میں بروزِ‏قیامت پوچھا جائے گا۔اگر نیت رِضائے الٰہی کی ہوئی تو میزان عمل میں یہ اعمال وزنی ہوں گے۔)قوت القلوب،الفصل الثامن فی الاخلاص…الخ، ۲/ ۲۶۷، ملخصًا)\nحدیث پاک میں ارشاد ہوا: (ہر شخص کے لئے وہی ہے جس کی اس نے نیت کی)\n¥مذکورہ حدیث پاک کا شانِ وُرُوْد: \n حضرت سیِّدُنا عبداللّٰہ بن مسعود رضی اللّٰہ عنہ فرماتے ہیں کہ ایک شخص تھا جس نے اُمِّ قیس نامی ایک عورت کو نکاح کا پیغام دیا، اُمِّ قیس نے کہا: جب تک تو مکہ سے مدینہ کی طرف ہجرت نہ کرے میں تجھ سے نکاح نہیں کروں گی۔ چنانچہ اس نے ہجرت کی اور اس سے نکاح کیا، اسی لئے ہم اسے مہاجر اُمِّ قیس(یعنی اُمِّ قیس سے نکاح کی نیت سے ہجرت کرنے والا) کہا کرتے تھے۔ (طبرانی)اس پر حضور نبی کریم صلّی اللّٰہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بےشک اعمال کا دارومدار نیتوں پر ہے اور ہر شخص کے لئے وہی ہے جس کی اس نے نیت کی(آخر تک پوری حدیث شریف) ۔‘‘(فیوض الباری شرح بخاری، 1/80،تحت الحدیث: 1)\nحدیث پاک میں ارشاد ہوا: ( جس کی ہجرت اللّٰہ پاک اور اس کے رسول صلّی اللّٰہ علیہ واٰلہٖ وسلّم کی طرف ہو تو اس کی ہجرت اللّٰہ ورسول ہی کی طرف ہے ۔۔۔ الخ )\n¥ہجرت کی تعریف، اقسام اور حکم:\n ہجرت کا لغوی معنیٰ: چھوڑنا ہے اور شرعی معنیٰ ہے: دین بچانے کے لئے ایک جگہ سے دوسری جگہ منتقل ہونا۔ (نزہۃ القاری، 1/ 229)ہجرت کی اقسام: ہجرت کی دو قسمیں ہیں: (1)… ظاہری (2)…باطنی۔ظاہری ہجرت یہ ہے کہ بندہ اپنے ایمان کو بچانے کے لئے فتنے کی جگہ سے کسی دوسری محفوظ جگہ چلا جائے اور باطنی ہجرت یہ ہے کہ بندہ ہر اس برائی کو چھوڑ دے جس کی طرف شیطان یا نفس اَمارہ بلائے۔(فتح الباری، کتاب الایمان، باب المسلم من سلم المسلمون… الخ، ۲/ ۵۲، حدیث:۱۰) ہجرت کا حکم:ابتدائے اسلام میں ہجرت فرض تھی پھرجب مکہ فتح ہوا تو اس کی فرضیت منسوخ ہوگئی جن احادیث میں ہجرت منقطع (ختم)ہونے کا ذکر ہے ان سے فرض ہجرت کا منقطع ہونا مراد ہے اور جن میں ہجرت جاری رہنے کا ذکر ہے اس سے مراد مستحب ہجرت ہے۔ (عمدةالقاری، کتاب بدء الوحی، باب کیف کان بدء الوحی الی رسول اللّٰہ، ۱/ ۵۹، حدیث:۱)\n¥عہد رسالت کی ہجرتیں:\n حضور نبی اکرم صلّی اللّٰہ علیہ واٰلہٖ وسلّم کی ظاہری حیات میں چار طرح کی ہجرتیں ہوئی ہیں: (1)…حبشہ کی طرف ہجرت اولیٰ ، (2)…حبشہ کی طرف ہجرت ثانیہ، (3)…فتح مکہ سے پہلے مدینہ منورہ کی طرف ہجرت اور (4)…قبائل عرب کی مدینہ منورہ کی طرف ہجرت۔ (نزہۃ القاری شرح صحیح بخاری، 1/ 229)\nحضور نبی پاک صلّی اللّٰہ علیہ واٰلہٖ وسلّم کے حکم سے مسلمانوں نے دو مرتبہ حبشہ کی طرف ہجرت فرمائی پہلی بار 11 مرد اور چار عورتیں اور دوسری بار میں 83 مرد اور 18 عورتیں شریک ہوئیں۔ (المواھب اللدنیة، المقصدالاول، ھجرتہ، ۱/ ۱۲۵۔ ۱۳۲ ملتقطًا) جب مدینہ منورہ کے قبائل بنو خزرج اور بنو اوس کے چند افراد ایمان لائے اور انہوں نے حضور نبی اکرم صلّی اللّٰہ علیہ واٰلہٖ وسلّم کو آنے کی دعوت دی تو آپ صلّی اللّٰہ علیہ واٰلہٖ وسلّم نے صحابَۂ کرام علیہمُ الرّضوان کو عام اجازت دی کہ وہ ہجرت کر کے مدینہ منورہ چلے جائیں۔(سیرةابن ھشام، ص ۱۸۶، ملخصًا) \n¥مکہ مکرمہ سے ملک شام کی طرف ہجرت:\n قربِ قیامت میں فتنوں کے ظہور سے قبل ایک ہجرت مکہ مکرمہ سے ملک شام کی جانب ہوگی جس کا اجمالی واقعہ کچھ یوں ہے: قیامت قائم ہونے سے قبل جب دنیا میں سب جگہ کفر کا تسلط ہوگا اس وقت تمام ابدال بلکہ تمام اولیا سب جگہ سے سمٹ کر حرمین شریفین کو ہجرت کر جائیں گے (کیونکہ) صرف وہیں اسلام ہوگا اور ساری زمین کفرِستان ہوجائے گی۔ رمضان المبارک کا مہینہ ہوگا ابدال طواف کعبہ میں مصروف ہوں گے اور حضرت امام مہدی( رحمۃُ اللّٰہ علیہ ) بھی وہاں ہوں گے اولیا انہیں پہچانیں گے ان سے بیعت کی درخواست کریں گے وہ انکار کریں گے، دفعۃً (اچانک) غیب سے ایک آواز آئے گی ’’ ھٰذَاخَلِیْفَۃُ اللّٰہ الْمَہْدِیْ فَاسْمَعُوْالَہٗ وَاَطِیْعُوْہُ ترجمہ: یہ اللّٰہ پاک کا خلیفہ مہدی ہے، اس کی بات سنو اور اس کا حکم مانو۔‘‘ چنانچہ تمام لوگ ان کے دستِ (ہاتھ)مبارک پر بیعت کریں گے، وہاں سے سب کو اپنے ہمراہ لے کر ملک ’’شام‘‘ کو تشریف لے جائیں گے۔ (بہار شریعت، حصہ1، 1/ 124، ملخصاً)\n¥ہجرت کب واجب ہے؟\n جو شخص کسی شہر میں اپنے دین پر قائم نہ رہ سکتا ہو اور یہ جانے کہ دوسری جگہ جانے سے اپنے فرائض دینی ادا کرسکے گا اس پر ہجرت واجب ہوجاتی ہے ، مروی ہے: ’’جو شخص اپنے دین کی حفاظت کے لئے ایک جگہ سے دوسری جگہ منتقل ہوا اگرچہ ایک بالشت ہی کیوں نہ ہو اس کے لئے جنت واجب ہو جاتی ہے اور اسے حضرت ابراہیم علیہِ السّلام اور محمد مصطفٰے صلّی اللّٰہ علیہ واٰلہٖ وسلّم کا ساتھ نصیب ہوگا۔‘‘ (تفسیر سمرقندی، العنکبوت، تحت الآیة:۵۶، ۲/ ۵۴۲)\n¥دار الاسلام سے ہجرت عامہ اور ہجرت خاصہ کا حکم:\n سیِّدِی اعلیٰ حضرت امام اہل سنت مولانا شاہ امام احمد رضا خان رحمۃُ اللّٰہ علیہ نے ہجرت کی اقسام بیان فرمائی ہیں ان میں سے ایک قسم کہ دارُالاسلام سے ہجرت ہو، اس کی تفصیل بیان کرتے ہوئے فرماتے ہیں:رہا دارُالاسلام،اس سے ہجرتِ عامہ حرام ہے کہ اس میں مساجد کی ویرانی وبے حرمتی، قبورِ مسلمین (مسلمانوں کی قبروں)کی بربادی، عورتوں بچوں اور ضعیفوں (کمزوروں) کی تباہی ہوگی اور ہجرتِ خاصہ میں تین صورتیں ہیں:\n (1)…اگر کوئی شخص کسی خاص وجہ سے کسی خاص مقام میں اپنے دینی فرائض بجانہ لاسکے اور دوسری جگہ انہیں بجا لانا ممکن ہوتو اگر یہ خاص اسی مکان میں ہے تو اس پر فرض ہے کہ یہ مکان چھوڑ کر دوسرے مکان میں چلاجائے اور اگر اس محلہ میں معذور ہوتو دوسرے محلہ میں چلا جائے اور اس شہر میں مجبور ہوتو دوسرے شہر میں چلا جائے۔ \n(2)…یہاں اپنے مذہبی فرائض بجالانے سے عاجز نہیں اور اس کے ضعیف ماں یا باپ یا بیوی یا بچے جن کا نفقہ اس پر فرض ہے وہ نہ جاسکیں گے یا نہ جائیں گے اور اس کے چلے جانے سے وہ بے وسیلہ رہ جائیں گے تو اس کو دارُالاسلام سے ہجرت کرنا حرام ہے،(کہ)حدیث میں ہے:’’کسی آدمی کے گنہگار ہونے کے لئے اتنا کافی ہے کہ وہ اسے ضائع کردے جس کا نفقہ اس کے ذمے تھا۔‘‘یا وہ عالِم جس سے بڑھ کر اس شہر میں عالِم نہ ہو اسے بھی وہاں سے ہجرت کرنا حرام ہے۔\n(3)…نہ فرائض سے عاجز ہے نہ اس کی یہاں حاجت ہے، اسے اختیار ہے کہ یہاں رہے یا چلا جائے ، جو اس کی مصلحت سے ہو وہ کر سکتا ہے ، یہ تفصیل دارُالاسلام میں ہے۔(فتاوی رضویہ، 14/ 131 تا 132، ملخصاً)\n¥افضل ہجرت:\nحضرت سیِّدَتُنا اُمِّ انس رضی اللّٰہ عنہا نے بارگاہِ رسالت میں عرض کی: یارسولَ اللّٰہ صلّی اللّٰہ علیہ واٰلہٖ وسلّم ! مجھے کچھ وصیت فرمائیے۔ تو آپ نے ارشاد فرمایا: ’’گناہوں سے ہجرت کرلو (یعنی انہیں چھوڑ دو) کہ یہ سب سے افضل ہجرت ہے۔‘‘\n(معجم کبیر، ۲۵/ ۱۲۹،حدیث:۳۱۳)\n¥حقیقی مہاجر کون؟\nہجرت کی کئی اقسام ہیں لیکن حدیث پاک میں حقیقی مہاجر (ہجرت کرنے والا) اسے کہا گیا ہے جو گناہوں کو چھوڑ دے۔ چنانچہ حضرت سیِّدُنا عبداللّٰہ بن عَمْرو بن عاص رضی اللّٰہ عنہما سے مروی ہے کہ اللّٰہ پاک کے آخری نبی صلّی اللّٰہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اَلْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُوْنَ مِنْ لِسَانِہٖ وَیَدِہٖ وَالْمُہَاجِرُ مَنْ ہَجَرَ مَانَہَی اللّٰہ عَنْہُ یعنی مسلمان وہ ہے جس کی زبان اور ہاتھ سے دوسرے مسلمان محفوظ رہیں اور مہاجر (ہجرت کرنے والا)وہ ہے جو ان چیزوں کو چھوڑ دے جن سے اللّٰہ پاک نے منع فرمایا۔‘‘ (بخاری ، کتاب الایمان، باب المسلم من سلم المسلمون من لسانہ ویدہ ، ۱ / ۱۵ ، حدیث : ۱۰)\n¥دعا:\nاللّٰہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللّٰہ علیہ واٰلہٖ وسلّم"}, {"id": 6867, "bookId": 13, "volNo": "1", "hadithNo": 2, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "حدیث جبریل", "arabic": "عَنْ عُمَرَ رَضيَ اللهُ عَنْهُ اَيْضًا قَالَ: بَيْنَمَا نَحْنُ عِنْدَ رَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ اِذْ طَلَعَ عَلَيْنَا رَجُلٌ شَدِيْدُ بَيَاضِ الثِّيَابِ شَدِيْدُ سَوَادِ الشَّعْرِ لَا يُرٰى عَلَيْهِ اَثَرُ السَّفَرِ وَلَا يَعْرِفُهٗ مِنَّا اَحَدٌ حَتّٰى جَلَسَ اِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاَسْنَدَ رُكْبَتَـيْهِ اِلٰى رُكْبَتَـيْهِ وَوَضَعَ كَفَّيْهِ عَلٰى فَخِذَيْهِ وَقَالَ: يَا مُحَمَّدُ اَخْبِرْنِيْ عَنِ الْاِسْلَامِ. فَقَالَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ :’’اَلْاِسْلَامُ اَنْ تَشْهَدَ اَنْ لَّااِلٰهَ اِلَّا اللهُ وَاَنَّ مُحَمَّدًا رَّسُوْلُ اللهِ وَتُقِيْمَ الصَّلَاةَ وَتُؤْتِيَ الزَّكٰوةَ، وَتَصُوْمَ رَمَضَانَ، وَتَحُجَّ الْبَـيْتَ اِنِ اسْتَطَعْتَ اِلَيْهِ سَبِيْلًا. ‘‘ قَالَ: صَدَقْتَ. فَعَجِبْنَا لَهٗ يَسْاَلُهٗ وَيُصَدِّقُهٗ. قَالَ: فَاَخْبِرْنِيْ عَنِ الْاِيْمَانِ. قَالَ: ’’اَنْ تُؤْمِنَ بِاللهِ وَمَلَآئِكَتِهٖ وَكُتُبِهٖ وَرُسُلِهٖ وَالْيَوْمِ الْاٰخِرِ وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهٖ وَشَرِّهٖ.‘‘ قَالَ: صَدَقْتَ. قَالَ: فَاَخْبِرْنِيْ عَنِ الْاِحْسَانِ. قَالَ: ’’اَنْ تَعْبُدَ اللهَ كَاَنَّكَ تَرَاهُ فَاِنْ لَّمْ تَكُنْ تَرَاهُ فَاِنَّهٗ يَرَاكَ. ‘‘ قَالَ: فَاَخْبِرْنِيْ عَنِ السَّاعَةِ. قَالَ: ’’مَا الْمَسْئُوْلُ عَنْهَا بِاَعْلَمَ مِنَ السَّائِلِ. ‘‘ قَالَ: فَاَخْبِرْنِيْ عَنْ اَمَارَاتِهَا. قَالَ: ’’اَنْ تَلِدَ الْاَمَةُ رَبَّتَهَا وَاَنْ تَـرَى الْحُفَاةَ الْعُرَاةَ الْعَالَةَ رِعَاءَ الشَّاءِ يَتَطَاوَلُوْنَ فِي الْبُنْيَانِ. ‘‘ ثُمَّ انْـطَلَقَ فَلَبِثْتُ مَلِيًّا ثُمَّ قَالَ: ’’يَا عُمَرُ! اَتَدْرِيْ مَنِ السَّائِلُ؟‘‘ قُلْتُ: اَللهُ وَرَسُوْلُهٗ اَعْلَمُ. قَالَ: ’’فَاِنَّهٗ جِبْرِيْلُ اَتَاكُمْ يُعَلِّمُكُمْ دِيْنَكُمْ.‘‘ (رَوَاهُ مُسْلِم)", "urdu": "حضرت سیِّدُنا عُمَر بن خطاب رضی الله عنہ سے ہی روایت ہے، آپ فرماتے ہیں: ایک دن ہم بارگاہِ رسالت میں حاضر تھے کہ اچانک نہایت سفید لباس اور انتہائی سیاہ بالوں والا ایک شخص حاضر خدمت ہوا، اس پر نہ تو سفر کے آثار دکھائی دے رہے تھے اور نہ ہی ہم میں سے کوئی اسے پہنچانتا تھا۔ وہ حضور نبی کریم صلّی الله علیہ واٰلہٖ وسلّم کے اتنا قریب ہو کر بیٹھ گیا کہ اس نے اپنے گھٹنے آپ کے مبارک گھٹنوں سے ملا دئیے اور اپنے ہاتھ زانوں پر رکھ کر عرض کی: یا رسولَ الله صلّی اللہ علیہ واٰلہٖ وسلّم ! مجھے اسلام کے بارے میں بتائیے؟ تو حضور نبی کریم صلّی الله علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اِسلام یہ ہے کہ تم اس بات کی گواہی دو الله پاک کے سوا کوئی عبادت کے لائق نہیں اور محمد صلّی الله علیہ واٰلہٖ وسلّم الله پاک کے رسول ہیں اور نماز قائم کرو، زکوٰۃ دو، رمضان کے روزے رکھو اور استطاعت ہو تو بیْتُ الله کا حج کرو۔‘‘ اس نے کہا: آپ نے سچ فرمایا۔ ہمیں تعجب ہوا کہ سوال بھی کر رہا ہے اور تصدیق بھی ۔ پھر عرض کی: مجھے ایمان کے بارے میں بتائیے؟ ارشاد فرمایا: ’’ایمان یہ ہے کہ تم الله پاک، اس کے فرشتوں، اس کی کتابوں ،اس کے رسولوں، آخرت اور اچھی وبُری تقدیر پر ایمان لاؤ۔‘‘ اس نے کہا: آپ نے سچ فرمایا۔ پھر عرض کی:مجھے احسان کے بارے میں بتائیے؟ آپ نے ارشاد فرمایا: ’’تم الله پاک کی عبادت اس طرح کرو گویا اسے دیکھ رہے ہو اگر تم اسے نہیں دیکھ سکتے تو بےشک وہ تو تمہیں دیکھ ہی رہا ہے ۔‘‘ پھر اس نے عرض کی: مجھے قیامت کے بارے میں بتائیے؟ ارشاد فرمایا: ’’جس سے قیا مت کے بارے میں پوچھا گیا ہے وہ پوچھنے والے سے زیادہ نہیں جانتا۔‘‘ عرض کی: پھر قیامت کی نشانیاں ہی بتا دیجئے۔ ارشاد فرمایا: ’’باندی (غلام عورت) اپنے مالک کو جنے گی اور تم دیکھو گے کہ ننگے پاؤں ،برہنہ جسم،مفلس، بکریاں چَرانے والے بلند و بالا عمارتوں کی تعمیرات میں ایک دوسرے پر فخر کریں گے ۔‘‘ (حضرت سیِّدُنا عمر فاروق اعظم رضی الله عنہ فرماتے ہیں:)پھر وہ شخص چلاگیا، میں کچھ دیر ٹھہرا رہا۔ پھر آپ صلّی الله علیہ واٰلہٖ وسلّم نے مجھ سے ارشاد فرمایا: ’’اے عمر! جانتے ہو وہ سائل کون تھا؟‘‘ میں نے عرض کی: الله پاک اور اس کے رسول صلّی الله علیہ واٰلہٖ وسلّم بہتر جانتے ہیں۔ ارشاد فرمایا: ’’وہ جبرائیل علیہ السَّلام تھے جو تمہیں تمہارا دین سکھانے آئے تھے۔‘‘ (مسلم، كتاب الايمان، باب بيان الايمان والاسلام والاحسان...الخ،ص۳۳، حدیث:۹۳)", "roman": "Hazrat Sayyiduna Umar bin Khattab RadiyAllahu Anhu se hi Riwayat hai, aap farmate hain: Ek din hum baargah-e-risalat mein haazir the ke achanak nihayat sufaid Libaas aur intehayi siyah Baalon wala ek Shakhs haazir-e-khidmat hua, us par na to safar ke aasaar dikhayi de rahe the aur na hi hum mein se koi use pehchanta tha. Woh Huzoor Nabi Kareem Sallallahu Alaihi Wasallam ke itna qareeb ho kar baith gaya ke us ne apne ghutne aap ke mubarak ghutnon se mila diye aur apne hath zaanon par rakh kar arz ki: Ya Rasoolullah Sallallahu Alaihi Wasallam! Mujhe Islam ke baare mein bataiye? To Huzoor Nabi Kareem Sallallahu Alaihi Wasallam ne irshad farmaya: \"Islam yeh hai ke tum is baat ki Gawahi do Allah Paak ke siwa koi ibadat ke laaiq nahi aur Muhammad Sallallahu Alaihi Wasallam Allah Paak ke Rasool hain aur Namaz qaim karo, Zakat do, Ramzan ke roze rakho aur istita'at ho to Baitullah ka Hajj karo.\" Us ne kaha: Aap ne sach farmaya. Humein ta'ajjub hua ke Sawaal bhi kar raha hai aur tasdeeq bhi. Phir arz ki: Mujhe Iman ke baare mein bataiye? Irshad farmaya: \"Iman yeh hai ke tum Allah Paak, us ke farishton, us ki kitabon, us ke rasoolon, aakhirat aur achhi wa buri taqdeer par iman lao.\" Us ne kaha: Aap ne sach farmaya. Phir arz ki: Mujhe Ihsan ke baare mein bataiye? Aap ne irshad farmaya: \"Tum Allah Paak ki ibadat is tarah karo goya use dekh rahe ho, agar tum use nahi dekh sakte to beshak woh to tumhein dekh hi raha hai.\" Phir us ne arz ki: Mujhe Qayamat ke baare mein bataiye? Irshad farmaya: \"Jis se Qayamat ke baare mein poocha gaya hai woh poochne wale se zyada nahi jaanta.\" Arz ki: Phir Qayamat ki nishaniyan hi bata dijiye. Irshad farmaya: \"Baandi (ghulam Aurat) apne maalik ko janegi aur tum dekhoge ke nange paaon, barhana jism, muflis, bakriyan charane wale buland-o-baala imaraton ki ta'meerat mein ek doosre par fakhr karenge.\" (Hazrat Sayyiduna Umar Farooq-e-Azam RadiyAllahu Anhu farmate hain:) Phir woh Shakhs chala gaya, main kuch der thehra raha. Phir aap Sallallahu Alaihi Wasallam ne mujh se irshad farmaya: \"Ae Umar! Jaante ho woh saail kaun tha?\" Main ne arz ki: Allah Paak aur us ke Rasool Sallallahu Alaihi Wasallam behtar jaante hain. Irshad farmaya: \"Woh Jibraeel Alayhis Salam the jo tumhein tumhara deen sikhaane aaye the.\" (Muslim, Kitaab-ul-Iman, Baab Bayan-il-Iman wal-Islam wal-Ihsan... ilkh, p. 33, Hadees: 93)", "explanation": "¥مذکورہ حدیث شریف کی اہمیت وفضیلت:\n خیال رہے رسولُ الله صلّی الله علیہ واٰلہٖ وسلّم سے نسبت کی وجہ سے ہر حدیث قابل احترام اور ذیشان ہے لیکن بعض احادیث کا مقام اور مرتبہ ہی الگ ہوتا ہے جیسے مذکورہ حدیث پاک۔ اس کی اہمیت، فضیلت اور شان کا اندازہ اس بات سے لگایا جاسکتا ہے کہ کئی جلیل القدر محدثین جیسے حضرت سیِّدُنا امام بخاری، حضرت سیِّدُنا امام مسلم، حضرت سیِّدُنا امام نسائی، حضرت سیِّدُنا امام ابن ماجہ، حضرت سیِّدُنا امام ابوداؤد، حضرت سیِّدُنا امام ترمذی، حضرت سیِّدُنا امام احمد بن حنبل اور حضرت سیِّدُنا امام بغوی رحمۃُ الله علیہم نے متعدد سندوں اور مختلف لفظوں کے ساتھ اسے نقل فرمایا ہے۔(منتخب حدیثیں، ص57، ملخصاً)\n حضرت سیِّدُنا علامہ قاضی عیاض مالکی رحمۃُ الله علیہ فرماتے ہیں: ’’یہ حدیث پاک تمام وظائف اور ظاہری وباطنی عبادتوں کی جامع ہے۔‘‘ (فیوض الباری،پارہ اوّل،کتاب الایمان، باب سؤال جبریل النبی…الخ،۱/ ۲۵۸، ملخصًا)\n حضرت سیِّدُنا شیخ عبد الحق محدث دہلوی رحمۃُ الله علیہ فرماتے ہیں: اس حدیث شریف کو علما محدثین ’’حدیْثِ جبریل‘‘ یا ’’حدیْثِ اُمُّ الاحادیث‘‘ یا ’’اُمُّ الجوامع‘‘ کہتے ہیں۔’’حدیث جبریل‘‘ اس لئے کہ حضرت سیِّدُنا جبریل علیہِ السّلام نے ایک آدمی کی صورت میں آکر حضور نبی پاک صلّی الله علیہ واٰلہٖ وسلّم سے سوال جواب کیا اور ’’اُمُّ الاحادیث یا اُمُّ الجوامع‘‘ کی وجہ یہ ہے کہ ’’اُم‘‘ اصل اور جڑ کو کہتے ہیں جس طرح سورۂ فاتحہ کہ وہ اجمالی طور پر تمام قرآنی مضامین کی جامع اور جڑ ہےاس لئے اسے ’’اُمُّ القرآن‘‘ کہا گیا اسی طرح یہ حدیث شریف چونکہ تمام احادیث نبویہ کے مضامین کو اجمالی طور پر اپنے دامن میں لئے ہوئے ہے اس لئے یہ ’’اُمّ الاحادیث یا اُمُّ الجوامع‘‘ کہلاتی ہے۔ (اشعة اللمعات، کتاب الایمان، الفصل الاول، ۱/ ۴۱، ملخصًا)\nحدیث شریف کے شروع میں ہے: (نہایت سفید لباس اور انتہائی سیاہ بالوں والا ایک شخص حاضر خدمت ہوا اور دو زانوں بیٹھ کر کچھ سوالات کیے)\n¥بزرگوں کی بارگاہ کے آداب:\n مذکورہ حدیث پاک سے ہمیں یہ بھی سیکھنے کو ملتا ہے کہ جب بھی کسی دینی منصب پر فائز شخص جیسے عالِم دین، مفتی صاحب اور بزرگوں کی خدمت میں حاضر ہوں تو صاف ستھرے لباس اور اچھی حالت میں آئیں، نیز ادب وتعظیم کا دامن ہاتھ سے نہ چھوٹے ورنہ علم دین اور اس کی برکتوں سے محرومی رہے گی۔ کیونکہ ’’حصولِ علم دین کے بنیادی ارکان میں سے ایک اہم رکن استاد ہے، حصول علم میں جس طرح درس گاہ وکتاب کی اہمیت ہے اسی طرح استاد کا ادب واحترام مرکزی حیثیت کا حامل ہے۔استاد کی تعظیم شاگرد پر لازم ہے کہ یہ بھی علم ہی کی تعظیم ہے اور ادب کے بغیر علم تو شاید حاصل ہو جائے مگر فیضانِ علم سے یقیناً محرومی ہوتی ہے۔ طالب علم کو استاد کے ادب کے مختلف دینی ودنیوی فوائد حاصل ہوتے ہیں۔ چنانچہ\nحضرت سیِّدُنا امام برہان الدین زرنوجی رحمۃُ الله علیہ فرماتے ہیں: ایک طالِبِ علم اس وقت تک علم حاصل نہیں کرسکتا اور نہ ہی علم سے نفع اٹھاسکتا ہے جب تک کہ وہ علم ، اہْلِ علم اور اپنے استاد کی تعظیم و توقیر نہیں کرتا۔ (تعلیم المتعلم طریق التعلم، ص۸)\nحضرت سیِّدُنا امام فخر الدین ارسا بندی رحمۃُ الله علیہ مَرْو شہر میں رئیسُ الائمہ کے مقام پر فائز تھے اورسلطانِ وقت آپ کا بے حد ادب واحترام کیا کرتاتھا۔ آپ فرمایا کرتے تھے کہ مجھے یہ منصب اپنے استاد کی خدمت و ادب کرنے کی وجہ سے ملا ہے۔ (تعلیم المتعلم طریق التعلم، ص۸) نیز’’استاد کےادب سے علم کی راہیں آسان ہوجاتی ہیں۔‘‘( علم وعلماء کی اہمیت ، ص108)دیْنِ اسلام میں استاد کے ادب کو بہت اہمیت دی گئی ہے حتّٰی کہ استاد کو روحانی باپ کا درجہ دیا گیا ہے، لہٰذا طالبِ علم کو چاہئے کہ اسے اپنے حق میں حقیقی باپ سے بڑھ کر مخلص جانے۔تفسیرِ کبیر میں ہے:”استاد اپنے شاگرد کے حق میں ماں باپ سے بڑھ کر شفیق ہوتا ہے کیونکہ والدین اسے دنیا کی آگ اور مصائب سے بچاتے ہیں جبکہ استاد اسے نارِ دوزخ اور مصائبِ آخرت سے بچاتا ہے۔‘‘(تفسیرِ کبیر،پ۱،البقرة، تحت الآیة:۳۱، جزء:۲،۱/ ۴۰۱)\nحدیث شریف میں ہے: (حاضر ہونے والے شخص نے آپ صلّی الله علیہ واٰلہٖ وسلّم کو نام لے کر پکارا )\n¥بارگاہِ رسالت کے آداب:\n یاد رکھئے! حضور نبی پاک صلّی الله علیہ واٰلہٖ وسلّم کی بارگاہ کے آداب میں سے ہے کہ آپ کو نام لے کر (یعنی ’’یَا مُحَمَّد‘‘ کہہ کر)نہ پکارا جائے۔ چنانچہ فتاویٰ رضویہ، جلد 30، صفحہ156 تا 157 پر سیِّدِی اعلیٰ حضرت مولانا شاہ امام احمد رضا خان رحمۃُ اللہ علیہ کےنقل کردہ کلام کا خلاصہ ہے کہ اللہ پاک نے قرآنِ مجید میں ارشاد فرمایا:\nلَا تَجْعَلُوْا دُعَآءَ الرَّسُوْلِ بَیْنَكُمْ كَدُعَآءِ بَعْضِكُمْ بَعْضًاؕ-(پ ۱۸، النور:۶۳) \nترجمہ کنزالایمان: رسول کے پکارنے کو آپس میں ایسا نہ ٹھہرا لو جیسا تم میں ایک دوسرے کو پکارتا ہے۔\n کہ اے زید!اے عَمرو! بلکہ یوں عرض کرو: یَارَسُوْلَ الله، یَانَبِیَّ الله، یَاسَیِّدَ الْمُرْسَلِیْن، یَاخَاتَمَ النَّبِیِّیْن، یَاشَفِیْعَ الْمُذْنِبِیْن صَلَّی الله تَعَالٰی عَلَیْکَ وَسَلَّم وَعَلٰی اٰلِکَ اَجْمَعِیْن۔ \n حضرت سیِّدُنا ابن عباس رضی الله عنہما سے اس آیت کی تفسیر یوں مروی ہے کہ کَانُوْا یَقُوْلُوْنَ یَامُحَمَّدُ یَااَبَا الْقَاسِمِ فَنَہٰہُمُ الله عَنْ ذٰلِکَ اِعْظَامًا لِّنَبِیِّہٖ صَلَّی الله تَعَالٰی عَلَیْہِ وَسَلَّم فَقَالُوْا یَانَبِیَ الله، یَارَسُوْلَ الله یعنی پہلے حضور صلّی الله علیہ وسلّم کو یَامُحَمَّد! یَااَبَاالْقَاسِم! کہہ کر پکارتے تھے، الله پاک نے اپنے نبی کی تعظیم کی وجہ سے اس سے منع فرما دیا، جب سے صحابَۂ کرام علیہمُ الرّضوان ’’یَارَسُوْلَ الله ، یَانَبِیَّ الله‘‘ کہا کرتے۔(دلائل النبوة لابی نعیم، الجزء الاول، الفصل الاول فی ذکر ماانزل اللّٰہ ...الخ، ص۱۹، حدیث:۴)\n حضرت سیِّدُنا عکرمہ رحمۃُ الله علیہ سے مذکورہ آیت مبارکہ کی تفسیر یوں مروی ہے: ’’لَاتَقُوْلُوْا یَامُحَمَّدُ! وَلٰکِن قُوْلُوْا یَارَسُوْلَ الله، یَا نَبِیَّ الله! یعنی الله پاک ارشاد فرماتا ہے: یَامُحَمَّد! نہ کہو بلکہ یَارَسُوْلَ الله! یَانَبِیَّ الله! کہو۔(درمنثور، پ۱۸، النور، تحت الایة:۶۳، ۶/ ۲۳۱)\n لہٰذا علما واضح طور پر فرماتے ہیں: حضورِ اقدس کو نام لے کر پکارنا حرام ہے اور انصاف بھی یہ ہی ہے کہ جسے اس کا مالک ومولیٰ تبارک وتعالیٰ نام لے کر نہ پکارے غلام کی کیا مجال کہ راہِ ادب سے تجاوز کرے بلکہ امام زین الدین مراغی وغیرہ محققین نے فرمایا: اگر یہ لفظ کسی دعا میں وارد ہو جو خود حضور نبی کریم صلّی الله علیہ واٰلہٖ وسلّم نے تعلیم فرمائی جیسے یہ دعا: ’’یَا مُحَمَّدُ اِنِّیْ تَوَجَّھْتُ بِکَ اِلٰی رَبِّی ‘‘ (اے محمد!میں آپ کے تَوَسُّل (وسیلے)سے اپنے رب کی طرف متوجہ ہوا)۔ (ابن ماجة، کتاب اقامة الصلٰوة، باب ماجاء فی صلٰوة الحاجة، ۲/ ۱۵۶، حدیث:۱۳۸۵) تاہم اس کی جگہ ’’ یَارَسُوْلَ الله! یَانَبِیَّ الله! ‘‘ کہنا چاہئے، حالانکہ الفاظ دعا میں جہاں تک ممکن ہو تبدیلی نہیں کی جاتی۔ (فتاوی رضویہ، 30/ 157، ملخصاً)\n¥ایک سوال اور اس کاجواب:\n سوال: جب ’’یَامُحَمَّد‘‘ کہہ کر پکارنا ناجائز ہے تو پھر حضرت سیِّدُنا جبرائیل علیہِ السّلام نے رسولِ پاک صلّی اللہ علیہ وسلّم کو ’’یَامُحَمَّد‘‘ کہہ کر کیوں پکارا؟ جواب: حضرت سیِّدُنا ملا علی قاری فرماتے ہیں: ممکن ہے کہ یہ واقعہ اس آیَتِ مبارکہ کے نازل ہونے سے پہلے کا ہو اور اس وقت رسولِ کریم صلّی اللہ علیہ وسلّم کو ’’یَامُحَمَّد‘‘ کہہ کر پکارنا جائز تھا یا اس لئے کہ اس آیَتِ طیبہ میں انسانوں سے خطاب ہے اور فرشتے اس حکم سے خارج ہیں۔(مرقاة المفاتیح، کتاب الایمان، الفصل الاول، ۱/ ۱۱۱، تحت الحدیث:۲)\nحدیث شریف میں ہے: (آنے والے شخص نے اسلام اور ایمان کے بارے میں سوال کیا)\n¥اسلام اور ایمان کی وضاحت:\n ایمان کی تعریف:سچّے دل سے اُن تمام باتوں کی تصدیق کرنا جو ضروریاتِ دین سے ہیں اُسے ایمان کہتے ہیں ، یا یوں سمجھیں کہ جو کچھ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم اللہ پاک کی طرف سے لائے ہیں خواہ وہ حکم ہو یا خبر ان سب کو حق جاننا اور سچّے دل سے ماننا ایمان کہلاتا ہے۔ اسلام کی تعریف:اسلام کے لغوی معنیٰ اطاعت و فرمانبرداری کے ہیں اور شرعی معنیٰ میں اسلام اور ایمان ایک ہی ہیں ان میں کوئی فرق نہیں۔جو مومن ہے وہ مسلمان ہے اور جو مسلمان ہے وہ مومن ہے، البتہ صرف زبانی اقرار کرناکہ جس کے ساتھ قلبی تصدیق نہ ہو معتبر نہیں ، اس سے آدمی مومن نہیں ہوتا۔ \n(ہمارا اسلام، ایمان وکفر، حصہ4، ص174، 176، ملخصاً)\n جمہور اہْلِ سنت کا مذہب یہ ہے کہ ایمان اور اسلام ایک ہی شے ہیں کیونکہ اسلام کا معنیٰ خُضُوْع واِنقیاد ( یعنی سر تسلیم خم کرنا احکام کو قبول کرنا اور مان لینا) ہے اور یہ تصدیق ہی ہے اور ایمان کی تعریف تصدیق کے ساتھ کی جاتی ہے۔اس سے معلوم ہوا کہ اسلام اور ایمان ایک ہی ہیں اسی طرح شرعاً کسی شخص کو اس طرح کہنا جائز نہیں کہ وہ مسلمان ہے مومن نہیں یا مومن ہے مسلمان نہیں بلکہ جو مسلمان ہوگا وہ مومن بھی ہوگا اور جو مومن ہوگا وہ مسلمان بھی ہوگا۔ احادیث مبارکہ میں اسلام اور ایمان کے بارے میں جو علیحدہ علیحدہ بیان ہے اس سے یہ لازم نہیں آتا کہ یہ دونوں الگ ہیں۔ جہاں اسلام کا تذکرہ ہے وہاں اسلام کی علامات و ثمرات کا بیان ہے اور جہاں ایمان کا ذکر ہے وہاں اس کی علامات وثمرات کا بیان ہے(حقیقت میں دونوں ایک ہی ہیں)۔ (شرح عقائد النسفیة، ص۲۸۸ تا ۲۹۱، ملخصًا) \n¥اللہ ورسول پر ایمان: \n اللہ پر ایمان لانے کا یہ مطلب ہے کہ اللہ تعالیٰ کو موجود،واجِبُ الْوُجود(جس کا وجود ضروری ہو)، واحد حقیقی،وحدہٗ لاشریک لہٗ، خالِقِ کائنات مانتے ہوئے اس کی تمام صفات مثلًا حیات، علم،قدرت،اِرادہ،کلام،سمع،بصر،تکوین کوصدقِ دل سے مان کر اس پر یقین کامل رکھا جائے اور اس کو ہر عیب و نقص سے پاک مانتے ہوئے اس کو ہر صفت کمال کے ساتھ مانا جائے۔ (منتخب حدیثیں، ص63)نیز ’’اللہ پر ایمان یہ نہیں کہ لفظ ’’ اللہ ‘‘ مان لیا بلکہ ایمان تصدیق کانام ہے، جو اللہ عَزّوَجَلَّ کے ہر ہر کلام کی تصدیق قطعی سچے دل سے کرتاہو وہ اللہ عَزّوَجَلَّ پر ایمان رکھتاہے اور جو اس کے کسی کلام میں شبہ بھی لائے اسے ہرگز اللہ پر ایمان نہیں کہ اس کی سب باتوں کی تصدیق نہیں کرتا۔اصل یہ ہے کہ ایمان بِاللہ میں جملہ ضروریاتِ دین پر ایمان داخل ہے کہ ان میں سے کسی بات کی تکذیب رب کی تکذیب ہے اور رب کی تکذیب رب کے ساتھ کفرہے۔‘‘ (فتاوی رضویہ، 14/ 699تا 700 ملتقطًا)رسول پر ایمان: ’’حضورِ اقدس صلّی اللہ علیہ واٰلہٖ وسلّم کی نبوت و رسالت پر ایمان لانا اور جو کچھ آپ اللہ تعالیٰ کی طرف سے لائے ہیں، صدق دل سے اس کو سچا ماننا ہر ہر امتی پر فرض عین ہے اور ہر مومن کا اس پر ایمان ہے کہ بغیر رسول پر ایمان لائے ہوئے ہر گز ہرگز کوئی مسلمان نہیں ہو سکتا، جو لوگ رسول صلّی اللہ علیہ واٰلہٖ وسلّم کی رسالت پر ایمان نہیں لائیں گے وہ اگرچہ خدا کی توحید کا عمربھر ڈنکا بجاتے رہیں مگر وہ کافر اور جہنمی ہی رہیں گے۔ اس لئے اسلام کا بنیادی کلمہ یعنی کَلمۂ طیبہ ’’لَا اِلٰہَ اِلَّا اللہ مُحَمَّدٌ رَّسُوْلُ اللہ‘‘ ہے، یعنی مسلمان ہونے کے لئے خدا کی توحید اور رسول کی رسالت دونوں پر ایمان لانا ضروری ہے۔‘‘ (سیرت مصطفیٰ، ص 826، ملتقطًا)\n¥صوفیا کے نزدیک ایمان کی حقیقت:\n حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ مراٰۃ المناجیح، جلد5، صفحہ409 پر فرماتے ہیں: اللہ رسول پر ایمان لانے کا مطلب یہ ہے کہ رب (کریم) نے جو کچھ بھیجا اورحضور (اقدس صلّی اللہ علیہ واٰلہٖ وسلّم )جو کچھ لائے ان سب پر ایمان لائے۔صوفیاء فرماتے ہیں کہ حقیقتاً ایمان ہے اللہ رسول کو ملانا، اللہ رسول میں فرق کرنا کفر ہے، (اللہ پاک)قرآن کریم فرماتاہے:\nاَنْ یُّفَرِّقُوْا بَیْنَ اللّٰهِ وَ رُسُلِهٖ وَ یَقُوْلُوْنَ نُؤْمِنُ بِبَعْضٍ وَّ نَكْفُرُ بِبَعْضٍۙ-وَّ یُرِیْدُوْنَ اَنْ یَّتَّخِذُوْا بَیْنَ ذٰلِكَ سَبِیْلًا(150)اُولٰٓىٕكَ هُمُ الْكٰفِرُوْنَ حَقًّاۚ- (پ ۶، النسآء:۱۵۰، ۱۵۱)\nترجمہ کنزالایمان: کہ اللہ سے اس کے رسولوں کو جدا کر دیں اور کہتے ہیں ہم کسی پر ایمان لائے اور کسی کے منکر ہوئے اور چاہتے ہیں کہ ایمان وکفر کے بیچ میں کوئی راہ نکال لیں یہی ہیں ٹھیک ٹھیک کافر۔\n¥فرشتوں پر ایمان کا مطلب:\n فرشتوں پر ایمان لانے سے یہ مراد ہے کہ صدقِ دل سے یہ مان لیا جائے کہ فرشتے اللہ (پاک) کی ایک نوری مخلوق اور اس کے محترم بندے ہیں جن میں گناہوں کا مادہ ہی نہیں ۔ وہ ہر چھوٹے بڑے گناہوں سے معصوم اور پاک ہیں ، نہ وہ عورت ہیں نہ مرد، نہ وہ کھاتے ہیں نہ پیتے ہیں ،بس خدا کی بندگی ان کی زندگی ہے۔قرآن میں اللہ تعالیٰ نے فرشتوں کی یہ صفت بیان فرمائی ہے کہ\nلَّا یَعْصُوْنَ اللّٰهَ مَاۤ اَمَرَهُمْ وَ یَفْعَلُوْنَ مَا یُؤْمَرُوْنَ\n (پ ۲۸، التحریم:۶)\nترجمہ کنزالایمان: جو اللہ کا حکم نہیں ٹالتے اور جوانھیں حکم ہو وہی کرتے ہیں۔\nیعنی وہ کبھی بھی اور کسی کام میں بھی اور کسی حال میں اللہ (پاک) کی کوئی نافرمانی نہیں کرتے بلکہ خداوند تعالیٰ جو کچھ انہیں حکم دیتا ہے وہی کرتے ہیں۔ کوئی وحی لاتا ہے،کوئی پانی برساتا ہے، کوئی انسانوں کے اعمال کی نگہبانی اور ان کی حفاظت کرتا ہے، کوئی مؤمنین کے لئے رحمت و مغفرت کی دعائیں کرتا ہے۔ غرض جس کو خدا نے جس کام میں لگادیا وہی کرتا ہے اور سب خدا کی عبادت واطاعت میں مصروفِ عمل ہیں ۔واضح رہے کہ فرشتوں کے وجود کا انکار کرنا یا ان پر کوئی عیب لگانا یا ان کی توہین کرنا کفر ہے۔ (منتخب حدیثیں، ص63)\n¥ تقدیر پر ایمان کا مطلب:\n تقدیر پر ایمان لانے کا مطلب یہ ہے کہ ہر بھلائی بُرائی اللہ عَزَّوَجَلَّ نے اپنے علْمِ اَزَلی کے مُوَافِق مُقَدَّر کردی ہے ، جو بات جیسے ہونے والی تھی اور جو شخص جو کچھ کرنے والا تھا، اللہ عَزَّوَجَلَّ اسے اَزَل سے جانتا تھا، اسی کے مطابق لکھ لیا، اب اس کے خلاف نہیں ہو سکتا ۔ یہ نہیں کہ اللہ عَزَّوَجَلَّ نے لوگوں کے اَحوال جانے بغیر جو چاہا لکھ دیا اور اب ہم اس لکھنے کی وجہ سے ویسا ہی کرنے پر مجبور ہیں۔ مثلاً زید کے ذمے برائی لکھی، اس لئے کہ اللہ عَزَّوَجَلَّ کو معلوم تھا کہ بُرائی کرے گا اگر زید بھلائی کرنے والا ہوتا تو اس کے ذمے بھلائی لکھتا ، اس کو یوں سمجھئے کہ اللہ عَزَّوَجَلَّ نے انسان کو جمادات پتھر کنکر کی طرح بےحس وحرکت، بے اِختیار نہیں بنایا، بلکہ ایک قسم کا اختیار بھی دیا ہے کہ کسی کام کو چاہے تو کرے، چاہے تو نہ کرے، اسی کے ساتھ عقل بھی دی کہ وہ بھلے بُرے نفع نقصان کو پہچان سکے اور ہر قسم کے سامان و اَسباب مہیا فرمادیئے کہ جب کوئی کام کرنا چاہتا ہے تو اُن اسباب سے کام لے، اسی اختیار پر مواخذہ ہے۔ اپنے آپ کو پتھر و کنکر کی طرح مجبور محض سمجھنا یا بالکل مختار سمجھنا دونوں گمراہی ہیں۔(مقالات شارح بخاری، باب اول، 1/ 146) \n¥تقدیر کے معاملات میں بحث ومباحثہ باعث ہلاکت ہے:\n تقدیر کے مسائل عام لوگوں کی سمجھ میں نہیں آسکتے۔ اس لئے تقدیر کے مسائل میں زیادہ غور و فکر اور بحث و مباحثہ کرنا ہلاکت کا سبب ہے۔ امیرالمؤمنین حضرت ابوبکر صدیق وامیرالمؤمنین حضرت عمر فاروق رضی اللہ تعالیٰ عنہما تقدیر کے مسئلہ میں بحث کرنے سے منع فرما ئےگئے ہیں۔ پھر بھلا ہم کس گنتی میں ہیں کہ اس مسئلہ میں بحث و مباحثہ کریں۔ ہمارے لئے یہی حکم ہے کہ ہم تقدیر پر ایمان لائیں اور اس مشکل اور نازک مسئلہ میں ہرگز ہرگز کبھی بحث ومباحثہ اور حجت و تکرار نہ کریں کہ اسی میں ایمان کی سلامتی ہے۔(جنتی زیور، ص187)\nحدیث شریف میں ہے: (آنے والے شخص نے احسان کے بارے میں پوچھا تو ارشاد ہوا: تم اللہ پاک کی عبادت اس طرح کرو گویا اسے دیکھ رہے ہو اگر تم اسے نہیں دیکھ سکتے تو بےشک وہ تو تمہیں دیکھ ہی رہا ہے )\n¥احسان کی حقیقت:\n لغت میں احسان کے معنیٰ ’’اچھائی ‘‘ہیں۔ چنانچہ اچھا کام احسان کہلاتا ہے اور کسی کے ساتھ اچھا سلوک کرنے کو بھی احسان کہا جاتا ہے اور قرآن و حدیث میں لفظ احسان اس معنیٰ میں بکثرت استعمال بھی ہواہے مگر اس حدیث میں جو ’’احسان‘‘ آیا ہے یہ احسان در حقیقت ایمان و اسلام کی طرح دین کا ایک اصطلاحی لفظ ہے جس کے معنیٰ کوخود حضور اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے اپنی زبان نبوت سے ارشاد فرمایاکہ ’’خدا کی عبادت اس طرح کی جائے کہ گویا عبادت کرنے والا خدا کو دیکھ رہا ہے ‘‘ اس معنیٰ میں احسان کا تعلق صرف نماز و روزہ اور زکوٰۃ و حج ہی کے ساتھ مخصوص نہیں ہے بلکہ مومن کے ہر عمل میں اس کی روح کارفرما ہونی چاہئے یعنی ہر عمل کے وقت بندہ اس طرح حضورِ قلب اور اخلاصِ دل کے ساتھ عمل میں مشغول ہو کہ گویا وہ خدا کو دیکھ رہا ہے اس تصوُّر سے عمل کرنے والے بندے کے دل میں خوف و خشیَّتِ ربّانی اور امید و رجاءِ رحمانی کا ایسا نور پیدا ہوجائے گا کہ اس کا عمل انوارِ مقبولیت کی روشنی سے پُر نوراور بندہ سراپا نور بلکہ نورٌ علیٰ نور ہوجائے گااور رحمْتِ کردگار و فَضلِ پروردگار کا دونوں جہان میں مستحق و حق دار بن جائے گا۔(منتخب حدیثیں، ص66)\nحدیث شریف میں ہے: (آنے والے شخص نے قیامت کے بارے میں پوچھا تو ارشاد ہوا: جس سے\nقیامت کے بارے میں پوچھا گیا ہے وہ پوچھنے والے سے زیادہ نہیں جانتا)\n¥کیا رسولُ اللہ صلّی اللہ علیہ وسلّم ¥کو قیامت کا علم نہیں؟\n جب قیامت کے بارے میں سوال ہوا تو اس کے جواب میں حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے اس کے جواب میں ارشاد فرمایا: ’’مَاالْمَسْؤُلُ عَنْہَا بِاَعْلَمَ مِنَ السَّائِلِ ۔‘‘ بعض لوگوں نے اس کا یہ معنیٰ سمجھا کہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم کو قیامت کا علم نہیں تھا جو اس بات پر دلیل ہے کہ آپ صلّی اللہ علیہ واٰلہٖ وسلّم عِلْمِ غیب نہیں جانتے حالانکہ ایسا نہیں ہے۔ چنانچہ مشہور شارح حدیث، حکیم الامت، مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ کے کلام کا خلاصہ ہے: ’’اس فرمان عالی سے یہ دلیل پکڑنا کہ آپ صلّی اللہ علیہ واٰلہٖ وسلّم کوقیامت کا علم نہیں ، محض لغو ہے دو وجہ سے ایک تو یہ کہ اس میں حضور صلّی اللہ علیہ واٰلہٖ وسلّم نے اپنے جاننے کی نفی نہیں کی بلکہ زیادتِیِ علم (یعنی سائل سے زیادہ جاننے) کی نفی کی ہے ورنہ یہ نہ فرماتے بلکہ فرماتے:’’لَا اَعْلَمُ یعنی میں نہیں جانتا۔‘‘ اتنی دراز عبارت کیوں ارشاد فرماتے !اس کا یہ مطلب ہو سکتا ہے کہ اے جبریل! اس مسئلہ میں میرا اور تمہارا علم برابرہے مجھ کو بھی خبر ہے اور تم کو بھی اس مجمع میں یہ پوچھ کر راز ظاہر کرنا مناسب نہیں دوسرا یہ کہ یہ جواب سن کر حضرت سیِّدُنا جبریل امین علیہِ السّلام نے عرض کی: ’’فَاَخْبِرْنِیْ عَنْ اَمَارَاتِھَا یعنی پھر قیامت کی نشانیاں ہی بتا دیجئے۔‘‘ اس پرحضور صلّی اللہ علیہ واٰلہٖ وسلّم نے چند نشانیاں بیان فرمائیں کہ اولاد نا فرمان ہوگی اور کمینے لوگ عزت پائیں گے وغیرہ وغیرہ ۔ جس کو قیامت کا بالکل ہی علم نہ ہو اس سے نشانیاں پوچھنا کیا معنیٰ؟ نشان اور پتہ تو جاننے والے سے پوچھا جاتا ہے۔ حضور صلّی اللہ علیہ واٰلہٖ وسلّم نے تو قیامت قائم ہونے کا دن تک بھی بتا دیا۔ چنانچہ مشکوٰۃ ’’بَابُ الْجُمُعَۃِ‘‘ میں ہے ’’لَا تَقُوْمُ السَّاعَۃُ اِلَّا فِیْ یَوْمِ الْجُمُعَۃِ یعنی قیامت جمعہ کے دن قائم ہوگی۔‘‘(مشکاة المصابیح، کتاب الصلاة، باب الجمعة، الفصل الاول، ۱/ ۲۶۳،حدیث:۱۳۵۶)شہادت اور بیچ کی انگلی کو ملا کر ارشاد فرمایا: ’’بُعِثْتُ اَنَا وَالسَّاعَۃُ کَھَاتَیْنِیعنی میں اور قیامت اس طرح ملے ہوئے بھیجے گئے ہیں۔‘‘ (بخاری،کتاب الرقاق، باب قول النبی بعثت انا والساعة کھاتین، ۴/ ۲۴۸،حدیث:۶۵۰۵)یعنی ہمارے زمانے کے بعد پس قیامت ہی ہے اور اس قدر علاماتِ قیامت ارشاد فرمائیں کہ ایک بات بھی نہ چھوڑی آج میں قسم کھا کر کہہ سکتا ہوں کہ ابھی قیامت نہیں آسکتی کیونکہ ابھی نہ دجال آیا نہ حضرت مسیح ومہدی (علیہما السّلام)، نہ سورج مغرب سے نکلا، ان علامات نے قیامت کو بالکل واضح فرما دیا ، پھر قیامت کا علم نہ ہونے کے کیا معنیٰ؟ پس زیادہ سے زیادہ یہ کہا جاسکتاہے کہ سن (سال)نہ بتایا کہ فلاں سن میں قیامت ہوگی۔ لیکن حضور صلّی اللہ علیہ واٰلہٖ وسلّم کے زمانَۂ پاک میں سن مقرر ہی نہ ہوئی تھی، سن ہجری عہدِ فاروقی میں مقرر ہوئی کہ ہجرت تو ربیع الاول میں ہوئی مگر سن ہجری کاآغاز محرم سے ہوتا ہے بلکہ اس زمانے میں قاعدہ یہ تھا کہ سال میں جوکوئی بھی اہم واقعہ ہوااس سے سال منسوب کر دیا ۔ سالِ فِیل، سال فتح، سالِ حدیبیہ وغیرہ۔ تو سن ہجری کس طرح بیان کیا جاسکتا تھا۔ اس دن کی علامات وغیرہ سب بتا دیں اور جو ذات اس قدر تفصیلی علامتیں بیان کرے وہ بے علم کیسے ہو سکتی ہے؟ نیزحدیث پاک سے ثابت ہے کہ حضور صلّی اللہ علیہ واٰلہٖ وسلّم نے قیامت تک کے مِنْ وعَنْ واقعات بیان کر دئیے۔ اب کیسے ممکن ہے کہ قیامت کا علم نہ ہو؟ کیونکہ دنیا ختم ہوتے ہی قیامت ہے اور حضور صلّی اللہ علیہ واٰلہٖ وسلّم کو یہ علم ہے کہ کون سا واقعہ کس کے بعد ہو گا ۔ تو جو آخری واقعہ ا رشاد فرمایا وہ ہی دنیا کی انتہا ہے اور قیامت کی ابتدا۔ دو ملی ہوئی چیزوں میں سے ایک کی انتہا کاعلم دوسری کے ابتداء کا علم ہوتا ہے۔\n (جاء الحق، ص96)\n¥علم غیب کے متعلق روایات\n¥جنتیوں اور جہنمیوں کے بارے میں بتا دیا: \n بخاری شریف میں ہے:امیر المؤمنین حضرت سیِّدُنا عمر فاروق اعظم رضی اللہ عنہ فرماتے ہیں کہ اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم ایک مرتبہ ہمارے درمیان کھڑے ہوئے اور ہمیں ابتدائے پیدائش کی خبر دے دی یہاں کہ جنتی لوگ اپنی اپنی منزلوں میں اور جہنمی اپنے اپنے ٹھکانوں میں پہنچ گئے، جس نے یاد رکھا اس نے یاد رکھا اور جو بھول گیا وہ بھول گیا۔ (بخاری،کتاب بدء الخلق، باب ماجاء فی قولِ اللّٰہ تعالٰی:وھوالذی یبدأ الخلق ثم یعیدہ، ۲/ ۳۷۵، حدیث:۳۱۹۲)\n¥جو پوچھنا چاہتے ہو پوچھ لو:\n بخاری شریف میں ہی حضرت سیِّدُنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم منبرِ اقدس پر کھڑے ہوئے، پس قیامت کا ذکر فرمایا اور ارشاد فرمایا: ’’ا س سے پہلے بڑے بڑے واقعات ہیں۔‘‘ پھر ارشاد فرمایا: ’’جو شخص بھی کچھ پوچھنا چاہتا ہے پوچھ لے اللہ پاک کی قسم ! جب تک میں اس جگہ یعنی اس منبر پر ہوں تم مجھ سے جو بھی بات پوچھو گے میں اس کا جواب دوں گا۔ چنانچہ ایک شخص کھڑا ہوا اور عرض کی: میرا ٹھکانہ کہاں ہے؟ ارشاد فرمایا: ’’جہنم میں۔‘‘ حضرت عبداللہ بن حُذافَہ رضی اللہ عنہ نے کھڑے ہو کر عرض کی: میرا باپ کون ہے؟ ارشاد فرمایا: ’’حُذافَہ۔‘‘ پھر آپ صلّی اللہ علیہ واٰلہٖ وسلّم بار بار ارشاد فرماتے رہے کہ ’’مجھ سے پوچھو! مجھ سے پوچھو!‘‘ \n(بخاری،کتاب الاعتصام بالکتاب والسنة، باب ما یکرہ من کثر السوال وتکلف ما لا یعنیہ، ۴/ ۵۰۳، حدیث:۷۲۹۴، ملخصًا)\n¥قیامت تک ہونے والے واقعات کی خبر:\n مسلم شریف میں ہے:حضرت سیِّدُنا عَمْرو بن اَخْطَب رضی اللہ عنہ فرماتے ہیں کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ہمیں ان تمام واقعات کی خبر دی جو ہوئے اور جو قیامت تک ہونے والے ہیں، پس ہم میں بڑا عالِم وہ ہے جو ان باتوں کو زیادہ یاد رکھنے والا ہے۔(مسلم، کتاب الفتن واشراط الساعة، باب اخبار النبی فیما یکون… الخ، ص۱۱۸۴، حدیث:۷۲۶۷)\n (نوٹ: مذکورہ روایات کے علاوہ بھی علم غیب سے متعلق بہت سی روایات ہیں۔ تفصیل کے لئے سیِّدِی اعلیٰ حضرت، امام اہل سنت مولانا شاہ امام احمد رضا خان رحمۃُ اللہ علیہ کے عظیم الشان رسائل: ’’اَلدَّوْلَۃُ الْمَکِّیَّۃ، اَلْفُیُوْضُ الْمَلَکِیَّۃ ،اَلْکَلِمَۃُ الْعُلْیَا‘‘ اور حضرت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ کی مایہ ناز تصنیف ’’جَآءَ الْحَق‘‘ کا مطالعہ کیجئے۔ )\nحدیث شریف میں ہے: (آنے والے شخص نے قیامت کی نشانیوں کے بارے میں پوچھا تو ارشاد ہوا:باندی\n(غلام عورت) اپنے مالک کو جنے گی اور تم دیکھو گے کہ ننگے پاؤں، برہنہ جسم، مفلس، بکریاں چرانے والے\nبلند وبالا عمارتوں کی تعمیرات میں ایک دوسرے پر فخر کریں گے)\n¥قیامت کی دو نشانیاں:\n اس حدیث پاک میں قیامت کی صرف دو نشانیوں کا ذکر ہے:(1)…باندی اپنے آقا کو جنے گی۔ (2)…مفلس ونادار اور گنوار لوگ اونچے اونچے محلات میں فخر کریں گے۔ یہ دو نشانیاں اُن نشانیوں میں سےہیں جو اِس زمانے میں ظاہر ہو چکی ہیں اور ہر شخص بخوبی جان اور دیکھ سکتا ہے۔شارحیْنِ حدیث نے ان کے کئی معانی بیان فرمائے ہیں۔ چنانچہ ایک معنیٰ یہ ہے کہ ’’قُربِ قیامت میں باندیوں کی کثرت ہوگی اُن سے اُن کے آقا کی جو اولاد ہوگی مرنے کے بعد یہ باندیاں انہیں مل جائیں گی کیونکہ مرنے کے بعدباپ کا مال اولاد کو ملتا ہے، ا س طرح ان کی مالک ان کی اپنی اولاد ہوگی۔‘‘ ایک معنیٰ یہ ہے کہ ’’باندیاں جن بچوں کو جنم دیں گی ان میں سے بعض قوم کے حاکم و سردار بنیں گے، پس وہ حاکم ہوں گے اور ان کی مائیں ان کی رعایا۔‘‘ ایک معنیٰ یہ ہے کہ ’’ایک شخص باندی خریدے گا اس سے بچہ پیدا ہو گا پھروہ باندی کو فروخت کردے گا بچہ بڑا ہوجائے گا اور وہ باندی دست بدست بکتی ہوئی اپنے اسی بچے کی ملکیت میں پہنچ جائے گی ۔اس طرح اس کااپنا بیٹا اس کا مالک بن جائے۔‘‘\n شارح بخاری حضرت علامہ مفتی شریف الحق امجدی رحمۃُ اللہ علیہ فرماتے ہیں: ’’یہ نشانیاں ظاہر ہو چکی ہیں شاہان بنی عباس میں سے سوائے امین سب باندی زادے تھے۔‘‘ ایک معنیٰ یہ ہے کہ ’’یہ کنایہ ہے اس بات سے کہ لوگ اپنی حقیقی ماں کے ساتھ لونڈیوں جیسا سلوک کریں گے، ماں کو لونڈیوں کی طرح رکھیں گے، ان کی نافرمانی وحق تلفی کریں گے، ایذا پہنچائیں گے یعنی اولاد اپنی ماں کے ساتھ آقا کی طرح برتاؤ کرے گی۔(مقالات شارح بخاری، باب اول، 1/ 156، ملخصاً) دوسری نشانی: ننگے پاؤں برہنہ بدن، فقیر اور بکریاں چرانے والے بڑی بڑی عمارتیں بنائیں گے۔مطلب یہ ہے کہ صحرا، جنگل گاؤں دیہات میں رہنے والے اورحاجت مند فقراء ترقی کرکے بڑے بڑے محلات بنائیں گے ،دنیا ان پر بہت آسان ہوجائے گی وہ اپنے عمدہ گھروں میں رہ کر ایک دوسرے پر فخر کریں گے۔(شرح الاربعین النوویة، ص۳۳)\n¥قیامت کی بڑی نشایاں:\n مذکورہ دونشانیوں کے علاوہ بھی دیگر احادیث مبارکہ میں اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے قیامت کی بہت سی نشانیاں بیان فرمائی ہیں۔کئی ظاہر ہو چکی ہیں اور جوباقی ہیں وہ بھی یقیناً ظاہر ہوں گی۔ جن میں سے کچھ یہ ہیں: (1)…دجال کا فتنہ۔ (2)…حضرت امام مہدی رحمۃُ اللہ علیہ کا ظہور۔ (3)…حضرت عیسیٰ علیہِ السّلام کا آسمان سے اترنا۔ (4)…یاجوج ماجوج کا نکلنا۔ (5)…دابۃ الارض کا خُروج۔ یہ سب قیامت کی وہ نشانیاں ہیں جو ابھی تک ظاہر نہیں ہوئیں مگر ان سب کا ظہور اتنا ہی یقینی ہے جتنا کہ رات کے بعد دن کا آنا یقینی ہےکیونکہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ان سب علامات کے ظاہر ہونے کی خبر دی ہے۔(منتخب حدیثیں، ص67ملخصاً)\nحدیث شریف کے آخر میں ہے کہ (اس شخص کے جانے كےبعد آپ صلّی اللہ علیہ وسلّم نے حضرت سیِّدُنا عُمَر فاروق اعظم رضی اللہ عنہ سے ارشاد فرمایا: اے عمر! جانتے ہو وہ سائل کون تھا؟ انہوں نے عرض کی: اللہ پاک اور اس کے رسول صلّی اللہ علیہ وسلّم بہتر جانتے ہیں۔ تو ارشاد ہوا: وہ جبرائیل علیہ السَّلام تھے جو تمہیں تمہارا دین سکھانے آئے تھے)\n¥بارگاہِ رسالت کا ایک ادب:\n’’اللہ پاک اور اس کے رسول صلّی اللہ علیہ وسلّم بہتر جانتے ہیں‘‘یہ صحابَہ (کرام علیہمُ الرّضوان) کا ادب ہے کہ علم اللہ اور رسول کے سپرد کرتے ہیں۔ اس سے دو مسئلے معلوم ہوئے: ایک یہ کہ حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کا ذکراللہ (پاک) کےساتھ ملاکرکرناشرک نہیں بلکہ سنَّتِ صحابہ ہے،یہ کہہ سکتے ہیں کہ اللہ اور رسول جانیں، اللہ اور رسول فضل کریں، اللہ اور رسول رحم فرمادیں، اللہ اور رسول بھلاکریں۔’’وہ جبریل علیہِ السّلام تھے‘‘حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم )کو خبرتھی کہ یہ سائل جبریل تھے ورنہ آپ فرمادیتے کہ مجھےبھی خبر نہیں یہ کون تھے (اور یہ بھی بتا دیا) اس لئے آئے تھے کہ تمہارے سامنے مجھ سے سوالات کریں تم جوابات سن کر دین سیکھ لو۔ اس سے معلوم ہوا کہ مسلمان پر حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کی اطاعت واجب ہے نہ کہ جبریل ( علیہِ السّلام ) کی کہ یہاں جبریل ( علیہِ السّلام ) نے حاضرین سے خود نہ کہہ دیا کہ لوگو! میں جبریل ہوں مجھ سے فلاں فلاں بات سیکھ لو بلکہ حضور صلّی اللہ علیہ وسلّم سے کہلوایا تاکہ لوگوں کےلیےقابل قبول ہو۔(مراٰۃ المناجیح، 1/ 27)\n’’جبریل‘‘ کا مطلب:جبریل عبرانی زبان کا لفظ ہے اس کا معنیٰ ہے’’ عبداللہ‘‘جبر کا معنیٰ عبد اور ایل کا معنیٰ اللہ ہے۔(ماخوذ ازمراٰۃ المناجیح، 1/ 27)\n¥سیِّدُنا جبریل علیہِ السّلام ¥انسانی صورت میں:\nیاد رہے! حضرت سیِّدُنا جبریل علیہِ السّلام فرشتوں کے سردار ہیں اور فرشتے نوری مخلوق ہیں اور نور وبشر ایک دوسرے کی ضد نہیں کہ ایک جگہ جمع نہ ہو سکیں حضرت سیِّدُنا جبریل علیہِ السّلام نوری مخلوق ہونے کے باوجود انسانی صورت میں تشریف لائے جیساکہ مذکورہ حدیث شریف میں ہے۔ اسی طرح حضرت سیِّدَتُنا بی بی مریم رضی اللہ عنہا کے سامنے انسانی شکل میں جلوہ گَر ہوئے تھے۔ جیساکہ قرآنِ مجید میں ہے:\nفَاَرْسَلْنَاۤ اِلَیْهَا رُوْحَنَا فَتَمَثَّلَ لَهَا بَشَرًا سَوِیًّا(17)\n(پ ۱۶، مریم:۱۷) ترجمہ کنزالایمان: تو اس کی طرف ہم نے اپنا روحانی بھیجا وہ اس کے سامنے ایک تندرست آدمی کے روپ میں ظاہر ہوا۔\nنیزبخاری شریف میں ہے کہ ’’حضرت مَلَکُ الموت علیہِ السّلام حضرت موسیٰ کَلِیْمُ اللہ علیہِ السّلام کی بارگاہ میں بشری صورت میں حاضر ہوئے۔‘‘ ( بخاری، کتاب الجنائز ، باب من احب الدفن فی الارض المقدسة اونحوھا ، ۱/ ۴۵۰، حدیث:۱۳۳۹)\n¥سردار ملائکہ کی بارگاہِ انبیا میں حاضری:\n حضرت سیِّدُنا جبریل علیہِ السّلام وحی لانے پر مقرر ہیں کہ آپ حضرت سیِّدُنا آدم علیہِ السّلام سے لے کر اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم تک تمام انبیائے کرام علیہمُ السّلام کی خدمت میں وحی لے کر حاضر ہوتے رہے مختلف انبیائے کرام علیہمُ السّلام کی بارگاہ میں متعدد بار حاضر ہوئے۔ چنانچہ حضرت سیِّدُنا آدم کی خدمت میں 12مرتبہ، حضرت سیِّدُنا ادریس کی خدمت میں چارمرتبہ، حضرت سیِّدُنا نوحکی خدمت میں 50مرتبہ، حضرت سیِّدُنا ابراہیم کی خدمت میں 42مرتبہ، حضرت سیِّدُنا عیسیٰ کی خدمت میں 10مرتبہ، تین بار بچپنے میں اور سات بار بڑے ہونے کے بعد، حضرت سیِّدُنا یعقوب کی خدمت میں چار مرتبہ، حضرت سیِّدُنا ایوب علیہمُ السّلام کی خدمت میں تین مرتبہ اور سیِّدُالانبیا صلّی اللہ علیہ واٰلہٖ وسلّم کی خدمت میں 24 ہزار مرتبہ باریابی سے مشرف ہوئے۔ \n(ارشاد الساری، کتاب بدء الوحی، باب کیف کان بدء الوحی الی رسول اللّٰہ، ۱/ ۱۰۱، تحت الحدیث:۲) \n¥دعا:\nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6868, "bookId": 13, "volNo": "1", "hadithNo": 3, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "اسلام کی بنیاد", "arabic": "عَنْ اَبِيْ عَبْدِ الرَّحْمٰنِ عَبْدِ اللهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ رَضيَ اللهُ عَنْهُ مَا قَالَ: سَمِعْتُ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُوْلُ: ’’بُنِيَ الْاِسْلَامُ عَلٰى خَمْسٍ: شَهَادَةِ اَنْ لَّااِلٰهَ اِلَّا اللهُ وَاَنَّ مُحَمَّدًا عَبْدُهٗ وَرَسُوْلُهٗ وَ اِقَامِ الصَّلَاةِ وَاِيْتَاءِ الزَّكَاةِ وَحَجِّ الْبَـيْتِ وَصَوْمِ رَمَضَانَ.‘‘ (رَوَاهُ الْبُخَارِي وَمُسْلِم)", "urdu": "حضرت سیِّدُنا ابو عبد الرحمٰن عبد اللہ بن عُمَر رضی اللہ عنہما بیان کرتے ہیں:میں نے رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم کو ارشاد فرماتے سنا کہ ”اِسلام کی بنیاد پانچ چیزوں پر ہے: اس بات کی گواہی دینا کہ اللہ پاک کے سوا کوئی عبادت کے لائق نہیں اور بےشک حضرت محمد صلّی اللہ علیہ واٰلہٖ وسلّم اللہ کے بندے اور رسول ہیں، نماز قائم کرنا، زکوٰۃ دینا، بیْتُ اللہ کا حج کرنا اور رمضان کے روزے رکھنا۔“( بخاری، كتاب الايمان، باب دعائكم ايمانكم، ۱/ ۱۴، حدیث:۸۔ مسلم، کتاب الایمان، باب ارکان الاسلام...الخ، ص ۳۷، حدیث:۱۱۳، بدون ’’سمعت‘‘)", "roman": "Hazrat Sayyiduna Abu Abdur Rahman Abdullah Ibn Umar RadiyAllahu Anhuma bayan karte hain: Main ne Rasool-e-Paak Sallallahu Alaihi Wasallam ko irshad farmate suna ke \"Islam ki buniad paanch cheezon par hai: Is baat ki Gawahi dena ke Allah Paak ke siwa koi ibadat ke laaiq nahi aur beshak Hazrat Muhammad Sallallahu Alaihi Wasallam Allah ke bande aur Rasool hain, Namaz qaim karna, Zakat dena, Baitullah ka Hajj karna aur Ramzan ke roze rakhna.\" (Bukhari, Kitaab-ul-Iman, Baab Dua'ukum Imanukum, 1/14, Hadees: 8. Muslim, Kitaab-ul-Iman, Baab Arkan-il-Islam... ilkh, p. 37, Hadees: 113, bidoon \"Sami'tu\")", "explanation": "ایمان اور اسلام کے متعلق ابتدائی اہم گفتگو سابقہ روایت کی شرح میں بیان ہو چکی ہے یہاں مختصراً کلمہ شہادت کی وضاحت اور باقی ارکان کی شرح بیان کی جاتی ہے۔\nپہلا رکن: ¥کَلمۂ شہادت\n کلمہ شہادت کا مفہوم اور مطلب یہ ہے کہ صدقِ دل سے اللہ پاک کے ایک ہونے اور معبود ہونے اور حضرت محمد صلّی اللہ علیہ واٰلہٖ وسلّم کے رسول ہونے کی گواہی دینا اور دل سے مانتے ہوئے زبان سے: ’’اَشْہَدُ اَنْ لَّا اِلٰہَ اِلَّا اللہ وَحْدَہٗ لَا شَرِیْکَ لَہٗ وَاَشْہَدُ اَنَّ مُحَمَّدًا عَبْدُہٗ وَرَسُوْلُہٗ‘‘ کہنا۔ اس میں تمام ضروری عقائد ِاسلام داخل ہیں کیونکہ جس نے حضور اکرم صلّی اللہ علیہ واٰلہٖ وسلّم کو دل سے اللہ پاک کا رسول مان کر ان کی رسالت کی گواہی دے دی (اس نے)ہر اس چیز کی تصدیق کردی جس کو حضور علیہِ الصّلوٰۃُوالسّلام خدا کی طرف سے لائے۔(منتخب حدیثیں، ص65)\nدوسرا رکن: ¥نماز\n¥نمازکی فرضیت، اہمیت اور فضیلت:\nجن پانچ چیزوں پر اسلام کی بنیاد ہے ان میں سے دوسری چیز نماز ہے۔اللہ پاک قرآنِ مجید میں ارشاد فرماتا ہے: \nوَ اَقِیْمُوا الصَّلٰوةَ وَ اٰتُوا الزَّكٰوةَ وَ ارْكَعُوْا مَعَ الرّٰكِعِیْنَ(43) \n(پ ۱، البقرة:۴۳) ترجمہ کنزالایمان: اور نماز قائم رکھو اور زکوٰۃ دو اور رکوع کرنے والوں کے ساتھ رکوع کرو۔\n ’’صَلوٰۃ‘‘ کا معنیٰ ومفہوم: یہ صَلْیٌ سے بنا بمعنی گوشت بھوننا، آگ پرپکانا، اللہ پاک ارشاد فرماتاہے: ’’ سَیَصْلٰى نَارًا ذَاتَ لَهَبٍ(3) (پ ۳۰، اللھب:۳ ، ترجمہ کنزالایمان:اب دھنستا ہے لپٹ مارتی آگ میں وہ)۔ ‘‘ نیز آگ سے لکڑی سیدھی کرنے کو ’’تصلیہ‘‘ کہا جاتا ہے، چونکہ نماز نمازی کے نفس کو مجاہدہ ومشقت کی آگ پر جلاتی ہے، نیزاسے سیدھے راستے پر رکھتی ہے اس لئے اسے ’’صلوٰۃ‘‘ کہتے ہیں۔اب ’’صلوٰۃ‘‘ کے معنیٰ دعا، رحمت، اِنزال رحمت، اِستغفار، ہیں۔ چونکہ یہ سب چیزیں نماز میں ہوتی ہیں اس لئے نماز کو ’’صلوٰۃ‘‘ کہتے ہیں۔ \n نماز کی فرضیت:اِسلام میں سب اَعمال سے پہلے نماز فرض ہوئی،یعنی نبوت کے گیارہویں سال ہجرت سے دو سال کچھ ماہ پہلے،نیزساری عبادتیں اللہ پاک نے فرش پر بھیجیں مگر نماز اپنے محبوب کو عرش پربلاکردی، اس لئے کَلمۂ شہادت کے بعد سب سے بڑی عبادت نماز ہے۔ جونمازسیدھی کرکے پڑھے تونمازاسے بھی سیدھا کردیتی ہے۔(مراٰۃ المناجیح، 1/ 360، ملخصاً)\n فرضیت نماز کا انکار کرنے کا حکم:ہر مکلف یعنی عاقل بالغ (مسلمان مرد وعورت) پر نماز فرضِ عین ہے، اس کی فرضیت کا منکر (انکار کرنے والا) کافر ہے اور جو قصداً ترک کرے اگرچہ ایک ہی وقت کی ہو وہ فاسق ہے اور جو نماز نہ پڑھتا ہو قید کیا جائے یہاں تک کہ توبہ کرے اور نماز پڑھنے لگے بلکہ ائمَّۂ ثلاثہ حضرت سیِّدُنا امام مالک، حضرت سیِّدُنا امام شافعی اور حضرت امام احمد بن حنبل رحمۃُ اللہ علیہم کے نزدیک سلطانِ اسلام کو اس کے قتل کا حکم ہے۔(الدر المختار معہ رد المحتار، کتاب الصلاة، ۲/ ۶)\nایمان اور عقائد کی درستی کے بعد تمام فرائض میں نماز نہایت اہم واعظم عبادت ہے۔ قرآنِ مجید کی آیات بینات اور احادیث مبارکہ اس کی اہمیت سے مالا مال ہیں، جابجا اس کی تاکید آئی ہے اور چھوڑنے پر وعیدات مروی ہیں۔\n¥نماز کی فضیلت پر آیاتِ مبارکہ:\n چنانچہ اللہ پاک ارشاد فرماتا ہے: \nفِیْهِ ۚۛ-هُدًى لِّلْمُتَّقِیْنَ(2) الَّذِیْنَ یُؤْمِنُوْنَ بِالْغَیْبِ وَ یُقِیْمُوْنَ الصَّلٰوةَ وَ مِمَّا رَزَقْنٰهُمْ یُنْفِقُوْنَ(3)\n(پ ۱، البقرة:۲، ۳) ترجمہ کنزالایمان: اس میں ہدایت ہے ڈر والوں کو وہ جو بےدیکھے ایمان لائیں اور نماز قائم رکھیں اور ہماری دی ہوئی روزی میں سے ہماری راہ میں اٹھائیں۔\nایک مقام پر ارشاد ہوا: \nحٰفِظُوْا عَلَى الصَّلَوٰتِ وَ الصَّلٰوةِ الْوُسْطٰىۗ-وَ قُوْمُوْا لِلّٰهِ قٰنِتِیْنَ(238) \n(پ ۲، البقرة: ۲۳۸) ترجمہ کنزالایمان: نگہبانی کرو سب نمازوں اور بیچ کی نماز کی اور کھڑے ہو اللہ کے حضور ادب سے۔\n¥نماز نہ پڑھنے پر قرآنی وعیدیں:\nنماز نہ پڑھنے پر قرآنِ مجید میں وعیدیں بھی بیان ہوئی ہیں۔ چنانچہ ارشادِ باری تعالیٰ ہے: \nفَوَیْلٌ لِّلْمُصَلِّیْنَ(4)الَّذِیْنَ هُمْ عَنْ صَلَاتِهِمْ سَاهُوْنَ(5)\n (پ ۳۰، الماعون: ۴، ۵) ترجمہ کنزالایمان: تو ان نمازیوں کی خرابی ہے جو اپنی نماز سے بھولے بیٹھے ہیں۔\nایک جگہ ارشاد ہوا:\nفَخَلَفَ مِنْۢ بَعْدِهِمْ خَلْفٌ اَضَاعُوا الصَّلٰوةَ وَ اتَّبَعُوا الشَّهَوٰتِ فَسَوْفَ یَلْقَوْنَ غَیًّا(59) \n(پ ۱۶، مریم: ۵۹) ترجمہ کنزالایمان: تو ان کے بعد ان کی جگہ وہ ناخلف آئے جنھوں نے نمازیں گنوائیں (ضائع کیں) اور اپنی خواہشوں کے پیچھے ہوئے تو عنقریب وہ دوزخ میں غَیّ کا جنگل پائیں گے۔\n اسی طرح احادیث مبارکہ میں بھی نماز پڑھنے کے فضائل اور نہ پڑھنے کی وعیدیں بیان ہوئی ہیں۔ چنانچہ \n¥نماز کی فضیلت پر احادیث مبارکہ:\nحضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’پانچ نمازیں اور جمعہ سے جمعہ تک اور رمضان سے رمضان تک ان تمام گناہوں کو مٹا دیتے ہیں، جو ان کے درمیان ہوں جب کہ کبائر سے بچا جائے۔‘‘(مسلم، کتاب الطھارة، باب الصلاة الخمس، ص۱۱۸، حدیث:۵۵۲) \n حضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بتاؤ تو کسی کے دروازہ پر نہر ہو وہ اس میں ہر روز پانچ بارغسل کرے کیا اس کے بدن پر میل رہ جائے گا؟‘‘ صحابَۂ کرام علیہمُ الرّضوان نے عرض کی: نہیں۔ ارشاد فرمایا: ’’یہی مثال پانچ نمازوں کی ہے کہ اللہ پاک ان کے سبب خطاؤں کو مٹا دیتا ہے۔‘‘ \n(مسلم، کتاب المساجد، باب المشی الی الصلاة …الخ، ص۲۶۳، حدیث:۱۵۲۲)\n¥نماز نہ پڑھنے کی مذمت پر احادیث مبارکہ:\n حضرت سیِّدُنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’قیامت کے دن بندے سے سب سے پہلے نماز کا حساب لیا جائے گا اگر یہ درست ہوئی تو باقی اعمال بھی ٹھیک رہیں گے اور یہ بگڑی تو سبھی بگڑے۔‘‘ (معجم اوسط، باب الالف، ۱/ ۵۰۴، حدیث: ۱۸۵۹)جبکہ ایک روایت میں ہے: ’’وہ خائب وخاسر ہوا۔‘‘\n(معجم اوسط، باب العین، ۳/ ۳۲، حدیث: ۳۷۸۲)\n اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ جس نے نماز پر محافظت (ہمیشگی اختیار) کی تو قیامت کے دن وہ نماز اس کے لئے نور، دلیل اور نجات ہو گی اور جس نے محافظت نہ کی اس کے لئے نہ نور ہے نہ دلیل اور نہ ہی نجات اور وہ قیامت کے دن قارون، فرعون، ہامان اور اُبی بن خلف کے ساتھ ہوگا ۔‘‘ (مسند احمد، مسند عبداللّٰہ بن عمرو، ۲/ ۵۷۴، حدیث: ۶۵۸۷)\n (نوٹ:نماز کے تفصیلی احکام کی معلومات کے لئے ’’بہار شریعت، جلد1، حصہ 3 ، 4اور نماز کے احکام و نماز کا طریقہ‘‘ نامی کتابوں کا مطالعہ کیجئے۔ )\nتیسرا رکن: ¥زکوٰۃ\n¥زکوٰۃ کی فرضیت، اہمیت اور فضیلت:\n جن پانچ چیزوں پر اسلام کی بنیاد ہے ان میں سے تیسری چیز زکوٰۃ ہے۔ قرآن وحدیث میں نماز کی طرح زکوٰۃ کی فضیلت واہمیت کو بھی بیان کیا گیا ہے۔ چنانچہ اللہ پاک کامیابی حاصل کرنے والے مؤمنین کی صفات بیان کرتے ہوئے ارشاد فرماتا ہے: ¥\nوَ الَّذِیْنَ هُمْ لِلزَّكٰوةِ فٰعِلُوْنَ(4) \n(پ ۱۸، المؤمنون: ۴) ترجمہ کنزالایمان: اور (مراد کو پہنچے) وہ کہ زکوٰۃ دینے کا کام کرتے ہیں۔\n ’’زکوٰۃ‘‘ کا معنیٰ ومفہوم:زکوٰۃ کے لغوی معنیٰ ہیں پاکی اور بڑھنا ربّ کریم ارشاد فرماتا ہے: ’’ قَدْ اَفْلَحَ مَنْ تَزَكّٰىۙ(۱۴) (پ ۳۰، الاعلٰی:۱۴ ، ترجمہ کنزالایمان:بےشک مراد کو پہنچا جو ستھرا ہوا)۔ ‘‘ چونکہ زکوٰۃ کی برکت سے نفْسِ انسانی بخل کے میل سے پاک و صاف ہوتا ہے، نیز اس کی وجہ سے مال میں برکت ہوتی ہے اس لئے اسے زکوٰۃ کہتے ہیں۔ زکوٰۃ کا سبب بڑھنے والا مال ہے۔ حق یہ ہے کہ زکوٰۃ کا اجمالی حکم ہجرت سے پہلے آیا اور اس کی تفصیل 11 ہجری میں بیان ہوئی ۔ (مراٰۃ المناجیح، 3/ 2 ، ملخصاً)\n زکوٰۃ کا شرعی معنیٰ: اللہ پاک کے لئے مال کے ایک حصہ کا جو شرع نے مقرر کیا ہے، مسلمان فقیر کو مالک کر دینے کا نام زکوٰۃ ہے اور وہ فقیر نہ ہاشمی ہو، نہ ہاشمی کا آزاد کردہ غلام اور اپنا نفع اُس سے بالکل جدا کرلے۔(تنویر الابصار، کتاب الزکاة، ۳/ ۲۰۳، ۲۰۶)\n زکوٰۃ کی فرضیت کا انکار کرنے کا حکم:زکوٰۃ فرض ہے، اُس کا منکر (انکار کرنے والا)کافر اور نہ دینے والا فاسق اور قتل کا مستحق اور ادا میں تاخیر کرنے والا گنہگار و مردودُ الشہادہ ہے۔(الفتاوی الھندیة، کتاب الزکاة، الباب الاول، ۱/ ۱۷۰)\n زکوٰۃ واجب ہونے کی شرائط: مسلمان ہونا، بالغ ہونا، عاقل ہونا، آزاد ہونا، مال بقدر نصاب ملک میں ہونا، پورے طور پر اس کا مالک ہو، نصاب کا دین(قرض) سے فارغ ہونا، نصاب حاجت اصلیہ سے فارغ ہو، مال نامی ہو یعنی بڑھنے والا خواہ حقیقتاً بڑھے یا حکماً، سال گزرنا۔(ماخوذ از بہار شریعت، حصہ 5، 1/ 875 تا 884)\n زکوٰۃ تین قسم کے مال پر ہے: ثمن یعنی سونا چاندی، مالِ تجارت اور سائمہ یعنی چرائی پر چھوٹے جانور۔ \n(بہار شریعت، حصہ 5، 1/ 882)\n¥زکوٰۃ کی فضیلت پر آیات مبارکہ:\n کئی آیاتِ مقدسہ میں زکوٰۃ دینے اور راہِ خدا میں مال خرچ کی فضیلت بیان فرمائی گئی ہے۔ چنانچہ ارشادِ باری تعالیٰ ہے: \nوَ مَاۤ اَنْفَقْتُمْ مِّنْ شَیْءٍ فَهُوَ یُخْلِفُهٗۚ-وَ هُوَ خَیْرُ الرّٰزِقِیْنَ(39)\n (پ ۲۲، سبا: ۳۹) ترجمہ کنزالایمان: اور جو چیز تم اللہ کی راہ میں خرچ کرو وہ اس کے بدلے اور دے گااور وہ سب سے بہتر رزق دینے والا ۔\n ایک مقام پر ارشاد ہوا:\nخُذْ مِنْ اَمْوَالِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَ تُزَكِّیْهِمْ بِهَا\n(پ ۱۱، التوبة: ۱۰۳) ترجمہ کنزالایمان: اے محبوب ان کے مال میں سے زکوٰۃ تحصیل (وصول) کروجس سے تم انھیں ستھرا اور پاکیزہ کر دو۔\n¥زکوٰۃ نہ دینے پر قرآنی وعیدیں:\n قرآنِ مجید میں زکوٰۃنہ دینے کی وعیدیں بھی بیان فرمائی ہیں۔ چنانچہ ارشادِ باری تعالیٰ ہے:\nوَ لَا یَحْسَبَنَّ الَّذِیْنَ یَبْخَلُوْنَ بِمَاۤ اٰتٰىهُمُ اللّٰهُ مِنْ فَضْلِهٖ هُوَ خَیْرًا لَّهُمْؕ-بَلْ هُوَ شَرٌّ لَّهُمْؕ-سَیُطَوَّقُوْنَ مَا بَخِلُوْا بِهٖ یَوْمَ الْقِیٰمَةِؕ- (پ ۴، اٰل عمرٰن: ۱۸۰) ترجمہ کنزالایمان: اور جو بخل کرتے ہیں اس چیز میں جو اللہ نے انہیں اپنے فضل سے دی ہرگز اسے اپنے لئے اچھا نہ سمجھیں بلکہ وہ ان کے لئے برا ہےعنقریب وہ جس میں بخل کیا تھا قیامت کے دن ان کے گلے کا طوق ہوگا۔\n ایک اور مقام پر فرمایا:\nوَ الَّذِیْنَ یَكْنِزُوْنَ الذَّهَبَ وَ الْفِضَّةَ وَ لَا یُنْفِقُوْنَهَا فِیْ سَبِیْلِ اللّٰهِۙ-فَبَشِّرْهُمْ بِعَذَابٍ اَلِیْمٍ(34)یَّوْمَ یُحْمٰى عَلَیْهَا فِیْ نَارِ جَهَنَّمَ فَتُكْوٰى بِهَا جِبَاهُهُمْ وَ جُنُوْبُهُمْ وَ ظُهُوْرُهُمْؕ-هٰذَا مَا كَنَزْتُمْ لِاَنْفُسِكُمْ فَذُوْقُوْا مَا كُنْتُمْ تَكْنِزُوْنَ(35) (پ ۱۰، التوبة: ۳۴، ۳۵) ترجمہ کنزالایمان: اور وہ کہ جوڑ کر رکھتے ہیں سونا اور چاندی اور اسے اللہ کی راہ میں خرچ نہیں کرتے انھیں خوش خبری سناؤ درد ناک عذاب کی جس دن وہ تپایا جائے گاجہنم کی آگ میں پھر اس سے داغیں گے ان کی پیشانیاں اور کروٹیں اور پیٹھیں یہ ہے وہ جو تم نے اپنے لئے جوڑ کر رکھا تھااب چکھو مزہ اس جوڑنے کا۔\n اس طرح احادیث طیبہ میں بھی زکوٰۃ دینے کی فضیلت اور نہ دینے پر وعیدیں بیان ہوئی ہیں۔ چنانچہ \n¥زکوٰۃ دینے کی فضیلت پر اَحادیث مبارکہ:\n حضرت سیِّدُنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اپنے مال کی زکوٰۃ نکال کہ وہ پاک کرنے والی ہے تجھے پاک کر دے گی۔‘‘ (مسند احمد، مسند انس بن مالک، ۴/ ۲۷۳، حدیث: ۱۲۳۹۷)\n حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’صدقہ دینے سے مال کم نہیں ہوتا۔‘‘ (مسلم، کتاب البر والصلة والادب، باب استحباب العفو والتواضع، ص۱۰۷۱، حدیث: ۶۵۹۲)\n حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’زکوٰۃ دے کر اپنے مالوں کو مضبوط قلعوں میں کر لو اور بیماروں کا علاج صدقہ سے کرو۔‘‘ (کتاب المراسیل لابی داود، باب فی الزکاة، ص۲۰۹)\n¥زکوٰۃ نہ دینے کی مذمت پر اَحادیث مبارکہ:\n امُّ المؤمنین حضرت سیِّدَتُنا عائشہ صدیقہ رضی اللہ عنہا سے مروی ہے کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’زکوٰۃ کسی مال میں نہ ملے گی مگر اسے ہلاک کر دے گی۔‘‘ (شعب الایمان، باب فی الزکاة، فصل فی الاستعفاف عن المسالة ، ۳/ ۲۷۳، حدیث: ۳۵۲۲) بعض ائمہ نے اس حدیث کےیہ معنیٰ بیان کئے ہیں کہ زکوٰۃ واجب ہوئی اور ادا نہ کی اور اپنے مال میں ملائے رہا تو یہ حرام اُس حلال کو ہلاک کر دے گا اور حضرت سیِّدُنا امام احمد بن حنبل رحمۃُ اللہ علیہ نے فرمایا : اس کے معنیٰ یہ ہیں کہ مال دار شخص مالِ زکوٰۃ لے تویہ مالِ زکوٰۃ اس کے مال کو ہلاک کر دے گا کہ زکوٰۃ تو فقیروں کے لئے ہے۔ یہ دونوں معنیٰ صحیح ہیں۔(الترغیب والترھیب، کتاب الصدقات، الترھیب من منع الزکاة، ۱/ ۳۰۹، حدیث: ۱۸)\n مسلمانوں کے دوسرے خلیفہ امیرالمؤمنین حضرت سیِّدُنا عُمَر فاروق اعظم رضی اللہ عنہ سے روایت ہے کہ رسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’خشکی وتری میں جو مال تلف ہوتا ہے وہ زکوٰۃ نہ دینے سے تلف ہوتا ہے۔‘‘\n(الترغیب والترھیب، کتاب الصدقات، الترھیب من منع الزکاة، ۱/ ۳۰۸، حدیث: ۱۶)\n حضرت سیِّدُنا بُریدہ رضی اللہ عنہ سے مروی ہے کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو قوم زکوٰۃ نہ دے گی اللہ پاک اسے قحط میں مبتلا فرمائے گا۔‘‘(معجم اوسط، ۳/ ۲۷۵، حدیث: ۴۵۷۷)\n (نوٹ: زکوٰۃ کے تفصیلی احکام کی معلومات کے لئے ’’بہار شریعت، جلد1، حصہ 5 اور فتاوی اہلسنت احکامِ زکوٰۃ‘‘کا مطالعہ کیجئے۔ )\nچوتھا رکن: ¥حج\n¥حج کی فرضیت، اہمیت اور فضیلت:\n جن پانچ چیزوں پر اسلام کی بنیاد ہے ان میں سے چوتھی چیز حج ہے۔نماز اور زکوٰۃ کی طرح حج کی فضیلت واہمیت بھی قرآن وحدیث میں بیان کی گئی ہے۔ چنانچہ اللہ پاک ارشاد فرماتا ہے:\nاِنَّ اَوَّلَ بَیْتٍ وُّضِعَ لِلنَّاسِ لَلَّذِیْ بِبَكَّةَ مُبٰرَكًا وَّ هُدًى لِّلْعٰلَمِیْنَ(96) فِیْهِ اٰیٰتٌۢ بَیِّنٰتٌ مَّقَامُ اِبْرٰهِیْمَ ﳛ وَ مَنْ دَخَلَهٗ كَانَ اٰمِنًاؕ-وَ لِلّٰهِ عَلَى النَّاسِ حِجُّ الْبَیْتِ مَنِ اسْتَطَاعَ اِلَیْهِ سَبِیْلًاؕ-وَ مَنْ كَفَرَ فَاِنَّ اللّٰهَ غَنِیٌّ عَنِ الْعٰلَمِیْنَ(97) \n(پ ۴، اٰل عمرٰن: ۹۶، ۹۷) ترجمہ کنزالایمان: بےشک سب میں پہلا گھر جو لوگوں کی عبادت کو مقرر ہوا وہ ہے جو مکہ میں ہے برکت والا اور سارے جہان کا راہنما اس میں کھلی نشانیاں ہیں ابراہیم کے کھڑے ہونے کی جگہ اور جو اس میں آئے امان میں ہو اور اللہ کے لئے لوگوں پر اس گھر کا حج کرنا ہے جو اس تک چل سکے اور جو منکر ہو تو اللہ سارے جہان سے بےپرواہ ہے۔\n ایک جگہ ارشاد ہوا:\nوَ اَتِمُّوا الْحَجَّ وَ الْعُمْرَةَ لِلّٰهِؕ- \n(پ ۲، البقرة: ۱۹۶) ترجمہ کنزالایمان: اور حج اور عمرہ اللہ کے لیے پورا کرو۔\n حج کا معنیٰ ومفہوم: حج کے معنیٰ ہیں قصد اور اِرادہ،عبادت کی نیت سے کعبہ شریف کا ارادہ کرنا حج ہے۔حج کا سبب کعبہ معظمہ ہے،کعبہ شریف سب سے پہلے فرشتوں نے بنایا بیْتُ المعمور کے مقابل، اسی کا نام فرشتوں کے ہاں ضراح تھا، آدم علیہِ السّلام کی پیدائش سے دو ہزار برس پہلے سے فر شتے اس کا حج کرتے تھے،پھر آدم علیہِ السّلام سے لے کر ہمارے حضور صلّی اللہ علیہ واٰلہٖ وسلّم تک صرف انبیائے کرام علیہمُ السّلام نے حج کعبہ کیا،کسی امت پر حج فرض نہ تھا۔(مراٰۃ المناجیح، 4/ 85 ، ملخصاً)\n حج کا شرعی معنیٰ: حج نام ہے احرام باندھ کر نویں ذی الحجہ کو عرفات میں ٹھہرنے اور کعبہ معظمہ کے طواف کا۔اس کے لئےخاص وقت مقرر ہے جس میں یہ افعال کئے جائیں تو حج ہے۔(بہار شریعت، حصہ6، 1/ 1035، 1036) \n حج کی فرضیت: حج 9 ہجری میں فرض ہوا اس کی فرضیت قطعی ہے، جو اس کی فرضیت کا انکار کرے کافر ہے۔ \n(بہار شریعت، حصہ6، 1/ 1035، 1036)\n حج کتنی بار فرض ہے:صاحِبِ استطاعت پر عُمْر بھر میں ایک مرتبہ حج کرنا فرض ہے نماز اور روزہ و زکوٰۃ کی طرح حج کی فرضیت بھی قطعی و یقینی ہے لہٰذا جو حج کی فرضیت کا انکار کرے وہ کافر ہے اور باوجود طاقت کے اس کا تارک فاسق ہے اور بِلاعُذْر حج میں تاخیر کرنے والا گناہگار اور مَردودُ ا لشَّہادۃ ہے۔ (منتخب حدیثیں، ص66)\n¥حج کی فضیلت پر احادیث مبارکہ:\n حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو حج کے لئے نکلا اور مر گیا تو قیامت تک اس کے لئے حج کرنے والے کا ثواب لکھا جائے گا اور جو عمرہ کے لئے نکلا اور مر گیا تواس کے لئے قیامت تک عمرہ کرنے والے کا ثواب لکھا جائے گا اور جو جہاد میں گیا اور مر گیا تو اس کے لئے قیامت تک غازی کا ثواب لکھا جائے گا۔‘‘(مسند ابی یعلی، مسند ابی ھریرة، ۵/ ۴۴۱، حدیث: ۶۳۲۷)\n حضرت سیِّدُنا عبد اللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ رسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’حج و عمرہ محتاجی اور گناہوں کو ایسے دور کرتے ہیں، جیسے بھٹّی لوہے، چاندی اور سونے کے میل کو دور کرتی ہے اور حج مبرور کا ثواب جنت ہی ہے۔‘‘(ترمذی، ابواب الحج، باب ماجاء فی ثواب الحج والعمرة، ۲/ ۲۱۸، حدیث: ۸۱۰)\n حضرت سیِّدُنا ابو موسیٰ اشعری رضی اللہ عنہ سے روایت ہے کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’حاجی اپنے گھر والوں میں سے 400 کی شفاعت کرے گا اور گناہوں سے ایسا نکل جائے گا جیسے اس دن کہ ماں کے پیٹ سے پیدا ہوا۔‘ ‘(مسند بزار، مسند ابی موسی اشعری، ۸/ ۱۶۹، حدیث: ۳۱۹۶)\n¥حج نہ کرنے پر وعید:\n حضرت سیِّدُنا ابو امامہ باہلی رضی اللہ عنہ سے مروی ہے کہ رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ جسے حج کرنے سے نہ تو حاجَتِ ظاہرہ مانع ہوئی، نہ ظالم بادشاہ اور نہ ہی کوئی ایسا مرض جو روک دے، پھر وہ بغیر حج کئے مرگیا تو چاہے یہودی ہو کر مرے یا نصرانی ہو کر ۔‘ ‘(دارمی، کتاب المناسک، باب من مات ولم یحج، ۲/ ۴۵، حدیث: ۱۷۸۵)\n (نوٹ: حج و عمرہ دونوں کے ہر ہر مسئلے میں بہت تفصیل ہے۔ اس کے لئے ’’بہار شریعت، جلد1، حصہ 6 اور رفیق الحرمین ومعتمرین‘‘ کا مطالعہ کیجئے ۔ )\nپانچواں رکن: ¥روزہ\n¥روزے کی فرضیت، اہمیت اور فضیلت:\n جن پانچ چیزوں پر اسلام کی بنیاد ہے ان میں سے پانچویں اور آخری چیز روزہ ہے۔نماز اور زکوٰۃ کی طرح روزوں کی فضیلت واہمیت بھی قرآن وحدیث میں بیان کی گئی ہے۔ چنانچہ اللہ پاک ارشاد فرماتا ہے:\nیٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا كُتِبَ عَلَیْكُمُ الصِّیَامُ كَمَا كُتِبَ عَلَى الَّذِیْنَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُوْنَ(183) \n(پ ۲، البقرة: ۱۸۳) ترجمہ کنزالایمان: اے ایمان والو تم پر روزے فرض کیے گئے جیسے اگلوں پر فرض ہوئے تھےکہ کہیں تمہیں پرہیزگاری ملے۔\n اور ارشاد فرماتا ہے:\nشَهْرُ رَمَضَانَ الَّذِیْۤ اُنْزِلَ فِیْهِ الْقُرْاٰنُ هُدًى لِّلنَّاسِ وَ بَیِّنٰتٍ مِّنَ الْهُدٰى وَ الْفُرْقَانِۚ-فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْیَصُمْهُؕ- \n(پ ۲، البقرة: ۱۸۵) ترجمہ کنزالایمان: رمضان کا مہینہ جس میں قرآن اترا لوگوں کے لیے ہدایت اور رہنمائی اور فیصلہ کی روشن باتیں تو تم میں جو کوئی یہ مہینہ پائے ضرور اس کے روزے رکھے۔\n روزے کا معنیٰ ومفہوم:’’صوم‘‘ کے لغوی معنیٰ ہیں باز رہنا ، رکے رہنا ، اللہ پاک قرآن مجید میں ارشاد فرماتا ہے:\nنَذَرْتُ لِلرَّحْمٰنِ صَوْمًا (پ ۱۶، مریم:۲۶ ، ترجمہ کنزالایمان:میں نے آج رحمٰن کا روزہ مانا ہے)۔ ‘‘ یعنی میں نے بات چیت سے باز رہنے کی نذر مانی ہے۔ (مراٰۃ المناجیح، 3/ 133 ، ملخصاً)\n روزے کا شرعی معنیٰ:روزہ عرفِ شرع میں مسلمان کا بہ نیَّتِ عبادت صبح صادق سے غروب آفتاب تک اپنے کو قصداً کھانے پینے جماع (ہم بستری) سے باز رکھناہے۔(الفتاوی الھندیة، کتاب الصوم، الباب الاول، ۱/ ۱۹۴)\n روزے کا منشا ہے: نفس کا زور توڑنا،دل میں صفائی پیدا کرنا فقرا اور مساکین کی موافقت کرنا،مساکین پر اپنے دل کو نرم بنانا۔مرقات میں ہے کہ حضرت یوسف علیہِ السّلام قحط کے زمانے میں پیٹ بھر کھانا نہ کھاتے تھے تاکہ بھوکوں، فاقہ مستوں کا حق نہ بھول جائیں۔(مراٰۃ المناجیح، 3/ 182 ملخصاً)\n روزے کی فرضیت:لمعات،مرقات اور درمختار وغیرہ میں ہے کہ 2 ہجری میں تبدیلی قبلہ کے ایک مہینے بعد ہجرت سے اٹھارھویں مہینے 10 شعبان کو روزے فرض ہوئے۔(مراٰۃ المناجیح، 3/ 182 ملخصاً) نماز وزکوٰۃ کی طرح روزے کی فرضیت کا انکار کرنے والا بھی کافر ہے۔ (ماخوذ از منتخب حدیثیں، ص66)\n¥ روزہ بہت عمدہ عبادت ہے، اس کی فضیلت میں بہت حدیثیں مروی ہیں۔ چنانچہ¥\nروزوں کی فضیلت پر احادیث مبارکہ:\n حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جب رمضان آتا ہے تو آسمان کے دروازے کھول دیئے جاتے ہیں۔‘‘\n(بخاری، کتاب الصوم،باب ھل یقال رمضان او شھررمضان… الخ، ۱/ ۶۲۶، حدیث: ۱۸۹۹)\n حضرت سیِّدُنا سہل بن سعد رضی اللہ عنہ سے روایت ہے کہ حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جنت کے آٹھ دروازے ہیں، ان میں ایک دروازے کا نام ریّان ہے، اس سے (جنت میں)وہی جائیں گے جو روزے رکھتے ہیں۔‘‘(بخاری، کتاب بدء الخلق، باب صفة ابواب الجنة، ۲/ ۳۹۴، حدیث: ۳۲۵۷)\n حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’روزہ سِپر (ڈھال) اور دوزخ سے حفاظت کا مضبوط قلعہ ہے۔‘‘\n(مسند احمد، مسند ابی ھریرہ، ۳/ ۳۶۷، حدیث: ۹۲۳۶)\n¥روزہ نہ رکھنے کی مذمت پر احادیث مبارکہ:\n¥ حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جس نے رَمضان کے ایک دن کا روزہ بغیر رُخصت وبغیر مرض اِفطار کیا (یعنی نہ رکھا)توزمانے بھر کا روزہ بھی اُس کی قضا نہیں ہوسکتا اگرچہ بعد میں رکھ بھی لے۔‘‘ (ترمذی، ابواب الصوم، باب ماجاء فی الافطار متعمدا، ۲/ ۱۷۵، حدیث: ۷۲۳)یعنی وہ فضیلت جو رمضان میں روزہ رکھنے کی تھی اب کسی طرح نہیں پاسکتا۔ (بہارِ شریعت، حصہ5، 1/ 985 ،ملخصاً)\n حضرت سیِّدُنا جابر بن عبد اللّٰہ رضی اللہ عنہ سے روایت ہے کہ اللہ پاک کے پیارے رسول صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جس نے ماہِ رَمضان کو پایا اورا س کے روزے نہ رکھے وہ شخص شقی (یعنی بد بخت) ہے، جس نے اپنے والدین یا کسی ایک کو پایا اور ان کے ساتھ اچھا سلوک نہ کیا وہ بھی بدبخت ہے اور جس کے پاس میرا ذِکر ہوا اور اُس نے مجھ پر دُرُود نہ پڑھا وہ بھی بدبخت ہے۔‘‘ (معجم اوسط، ۳/ ۶۲، حدیث: ۳۸۷۱)\n (نوٹ: روزے کے تفصیلی احکام کی معلومات کے لئے ’’بہار شریعت، جلد1، حصہ 5 اور فیضان رمضان ‘‘ کا مطالعہ کیجئے۔ )\n¥دعا:\nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6869, "bookId": 13, "volNo": "1", "hadithNo": 4, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "تخلیق انسانی کے مراحل", "arabic": "عَنْ اَبِيْ عَبْدِالرَّحْمٰنِ عَبْدِ اللهِ بْنِ مَسْعُوْدٍ رَضيَ اللهُ عَنْهُ قَالَ: حَدَّثَنَا رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ الصَّادِقُ الْمَصْدُوْقُ: ’’اِنَّ اَحَدَكُمْ يُجْمَعُ خَلْقُهٗ فِيْ بَطْنِ اُمِّهٖ اَرْبَعِيْنَ يَوْمًا ثُمَّ يَكُوْنُ عَلَقَةً مِّثْلَ ذٰلِكَ ثُمَّ يَكُوْنُ مُضْغَةً مِّثْلَ ذٰلِكَ ثُمَّ يُرْسَلُ الْمَلَكُ فَيَنْفُخُ فِيْهِ الرُّوْحَ وَيُؤْمَرُ بِاَرْبَعِ كَلِمَاتٍ: بِكَتْبِ رِزْقِهٖ وَاَجَلِهٖ وَعَمَلِهٖ وَشَقِيٌّ اَوْ سَعِيْدٌ. فَوَالَّذِيْ لَا اِلٰهَ غَيْرُهٗ اِنَّ اَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ اَهْلِ الْجَنَّةِ حَتّٰى مَا يَكُوْنُ بَيْنَهٗ وَبَيْنَهَا اِلَّا ذِرَاعٌ فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيَعْمَلُ بِعَمَلِ اَهْلِ النَّارِ فَيَدْخُلُهَا وَاِنَّ اَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ اَهْلِ النَّارِ حَتّٰى مَا يَكُونُ بَيْنَهٗ وَبَيْنَهَا اِلَّا ذِرَاعٌ فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيَعْمَلُ بِعَمَلِ اَهْلِ الْجَنَّةِ فَيَدْخُلُهَا.‘‘ (رَوَاهُ الْبُخَارِی وَمُسْلِمٌ)", "urdu": "ترجمہ:حضرت سیِّدُنا ابو عبدالرحمٰن عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ صادق ومصدوق(یعنی سچے اور تصدیق کئے ہوئے) نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے ہم سے بیان فرمایا: ’’تمہاری پیدائش (کے مادہ یعنی نطفہ) کو ماں کے پیٹ میں 40 دن تک جمع کیا جاتا ہے، پھر 40 دن جما ہوا خون، پھر40 دن تک مُضْغَہ (گوشت کے لوتھڑے) کی صورت میں رہتا ہے، پھر اللہ پاک اس کی طرف ایک فرشتہ بھیجتا ہے، وہ اس میں روح پھونکتا ہےاور اسے چارچیزیں لکھنے کا حکم دیتا ہے:اس کا عمل، اس کی موت کا وقت، اس کا رزق اور وہ نیک ہے یا بدبخت۔ پس اس کی قسم جس کے سوا کوئی معبود نہیں! بےشک تم میں سے کوئی جنتیوں جیسے عمل کرتا رہتا ہے یہاں تک کہ جنت اور اس کے درمیان ایک گز کا فاصلہ رہ جاتا ہے پس تقدیراس پر غالب آ جاتی ہے تو وہ جہنمیوں جیسے عمل کر کے جہنم میں داخل ہو جاتا ہے اور بےشک تم میں کوئی جہنمیوں جیسے عمل کرتا رہتا ہے یہاں تک کہ اس کے اور جہنم کے درمیان ایک گز کا فاصلہ رہ جاتا ہے پس تقدیر اس پرغالب آ جاتی ہے اور وہ جنتیوں جیسے عمل کرکے جنت میں داخل ہو جاتا ہے۔‘‘\n(بخاری، کتاب بدء الخلق، باب ذکر الملائکة، ۲/ ۳۸، حدیث:۳۲۰۸، بتغیر قلیل۔مسلم، كتاب القدر، باب کیفیة الخلق الادمی، ص ۱۰۹۰، حدیث:۶۷۲۳)", "roman": "Tarjuma: Hazrat Sayyiduna Abu Abdur Rahman Abdullah Ibn Mas'ood RadiyAllahu Anhu se Marwi hai ke Sadiq-o-Masdooq (yaani sacche aur tasdeeq kiye hue) Nabi Sallallahu Alaihi Wasallam ne hum se bayan farmaya: \"Tumhari paidaaish (ke maaddah yaani nutfah) ko maa ke pait mein 40 din tak jama kiya jata hai, phir 40 din jama hua khoon, phir 40 din tak mudghah (gosht ke lothray) ki soorat mein rehta hai, phir Allah Paak us ki taraf ek farishta bhejta hai, woh us mein rooh phoonkta hai aur use chaar cheezain likhne ka Hukm deta hai: Us ka amal, us ki maut ka waqt, us ka rizq aur woh nek hai ya badbakht. Pas us ki qasam jis ke siwa koi mabood nahi! Beshak tum mein se koi jannatiyon jaise amal karta rehta hai yahan tak ke jannat aur us ke darmiyan ek gaz ka faasla reh jata hai pas taqdeer us par ghalib aa jaati hai to woh jahannamiyon jaise amal kar ke jahannam mein daakhil ho jata hai aur beshak tum mein koi jahannamiyon jaise amal karta rehta hai yahan tak ke us ke aur jahannam ke darmiyan ek gaz ka faasla reh jata hai pas taqdeer us par ghalib aa jaati hai aur woh jannatiyon jaise amal karke jannat mein daakhil ho jata hai.\" (Bukhari, Kitaab Bad'il Khalq, Baab Zikr-il-Malaikah, 2/38, Hadees: 3208, ba-taghayyur-e-qaleel. Muslim, Kitaab-ul-Qadr, Baab Kaifiyyat-e-Khalq-il-Aadami, p. 1090, Hadees: 6723)", "explanation": "¥صادِق و مَصدُوق کسے کہتے ہیں؟\nمذکورہ حدیث شریف میں حضرت سیِّدُنا عبداللہ بن مسعود رضی اللہ عنہ نے حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم کے دو اوصاف ’’صادق و مصدوق‘‘ بیان فرمائے، ان کی وضاحت کرتے ہوئے مشہور شارح حدیث، حکیم الامت حضرت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں: ’’صادق وہ جس کے سارے اقوال سچے ہوں ، مصدوق وہ جس کے سارے اعمال سچے ہوں۔ یا صادق وہ جوہوش سنبھال کر سچ بولے اور مصدوق وہ جو پہلے ہی سے سچا ہو۔ یا صادق وہ جو واقع کے مطابق خبردے اور مصدوق وہ کہ جو وہ اپنی زبان مبارک سے کہہ دے واقعہ اُس کے مطابق ہوجائے۔ حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) میں یہ سارے اوصاف جمع ہیں۔(مراۃ المناجیح، 1/ 93)\n¥مختلف مراحل میں انسانی تخلیق کی حکمتیں : \n حدیث پاک کے شروع میں انسان کی تخلیق کے مختلف مراحل بیان کئے گئے ہیں جیسے: ’’ ماں کے پیٹ میں 40 دن تک نطفہ کی صورت میں، پھر 40 دن جما ہوا خون، پھر40 دن گوشت کا لوتھڑاوغیرہ اور پھر اس میں روح پھونکنے کا مرحلہ‘‘اتنے مراحل کیوں رکھے گئے ؟ حالانکہ اللہ پاک اس بات پر قادر ہے کہ آن کی آن میں انسان کو پیدا فرمادے۔ انسان کی اس مرحلہ وار تخلیق میں بےشمار حکمتیں ہیں۔ چنانچہ حضرت سیِّدُنا علامہ بدر الدین عینی رحمۃُ اللہ علیہ انسانی تخلیق کے ان مراحل کی حکمتیں بیان کرتے ہوئے فرماتے ہیں:’’ (1)… اگر اللہ پاک انسان کو یک دم پیدا کر دیتا تو اس میں اس کی ماں کے لئے بہت دشواری ہوتی کیونکہ وہ اس چیز کی عادی نہیں اور بسااوقات تو ماں کے ہلاک ہونے کا بھی اندیشہ ہوجاتا۔ اس لیے پہلے نطفہ بنایا، جب اسے اس کی عادت ہوگئی تو اسے جما ہوا خون کردیا ، پھر اس طرح مراحل طے کر کے بچہ مکمل کردیا۔ (2)… انسان کو مرحلہ وار پیدا کرنے میں اللہ پاک کی قدرت اور نعمت کا اظہار ہے تاکہ بندے اللہ پاک کی عبادت کریں اور اس کا شکر بجالائیں کہ اس نے کیسے کیسے مراحل سے گزار کر کتنی اچھی صورت میں پیدا فرما کر عقل ، فہم اور ذہانت و فطانت سے نوازا۔ (3)… اس میں لوگوں کو اس بات پر تنبیہ ہے کہ اللہ پاک کو حشر و نشر پرکمال قدرت حاصل ہے کہ جس طرح وہ انسان کو ایک بے قدرپانی سے پیدا کرنے پر قادر ہے اسی طرح وہ مر کر مٹی بن جانے والے انسان کو دوبارہ اُٹھانے اور حشر میں اس سے حساب و کتاب لینے پر بھی قادر ہے ۔‘‘ (عمدة القاری، کتاب بدء الخلق ، باب ذکر الملائکة، ۱۰ / ۵۷۱ ، تحت الحدیث: ۳۲۰۸)\n40¥ میں انقلاب ہے:\n صوفیائے کرام فرماتے ہیں:چونکہ آدم علیہِ السّلام کا خمیر چالیس سال اورموسیٰ علیہِ السّلام کا قیام طور پر چالیس دن رہا، اس لیئے نطفہ پر ہرچلہ (40 دن)کے بعد انقلاب آتا ہے،پھر بعد پیدائش نِفاس کی مدت چالیس دن ہے،کمالِ عقل چالیس سال میں ہوتا ہے۔(مراۃ المناجیح، 1/ 93)\n¥کاتِبِ تقدیر فرشتے کا علم:\n حدیث پاک میں ہے کہ ’’پھر اس کی طرف ایک فرشتے کو بھیجا جاتا ہے اور اسے چار چیزیں لکھنے کا حکم دیا جاتا ہے: اس کا عمل، اس کی موت کا وقت، اس کا رزق اور وہ نیک ہے یا بدبخت‘‘یعنی کاتبِ تقدیر فرشتہ جو رحموں پرمتعین ہے ایک ہی فرشتہ جو سارے عالَم کی حاملہ عورتوں کا نگران ہے۔ معلوم ہوا کہ وہ حاضروناظرہے۔(اسے بھیجا جاتا ہے اور وہ لکھتا ہے)کہ یہ کیا کرے گا،کب اور کہاں مرے گا،کیا کیا کھائے گا اور کیا پیئے گا،اس کا خاتمہ کفر پر ہوگا،یا ایمان پر۔ خیال رہے کہ یہ چیزیں ان علوم خمسہ (پانچ علوم) میں سے ہیں جس کے بارے میں فرمایا گیا:’’ وَ عِنْدَهٗ مَفَاتِحُ الْغَیْبِ (پ ۷، الانعام:۵۹ ، ترجمہ کنزالایمان:اور اسی کے پاس ہیں کنجیاں غیب کی)۔ ‘‘یہ (کاتب تقدیر)فرشتہ بتعلیم الٰہی (اللہ پاک کی عطا سے)سارے انسانوں کی یہ ساری چیزیں جانتا ہے۔مرقاۃ میں ہے کہ یہ باتیں ایک تختی پرلکھ کر بچے کے گلے میں ڈال دیتا ہے ربِّ کریم ارشاد فرماتا ہے:’’ وَ كُلَّ اِنْسَانٍ اَلْزَمْنٰهُ طٰٓىٕرَهٗ فِیْ عُنُقِهٖؕ- (پ ۱۵، بنی اسرائیل:۱۳ ، ترجمہ کنزالایمان:اور ہر انسان کی قسمت ہم نے اس کے گلے سے لگا دی ہے)۔ ‘‘غور کرو جب اُس فرشتے کا اس قدر علم ہے تو ہمارے نبی صلّی اللہ علیہ واٰلہٖ وسلّم جو اعلَمُ الخلق (مخلوق میں سب سے زیادہ علم والے) ہیں ان کا علم تو ہمارے خیالات سے ورا ہے اور یہ تختی پر لکھنا اور گلے میں ڈالنا اسی لئےہے کہ حقیقت میں نگاہیں اسے پڑھ سکیں۔خیال رہے کہ تحریر لوح محفوظ میں بھی ہوتی ہے اور شب قدر میں فرشتوں کے صحائف میں بھی ہے اور بچے کی پیشانی یا گلے کی تختی یا ہاتھ میں بھی ہے مگر یہ تحریر مختلف ہیں۔(مراۃ المناجیح، 1/ 93،ملخصاً)\n انسانی تخلیق کے ان مراحل کو اللہ پاک نے قرآنِ مجید میں بھی بیان فرمایا ہے۔ چنانچہ ارشاد باری تعالیٰ ہے: \nوَ لَقَدْ خَلَقْنَا الْاِنْسَانَ مِنْ سُلٰلَةٍ مِّنْ طِیْنٍ(12)ثُمَّ جَعَلْنٰهُ نُطْفَةً فِیْ قَرَارٍ مَّـكِیْنٍ(13) ثُمَّ خَلَقْنَا النُّطْفَةَ عَلَقَةً فَخَلَقْنَا الْعَلَقَةَ مُضْغَةً فَخَلَقْنَا الْمُضْغَةَ عِظٰمًا فَكَسَوْنَا الْعِظٰمَ لَحْمًاۗ-ثُمَّ اَنْشَاْنٰهُ خَلْقًا اٰخَرَؕ-فَتَبٰرَكَ اللّٰهُ اَحْسَنُ الْخٰلِقِیْنَﭤ(14) ثُمَّ اِنَّكُمْ بَعْدَ ذٰلِكَ لَمَیِّتُوْنَﭤ(15)ثُمَّ اِنَّكُمْ یَوْمَ الْقِیٰمَةِ تُبْعَثُوْنَ(16) (پ ۱۸، المؤمنون: ۱۲ تا ۱۶) ترجمہ کنزالایمان: اور بےشک ہم نے آدمی کو چنی ہوئی مٹی سے بنایا پھر اُسے پانی کی بوند کیا ایک مضبوط ٹھہراؤ میں پھر ہم نے اس پانی کی بوند کو خون کی پھٹک کیا پھر خون کی پھٹک کو گوشت کی بوٹی پھر گوشت کی بوٹی کو ہڈیاں پھر اُن ہڈیوں پر گوشت پہنایا پھر اسے اور صورت میں اُٹھان دی تو بڑی برکت والا ہے اللہ سب سے بہتر بنانے والا ہے پھر اُس کے بعد تم ضرور مرنے والے ہو پھر تم سب قیامت کے دن اُٹھائے جاؤ گے۔\n¥انسان کی پیدائش میں چار طریقے اختیار فرمائے گئے :\n مذکورہ حدیث شریف اور آیاتِ طیبہ میں انسان کی پیدائش کے مراحل کا بیان ہے۔ مزید یہ کہ خلّاقِ عالَم جَلَّ جَلَالُہ نے انسانوں کو چار طریقوں سے پیدا فرمایا ہے: (1)… مرد وعورت دونوں کے ملاپ سے، جیساکہ عام طور پر انسانوں کی پیدائش ہوتی ہے۔ چنانچہ قرآنِ مجید میں صاف صاف اعلان ہے :\nاِنَّا خَلَقْنَا الْاِنْسَانَ مِنْ نُّطْفَةٍ اَمْشَاجٍ ﳓ (پ ۲۹، الدھر: ۲) ترجمہ کنزالایمان: بےشک ہم نے آدمی کو پیدا کیا ملی ہوئی منی سے۔\n(2)… تنہا مرد سے ایک انسان پیدا ہو: اور وہ حضرت حواء رضی اللہ عنہا ہیں کہ اللہ پاک نے ان کو حضرت آدم علیہِ السّلام کی بائیں (الٹی جانب کی)پسلی سے پیدا فرمادیا۔(3)… تنہا ایک عورت سے ایک انسان پیدا ہو:اور وہ حضرت عیسیٰ علیہِ السّلام ہیں جو کہ پاک دامن کنواری بی بی مریم رحمۃُ اللہ علیہا کے شکم سے بغیر باپ کے پیدا ہوئے۔(4)… بغیر مرد و عورت کے بھی ایک انسان کو خداوند ِ قدوس نے پیدا فرما دیا اور وہ انسان حضرت آدم علیہِ السّلام ہیں کہ اللہ پاک نے ان کو مٹی سے بنا دیا۔\nان واقعات سے مندرجہ ذیل اسباق کی طرف راہنمائی ہوتی ہے کہ خداوند ِ قدوس ایسا قادر و قیّوم اور خلاّق(پیدا کرنے والا) ہے کہ انسانوں کو کسی خاص ایک ہی طریقے سے پیدا فرمانے کا پابند نہیں ہے، بلکہ وہ ایسی عظیم قدرت والا ہے کہ وہ جس طرح چاہے انسانوں کو پیدا فرما دے۔ چنانچہ مذکورہ بالا چار طریقوں سے اس نے انسانوں کو پیدا فرمادیا۔ جو اس کی قدرت و حکمت اور اس کی عظیم الشان خلاّقیت کا نشانِ اعظم ہے۔سُبْحٰنَ اللہ! خداوند ِ قدوس کی شانِ خالقیت کی عظمت کا کیا کہنا؟ جس خلّاقِ عالَم نے کرسی و عرش اور لوح و قلم اور زمین و آسمان کو ’’کُن‘‘ فرما کر موجود فرما دیا اس کی قدرتِ کاملہ اور حکمَتِ بالِغَہ کے حضور خلقَتِ انسانی کی بھلا حقیقت و حیثیت ہی کیا ہے۔ لیکن اس میں کوئی شک نہیں کہ تخلیْقِ انسان اس قادر مطلق کا وہ تخلیقی شاہکار ہے کہ کائناتِ عالَم میں اس کی کوئی مثال نہیں۔ کیونکہ وجودِ انسان عالَمِ خلق کی تمام مخلوقات کے نمونوں کا ایک جامع مُرقَّع ہے۔ اللہ اَکْبَر!کیا خوب ارشاد فرمایا مولائے کائنات حضرت علی مرتضیٰ رضی اللہ عنہ نے کہ\nاَتَحْسِبُ اِنَّکَ جِرْمٌ صَغِیْرٌ وَّفِیْکَ اِنْـطَوَی الْعَالَمُ الْاَکْبَرُ\n¥ترجمہ: اے انسان! کیا تو یہ گمان کرتا ہے کہ تو ایک چھوٹا سا جسم ہے؟ حالانکہ تیری عظمت کا یہ حال ہے کہ تیرے اندر عالَمِ اکبر سمٹا ہوا ہے۔\nممکن تھا کہ کوئی مرد یہ خیال کرتا کہ اگر ہم مردوں کی جماعت نہ ہوتی تو تنہا عورتوں سے کوئی انسان پیدا نہیں ہو سکتا تھا۔ اسی طرح ممکن تھا کہ عورتوں کو یہ گمان ہوتا کہ اگر ہم عورتیں نہ ہوتیں تو تنہا مردوں سے کوئی انسان پیدا نہ ہوتا۔ اسی طرح ممکن تھا کہ عورت و مرد دونوں مل کر یہ ناز کرتے کہ اگر ہم مردوں اور عورتوں کا وجود نہ ہوتا تو کوئی انسان پیدا نہیں ہوسکتا تھا تو اللہ پاک نے چاروں طریقوں سے انسانوں کو پیدا فرما کر عورتوں اور مردوں دونوں کا منہ بند کردیا کہ دیکھ لو، ہم ایسے قادر و قیّوم ہیں کہ حضرت حواء رضی اللہ عنہا کو تنہا مرد یعنی حضرت آدم علیہِ السّلام کی پسلی سے پیدا فرما دیا۔ لہٰذا اے عورتو! تم یہ گمان مت رکھو کہ اگر عورتیں نہ ہوتیں تو کوئی انسان پیدا نہ ہوتا۔ اسی طرح حضرت عیسیٰ علیہِ السّلام کو تنہا عورت کے شکم سے بغیر مرد کے پیدا فرما کر مردوں کو تنبیہ فرما دی کہ اے مردو! تم یہ ناز نہ کرو کہ اگر تم نہ ہوتے تو انسانوں کی پیدائش نہیں ہو سکتی تھی۔ دیکھ لو! ہم نے حضرت عیسیٰ علیہِ السّلام کو تنہا عورت کے شکم سے بغیر مرد کے پیدا فرمادیا اور حضرت آدم علیہِ السّلام کو بغیر مرد و عورت کے مٹی سے پیدا فرما کر عورتوں اور مردوں کا منہ بند فرمادیا کہ اے عورتو اور مردو! تم کبھی بھی اپنے دل میں خیال نہ لانا کہ اگر ہم دونوں نہ ہوتے تو انسانوں کی جماعت پیدا نہیں ہو سکتی تھی۔ دیکھ لو!حضرت آدم علیہِ السّلام کے نہ باپ ہیں نہ ماں، بلکہ ہم نے ان کو مٹی سے پیدا فرمادیا۔سُبْحٰن اللہ!سچ فرمایا اللہ جَلَّ جَلَالُہ نے کہ\nاللّٰهُ خَالِقُ كُلِّ شَیْءٍ وَّ هُوَ الْوَاحِدُ الْقَهَّارُ(16) (پ ۱۳، الرعد: ۱۶) ترجمہ کنزالایمان: اللہ ہر چیز کا بنانے والا ہے اور وہ اکیلا سب پر غالب ہے۔\nوہ جس کو چاہے اور جیسے چاہے اور جب چاہے پیدا فرما دیتا ہے۔ اس کے افعال اور اس کی قدرت کسی اسباب و علل، اور کسی خاص طور طریقوں کی بندشوں کے محتاج نہیں ہیں۔(عجائب القرآن مع غرائب القرآن، ص243،ملخصاً)\n¥تقدیرِ اِلٰہی سے متعلق اہم وضاحت : \nمذکورہ حدیث پاک میں تقدیر کے متعلق بیان ہوا کہ ’’بندہ جنتیوں جیسے اعمال کرتا ہے لیکن اس کا خاتمہ جہنمیوں والے اعمال پر ہوتا ہے اور اسی طرح کوئی بندہ جہنمیوں جیسے اعمال کرتا ہے لیکن اس کا خاتمہ جنتیوں جیسے اعمال پر ہوتا ہے‘‘اس سے ایک سوال ذہن میں آتا ہے کہ جب اللہ پاک نے سب کی تقدیر پہلے ہی سے لکھ دی ہے کہ کون خوش بخت ہے اور کون بدبخت، کون جنتی ہے اور کون جہنمی تو پھر یہ سزا و جزا کا معاملہ کیوں رکھاگیا؟اس کا جواب یہ ہے کہ تقدیر کا معاملہ ایسا نہیں ہے کہ جو اللہ پاک نے لکھ دیا ہے وہی ہمیں کرنا پڑتا ہے۔ ایسا ہرگز نہیں ، بلکہ اس دنیا میں آکر جس نے جو کرنا تھا اللہ پاک نے اپنے عِلمِ اَزَلی سے جان لیا اور وہی لکھ دیا ۔ چنانچہ صدرُالشریعہ، بدرُالطریقہ حضرت علامہ مولانا مفتی محمد امجد علی اعظمی رحمۃُ اللہ علیہ فرماتے ہیں: ’’ہر بھلائی ، بُرائی اُس (یعنی اللہ پاک)نے اپنے عِلمِ اَزَلی کے موافق مقدّر فرما دی ہے ، جیسا ہونے والا تھا اورجو جیسا کرنے والا تھا ، اپنے علم سے جانا اور وہی لکھ لیا تو یہ نہیں کہ جیسا اُس نے لکھ دیا ویسا ہم کو کرنا پڑتا ہے ، بلکہ جیسا ہم کرنے والے تھے ، ویسا اُس نے لکھ دیا ۔ زید کے ذِمّہ بُرائی لکھی اس لیے کہ زید برائی کرنے والا تھا ، اگر زید بھلائی کرنے والا ہوتا وہ اُس کے لیے بھلائی لکھتا تو اُس کے علم یا اُس کے لکھ دینے نے کسی کو مجبور نہیں کر دیا۔‘‘ (بہار شریعت، حصہ1، 1/ 11)\n¥خوف اور امید کے درمیان رہو:\nحدیث شریف کے آخر میں ’’انسان کے اچھے اور برے خاتمے کا بیان ہے‘‘لہٰذا مؤمن کو ہر وقت اپنے خاتمہ کے لیے ڈرتے رہنا چاہئے، نیز جو نیک اعمال کرے اسے فخر نہیں کرناچاہیے کہ کہیں ایسا نہ ہو کہ ساری زندگی نیک اعمال کرے اور آخری ایام میں نیکیوں کو چھوڑ کر گناہوں بھرے کام کر کے جہنم میں داخل ہوجائے ۔ چنانچہ مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں:’’( کوئی) ایمان لاکر متقی بن کے مرتا ہے، لہٰذا کوئی بدکار ربِّ کریم سے مایوس نہ ہو اور کوئی نیک کار اپنے تقویٰ پرفخر نہ کرے۔ اللہ پاک اچھا خاتمہ نصیب فرمائے(آمین)۔ (مراٰۃ المناجیح، 1/ 93،ملخصاً)\n¥دعا:\nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6870, "bookId": 13, "volNo": "1", "hadithNo": 5, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "بُری بدعات کا رد", "arabic": "عَنْ اُمِّ الْمُؤمِنِيْنَ اُمِّ عَبْدِ اللهِ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُوْلُ اللهِ: ’’مَنْ اَحْدَثَ فِيْ اَمْرِنَا هٰذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ. ‘‘ (رَوَاهُ الْبُخَارِی وَمُسْلِمٌ) وَفِيْ رِوَايَةٍ لِمُسْلِمٍ: ’’مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ اَمْرُنَا فَهُوَ رَدٌّ.‘‘", "urdu": "اُمِّ عبداللہ اُمُّ المؤمنین حضرت سیِّدَتُنا عائشہ صدیقہ رضی اللہ عنہا فرماتی ہیں کہ رسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے اِرشاد فرمایا: ’’ جس نے ہمارے دین میں کوئی ایسی چیز ایجادکی جو ہمارے دین سے نہیں تو وہ مردود ہے۔ ‘‘\n (بخاری، کتاب الصلح، باب اذا اصطلحوا علی صلح جور...الخ، ۲/ ۲۱۱، حدیث:۲۶۹۷، ’’منہ‘‘ بدلہ ’’فیہ‘‘ ۔ مسلم، كتاب الاقضية، باب نقض الاحكام الباطلة...الخ،ص۷۳۱، حدیث:۴۴۹۲)\n مسلم شریف کی ایک روایت میں ہے: ”جس نے کوئی ایسا عمل کیا جوہمارے دین سے نہیں تو اس کا وہ عمل مردود ہے۔‘‘\n(مسلم، كتاب الاقضية، باب نقض الاحكام الباطلة...الخ،ص ۷۳۱، حدیث: ۴۴۹۳)", "roman": "Umm-e-Abdullah Umm-ul-Momineen Hazrat Sayyidatuna Aisha Siddiqah Radiyallahu Anha farmati hain ke Rasool-e-Akram Sallallahu Alaihi Wasallam ne irshad farmaya: \"Jis ne hamare deen mein koi aisi cheez ijaad ki jo hamare deen se nahi to woh mardood hai.\" (Bukhari, Kitaab-us-Sulh, Baab Iza Istalahoo Ala Sulhin Jaور... ilkh, 2/211, Hadees: 2697, \"Minhu\" badle \"Feehi\". Muslim, Kitaab-ul-Aqdiyah, Baab Naqd-il-Ahkam-il-Baatilah... ilkh, p. 731, Hadees: 4492). Muslim shareef ki ek Riwayat mein hai: \"Jis ne koi aisa amal kiya jo hamare deen se nahi to us ka woh amal mardood hai.\" (Muslim, Kitaab-ul-Aqdiyah, Baab Naqd-il-Ahkam-il-Baatilah... ilkh, p. 731, Hadees: 4493)", "explanation": "¥مذکورہ حدیث پاک کی اہمیت:\nحضرت علامہ ابو زکریا یحییٰ بن شرف نووی رحمۃُ اللہ علیہ فرماتے ہیں: ’’یہ حدیث قواعدِ اسلامیہ میں سے ایک بہت بڑا قاعدہ اور جوامِعُ الکلم میں سے ہے۔ نیز اس میں تمام اختراعات و بدعاتِ سیئہ کا واضح رد ہے۔‘‘ مزید فرماتے ہیں: ’’اس حدیث کو یاد رکھنا، منکرات (ممنوعاتِ شرعِیَّہ) کے بُطلان میں اسے استعمال کرنا اور اس کی خوب تشہیر کرنی چاہئے۔‘‘\n(شرح مسلم للنووی،کتاب الاقضیة، باب نقض الاحکام الباطلة...الخ، الجزء الثانی عشر، ۶‏ / ۱۶)\nحافظ اِبْنِ حجر عسقلانی رحمۃُ اللہ علیہ فرماتے ہیں : ’’اس حدیث کو اصولِ دین میں شمار کیا جاتا ہے اور یہ قَوَاعِد (اِسلامِیَّہ) میں سے ایک قاعدہ ہے۔‘‘ علامہ طوفی رحمۃُ اللہ علیہ فرماتے ہیں: ’’اس حدیث کو اَدِلَّۂ شَرْعِیَّہ کا نصف کہنا بالکل درست ہے۔‘‘\n(دلیل الفالحین، باب فی النھی عن البدع ومحدثات الامور، ۱/ ۴۴۰، تحت الحدیث:۱۷۰)\n¥باطل عقائد اور اعمال:\nمشہور شارح حدیث، حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ اس حدیث پاک کی شرح فرماتے ہیں: وہ ایجاد کرنے والا مردود ہے یا اس کی یہ ایجاد مردود ہے۔خیال رہے کہ (حدیث شریف میں موجود لفظ) اَمر سے مراد دیْنِ اسلام ہے اور مَا سے مراد عقائد،یعنی جو شخص اسلام میں خلافِ اسلام عقیدے ایجاد کرے وہ شخص بھی مردود اور وہ عقائد بھی باطل۔ لہٰذا روافض، قادیانی وغیرہ بہتّر(72) فرقے جن کے عقائد خلافِ اسلام ہیں باطل ہیں۔یا (لفظ) اَمر سے مراد دین ہے اور مَا سے مراد اعمال ہیں اور لَیْسَ مِنْہُ سے مراد قرآن و حدیث کے مخالف،یعنی جو کوئی دین میں ایسے عمل ایجاد کرے جودین،یعنی کتاب و سنت کے مخالف ہوں جس سے سنّت اٹھ جاتی ہو وہ ایجاد کرنے والا بھی مردود، ایسے عمل بھی باطل جیسے اردو میں خطبہ و نماز پڑھنا،فارسی میں اذان دینا وغیرہ۔اس کی تفسیر وہ حدیث ہے جو آگےآرہی ہے کہ جو کوئی بدعَت ایجاد کرے تو اللہ پاک سنت کو اٹھالیتا ہے۔ اس تفسیر کی بنا پر یہ حدیث اپنے عموم پر ہے اس میں کوئی قید لگانے کی ضرورت نہیں۔ (صاحب)مرقاۃ نے فرمایا: لَیْسَ مِنْہُ سے معلوم ہوا کہ دین میں ایسے کام کی ایجاد جو کتاب و سنّت کے خلاف نہ ہو بُری نہیں۔(مراٰۃ المناجیح، 1/ 138)\n¥بدعت کی تعریف، اقسام اور ان کی مثالیں:\nحکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں کہ بدعت کے لغوی معنیٰ ہیں: نئی چیز۔ قرآنِ کریم (میں اللہ پاک ارشاد)فرماتاہے: قُلْ مَا كُنْتُ بِدْعًا مِّنَ الرُّسُلِ (پ ۲۶، الاحقاف:۹ ) فرمادو کہ میں نیا رسول نہیں ہوں۔ ‘‘ نیز فرماتا ہے: بَدِیْعُ السَّمٰوٰتِ وَ الْاَرْضِؕ- (پ ۱، البقرة:۱۱۷ ) آسمانوں اور زمین کا ایجاد کرنے والا۔ ‘‘ نیز فرماتا ہے: وَ رَهْبَانِیَّةَ-ﰳابْتَدَعُوْهَا مَا كَتَبْنٰهَا عَلَیْهِمْ (پ ۲۷، الحدید:۲۷ ) (اور راہب بننا تو یہ بات انہوں نے دین میں اپنی طرف سے نکالی ہم نے ان پر مقرر نہ کی تھی)۔ ‘‘ان آیات میں بدعت لغوی معنیٰ میں استعمال ہوا ہے یعنی ایجاد کرنا، نیا بنانا وغیرہ۔اور بدعت کے شرعی معنیٰ ہیں: ’’وہ اِعتقاد یا وہ اعمال جو کہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم کی ظاہری حیات کے زمانہ میں نہ ہوں بعد میں اِیجاد ہوئے ہوں۔ ‘‘\n صاحب مرقات فرماتے ہیں: بدعت وہ کام ہے جو بغیر گزری مثال کے کیا جائے (یعنی حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم اور صحابَۂ کرام علیہمُ الرّضوان کے زمانہ میں اس کی مثال موجود نہ ہو)۔ اب بدعت تین معنیٰ میں استعمال ہوتا ہے:پہلا معنیٰ:نیا کام جو حضور انور صلّی اللہ علیہ واٰلہٖ وسلّم کے بعد ایجاد ہوا۔دوسرا معنیٰ:خلاف سنت کام جو دافع سنت ہو (یعنی جس سے کوئی سنت مٹ جائے)۔ تیسرا معنیٰ:برے عقائد جو بعد میں پیدا ہوئے۔ پہلے معنیٰ سے بدعت کی دو قسمیں ہیں: (1)…بدعَتِ حسنہ (یعنی اچھی بدعت)۔ (2)…بدعَتِ سیئہ (یعنی بری بدعت)۔دوسرے معنیٰ کے اعتبار سے ہر بدعت سیئہ (بری) ہی ہے جن بزرگوں نے فرمایا کہ ہر بدعت سیئہ ہوتی ہے وہاں دوسرے معنیٰ مراد ہیں وہ جو حدیث میں ہے کہ ’’ہربدعت گمراہی ہے۔‘‘ وہاں تیسرے معنیٰ مراد ہیں، لہٰذا احادیث واقوالِ علما میں تعارض نہیں۔\n¥تفصیل:\nبدعَتِ شرعی دو طرح کی ہوئی: (1)…بدعَتِ اعتقادی اور (2)…بدعَتِ عملی۔بدعت اعتقادی: ان برے عقائد کو کہتے ہیں جو حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم کے بعد اسلام میں ایجاد ہوئے۔جیسے: جبریہ، قَدَرِیَّہ، مُرجِیَہ، چکڑالوی، غیر مُقَلّد وغیرہ بدمذہب گروہوں کے بعض عقائد بدعَتِ اِعتقادیہ ہیں۔ کیونکہ یہ سب بعد کو بنے اور یہ لوگ ان کو اسلامی عقائد سمجھتے ہیں۔ مثلاً: ان میں سے کسی کا یہ عقیدہ ہے کہ خدا جُھوٹ پر قادر ہے، حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم مطلقًا غیب نہیں جانتے، حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم کا خیال نماز میں بیل گدھے کے خیال سے بدتر ہے مَعَاذ اللہ۔یہ تمام ناپاک عقیدے بارہویں صدی کی پیداوار ہیں، حضور پاک صلّی اللہ علیہ واٰلہٖ وسلّم کے زمانے میں بالکل نہ تھے۔ اسی طرح بدعت عملی: ہر وہ کام ہے جو حضور پرنور صلّی اللہ علیہ واٰلہٖ وسلّم کے زمانہ پاک کے بعد ایجاد ہوا خواہ وہ دنیاوی ہو یا دینی، خواہ صحابَۂ کرام علیہمُ الرّضوان کے زمانہ میں ہو یا اس کے بھی بعد۔ البتہ عُرفِ عام میں صحابَۂ کرام علیہمُ الرّضوان کی اِیجادات کو سنت صحابہ کہتے ہیں بدعت نہیں بولتے یہ عُرف ہے۔ ‘‘ پھر بدعَتِ عملی کی دوقسمیں ہیں: (1)…بدعَتِ حسنہ اور (2)…بدعَتِ سیئہ۔ بدعَتِ حسنہ: وہ نیا کام جو کسی سنت کے خلاف نہ ہو۔جیسے دینی مدارس اور نئے نئے عمدہ کھانے اور پریس میں قرآن ودینی کتب کا چھپوانا وغیرہ۔ بدعَتِ سیئہ: وہ کہ جو کسی سنت کے خلاف ہو یا سنت کو مٹانے والی ہو۔ جیسے کہ غیر عربی میں جمعہ وعیدین کا خطبہ پڑھنا ۔ بدعَتِ حسنہ جائز بلکہ بعض وقت مستحب اور واجب بھی ہے اور بدعَتِ سیئہ مکروہ تنزیہی یا مکروہ تحریمی یا حرام ہوتی ہے۔\n¥خلاصَۂ کلام:\n بدعَتِ حسنہ کی تین قسمیں ہیں: جائز، مُسْتَحَب، واجب اور بدعَتِ سیئہ کی دو قسمیں ہیں: مکروہ اور حرام۔ بدعت کی یہ کل پانچ اقسام ہوئیں: (1)…جائز، (2)…مستحب، (3)… واجب، (4)…مکروہ اور (5)…حرام۔\nجائز: ہر وہ نیا کام جو شریعت میں منع نہ ہو اور بغیر کسی نیت خیر کے کیا جائے۔ جیسے انواع اقسام کے کھانے کھانا وغیرہ۔ ان کاموں پر نہ ثواب نہ عذاب۔\nمستحب: وہ نیا کام جو شریعت میں منع نہ ہو اور اس کو عام مسلمان کارِ ثواب جانتے ہوں یا کوئی شخص اس کو نیَتِ خیر سے کرے۔ جیسے محفل میلاد شریف اور فاتحہ بزرگانِ دین کہ عام مسلمان اس کو کارِ ثواب جانتے ہیں۔ اس کو کرنے والا ثواب پائے گا اور نہ کرنے والا گناہ گار نہیں ہوگا۔\nواجب: وہ نیا کام جو شرعاً منع نہ ہو اور اس کے چھوڑنے سے دین میں حرج واقع ہو۔ جیسے کہ قرآن کے اعراب اور دینی مدارس اور علْمِ نحو وغیرہ پڑھنا۔\nمکروہ: وہ نیا کام جس سے کوئی سنت چھوٹ جائے۔ اگر سنت غیر مؤکّدہ چھوٹی تو یہ بدعت مکروہ تنزیہی ہے اور اگر سنت مؤکّدہ چھوٹی تو یہ بدعت مکروہ تحریمی۔\nحرام: وہ نیا کام جس سے کوئی واجب چھوٹ جائے یعنی (وہ بدعت)واجب کو مٹانے والی ہو۔ (جاء الحق، ص177 تا 183 ، ملخصاً)\n¥اعتراض اور اس کا جواب:\n کسی کے ذہن میں یہ اعتراض آسکتا ہے کہ حدیث پاک میں تو اس طرح کی کوئی تفصیل بیان نہیں کہ بدعت کی اتنی قسمیں ہیں اور بدعت اچھی بھی ہوتی ہے اور بُری بھی۔ اس کا جواب یہ ہے کہ ایک دوسری حدیث شریف میں اچھی اور بری بدعت کی تقسیم بیان کی گئی ہے۔ چنانچہ \n مروی ہے کہ اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’مَنْ سَنَّ فِي الْاِسْلَامِ سُنَّةً حَسَنَةً فَلَهٗ اَجْرُهَا وَاَجْرُ مَنْ عَمِلَ بِهَا بَعْدَهٗ مِنْ غَيْر اَنْ يَّنْقُصَ مِنْ اُجُوْرِهِمْ شَيْءٌ وَّمَنْ سَنَّ فِي الْاِسْلَامِ سُنَّةً سَيِّئَةً كَانَ عَلَيْهِ وِزْرُهَا وَوِزْرُ مَنْ عَمِلَ بِهَا مِنْ بَعْدِهٖ مِنْ غَيْرِ اَنْ يَّنْقُصَ مِنْ اَوْزَارِهِمْ شَيْءٌ یعنی جس نے اسلام میں اچھا طریقہ ایجاد کیا تو اس کے لئے اس کا اجر تو ہے ہی لیکن بعد میں جو اس اچھے طریقے پر عمل کرے اس کا ثواب بھی اسے ملے گا اور ان کے ثواب میں بھی کوئی کمی نہیں ہوگی اور جس نے اسلام میں کوئی برا طریقہ ایجاد کیا تو اس پر اس کا گناہ تو ہے لیکن بعد میں جوبھی اس برے طریقے پر عمل کرے گا اس کا گناہ بھی ایجاد کرنے والے کو ملے گا اور ان کے گناہوں میں بھی کچھ کمی نہ ہوگی۔‘‘\n(مسلم،کتاب العلم، باب الحث علی الصدقة ولوبشق تمرة...الخ، ص۳۹۴، حدیث:۲۳۵۱)\n (نوٹ: بدعت کے بارے میں تفصیلی معلومات کے لئے مایہ ناز تصنیف ’’جاء الحق‘‘ سے ’’بدعت کی بحث، معنیٰ، اقسام اور احکام‘‘\nاور ’’فیضان ریاض الصالحین (جلد:02)‘‘ صفحہ 577 تا 588‘‘ کا مطالعہ کیجئے۔ )\n¥دعا:\nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6871, "bookId": 13, "volNo": "1", "hadithNo": 6, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "حلال بھی واضح ہے اور حرام بھی", "arabic": "عَنْ اَبِيْ عَبْدِ اللهِ النُّعْمَانِ بْنِ بَشِيْرٍ رَضيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُوْلُ:’’ اِنَّ الْحَلَالَ بَيِّنٌ وَّاِنَّ الْحَرَامَ بَيِّنٌ وَّبَيْنَهُمَا مُشْتَبِهَاتٌ لَّا يَعْلَمُهُنَّ كَثِيْرٌ مِّنَ النَّاسِ فَمَنِ اتَّقَى الشُّبُهَاتِ اِسْتَبْرَاَ لِدِيْـنِهٖ وعِرْضِهٖ وَمَنْ وَّقَعَ فِي الشُّبُهَاتِ وَقَعَ فِي الْحَرَامِ كَالرَّاعِيْ يَرْعٰى حَوْلَ الْحِمٰى يُوشِكُ اَنْ يَرْتَعَ فِيْهِ اَلَا وَاِنَّ لِكُلِّ مَلِكٍ حِمًى. اَلَا وَاِنَّ حِمَى اللهِ مَحَارِمُهٗ اَلَا وَاِنَّ فِي الْجَسَدِ مُضْغَةً اِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهٗ وَاِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهٗ اَلَا وَهِيَ الْقَلْبُ.‘‘ (رَوَاهُ الْبُخَارِی وَمُسْلِمٌ)", "urdu": "حضرت سیِّدُنا نعمان بن بشیر رضی اللہ عنہ بیان کرتے ہیں: میں نے رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم کو ارشاد فرماتے سناکہ ’’ بے شک حلال ظاہر ہے اورحرام بھی ظاہرہےاوراُن کے درمیا ن مشکوک چیزیں ہیں جنہیں بہت سے لوگ نہیں جانتے ۔تو جو ان مشکوک چیزوں سے بچا اس نے اپنا دِین اور اپنی عزت محفوظ کرلی اور جوان مشکوک چیزوں میں پڑ ا وہ حرام میں پڑ گیا ۔جیسے وہ چرواہا جو ممنوعہ چراہ گا ہ کے قریب بکریاں چَراتاہو توقریب ہے کہ وہ جانورا س چراہ گاہ میں بھی چرنے لگیں۔ خبردار! ہر بادشا ہ کی ممنوعہ چراہ گاہ ہوتی ہے اور اللہ پاک کی ممنوعہ چراہ گاہ اس کی حرام کردہ اَشیاء ہیں۔خبرادر!جسم میں گوشت کا ایک ٹکڑاہے جب وہ ٹھیک ہوجائے تو سارا جسم ٹھیک ہوجاتا ہے اور اگر وہ خراب ہوجائے تو سا را جسم خراب ہو جاتاہے۔ سنو! وہ ٹکڑا دل ہے۔‘‘ (بخاری، کتاب الایمان، باب فضل من استبرأ لدینہ، ۱/ ۳۳، حدیث:۵۲، بتغیر قلیل ۔ مسلم، كتاب المساقاة، باب اخذ الحلال وترك الشبهات،ص ۶۶۳، حدیث:۴۰۹۴)", "roman": "Hazrat Sayyiduna Nu'man bin Basheer RadiyAllahu Anhu bayan karte hain: Main ne Rasool-e-Paak Sallallahu Alaihi Wasallam ko irshad farmate suna ke \"Beshak Halal zahir hai aur Haram bhi zahir hai aur un ke darmiyan mashkook cheezain hain jinhein bohat se log nahi jaante. To jo un mashkook cheezon se bacha us ne apna deen aur apni izzat mehfooz kar li aur jo un mashkook cheezon mein pada woh Haram mein pad gaya. Jaise woh charwaha jo mamnoo'ah charagah ke qareeb bakriyan charata ho to qareeb hai ke woh janwar us charagah mein bhi charne lagein. Khabardar! Har badshah ki mamnoo'ah charagah hoti hai aur Allah Paak ki mamnoo'ah charagah us ki Haram kardah ashya hain. Khabardar! Jism mein gosht ka ek tukda hai jab woh theek ho jaye to sara jism theek ho jata hai aur agar woh kharab ho jaye to sara jism kharab ho jata hai. Suno! Woh tukda dil hai.\" (Bukhari, Kitaab-ul-Iman, Baab Fazl Man Istabra-a Li-Deenihi, 1/33, Hadees: 52, ba-taghayyur-e-qaleel. Muslim, Kitaab-ul-Musaqaat, Baab Akhz-il-Halal wa Tark-ish-Shubuhaat, p. 663, Hadees: 4094)", "explanation": "¥مذکورہ حدیث پاک کی اہمیت:\n یہ حدیْثِ پاک بھی اُن اَحادیْثِ کریمہ میں سے ایک ہے جنہیں اِسلام کا مَدار قرار دیا گیا ہے۔ چنانچہ حضرت سیِّدُنا امام ابو داود رحمۃُ اللہ علیہ فرماتے ہیں کہ انسان کو اپنے دین کے لئے چار حدیثیں کافی ہیں۔ پھر آپ نے وہ چاروں حدیثیں بیان فرمائیں۔ مذکورہ حدیث شریف بھی ان میں سے ایک ہے۔(ارشاد الساری، کتاب الوحی، باب کیف کان بدء الوحی، ۱/ ۹۵، تحت الحدیث:۱)\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں:یہ حدیث اصل اصولِ دین (اصول دین کی اصل) ہے۔( مراٰۃ المناجیح،4/ 229)\n حضرت سیِّدُنا امام اعظم ابوحنیفہ رحمۃُ اللہ علیہ نے اپنے صاحبزادے حضرت حماد رحمۃُ اللہ علیہ کو 20 باتوں کی نصیحت فرمائی، انیسویں یہ تھی کہ میں نے پانچ لاکھ حدیثوں میں سے پانچ حدیثیں منتخب کی ہیں ان پر اعتماد کرنا۔ مذکورہ حدیث پاک بھی ان پانچ میں سے ایک ہے۔ (ماخوذ از بشیر القاری، ص65)\n¥مذکورہ حدیث پاک کا مطلب ومفہوم: \n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ اس حدیث شریف کی شرح میں فرماتے ہیں: اس کا مطلب یہ ہے کہ چیزیں تین قسم کی ہیں:بالکل حلال جن کی حِلَّت منصوص (قرآن وحدیث سے ثابت)ہے۔ بالکل حرام جن کی حُرمت مَنصوص ہے، جیسے محرمات و فَوَاحِش۔ اورمُشتبہات جن میں حلت و حرمت کے دلائل مُتعارض ہیں یا حلت و حرمت کی دلیل نہیں۔ اصْلِ حلال پر عمل کرو،اصْلِ حرام سے ضروربچواورمُشتبہات سے احتیاطًا پرہیزکرو کہ شاید حرام ہوں۔ مگر جن میں حِلَّت (حلال ہونے) کی اصل موجود ہو وہ مشتبہ نہیں،انہیں حرام سمجھنا محض باطل وہم ہے۔ جوشخص مشتبہات سے پرہیز نہ کرے گا وہ آخر کار محرمات میں بھی پھنس جائے گااس لئے مشتبہات سے بچو۔ شاہی چراگاہ میں جانورچَرانا سخت جرم ہوتا ہے ۔ہوشیار چرواہے شاہی چراگاہ سے دور ہی رہتے ہیں تاکہ کوئی جانوربے قابو ہوکر اس چراگاہ میں نہ گھس جائےاور ہم مجرم ہوجائیں،مگر بے احتیاط چرواہے وہاں قریب پہنچ جاتے ہیں اورآخرکاران کا جانور وہاں گھس جاتا ہے اور یہ مجرم ہوکرپکڑ ے جاتے ہیں۔ایسے ہی مُشتبہات میں واقع ہونے والا کبھی حرام میں بھی گرفتار ہوجائے گا۔ تم چرواہے ہو،نفس بے سمجھ جانور،محرماتِ شرعیہ شاہی چراگاہ ہے، مشتبہات اس چراگاہ کے مُتَّصِل زمین (لہٰذا ان سے بچو)۔ (مراٰۃ المناجیح، 4/ 229)\n¥دل کی اصلاح ضروری ہے:\n مفتی صاحب مزید حدیث شریف کے جز ’’ جسم میں گوشت کا ایک ٹکڑاہے‘‘ کے تحت فرماتے ہیں: دِل بادشاہ ہےجسم اس کی رعایاجیسے بادشاہ کے درست ہوجانے سے تمام ملک ٹھیک ہوجاتا ہے ایسے ہی دل سنبھل جانے سے تمام جسم ٹھیک ہوجاتا ہے۔ دل ارادہ کرتا ہے جسم اس پر عمل کی کوشش ۔ دل میں بُرے ارادے نہ پیدا ہوں اس لیے صوفیائے کرام ( رحمۃُ اللہ علیہم ) دل کی اصلاح پر بہت زور دیتے ہیں۔صوفیاء ( رحمۃُ اللہ علیہم ) فرماتے ہیں کہ دل کو اپنی منزلوں میں رکھو، اس کی منزل فرض، واجب، سنت، مستحب، آداب، مباح ہیں،اِن حدود میں رہا تو خیر ہے، اگلی منزلیں خطرناک ہیں اُدھر نہ جانے دو، اگلی منزلیں مکروہِ تنزیہی، مکروہِ تحریمی، حرام و کفر ہیں۔ مکروہِ تنزیہی سے بچاؤ تاکہ آگے بڑھنے کی ہمت نہ کرے۔( مراٰۃ المناجیح،4/230)\n¥راہِ نجات:\n حضرت سیّدناسہل بن عبداللہ رحمۃ اللہ علیہ نے فرمایا کہ ”نجات تین چیزوں میں ہے: (1) حلا ل کھانے میں، (2) فرائض کی ادائیگی میں اور (3) حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم کی سنتوں کی اتباع میں۔“( تفسیر قرطبی، پ۲، بقرة، ۱۶۸، الجزء الثانی، ۱/ ۱۵۹)\n¥حلال رزق کی تلاش فرض ہے:\n حضرت سیِّدُنا عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم کا فرمانِ عالیشان ہے: ’’طَلَبُ الْحَلَالِ فَرِیْضَۃٌ عَلٰی کُلِّ مُسْلِم یعنی رزقِ حلال حاصل کرنا ہر مسلمان پر فرض ہے۔‘‘\n (معجم اوسط، ۶/ ۲۳۱، حدیث: ۸۶۱۰۔ معجم کبیر، ۱۰/ ۷۴، حدیث: ۹۹۹۳ بتغیر قلیل) \n¥مشکل سے سمجھ میں آنے والا فرض:\n حضرت سیِّدُنا امام غزالی رحمۃُ اللہ علیہ فرماتے ہیں: تمام فرائض میں سے یہ (یعنی رزقِ حلال کاحصول) ایسا فرض ہے جس کا سمجھنا عقلوں کے لئے بہت دشوار اور اس کا بجالانا اعضاء پر بہت بھاری ہے۔یہی وجہ ہے کہ اس کا علم حاصل کرنا اور اس پر عمل کرنا بالکل ختم ہو چکا ہےاوراس پر عمل کے ختم ہونے کا سبب اس کے علم کا پیچیدہ ہونا ہےکیونکہ جاہل لوگ یہ گمان کرتے ہیں کہ ’’حلال چیز حاصل کرنا مفقود ہو گیا اور اس تک پہنچنے کے تمام راستے بند ہو گئے اور نہروں کے پانی اور بنجر وویران زمین میں اگنے والی گھاس کے علاوہ کوئی حلال چیز باقی نہیں رہی اور اس کے علاوہ جوکچھ ہے اسے ظالموں نے خراب اور بُرے معاملات نے فاسد کردیا۔پس جب زمینی پیداوار میں گھاس پر قناعت کرنا مشکل ہو گیا تو حرام کے اِرتکاب کے سوا کوئی چارہ نہ رہا (لیکن یہ جاہلوں کا گمان ہے عقلمند اس سوچ سے دور ہیں) ۔ ‘‘(احیاء علوم الدین، کتاب الحلال والحرام، ۲/ ۱۱۲)\n¥حلال وحرام سے متعلق آیات مبارکہ:\nاللہ پاک حلال وپاک چیزیں کھانے کے متعلق ارشاد فرماتاہے:\nكُلُوْا مِنَ الطَّیِّبٰتِ وَ اعْمَلُوْا صَالِحًاؕ- (پ ۱۸، المؤمنون: ۵۱) ترجمہ کنزالایمان: پاکیزہ چیزیں کھاؤ اور اچھا کام کرو۔\n اس آیت طیبہ میں اللہ پاک نے اعمال بجالانے سے پہلے پاکیزہ چیزیں کھانے کا حکم دیا ہےاور کہا گیا ہے کہ یہاں\n ’’ الطَّیِّبٰتِ ‘‘ سے مراد حلال چیزیں ہیں۔\n اور حرام وناحق طریقے سے مال کھانے کی مذمت بیان کرتے ہوئے ارشاد فرمایا:\nوَ لَا تَاْكُلُوْۤا اَمْوَالَكُمْ بَیْنَكُمْ بِالْبَاطِلِ\n(پ ۲، البقرة: ۱۸۸) ترجمہ کنزالایمان: اور آپس میں ایک دوسرے کا مال ناحق نہ کھاؤ۔\n اور یتیم کا مال کھانے کی مذمت بیان کرتے ہوئے ارشاد فرمایا:\nاِنَّ الَّذِیْنَ یَاْكُلُوْنَ اَمْوَالَ الْیَتٰمٰى ظُلْمًا اِنَّمَا یَاْكُلُوْنَ فِیْ بُطُوْنِهِمْ نَارًاؕ-وَ سَیَصْلَوْنَ سَعِیْرًا(10) \n(پ ۴، النسآء: ۱۰) ترجمہ کنزالایمان: وہ جو یتیموں کا مال ناحق کھاتے ہیں وہ تو اپنے پیٹ میں نِری آگ بھرتے ہیں اور کوئی دم جاتا ہے کہ بھڑکتے دھڑے (بھڑکتی آگ) میں جائیں گے۔\n¥ ان کے علاوہ دیگر آیات میں بھی حرام مال کے وبال ونحوست کو بیان کیا گیا ہے بالخصوص سود کی حرمت ومذمت کو وضاحت کے ساتھ بیان کیا گیا ہے۔ اسی طرح احادیث مبارکہ میں بھی حلال کی فضیلت اور حرام کی مذمت کو بیان کیا گیا ہے۔ چنانچہ \n¥حلال وحرام سے متعلق احادیث مبارکہ:\n حضرت سیِّدُناسعد بن ابی وقاص رضی اللہ عنہ نے بارگاہِ رسالت میں عرض کی:آپ بارگاہِ الٰہی میں دعا کیجئے کہ”وہ مجھے مُسْتَجَابُ الدَّعْوَات(یعنی جس کی دعائیں قبول ہوں)بنادے۔“توآپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اپنے کھانے کو پاکیزہ بناؤتمہاری دعائیں قبول ہوں گی۔‘‘ (معجم اوسط، ۵/ ۳۴، حدیث:۶۴۹۵)\n اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے دنیا پر مر مٹنے والے کا ذکر کیا تو ارشاد فرمایا: بعض اوقات ایسا ہوتا ہے کہ بکھرے بال، گرد آلود چہرے اور سفر کی مشقت برداشت کرنے والا شخص اپنے ہاتھ اٹھاتا اور دعا کرتا ہے: ’’اے میرے رب! اے میرے رب!‘‘ اس کی دعا کیسے قبول کی جائے گی؟ جبکہ اس کا کھانا حرام، لباس حرام اور غذا حرام ہے۔\n(مسلم، کتاب الزکاة، باب قبول الصدقة من الکسب الطیب وتربیتها، ص۳۹۳، حدیث: ۲۳۴۶)\n اللہ پاک کے پیارے رسول صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ ہروہ گوشت(یعنی جسم) جوحرام سے پروان چڑھے آگ اس کی زیادہ حقدار ہے ۔‘‘(ترمذی، کتاب السفر، باب ما ذکر فی فضل الصلاة، ۲/ ۱۱۸، حدیث: ۶۱۴)\n¥دعا:\nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6872, "bookId": 13, "volNo": "1", "hadithNo": 7, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "دین خیرخواہی کا نام ہے", "arabic": "عَنْ اَبِيْ رُقَيَّةَ تَمِيْمِ بْنِ اَوْسٍ الدَّارِيِّ رَضيَ اللهُ عَنْهُ اَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’اَلدِّيْنُ النَّصِيْحَةُ.‘‘ قُلْنَا: لِمَنْ؟ قَالَ: ’’لِلّٰهِ وَلِكِتَابِهٖ وَلِرَسُوْلِهٖ وَلِاَئِمَّةِ الْمُسْلِمِيْنَ وَعَامَّتِهِمْ.‘‘ (رَوَاہُ مُسْلِم)", "urdu": "حضرت سیِّدُنا ابو رقیہ تمیم بن اوس داری رضی اللہ عنہ سے روایت ہے کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’دین خیر خواہی ہے۔‘‘ ہم نے عرض کی: کس کے لئے؟ ارشاد فرمایا: ’’اللہ پاک کےلئے، اس کی کتاب کے لئے، اس کے رسول کے لئے، مسلمانوں کے ائمہ اور عام مسلمانوں کے لئے۔‘‘\n(مسلم، كتاب الایمان، باب بیان ان الدین النصیحة، ص ۵۱، حدیث:۱۹۶)", "roman": "Hazrat Sayyiduna Abu Ruqayyah Tameem bin Aus Daari RadiyAllahu Anhu se Riwayat hai ke Rasool-e-Paak Sallallahu Alaihi Wasallam ne irshad farmaya: \"Deen khair khwahi hai.\" Hum ne arz ki: Kis ke liye? Irshad farmaya: \"Allah Paak ke liye, us ki Kitaab ke liye, us ke Rasool ke liye, Musalmanon ke a'immah aur aam Musalmanon ke liye.\" (Muslim, Kitaab-ul-Iman, Baab Bayan Anna Ad-Deena An-Naseehah, p. 51, Hadees: 196)", "explanation": "¥مذکورہ حدیث پاک کی اہمیت:\n خیال رہے! حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم کو اللہ پاک کی طرف سے عطا کئے گئے بےشمار معجزات میں ایک معجزہ\n ’’جوامع الکلم‘‘ کا بھی عطا ہوا کہ ’’مختصر جملہ میں لمبی چوڑی بات کو بیان فرما دیا کرتے تھے۔ (سیرت مصطفیٰ، ص589) مذکورہ حدیث پاک بھی ان احادیث میں شمار کی جاتی ہے جن کو ’’جوامع الکلم‘‘ کہا جاتا ہے یعنی وہ احادیث جن کے الفاظ تو بہت کم ہوتے ہیں لیکن علم وحکمت کے کثیر موتی ان میں موجود ہوتے ہیں۔ چنانچہ حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں: یہ (حدیث پاک) بھی جامع کلمات میں سے ہے کہ ایک لفظ میں لاکھوں چیزیں شامل ہیں۔ (مراٰۃ المناجیح، 6/ 557)\n¥نصیحت کا معنیٰ ومفہوم:\n نصیحت بنا ہے نصح سے بمعنیٰ خالص ہونا، (اہل)عرب کہتے ہیں: ’’نَصَحْتُ الْعَسْلَ عَنِ الشَّمْعِ (یعنی)میں نے شہد کو موم سے خالص کرلیا۔‘‘ اصطلاح میں کسی کی خالص خیر خواہی کرنا جس میں بدخواہی کا شائبہ نہ ہو یا خلوصِ دل سے کسی کا بھلا چاہنا نصیحت ہے۔ حتّٰی کہ اعتقاد کو کفر سے خالص کرنا،عبادات کو ریا سے پاک و صاف کرنا، معاملات کو خرابیوں سے بچانا سب ہی نصیحت میں داخل ہیں۔ (مراٰۃ المناجیح، 6/ 557)\n¥نصیحت کی علامتیں:\nحضرت علامہ شاہ کرمانی رحمۃُ اللہ علیہ فرماتے ہیں کہ’’نصیحت کی تین علامات ہیں: (1)…مسلمانوں کے مَصائب پر دلی طور پر دکھی وغمزدہ ہو۔ (2)… اُن کی خیر خواہی کی کوشش کرے اور (3)… بہتری کے کاموں کی طرف اُن کی رہنمائی کرے اگر چہ وہ اس کو ناپسند کریں اور اس سے ناواقِف ہوں۔ (دلیل الفالحین، باب فی النصیحة، ۱/ ۴۶۰)\n¥اللہ پاک کے لئے نصیحت کا معنیٰ: \n سیِّدُنا امام ابو زکریا یحییٰ بن شرف نووی رحمۃُ اللہ علیہ ’’شرح صحیح مسلم‘‘ میں مذکورہ حدیث پاک کی شرح میں فرماتے ہیں: (دین کا) اللہ پاک کے لئے خیر خواہی ہونے سے مراد یہ ہےکہ اللہ پاک کی ذات پہ ایمان رکھنا، اُس سے شرک کی نفی کرنا، اُس کی صفات كو عيب سے پاک ماننا، اسے کمال اور بزرگی کی صفات سے متصف ماننا، تمام عیوب سے پاک ماننا، اس کی فرمانبرداری کرنا اورنافرمانی سے بچنا،اسی کے لئے محبت اور اسی کے لئے دشمنی رکھنا، اس کے فرمانبرداروں سے محبت اور نافرمانوں سے عداوت رکھنا، جو اس ذات ِباری تعالیٰ کا انکار کرے اس سے جہاد کرنا، اس کی نعمتوں کا اِعتراف اور اُن پر شکر بجا لانا، سچے دل سے اِن تمام اُمور کو ماننا، مذکورہ تمام اَوصاف کی طرف لوگوں کو دعوت دینا، اُن پر اُبھارنااور تمام لوگوں سے حتی الامکان نرمی کا برتاؤ کرنا۔\n¥کتابُ اللہ کے لئے نصیحت کا معنیٰ: \n (دِین کا) کتابُ اللہ کے لئے خیر خواہی ہونے سے مراد یہ ہے کہ اِس بات پر ایمان لانا کہ بے شک یہ اللہ پاک کا کلام ہے، اسی کا نازل کردہ ہے، مخلوق میں سے کسی کا کلام اس کے مشابہ نہیں ، نہ ہی مخلو ق میں سے کوئی اس جیسا کلام لانے پر قادر ہے، کتابُ اللہ کی تعظیم کرنا، کما حقہ اس کی تلاوت کرنا،اسے خوبصورت بنانا،جو کچھ اس میں ہے اس کی تصدیق کرنا، اس کے احکام پر عمل کرنا، اس کے علوم و امثال کو سمجھنا، اس کےعجائبات میں غور و فکر کرنا، احکام والی آیات پر عمل کرنا، متشابہ آیات پر ایمان رکھنا، اُس کےعموم وخصوص اور ناسخ و منسوخ سے بحث کرنا،اس کے علوم کو پھیلانا اورقرآن اور اُس کی نصیحتوں کی جانب لوگوں کو بلانا ۔\n¥رسولُ اللہ صلّی اللہ علیہ وسلّم ¥ کے لئے نصیحت کا معنیٰ: \n (دِین کے) حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم کے لئے خیر خواہی ہونے سے مراد یہ ہے کہ آپ صلّی اللہ علیہ واٰلہٖ وسلّم کی رسالت کی تصدیق کرنا اور جو کچھ آپ لے کر آئے ہیں اُس پر ایمان لانا،جس چیز کا حکم دیں اُس پر عمل کرنا اور جس چیز سے منع کریں اُس سے باز رہنا، حیاتِ ظاہری میں اور اُس کے بعدآپ صلّی اللہ علیہ واٰلہٖ وسلّم کی مدد کرنا،آپ کے دشمنوں سے دشمنی اور دوستوں سے دوستی رکھنا، آپ کے حق کا لحاظ رکھنا، آپ کاادب واحترام اور تعظیم وتوقیربجالانا، آپ صلّی اللہ علیہ واٰلہٖ وسلّم کے طریقے و سنت کو زندہ کرنا، آپ کی دعوت اور شریعت کو پھیلانا،آپ کی شریعت سے تہمت کی نفی کرنا، شریعت کے علوم سے فائدہ حاصل کرنا، اُس کے معانی میں گہری سمجھ بوجھ حاصل کرنا، لوگوں کو اُس کی طرف بلانا، اُس کے سیکھنے سیکھانے، تعظیم و بزرگی میں نرم رویہ اختیار کرنا، اِن علوم کو پڑھتے وقت اُن کے اَدب کا خیال رکھنا، اگر علم نہ ہو تو اُس کے بارے میں کلام کرنے سے رکنا، آپ صلّی اللہ علیہ واٰلہٖ وسلّم کی نسبت کی وجہ سے اہل بیت کا احترام کرنا،آپ کے اَخلاق و آداب کو اپنانا،اَہْلِ بیت اور صحابَۂ کرام علیہمُ الرّضوان سے محبت کرنا،اُن لوگوں سے بُغض رکھنا جو سنت میں کوئی نئی وبُری چیز اِیجاد کریں یا صحابَۂ کرام علیہمُ الرّضوان میں سے کسی ایک صحابی سے بھی اِعراض کریں۔\n¥اَئِمَّۂ مسلمین کے لئے نصیحت کا معنیٰ: \n (دِین کے) اَئِمَّۂ مسلمین کے لئے خیر خواہی ہونے سے مراد یہ ہے کہ حق پر اُن کی مدد کرنا، حق بات میں اُن کی اطاعت کرنا، اُن کے حکم کو ماننا، نرمی کے ساتھ اُن کو تنبیہ کرنا اور ڈرانا، وہ جس چیز سے غافل ہوں اُس کی انہیں خبر دینا،انہیں مسلمانوں کے وہ حقوق یاد دلانا جن سے وہ بے خبر ہوں، اُن کے خلاف بغاوت نہ کرنا، لوگوں کے دلوں کو اُن کی اطاعت کے لئے نرم کر نا، اُن کے پیچھے نماز پڑھنا، جہاد میں اُن کا ساتھ دینا اور اُن کو صدقات اَدا کرنا۔ یہ تمام معاملات اُسی صورت میں ہیں جب کہ اَئِمَّۂ مسلمین یا تو خلفاء ہوں یا قوم کے خیرخواہ حکمران ہو ں۔ نیز اَئِمَّۂ مسلمین سے مُراد علمائے دین بھی ہوتے ہیں تو اُن کے ساتھ خیر خواہی کا مطلب یہ ہے کہ جو وہ بیان کریں اُسے قبول کیا جائے اور اَحکام میں اُن کی تقلید یعنی پیروی کی جائے اور اُن کے ساتھ حُسنِ ظن رکھاجائے۔\n¥عام مسلمانوں کے لئے نصیحت کا معنیٰ: \n (دِین کے) عام مسلمانوں کے لئے خیر خواہی ہونے سے مراد یہ ہے کہ دُنیوی و اُخروی معاملات میں اُن کی رہنمائی کرنا، اُن کی تکالیف کو دُور کرنا، دِین کے بارے میں جوبات وہ نہیں جانتے اُنہیں سکھانا، قول و فعل سے اُن کی مدد کرنا، اُن کے عیبوں کو چھپانا، اُن کی ضرورت کو پورا کرنا، تکلیف دہ چیز کو اُن سے دُور کرنا، نفع دینے والی چیزوں کو اُن کے قریب کرنا، اِخلاص اور نرمی کے ساتھ اُنہیں بھلائی کا حکم دینااور بُرائی سے روکنا، اُن پر شفقت کرنا، اُن کے بڑوں کی عزت اور چھوٹوں پر شفقت کرنا، انہیں اچھی نصیحت کرنا، اُنہیں دھوکا نہ دینا، ان سے حسد نہ کرنا، بھلائی میں سے جو اپنے لئے پسند کرے اُن کے لئے بھی پسند کرنا اور ناپسندیدہ چیزوں میں سے جو اپنے لئے ناپسند کرے اُن کے لئے بھی ناپسند کرنا۔ \n(شرح مسلم للنووی ، کتاب الایمان ، باب الدین النصیحة ، الجزء الثانی، ۱ / ۳۷ تا ۳۹ )\n¥خیر خواہی کے لئے علم ضروری ہے:\n علامہ اِبن بَطال رحمۃُ اللہ علیہ نقل فرماتے ہیں کہ کوئی بھی شخص اللہ پاک، کتابُ اللہ، اُس کے رسول صلّی اللہ علیہ واٰلہٖ وسلّم ، اَئِمَّۂ مسلمین اور عام مسلمانوں کے لئے اُس وقت تک خیر خواہ نہیں ہو سکتا جب تک کہ وہ اپنے آپ سے خیر خواہی اور طلب علم کے لئے کوشش نہ کرے، کیونکہ علم ہی کے ذریعے اُسے معلوم ہوگا کہ کیا چیز اُس کے لئے واجب ہے اور کیا نہیں۔ نیز یہ بھی معلوم ہوگا کہ شیطان اُس کا دشمن ہے، اُس سے کس طرح بچا جاسکتا ہے؟ اورنفس کِن بُری باتوں کی طرف مائل ہوتا ہےجن سے بچنا چاہیے وغیرہ۔(شرح بخاری لابن بطال، کتاب الایمان ، باب قول الرسول: الدین النصیحة...الخ، ۱ / ۱۳۰) \n¥دعا:\nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6873, "bookId": 13, "volNo": "1", "hadithNo": 8, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "مسلمان کے مال اور خون کی حرمت", "arabic": "عَنِ ابْنِ عُمَرَ رَضيَ اللهُ عَنْهُ مَا اَنَّ رَسُوْلَ اللهِ صلّی اللہ علیہ وسلّم قَالَ: ’’اُمِرْتُ اَنْ اُقَاتِلَ النَّاسَ حَتّٰى يَشْهَدُوْا اَنْ لَّا اِلٰهَ اِلَّا اللهُ وَاَنَّ مُحَمَّدًا رَسُوْلُ اللهِ وَيُقِيْمُوْا الصَّلَاةَ وَيُؤْتُوْا الزَّكَاةَ فَاِذَا فَعَلُوْا ذٰلِكَ عَصَمُوْا مِنِّيْ دِمَآءَهُمْ وَ اَمْوَالَهُمْ اِلَّا بِحَقِّ الْاِسْلَامِ وَحِسَابُهُمْ عَلَى اللهِ تَعَالٰى.‘‘(رَوَاہُ الْبُخَارِی وَمُسْلِم)", "urdu": "حضرت سیِّدُنا عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسولِ پاک صلی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ مجھے حکم دیا گیا ہے کہ میں لوگوں سے جہاد کروں یہاں تک کہ وہ اس بات کی گواہی دیں کہ اللہ پاک کے سوا کوئی عبادت کے لائق نہیں اور یہ کہ محمد ( صلّی اللہ علیہ واٰلہٖ وسلّم ) اللہ پاک کے رسول ہیں، نماز قائم کریں اور زکوٰۃ ادا کریں۔ پس جب انہوں نے یہ کام کرلیا تو انہوں نے مجھ سے اپنا خون اور مال بچالیا سوائے اسلام کے حق کے اور ان کا حساب اللہ پاک کے ذمَّۂ کرم پر ہے۔‘‘(بخاری، كتاب الایمان، باب فان تابوا واقاموا الصلاة، ۱/ ۲۰، حدیث:۲۵۔ مسلم، کتاب الایمان، باب الامر بقتال الناس حتی یقولوا...الخ، ص۴۰، حدیث:۱۲۹)", "roman": "Hazrat Sayyiduna Abdullah Ibn Umar RadiyAllahu Anhuma se Riwayat hai ke Rasool-e-Paak Sallallahu Alaihi Wasallam ne irshad farmaya: \"Mujhe Hukm diya gaya hai ke main logon se jihad karoon yahan tak ke woh is baat ki Gawahi dein ke Allah Paak ke siwa koi ibadat ke laaiq nahi aur yeh ke Muhammad (Sallallahu Alaihi Wasallam) Allah Paak ke Rasool hain, Namaz qaim karein aur Zakat ada karein. Pas jab unhon ne yeh kaam kar liya to unhon ne mujh se apna khoon aur Maal bacha liya siwaye Islam ke haq ke aur un ka hisab Allah Paak ke zimmah-e-karam par hai.\" (Bukhari, Kitaab-ul-Iman, Baab Fa-in Taaboo wa Aqaamoo As-Salah, 1/20, Hadees: 25. Muslim, Kitaab-ul-Iman, Baab Al-Amr bi-Qitaal-in-Naas Hatta Yaqooloo... ilkh, p. 40, Hadees: 129)", "explanation": "¥لوگوں سے مراد:\n خیال رہے! حدیث شریف میں مذکور ’’مجھے لوگوں سے جہاد کرنے کا حکم دیا گیا ہے‘‘ میں لوگوں سے مراد کفار ومشرکین ہیں۔چنانچہ علامہ شِہاب الدین احمد بن محمد قسطلانی رحمۃُ اللہ علیہ فرماتے ہیں: یہاں عام لفظ بول کر خاص افراد مراد لئے گئے ہیں اور وہ اہْلِ کتاب کے علاوہ مشرکین ہیں۔ بعض روایات میں تو مشرکین کے الفاظ بھی ہیں جیسا کہ نسائی شریف کی روایت میں ہے: ” مجھے مشرکین سے جہاد کا حکم دیا گیا ہے۔“(نسائی، کتاب تحریم الدم، باب ، ص۶۴۹، حدیث:۳۹۷۲) یہ بھی ہو سکتا ہے کہ یہاں مراد اہْلِ کتا ب ہی ہوں۔(ارشاد الساری، کتاب الایمان، باب فان تابوا...الخ، ۱ / ۱۸۴، تحت الحدیث:۲۵)\n¥شہادتین، نماز اور زکوٰۃ کی خصوصیت کی وجہ :\nعلامہ محمد بن علّان شافعی رحمۃُ اللہ علیہ فرماتے ہیں: ’’اسلام کے پانچ ارکان میں سے شہادت یعنی اس بات کی گواہی دینا کہ اللہ پاک کے سوا کوئی معبود نہیں اور حضرت محمد صلّی اللہ علیہ واٰلہٖ وسلّم اللہ پاک کے بندے اور اس کے رسول ہیں۔ یہ اعتقادی رکن ہے ، نماز کی پابندی(جسمانی) اور زکوٰۃ کی ادائیگی مالی رکن ہے۔ اسلام کی طرف بلانے میں فقط شہادت کافی ہوتی ہے تاکہ دیگر دو ارکان یعنی نماز اور زکوٰۃ اس پر متفرع ہوسکیں کیونکہ روزہ محض بدنی رکن ہے، جبکہ حج بدنی اور مالی دونوں کا جامع ہے۔ پس کلمہ اسلام (یعنی وحدانیت ورسالت کا اقرار) ہی اصل ہے اور یہی کفار پر شاق و گراں ہے۔ یہی وجہ ہے کہ پہلے اس کا ذکر ہوا پھر نماز کا کیونکہ وہ تکرار(یعنی دن میں پانچ بار ہونے کی وجہ سے) کفار پر گراں ہے اور تیسرے نمبر پر زکوٰۃ کا کہ اس میں مال خرچ کرنا ہوتا ہے جو انسانی طبیعت پر گراں ہے کیونکہ عموماً انسان کو مال سے محبت ہوتی ہے۔ پس جب بندہ ان تین امور کی ادائیگی کرلے گا تو بقیہ اَحکامات پر عمل کرنا اس کے لئے زیادہ آسان ہوگا۔‘‘ \n(دلیل الفالحین، باب فی تحریم الظلم والامر برد المظالم،۱ / ۵۲۵، تحت الحدیث:۲۰۹)\n¥شہادتین کے ساتھ بقیہ ارکان کا ذکر کیوں نہیں؟\n علامہ بدر الدین عینی رحمۃُ اللہ علیہ فرماتے ہیں: ’’اِس حدیث پاک میں توحید و رسالت کے ساتھ نماز و زکوٰۃ پر ایمان لانے کا حکم ہے جبکہ بقیہ ارکان و احکام کا ذکر نہیں ہے (اس کی وجہ یہ ہے کہ ) نماز وزکوٰۃ کی اہمیت کی وجہ سے خاص طور پر اِن دونوں کا ذکر فرمایا ورنہ مومن ہونے کے لئے اُن تمام باتوں پر ایمان لانا ضروری ہے جو حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم اللہ پاک کی طرف سے لائے ہیں۔‘‘ (عمدة القاری، کتاب الایمان، باب فان تابوا... الخ، ۱/ ۲۷۶، تحت الحدیث:۲۵، ملخصًا)\n¥تارِک نمازوزکوٰۃ کا شرعی حکم :\n مذکورہ حدیث شریف میں اس بات کا بیان ہے کہ جو شخص توحید ورسالت کی گواہی کے ساتھ نماز وزکوٰۃکی ادائیگی کرے گا اس کا خون اور مال محفوظ ہے۔ اس سے پتا چلا کہ جو نماز نہ پڑھے یا زکوٰۃ ادا نہ کرے تو اس پر اس سے مواخذہ ہوگا۔ چنانچہ صدرُالشریعہ ، بدرُالطریقہ حضرت علامہ مولانا مفتی محمد امجد علی اعظمی رحمۃُ اللہ علیہ نماز کا شرعی حکم بیان کرتے ہوئے فرماتے ہیں: ’’ہر مکلّف یعنی عاقِل بالغ پر نما ز فرضِ عین ہے اس کی فرضیت کا منکر کافر ہے اور جو قصداً چھوڑے اگرچہ ایک ہی وقت کی وہ فاسِق ہے اور جو نماز نہ پڑھتا ہو قید کیا جائے یہاں تک کہ توبہ کرے اور نماز پڑھنے لگے بلکہ اَئِمَّۂ ثلاثہ مالک و شافعی و احمد رضی اللہ عنہم کے نزدیک سلطانِ اسلام کو اس کے قتل کا حکم ہے۔‘‘ (بہارشریعت ، حصہ3، 1/ 443) اور زکوٰۃ ادا نہ کرنے کے متعلق فرماتے ہیں: ’’زکاۃ فرض ہے، اُس کا منکر کافر اور نہ دینے والا فاسق اور قتل کا مستحق اور ادا میں تاخیر کرنے والا گنہگار و مردودُ الشہادۃ ہے۔‘‘ (بہارشریعت ، حصہ5، 1/ 874)\n¥حَقِّ اِسلام سے مرا د:\nمذکورہ حدیث پاک کے آخر میں اس بات کا بیان ہوا کہ توحید باری تعالیٰ اور رسالت کی گواہی، نماز ادا کرنے اور زکوٰۃ دینے سے خون اور مال محفوظ ہوگیامگر حَقِّ اسلام معاف نہ ہوگا۔ علمائے کرام رحمۃُ اللہ علیہم نے یہاں حَقِّ اسلام سے یہ حُقُوق مراد لئے ہیں: (1) جان بوجھ کر قتل کرنا اس کے بدلے اسے قصاص میں قتل کیا جائے گا ۔ (2)محصن یعنی شادی شدہ شخص کا زنا کرنا اسے سنگسار کیا جائے گا۔ (3)مسلمان ہونے کے بعد مرتد ہوجانا۔ (4)مختلف اَموال میں فرض ہونے والی مختلف اَقسام کی زکاتیں بھی معاف نہ ہوں گی۔ (5) مختلف اَحکامِ شرعیہ میں جو کَفّارے لازم ہوتے ہیں وہ بھی معاف نہ ہوں گے۔ (6) نفقاتِ واجبہ یعنی جن لوگوں پر خرچ کرنا واجب ہے ان کا خرچ بھی معاف نہ ہوگا۔ (7) وہ تمام امور جن کا کرنا شرع نے اس پر واجب فرمایا ہے ان کی ادائیگی معاف نہ ہوگی۔ اسی طرح وہ تمام امور جن کو کرنے کی ممانعت ہے ان کی ممانعت بھی اس سے ختم نہ ہوگی یعنی اسے ان سے ضرور بچنا ہوگا۔ (دلیل الفالحین، کتاب الفضائل، باب فی الامر بالمحافظة علی الصلوات...الخ، ۳/ ۵۶۱، تحت الحدیث:۱۰۷۴)\n¥باطنی اُمُور کا حساب اللہ پاک کے ذِمَّۂ کرم پر ہے:\n حضرت سیِّدُنا علامہ محمد بن علّان شافعی رحمۃُ اللہ علیہ ’’ اور اُن کا حساب اللہ پاک کے ذِمَّۂ کرم پر ہے‘‘ کے تحت فرماتے ہیں: ’’یعنی مخفی معاملات اور پوشیدہ عقائد کا حساب وکتاب اور فیصلہ ربّ کریم فرمائے گا جبکہ ظاہری معاملات کا فیصلہ مقتضائے حال کے مطابق کیا جائے گا ۔ حدیث پاک کا حاصل یہ ہے کہ باطنی اُمور کا معاملہ اللہ پاک کے سپرد کر دیا جائے کیونکہ رازوں کی پوشیدگیوں، دلوں کے باریک اور خفیہ خیالات کا ذِمَّہ اس ربِّ کریم ہی پر ہے جو (بندوں کے)ایمان، کفر اور نفاق کو جانتا ہے۔‘‘(دلیل الفالحین، باب فی اجراء احکام الناس...الخ، ۲/ ۲۷۰، تحت الحدیث:۳۹۰)\n¥ظاہر کے مطابق فیصلہ کرنے کا حکم :\n علامہ بدر الدین عینی رحمۃُ اللہ علیہ فرماتے ہیں: ’’حدیث پاک میں اس بات پر دلیل ہے کہ لوگوں پر ان کی ظاہری حالت کے مطابق فیصلہ کیا جائے جبکہ ان کے باطنی معاملات کو اللہ پاک کے سپرد کر دیا جائے۔ نبی کریم صلّی اللہ علیہ وسلّم اور آپ کے بعد کے اَئِمَّہ نے بھی اسی طرح لوگوں کے درمیان فیصلہ فرمایا۔‘‘ (عمدة القاری، کتاب الایمان، باب فان تابوا...الخ، ۱/ ۲۷۵، تحت الحدیث:۲۵)\n امام شرف الدین حسین بن محمد طیبی رحمۃُ اللہ علیہ فرماتے ہیں: ’’جن باتوں کو لو گ اپنے دل میں چھپائے بیٹھے ہیں جیسے کفر گناہ وغیرہ، ان کا حساب اللہ پاک ہی لے گا، مخلص کو ثواب دے گا اور مُنافق کو عذاب یا چھپ کر فسق کرنے والے کو سزا دے گا یا معاف فرما دے گا۔ جو شخص اپنے اسلام کو ظاہر کرے اور کفر کو چھپائے تو ظاہر کے اعتبار سے اس کے اسلام کو قبول کر لیا جائے گا اکثر علماء کا یہی قول ہے۔‘‘ (شرح الطیبی، کتاب الایمان، ۱/ ۱۲۹، تحت الحدیث:۱۰)\n علامہ محمد بن علّان شافعی رحمۃُ اللہ علیہ فرماتے ہیں: ’’مذکورہ حدیث شریف میں حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ظاہری اَحوال پر اَحکام کا اِجرا فرمایا ہے اور باطنی احوال کا معاملہ باطنی امور کو جاننے والے ربّ کریم کے سپرد کر دیا ہے کہ باطنی احوال پر وہ خود ہی ان کا محاسبہ فرمائے ۔ ‘‘(دلیل الفالحین، کتاب الفضائل، باب فی الامر بالمحافظة علی الصلوات...الخ، ۳/ ۵۶۱، تحت الحدیث:۱۰۷۴)\n¥رسولِ پاک صلّی اللہ علیہ وسلّم ¥کے فیصلوں سے متعلق اہم وضاحت :\nواضح رہے کہ مذکورہ حدیث پاک میں جو ظاہر پر فیصلہ کرنے کا حکم دیاگیا ہے وہ فقط اُمَّت کے لئے ہے جبکہ اللہ پاک کے آخری نبی، محمد عربی صلّی اللہ علیہ واٰلہٖ وسلّم کو اللہ پاک نے یہ خصوصی اختیار عطا فرمایا ہے کہ آپ کسی بھی شخص کے ظاہر پر بھی فیصلہ فرماسکتے ہیں اور باطن پر بھی ، بہرصورت آپ صلّی اللہ علیہ واٰلہٖ وسلّم کا فیصلہ نافذہوگا کیونکہ آپ پر اُمَّت کے تمام ظاہری وباطنی اَحوال ظاہر ہیں، اس لئے کہ اللہ پاک نے آپ کو ظاہر کا علم بھی عطا فرمایا ہے اور باطن کا بھی ۔ آپ صلّی اللہ علیہ واٰلہٖ وسلّم کو فریقین میں فیصلہ کے لئے نہ تو کسی گواہ کی ضرورت ہے اور نہ ہی قسم کی۔\n¥ظاہر وباطن کے مطابق فیصلے کی چند مثالیں:\n واضح رہے کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے اپنی حیات طیبہ میں عمومی طور پر ظاہر پر ہی فیصلہ فرمایا لیکن بسا اوقات ظاہری وباطنی دونوں، کبھی فقط باطنی پر یعنی ہرطرح کے فیصلے فرمائے۔ چنانچہ\nظاہر وباطن کے مطابق فیصلہ: اُمُّ المؤمنین حضرت سیِّدَتُنا عائشہ صدیقہ رضی اللہ عنہا فرماتی ہیں کہ حضرت سعد بن ابی وقاص اور حضرت عبد بن زمعہ رضی اللہ عنہما کا ایک نوجوان لڑکے کے بارے میں جھگڑا ہوگیا۔ حضرت سعد رضی اللہ عنہ نے بارگاہِ رسالت میں عرض کی: ’’یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! یہ میرے بھائی عتبہ بن ابی وقاص کا بیٹا ہے ، اُس نے مجھے وصیت کی تھی کہ یہ اس کا بیٹا ہے، آپ اس کی صورت تو دیکھئے (عتبہ سے کتنی ملتی ہے)۔‘‘ حضرت عبد بن زمعہ رضی اللہ عنہ نے عرض کی: ’’یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! یہ میرا بھائی ہے جو میرے باپ کے بستر پر اس کی باندی (غلام عورت) سے پیدا ہواہے۔‘‘ تو آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اے عبد بن زمعہ! یہ تیرا بھائی ہے، اس لئے کہ بچہ اسی کا ہوتا ہے جس کے ہاں وہ پیدا ہوا ہو اور زانی کے لیے پتھر ہیں۔‘‘ اور عتبہ کے ساتھ مشابہت کی وجہ سے حضرت سودہ بنت زمعہ رضی اللہ عنہا سے ارشاد فرمایا: ’’اے سودہ ! اس سے پردہ کرو۔ ‘‘ پس حضرت سودہ رضی اللہ عنہا نے اسے پھر کبھی نہ دیکھا۔ (بخاری، کتاب الفرائض، باب الولدللفراش...الخ، ۴/ ۳۲۱،حدیث:۶۷۴۹)\n اس میں ظاہر کا فیصلہ تو حضرت زمعہ رضی اللہ عنہ کا بھائی قرار دے کر فرمایا لیکن باطنی فیصلے میں حضرت سودہ رضی اللہ عنہا کو پردے کا حکم دیا حالانکہ ظاہری فیصلے کے اعتبار سے وہ آپ کا بھائی بنتا تھا ۔\nفقط ظاہر کے مطابق فیصلہ: حضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے مسجد میں بارگاہِ رسالت میں حاضر ہو کر زنا کا اعتراف کیا، آپ صلّی اللہ علیہ وسلّم نے اپنا رُخِ اَنور دوسری طرف کر لیا، اس نے دوسری جانب سے آکر اعتراف کیا تو آپ نے پھر چہرہ مبارکہ پھیر لیا حتّٰی کہ چار بار اس نے زنا کا اعتراف کیا۔ آپ نے اس سے ارشاد فرمایا: ’’کیا تمہارا ذہنی توازن تو خراب نہیں؟‘‘ اس نے عرض کی: نہیں۔ ارشاد فرمایا: ’’کیا تم شادی شدہ ہو؟‘‘ عرض کی: جی ہاں۔ اس پر آپ صلّی اللہ علیہ وسلّم نے اسے رجم (سنگسار) کرنے کا حکم دے دیا۔ (مسلم، کتاب الحدود، باب من اعتراف علی نفسہ بالزنی، ص۹۲۹، حدیث:۴۴۲۰)\nرَجم کا مفہوم: زانی مرد یا زانیہ عورت (جس کے متعلق رجم کا حکم ہے اس) کومیدان میں لے جا کر اس قدر پتھر مارنا کہ مرجائے۔ (ماخوذ از بہارشریعت، حصہ9، 2/ 374)\nفقط باطن کے مطابق فیصلہ: حضرت سیِّدُنا جابر بن عبد اللہ رضی اللہ عنہ بیان کرتے ہیں کہ بارگاہِ رسالت میں ایک چور کو لایا گیا تو حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اسے قتل کردو۔‘‘ عرض کی گئی: ’’یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! اس نے تو صرف چوری کی ہے؟‘‘ ارشاد فرمایا: ’’اس کا ہاتھ کاٹ دو ۔‘‘ اسے دوبارہ چوری کے جرم میں لایا گیا تو آپ نے قتل کا حکم دیا۔ پھر چوری کا عرض کیا گیا تو ارشاد فرمایا: ’’اس کا پاؤں کاٹ دو۔‘‘ تیسری مرتبہ پھرچوری کے جرم میں اسے لایا گیا تو قتل کا حکم فرمایا۔ پھر چوری کا عرض کیا گیا تو ارشاد فرمایا: ’’اس کا دوسرا ہاتھ بھی کاٹ دو۔‘‘ چوتھی بار بھی اسے چوری کے جرم میں لایا گیا تو قتل کا حکم فرمایا۔ پھر چوری کا عرض کیا گیا تو ارشاد فرمایا: ’’اس کا دوسرا پاؤں بھی کاٹ دو۔‘‘ پانچویں مرتبہ پھر اسے چوری کے جرم میں لایا گیا تو ارشاد فرمایا: ’’اسے قتل کردو۔‘‘ چنانچہ اسے قتل کردیا گیا۔ \n(نسائی، کتاب قطع السارق، باب قطع الرجل من السارق بعد الید، ص۷۹۵، حدیث:۴۹۸۷، بتغیر)\nاس حدیث پاک میں اولاً آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے چور کو جو قتل کرنے کا حکم دیا وہ باطن کے مطابق فیصلہ تھا کیونکہ بالآخر اس نے قتل ہی ہونا تھا۔\n(نوٹ: حضور نبی کریم صلّی اللہ علیہ وسلّم کے ظاہر وباطن کے مطابق فیصلہ فرمانے کے متعلق تفصیل جاننے کے لئے حضرت سیِّدُنا امام جلال الدین سیوطی رحمۃُ اللہ علیہ کی مایہ ناز تصنیف ’’اَلْبَاہِر فِیْ حُکْمِ النَّبِیِّ بِالْبَاطِنِ وَالظَّاہِر‘‘ ترجمہ بنام ’’مدنی آقا کے روشن فیصلے‘‘ کا مطالعہ کیجئے۔ )\n¥دعا:\nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6874, "bookId": 13, "volNo": "1", "hadithNo": 9, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "زیادہ سوال کرنے سے بچو", "arabic": "عَنْ اَبِيْ هُرَيْرَةَ عَبْدِ الرَّحْمٰنِ بْنِ صَخْرٍ رَضيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُوْلَ اللہ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُوْلُ: ’’ مَا نَهَيْتُكُمْ عَنْهُ فَاجْتَنِبُوْهُ وَمَا اَمَرْتُكُمْ بِهٖ فَافْعَلُوْا مِنْهُ مَا اسْتَطَعْتُمْ فَاِنَّمَا اَهْلَكَ الَّذِيْنَ مِنْ قَبْلِكُمْ كَثْرَةُ مَسَآئِلِہِمْ وَاخْتِلَافُهُمْ عَلٰى اَنْبِيَآئِهِمْ.‘‘( رَوَاهُ الْبُخَارِی وَمُسْلِم )", "urdu": "حضرت سیِّدُنا ابوہریرہ عبد الرحمٰن بن صخر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم کو ارشاد فرماتے سنا: ’’جس چیز سے میں تمہیں منع کردوں تو اس سے رک جاؤ اور جس چیز کا میں تمہیں حکم دوں تو اپنی استطاعت کے مطابق اس پر عمل کرو کیونکہ تم سے پہلوں کو زیادہ سوال کرنےاور اپنے انبیا کی مخالفت نے ہلاک کردیا۔‘‘(بخاری، کتاب الاعتصام بالکتاب والسنة، باب الاقتداء بسنن رسول، ۴/ ۵۰۲، حدیث: ۷۲۸۸ ، بتغیر قلیل ۔ مسلم، کتاب الحج، باب فی الحج مرة فی العمر،ص۵۳۶، حدیث:۳۲۵۷، بتغیر)", "roman": "Hazrat Sayyiduna Abu Hurairah Abdur Rahman Bin Sakhr RadiyAllahu Anhu bayaan karte hain ke main ne Rasool-e-Paak Sallallahu Alayhi wa Sallam ko irshaad farmate suna: ''Jis cheez se main tumhein mana' kar doon to us se ruk jao aur jis cheez ka main tumhein Hukm doon to apni istita'at ke mutabiq us par amal karo kyonke tum se pehlo'n ko zyada Sawaal karne aur apne Ambiya ki mukhalifat ne halaak kar diya.'' (Bukhari, Kitaab-ul-I'tisaam bil-Kitaab was-Sunnah, Baab-ul-Iqtida bi Sunan-e-Rasool, 4/502, Hadees: 7288, bitaghayyur-e-qaleel. Muslim, Kitaab-ul-Hajj, Baab fil Hajj marratan fil umr, s. 536, Hadees: 3257, bitaghayyur)", "explanation": "¥حدیث پاک کا شانِ وُرُوْد:\n حضرت سیِّدُنا علامہ حافظ ابن حجر عسقلانی رحمۃُ اللہ علیہ بیان کرتے ہیں کہ حضرت سیِّدُناابوہریرہ رضی اللہ عنہ سےمروی ہے کہ رسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ہمیں خطبہ دیتے ہوئے ارشاد فرمایا: ’’اے لوگو! اللہ پاک نے تم پر حج فرض کیا ہے، لہٰذا تم حج کرو۔‘‘ ایک شخص نے عرض کی: یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! کیا ہر سال حج فرض ہے؟ آپ نے سکوت فرمایا یہاں تک کہ اس نےتین مرتبہ یہی کہا۔ پھرآپ نے ارشاد فرمایا: ’’اگر میں ’’ہاں‘‘ کہہ دیتاتو تم پرہرسال حج فرض ہوجاتااورتم اس کی طاقت نہ رکھتے۔‘‘ پھر آپ نے حدیث مذکور ارشاد فرمائی۔ دارقطنی میں ہے کہ یہ آیت مقدسہ اسی معاملے میں نازل ہوئی:\nیٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا لَا تَسْــٴَـلُوْا عَنْ اَشْیَآءَ اِنْ تُبْدَ لَكُمْ تَسُؤْكُمْۚ-\n (پ ۷، المآئدة: ۱۰۱) ترجمہ کنزالایمان: اے ایمان والو ایسی باتیں نہ پوچھو جو تم پر ظاہر کی جائیں تو تمہیں بُری لگیں۔\nقریب قریب تفسیر ِطبری میں بھی اسی طرح منقول ہے۔ \n(فتح الباری،کتاب الاعتصام بالکتاب والسنة، باب الاقتداءبسنن رسول اللّٰہ...الخ، ۱۴/ ۲۲۳، تحت الحدیث:۷۲۸۸)\nحضرت سیِّدُنا علامہ ابو زکریا یحییٰ بن شرف نووی رحمۃُ اللہ علیہ فرماتے ہیں:یہ حدیث شریف جوامِعُ الْکَلِم اور قواعدِ اِسلامیَّہ میں سے ہےاور اِس اُصول میں بےشماراَحکام داخل ہیں۔ (شرح مسلم للنووی، کتاب الحج، باب فرض الحج مرة فی العمرة، ۹/ ۱۰۲)\n¥ہر بات میں رسول صلّی اللہ علیہ وسلّم ¥کی اطاعت کرو:\n حدیث پاک میں ارشاد ہوا: ’’ جس چیز سے میں تمہیں منع کردوں تو اس سے رک جاؤ اور جس چیز کا تمہیں حکم دوں تو اپنی استطاعت کے مطابق اس پر عمل کرو‘‘ مشہور شارح حدیث، حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ اس کے تحت فرماتے ہیں: یعنی میرے اَحکام پر عمل کر نا فرض ہے اور ممنوعات سے بچنا لازم، یہ دونوں کام بقدرِ طاقت ہیں اگر نماز کھڑے ہو کر نہ پڑھ سکو تو بیٹھ کر پڑھ لو، اگر جان پر بن جائے تو مردار کھا لو۔اس سے معلوم ہوا کہ جیسے وجوب و فرضیت کے لیے امر ضروری ہے ایسے ہی حُرمت و مُمانعت کے لیے نہی لازم، جس چیز کا حکم بھی نہ ہو اور ممانعت بھی نہ ہو وہ جائز ہے۔ ربِّ کریم ارشاد فرماتا ہے:\nوَ مَاۤ اٰتٰىكُمُ الرَّسُوْلُ فَخُذُوْهُۚ-وَ مَا نَهٰىكُمْ عَنْهُ فَانْتَهُوْاۚ- (پ ۲۸، الحشر:۷) \nترجمہ کنزالایمان: اور جو کچھ تمہیں رسول عطا فرمائیں وہ لو اور جس سے منع فرمائیں باز رہو۔\n بعض جو کہتے ہیں کہ ’’ جو کام حضور علیہِ الصّلوٰۃُوالسّلام نے نہ کیا ہو وہ حرام ہے۔‘‘(ایسا کہنا) غلط ہے، قرآن شریف کے بھی خلاف ہے اور اس قسم کی احادیث کے بھی۔(مراٰۃ المناجیح، 4/ 87 ،ملخصاً)\n حضرت سیِّدُناشیخ عبدالحق مُحدِّث دہلوی رحمۃُ اللہ علیہ فرماتے ہیں: ’’مجھ سے یہ سوال نہ کروکہ کتنا ہےاورکیوں ہےجب تک میں خودبیان نہ کروں کہ کتناہےاورکیوں ہے یعنی جتنا میں کہوں اتنے پرعمل کرو، اگرمطلق حکم دوں تواس کےمطابق عمل کرواورتعیین کردوں تواس پر عمل کرو، کیونکہ مجھےشرعی اَحکام بیان کرنےکے‏لیےبھیجاگیاہے، جو حکم ہو گا وہ میں تمہارے پوچھے بغیر ہی بیان کر دوں گا۔‘‘ (اشعة اللمعات،کتاب المناسک،الفصل الاول، ۲‏/ ۳۲۰)\n¥ماقبل امتوں کی ہلاکت کے اسباب:\n حدیث پاک میں زیادہ سوالات کرنے سے منع کرتے ہوئے ارشاد فرمایا: ’’ تم سے پہلوں کو زیادہ سوال کرنے اور اپنے انبیا کی مخالفت نے ہلاک کر دیا ‘‘ حضرت سیِّدُنا علامہ ملا علی قاری رحمۃُ اللہ علیہ اس کے تحت فرماتے ہیں: تم سے پہلے یہودونصاریٰ کثرتِ سوال کی وجہ سے ہلاک کئے گئے۔جیساکہ ان کا (حضرت سیِّدُنا موسیٰ علیہِ السّلام سے) دیدار الٰہی اور کلام کا سوال کرنا، گائے ذبح کرنے کے معاملے میں بِلا وجہ سوالات کرنا وغیرہ۔ان کے سوال کے بعد اَنبیائے کرام علیہمُ السّلام جب انہیں کسی چیز کاحکم دیتے تو وہ اس کی مخالفت کرتے، لہٰذاوہ ہلاک کر دیئے گئے۔\n(مرقاة المفاتیح، کتاب المناسک، الفصل الاول، ۵/ ۳۸۰، تحت الحدیث:۲۵۰۵)\n مشہور شارح حدیث، حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ ’’کثرتِ سوال اور انبیا کی مخالفت‘‘کے تحت فرماتے ہیں: اس طرح کہ انہوں نے زیادہ پوچھ پوچھ کر پابندیاں لگوالیں، پھر ان پابندیوں پر عمل نہ کر سکے یا انہوں نے عمل تو کیا مگر بہت مشکل سے جیسے ذبح گائے کا واقعہ ۔ (مراٰ ۃالمناجیح، 4/ 87)\n¥کثرت سوالات سے مراد:\n حضرت سیِّدُنا علامہ عبد الرؤوف مناوی رحمۃُ اللہ علیہ ’’کثرتِ سوالات سے ممانعت‘‘ کے تحت فرماتے ہیں: اس سے مراد یہ ہے کہ لوگوں کے احوال کے متعلق زیادہ سوال کرنا یا فضول چیزوں کے بارے میں زیادہ سوال کرنا یا امتحاناً اور فخر کے طور پریا اپنی عظمت وبڑائی ظاہر کرنے کے لئے دوسروں سے علمی سوالات کرنا( اس قسم کے تمام سوالات ناپسندیدہ ہیں)۔\n(تیسر بشرح جامع الصغیر، ۱/ ۲۵۱)\n حضرت سیِّدُنا علامہ محمد بن علّان شافعی رحمۃُ اللہ علیہ نے کثرت سوال سے کئی باتیں مراد لی ہیں۔ چنانچہ فرماتے ہیں: اپنی ذات کے لیے بغیر حاجت مال کا سوال کرنا، بلا ضرورت مشکل اور پیچیدہ چیزوں کے بارے میں سوال کرنا، لوگوں کے حالات اور زمانے کے مختلف واقعات کے بارے میں سوال کرنا، کسی بھی شخص سے خصوصیت کے ساتھ اس کے حالات کے بارے میں تفصیلاً سوالات کرنا ہوسکتا ہے کہ اسے یہ اچھا نہ لگے (لہٰذا اس قسم کے زیادہ سوالات کرنے سے بچنا چاہئے)۔\n (دلیل الفالحین، باب فی تحریم العقوق وقطعیة الرحم، ۲/ ۱۸۵، تحت الحدیث:۳۴۱)\n¥دعا:\nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6875, "bookId": 13, "volNo": "1", "hadithNo": 10, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "حلال کی برکت اور حرام کی نحوست", "arabic": "عَنْ اَبِيْ هُرَيْرَةَ رَضيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : ’’اِنَّ اللهَ تَعَالٰی طَيِّبٌ لَّا يَقْبَلُ اِلَّا طَيِّبًا وَّاِنَّ اللهَ اَمَرَ الْمُؤْمِنِيْنَ بِمَا اَمَرَ بِهِ الْمُرْسَلِيْنَ فَقَالَ تَعَالٰی: ’’ یٰۤاَیُّهَا الرُّسُلُ كُلُوْا مِنَ الطَّیِّبٰتِ وَ اعْمَلُوْا صَالِحًاؕ-... الاٰیة (پ۱۸، المؤمنون:۵۱)‘‘ وَقَالَ تَعَالَى: ’’ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ... الاٰیة (پ۲، البقرة:۱۷۲)‘‘. ثُمَّ ذَكَرَ الرَّجُلَ يُـطِيْلُ السَّفَرَ اَشْعَثَ اَغْبَرَ يَمُدُّ يَدَيْهِ اِلَى السَّمَآءِ يَا رَبِّ يَا رَبِّ! وَمَطْعَمُهٗ حَرَامٌ وَّمَشْرَ بُہٗ حَرَامٌ وَّغُذِيَ بِالْحَرَامِ فَاَنّٰى يُسْتَجَابُ لِذٰلِكَ.‘‘ (رَوَاهُ مُسْلِم)", "urdu": "حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بےشک اللہ پاک طیب ہے اور وہ پاک ہی کو قبول کرتا ہے اور بے شک اللہ پاک نے مؤمنوں کو بھی اسی چیز کا حکم دیا ہے جس چیز کا رسولوں علیہمُ السّلام کو حکم دیا ہے۔ چنانچہ اللہ پاک نے ارشاد فرمایا:\nيَٰٓأَيُّهَا ٱلرُّسُلُ كُلُواْ مِنَ ٱلطَّيِّبَٰتِ وَٱعۡمَلُواْ صَٰلِحًاۖ (پ ۱۸، المؤمنون:۵۱)\nترجمہ کنزالایمان: اے پیغمبرو پاکیزہ چیزیں کھاؤ اور اچھا کام کرو۔\n ایک اور جگہ ارشاد فرمایا:\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ (پ ۲، البقرة:۱۷۲)\nترجمہ کنزالایمان: اے ایمان والو کھاؤ ہماری دی ہوئی ستھری چیزیں ۔\n پھر آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ایک شخص کا تذکرہ کیا جو طویل سفر کرتا ہے، گرد آلود پراگندا بالوں والا ہے، وہ اپنے ہاتھ آسمان کی طرف پھیلا کر کہتا ہے:اے میرے رب ! اے میرے رب! حالانکہ اسکا کھانا حرام، پینا حرام اور اس کی غذا حرام سے ہے تو اس کی دعا کیسے قبول ہو سکتی ہے۔‘‘(مسلم، كتاب الزکاة، باب قبول الصدقة من الکسب...الخ، ص۳۹۳، حدیث:۲۳۴۶)", "roman": "Hazrat Sayyiduna Abu Hurairah RadiyAllahu Anhu bayaan karte hain ke Huzoor Nabi Kareem Sallallahu Alayhi wa Sallam ne irshaad farmaya: ''Beshak Allah Paak tayyib hai aur woh Paak hi ko Qubool karta hai aur beshak Allah Paak ne Momino'n ko bhi usi cheez ka Hukm diya hai jis cheez ka Rasoolon Alayhimus Salam ko Hukm diya hai. Chunanche Allah Paak ne irshaad farmaya:\nيَٰٓأَيُّهَا ٱلرُّسُلُ كُلُواْ مِنَ ٱلطَّيِّبَٰتِ وَٱعۡمَلُواْ صَٰلِحًاۖ (پ ۱۸، المؤمنون:۵۱)\nTarjuma Kanzul Iman: Aye paighambaro pakeeza cheezein khao aur achha kaam karo.\nEk aur jagah irshaad farmaya:\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ (پ ۲، البقرة:۱۷۲)\nTarjuma Kanzul Iman: Aye imaan walo khao hamari di hui suthri cheezein.\nPhir Aap Sallallahu Alayhi wa Sallam ne ek Shakhs ka tazkira kiya jo taweel safar karta hai, gard-alood paraganda Baal'on wala hai, woh apne haath aasmaan ki taraf phaila kar kehta hai: Aye mere Rab! Aye mere Rab! halanke uska khana Haram, peena Haram aur uski ghiza Haram se hai to uski Dua kaise Qubool ho sakti hai.'' (Muslim, Kitaab-uz-Zakaat, Baab Qubool-is-Sadaqah minal Kasb...alkh, s. 393, Hadees: 2346)", "explanation": "¥مذکورہ حدیث پاک کی اہمیت:\n حضرت سیِّدُنا امام ابن دقیق رحمۃُ اللہ علیہ فرماتے ہیں:یہ حدیث شریف بھی ان احادیث کریمہ میں سے ایک ہے جنہیں اسلام کا مدار قرار دیا گیا ہے اور بے شمار اسلامی قواعد اور احکام پر مبنی ہے۔ (شرح اربعین لابن دقیق، ص۱۱۲، ملخصًا)\n¥شانِ باری تعالیٰ:\n حدیث شریف میں بیان ہوا کہ ’’اللہ طیب ہے“ اس سے مراد یہ ہے کہ ربِّ کریم بے عیب ہے اور بےعیب صدقات اور نقصانات سے خالی عبادات کو قبول فرماتاہے۔ ’’طیب‘‘ خبیث کی ضد ہے، حلال، پاک، لطیف، پسندیدہ،شرعی چیز ’’طیب‘‘ ہے۔اللہ پاک ’’طیب‘‘ ہے کہ خبیث چیزیں ناپسند کرتا ہے تمام صفات غیر کمالیہ سے بری و پاک ہے،مسلمانوں کو حکم دیا کہ ظاہری و باطنی نجاست سے دور رہیں نیک اعمال کریں،چیزیں انسان کے لیے ہیں اور انسان رحمٰن کے لیے۔(مراٰۃ المناجیح،4/227 ، 228 ، ملخصاً وملتقطاً)\n¥حلال وپاکیزہ چیز کھانے کا حکم:\n اللہ پاک نے مؤمنین کو بھی وہی حکم دیا جو رسولوں علیہمُ السّلام کو دیا کہ ”پاکیزہ اور ستھری چیزیں کھاؤ‘‘مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ اس حدیث پاک کی شرح میں فرماتے ہیں: ’’کسبِ حلال و طلبِ معاش ایسا مبارک مشغلہ ہے جس میں رب تعالیٰ نے انبیائے کرام علیہمُ الصّلوٰۃ ُوالسّلام اور عوام کو جمع فرمادیا ہے لہٰذا یہ حُکمِ خداوندی بھی ہے سنتِ مصطفوی بھی اور سنتِ انبیاءبھی اس لیے کسب حلال سنت سمجھ کر کرنا چاہیے،اس میں دنیا کی عزت بھی ہے آخرت کی سرخروئی بھی۔‘‘ حدیث پاک کے جز” اے پیغمبرو پاکیزہ چیزیں کھاؤ “ کے تحت فرماتے ہیں: ’’یا تو میثاق کے دن رب تعالیٰ نے نبیوں سے یہ خطاب بیک وقت فرمایا تھا یا ہر نبی سے ان کے زمانہ میں یہ خطاب ہوا جو قرآن کریم میں نقل فرمایا گیا اور حضور انور ( صلّی اللہ علیہ وسلّم ) کو سنایا گیا تاکہ معلوم ہو کہ رہبانیت اور ترک دنیا نہ اسلام میں ہے نہ پہلے کسی نبی کے دین میں تھی۔‘‘(مراٰۃ المناجیح، 4/227)\n¥انبیائے کرام علیہمُ السّلام ¥کے مبارک پیشے:\n اسی حکم کے پیش نظر انبیائے کرام علیہمُ السّلام نے حلال وپاکیزگی کے لئے مختلف پیشے اختیار فرمائے، کسی نے چندوں یا سوال پر زندگی نہ گزاری۔ چنانچہ حضرت سیِّدُنا آدم علیہ السّلام اولًا کپڑا سازی پھر کھیتی باڑی کرتے تھے، حضرت سیِّدُنا نوح علیہ السّلام لکڑی کا پیشہ، حضرت سیِّدُنا ادریس علیہ السّلام درزی گری، حضرت سیِّدُنا ہود اور حضرت سیِّدُنا صالح علیہما السلام تجارت، حضرت سیِّدُنا ابراہیم اور حضرت لوط علیہما السّلام کھیتی باڑی کرتے تھے، حضرت سیِّدُنا شعیب علیہ السّلام جانور پالتے تھے، حضرت سیِّدُنا موسیٰ علیہ السّلام نے بکریاں چَرائیں، حضرت سیِّدُنا داؤد علیہ السّلام زرہ بناتے، حضرت سیِّدُنا سلیمان علیہ السّلام اتنے بڑے ملک کے مالک ہوکر پنکھے اور زنبیلیں بنا کرگزارہ کرتے تھے، حضرت سیِّدُنا عیسیٰ علیہ السّلام ہمیشہ سیاحی (سیر وسیاحت)کرتے تھے اور ہمارے حضور انور صلّی اللہ علیہ وسلّم نے اولًا تجارت کا پیشہ اختیار فرمایا اور پھر جہاد کئے۔(مراٰۃ المناجیح،4/227 ،ملخصاً)\n¥حرام کی نحوست:\n حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ ’’مراٰۃ المناجیح، جلد4، صفحہ228‘‘ پر حدیث پاک کے جز”اس کی غذاحرام سے ہے تو اس کی دعا کیسے قبول ہو سکتی ہے“ کے تحت فرماتے ہیں:یعنی بچپن سے ہی حرام میں پلا اور جوان ہوکر حرام کمائی ہی کی جس سے غذا لباس حرام کا رہا۔ یہاں روئے سخن یا حرام خور حاجی یا غازی کی طرف ہے یعنی حرام کمائی سے حج یا غزوہ کرنے گیا، پراگندا حال پریشان حال رہا،کعبہ معظمہ یا میدان جہاد میں دعائیں مانگیں مگر قبول نہ ہوئیں کہ روزی حرام تھی جب ایسے حاجی و غازی کی دعا بھی قبول نہیں تو دوسروں کا کیا کہنا۔\n¥قبولیتِ دعا کا نسخہ:\n صوفیائے کرام رحمۃُ اللہ علیہم فرماتے ہیں: دعا کے دو بازو یعنی پَر ہیں:اکل حلال (حلال کھانا)، صدق مقال (سچ بولنا)اگر ان سے دعا خالی ہو تو قبول نہیں ہوتی۔تقویٰ کی پہلی سیڑھی حلال روزی ہے،حرام سے بچنا عوام کا تقویٰ ہے،شبہات سے بچنا خواص کا تقویٰ،ذریعَۂ معصیت سے بچنا صدیقین کا تقویٰ، اللہ پاک نصیب کرے۔ (مراٰۃ المناجیح،4/228 )\n حضرت سیِّدُنا سعد بن ابی وقاص رضی اللہ عنہ نے بارگاہِ رسالت میں عرض کی: یارسولَ اللہ صلّی اللہ علیہ وسلّم !اللہ پاک کی بارگاہ میں دعا کیجئے کہ وہ مجھے مستجاب الدعوات بنادے(یعنی ایسا بنادے کہ میری ہر دعا قبول ہو)۔ حضور نبی پاک صلّی اللہ علیہ وسلّم نے ارشاد فرمایا: ’’اے سعد! اپنا کھانا حلال وپاکیزہ کر لو مستجاب الدعوات ہو جاؤ گے۔‘‘ (معجم اوسط، ۵/ ۳۴، حدیث:۶۴۹۵)\n¥پاک لوگوں کی پاکیزہ خوراک:\n چونکہ جسمانی غذاؤں سے جسم کی بقا ہے اور روح کا ارتقاء کہ حلال غذا سے دل میں جلا پیدا ہوتی ہے جیسے حرام غذا سے دل میں تاریکی پیدا ہوتی ہے اس لیے رب تعالیٰ نے نماز و روزہ کی طرح حلال غذا کا بھی حکم دیا کہ اے مسلمانو! خدا کی محبت اورایمان کا تقاضا یہ نہیں ہے کہ تم لذیذ کھانوں اور اچھی نعمتوں سے ایک دم محروم ہو جاؤ بلکہ تقاضائے ایمان یہ ہے کہ ہر چیز کی حکمَتِ پیدا ئش سمجھو اور تقاضائے محبت یہ ہے کہ محبوب جو عطا کرے اسے بخوشی استعمال میں لاؤ معشوق کے ہاتھ کی کڑوی چیز بھی میٹھی (چیز) کی طرح کھائی جاتی ہے پس ہم تم سے کہتے ہیں کہ ہماری دی ہوئی حلال پاک اور لذیذ چیزیں شوق سے کھاؤ خواہ مہنگی ہی ہوں۔ (تفسیر نعیمی،پارہ2،سورۂ بقرہ،تحت الآیۃ: 172، 2/ 146)\n¥حلال لقمہ کی فضیلت:\n حضرت سیِّدُنا ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو شخص پاکیزہ (یعنی حلال) چیز کھائے اور سنت کے مطابق عمل کرے اور لوگ اس کے شر سے محفوظ رہیں تو وہ جنت میں داخل ہوگا۔‘‘(ترمذی، کتاب صفة القیامة والرقائق والورع، ۴/ ۲۳۳، حدیث:۲۵۲۸)\n حضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’کچھ گناہ ایسے ہیں جن کاکفّارہ نہ نمازہے،نہ روزہ ہے، نہ حج ہے اور نہ ہی عمرہ ہے۔‘‘ صحابَۂ کرام علیہمُ الرّضواننے عرض کی: یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم !پھر ان کا کفارہ کیا ہے؟ ارشاد فرمایا: ’’ان کاکفّارہ وہ پریشانیاں ہیں جوآدمی کو حلال روزی کی تلا ش میں پہنچتی ہیں۔‘‘ (معجم اوسط،باب الالف من اسمہ احمد، ۱/ ۴۲، حدیث:۱۰۲)\n ایک برزگ فرماتے ہیں: ’’مسلمان جب حلال کھانے کا پہلا لقمہ کھاتا ہے تو اس کے پہلے گناہ معاف کردئیے جاتے ہیں اور جو شخص طلب حلال کےلئے رسوائی کے مقام پر جاتا ہے تو اس کے گناہ درخت کے پتّوں کی طرح جھڑتے ہیں۔‘‘\n(احیاء العلوم،کتاب الحلال والحرام، الباب الاول فی فضیلة الحلال ومذمة الحرام، ۲/ ۱۱۶)\n¥حرام لقمہ کی نحوست:\n مسلمانوں کے پہلے خلیفہ حضرت سیِّدُنا ابو بکر صدیق رضی اللہ عنہ سے مروی ہے کہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ہر وہ جسم جو حرام سے پلا بڑھا ہو آگ اس سے بہت قریب ہوگی۔‘‘\n(شعب الایمان، التاسع والثلاثون من شعب الایمان...الخ، الفصل الثالث فی طیب المطعم والملبس، ۵/ ۵۶، حدیث:۵۷۵۹)\n حضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’تم میں سے کوئی شخص اپنے منہ میں مٹی ڈال لے تو یہ اس سے بہتر ہے کہ وہ اپنے منہ میں ایسی چیز ڈالے جسے اللہ پاک نے حرام کر دیا ہے۔‘‘\n(شعب الایمان، التاسع والثلاثون من شعب الایمان...الخ، الفصل الثالث فی طیب المطعم والملبس، ۵/ ۵۷، حدیث:۵۷۶۳)\n حضرت سیِّدُنا عبد اللہ بن مسعود رضی اللہ عنہ سے مروی ایک طویل روایت میں ہے کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو بندہ حرام مال حاصل کرتا ہےاگر اس کو صدقہ کرے تو مقبول نہیں، خرچ کرے تو اس کے لئے اس میں برکت نہیں اور اپنے بعد چھوڑ کر مرے تو جہنم میں جانے کا سامان ہے، اللہ پاک برائی سے برائی کو نہیں مٹاتا ہاں نیکی سے برائی کو مٹاتا ہےبے شک خبیث کوخبیث نہیں مٹاتا۔‘‘ (مسند احمد، مسند عبداللّٰہ بن مسعود، ۲/ ۳۳، حدیث:۳۶۷۲)\n¥دعا:\nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6876, "bookId": 13, "volNo": "1", "hadithNo": 11, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "مشکوک چیز سے بچو", "arabic": "عَنْ اَبِيْ مُحَمَّدِنِ الْحَسَنِ بْنِ عَلِیِّ بْنِ اَبِیْ طَالِبٍ سِبْطِ رَسُوْلِ اللہ وَرَیْحَانَتِہٖ رَضيَ اللهُ عَنْهُ مَا قَالَ: حَفِظْتُ مِنْ رَّسُوْلِ اللہ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : ’’دَعْ مَا یَرِیْبُکَ اِلٰی مَا لَا یَرِیْبُکَ.‘‘(رَوَاهُ التِّرْمِذِیُّ وَالنِّسَائِیُّ. وَقَالَ التِّرْمِذِیُّ حَدِيْثٌ حَسَنٌ صَحِیْحٌ)", "urdu": "خوشبوئے مصطفٰے، جگر گوشَۂ رسول حضرت سیِّدُنا ابو محمد حسن بن علی رضی اللہ عنہما فرماتے ہیں: میں نے رسولُ اللہ صلّی اللہ علیہ وسلّم سے (سن کر)یہ بات یاد کی کہ ’’جو چیز تجھے شک میں ڈالے اسے چھوڑ کر وہ اختیار کر جو تجھے شک میں نہ ڈالے۔‘‘\n(ترمذی، كتاب صفة القیامة والرقائق والورع، ۴/ ۲۳۲، حدیث:۲۵۲۶ ۔ نسائی، کتاب الاشربة، باب الحث علی ترک الشبھات، ص۹۰۰، حدیث:۵۷۲۲)\n (اس حدیث کو حضرت سیِّدُنا امام ابو عیسیٰ محمد بن عیسیٰ ترمذی اور حضرت سیِّدُنا امام ابو عبدالرحمٰن احمد بن شعیب بن علی خراسانی نسائی رحمۃ اللہ علیہما نے (ترمذی ونسائی میں) روایت کیا ہے اور حضرت سیِّدُنا امام ترمذی رحمۃ اللہ علیہ نے فرمایا: (اصولِ حدیث کی رو سے) یہ حدیث حسن صحیح ہے۔)", "roman": "Khushboo-e-Mustafa, Jigar Gosha-e-Rasool Hazrat Sayyiduna Abu Muhammad Hasan bin Ali RadiyAllahu Anhuma farmate hain: Main ne Rasoolullah Sallallahu Alayhi wa Sallam se (sun kar) yeh baat yaad ki ke ''Jo cheez tujhe shak mein daale use chhor kar woh ikhtiyaar kar jo tujhe shak mein na daale.''\n(Tirmizi, Kitaab Sifat-il-Qiyamah war-Raqaiq wal-Wara', 4/232, Hadees: 2526. Nasai, Kitaab-ul-Ashribah, Baab-ul-Hass ala Tark-ish-Shubuhaat, s. 900, Hadees: 5722)\n(Is Hadees ko Hazrat Sayyiduna Imam Abu Eesa Muhammad bin Eesa Tirmizi aur Hazrat Sayyiduna Imam Abu Abdur Rahman Ahmad bin Shu'ayb bin Ali Khurasani Nasai Rahmatullah Alayhima ne (Tirmizi wa Nasai mein) Riwayat kiya hai aur Hazrat Sayyiduna Imam Tirmizi Rahmatullah Alayh ne farmaya: (Usool-e-Hadees ki roo se) Yeh Hadees Hasan Saheeh hai.)", "explanation": "¥بچوں کا حدیث پاک روایت کرنا:\n مشہور شارحِ حدیث، حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ اس حدیثِ پاک کی شرح میں لکھتے ہیں: ’’ظاہر یہ ہے کہ حضرت سیِّدُنا امام حسن مجتبیٰ رضی اللہ عنہ نے بِلاواسطہ حضور صلّی اللہ علیہ واٰلہٖ وسلّم سے یہ سنا اور یاد کیا، کیونکہ حضور ِاَنور صلّی اللہ علیہ واٰلہٖ وسلّم کی زندگی شریف میں حضرت سیِّدُنا امام حَسن مجتبیٰ رضی اللہ عنہ قدرے سمجھدار تھے اور بچوں کا حدیث سننا معتبر ہے جب کہ کچھ سمجھدار ہوں اور ہوسکتا ہے کہ آپ رضی اللہ عنہ نے کسی صحابی رضی اللہ عنہ سے سنا ہو، چونکہ یہ قولِ رسول تھا، اس لئے اسے حضور صلّی اللہ علیہ واٰلہٖ وسلّم کی طرف نسبت فرمادیا، جیسے ہم کہہ دیتے ہیں کہ حضور صلّی اللہ علیہ واٰلہٖ وسلّم نے یہ فرمایا ،یا ہمیں حضور صلّی اللہ علیہ واٰلہٖ وسلّم کا یہ فرمان یاد ہے۔‘‘(مراٰۃ المناجیح، 4/234 ،ملخصاً)\n¥مذکورہ حدیث شریف کا معنیٰ:\n حضرت سیِّدُنا ابو زکریا یحییٰ بن شرف نووی رحمۃُ اللہ علیہ فرماتے ہیں: ’’اس حدیث شریف کا معنیٰ یہ ہے کہ جس کے حلال ہونے میں تجھے شک ہے اسے چھوڑدے اور جس کے حلال ہونے میں شک نہیں اسے اختیار کر۔‘‘ \n(ریاض الصالحین، باب الورع وترک الشبھات، ص ۱۸۴، تحت الحدیث:۵۹۳)\n¥مومن کا دل صحیح کام پر ہی مطمئن ہوتا ہے:\nحضرت سیِّدُنا امام شرف الدین حسین بن محمد بن عبد اللہ طیبی رحمۃُ اللہ علیہ فرماتے ہیں: ’’حدیث پاک کا مطلب یہ ہے کہ جب کسی چیز میں تمہیں شک ہو جائے تو اسے چھوڑ کر وہ کام کرو جس میں کوئی شک نہ ہو یعنی جب تمہارا نفس کسی کام کے بارے میں شک میں پڑ جائے تو اسے چھوڑ دو کیونکہ مومن کا نفس سچی بات پر مطمئن ہوتا ہے اور کسی کام پر نفس کا مطمئن نہ ہونا اُس کام کے باطل ہونے کی دلیل ہے، لہٰذا اس کام کو کرنے سے بچو اور کسی کام پر نفس کا مطمئن ہوجانا اس کام کے صحیح ہونے کی دلیل ہے، لہٰذا اس کام کو کرلو۔ لیکن یہ بات ان نفوسِ قدسیہ کے ساتھ خاص ہے جن کے دل گناہوں کی گندگی اور برائیوں کے میل سے پاک ہیں (یعنی یہ حکم ہر ایک کے لیے نہیں عام لوگوں کو حکم یہی ہے کہ وہ اپنے معاملات کی رہنمائی علمائے دین سے لیں)۔(شرح الطیبی، کتاب البیوع، باب الکسب وطلب الحلال، ۶/ ۲۰، تحت الحدیث:۲۷۷۳)\n¥مشکوک چیزوں سے بچنے کا حکم:\n حدیث پاک میں ہے:’’جو چیز تجھے شک میں ڈالے اسے چھوڑ دے۔‘‘ حضرت سیِّدُنا علامہ عبد الرؤوف مناوی رحمۃُ اللہ علیہ اس کی شرح میں فرماتے ہیں: تجھے کسی چیز کے اچھا یا بُرا ہونے، اسی طرح حلال یا حرام ہونے میں شک ہو تو اسے چھوڑ دے اور اس کو اختیار کر جس کے اچھا اور حلال ہونے میں تجھے یقین ہو کہ مشکوک چیز کو چھوڑ کر واضح حلال کی طرف پھر جانا چاہئے کیونکہ جو شبہات سے بچتا ہے وہ اپنا دین اور عزت بچا لیتا ہے۔ (تیسیر شرح جامع صغیر، ۲/ ۷، ملخصًا)\n حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے اس جز ’’شک میں ڈالنے والی چیزوں کو چھوڑ دے“ کی شرح میں فرماتے ہیں: یعنی جو کام یا کلام تمہارے دل میں کھٹکے کہ نہ معلوم حرام ہے یا حلال، اسے چھوڑ دو اور جس پر دل گواہی دے کہ یہ ٹھیک ہے اسے اختیار کرو، مگر یہ ان حضرات کے لئے ہے جو امام حَسَن ( رضی اللہ عنہ ) جیسی قوتِ قُدْسِیَہ و عِلمِ لَدُنّی والے ہوں جن کا فیصلَۂ قلب کتاب و سنت کے مطابق ہو عام لوگ یا جو نفسانی و شیطانی وَہمیات میں پھنسے ہوں ان کے لئے یہ قاعدہ نہیں، بعض لاپروا لوگ قطعی حراموں میں کوئی تَرَدُّد (شک) نہیں کرتے اور بعض وَہم پرست جائز چیزوں کو بلاوجہ حرام و مشکوک سمجھ لیتے ہیں ان کے لئے یہ قاعدہ نہیں ہے ۔(مراٰۃ المناجیح، 4/234)\n ابو زکریا یحییٰ بن شرف نووی رحمۃُ اللہ علیہ فرماتے ہیں: ’’متقی کو چاہئے کہ شبہے والے مال سے اس طرح بچے جیسے حرام سے بچتا ہے اور ایسا کھانا کھائے جس پر اس کا دل اور نفس مطمئن ہو۔‘‘ (شرح الاربعین النوویہ، الحدیث الحادی عشر، ص۶۲، ملخصًا)\n¥حکایت: اپنا دینار بھی چھوڑ دیا\nمنقول ہے کہ ایک بزرگ رحمۃُ اللہ علیہ کا ایک دینار گر گیا، وہ اسے ڈھونڈنے لگے ، انہیں ایک ساتھ دو دینار ملے لیکن انہیں یہ پتا نہ چلا کہ اُن کا دینار کون سا ہے تو انہوں نے (مشکوک ہو جانے کی وجہ سے) دونوں دینار چھوڑ دیئے۔ \n(قوت القلوب، الفصل الثامن والاربعون، ۲/ ۴۷۸)\n¥دعا:\nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6877, "bookId": 13, "volNo": "1", "hadithNo": 12, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "اسلام کی ایک خوبی", "arabic": "عَنْ اَبِيْ هُرَيْرَةَ رَضيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : ’’مِنْ حُسْنِ اِسْلَامِ الْمَرْءِ تَرْكُهٗ مَا لَا يَعْنِيْهِ.‘‘\n( حَدِيْثٌ حَسَنٌ، رَوَاهُ التِّرْمِذِيُّ وَغَيْرُهٗ ھٰکَذَا)", "urdu": "حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ آدمی کے اسلام کی خوبی میں سے یہ بھی ہے کہ وہ بے فائدہ کاموں کو چھوڑ دے ۔‘‘\n(ترمذی، كتاب الزھد، باب ماجاء من تکلم بالکلمة لیضحک الناس، ۴/ ۱۴۲، حدیث:۲۳۲۴)\n (یہ حدیث حسن ہے اسے حضرت سیِّدُنا امام ابو عیسیٰ محمد بن عیسیٰ ترمذی رحمۃ اللہ علیہ اور دیگر محدثین نے اسی طرح روایت کیا ہے۔)", "roman": "Hazrat Sayyiduna Abu Hurairah RadiyAllahu Anhu bayaan karte hain ke Rasoolullah Sallallahu Alayhi wa Sallam ne irshaad farmaya: ''Aadmi ke Islam ki khoobi mein se yeh bhi hai ke woh be-faida kaamon ko chhor de.''\n(Tirmizi, Kitaab-uz-Zuhd, Baab Ma Jaa'a man Takallama bil-Kalimati liyudhika-n-naas, 4/142, Hadees: 2324)\n(Yeh Hadees Hasan hai ise Hazrat Sayyiduna Imam Abu Eesa Muhammad bin Eesa Tirmizi Rahmatullah Alayh aur deegar Muhaddiseen ne isi tarah Riwayat kiya hai.)", "explanation": "¥مذکورہ حدیث پاک کی اہمیت:\n یہ حدیْثِ پاک بھی اُن اَحادیْثِ کریمہ میں سے ایک ہے جنہیں اِسلام کا مَدار قرار دیا گیا ہے۔ چنانچہ حضرت سیِّدُنا امام ابو داود رحمۃُ اللہ علیہ فرماتے ہیں کہ انسان کو اپنے دین کے لئے چار حدیثیں کافی ہیں۔ پھر آپ نے وہ چاروں حدیثیں بیان فرمائیں۔ مذکورہ حدیث شریف بھی ان میں سے ایک ہے۔\n(ارشاد الساری، کتاب بدء الوحی، باب کیف کان بدء الوحی، ۱/ ۹۵، تحت الحدیث:۱۔ تاریخ بغداد، ۹/ ۵۸،رقم:۴۶۳۸) \n¥مومن کو چاہئے کہ بےفائدہ باتوں کو چھوڑ دے:\nحضرت سیِّدُنا مُلّا علی قاری رحمۃُ اللہ علیہ اس حدیْثِ پاک کی شرح میں فرماتے ہیں: بندے کے اسلام کی خوبیوں اور کمال میں سے ہے کہ وہ ایسے کلام اور ایسی حرکات و سکنات سے بچے جو اس کے لئے دین و دنیا میں فا ئدہ مند نہ ہوں۔ ہمیشہ وہ کلام یا کام کرے جو دنیا یا آخرت کے لئے فائدہ مند ہو کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جنتیوں کو جنت میں ان لمحات پر افسوس ہوگا جنہیں اللہ پاک کے ذکر کے بغیرگزار دیا تھا۔‘‘ \n(مرقاة المفاتیح، کتاب الاداب، باب حفظ اللسان والغیبة والشتم، الفصل الثانی، ۸/ ۵۸۵، ۵۸۶، تحت الحدیث:۴۸۴۰، ملخصًا)\n لہٰذا بولنے سے پہلے خوب غور کر لینا چاہئے کہ یہ کام یا گفتگو میرے لئے دنیا وآخرت میں مفید ہے یا نہیں کسی نے سچ کہا ہے کہ ’’پہلے تولو پھر بولو۔‘‘یاد رکھیں زبان کی بےاحتیاطی انسان کو ہلاکت وبربادی میں مبتلا کر سکتی ہے۔پس ایسا کام یا ایسی بات جو بےفائدہ ہو اسے چھوڑ دینا چاہئے کہ مذکورہ حدیث شریف میں اسے بندے کے اسلام کی خوبی کہا گیا ہے اور سوچ سمجھ کر کلام کرنا چاہئے۔ چنانچہ\n¥گفتگو کی اقسام: \n حضرت سیِّدُنا امام محمد بن محمد بن محمد غزالی رحمۃُ اللہ علیہ فرماتے ہیں کہ کلام و گفتگو کی چار قسمیں ہیں: (1) مکمّل نقصان دہ،اس سے ہمیشہ پرہیز ضروری ہے، (2) مکمَّل فائدےمند بات، (3) ایسی بات جو نقصان دہ بھی ہو اور فائدے مند بھی، اس سے بھی بچنا لازم ہے اور (4) ایسی بات جس میں نہ فائدہ ہو نہ نقصان، یہ فضولیات میں شامل ہے کہ اس کا نہ تو کوئی فائدہ ہے اور نہ ہی کوئی نقصان، لہٰذا ایسی بات میں وقت ضائع کرنا بھی ایک طرح کا نقصان ہی ہے۔ رہی دوسری قسم جو مکمل فائدے مند ہے ، اس میں بھی باریک قسم کی رِیاکاری، بناوٹ، غیبت، جھوٹے مبالغے اور میں میں کرنے کی آفت یعنی اپنی فضیلت وپاکیزگی بیان کر بیٹھنے وغیرہ جیسے بےشمار اندیشے ہیں۔ نیز فائدہ مندگفتگو کرتے کرتے فُضُول باتوں میں جا پڑنے پھر اس کے ذَرِیعے مزید آگے بڑھتے ہوئے گناہ کا ارتِکاب ہو جانے جیسے خدشات شامل ہیں اوریہ شمولیت ایسی باریک ہے جس کاعِلْم نہیں ہوتا، لہٰذا اس قابلِ استِعمال بات کے ذَرِیعے بھی ا نسان خطرات میں گِھرا رہتا ہے۔(احیاء العلوم، ۳/ ۱۳۸، ملخصًا)\n¥بےفائدہ کلام:\n حضرت سیِّدُنا امام غزالی رحمۃُ اللہ علیہ مزید فرماتے ہیں: بےفائدہ کلام وہ ہے کہ اگر تم اسے نہ کرو تو نہ تمہیں کوئی گناہ ہو اورنہ ہی کسی قسم کا کوئی نقصان۔ اسے یوں سمجھئے کہ جیسے آپ اپنے کسی سفر کا حال لوگوں کے سامنے بیان کریں، دورانِ سفر لوگوں سے ملاقات کے واقعات، پسندیدہ کھانوں، کپڑوں پہاڑوں اور نہروں وغیرہ کا بیان کریں تو یہ ایسی باتیں ہیں کہ ان کے بیان نہ کرنے پر نہ تو کوئی گناہ ہے نہ فی الحال یا آئندہ کسی قسم کا کوئی نقصان اور یہ بھی اسی صورت میں ہے جبکہ واقعات میں اپنی طرف سے نہ تو جھوٹی مبالغہ آرائی ہو، نہ اپنا تزکیہ نفس بیان کیا گیا ہو اور نہ ہی کسی کی غیبت یا بُرائی بیان کی ہو۔ ان تمام باتوں کا خیال رکھنے کے باوجود ان واقعات کو بیان کرنے میں بہت ساقیمتی وقت ضائع ہو گیا ۔(احیاء العلوم، ۳/ ۱۴۰)\n¥فضول باتوں کا نقصان:\n حضرت سیِّدُنا امام غزالی رحمۃُ اللہ علیہ چار وجوہات کی بنا پر فضول باتوں کی مذمت بیان فرماتے ہیں: (1)…فُضُول باتیں (اعمال لکھنے والے بُزُرگ فِرِشتوں)کو لکھنی پڑتی ہیں، لہٰذا آدمی کو چاہئے کہ ان سے شرم کرے اور انہیں فضول باتیں لکھنے کی زحمت نہ دے۔ اللہ پاک ارشاد فرماتا ہے:\nمَا یَلْفِظُ مِنْ قَوْلٍ اِلَّا لَدَیْهِ رَقِیْبٌ عَتِیْدٌ(۱۸) (پ ۲۶، ق: ۱۸)\nترجمہ کنزالایمان: کوئی بات وہ زبان سے نہیں نکالتا کہ اس کے پاس ایک محافظ تیار نہ بیٹھا ہو۔\n (2)…یہ بات اچھّی نہیں کہ فضول باتوں سے بھرپور اعمال نامہ بارگاہِ الٰہی میں پیش ہو۔ (3)…اللہ پاک کے دربار میں تمام مخلو ق کے سامنے بندے کو حکم ہو گا کہ اپنا اعمال نامہ پڑھ کر سناؤ! اب قِیامت کی خوفناک سختیاں اس کے سامنے ہوں گی ،انسان بےلباس ہوگا، سخت پیاس اور بھوک سے کمر ٹوٹ رہی ہو گی، جنَّت میں جانے سے روک دیا گیا ہوگااورہر قسم کی راحت اُس پر بند کردی گئی ہوگی ( غور کیجئے ایسے تکلیف دِہ حالات میں فضول باتوں سے بھرپور اعمال نامہ پڑھ کر سنانا کس قدر پریشان کُن ہوگا)۔ (4)…بروزِقیامت بندے کوفُضول باتوں پر ملامت کی جائے گی اور اُسے شرمندہ کیا جائے گا۔ بندے کے پاس اس کا کوئی جواب نہ ہوگا اور وہ اللہ پاک کے سامنے شرم ونَدامت سے پانی پانی ہوجائے گا۔ (منھاج العابدین، ص۶۷)\n¥فضولیات سے بچنے کے فوائد:\n مسلمانوں کے دوسرے خلیفہ امیرالمؤمنین حضرت سیِّدُنا عُمَر فاروقِ اعظم رضی اللہ عنہ فضولیات سے بچنے کے فوائد بیان کرتے ہوئے فرماتے ہیں: فُضُول گوئی سے بچنے والے کو حکمت و دانائی عطا کی جاتی ہے۔فُضُول نگاہی یعنی بِلاضَرورت اِدھر اُدھر دیکھنے سے بچنے والے کو دِلی سکون ملتا ہے۔ فُضُول طَعام چھوڑنے والے کو عِبادت میں لذّت دی جاتی ہے۔ فضول ہنسنے سے بچنے والے کو رُعب و دبدبہ عنایت ہوتا ہے۔مذاق مسخری سے بچنے والے کو نورِ ایمان نصیب ہوتا ہے۔ دُنیا کی محبت سے بچنے والے کو آخِرت کی محبت دی جاتی ہے اوردوسروں کے عیب ڈھونڈنے سے بچنے والے کو اپنے عیبوں کی اصلاح کی توفیق ملتی ہے۔ (ماخوذ از المنبھات، ص۸۹)\n (نوٹ: گفتگو کے آداب، فضول باتوں سے بچنے اور زبان کی حفاظت کے متعلق تفصیلی معلومات کے لئے شیخ طریقت حضرت علامہ مولانا محمد الیاس عطار قادری دامت بَرَکاتُہمُ العالیہ کی مایہ ناز تصنیف ’’گفتگو کے آداب اور فضول باتوں سے بچنے کی فضیلت‘‘ کا مطالعہ کیجئے۔)\n¥دعا:\nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6878, "bookId": 13, "volNo": "1", "hadithNo": 13, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "کامل ایمان کی نشانی", "arabic": "عَنْ اَبِيْ حَمْزَةَ اَنَسِ بْنِ مَالِكٍ رَضيَ اللهُ عَنْهُ خَادِمِ رَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَن النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’لَا يُؤْمِنُ اَحَدُكُمْ حَتّٰى يُحِبَّ لِاَخِيْهِ مَا يُحِبُّ لِنَفْسِهٖ.‘‘(رَوَاہُ الْبُخَارِی وَمُسْلِم)", "urdu": "خادِمِ رسول ابو حمزہ حضرت سیِّدُنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: تم میں سے کوئی اس وقت تک (کامل) ایمان والا نہیں ہوسکتا جب تک کہ اپنے (مسلمان)بھائی کے لئے بھی وہی چیز پسند نہ کرے جووہ اپنے لئے پسند کرتا ہے۔(بخاری، كتاب الايمان، باب من الايمان ان یحب لاخیہ...الخ، ۱/ ۱۶، حدیث:۱۳ ۔ مسلم، کتاب الایمان، باب الدلیل علی ان من خصال الایمان...الخ، ص۴۷، حدیث: ۱۷۰)", "roman": "Khaadim-e-Rasool Abu Hamza Hazrat Sayyiduna Anas Bin Malik RadiyAllahu Anhu se Riwayat hai ke Huzoor Nabi Paak Sallallahu Alayhi wa Sallam ne irshaad farmaya: Tum mein se koi us waqt tak (kaamil) imaan wala nahi ho sakta jab tak ke apne (Musalman) bhai ke liye bhi wahi cheez pasand na kare jo woh apne liye pasand karta hai. (Bukhari, Kitaab-ul-Imaan, Baab minal Imaani an yuhibba li akheehi...alkh, 1/16, Hadees: 13. Muslim, Kitaab-ul-Imaan, Baab-ud-Daleel ala anna min Khisaal-il-Imaan...alkh, s. 47, Hadees: 170)", "explanation": "¥مذکورہ حدیث پاک کی اہمیت:\n یہ حدیْثِ پاک بھی اُن اَحادیْثِ کریمہ میں سے ایک ہے جنہیں اِسلام کا مَدار اور اُمُّ الاحادیث وجوامِعُ الکلِم قرار دیا گیا ہے۔ (نزہۃ القاری، 1/ 315، ملخصاً) چنانچہ حضرت سیِّدُنا امام ابو داود رحمۃُ اللہ علیہ فرماتے ہیں کہ انسان کو اپنے دین کے لئے چار حدیثیں کافی ہیں۔ پھر آپ نے وہ چاروں حدیثیں بیان فرمائیں۔ مذکورہ حدیث شریف بھی ان میں سے ایک ہے۔\n(ارشاد الساری، کتاب بدء الوحی، باب کیف کان بدء الوحی، ۱/ ۹۵، تحت الحدیث:۱۔ تاریخ بغداد، ۹/ ۵۸، رقم:۴۶۳۸)\n¥کمالِ ایمان کی نفی:\n حضرت سیِّدُنا حافظ ابن حجر عسقلانی رحمۃُ اللہ علیہ فرماتے ہیں: اِس حدیث پاک میں کمالِ ایمان کی نفی ہے یعنی کوئی شخص اس وقت تک کامل مومن نہیں ہوسکتا۔ اس لئے کہ کسی چیز کے نام کی نفی سے اس کے کامل ہونے کی نفی(بھی) ہوتی ہے ۔جیسا کہ اہْلِ عرب کا مقولہ ہے: ’’فُلَانٌ لَّیْسَ بِاِنْسَانٍیعنی فلاں شخص اِنسان نہیں ہے۔‘‘ مراد یہ ہے کہ وہ کامل انسان نہیں، نہ یہ کہ وہ انسان ہی نہیں ہے۔ (فتح الباری، کتاب الایمان، باب من الایمان ان یحب لاخیہ... الخ، ۲ / ۵۵، تحت الحدیث : ۱۳)\n¥پسندیدہ چیز سے مراد:\n حافظ ابن حجر عسقلانی رحمۃُ اللہ علیہ فرماتے ہیں: پسندیدہ چیز سے مرادیہ ہے کہ خیر اور نیکی کی جو چیز بھی اپنے لئے پسند کرے وہ اپنے بھائی کے لئے بھی پسند کرے۔ خیر ایک جامع لفظ ہے جس میں تمام نیکیاں، دینی اور دنیاوی تمام مباح یعنی جائز کام شامل ہیں اِس سے ممنوعہ یعنی ناجائز کام نکل گئے۔(فتح الباری، کتاب الایمان، باب من الایمان ان یحب لاخیہ... الخ، ۲ / ۵۵، تحت الحدیث : ۱۳)\n¥مذکورہ حدیث پاک کا ایک مفہوم:\nحضرت سیِّدُنا علامہ ابو الحسن ابن بطّال رحمۃُ اللہ علیہ بیان کرتے ہیں کہ بعض علمائے کرام رحمۃُ اللہ علیہم نے فرمایا: اِس حدیث شریف کا مطلب یہ ہے کہ لوگوں سے تکلیف دہ اور ناپسندیدہ چیزوں کو دُور کرےجیسا کہ حضرت سیدنا اَحْنَف بِن قَیْس رحمۃُ اللہ علیہ نے فرمایا کہ اگر مجھے کسی کی کوئی بھی بات یا کام ناپسند ہوتو میں بھی کسی اور کے ساتھ وہ بات یا کام نہیں کرتا۔ \n(شرح بخاری لابن بطال، کتاب الایمان، باب من الایمان ان یحب لاخیہ... الخ، ۱ / ۶۵)\n¥چند لفظوں میں دونوں جہاں کی خوبیاں جمع:\n مشہور شارحِ حدیث، حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ اس کی شرح میں فرماتے ہیں: یہ فرمانِ عالی حضور صلّی اللہ علیہ واٰلہٖ وسلّم کے جامع کلمات سے ہے ،اِن چند لفظوں میں دونوں جہاں کی خوبیاں جمع ہیں۔ کوئی شخص مؤمِن کامل اُس وقت تک نہیں ہوسکتا جب تک کہ اپنےمسلمان بھائی کے لئے دینی و دُنیاوی وہ چیز نہ پسند کرے جو اپنے لئے پسند کرتا ہے۔ خیال رہے کہ یہاں خیر یعنی اچھائی وبھلائی مراد ہے یعنی ہر مسلمان کے لئے دنیا و آخرت کی خیر پسند کرو جو اپنے لئے پسند کرتے ہو۔اپنے مسلمان بھائی کے لئے اچھائی وبھلائی کی پسند کا ظہور مختلف طریقوں سے ہوسکتا ہے۔مثلاً کسی کے لئے دولت مندی خیر ہے،کسی کےلئے فقیری خیر،کسی کےلئے خَلْوَتْ یعنی تنہائی خیر، تو کسی کےلئے جَلْوَتْ یعنی بِھیڑ خیر۔ لہٰذااگر کوئی مسلمان فقیر ہو اور اپنے لئے فقیری کو پسند کرتا ہو مگر اپنے بھائی کے لیے دولت مندی کو پسند کرے کہ اُسے دولت مندی ہی پسند ہے تو یہ اِس فرمان کے خلاف نہیں، اِسی طرح اگر کوئی خلوت نشین ہو یعنی تنہائی پسند ہو مگر وہ اپنے بھائی کے لئے جلوت پسند کرے کہ اُسے جلوت ہی پسند ہے تو یہ بھی اِس فرمان کے منافی نہیںوَعَلٰی ھٰذَا الْقِیَاس۔دراصل تمام مسلمانوں میں خیر ہی خیر ہے مگر ہرمسلمان میں اِس کی صورت مختلف ہے جیسا کہ پاور یعنی بجلی ایک ہی ہوتی ہے مگر ہیٹر میں پہنچے تو گرمی دیتی ہے اورفِرج میں پہنچے تو ٹھنڈک ۔ (مراٰۃ المناجیح، 6/ 555 ،ملخصاً)\n¥دل نشین اور بلیغ ترین کلام:\n فقیہ اعظم ہند حضرت مولانا مفتی محمد شریف الحق امجدی رحمۃُ اللہ علیہ اس کی شرح میں فرماتے ہیں: اس حدیث میں ایمان سے مراد ایمانِ کامل ہے، محبت کسی کی طرف دل کے میلان کو کہتے ہیں یہاں محبت سے مراد پسندیدگی ہے۔ مراد یہ ہے کہ کامل مومن وہی ہےجو اپنے مسلمان بھائی کے لئے وہی پسند کرے جو اپنے لئے پسند کرتا ہےاس کو لازم ہے کہ جوبات اپنے لئے ناگوار جانے وہ دوسروں کے لئے بھی ناپسند کرے ۔یعنی آدمی یہ چاہتا ہے کہ ہم آرام ، اعزاز کے ساتھ خوش وخرم رہیں، کوئی ہماری توہین وتذلیل نہ کرے ، کوئی ہمیں ایذاء نہ پہنچائے، کوئی ہمارا حق غصب نہ کرے، اسی طرح یہ بھی چاہیےکہ میرا بھائی اعزاز واکرام کے ساتھ خوش وخرم رہے، نہ اس کی توہین وتذلیل ہو، نہ اس کا حق غصب کیا جائے، اس سے بطورِ لزوم یہ بھی سمجھ میں آیاکہ ہر شخص اگر اس کا عادی ہوجائےتو معاشرہ صاف ستھرا رہے گااور زندگی چین واطمینان سے گذرے گی۔ظاہر ہے کہ لڑائی جھگڑا کی بنیاد یہی ہوتی ہے کہ انسان تنگ دلی سے یہ چاہنے لگتاہےکہ سب کچھ ہمیں میسر ہو دوسرے محروم رہیں۔ اس حدیث میں تواضع، مروت، امدادِ باہمی ایک دوسرے کے کام آنے اور دوسروں کے ساتھ اچھا سلوک کرنےکی بلیغ ترین ترغیب ہے۔ حسد، کینہ، عداوت، بغض، ایذا رسانی ، حق تلفی، تفوق، تَرفُّع، تحقیر وتذلیل سے دور رہنے کی انتہائی دلنشین پیرائے میں تلقین ہےاسی لئے علماء کرام نےاس حدیث کو بھی جوامع الکلم اور اُمّ الاحادیث سے شمار کیا ہے۔ ( نزھۃ القاری شرح صحیح البخاری، 1/314 )\n¥دنیاوی اور اخروی خیر سے مراد:\n حضرت سیِّدُنا شیخ عبد الحق محدث دہلوی رحمۃُ اللہ علیہ اس کی شرح میں فرماتے ہیں: خواہ اس شے کا تعلق دُنیوی خیر (بھلائی)سے ہو یا اُخروی خیر سے۔ اُخروی خیر یہ ہے کہ دوزخ کے عذاب سے نجات اور درجاتِ جنت کا حصول، ایسا ایمان نیک اَعمال کا تقاضا کرتا ہے۔ دُنیوی خیر سے مراد اَسبابِ زندگی اور اہْل و اولاد ہیں جو آخرت میں بھلائی کا ذریعہ ہیں۔ جب اِنسان اپنے لئے اِن دونوں کی خواہش کرتا ہے تو اُسے دوسرے تمام مسلمانوں کے لئے بھی یہی خواہش کرنی چاہیے۔\n(اشعۃ اللمعات ، کتاب الآداب ، باب الشفقۃ والرحمۃ علی الخلق ، 4/ 128)\n¥خیر خواہی سے متعلق تین روایات:\n(1)… اللہ پاک ارشاد فرماتا ہے: ’’میرے نزدیک بندے کی سب سے پسندیدہ عبادت لوگوں سے خیر خواہی کرناہے۔‘‘ \n(کنز العمال، کتاب الاخلاق، قسم الاقوال، الجزء: ۳، ۲/ ۱۶۶، حدیث:۷۱۹۷)\n(2)… مومن اس وقت تک اپنے دین (یعنی رحمَتِ الٰہی) کی وسعت میں رہتا ہے جب تک اپنے مسلمان بھائی کی خیرخواہی چاہتا ہے اور جب اس کی خیرخواہی سے الگ ہو جاتا ہے تو اس سے توفیق کی نعمت چھین لی جاتی ہے۔ \n(مسند الفردوس، باب اللام الف، ۲/ ۴۲۹، حدیث:۷۷۲۲)\n(3)… بروزِ قیامت جو پانچ چیزیں لے کر آئے گا اسے جنت سے نہیں روکا جائے گا: اللہ پاک، اس کے دین، اس کی کتاب، اس کے رسول اور مسلمانوں کی جماعت کی خیرخواہی۔ (کنز العمال، کتاب الاخلاق، قسم الاقوال، الجزء: ۳، ۲/ ۱۶۶، حدیث:۷۱۹۹)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6879, "bookId": 13, "volNo": "1", "hadithNo": 14, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "مسلمان کے خون کی حرمت", "arabic": "عَنِ ابْنِ مَسْعُوْدٍ رَضيَ اللهُ عَنْهُ قَالَ: قَالَ سُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : ’’لَا یَحِلُّ دَمُ امْرِیٍٔ مُّسْلِـمٍ اِلَّا بِاِحْدٰی ثَلَاثٍ اَلثَّیِّبِ الزَّانِی وَالنَّفْسِ بِالنَّفْسِ وَالتَّارِکِ لِدِیْنِہِ الْمُفَارِقِ لِلْجَمَاعَۃ. ‘‘(رَوَاہُ الْبُخَارِی وَمُسْلِم)", "urdu": "حضرت سیِّدُنا ابن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’کسی مسلمان شخص کا خون حلال نہیں سوائے یہ کہ تین میں سے کوئی ایک وجہ پائی جائے: (1)…شادی شدہ زانی، (2)… جان کے بدلے جان (قصاص) اور (3)… اپنے دین کوچھوڑ کرجماعت سے الگ ہونے والا۔‘‘ (بخاری، كتاب الديات، باب قول اللّٰہ تعالٰى: ان النفس بالنفس...الخ، ۴/ ۳۶۱، حدیث:۶۸۷۸ ۔ مسلم، کتاب القسامة، باب ما یباح بہ دم المسلم، ص۷۱۰، حدیث:۴۳۷۵)", "roman": "Hazrat Sayyiduna Ibn Mas'ood RadiyAllahu Anhu bayaan karte hain ke Rasool-e-Paak Sallallahu Alayhi wa Sallam ne irshaad farmaya: ''Kisi Musalman Shakhs ka khoon Halal nahi siwaye yeh ke teen mein se koi ek wajah payi jaye: (1)… Shaadi shuda zaani, (2)… Jaan ke badle jaan (qisaas) aur (3)… Apne deen ko chhor kar Jama'at se alag hone wala.'' (Bukhari, Kitaab-ud-Diyaat, Baab Qaul-illahi Ta'ala: Innan-Nafsa bin-Nafs...alkh, 4/361, Hadees: 6878. Muslim, Kitaab-ul-Qasaamah, Baab maa yubaahu bihi Damm-ul-Muslim, s. 710, Hadees: 4375)", "explanation": "¥مسلمان کو قتل کرنے کی صورتیں:\n یاد رکھئے! اسلام میں انسانی جان کی بے پناہ حرمت ہے اور کسی انسان کو قتل کرنا شدید کبیرہ گناہ ہے اور اس کی محدود صورتوں کے علاوہ کسی بھی طرح اجازت نہیں۔ (صراط الجنان، 5/ 458) مسلمان کے قتل کی بعض صورتیں مذکورہ حدیث پاک میں بیان ہوئی ہیں۔ جیسے: شادی شدہ زانی، جان کے بدلے جان اور مرتد یعنی اسلام سے پھرنے والا۔¥\n’’اِمرءٌ‘‘ سے مراد:\n حدیث پاک میں ”امرءٌ“ ( یعنی شخص) سے مراد مطلق انسان ہے (چاہے) مرد ہو یا عورت،صرف مرد مراد نہیں کیونکہ یہ احکام عورت پر بھی جاری ہیں۔ (مراٰۃ المناجیح ،5/213)\n¥شادی شدہ زانی سے مراد:\n آزاد مسلمان مرد (یا عورت) جو ایک بار حلال ہم بستری کرچکے ہوں اگر وہ زنا کر لیں توانہیں رجم یعنی سنگسار کیا جائے گا۔(ماخوذ ازمراٰۃ المناجیح ،5/214)\n¥قصاص کی کچھ تفصیل:\n اگر کوئی مسلمان کسی کو عمداً (جان بوجھ کر) قتل کردے تو مقتول کا ولی اسے قصاصًا قتل کراسکتا ہے۔(مراٰۃ المناجیح ،5/213) قصاص میں قتل کرنا یعنی قتل کے بدلے قتل اور یہ بھی قاضی کے فیصلے کے بعد ہے ، یہ نہیں کہ بغیر قاضی کے فیصلے کے خود ہی قصاص لیتے پھریں ، اس کی ہرگز ہرگز اجازت نہیں ۔ پھر قصاص میں قتل کی اجازت کے ساتھ اس کی بھی حدود و قُیود بیان فرمائی ہیں کہ قصاص میں قتل کرنے میں بھی مقتول کا وارث حد سے نہ بڑھے جیسے زمانَۂ جاہلیت میں ایک مقتول کے عِوض میں کئی کئی لوگوں کو قتل کردیا جاتا تو فرمایا گیا کہ صرف قاتل سے قصاص لیا جائے گا ، کسی اور سے نہیں۔ نیز قصاص لینے کا حق ولی کو ہے اور ولی میں وہی ترتیب ہے جو رشتے داروں کی ایک خاص قسم میں ہے اور جس کا ولی نہ ہو اس کا ولی سلطان ہے۔ پھر یہ کہ قصاص حَقُّ العبد ہے، اگر ولی چاہے تو معاف کردے۔ کتنے افسوس کی بات ہے کہ اسلام میں انسانی جان کی کس قدر حرمت بیان کی گئی ہے اور آج ہمارے معاشرے کا حال یہ ہے کہ جس کا دل کرتا ہے وہ بندوق اٹھاتا ہے اور جس کو دل کرتا ہے قتل کردیتا ہے، کہیں سیاسی وجوہات سے، تو کہیں علاقائی اور صوبائی تَعَصُّب کی وجہ سے۔ ان میں سے کوئی بھی صورت جائز نہیں ہے۔ قتل کی اجازت صرف مخصوص صورتوں میں حاکِمِ اسلام کو ہے اور کسی کو نہیں۔(صراط الجنان، 5/ 458،ملخصاً)\n¥دین سے نکل جانے کی صورتیں:\n دین سے نکل جانے کی دو صورتیں ہیں: یا تو اسلام کو چھوڑکر یہودی،عیسائی،ہندو وغیرہ دوسری ملت میں داخل ہو جائے یا کلمہ گو تو رہے مگر کوئی کفریہ عقیدہ اختیارکرے ۔(مراٰۃ المناجیح ،5/214)\n¥قتل ناحق کی مذمت و وعید پر آیاتِ مبارکہ:\n اللہ پاک قرآن مجید میں قتل ناحق کی مذمت بیان کرتے ہوئے ارشاد فرماتا ہے:\nوَ مَنْ یَّقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا فَجَزَآؤُهٗ جَهَنَّمُ خٰلِدًا فِیْهَا وَ غَضِبَ اللّٰهُ عَلَیْهِ وَ لَعَنَهٗ وَ اَعَدَّ لَهٗ عَذَابًا عَظِیْمًا(۹۳) (پ ۵، النسآء: ۹۳)\nترجمہ کنزالایمان: اور جو کوئی مسلمان کو جان بوجھ کر قتل کرے تو اس کا بدلہ جہنم ہے کہ مدتوں اس میں رہے اور اللہ نے اس پر غضب کیا اور اس پر لعنت کی اور اس کے لیے تیار رکھا بڑا عذاب۔\n ایک اور جگہ ارشاد فرمایا:\nاَنَّهٗ مَنْ قَتَلَ نَفْسًۢا بِغَیْرِ نَفْسٍ اَوْ فَسَادٍ فِی الْاَرْضِ فَكَاَنَّمَا قَتَلَ النَّاسَ جَمِیْعًاؕ \n (پ ۶، المآئدة: ۳۲)\nترجمہ کنزالایمان: جس نے کوئی جان قتل کی بغیر جان کے بدلے یا زمین میں فساد کے تو گویا اس نے سب لوگوں کو قتل کیا۔\n¥قتْلِ ناحق کی مذمت و وعید پر احادیْثِ مبارکہ:\n احادیث مبارکہ میں بھی قتل ناحق کی مذمت بیان ہوئی ہے۔ چنانچہ حضرت سیِّدُنا عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ اللہ پاک کے آخری نبی، محمد عربی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ سب سے پہلے خونِ ناحق کے بارےمیں لوگوں کے درمیان فیصلہ کیا جائے گا۔‘‘(بخاری، کتاب الدیات، باب قول اللّٰہ تعالٰی: وَ مَنْ یَّقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا...الخ، ۴/ ۳۵۷، حدیث:۶۸۶۴)\n حضرت سیِّدُنا ابو سعید اور حضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہما سے روایت ہے کہ اللہ پاک کے پیارے حبیب صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اگر آسمان وزمین والے ایک مرد مومن کے خون میں شریک ہو جائیں تو اللہ پاک سب کو اوندھا کر کے جہنم میں ڈال دے گا۔‘‘(ترمذی، کتاب الدیات، باب الحکم فی الدمآء، ۳/ ۱۰۰، حدیث:۱۴۰۳)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6880, "bookId": 13, "volNo": "1", "hadithNo": 15, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "اچھی بات کرنا، مہمان اور پڑوسی کی عزت کرنا", "arabic": "عَنْ اَبِيْ هُرَيْرَةَ رَضيَ اللهُ عَنْهُ عَنْ رَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’مَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْاٰخِرِ فَلْيَقُلْ خَيْرًا اَوْ لِيَصْمُتْ وَمَنْ كَانَ يُؤمِنُ بِاللهِ وَالْيَوْمِ الْاٰخِرِ فَلْيُكْرِمْ جَارَهٗ ومَنْ كَانَ يُؤْمِنُ بِاللهِ والْيَوْمِ الْاٰخِرِ فَلْيُكْرِمْ ضَيْفَهٗ. ‘‘ \n(رَوَاہُ الْبُخَارِی وَمُسْلِم)", "urdu": "حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو شخص اللہ پاک اور قیامت کے دن پر ایمان رکھتا ہے اسے چاہئے کہ اچھی بات کہے یا خاموش رہےاور جو شخص اللہ پاک اور قیامت کے دن پر ایمان رکھتا ہے اسے چاہئے کہ اپنے پڑوسی کی عزت کرے اور جو شخص اللہ پاک اور قیامت کے دن پر ایمان رکھتا ہےاسے چاہئے کہ اپنےمہمان کا احترام کرے۔‘‘(بخاری، كتاب الادب، باب من كان يؤمن باللّٰہ ...الخ، ۴/ ۱۰۵،حدیث:۶۰۱۸ ۔ مسلم، کتاب الایمان، باب الحث علی اکرام الجار...الخ، ص۴۸، حدیث:۱۷۳)", "roman": "Hazrat Sayyiduna Abu Hurairah RadiyAllahu Anhu se Marwi hai ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne irshaad farmaya: ''Jo Shakhs Allah Paak aur Qiyamat ke din par imaan rakhta hai use chahiye ke achhi baat kahe ya khamosh rahe aur jo Shakhs Allah Paak aur Qiyamat ke din par imaan rakhta hai use chahiye ke apne padosi ki izzat kare aur jo Shakhs Allah Paak aur Qiyamat ke din par imaan rakhta hai use chahiye ke apne mehmaan ka ehtiram kare.'' (Bukhari, Kitaab-ul-Adab, Baab man kaana yu'minu billah...alkh, 4/105, Hadees: 6018. Muslim, Kitaab-ul-Imaan, Baab-ul-Hass ala Ikraam-il-Jaar...alkh, s. 48, Hadees: 173)", "explanation": "مذکورہ حدیث شریف میں کامل مومن کی تین صفات بیان کی گئی ہیں۔ ان کی کچھ مختصر وضاحت ملاحظہ فرمائیں۔ چنانچہ ¥\nپہلی صفت: ¥اچھی بات کہے یا خاموش رہے\n حدیث پاک میں مذکور لفظ ’’خیر‘‘ سے اچھی بات مراد ہے، خواہ وہ اچھی بات فرض، واجب، سنت یا مستحب ہو یا کوئی بھی جائز بات ہو مگر بہت زیادہ جائز باتیں کرنے سے بھی پرہیز کرنا چاہیے کہ بندہ کہیں ناجائز بات میں نہ پھنس جائے کیونکہ زیادہ بولنے سے اکثر ناجائز باتیں منہ سے نکل جاتی ہیں۔ مشہور مقولہ ہے:”جو خاموش رہا وہ سلامت رہا جو سلامت رہا وہ نجات پا گیا۔“ پچانوے فیصد گناہ زبان سے ہوتے ہیں اور پانچ فیصد گناہ دوسرے اعضاء سے۔ مطلب یہ ہے کہ مومِن کامل وہ ہے جو بھلی بات منہ سے نکالے ورنہ خاموش رہے۔ خیال رہے کہ بات ہی ایمان ہے، بات ہی کفر، بات ہی مقبول ہے، بات ہی مُردود۔(ماخوذ اَز مِراٰۃ المناجیح، 6/53)\n¥تمہارے حق میں یا تمہارے خلاف:\n ایک طویل حدیث پاک کے آخر میں اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم کا ارشاد ہے: جو تم کہتے ہو وہ یا تو تمہارے حق میں ہوتا ہے یا تمہارے خلاف ہوتا ہے، لوگوں کو منہ کے بل جہنم میں گرانے والی ان کے منہ سے نکلی ہوئی باتیں ہی تو ہیں۔ (ترمذی، کتاب الایمان ، باب ماجا ء فی حرمة الصلاة ، ۴/ ۲۸۰،حدیث:۲۶۲۵ ، مفھومًا)\n¥پہلے تولو پھر بولو:\n حضرت سیِّدُنا امام محمد بن ادریس شافعی رحمۃُ اللہ علیہ فرماتے ہیں: ’’اچھی بات کہنے سے پہلے بھی غور کرلو، جب ظاہر ہو جائے کہ جو بات کرنی ہے اس میں صرف بھلائی ہے،فساد نہیں اور نہ ہی وہ بات حرام یا مکروہ کی طرف لے جانے والی ہے تو ہی کرو۔‘‘ پس اگر انسان اچھی بات نہیں کہہ سکتا تو اسے چاہئے کہ خاموش رہے مباح بات بھی نہ کرے کیونکہ بعض اوقات مباح کلام بھی حرام یا مکروہ کی طرف لے جاتا ہے اور بالفرض اگر مباح کلام حرام یا مکروہ کی طرف لے جانے والا نہ بھی ہو پھر بھی اس میں وقت کا ضیاع تو ہے کہ یہ فضول کام ہے۔(دلیل الفالحین، باب فی حق الجار والوصیة بہ، ۲/ ۱۳۹ تا ۱۴۰، تحت الحدیث: ۳۰۹، ملخصًا)\nدوسری صفت: ¥اپنے پڑوسی کی عزت کرے\n اللہ پاک نے قرآنِ مجید میں پڑوسیوں کے ساتھ بھلائی کرنے کا حکم دیتے ہوئے ارشاد فرمایا:\nوَ اعْبُدُوا اللّٰهَ وَ لَا تُشْرِكُوْا بِهٖ شَیْــٴًـا وَّ بِالْوَالِدَیْنِ اِحْسَانًا وَّ بِذِی الْقُرْبٰى وَ الْیَتٰمٰى وَ الْمَسٰكِیْنِ وَ الْجَارِ ذِی الْقُرْبٰى وَ الْجَارِ الْجُنُبِ وَ الصَّاحِبِ بِالْجَنْۢبِ وَ ابْنِ السَّبِیْلِۙ-وَ مَا مَلَكَتْ اَیْمَانُكُمْؕ- (پ ۵، النسآء: ۳۶)\nترجمہ کنزالایمان: اور اللہ کی بندگی کرو اور اس کا شریک کسی کو نہ ٹھہراؤ اور ماں پاب سے بھلائی کرو اور رشتہ داروں اور یتیموں اور محتاجوں اور پاس کے ہمسائے اور دور کے ہمسائے اور کروٹ کے ساتھی اور راہ گیر اور اپنی باندی غلام سے۔\n¥قریب اور دور کے ہمسائے:\n اس آیت مبارکہ میں اللہ پاک نے اپنی عبادت کرنے اور کسی کو شریک نہ ٹھہرانے کا حکم دینے کے بعد والدین ، رشتہ داروں ، یتیموں اور مسکینوں کے ساتھ بھلائی کرنے کا حکم دیا اور ان کے بعد قریب اور دور دونوں طرح کے پڑوسیوں سے بھلائی اور اچھا سلوک کرنے کا حکم ارشاد فرمایا ہے۔ ان پڑوسیوں کے بارے میں دعوت اسلامی کے اشاعتی ادارے ’’مکتبۃ المدینہ‘‘ کی مطبوعہ 495 صفحات پر مشتمل کتاب ’’صراط الجنان، جلد2 ،صفحہ201‘‘ پر ’’تفسیراتِ احمدیہ‘‘ کے حوالے سے لکھا ہے کہ ’’قریب کے ہمسائے سے مراد وہ ہے جس کا گھر اپنے گھر سے ملا ہوا ہوا ور دور کے ہمسائے سے مراد وہ ہے جو محلہ دار تو ہو مگر اس کا گھر اپنے گھر سے ملا ہوا نہ ہو ، یا جو پڑوسی بھی ہو اور رشتہ دار بھی وہ قریب کا ہمسایہ ہے اور وہ جو صرف پڑوسی ہو ، رشتہ دار نہ ہو وہ دور کا ہمسایہ ، یا جو پڑوسی بھی ہو اورمسلمان بھی وہ قریب کا ہمسایہ اور وہ جو صر ف پڑوسی ہو مسلمان نہ ہو وہ دور کا ہمسایہ ہے۔‘‘ (ماخوذ از تفسیرات احمدیة ، النسآء ، تحت الاٰیة: ۳۶ ، ص۲۷۵)\n ایک وہ پڑوسی ہوتا ہے، جس کی دیوار ہمارے گھر کی دِیوار کے ساتھ ملتی ہے مگر اُس کا دروازہ ہمارے دروازے سے دُور ہوتا ہے،جس کا دروازہ ہمارے دروازے کے قریب ہو وہ قریب کا پڑوسی اور جس کا دروازہ دُور ہو وہ دُورکا پڑوسی ہے۔ چنانچہ مؤمنین کی ماں حضرت سیِّدَتُنا عائشہ صدّیقہ رضی اللہ عنہا کا بیان ہے کہ ایک روز میں نے بارگاہِ رسالت میں عرض کی: یا رسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! میرےدو پڑوسی ہیں، ان میں سے تحفہ کسے دیا کروں؟ ارشاد فرمایا: ’’جس کا دروازہ تم سے قریب ہے۔‘‘ ) بخاری ، کتاب الھبة...الخ، باب بمن یبدأ بالھدیة، ۲/ ۱۷۴، حدیث:۲۵۹۵)\n¥پڑوس کہاں تک ہے؟\n حدیْثِ پاک میں ہے کہ رسولِ خدا صلّی اللہ علیہ واٰلہٖ وسلّم کے حکم سے حضرت سیِّدُنا ابوبکر، حضرت سیِّدُنا عمر فاروق اور حضرت سیِّدُنا علی المرتضیٰ رضی اللہ عنہم مسجد کے دروازے پر کھڑے ہوئے اور بلند آواز سے کہنے لگے: سنو! 40 گھر پڑوسی ہیں اور وہ شخص جنت میں نہیں جائے گا جس کا پڑوسی اس کے شر سے خوفزدہ ہوا۔ (معجم کبير، ۱۹/ ۷۳، حدیث:۱۴۳)\n¥پڑوسی کون ہے؟\nحدیث پاک میں مذکور لفظ ’’پڑوسی‘‘ عام ہے، لہٰذا پڑوسی خواہ مسلمان ہو یاکافر، عابدہو یا فاسق، دوست ہو یا دُشمن، پردیسی ہو یا ہم وطن، نقصان پہنچانے والا ہو یا نفع دینے والا، رشتہ دار ہو یا اجنبی، اس کا گھر قریب ہو یا دور سب ہی اس میں داخل ہیں۔ (ارشاد الساری ، کتاب الادب ، باب الوصاءة بالجار، ۱۳ / ۴۸ ، تحت الحدیث: ۶۰۱۴)\n¥حقوق کے اعتبار سے پڑوسیوں کی اقسام:\nواضح رہے کہ پڑسیوں میں اگرچہ سب ہی داخل ہیں لیکن حقوق کے اعتبار سے ان میں فرق ہے جیساکہ حضرت سیِّدُنا جابر رضی اللہ عنہ بیان کرتے ہیں: نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا کہ ’’پڑوسی تین ہیں: (1) وہ پڑوسی جس کا ایک حق ہے اور حق کے اعتبار سے یہ ادنیٰ پڑوسی ہے۔ (2) وہ پڑوسی جس کے دو حق ہیں اور (3) وہ پڑوسی جس کے تین حق ہیں اور حق کے اعتبار سے یہ افضل پڑوسی ہے۔ بہر حال وہ پڑوسی جس کا ایک حق ہے تو یہ وہ مشرک پڑوسی ہے جس کے ساتھ کوئی رشتہ داری نہیں صرف حَقِّ پڑوس ہے۔ جس کے دو حق ہیں تو یہ وہ مسلمان پڑوسی ہے جو رشتہ دار نہیں ، اس کے لئے دو حق ہیں،حَقِّ اسلام اور حَقِّ پڑوس۔ وہ پڑوسی جس کے تین حق ہیں تو یہ وہ مسلمان پڑوسی ہے جس کے ساتھ رشتہ داری ہو ، اس کے لئے حَقِّ اسلام، حَقِّ پڑوس اور رشتہ داری کا حق ہے۔‘‘ (حلیة الاولیاء، عطاء بن میسرة، ۵/ ۲۳۵، حدیث: ۶۹۴۸)\n¥پڑوسی کے حقوق:\n حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا کہ پڑوسی کے 11 حق ہیں: (1) جب اسے تمہاری مدد کی ضرورت ہو تو اس کی مدد کرو، (2) اگر معمولی قرض مانگے تو دے دو، (3) اگر وہ غریب ہو تو اس کا خیال رکھو، (4) بیمار ہو تو مزاج پرسی بلکہ ضرورت ہو تو تیمارداری کرو، (5) مرجائے تو جنازہ کے ساتھ جاؤ، (6) اس کی خوشی میں خوشی کے ساتھ شرکت کرو، (7) اس کے غم و مصیبت میں ہمدردی کے ساتھ شریک رہو، (8) اپنا مکان اتنا اونچا نہ بناؤ کہ اس کی ہوا روک دو مگر اس کی اجازت سے (بنا سکتے ہو)، (9) گھر میں پھل فروٹ آئے تو اسے ہدیۃً بھیجتے رہو، نہ بھیج سکو تو خفیہ رکھو اس پر ظاہر نہ ہونے دو، تمہارے بچے اس کے بچوں کے سامنے نہ کھائیں، (10) اپنے گھر کے دھوئیں سے اسے تکلیف نہ دو اور (11) اپنے گھر کی چھت پر ایسے نہ چڑھو کہ اس کی بے پردگی ہو۔ قسم اس کی جس کے قبضہ میں میری جان ہے! پڑوسی کے حقوق وہ ہی ادا کر سکتا ہے جس پر اللہ پاک رحم فرمائے۔(مكارم الاخلاق للخرائطی، باب ماجاء فی حفظ الجار وحسن مجاورتہ من الفضل، ص۵۹، حدیث:۱۰۴)\nتیسری صفت: ¥اپنے مہمان کا احترام کرے\n مہمانوں کی عزّت و تکریم اور خاطرتواضع اسلامی معاشرے کی اعلیٰ تہذیب اور بلندیِ اَخلاق کی روشن علامت ہے۔ اسلام نے مہمان نوازی کی بہت ترغیب دلائی ہے۔ جیسے مذکورہ حدیث شریف کہ ’’ جو شخص اللہ پاک اور قیامت کے دن پر ایمان رکھتا ہےاسے چاہئے کہ اپنےمہمان کا احترام کرے۔‘‘ اسی طرح دیگر احادیث مبارکہ میں بھی مہمان کے احترام کی ترغیب ارشاد فرمائی گئی ہے۔ چنانچہ\n¥مہمان کی عزت واحترام سے متعلق احادیْثِ مبارکہ:\n حضرت سیِّدُنا عبد اللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جس نے نَماز قائم کی، زکوٰۃ ادا کی ، حج کیا، رَمَضان کے روز ے رکھے اور مہمان کی مہمان نوازی کی،وہ جنّت میں داخِل ہوگا۔‘‘ (معجم کبیر، ۱۲/ ۱۰۶، حدیث: ۱۲۶۹۲) \n حضرت سیِّدُنا ابن عباس رضی اللہ عنہما سے مروی ہے کہ ’’آدمی کی کم عقلی ہے کہ وہ اپنے مہمان سے خدمت لے۔‘‘\n(جامع صغیر، ص۲۸۸، حدیث: ۴۶۸۶)\n حضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بےشک سنت سے ہے کہ آدمی مہمان کو دروازے تک رخصت کرنے جائے۔‘‘ (ابن ماجہ، کتاب الاطعمة، باب الضیافة، ۴/ ۵۲، حدیث:۳۳۵۸)\n¥مہمان کا احترام:\n مہمان کا احترام یہ ہے کہ اس سے خندہ پیشانی سے ملے اس کے لیے کھانے اور دوسری خدمات کا انتظام کرے حتَّی الامکان اپنے ہاتھ سے اس کی خدمت کرے،بعض حضرات خود مہمان کے آگے دسترخوان بچھاتے اس کے ہاتھ دھلاتے ہیں یہ اسی حدیث پر عمل ہے،بعض لوگ مہمان کے لیے بقدرِ طاقت اچھا کھانا پکاتے ہیں وہ بھی اس عمل پر ہے جسے کہتے ہیں مہمان کی خاطر تواضع۔(مراٰۃ المناجیح ،6/52)\n¥کمال ایمان کی علامت:\n اس حدیث کا مطلب یہ نہیں کہ جو مہمان کی خدمت نہ کرے وہ کافر ہے۔ بلکہ مطلب یہ ہے کہ مہمان کی تعظیم اور اور اس کی خاطر داری ایمان کا تقاضا اور کمالِ ایمان کی علامت ہے۔(مراٰۃ المناجیح ،6/52 ،ملخصاً)\n¥مہمان اور ملاقاتی میں فرق:\nمفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں: ہمارا مہمان وہ ہے جو ہم سے ملاقات کے لیے باہر سے آئے خواہ اُس سے ہماری واقفیت پہلے سے ہو یا نہ ہو جو ہمارے لئے اپنے ہی محلہ یا اپنے شہر میں سے ہم سے ملنے آئے دو چار منٹ کے لئے وہ ملاقاتی ہے مہمان نہیں۔ اس کی خاطر تو کرو مگر اس کی دعوت نہیں ہے اور جوناواقف شخص اپنے کام کے لئے ہمارے پاس آئے وہ مہمان نہیں جیسے حاکم یا مفتی کے پاس مقدمہ والے یا فتویٰ والے آتے ہیں یہ حاکم کے مہمان نہیں۔(مراٰۃ المناجیح ،6/54)\n¥مہمانی کب تک ہے؟\n’’بہار شریعت، حصہ 16، جلد3، صفحہ 391‘‘ پر ہے: حضرت سیِّدُنا ابو شریح کعبی رضی اللہ عنہ سے مروی ہے کہ رسولِ اکرم صلّی اللہ علیہ وسلّم نے ارشاد فرمایا: جو شخص اللہ پاک اور قیامت کے دن پر ایمان رکھتے ہے وہ مہمان کا اکرام کرے، ایک دن رات اُس کا جائزہ ہے (یعنی ایک دن اس کی پوری خاطر داری کرے، اپنے مقدور بھر اس کے لئے تکلف کا کھانا تیّار کرائے) اور ضِیافت تین دن ہے (یعنی ایک دن کے بعد تکلُّف نہ کرے بلکہ جو حاضِر ہو وہی پیش کردے) اور تین دن کے بعد صدقہ ہے، مہمان کے لیے یہ حلال نہیں کہ اس کے یہاں ٹھہرا رہے کہ اسے حرج میں ڈال دے۔ (بخاری، کتاب الادب، باب اکرام الضیف...الخ، ۴/ ۱۳۶، حدیث: ۶۱۳۵)\n¥اپنارزق لاتا اور گناہ بخشواتا ہے:\nحضرت سیِّدُنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ ’’جب کوئی مہمان کسی کے یہاں آتا ہے تو اپنا رِزق لے کر آتا ہے اور جب جاتا ہے تو صاحِبِ خانہ کے گناہ بخشے جانے کا سبب ہوتا ہے۔‘‘ \n(کنز العمال، کتاب الضیافة، من قسم الاقوال، الفصل الاول فی الترغیب فی الضیافة، الجزء الاول، ۵/ ۱۰۷، حدیث:۲۵۸۳۱)\n¥مہمان اور میزبان کے کچھ آداب:\n * مہمان کو چاہئے کہ اپنے میزبان کی مصروفیات اور ذِمّے داریوں کا لحاظ رکھے۔ * جب آپ کسی کے پاس بطورِ مہمان جائیں تو مُناسب ہے کہ اچّھی اچھّی نیّتوں کے ساتھ حسبِ حیثیت میزبان یااُس کے بچّوں کے لئے تحفے لیتے جائیے * حضرت علّامہ مولانا مفتی محمد امجد علی اعظمی رحمۃُ اللہ علیہ ’’بہار شریعت، حصہ 16، جلد3، صفحہ 394‘‘ پر نقل فرماتے ہیں کہ مہمان کو چار باتیں ضَروری ہیں: (1) جہاں بٹھایا جائے وہیں بیٹھے، (2) جو کچھ اس کے سامنے پیش کیا جائے اس پر خوش ہو، یہ نہ ہو کہ کہنے لگے:اس سے اچھا تو میں اپنے ہی گھر کھایا کرتا ہوں یا اسی قسم کے دوسرے الفاظ، (3) بِغیر اجازتِ صاحِبِ خانہ (یعنی میزبان سے اجازت لئے بِغیر) وہاں سے نہ اُٹھے اور (4) جب وہاں سے جائے تو اس کے لیے دُعا کرے۔(فتاوی ھندیة، کتاب الکراھیة، الباب الثانی عشر فی الھدایا والضیافات، ۵/ ۳۴۴، ۳۴۵) * میزبان کو بالکل خاموش نہ رہنا چاہیے اور یہ بھی نہ کرنا چاہیے کہ کھانا رکھ کر غائب ہوجائے بلکہ وہاں حاضر رہے۔(فتاوی ھندیة، کتاب الکراھیة، الباب الثانی عشر فی الھدایا والضیافات، ۵/ ۳۴۵) * مہمانوں کے سامنے خادم وغیرہ پر ناراض نہ ہو(ایضاً) * میزبان کو چاہیے کہ مہمان کی خاطرداری میں خود مشغول ہو، خادموں کے ذ مّے اس کو نہ چھوڑے کہ یہ حضرت سیِّدُنا ابراہیم خلیلُ اللّٰہ علیہِ السّلام کی سنّت ہے۔ (ایضاً) مہمان کے ساتھ کھائے بھی کہ جو شخص اپنے بھائیوں ( مہمانوں) کے ساتھ کھاتا ہے اُس سے حساب نہ ہو گا۔ ( قوت القلوب، ۲/ ۳۰۶)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6881, "bookId": 13, "volNo": "1", "hadithNo": 16, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "غصہ نہ کرو", "arabic": "عَنْ اَبِيْ هُرَيْرَةَ رَضيَ اللهُ عَنْهُ اَنَّ رَجُلًا قَالَ لِلنَّبيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : اَوْصِنِيْ. قَالَ: ’’لَاتَغْضَبْ.‘‘ فَرَدَّدَ مِرَارًا. قَالَ: ’’لَاتَغْضَبْ.‘‘\n (رَوَاہُ الْبُخَارِی)", "urdu": "حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ ایک شخص نے رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم کی خدمت میں عرض کی: مجھے نصیحت کیجئے۔ آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’غصہ نہ کیا کرو۔‘‘ اس نے کئی بار یہی عرض کی تو آپ نے (وہی)ارشاد فرمایا کہ ’’غصہ نہ کیا کرو۔‘‘ (بخاری، كتاب الادب، باب الحذر من الغضب، ۴/ ۱۳۱، حدیث:۶۱۱۶)", "roman": "Hazrat Sayyiduna Abu Hurairah RadiyAllahu Anhu se Marwi hai ke ek Shakhs ne Rasool-e-Kareem Sallallahu Alayhi wa Sallam ki khidmat mein arz ki: Mujhe naseehat kijiye. Aap Sallallahu Alayhi wa Sallam ne irshaad farmaya: ''Gussa na kiya karo.'' Us ne kayi baar yahi arz ki to Aap ne (wahi) irshaad farmaya ke ''Gussa na kiya karo.'' (Bukhari, Kitaab-ul-Adab, Baab-ul-Hazar minal Ghadab, 4/131, Hadees: 6116)", "explanation": "¥غصہ کی تعریف:\n غضب یعنی غصہ نفس کے اس جوش کا نام ہے جو دوسرے سے بدلہ لینے یا اسے دفع (دور) کرنے پر ابھارے۔غصہ اچھا بھی ہے اور برا بھی،اللہ (پاک)کے لیے غصہ اچھا ہے جیسے مجاہد غازی کو کفار پر یا کسی واعِظ عالِم کو فُسّاق و فُجّار پر یا ماں باپ کو نافرمان اولاد پر آوے اور بُرا بھی ہوتا ہے جیسے وہ غصہ جو نفسانیت کے لیے کسی پر آوے۔ (مراٰۃ المناجیح، 6/ 655)\n¥غصہ نہ کرنے سے کیا مراد ہے؟\n حضرت سیِّدُنا حافظ ابن حجر عسقلانی رحمۃُ اللہ علیہ بیان کرتے ہیں: حضرت سیِّدُنا امام خطابی رحمۃُ اللہ علیہ فرماتے ہیں کہ ’’لَاتَغْضَب‘‘ کا معنیٰ ہے: غصے کے اَسباب سے بچ اور غصے کی وجہ سے جو کیفیت ہوتی ہے اسے اپنے اوپرطاری مت کر، یہاں پر نَفسِ غُصّہ سے منع نہیں کیاگیا کیونکہ وہ تو طبعی چیز ہے جو کہ انسان کی فطرت میں موجود ہوتا ہے۔ بعض حضرات فرماتے ہیں کہ ’’جو شخص بارگاہِ رسالت میں نصیحت کا طالب ہوا تھا شاید ان کا مزاج بہت تیز اورطبیعت میں غصہ زیادہ تھا اور حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم کی یہ عادتِ مبارکہ تھی کہ ہر ایک کو اس کی طبیعت کے مطابق حکم ارشاد فرماتے، اسی لئے آپ نے انہیں غصہ ترک کرنے کی وصیت فرمائی۔‘‘(فتح الباری، کتاب الادب، باب الحذر من الغضب، ۱۱/ ۴۳۹، تحت الحدیث:۶۱۱۶)\n¥ایک جملے میں دنیا وآخرت کی بھلائی:\n حضرت سیِّدُنا اِبْنِ تِیْن رحمۃُ اللہ علیہ فرماتے ہیں کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے اپنے اس جملے ’’لَا تَغْضَب‘‘ میں دنیا و آخرت کی بھلائی جمع فرمادی کیونکہ غُصّہ اِنسان کو قَطعِ تعلق کی طرف لے جاتا اور نرمی سے روکتا ہے اور بسا اوقات یہ انسان کو مَغْضُوْب عَلَیْہ (جس پر غُصّہ آیا ہے اس) کی ایذا رسانی پر اُبھارتا ہے اور اس سے دین میں کمی آتی ہے۔\n(فتح الباری، کتاب الادب، باب الحذر من الغضب، ۱۱/ ۴۴۰، تحت الحدیث:۶۱۱۶)\n حضرت سیِّدُنا عبد اللہ بن مبارک رحمۃُ اللہ علیہ سے عرض کی گئی: ایک جملے میں بتائیے کہ اچھے اخلاق کیا ہیں؟ آپ نے فرمایا: ’’غصے کو چھوڑ دینا۔‘‘ (احیاء العلوم، کتاب ذم الغضب والحقد والحسد، بیان ذم الغضب، ۳/ ۲۰۶)\n جب انسان کو غصہ آتا ہے تو دِلی کیفیت کے ساتھ جسمانی اعضاء پر بھی غصہ کی علامات ظاہر ہوتی ہیں۔چنانچہ \n¥اعضاء پرغصے کے اثرات:\n غصے کے جسم پر اثرات:رنگ متغیر ہوجانا، کندھوں پر کپکپی طاری ہونا، اپنے افعال پر قابو نہ رہنا، حرکات وسکنات میں بے چینی کا پایا جانا، نیز کلام کامضطرب ہو جانا (زبان پر قابو نہ رہنا) یہاں تک کہ باچھوں (ہونٹوں کے سِروں) سے جھاگ نکلنے لگتا، آنکھوں کی سرخی حد سے بڑھ جاتی، نتھنے پھول جاتے، بلکہ پوری صورت ہی تبدیل ہو جاتی ہے۔ اگر کوئی غضبناک شخص اس حالت میں اپنی ہی شکل دیکھ لے تو شرم کے مارے اپنی خوبصورت شکل کو بدصورتی میں تبدیل پا کر خود بخود ہی اس کا غصہ ختم ہو جائے گا، کیونکہ کسی بھی انسان کی ظاہری حالت اس کی باطنی کیفیت کی عکاس ہوتی ہے۔ لہٰذاجب باطنی کیفیت ہی بُری ہو گی تو ظاہری حالت بھی اسی بُرائی پر پروان چڑھے گی، لہٰذا ظاہر کی تبدیلی حقیقت میں باطن کی تبدیلی کانتیجہ ہوتی ہے۔زبان پر غصے کے اثرات: اس سے بُری باتیں نکلتی ہیں۔ مثلاً ایسی فحش اور گندی گالیاں وغیرہ کہ جن سے ہر صاحِبِ عقل انسان کو حیا آتی ہے، ایسی گفتگو کرنے والے شخص کو غصے کے وقت اپنی باتوں پر قابو نہیں رہتا بلکہ اس کے الفاظ بھی بےربط اورخلط ملط ہو جاتے ہیں۔ پھرنوبت مار پیٹ بلکہ قتل وغارت گری تک جا پہنچتی ہے، اگر کوئی شخص بدلہ نہ لے سکتا ہو تو اپنا غصہ خود پر ہی نکالنے لگتا ہے، یوں کہ اپنے کپڑے پھاڑتا، خود کو اور دوسروں کو یہاں تک کہ جانوروں اور دوسری اشیاء تک کو مارنے یا توڑنے لگتا ہے، بلاوجہ پاگلوں کی طرح بھاگنے لگتا ہے اور بعض اوقات زمین پر گر جاتا اور حرکت تک نہیں کر سکتا بلکہ غضب کی زیادتی کی وجہ سے اس پر غشی کی حالت طاری ہو جاتی ہے۔ دل پر غصے کے اثرات: جس پر غصہ ہو اس کے خلاف دل میں کینہ اور حسد پیدا ہو جاتا ہے، اس کی مصیبت پر خوشی کا اورخوشی پر غم کااظہار کرتا ہے، اس کا راز فاش کرنے، دامَن عزت چاک کرنے اور مذاق اُڑانے کا پختہ ارادہ کرلیتا ہے۔ اس کے علاوہ اور بہت سی برائیاں ایسی ہیں جن کا سبب غصہ بنتا ہے۔(الزواجر عن اقتراف الکبائر، ۱/ ۱۱۸، ۱۱۹)\n¥زیادہ غصے کا نقصان:\n حضرت سیِّدُنا سلیمان بن داؤد علیہما السّلام نے ارشاد فرمایا: ’’زیادہ غصہ کرنے سے بچو کیونکہ غصے کی کثرت بُردبار شخص کے دل کو راہِ حق سے ہٹا دیتی ہے۔‘‘ (احیاء العلوم، کتاب ذم الغضب والحقد والحسد، بیان ذم الغضب، ۳/ ۲۰۴) \n حضرت سیِّدُنا حسن بصری رحمۃُ اللہ علیہ فرماتے ہیں: ’’اے انسان! جب تو غصے میں آتا ہے تو اچھلتا ہے خیال کر کہیں ایسا نہ ہو کہ تو جہنم میں چھلانگ لگا بیٹھے۔‘‘ (احیاء العلوم، کتاب ذم الغضب والحقد والحسد، بیان ذم الغضب، ۳/ ۲۰۵)\n¥کیا ہر غصہ حرام ہے؟\n عوام میں یہ غلط مشہور ہے کہ ’’غصہ حرام ہے‘‘ غصہ ایک غیر اختیاری امر ہے، انسان کو آ ہی جاتا ہے اس میں اس کا قصور نہیں، ہاں غصے کا بےجا (یعنی غلط)استعمال بُرا ہے۔ بعض صورتوں میں غصہ ضروری بھی ہے۔ مثلاً: جہاد کے وقت اگر غصہ نہیں آئے گا تو اللہ پاک کےدشمنوں سے کس طرح لڑیں گے! بہر حال غصے کا ’’اِزالہ‘‘ (یعنی اس کا نہ آنا) ممکن نہیں ’’اِمالہ‘‘ ہونا چاہئے یعنی غصہ کا رُخ دوسری طرف پھر جانا چاہئے۔ یہ آخرت کے لئے انتہائی مفید ہے۔ (بیانات عطاریہ، حصہ دوم، ص173)\n¥غصہ کس کی طرف سے ہے؟ اور اس کا علاج:\n حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’غصہ شیطان کی طرف سے ہے اور شیطان آگ سے پیدا ہوا ہے اور آگ پانی سے بجھتی ہے، لہٰذا جب تم میں سے کسی کو غصہ آئے تو وہ وضو کر لیا کرے۔‘‘ \n(ابو داود، کتاب الادب، باب ما یقال عند الغضب، ۴/ ۳۲۷، حدیث:۴۷۸۴)\n رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشادفرمایا: ’’جب تم میں سے کسی کو غصہ آئے تو اگر کھڑا ہو تو بیٹھ جائے اگر اس سے اس کا غصہ دور ہو جائے تو ٹھیک ورنہ لیٹ جائے۔‘‘ (ابو داود، کتاب الادب، باب ما یقال عند الغضب، ۴/ ۳۲۷، حدیث:۴۷۸۲) \n¥غصے پر قابو پانے کی فضیلت:\nحضرت سیِّدُنا عبد اللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے ہم سے استفسار فرمایا: ’’ تم پہلوان کسے سمجھتے ہو؟ ہم نے عرض کی: جسے لوگ پچھاڑ نہ سکیں۔ تو آپ نے ارشاد فرمایا: ’’پہلوان وہ نہیں بلکہ پہلوان وہ ہے جو غصے کے وقت اپنے آپ پر قابو رکھے۔‘‘ (مسلم، کتاب البر والصلة، باب قبح الکذب...الخ، ص۱۰۷۸، حدیث:۶۶۴۱)\nایک شخص نے بارگاہِ رسالت میں عرض کی: کون سی چیز سب سے زیادہ سخت ہے؟ تو رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اللہ پاک کا غضب۔‘‘ اس نے عرض کی: مجھے غضب الٰہی سے کیا چیز بچا سکتی ہے؟ ارشاد فرمایا: ’’غصہ نہ کیا کرو۔‘‘ \n(مساوی الاخلاق للخرائطی، باب ما جاء فی فضل الحلم، ص۱۶۲، حدیث:۳۴۲)\nاللہ پاک کے پیارے حبیب صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو شخص اپنے غصے کو روکتا ہے اللہ پاک اس کی پردہ پوشی فرماتا ہے۔‘‘ (معجم کبیر، عمرو بن دینار عن ابن عمر، ۱۲/ ۳۴۷، حدیث:۱۳۶۴۶)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6882, "bookId": 13, "volNo": "1", "hadithNo": 17, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "ہر چیز کے ساتھ بھلائی کرو", "arabic": "عَنْ اَبِيْ يَعْلٰى شَدَّادِ بْنِ اَوْسٍ رَضِیَ اللهُ عَنْہُ عَنْ رَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’اِنَّ اللهَ كَتَبَ الْاِحْسَانَ عَلٰى كُلِّ شَيْءٍ. فَاِذَا قَتَلْتُمْ فَاَحْسِنُوا الْقِتْلَةَ وَاِذَا ذَبَحْتُمْ فَاَحْسِنُوا الذِّبْحَةَ وَلْيُحِدَّ اَحَدُكُمْ شَفْرَتَهٗ وَلْيُرِحْ ذَبِيْحَتَهٗ.‘‘ (رَوَاہُ مُسْلِم)", "urdu": "حضرت سیِّدُنا ابویعلی شداد بن اوس رضی اللہ عنہ سے روایت ہے کہ رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بےشک اللہ پاک نے ہر چیز کے ساتھ بھلائی کرنا فرض کیا ہے، لہٰذا جب تم قتل کرو تو اچھے طریقے سے قتل کرو اور جب تم ذبح کرو تو اچھے طریقے سے ذبح کرو، تم اپنی چھری کو تیز کرو اور ذبح ہونے والے جانور کو آرام پہنچاؤ۔‘‘ \n( مسلم، كتاب الصيد والذبائح...الخ، باب الامر باحسان الذبح والقتل وتحديد الشفرة، ص۸۳۲، حدیث:۵۰۵۵)", "roman": "Hazrat Sayyiduna Abu Ya'la Shaddad Bin Aws RadiyAllahu Anhu se Riwayat hai ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne irshad farmaya: ''Beshak Allah Paak ne har cheez ke saath bhalai karna Farz kiya hai, lihaza jab tum qatl karo to achhe tareeqe se qatl karo aur jab tum Zibah karo to achhe tareeqe se Zibah karo, tum apni chhuri ko teiz karo aur Zibah hone wale jaanwar ko aaram pohanchao.''\n(Muslim, Kitab-us-Sayd waz-Zaba'ih...al-aakhir, Baab-ul-Amr bi-Ihsaniz-Zibah wal-Qatl wa Tahdeed-ish-Shafrah, Safha 832, Hadees: 5055)", "explanation": "حدیثِ مبارکہ میں حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ہر شے کے ساتھ بھلائی اور احسان کا حکم ارشاد فرمایا ہے، یہاں یہ بات یاد رہے کہ ہر شے کے ساتھ بھلائی کا انداز جُدا ہے جیسے بیمار کو ڈاکٹر کی تجویز کردہ کڑوی دوا پلانامریض کے ساتھ احسان و بھلائی ہے جبکہ ایسی دوا بلا وجہ تندرست کو پلانا ظلم وزیادتی ہے۔\n¥بھلائی کا حکم ہر چیز کے ساتھ ہے:\n حضرت سیِّدُنا علّامہ علی بن سلطان قاری حنفی رحمۃُ اللہ علیہ فرماتے ہیں: بھلائی کرنے کا حکم عام ہے جس میں انسان، حیوان، زندہ اور مردہ سب شامل ہیں ۔ (مرقاة المفاتیح، ۷/ ۶۷۹، تحت الحدیث: ۴۰۷۳)\n¥قتل و ذبح میں بھی بھلائی کرو:\n مشہور شارح حدیث، حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’اچھے طریقے سے قتل کرو‘‘ کی شرح میں فرماتے ہیں: یعنی اگر تم قاتل یا کافر کو قصاص یا جنگ میں قتل کرو تو ان کے اعضاء نہ کاٹو، مُثلہ نہ کرو (یعنی ناک کان وغیرہ کاٹ کر صورت نہ بگاڑو)۔ اور حدیث شریف کے جز ’’اچھے طریقے سے ذبح کرو‘‘ کے تحت فرماتے ہیں: مثلاً جانور کو ذبح سے پہلے خوب کھلا پلا لیا جائے، ایک کے سامنے دوسرے کو ذبح نہ کیا جائے، اس کے سامنے چھری تیز نہ کی جائے، ماں کے سامنے بچے کو اور بچے کے سامنے ماں کو ذبح نہ کیا جائے، مذبح (یعنی قربانی کی جگہ) کی طرف گھسیٹ کر نہ لے جایا جائے اور جان نکل جانے سے پہلے اس کی کھال نہ اتاری جائے کہ یہ تمام باتیں ظلم وزیادتی ہیں۔ اور حدیث پاک کے جز ’’اپنی چھری کو تیز کرو‘‘ کی شرح میں فرماتے ہیں: تیز چھری سے ذبح کرنے میں راحت ہے، کھنڈی چھری سے ذبح کرنے میں بہت تکلیف ہوتی ہے اس سے بچے، پوری گردن نہ کاٹ دے صرف حلقوم اور رگیں کاٹے۔ (مراٰۃ المناجیح، 5/ 645)\n¥جانور کے ساتھ بھلائی ونرمی:\nحضرت سیِّدُنا امام قرطبی رحمۃُ اللہ علیہ فرماتے ہیں: جانور کو ذبح کرنے میں اچھا برتاؤ یہ ہے کہ جانور پر نرمی کی جائے، سختی اور بےدردی سے زمین پر نہ گرایا جائے، ایک جگہ سے دوسری جگہ گھسیٹ کر نہ لے جایا جائے، ذبح کے آلے (چھری وغیرہ) کو تیز کر لیا جائے، قربت (نیکی) اور اِباحت (گوشت کے حلال کرنے) کی نیت حاضر کر لے، جانور کو قبلہ رو کرے، اسی طرح (بوقْتِ ذبح) اللہ پاک کا نام لینا، جلدی ذبح کرنا، ودجین اور حلقوم کا کاٹنا، ذبیحہ کو آرام پہنچانا، ٹھنڈا ہو جانے تک ذبیحہ کو چھوڑ دینا، اللہ پاک (نے یہ جانور حلال فرمایا اس) کے احسان کا اعتراف کرنا، اللہ پاک اگر چاہتا تو ضرور اس جانور کو ہم پر مسلط فرما دیتا لیکن اُس نے اِس جانور کو ہمارے بس میں کر دیا اسی طرح اگر وہ چاہتا تو ضرور اسے ہمارے لئے حرام فرما دیتا مگر اس نے ہمارے لئے اسے حلال فرمایا، لہٰذا اس نعمت پر اللہ پاک کا شکر بجا لانا (اور جانور کے ساتھ نرمی وبھلائی کا معاملہ کرنا) چاہئے۔\n (المفهم لما اشكل من تلخيص كتاب مسلم، ۵/ ۲۴۱، تحت الحدیث:۱۸۵۴)\n¥بکری ذبح کرنے والے کو نصیحت فاروقی:\n مسلمانوں کے دوسرے خلیفہ حضرت سیِّدُنا عمر فاروقِ اعظم رضی اللہ عنہ نے ایک شخص کو دیکھا جو بکری کو ذَبْح کرنے کے لئے اسے ٹانگ سے پکڑ کر گھسیٹ رہا تھا، آپ رضی اللہ عنہ نے اس سے فرمایا: تیرے لئے خرابی ہو، اسے موت کی طرف اچّھے انداز میں لے کر جا۔ (مصنف عبدالرزاق، ۴/ ۳۷۶، حدیث:۸۶۳۶)\n¥اللہ پاک بھی تم پر رحم فرمائے گا:\n ایک صَحابی رضی اللہ عنہ نے بارگاہِ رسالت میں عرض کی: یارسولَ اللہ صلّی اللہ علیہ وسلّم ! مجھے بکری ذَبْح کرنے پر رَحْم آتا ہے۔ تو حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اگر تم اس پر رَحْم کرو گے تو اللہ پاک بھی تم پر رَحْم فرمائے گا۔‘‘ \n(مسنداحمد، ۵/ ۳۰۴، حدیث:۱۵۵۹۲)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6883, "bookId": 13, "volNo": "1", "hadithNo": 18, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "نیکی گناہ کو مٹا دیتی ہے", "arabic": "عَنْ اَبِيْ ذَرٍّ جُنْدُبِ بْنِ جُنَادَةَ وَاَبِيْ عَبْدِ الرَّحْمٰنِ مُعَاذِ بْنِ جَبَلٍ رَضيَ اللهُ عَنْهُ مَا عَنْ رَسُوْلِ اللهِ صَلَّی اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’اِتَّقِ اللهَ حَيْثُمَا كُنْتَ وَاتْبِعِ السَّيِّئَةَ الْحَسَنَةَ تَمْحُهَا وَخَالِـقِ النَّاسَ بِخُلُقٍ حَسَنٍ. (رَوَاہُ التِّرْمِذِیُّ وَقَالَ: حَدِیْثٌ حَسَنٌ وَفِیْ بَعْضِ النُّسَخِ: حَسَنٌ صَحِیْحٌ)", "urdu": "حضرت سیِّدُنا ابو ذر جُندُب بن جُنادہ اورحضرت سیِّدُنا ابو عبد الرحمٰن معاذبن جبل رضی اللہ عنہما سے روایت ہے کہ رسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جہاں بھی ہو اللہ پاک سے ڈرتے رہو اور گناہ ہوجائے تو اس کے بعد نیکی کر لیا کرو کہ نیکی گناہ کو مٹا دے گی اور لوگوں کے ساتھ اچھے اخلاق سے ملو۔‘‘ \n(ترمذی، كتاب البرّ والصلة، باب ما جاء فی معاشرة الناس، ۳/ ۳۹۷، حدیث:۱۹۹۴)\n (اس حدیث کو حضرت سیِّدُنا امام ابو عیسیٰ محمد بن عیسیٰ ترمذی رحمۃ اللہ علیہ نے روایت کیا اور فرمایا: یہ حدیث حسن ہے۔ جبکہ بعض نسخوں میں ہے: یہ حدیث حسن صحیح ہے۔)", "roman": "Hazrat Sayyiduna Abu Zar Jundub Bin Junadah aur Hazrat Sayyiduna Abu Abdur Rahman Mu'az Bin Jabal RadiyAllahu Anhuma se Riwayat hai ke Rasool-e-Akram Sallallahu Alayhi wa Sallam ne irshad farmaya: ''Jahan bhi ho Allah Paak se darte raho aur gunah ho jaye to us ke baad neki kar liya karo ke neki gunah ko mita degi aur logon ke saath achhe akhlaaq se milo.''\n(Tirmizi, Kitab-ul-Birr was-Silah, Baab Ma Jaa Fee Mu'asharat-in-Naas, 3/397, Hadees: 1994)\n(Is Hadees ko Hazrat Sayyiduna Imam Abu Isa Muhammad Bin Isa Tirmizi Rahmatullah Alayh ne Riwayat kiya aur farmaya: Yeh Hadees Hasan hai. Jabke baaz nuskho mein hai: Yeh Hadees Hasan Saheeh hai.)", "explanation": "¥تین نصیحتیں :\nمذکورہ حدیث پاک میں تین چیزوں کا حکم دیا گیا ہے: (1)…جہاں بھی رہو اللہ پاک سے ڈرتے رہو، (2)…گناہ سرزد ہو جائے تو اس کے بعد فوراً نیکی کر لو اور (3)…لوگوں کے ساتھ حسْنِ اخلاق سے پیش آؤ۔ ان تینوں نصیحتوں کی وضاحت ملاحظہ فرمائیں۔ چنانچہ\nپہلی نصیحت:¥ اللہ¥ پاک کا ڈر و خوف\n¥اللہ پاک سے ڈرنے کا مطلب:\n حضرت سیِّدُنا علّامہ علی بن سلطان قاری حنفی رحمۃُ اللہ علیہم ذکورہ حدیث شریف کی شرح میں فرماتے ہیں: تنہائی میں ہو یا لوگوں کے درمیان ہر جگہ ہر حال میں اللہ پاک سے ڈرتے رہو کیونکہ اللہ پاک جس طرح تمہارے ظاہر کو جانتا ہے اسی طرح تمہارے باطن سے بھی باخبر ہے، لہٰذا اللہ پاک کا حکم بجالاتے ہوئے فرائض وواجبات کی ادائیگی کرو اور بُری چیزوں سے باز رہو، اس کی رضا چاہو اور ناراضی والے کاموں سے بچو۔(مرقاةالمفاتیح، کتاب الاٰداب، باب الرفق والحیا...الخ، ۸/ ۸۱۰، تحت الحدیث:۵۰۸۳)\n¥تقوی اور متقی کی تعریف:\n تفسیر کبیر میں تقوی کی تعریف یہ ہے کہ تم اپنے باطن کو اللہ پاک کے لئے ویسے ہی سنوارو جیسے اپنے ظاہرکو مخلوق کے لئے سنوارتے ہو۔یہ بھی کہا گیا ہے کہ متقی وہ ہے جو مصطفٰے کریم صلّی اللہ علیہ وسلّم کے (بتائے ہوئے) راستے پرچلے، دُنیا کو پیٹھ پیچھےرکھے، اپنے نَفْس کواِخلاص کاعادی بنائےاور حرام ونافرمانی والے کاموں سے بچے۔ (تفسیر کبیر، پ۱، البقرة، تحت الاٰیة:۲، ۱/ ۲۶۸)\n حُجَّۃ ُالْاِسْلَام حضرت سیِّدُنا امام محمد بن محمد بن محمد غزالی رحمۃُ اللہ علیہ تقوی کی تعریف کرتے ہوئے فرماتے ہیں: ’’ہر اس چیزاور کام سے بچنے کانام تقویٰ ہے جس سے دین میں نقصان پہنچنے کاخوف اوراندیشہ ہو۔‘‘ (منھاج العابدین، ص۶۰)\n¥تقویٰ کے درجات:\n یاد رکھئے! تقویٰ دین کی بنیاد ہے اور اسی کے ذریعے یقین کے درجوں تک پہنچا جاتا ہے۔ تقویٰ کا ادنیٰ درجہ یہ ہے کہ اللہ پاک کے ساتھ کسی کو شریک نہ ٹھہرایا جائے اور اعلیٰ درجہ یہ ہے کہ اس پاک ذات کے علاوہ ہر چیز سے توجہ ہٹا لی جائے۔ پھر ان دونوں کے درمیان مزید کچھ مراتب ہیں اور بعض بعض سے اولیٰ ہیں۔ مثلاً گناہ ترک کرنا ادنیٰ درجہ، مکروہ کو ترک کرنا اس سے اعلیٰ اور مباح کو ترک کرنا اس سے بھی اعلیٰ ہے۔ (مرقاة المفاتیح، ۸/ ۸۱۰، تحت الحدیث: ۵۰۸۳ملخصًا وملتقطًا)\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں: تقویٰ کے بہت درجے ہیں۔ پہلا درجہ: بدعقیدگی سے بچنا ہے۔ دوسرا درجہ: بدعملی سے بچنا ہے۔ تیسرا درجہ: مکروہ بلکہ مشتبہ چیزوں (یعنی جن چیزوں کا جائز، ناجائز ہونا یقینی طور پر معلوم نہ ہو ان) سے بچنا۔ چوتھا درجہ: بیکار چیزوں سے بچنا۔ پانچواں درجہ: جو بارے حجاب ہو اس سے بچنا (رکاوٹ کا باعث بننے والی چیزوں سے بچنا)۔ (لہٰذا) ’’تم جہاں کہیں بھی ہو اللہ پاک سے ڈرو‘‘مراد یہ ہے کہ علانیہ خفیہ ہر طرح ہر جگہ خدا سے ڈرنا۔ (مراٰۃ المناجیح، 6/ 644)\n¥تنہائی میں گناہ سے نہ بچنے کا وبال:\n حضرت سیِّدُنا داود طائی رحمۃُ اللہ علیہ بیان کرتے ہیں کہ میں نے ایک قبر سے یہ آواز سنی: ’’کیا میں زکوٰۃ نہیں دیا کرتا تھا؟ کیا میں نمازی نہ تھا؟ کیا میں فلاں فلاں نیک عمل کا پابند نہ تھا؟‘‘ اس سے کہا گیا: ’’کیوں نہیں! بےشک تو یہ سب کام کرتا تھا مگر تو تنہائی میں گناہ کیا کرتا تھا۔‘‘ (مرقاة المفاتیح، ۸/ ۸۱۰، تحت الحدیث: ۵۰۸۳ملخصًا وملتقطًا)\n (نوٹ: تقوی کے فضائل وفوائد کے متعلق تفصیلی معلومات کے لئے دعوت اسلامی کے اشاعتی ادارے مکتبہ المدینہ کی مطبوعہ 125 صفحات پر مشتمل کتاب ’’اَچّھے بُرے عمل‘‘ کا مطالعہ کیجئے۔)\nدوسری نصیحت:¥ گناہ سرز ہو تو فوراً نیکی کرلو\nنیکی گناہ کو مٹاد دیتی ہے:\n سیِّدُنا امام شرف الدین حسین بن محمد بن عبد اللہ طیبی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’گناہ سرزد ہوجائے تو فوراً نیکی کرلو‘‘کے تحت فرماتے ہیں: گناہ اپنی ضد (الٹ) یعنی نیکی سے مٹتے ہیں۔ لہٰذا گانے باجے سننے کا کفارہ (توبہ کرنے کے بعد) قرآن پاک کی تلاوت سننا اور ذکر کی محفل میں بیٹھنا ہے۔ شراب پینے کا کفارہ (توبہ کے بعد) حلال مشروب صدقہ کرنا ہے کہ ہر مرض کا علاج اس کی ضد کے ذریعے ہوتا ہے، کیونکہ متضاد چیزیں آپس میں مناسبت رکھتی ہیں، لہٰذا بُرائی کو اس کی ہم جنس نیکی سے مٹایا جائے جیساکہ سفیدی سیاہی کو ختم کرتی ہے اور دنیا کی محبت نیکی کی محبت کے اثر سے زائل ہوتی ہے۔ نیز یہ بات بھی یقینی ہے کہ مسلمان کو غم یا دکھ وغیرہ کے سبب جو بھی تکلیف پہنچے وہ اس کے گناہوں کا کفارہ بن جاتی ہے۔ \n(شرح الطیبی، کتاب الادب، باب الرفق والحیاء وحسن الخلق، ۹/ ۲۷۷، تحت الحدیث:۵۰۸۳)\n اللہ پاک قرآن مجید میں ارشاد فرماتا ہے:\nاِنَّ الْحَسَنٰتِ یُذْهِبْنَ السَّیِّاٰتِؕ (پ ۱۲، ھود: ۱۱۴)\nترجمہ کنزالایمان: بےشک نیکیاں بُرائیوں کو مٹا دیتی ہیں۔\n¥مذکورہ آیت طیبہ کی تفسیر اور شان نزول:\nصدر الافاضل حضرت علامہ مولانا سیِّد محمد نعیم الدین مراد آبادی رحمۃُ اللہ علیہ اس آیت مبارکہ کی تفسیر میں لکھتے ہیں: آیت سے معلوم ہوا کہ نیکیاں صغیرہ گناہوں کے لئے کفارہ ہوتی ہیں خواہ وہ نیکیاں نماز ہوں یا صدقہ یا ذکر واستغفار یا اور کچھ۔ مسلم شریف کی حدیث میں ہے کہ ’’پانچوں نمازیں اور جمعہ دوسرے جمعہ تک اور ایک روایت میں ہے کہ رمضان دوسرے رمضان تک یہ سب کفارہ ہیں ان گناہوں کے لئے جو ان کے درمیان واقع ہوں جب کہ آدمی کبیرہ گناہوں سے بچے۔‘‘ (مسلم، کتاب الطھارة، باب الصلوات الخمس والجمعة الی الجمعة... الخ، ص۱۱۸، حدیث:۵۵۲) شانِ نزول: ایک شخص نے کسی عورت کو دیکھا اور اس سے کوئی خفیف سی حرکت بے حجابی کی سرزد ہوئی اس پر وہ نادِم ہوا اور رسولِ کریم صلّی اللہ علیہ وسلّم کی خدمت میں حاضر ہو کر اپنا حال عرض کیا اس پر یہ آیت نازل ہوئی، اس شخص نے عرض کیا: کیا صغیرہ گناہوں کے لئے نیکیوں کا کفارہ ہونا خاص میرے لئے ہے ؟فرمایا: نہیں سب کے لئے۔ (خزائن العرفا ن، پ12، ہود، تحت الآیۃ:114)\nتیسری نصیحت:¥ لوگوں کے ساتھ اچھے اَخلاق سے پیش آؤ\nحدیث شریف میں تیسری بات یہ ارشاد فرمائی کہ ’’لوگوں کے ساتھ اچھے اخلاق سے پیش آؤ‘‘ پہلی دونوں باتیں خالِقِ حقیقی سے متعلق تھیں جبکہ تیسری بات مخلوق سے متعلق ہے، یعنی جب بھی لوگوں سے مِلو تو خندہ پیشانی سے ملو ، اچھے انداز میں ان سے ہم کلام ہو ،ہمیشہ سچ بولو جھوٹ سے بچو۔ ¥\nحسن اخلاق کی تعریف:\nحضرت سیِّدُنا عبداللہبن مبارک رحمۃُ اللہ علیہ فرماتے ہیں: ’’خندہ پیشانی سے ملاقات کرنے، خوب بھلائی کرنے اور کسی کو تکلیف نہ دینے کا نام حُسنِ اَخلاق ہے۔‘‘ ( ترمذی، کتاب البر والصلة، باب ما جاء فی حسن الخلق، ۳/ ۴۰۴، حدیث:۲۰۱۲)\nمفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’لوگوں سے اچھے اخلاق سے پیش آؤ‘‘ اس طرح کہ لوگوں کی تکالیف برداشت کرو، ان پر اپنا مال خرچ کرو، ان سے خندہ پیشانی سے ملو، ان کی مصیبتوں میں کام آؤ۔(مراٰۃ المناجیح، 6/ 645)\n¥حسن اَخلاق کی فضیلت پر احادیث مبارکہ:\n سیِّدُنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلّی اللہ علیہ وسلّم نے ارشاد فرمایا: ’’مسلمانوں میں سب سے زیادہ کامل مسلمان وہ ہے جو سب سے زیادہ اچھے اخلاق والا ہے۔‘‘ (ابو داود، کتاب السنة، باب الدلیل علی زیادة الایمان، ۴/ ۲۹۰، حدیث:۴۶۸۲)\n سیِّدُنا ابودَرْداء رضی اللہ عنہ سے روایت ہے کہ رسولِ کریم صلّی اللہ علیہ وسلّم نے ارشاد فرمایا: ’’قیامت کے دن مومن کے میزان میں حُسنِ اَخلاق سے زیادہ وزنی کوئی شے نہیں ہو گی۔‘‘ ( ترمذی،کتاب البر والصلة، باب ما جاء فی حسن الخلق، ۳/ ۴۰۳، حدیث:۲۰۰۹)\n حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’قیامت کے دن تم میں سے میرے نزدیک سب سے زیادہ محبوب اور میری مجلس میں زیادہ قریب وہ لوگ ہوں گے جو تم میں اچھے اخلاق والے، نرمی کرنے والے، وہ لوگوں سے اور لوگ ان سے محبت کرتے ہوں۔‘‘ (معجم اوسط، ۵/ ۳۸۶، حدیث:۷۶۹۷)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6884, "bookId": 13, "volNo": "1", "hadithNo": 19, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "ایک اسلامی عقیدے کے متعلق نصیحت مصطفٰے", "arabic": "عَنْ اَبِي الْعَبَّاسِ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضيَ اللهُ عَنْهُ مَا قَالَ: كُنْتُ خَلْفَ النَّبِیِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمًا فَقَالَ: ’’يَا غُلاَمُ اِنِّيْ اُعَلِّمُكَ كَلِمَاتٍ اِحْفَظِ اللهَ يَحْفَظْكَ، اِحْفَظِ اللهَ تَجِدْهُ تُجَاهَكَ، اِذَا سَاَلْتَ فَاسْاَلِ اللهَ وَاِذَا اسْتَعَنْتَ فَاسْتَعِنْ بِاللهِ وَاعْلَمْ اَنَّ الْاُمَّةَ لَوِ اجْتَمَعَتْ عَلٰى اَنْ يَّنْفَعُوْكَ بِشَيْءٍ لَّمْ يَنْفَعُوْكَ اِلَّا بِشَيْءٍ قَدْ كَتَـبَهُ اللهُ لَكَ واِنِ اجْتَمَعُوْا عَلٰى اَنْ يَّضُرُّوْكَ بِشَيْءٍ لَّمْ يَضُرُّوْكَ اِلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللهُ عَلَيْكَ، رُفِعَتِ الْاَقْلَامُ وَجَفَّتِ الصُّحُفُ.‘‘ (رَوَاہُ التِّرْمِذِیُّ وَقَالَ: حَدِیْثٌ حَسَنٌ صَحِیْحٌ) وَفِيْ رِوَايَةِ غَيْرِ التِّرْمِذِيِّ: ’’اِحْفَظِ اللهَ تَجِدْهُ اَمَامَكَ، تَعَرَّفْ اِلَى اللهِ فِي الرَّخَآءِ يَعرِفْكَ فِي الشِّدَّةِ وَاعْلَمْ اَنَّ مَا اَخْطَاَكَ لَمْ يَكُنْ لِّيُصِيْبَكَ وَمَا اَصَابَكَ لَمْ يَكُنْ لِّيُخْطِئَكَ وَاعْلَمْ اَنَّ النَّصْرَ مَعَ الصَّبْرِ وَاَنَّ الْفَرَجَ مَعَ الْكَرْبِ وَاَنَّ مَعَ الْعُسْرِ يُسْرًا.‘‘", "urdu": "حضرت سیِّد نا عبد اللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ میں ایک دن حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم کے پیچھے (سواری پر سوار) تھا۔ آپ نے ارشاد فرمایا: ’’اے لڑکے! میں تجھے چند کلمات سکھاتا ہوں ، اللہ پاک کے احکام کی پابندی کر، اللہ پاک تیری حفاظت فرمائے گا، اللہ پاک کے حق کی رعایت کرتو اُسے اپنے سامنے پائے گا، جب مانگے تو اللہ پاک سے ہی مانگ اور جب مدد طلب کرے تو اللہ پاک سے ہی مددطلب کر اور جان لے کہ اگر ساری امت بھی تجھے نفع پہنچانے پر جمع ہو جائے تو صرف اتنا ہی نفع دے گی جتنا اللہ پاک نے تیرے لئے لکھ دیا ہے اور اگر سب مل کر تجھے کوئی نقصان پہنچانا چاہیں تو صرف اتنا ہی پہنچا سکیں گے جتنا اللہ پاک نے تیرے لئے لکھ دیا ہے۔ قلم اُٹھا دئیے گئے اور صحیفے خشک ہوگئے۔‘‘(ترمذی، كتاب صفة القيامة والرقائق والورع، ۴/ ۲۳۱، حدیث:۲۵۲۴)\nترمذی شریف کے علاوہ دیگر کتب میں یوں ہے: ’’اللہ پاک کے حقوق کی حفاظت کر! تو اُسے اپنے قریب پائے گا، خوشحالی میں اللہ پاک کو یاد رکھ وہ تنگدستی میں تجھ پر خاص توجہ فرمائے گا اور جان لے کہ جو تجھے نہیں ملا وہ ملنے والا ہی نہ تھا اور جو مل گیا وہ ٹلنے والا ہی نہ تھا۔جان لے!مدد صبر کے ساتھ اور کُشادگی رَنج وغم کے ساتھ ہے اور تنگی کے ساتھ آسانی ہے۔‘‘ \n(مستدرك، كتاب معرفة الصحابة، باب تعليم النبی ابن عباس، ۴/ ۶۹۹، حدیث: ۶۳۵۸، بتقدم وتاخر)", "roman": "Hazrat Sayyiduna Abdullah Bin Abbas RadiyAllahu Anhuma bayan karte hain ke main ek din Huzoor Nabi-e-Kareem Sallallahu Alayhi wa Sallam ke peeche (sawari par sawaar) tha. Aap ne irshad farmaya: ''Ae larke! Main tujhe chand kalimaat sikhata hoon, Allah Paak ke ahkaam ki pabandi kar, Allah Paak teri hifazat farmaye ga, Allah Paak ke haq ki ri'ayat kar to usey apne saamne paye ga, jab maange to Allah Paak se hi maang aur jab madad talab kare to Allah Paak se hi madad talab kar aur jaan le ke agar Saari ummat bhi tujhe nafa pohanchane par jama ho jaye to Sarf itna hi nafa degi jitna Allah Paak ne tere liye likh diya hai aur agar sab mil kar tujhe koi nuqsan pohanchana chahein to Sarf itna hi pohancha sakein ge jitna Allah Paak ne tere liye likh diya hai. Qalam utha diye gaye aur saheefe khushk ho gaye.''(Tirmizi, Kitab Sifat-il-Qiyamah war-Raqaiq wal-Wara', 4/231, Hadees: 2524)\nTirmizi Shareef ke ilawah deegar kutub mein yoon hai: ''Allah Paak ke huqooq ki hifazat kar! Tu usey apne qareeb paye ga, khush-haali mein Allah Paak ko yaad rakh woh tangdasti mein tujh par khaas tawajjuh farmaye ga aur jaan le ke jo tujhe nahin mila woh milne wala hi na tha aur jo mil gaya woh talne wala hi na tha. Jaan le! Madad sabr ke saath aur kushadgi ranj-o-gham ke saath hai aur tangi ke saath aasani hai.''\n(Mustadrak, Kitab Ma'rifat-is-Sahabah, Baab Ta'leem-in-Nabi Ibn Abbas, 4/699, Hadees: 6358, bi-taqaddum wa ta'akhkhur)", "explanation": "¥حقوقُ اللہ کی حفاظت کرو:\n حضرت سیِّدُنا علامہ علی قاری رحمۃُ اللہ علیہ حدیث پاک کے جز ’’اِحْفَظِ اللہ یَحْفَظْکَ (اللہ پاک کے حقوق واحکام کی پابندی کر)‘‘کی شرح بیان کرتے ہوئے فرماتے ہیں: جس چیز کا اس نے حکم دیا ہے اس پر عمل کر اور جس سے منع فرمایا اس سے باز رہ تو وہ دنیا میں مصیبتوں اور پریشانیوں سے اور آخرت میں اُن عذابات سے تیری حفاظت فرمائے گا جو تیرے اعمال کا بدلہ ہونگے کہ جو اللہپاک کاہو جاتا ہے اللہ پاک اس کا ہو جاتا ہے۔ نیز اللہ پاک کا حق یہ ہے کہ ہمیشہ اس کے ذکر و فکر اور شکر میں مشغول رہو اگر ایسا کرو گے تو اسے اپنے قریب پاؤ گے۔(مرقاة المفاتیح، کتاب الرقاق، الفصل الثانی، ۹/ ۱۶۲، تحت الحدیث: ۵۳۰۲، ملخصًا)\n¥رضائے الٰہی والے کام کرو:\n حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے مذکورہ جز کی شرح میں فرماتے ہیں: تم دنیا میں اپنے ہر کام، ہر چیز میں احکامِ الٰہیہ کا لحاظ رکھو،جائز کام کرو، ناجائز سے بچو،الله پاک کی رضا کے کام کرو، ناراضی کے کاموں سے بچو تو الله تعالیٰ تم کو دینی و دنیاوی آفتوں سے بچائے گااورہر مصیبت میں رب تعالیٰ کی رحمت تمہارے دل پر وارد ہوگی جس کے اثر سے تمہارے دل پر غم طاری نہ ہوگا۔(مراٰۃ المناجیح، 7/117)\n¥ہر وقت اللہ پاک کی فرمانبرداری میں رہو:\n حضرت سیِّدُنا امام شرف الدین حسین بن محمد بن عبداللہ طیبی رحمۃُ اللہ علیہ مذکورہ جز کے تحت فرماتے ہیں: ’’تم اللہ پاک کے حق کی رعایت کرو اور اس کی رضا طلب کرو اگر ایسا کرو گے تو اسے اپنے قریب پاؤ گے اور اللہ پا ک کے حق کی حفاظت کرو اللہ پاک دنیا کے مصائب وآلام سے تمہاری حفاظت فرمائے گا۔ لہٰذا ایسے ہوجاؤ کہ اللہ پاک ہر وقت تمہیں اپنی فرمانبرداری میں اور ایسے عمل میں دیکھے جو تمہیں اس کی نعمتوں سے قریب کردے، پھر وہ دنیا و آخرت میں تمہاری شدید حاجت کے وقت تمہیں اس کی جزا عطافرمائے گا۔‘‘ (شرح الطیبی، کتاب الرقاق، باب التوکل والصبر، ۹/ ۴۱۲، حدیث:۵۳۰۲)\n¥اللہ پاک ہی سے مانگو:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’ جب مانگو تو اللہ پاک سے ہی مانگو اور مدد طلب کرو تو اللہ پاک سے ہی مددطلب کرو‘‘ یعنی ہر چھوٹی بڑی چیز اعلیٰ ادنیٰ مدد اللہ پاک سے مانگو، یہ نہ خیال کرو کہ اتنے بڑے دربار میں ایسی ادنیٰ چیز کیوں مانگو ،دوسرے کریم مانگنے سے ناراض ہوتے ہیں اللہ پاک نہ مانگنے سے ناراض ہوتا ہے، خیال رہے کہ مجازی طور پر بادشاہ ،حاکم ،اولیائے کرام ،حضرت محمد مصطفٰے صلّی اللہ علیہ واٰلہٖ وسلّم سے کچھ مانگنا خداتعالیٰ سے ہی مانگنا ہے کہ یہ حضرات اللہ تعالیٰ کے خُدَّام، اللہ تعالیٰ کے حکم سے اللہ تعالیٰ کی نعمت دیتے ہیں ان سے مانگنا بِالواسطہ رَبّ (کریم) سے ہی مانگنا ہے، لہٰذا یہ حدیث ان قرآنی آیات اور احادیث کے خلاف نہیں، جن میں بندوں سے مانگنے کا ذکر یا حکم ہے۔(مراٰۃ المناجیح، 7/117)\n¥اللہ پاک ہی سے مدد چاہو:\n حضرت سیِّدُنا علامہ علی قاری رحمۃُ اللہ علیہ حدیث پاک کے جز ’’ جب تم مدد طلب کرو تو اللہ پاک سے ہی مددطلب کرو‘‘ کے تحت فرماتے ہیں: جب تم دنیا وآخرت کے معاملات میں مدد مانگنا چاہو تو اللہ پاک ہی سے مانگو کیونکہ اُسی سے مدد مانگی جاتی ہے اور ہر زمان اور مکان میں اسی پر بھروسا کیا جاتا ہے اور جان لو کہ اگر تمام لوگ کسی دینی یا دُنیاوی معاملے میں تجھے کسی چیز سے نفع پہنچانے کے لئے جمع ہو جائیں تو وہ اس پر قادر نہیں کہ وہ تجھے نفع پہنچائیں، سوائے اس کے کہ جو تیرے مقدر میں اللہ پاک نے لکھ دیا ہے ۔(مرقاة المفاتیح، کتاب الرقاق، الفصل الثانی، ۹/ ۱۶۳، تحت الحدیث: ۵۳۰۲، ملخصًا) \n¥وہی ہوگا جو مقدر میں ہے:\n حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’ساری امت بھی تجھے نفع پہنچانے پر جمع ہو جائے ‘‘ کے تحت فرماتے ہیں: یعنی ساری دنیا مل کر تم کو نفع نہیں پہنچاسکتی، اگر کچھ پہنچائے گی تو وہ ہی جو تمہارے مقدر میں لکھا ہے اس سے معلوم ہوا کہ اللہ پاک کا لکھا ہوا نفع دنیا پہنچاسکتی ہے۔طبیب کی دوا شفا دے سکتی ہے، سانپ کازہر جان لے سکتا ہے مگر یہ اللہ پاک کا طے شدہ اور اس کی طرف سے ہے، حضرت سیِّدُنا یوسف علیہِ السّلام کی قمیص نے حضرت سیِّدُنا یعقوب علیہِ السّلام کی آنکھوں کو روشنی بخشی، حضرت سیِّدُنا عیسیٰ علیہِ السّلام مردے زندہ اور بیمار اچھے کرتے تھے مگر اللہ پاک کے حکم اور اجازت سے۔(مراٰۃ المناجیح، 7/117، ملخصاً)\n¥نفع ونقصان کا مالک اللہ پاک ہے:\n ’’اللہ پاک لکھ چکا‘‘( یہاں ) لکھنے سے مراد لوحِ محفوظ میں لکھنا ہے اگرچہ وہ تحریر قلم نے کی مگر چونکہ اللہ (پاک) کے حکم سے کی تھی اس لیے کہا گیا کہ ’’ اللہ (پاک) نے لکھا‘‘ مطلب ظاہر ہے کہ اگر سارا جہاں مل کر تمہیں کوئی نقصان دے تو وہ بھی طے شدہ پروگرام کے ماتحت ہوگا کہ لو حِ محفوظ میں یوں ہی لکھا جاچکا تھا ۔(مراٰۃ المناجیح، 7/118)\n¥قلم اٹھا لئے گئے اور صحیفے خشک ہو گئے: \nعلامہ علی قاری رحمۃُ اللہ علیہ حدیث شریف کے جز ’’قلم اٹھا لئے گئے اور صحیفے خشک ہو گئے‘‘ کے تحت فرماتے ہیں: یعنی تقدیر لکھ دی گئی ہے کاتب نے جو لکھنا تھا وہ لکھاجا چکا اب اس میں کچھ تغیر وتبدل نہ ہوگا، لوحِ محفوظ میں سب کچھ لکھ دیا گیا اب اس میں کچھ نہیں لکھا جائے گا۔حدیث پاک میں ہے: ’’اللہ پاک نے سب سے پہلے قلم کو پیدا کیا۔ پھر اس سے ارشاد فرمایا: لکھ! قلم نے عرض کی: کیالکھوں؟ ارشاد فرمایا: تقدیر لکھ۔ پھر اس نے قیامت تک جو کچھ ہونے والا تھا وہ لکھ دیا۔‘‘ ایک اور حدیث مبارک میں ہے کہ ’’اللہ پاک کے علم کے مطابق قلم خشک ہو گئے۔‘‘ یعنی ازل میں اللہ پاک نے جو کچھ اسے سکھایا اور حکم دیا (اس نے وہ لکھ دیا) اب اس میں کسی قسم کی کوئی تبدیلی نہیں ہوگی۔ یہاں یہ اعتراض نہ کیا جائے کہ یہ حدیث شریف درج ذیل فرمانِ باری تعالیٰ’’ یَمْحُوا اللّٰهُ مَا یَشَآءُ وَ یُثْبِتُ (پ۱۳، الرعد:۳۹)ترجمہ کنزالایمان: اللہ جو چاہے مٹاتا اور ثابت کرتا ہے‘‘ کے خلاف ہے (ایسا نہیں ہے) حدیث مبارک اور آیت طیبہ میں کوئی تضاد نہیں اس لئے کہ مِٹنا اور ثابت ہونا بھی تقدیر میں سے ہے، کیونکہ تقدیر کی قسمیں ہیں:مبرم اورمعلق اور یہ تقسیم لوحِ محفوظ کے اعتبار سے ہے۔ بہرحال وہ تقدیر جو اللہ پاک کے علم میں ہے اس میں تبدیلی اور تغیُّر ممکن نہیں اسی لئے اللہ پاک نے اسی کے ساتھ متصل آگے ارشاد فرمایا: ’’ وَ عِنْدَهٗۤ اُمُّ الْكِتٰبِ(۳۹) (پ۱۳، الرعد:۳۹)\nترجمہ کنزالایمان: اور اصل لکھا ہوا اسی کے پاس ہے۔‘‘\n(مرقاة المفاتیح، کتاب الرقاق، الفصل الثانی، ۹/ ۱۶۴، تحت الحدیث: ۵۳۰۲)\n¥تقدیر کی اقسام اور کچھ تفصیل:\n تقدیر کی تین قسمیں ہیں: (1)…مُبرمِ حقیقی کہ علْمِ الٰہی میں کسی شے پر معلَّق نہیں۔ (2)…معلَّقِ محض کہ ملائکہ کے صحیفوں میں کسی شے پر اُس کا معلَّق ہونا ظاہر فرما دیا گیا ہے۔(3)…معلَّقِ شبیہ بہ مُبرم کہ ملائکہ کے صحیفوں میں اُس کی تعلیق مذکور نہیں اور علْمِ الٰہی میں تعلیق ہے۔ وہ جو مُبرمِ حقیقی ہے اس کی تبدیلی ناممکن ہے، اللہ پاک کے محبوب وبزرگ بندے اگر اتفاقاً اس بارے میں کچھ عرض کرتے ہیں تو انہیں اس خیال سے روک دیا جاتا ہے۔ جیسے ملائکہ قومِ لوط پر عذاب لے کر آئے تو حضرت سیِّدُنا ابراہیم علیہِ السّلام جو سراپا رحمت تھے کہ ان کا نام پاک ہی ’’ابراہیم‘‘ ہے یعنی ابِ رحیم مہربان باپ، ان کافروں کے بارے میں اپنے ربِّ کریم سے جھگڑنے لگے۔ چنانچہ ان کا ربِّ کریم ارشاد فرماتا ہے: ’’ یُجَادِلُنَا فِیْ قَوْمِ لُوْطٍؕ(۷۴) (پ۱۲، ھود:۷۴)ترجمہ: ہم سے جھگڑنے لگا قومِ لوط کے بارے میں۔‘‘ قومِ لوط پر عذاب قضائے مُبرمِ حقیقی تھا، خلیلُ اللہ علیہِ السّلام اس میں جھگڑے تو انہیں ارشاد ہوا:\nیٰۤاِبْرٰهِیْمُ اَعْرِضْ عَنْ هٰذَاۚ-اِنَّهٗ قَدْ جَآءَ اَمْرُ رَبِّكَۚ-وَ اِنَّهُمْ اٰتِیْهِمْ عَذَابٌ غَیْرُ مَرْدُوْدٍ(۷۶)\n(پ ۱۲، ھود:۷۶)\nترجمہ کنزالایمان: اے ابراہیم اس خیال میں نہ پڑ بےشک تیرے رب کا حکم آ چکا اور بےشک ان پر عذاب آنے والا ہے کہ پھیرا نہ جائے گا۔\n اور وہ جو ظاہر قضائے معلّق ہے، اس تک اکثر اولیاء کی رسائی ہوتی ہے، اُن کی دُعا سے، اُن کی ہمّت سے ٹل جاتی ہے اور وہ جو متوسّط حالت میں ہے، جسے ملائکہ کے صحیفوں کے اعتبا ر سے مُبرَم بھی کہہ سکتے ہیں، اُس تک خواص اکابر کی رسائی ہوتی ہے۔ حضور سیّدنا غوثِ اعظم رحمۃُ اللہ علیہ اسی کے بارے میں فرماتے ہیں: ’’میں قضائے مُبرَم کو رد کر (یعنی ٹال) دیتا ہوں۔‘‘ اور اسی کی نسبت حدیث شریف میں ارشاد ہوا: ’’اِنَّ الدُّعَاءَ یَرُدُّ الْقَضَآءَ بَعْدَ مَا اُبْرِمَ‘‘ (یعنی بےشک دُعا قضائے مبرم کو ٹال دیتی ہے)۔‘‘ (بہارِ شریعت، حصہ1، 1/ 12 تا 16، ملخصاً)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6885, "bookId": 13, "volNo": "1", "hadithNo": 20, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "حیا نہ ہو تو جو چاہو کرو", "arabic": "عَنْ اَبِيْ مَسْعُوْدٍ عُقْبَةَ بْنِ عَمْرِو الْاَنْصَارِيِّ الْبَدْرِيِّ رَضيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : ’’اِنَّ مِمَّا اَدرَكَ النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْاُوْلٰى اِذَا لَمْ تَستَحِيْ فَاصْنَعْ مَا شِئْتَ.‘‘ (رَوَاہُ البُخَارِی)", "urdu": "بدری صحابی حضرت سیِّدُنا ابومسعود عقبہ بن عَمْرو انصاری رضی اللہ عنہ بیان کرتے ہیں کہ اللہ پاک کے آخری نبی، محمد عربی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا:’’بےشک گزشتہ انبیائے کرام علیہمُ السّلام کے کلام میں سے لوگوں نے یہ بھی پایا ہےکہ جب تمہیں حیا نہ ہو تو جو چاہو کرو۔‘‘ (بخاری كتاب الادب، باب اذا لم تستح فاصنع ما شئت، ۴/ ۱۳۱، حدیث:۶۱۲۰)", "roman": "Badri Sahabi Hazrat Sayyiduna Abu Mas'ood Uqbah Bin Amr Ansari RadiyAllahu Anhu bayan karte hain ke Allah Paak ke Aakhiri Nabi, Muhammad-e-Arabi Sallallahu Alayhi wa Sallam ne irshad farmaya: ''Beshak guzashtah Ambiya-e-Kiram Alaihimus Salam ke kalaam mein se logon ne yeh bhi paya hai ke jab tumhein Haya na ho to jo chaho karo.''(Bukhari, Kitab-ul-Adab, Baab Iza Lam Tastahi Fasna' Ma Shi'ta, 4/131, Hadees: 6120)", "explanation": "¥حیا کی اہمیت:\n حدیثِ پاک میں سابقہ انبیائے کرام علیہمُ السّلام کے کلام سے ہونے کا مطلب یہ ہے کہ تمام انبیائے کرام علیہمُ السّلام نے حیا کو پسند فرمایااور ہر نبی علیہ السّلام نے حیا پر ابھارا، کسی بھی شریعت میں حیا کا معنی ومفہوم نہیں بدلا، نیز سلامت عقلیں بھی اس بات پر متفق ہیں کہ حیا بہت بہترین وصف ہے۔ (ماخوذ از مرقاةالمفاتيح، ۸/ ۸۰۲، تحت الحدیث:۵۰۷۱)\n¥برائیوں سے روکنے والی چیز:\n حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ مذکورہ حدیث پاک کی شرح میں فرماتے ہیں: گزشتہ انبیائےکرام علیہمُ السّلام نے اپنی امتوں سے جو حکیمانہ کلام فرمائے ان میں سے ایک کلام یہ بھی ہے کہ جب تیرے دل میں الله رسول کی اپنے بزرگوں کی شرم و حیا نہ ہوگی تو بُرے سے بُرے کام کر گزرے گا کیونکہ برائیوں سے روکنے والی چیز تو غیرت ہے جب وہ نہ رہی تو بُرائی سے کون روکے،بہت لوگ اپنی بدنامی کے خوف سے بُرائیاں نہیں کرتے مگر جنہیں نیک نامی بدنامی کی پروا نہ ہو وہ ہر گناہ کر گزرتے ہیں ۔(مراٰۃ المناجیح، 6/ 638، ملخصاً)\n¥سب سے زیادہ حیا اللہ پاک سے کرو:\n حضرت سیِّدُنا علامہ ملا علی قاری رحمۃُ اللہ علیہ مذکورہ حدیث شریف کی شرح میں فرماتے ہیں: بندے کو سب سے زیادہ حیاء اللہ پاک سے کرنی چاہیے اور اللہ پاک سے حیا کا مطلب ہے کہ بندہ اس کی ہیبت و جلال اور اس کا خوف دل میں بٹھائے اور ہر اس کام سے بچے جس سے اُس کی ناراضی کا اندیشہ ہو۔ حضرت سیِّدنا شہابُ الدین سُہروردی رحمۃُ اللہ علیہ فرماتے ہیں:اللہ پاک کی عظمت و جلال کی تعظیم کے لئے روح کو جُھکانا حیا ہے۔ حضرت سیِّدنا اِسرافیل علیہ السّلام کی حیا بھی اسی قسم سے ہے۔ چنانچہ ان کے متعلق روایت میں ہے کہ وہ اللہ پاک سے حیا کی وجہ سے اپنے پَروں سے خود کو چُھپائے ہوئے ہیں۔‘‘ (ماخوذ از مرقاةالمفاتيح، ۸/ ۸۰۲، تحت الحدیث:۵۰۷۱) \n¥حیا کی تعریف:\nکسی کام کے ارتکاب کے وقت مذمت اور ملامت کے خوف سے انسان کی حالت کا تبدیل ہو جانا حیا کہلاتا ہے۔ (عمدةالقاری، کتاب الایمان، باب امور الایمان، ۱/ ۱۹۸)ایک تعریف یہ ہے کہ’’حیا وہ وصف ہے جو برے کام کے ترک پر ابھارتا اور حق دار کے حق کی ادائیگی میں کوتاہی سے روکتا ہے۔‘‘ (شرح صحیح مسلم للنووی، ۲/ ۶) ایک تعریف یہ ہے کہ’’حیا وہ عادت ہے جو ایمان کے سبب آدمی کو بُرے کاموں سے روک دے۔‘‘ (مرقاةالمفاتیح، ۱/ ۱۴۰، تحت الحدیث:۵)\n¥دینی اور دنیاوی برائیوں سے حفاظت:\nحیاءسے مُرادوہ وَصْف ہے جو ان چیزوں سے روک دے جواللہ پاک اور مخلوق کے نزدیک ناپسندیدہ ہوں۔ لوگوں سے شرما کر کسی ایسے کام سے رک جانا جو ان کے نزدیک اچھانہ ہو ”مخلوق سے حيا“ کہلاتا ہے۔ یہ بھی اچھی بات ہے کہ عام لوگوں سے حیا ء کرنا دنیاوی برائیوں سے بچائے گا اور عُلَماء وَ صُلَحاء (نیک لوگوں) سے حیا کرنا دینی بُرائیوں سے باز رکھے گا۔ مگر حیاء کے اچھا ہونے کے لئے ضروری ہے کہ مخلوق سے شرمانے میں خالق جَلَّ جَلَالُہ کی نافرمانی نہ ہوتی ہو اور نہ کسی کے حقوق کی ادائیگی میں رکاوٹ آتی ہو۔ (باحیا نوجوان، ص7، مفہوماً)\n¥اللہ پاک سے حیا کا معنیٰ:\nحضرت سیِّدُنا عبداللہ بن مسعود رضی اللہ عنہ سے مَروی ہے کہ حُضُور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے صَحابَۂ کِرام علیہمُ الرّضوان سے ارشاد فرمایا: ’’اللہ پاک سے حیاکرو جیسا حیا کرنے کا حق ہے۔‘‘ عرض کی: ہم اللہ¥ پاک سے حیا کرتے ہیں اور سب خوبیاں اللہ پاک کے لئے ہیں۔ ارشاد فرمایا: ’’یہ نہیں، بلکہ اللہ پاک سے کما حَقُّہٗ ، حیا کرنے کے معنیٰ یہ ہيں کہ سر اور سر میں جتنے اَعضاء ہیں ان کی اور پیٹ کی اور پیٹ جن جن اَعضاء کو گھیرے ہوئے ہے اُن کی حفاظت کرو اور موت اور مرنے کے بعد گلنے سڑنے کو یاد کرو، آخِرت کو چاہنے والا دنیا کی زَیب و زِینت چھوڑ دیتا ہے تو جس نے ایسا کیا اُس نے اللہ پاک سے حیا کا حق ادا کر دیا۔‘‘ (مسند احمد، مسند عبد اللّٰہ بن مسعود، ۲/ ۳۳، حدیث:۳۶۷۱)\n¥فطری وشرعی حیا:\nفِطری و شَرْعی اعتبار سے بھی حَيا کی تقسیم کی گئی ہے۔ چنانچہ فِطری حیا وہ ہے جسے اللہ پاک نے ہر جان میں پیدا فرمایا ہے اور یہ پیدائشی طور پر ہر شَخْص میں ہوتی ہے اور شَرْعی حیا یہ ہے کہ بندہ اللہ پاک کی نعمتوں اور اپنی کوتاہیوں پر غور کر کے نادِم و شرمندہ ہو اور اِس شرمندگی اور اللہ پاک کے خوف کی بِنا پر آئندہ گناہوں سے بچنے اور نیکیاں کرنے کی کوشِش کرے۔(باحیا نوجوان، ص10) \n¥حیا کے احکام:\nحیا کبھی فرض و واجِب ہوتی ہے جیسے کسی حرام و ناجائز کام سے حَیا کرنا، کبھی مُستَحب جیسے مکروہِ تنزیہی سے بچنے میں حيا اور کبھی مُباح (یعنی کرنا نہ کرنا یکساں ہو) جیسے کسی مُباحِ شَرْعی کے کرنے سے حیا۔ (نزہۃ القاری شرح، 1/ 334، مفہوماً)\n¥حیا کی فضیلت پر احادیث وروایات:\nحضرت سیِّدُنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بےشک ہر دین کا ایک خلق ہے اور اسلام کا خلق حیا ہے۔‘‘ (ابن ماجة، کتاب الزھد، باب الحیاء، ۴/ ۴۶۰، حدیث:۴۱۸۱)\nحضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ایمان کے 70 سے زائد شعبے ہیں اور حیا ایمان کا ایک شعبہ ہے۔‘‘ (مسلم، کتاب الایمان، باب بیان عدد شعب الایمان...الخ ،ص۴۵، حدیث:۱۵۲)\nحضرت سیِّدُنا ابن عمر رضی اللہ عنہما سے روایت ہے کہ حُضُور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بےشک حیا اور ایمان دونوں آپس میں ملے ہوئے ہیں تو جب ایک کو اٹھا لیا جائے تو دوسرا بھی اٹھا لیا جاتا ہے۔‘‘ \n(مستدرک، کتاب الایمان، باب اذا زنی العبد خرج منہ الایمان، ۱/ ۱۷۶، حدیث:۶۶)\n مسلمانوں کے چوتھے خلیفہ حضرت سیِّدُنا علیُّ المرتضٰی رضی اللہ عنہ فرماتے ہیں: ’’جس نے حیا کی چادر اوڑھ لی لوگوں کو اس کے عیب دکھائی نہیں دیتے۔‘‘(مستطرف، باب السادس والعشرون، فی الحیاء والتواضع...الخ، الفصل الاول ،۱/ ۲۲۴)\n حضرت سیِّدُناخواص رحمۃُ اللہ علیہ فرماتے ہیں کہ بندوں کا عمل چار منزلوں پر ہوتا ہے: (1)… خوف، (2)… رجا (امید)، (3)… تعظیم اور (4)…حیا۔ ان میں سب سےاونچی منزل حیا ہے۔ جب بندے یہ یقین کر لیتے ہیں کہ اللہ پاک انہیں ہر حال میں دیکھ رہا ہےتو کہتے ہیں: ہمارے لئے برابر ہے کہ ہم اسے دیکھیں یا وہ ہمیں دیکھے اور اللہ پاک سے حیاان کے لئے ان کے گناہوں سے آڑ بن جاتی ہے۔(مستطرف، باب السادس والعشرون، فی الحیاء والتواضع...الخ، الفصل الاول ،۱/ ۲۲۴)\n حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں: ’’حیا انسان کا خاص جوہر ہے جتنا ایمان قوی (ہوگا) اتنی حیا(بھی) زیادہ ہوگی۔‘‘ (مراٰۃ المناجیح،8/ 73)\n (نوٹ: حیا سے متعلق تفصیلی معلومات کے لئے مکتبہ المدینہ کے مطبوعہ64 صفحات پر مشتمل رسالے ’’باحیا نوجوان‘‘ کا مطالعہ کیجئے۔)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6886, "bookId": 13, "volNo": "1", "hadithNo": 21, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "ایمان پر ثابت قدم رہو", "arabic": "عَنِ اَبِيْ عَمْرٍو وَقِيْلَ اَبِيْ عَمْرَةَ سُفْيَانَ بْنِ عَبْدِ اللهِ الثَّقَفِيِّ رَضيَ اللهُ عَنْهُ قَالَ: قُلْتُ يَارَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ! قُلْ لِيْ فِي الْاِسْلَامِ قَوْلًا لَا اَسْاَلُ عَنْهُ اَحَدًا غَيْرَكَ. قَالَ: ’’قُلْ اٰمَنْتُ باللهِ ثُمَّ اسْتَقِمْ.‘‘ (رَوَاہُ مُسْلِم)", "urdu": "حضرت سیِّدُنا ابو عمرو یا ابوعمرہ سفیان بن عبداللہ ثقفی رضی اللہ عنہ کہتے ہیں کہ میں نے بارگاہِ رسالت میں عرض کی:یارسولَ اللہ صلّی اللہ علیہ وسلّم ! مجھے اسلام کے بارے میں ایسی بات بتائیے کہ میں اس کے بارے میں آپ کے علاوہ کسی سے نہ پوچھوں۔ تو آپ نے ارشاد فرمایا: ’’کہو میں اللہ پاک پر ایمان لایا پھر اس پر ثابت قدم رہو۔‘‘ \n(مسلم، كتاب الايمان، باب جامع اوصاف الاسلام، ص۴۸، حدیث: ۱۵۹)", "roman": "Hazrat Sayyiduna Abu Amr ya Abu Amrah Sufyan Bin Abdullah Saqafi RadiyAllahu Anhu kehte hain ke main ne Baargah-e-Risalat mein arz ki: Ya Rasoolullah Sallallahu Alayhi wa Sallam! Mujhe Islam ke baare mein aisi baat bataiye ke main is ke baare mein Aap ke ilawah kisi se na poochhoon. To Aap ne irshad farmaya: ''Kaho main Allah Paak par imaan laya phir is par sabit qadam raho.''\n(Muslim, Kitab-ul-Imaan, Baab Jami' Awsaf-il-Islam, Safha 48, Hadees: 159)", "explanation": "¥اسلام مکمل ہوجائے:\n حضرت سیِّدُنا امام شرف الدین حسین بن محمد بن عبداللہ طیبی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’اسلام کے بارے میں مجھے کوئی ایسی بات بتائیے کہ کسی اور سے پوچھنے کی ضرورت نہ رہے‘‘ کی شرح میں فرماتے ہیں: مجھے کوئی ایسی بات بتائیے جس کے ذریعے اسلام مکمل ہو جائے، اسلامی باتوں کی طرف راہ نمائی ہو، اس کے حقوق کی حفاظت ہو اور آپ کے بعد کسی اور سے پوچھنے کی حاجت نہ رہے تو حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’قُلْ اٰمَنْتُ بِاللہ ثُمَّ اسْتَقِمْ یعنی کہو:میں اللہ پاک پر ایمان لایا اور پھر اس پر قائم رہو۔‘‘ اِسْتَقِم ایسا لفظ ہے جو تمام اَحکامات پر عمل کرنے اور تمام ممنوعہ کاموں سے رُک جانے کو شامل ہے کیونکہ بندہ حکم عدولی کی وجہ سے صراطِ مستقیم سے دُور ہوجاتا ہے جب تک دوبارہ تَعمیلِ حکم نہ کرے۔ اِسی طرح ممنوعہ کام کے اِرتکاب سے بھی صراطِ مستقیم سے دُور ہوجاتا ہے جب تک توبہ نہ کرے۔\n(شرح الطیبی، کتاب الایمان، الفصل الاول، ۱/ ۱۳۴، حدیث:۱۵)\n¥اللہ پاک پر ایمان پھر اس پر استقامت:\n حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’الله پاک پر ايمان لاؤ پھر اس پر قائم رہو“ کے تحت فرماتے ہیں:الله (پاک) پر ایمان لانےسےمرادسارے عقائدِ اسلامیہ ماننا ہیں۔لہٰذا اس میں توحیدو رسالت، حشر ونشر، ملائکہ، جنت ودوزخ سب پر ایمان لاناداخل ہے۔ جیسےکسی کو اپنا باپ مان کر اس کے سارے اہْلِ قرابت کو اپنا عزیر ماننا پڑتاہے کہ اس کا باپ ہمارا دادا ہے، اس کی اولاد ہمارے بھائی بہن، اس کے بھائی ہمارے چچا تائے اور اسقامت سے مراد سارے اعمالِ اسلامیہ پرسختی وپابندی سے عمل کرنا ہے۔لہٰذا یہ حدیث ایمان وتقویٰ کی جامع ہے اور اس پر عامل (یعنی عمل کرنے والا) یقیناً جنتی ہے،ربّ (کریم ارشاد) فرماتا ہے:’’ اِنَّ الَّذِیْنَ قَالُوْا رَبُّنَا اللّٰهُ ثُمَّ اسْتَقَامُوْا (پ ۲۴، حم السجدة:۳۰، ترجمہ کنزالایمان: بےشک وہ جنھوں نے کہا ہمارا رب اللہ ہے پھر اس پر قائم رہے) الخ۔‘‘یہ (حدیث مذکور کے الفاظ)کلماتِ جامع میں سے ہیں۔ (مراٰۃ المناجیح، 1/ 35)\n¥استقامت کی اہمیت:\n حضرت سیِّدُنا علامہ ابو زکریا یحییٰ بن شرف نووی رحمۃُ اللہ علیہ فرماتے ہیں کہ رسالہ قشیریہ میں ہے: استقامت ایسا درجہ ہے جس سے امور کی تکمیل اور نیکیوں کا حصول ہوتا ہے۔ جو اِسے اختیار نہ کرے اُس کی کوشش ضائع ہو جاتی ہے۔ ایک قول یہ ہے کہ اِستقامت کی طاقت صرف اکابر ہی رکھتے ہیں کیونکہ اِستقامت یہ ہے کہ انسان اپنے معمولات اور رَسم و رَواج کو چھوڑ کر اپنے آپ کو اللہ پاک کے احکامات کے مطابق کرلے۔ اسی لئے رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا : ’’استقامت پر رہو اور تم ہر گز اُس کا اِحاطہ نہیں کر سکتے۔‘‘ (ابن ماجة، کتاب الطھارة وسننھا، باب المحاظة علی الوضوء، ۱/ ۱۷۸، حدیث:۲۷۷) حضرت سیِّدُنا واسطی رحمۃُ اللہ علیہ فرماتے ہیں: ’’اِستقامت ایسا وصف ہے جس کے پائے جانے سے اچھائیاں مکمل ہوتیں اور اس کے نہ ہونے کی وجہ سے خوبیاں خامیوں میں تبدیل ہو جاتی ہیں۔‘‘ \n(شرح مسلم للنووی، کتاب الایمان، باب جامع اوصاف الاسلام، الجزءالثانی، ۲/ ۹)\n یہاں اِستقامت کا معنیٰ ہے:ایمان، اَعمالِ صالِحہ اور گناہوں سےبچنے پر ڈٹے رہنا۔یوں بھی کہہ سکتے ہیں کہ استقامت یہ ہے کہ ایمان ضائع نہ ہو، نیک اَعمال، مثلاً: نماز، روزہ، حج، زکوٰۃ ترک نہ ہوں۔ تلاوت، ذِکر، دُرود، تسبیحات و اذکار، صَدَقات و خیرات، دوسروں کی خیر خواہی وغیرہا پر ہمیشگی ہو۔ تمام گناہوں سے بچنے کی عادت پختہ رہے۔ یہ تمام چیزیں اِستِقامت میں داخل ہیں۔ البتہ ہر استقامت کا حکم جُدا ہے، جیسے: صحیح عقائد پر جمے رہنا سب سے بڑا فرض ہے۔ فرائض پر ہمیشگی بھی فرض ہے۔ گناہوں سے بچتے رہنا بھی لازم ہے اور مستحبات کی پابندی بھی اعلیٰ درجے کا مستحب ہے۔ چنانچہ \n¥اِستِقامت کی اقسام اور مختصر تفصیل:\n (1)… ایمان پر اِستِقامت:ایمان پر اِستِقامت کی عظمت کے متعلّق حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم کا بڑا خوب صورت فرمان ہے۔ ارشاد فرماتے ہیں کہ ’’تین چیزیں جس میں ہوں وہ ایمان کی مٹھاس پائے گا: (1)…جسےاللہ پاک اور رسول صلّی اللہ علیہ واٰلہٖ وسلّم سب سے زیادہ محبوب ہوں۔ (2)…جو کسی سے خاص اللہ پاک ہی کےلئے محبّت رکھتا ہو۔ (3)… جو اسلام لانے کے بعد کفر کی طرف لوٹنے کو ایسا برا جانے جیسے آگ میں ڈالے جانے کو برا جانتا ہے۔‘‘\n(بخاری، کتاب الایمان، باب حلاوة الایمان ، ۱/ ۱۷، حدیث:۱۶)\n (2)…فرائض پر اِستِقامت:یہ ہے کہ کبھی ترک نہ ہوں، جیسے: نماز کے متعلّق قرآن مجید میں ارشاد ہوا: ’’ وَ الَّذِیْنَ هُمْ عَلٰى صَلَوٰتِهِمْ یُحَافِظُوْنَۘ(۹) (پ۱۸، المؤمنون:۹) ترجمہ کنز الایمان: اور وہ جو اپنی نمازوں کی نگہبانی کرتے ہیں۔‘‘ ایک مقام پر ارشاد ہوا: ’’ الَّذِیْنَ هُمْ عَلٰى صَلَاتِهِمْ دَآىٕمُوْنَﭪ(۲۳) (پ۲۹، المعارج:۲۳) ترجمہ کنز الایمان: جو اپنی نماز کے پابند ہیں۔‘‘\n (3)… مستحبات پر اِستِقامت: یعنی ان پر ہمیشگی ہو۔ جیسے: تلاوت، ذکر، دُرود، صدقہ، حُسنِ اَخلاق، عَفْو وکرم اور تہجد وغیرہا پر استقامت۔ یہ استقامت بھی اللہ پاک کو بہت محبوب ہے۔ چنانچہ مروی ہے کہ ایک مرتبہ کچھ صحابَۂ کرام علیہمُ الرّضوان نے حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم کی بارگاہ میں حضرت سیِّدُنا عبداللہ بن عُمَر رضی اللہ عنہما کا تذکرہ کیا توآپ نے اِرشاد فرمایا: ’’عبداللہ ایک اچھا شخص ہے، کیا ہی اچھا ہوتا کہ وہ تہجد بھی ادا کرتا۔‘‘ (مسلم، کتاب فضائل الصحابة، باب من فضائل عبد اللّٰہ بن عمر، ص۱۰۳۴، حدیث:۶۳۷۰) ایک موقع پر حضرت سیِّدُنا عبداللہ بن عَمرو رضی اللہ عنہ کو اِرشاد فرمایا: ’’اے عبداللہ! تم فلاں کی طرح نہ ہونا جو رات میں نماز پڑھتا تھا پھر اس نے رات میں نماز (یعنی تہجد وغیرہ) كاقِیام کرنا چھوڑ دیا۔‘‘\n (مسلم، کتاب الصیام، باب النھی عن صوم الدھر...الخ، ص۴۵۲، حدیث:۲۷۳۳)\n¥اللہ پاک کے نزدیک پسندیدہ عمل:\n اُمُّ المؤمنین حضرت سیِّدَتُنا عائشہ صدیقہ رضی اللہ عنہا فرماتی ہیں کہ بارگاہِ رسالت میں عرض کی گئی: اللہ پاک کے نزدیک پسندیدہ عمل کون سا ہے؟ تو رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’وہ عمل جواستقامت کے ساتھ ہو اگرچہ تھوڑا ہو۔‘‘ (بخاری، کتاب الرقاق، باب القصد والمداومة علی العمل، ۴/ ۲۳۷، حدیث:۶۴۶۵)\n ہمارے بزرگانِ دین رحمۃُ اللہ علیہم نے اعمالِ صالحہ پر کیسی استقامت اختیار کی، اس کااندازہ اس حکایت سے لگائیے۔ چنانچہ\n¥حکایت:ایک رات میں خَتْمِ قرآن\n کروڑوں حنفیوں کے عظیم پیشوا، حضرت سیِّدُنا نعمان بن ثابت المعروف امام اعظم ابوحنیفہ رحمۃُ اللہ علیہ نے 30سال تک روزانہ ہر رات ایک رکعت میں پورا قرآن ختم کیا۔ 40 سال تک عشا کے وضو سے فجر کی نماز ادا کی۔ آپ رات کو خوفِ خدا کے باعث اِس قدر روتے کہ ہمسائے آپ پر رحم کرتے اور جس جگہ آپ رحمۃُ اللہ علیہ کا وصال ہوا وہاں آپ نے سات ہزار مرتبہ قرآن شریف ختم فرمایا تھا۔ (الخیرات الحسان، الفصل الرابع عشر، ص۵۰)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6887, "bookId": 13, "volNo": "1", "hadithNo": 22, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "جنت میں داخلہ", "arabic": "عَنْ اَبِيْ عَبْدِ اللهِ جَابِرِ بْنِ عَبْدِ اللهِ الْاَنْصَارِيِّ رَضِيِ اللهُ عَنْهُمَا اَنَّ رَجُلًا سَاَلَ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: اَرَاَيْتَ اِذَا صَلَّيْتُ الْمَكْتُوْبَاتِ وَصُمْتُ رَمَضَانَ وَاَحْلَلْتُ الْحَلَالَ وَحَرَّمْتُ الْحَرَامَ وَلَمْ اَزِدْ عَلٰى ذٰلِكَ شَيْئًا اَاَدْخُلُ الْجَنَّةَ؟ قَالَ: ’’نَعَمْ.‘‘ (رَوَاہُ مُسْلِم)وَمَعْنٰی: حَرَّمْتُ الْحَرَام اِجْتَـنَبْتُہٗ. وَمَعْنٰی: اَحْلَلْتُ الْحَلَالَ فَعَلْتُہٗ مُعْتَقِدًا حِلَّہٗ.", "urdu": "حضرت سیِّدُنا ابو عبداللہ جابر بن عبداللہ انصاری رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے رسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم کی بارگاہ میں عرض کی: مجھے بتائیے کہ جب میں فرض نمازیں اداکروں، رمضان کے روزے رکھوں، حلال کوحلال اور حرام کو حرام جانوں اور ان کاموں پر کچھ زیادہ نہ کروں تو کیا میں جنت میں چلا جاؤں گا؟ آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ہاں۔‘‘ (مسلم، كتاب الايمان، باب الايمان الذی يدخل بہ الجنة...الخ، ص۳۷، حدیث:۱۱۰) \n حضرت سیِّدُنا امام نووی رحمۃُ اللہ علیہ فرماتے ہیں: حرام کو حرام سمجھوں کا معنیٰ یہ ہےکہ حرام سے بچوں اور حلال کو حلال جاننے کا معنیٰ یہ ہےکہ اس کے حلال ہونے کا اعتقاد رکھتے ہوئے اس پر عمل کروں۔", "roman": "Hazrat Sayyiduna Abu Abdullah Jabir Bin Abdullah Ansari RadiyAllahu Anhuma se Riwayat hai ke ek Shakhs ne Rasool-e-Akram Sallallahu Alayhi wa Sallam ki baargah mein arz ki: Mujhe bataiye ke jab main Farz namazein ada karoon, Ramazan ke roze rakhoon, Halal ko Halal aur Haram ko Haram jaanoon aur in kaamon par kuch zyada na karoon to kya main Jannat mein chala jaon ga? Aap Sallallahu Alayhi wa Sallam ne irshad farmaya: ''Haan.''(Muslim, Kitab-ul-Imaan, Baab-ul-Imaan-illazi Yudkhalu bihil-Jannah...al-aakhir, Safha 37, Hadees: 110)\nHazrat Sayyiduna Imam Nawawi Rahmatullah Alayh farmate hain: Haram ko Haram samajhoon ka ma'na yeh hai ke Haram se bachoon aur Halal ko Halal jaanne ka ma'na yeh hai ke us ke Halal hone ka aiteqaad rakhte hue us par amal karoon.", "explanation": "¥حرام کو حرام جانوں:\n حضرت سیِّدُنا شیخ ابو عمرو بن صلاح رحمۃُ اللہ علیہ فرماتے ہیں: ’’حرام کو حرام جانوں‘‘ ظاہر یہ ہے کہ اس سے سائل نے دو چیزیں مرادلی ہیں: ایک یہ کہ حرام کا اعتقاد رکھوں اور دوسری یہ کہ حرام سے بچوں۔ جبکہ حلال کو حلال جاننے میں ایسا نہیں ہے کیونکہ اس میں فقط حلال کا اعتقاد رکھنا کافی ہے۔(شرح النووی علی صحیح مسلم، كتاب الايمان، باب الايمان الذی يدخل بہ الجنة...الخ، ۱/ ۱۷۵)\n¥کیا صرف فرض نماز ضروری ہے؟\n مذکورہ حدیث پاک میں فرائض کا ذکر ہے نوافل ومستحبات کا ذکر نہیں اس کا یہ مطلب ہرگز نہیں کہ نوافل وغیرہ کو چھوڑ دیا جائے جو ایسا کرے گا وہ بہت بڑے فائدے سے محروم رہے گا۔ نیز سنتوں کو چھوڑنے پر اس کا دین کمزور ہو جائے گا بلکہ سنت مؤکدہ کو اگر چھوڑنے کی عادت بنالی تو اس کے عادل ہونے میں بھی نقص آئے گا۔ پس اگر اس نے سنتوں کو ہلکا جانتے ہوئے اور بےرغبتی کی وجہ سے چھوڑاتو یہ فسق (گناہ)ہے اور وہ مذمت کا مستحق ٹھہرے گا۔ علما فرماتے ہیں: اگر شہر کے تمام لوگ سنتوں کے ترک پر ہمیشگی اختیار کریں تو ضرور ان سے لڑا جائے یہاں تک کہ سنتوں کی ادائیگی پر آمادہ ہو جائیں۔ کیونکہ صحابَۂ کرام اور تابعین عظام علیہمُ الرّضوان حصول ثواب کی خاطر سنتوں کی پابندی کیا کرتے تھے اور سنت وفرض کے درمیان فرق نہیں کرتے تھے۔ (شرح الاربعين النوویة لابن دقيق العيد، ص۱۵۸، تحت الحدیث:۲۲، ملخصًا)\n¥غور تو کیجئے:\n یاد رکھئے! سنتیں اس لئے نہیں ہوتیں کہ انہیں چھوڑا جائے بلکہ اس لئے ہوتی ہیں کہ انہیں اختیار کیا جائے صحابَۂ کرام علیہمُ الرّضوان سنتوں کے پابند تھے کہ یہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم کا طریقہ ہے جبکہ ہماری حالت یہ کہ ہم یہ کہہ کر سنتیں چھوڑ دیتے کہ سنتیں ہی تو ہیں۔\n¥زکوٰۃ اور حج کا ذکر کیوں نہیں کیا؟\n مذکورہ حدیث شریف میں صرف نماز اور روزوں کا ذکر ہے زکوٰۃ اور حج کا ذکر نہیں، اس کی وجہ یہ ہے کہ اس وقت تک زکوٰۃ اور حج فرض نہیں تھا یا پھر صاحب نصاب نہ ہونے کی وجہ سے زکوٰۃ اور استطاعت نہ ہونے کی وجہ سے حج سائل پر فرض نہیں تھا یا یہ وجہ ہے کہ زکوٰۃ اور حج سائل کے اس قول میں داخل ہے کہ ’’میں حرام کو حرام جانوں‘‘ کیونکہ فرائض چھوڑنا بھی حرام ہے اگرچہ نماز وروزہ بھی اس جملے کے تحت داخل ہے لیکن ان کی اہمیت وفضیلت کی وجہ سے انہیں صرحتاً بیان کیا۔\n (الجواھر اللؤلؤیة فی شرح الاربعین النوویة للجردانی، ص۳۳۹، تحت الحدیث:۲۲)\n¥ایک اعتراض اور اس کا جواب:\n اعتراض:مذکورہ حدیث پاک سے ظاہر ہو رہا کہ نیک عمل جنت میں داخلے کا سبب ہے جب کہ ایک روایت میں ہے، حضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں: میں نے حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم کو ارشاد فرماتے سنا کہ’’کسی کو اس کا عمل ہرگز جنت میں داخل نہیں کروا سکے گا(حاشیہ1)۔‘‘ صحابَۂ کرام علیہمُ الرّضوان نے عرض کی: یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! آپ کو بھی نہیں۔ ارشاد فرمایا: ’’مجھے بھی نہیں، البتہ اللہ پاک مجھے مہربانی سے اپنی رحمت میں چھپا لے۔‘‘(بخاری، کتاب المرضی، باب تمنی المریض الموت، ۴/ ۱۳، حدیث:۵۶۷۳) اس کا جواب یہ ہے کہ وہ عمل جو جنت میں داخلے کا سبب ہے وہی ہے جو مقبول ہو نہ کہ غیرمقبول عمل اور اس بات میں کوئی شک نہیں کہ قبولیت اللہ پاک کی جانب سے رحمت ہی ہے۔ خلاصہ یہ ہے کہ جنت میں داخلہ رحمَتِ الٰہی سے ہی ہوگا۔(الجواھر اللؤلؤیة فی شرح الاربعین النوویة للجردانی، ص۳۴۰، تحت الحدیث:۲۲)\n۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔\n(حاشیہ1) حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ اس حدیث شریف کے جز ’’کسی کو اس کا عمل ہرگز جنت میں داخل نہیں کروا سکے گا‘‘ کی شرح میں فرماتے ہیں:یعنی نیک اعمال دوزخ سے بچنے،جنت میں داخل ہونے کے اسباب تو ہیں مگر علّتِ تامہ نہیں۔ بہت سے لوگ بغیر نیک عمل جنتی ہیں جیسے مسلمانوں کے ناسمجھ بچے یا دیوانے یا وہ جو مسلمان ہوتے ہی فوت ہوجائیں اور بعض لوگ نیکیوں کے باوجود دوزخی ہیں جیسے نیکیاں کرنے والے کفار یا جن کی نیکیاں مردود ہوگئیں۔ جنت ملنے کی علّتِ تامہ اللہ پاک کا فضل ہے،محض تخم (بیج) درخت کی علَّتِ تامہ نہیں بہت بارتخم ضائع ہوجاتاہے۔ اس فرمان کا مقصد لوگوں کو نیکیوں سے روکنا نہیں ہے بلکہ نیکوں کو اپنے اعمال پر ناز کرنے سے بچانا ہے کہ اے پرہیزگارو! اپنے اعمال پرغرور نہ کرو،ربِّ کریم کا فضل مانگو، شیطان کے اعمال سے،اس کے انجام سے سبق لو۔ اور اس جز ’’یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! آپ کو بھی نہیں ‘‘ کی شرح میں فرماتے ہیں: یعنی آپ کی نیکیاں تو قبولیت کی انتہائی منزل پر ہیں کیا یہ بھی حصولِ جنت کے لیے کافی وافی نہیں،کیا آپ کو بھی اللہ پاک کی رحمت درکار ہے۔صحابَۂ کرام علیہمُ الرّضوان سمجھے یہ تھے کہ ایسے موقعہ پر متکلم مستثنیٰ ہوتا ہے شاید حضور صلّی اللہ علیہ واٰلہٖ وسلّم یہ ہمارے لیے فرمارہے ہیں اس لیے یہ سوال کیا۔اس سوال سے معلوم ہوتا کہ صحابہ کرام علیہمُ الرّضوان عمومی احکام پرحضور صلّی اللہ علیہ واٰلہٖ وسلّم کو داخل نہ مانتے تھے۔ اور حدیث پا ک کے جز ’’ اللہ پاک مجھے مہربانی سے اپنی رحمت میں چھپا لے ‘‘ کے تحت فرماتے ہیں: یعنی میں بھی محض عمل سے بلافضل الٰہی جنت کا حقدار نہیں،ہاں ربِّ کریم کی رحمت ہر طرف سے مجھے گھیرے تو جنت میر ی ہے۔ خیال رہے کہ تمام دنیا کے لئےحضورانور صلّی اللہ علیہ واٰلہٖ وسلّم رحمت ہیں،ربِّ کریم ارشاد فرماتا ہے: وَ مَاۤ اَرْسَلْنٰكَ اِلَّا رَحْمَةً لِّلْعٰلَمِیْنَ(۱۰۷) (پ۱۷، الانبیآء:۱۰۷، ترجمہ کنزالایمان: اور ہم نے تمہیں نہ بھیجا مگر رحمت سارے جہان کے لئے۔) اور رحمَتِ الٰہی جنت ملنے کا ذریعہ ہے تو ہماری جنت کا وسلیہ عظمی حضور انور صلّی اللہ علیہ واٰلہٖ وسلّم ہیں اور حضور انور صلّی اللہ علیہ واٰلہٖ وسلّم پر خود ربِّ کریم کا فضل ربانی ہے: وَ كَانَ فَضْلُ اللّٰهِ عَلَیْكَ عَظِیْمًا(۱۱۳) (پ۵، النسآء:۱۱۳، ترجمہ کنزالایمان: اور اللہ کا تم پر بڑا فضل ہے۔) لہٰذا ہم اور رحمت سےجنتی ہیں حضور انور صلّی اللہ علیہ واٰلہٖ وسلّم دوسری رحمت سے،سورج و چاند دونوں کو نور ربِّ کریم نے دیا مگر چاند کو سورج کے ذریعہ اور سورج کو بلاواسطہ اپنی طرف سے لہٰذا اس حدیث سے حضور صلّی اللہ علیہ واٰلہٖ وسلّم کا ہماری مثل ہونا ثابت نہیں ہوتا۔(مراٰۃ المناجیح، 3/ 383، ملخصاً)\n۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔\n¥رحمت الٰہی تک پہنچانے والے اعمال:\n حضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اللہ پاک کے 99 نام ہیں جو ان مبارک ناموں کو گن گن کر اخلاص کے ساتھ پڑھتا رہے وہ جنت میں داخل ہوگا۔‘‘ \n(بخاری، کتاب الشروط، باب مایجوز من الاشتراط والثنیا فی الاقرار...الخ، ۲/ ۲۲۹، حدیث:۲۷۳۶)\n حضرت سیِّدُنا ابو امامہ رضی اللہ عنہ بیان کرتے ہیں کہ اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا:\n ’’جس نے ہر فرض نماز کے بعد آیۃ الکرسی پڑھی اسے موت کے علاوہ جنت میں داخلے سے کوئی چیز نہیں روک سکتی۔‘‘ \n(معجم کبیر، ۸/ ۱۱۴، حدیث:۷۵۳۲)\n حضرت سیِّدُنا سہل بن سعد رضی اللہ عنہ سے مروی ہے کہ رسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو مجھے دونوں جبڑوں اور دونوں ٹانگوں کے درمیان والی چیز کی حفاظت کی ضمانت دے، میں اسے جنت کی ضمانت دیتا ہوں۔‘‘ \n(بخاری، کتاب الرقاق، باب حفظ اللسان، ۴/ ۲۴۰، حدیث:۶۴۷۴)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6888, "bookId": 13, "volNo": "1", "hadithNo": 23, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "بھلائی ہی بھلائی", "arabic": "عَنْ اَبِيْ مَالِكِ الْحَارِثِ بْنِ عَاصِمِ الْاَشْعَرِيِّ رَضيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : ’’اَلطُّهُوْرُ شَطْرُ الْاِيْمَانِ وَالْحَمْدُ لِلّٰهِ تَمْلَاُ الْمِيْزَانَ وَسُبْحٰنَ اللهِ والْحَمْدُ لِلّٰهِ تَمْلَاٰنِ اَوْ تَمْلَاُ مَا بَيْنَ السَّمٰوَاتِ والْاَرْضِ وَالصَّلَاةُ نُوْرٌ وَّالصَّدَقَةُ بُرْهَانٌ وَّالصَّبْرُ ضِيَآءٌ وَّالْقُرْاٰنُ حُجَّةٌ لَّكَ اَوْ عَلَيْكَ كُلُّ النَّاسِ يَغْدُوْ فَبَآئِعٌ نَفْسَهٗ فَمُعْتِقُهَا اَوْ مُوْبِقُهَا.‘‘ (رَوَاہُ مُسْلِم)", "urdu": "حضرت سیِّدُنا ابومالک حارث بن عاصم اشعری رضی اللہ عنہ بیان کرتے ہیں کہ رسولُ اللہ صلّی اللہ علیہ وسلّم نے ارشاد فرمایا: ’’پاکیزگی (صفائی ستھرائی) آدھا ایمان ہے اور ’’اَلْحَمْدُلِلّٰہ“ ترازو کو بھر دیتا ہے اور ’’سُبْحٰنَ اللہ“ اور ” اَلْحَمْدُلِلّٰہ“ آسمان اور زمین کے درمیان کو بھر دیتے ہیں، نماز نور ہے،صدقہ دلیل ہے، صبر روشنی ہے اور قرآن تمہارے حق میں یا تمہارے خلاف دلیل ہے۔ ہر شخص اس حال میں صبح کرتا ہے کہ وہ خود کو بیچنے والاہوتا ہے، لہٰذا وہ اپنے آپ کوآزاد کرتایا ہلاک کرتا ہے۔‘‘ ( مسلم، كتاب الطهارة، باب فضل الوضوء، ص۱۱۵، حدیث:۵۳۴)", "roman": "Hazrat Sayyiduna Abu Malik Haris Bin Aasim Ash'ari RadiyAllahu Anhu bayan karte hain ke Rasoolullah Sallallahu Alayhi wa Sallam ne irshad farmaya: ''Pakeezgi (safai suthrai) aadha imaan hai aur 'Alhamdulillah' taraazu ko bhar deta hai aur 'SubhanAllah' aur 'Alhamdulillah' aasman aur Zameen ke darmiyan ko bhar dete hain, Namaz noor hai, Sadaqah daleel hai, sabr roshni hai aur Quran tumhare haq mein ya tumhare khilaf daleel hai. Har Shakhs is haal mein subah karta hai ke woh khud ko bechne wala hota hai, lihaza woh apne aap ko aazad karta ya halak karta hai.''(Muslim, Kitab-ut-Taharah, Baab Fazl-il-Wazu, Safha 115, Hadees: 534)", "explanation": "¥’’پاکیزگی آدھا ایمان ہے‘‘ کا معنیٰ ومفہوم:\n حضرت سیِّدُنا علامہ ابو زکریا یحییٰ بن شرف نووی رحمۃُ اللہ علیہ اس حدیث پاک کی شرح کرتے ہوئے فرماتے ہیں: ’’صفائی نصف ایمان ہے‘‘ کا ایک معنیٰ یہ ہے کہ طہارت کا اجر بڑھ کر نصف ایمان تک پہنچ جاتا ہے۔ دوسرا معنیٰ یہ ہے کہ جس طرح ایمان لانے سے سابقہ تمام گناہ مٹ جاتے ہیں، اسی طرح وضو سے بھی مسلمان کے سابقہ گناہ مٹ جاتے ہیں۔ ‘‘ \n(شرح مسلم للنووی، کتاب الطھارة، باب فضل الوضوء، الجزء الثالث، ۳/ ۱۰۰)\n¥ظاہری اور باطنی گناہوں سے پاکیزگی:\n حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے اس جز ’’صفائی نصف ایمان ہے‘‘ کی شرح میں فرماتے ہیں: ’’طُہُوْر‘‘ سے ظاہری پاکی اورایمان سے عرفی ایمان مرادہے۔ چونکہ ایمان بھی گناہوں کو مٹاتا ہے اور وضوءبھی،لیکن ایمان چھوٹے بڑے سارے گناہ مٹا دیتا ہے اور وضوءصرف چھوٹے،اس لیے اسے آدھا ایمان فرمایا۔ ایمان باطن کو عیبوں سے پاک فرماتا ہے اور وضو ظاہر کو گندگیوں سےاور ظاہر باطن کا گویا نصف ہےیا ایمان دل کو برائیوں سے پاک اور خوبیوں سے آراستہ کرتا ہے اور طہارت جسم کو فقط گندگیوں سے پاک کرتی ہے،لہٰذا یہ نصف ہے اورممکن ہے کہ ایمان سے مراد نماز ہو،ربّ (تعالیٰ ارشاد) فرماتاہے: ’’لِیُضِیْعَ اِیْمَانَكُمْؕ (پ۲، البقرة:۱۴۳) ‘‘۔ مطلب یہ ہے کہ نماز کی ساری شرطیں شرطِ طہارت کے برابر ہیں ۔غرضیکہ حدیث پر یہ اعتراض نہیں کہ ایمان بسیط چیز ہے پھر اس کا آدھا اورتہائی کیسا؟ (مراٰۃ المناجیح، 1/ 232)\n¥’’اَلْحَمْدُ لِلّٰہ¥‘‘ اور ’’سُبْحٰنَ ¥اللہ‘‘ کی فضیلت:\n’’اَلْحَمْدُلِلّٰہ‘‘ میزان کو جبکہ ’’ سُبْحٰنَ اللہ ‘‘ اور ’’ اَلْحَمْدُلِلّٰہ ‘‘ زمین و آسمان کے درمیان کو بھر دیتے ہیں۔ قرآن و سنت سے ثابت ہے کہ اعمال کا وزن کیا جاتا ہے اور اعمال کم اور زیادہ ہوتے ہیں۔ اس حدیث کا معنیٰ یہ ہے کہ اگر ’’ سُبْحٰنَ اللہ ‘‘ اور ’’ اَلْحَمْدُلِلّٰہ ‘‘ کے ثواب کو مجسم کیا جائے (یعنی جسمانی صورت دی جائے) تو ان کی جسامت آسمان اور زمین کو بھردے گی اور ان کے ثواب کے زیادہ ہونے کی وجہ یہ ہے کہ’’ سُبْحٰنَ اللہ ‘‘ کا کلمہ ربِّ کریم کے پاک اور ہرنقص وعیب سے بَری ہونے کے معنیٰ پر اور ’’اَلْحَمْدُلِلّٰہ‘‘ کا کلمہ اللہ پاک کی طرف محتاج ہونے کو بیان کرنے والا، اس کی حمد وثنا اور اس کا شکر بجا لانے پر مشتمل ہے۔(شرح مسلم للنووی، کتاب الطھارة، باب فضل الوضوء، الجزء الثالث، ۳/ ۱۰۱)\n¥تمام گناہوں پر بھاری:\n جو شخص ہر حال میں ’’اَلْحَمْدُلِلّٰہ‘‘ کہا کرے تو قیامت میں میزانِ عمل کے نیکی کا پلہ اس سے بھر جائے گا اور ایک حمد تمام گناہوں پر بھاری ہوگی۔(مراٰۃ المناجیح، 1/ 232)\n¥’’نماز نور ہے‘‘ کا معنیٰ ومفہوم:\nحدیث پاک میں ہے: ’’نماز نورہے ‘‘ اس کا ایک معنیٰ یہ ہے کہ جس طرح نور اندھیروں کو دور کر کے روشنی پھیلا دیتا ہے اسی طرح نماز گناہوں، بے حیائی اور بُرے کاموں کو دور کر کے نیک اعمال کی ہدایت دیتی ہے۔ دوسرا معنیٰ یہ ہے کہ بروزِ قیامت نمازی کا چہرہ نماز کی وجہ سے روشن و منور ہوگا اور دنیا میں بھی نمازی کا چہرہ تروتازہ رہتا ہے۔ \n(شرح مسلم للنووی، کتاب الطھارة، باب فضل الوضوء، الجزء الثالث، ۳/ ۱۰۰)\n¥سجدے کا نشان بیٹری کا کام دے گا: \nمشہور شارح حدیث، حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے اس جز ’’نماز نور ہے‘‘ کی شرح میں فرماتے ہیں: یعنی نماز مسلمان کے دل کی، چہرے کی، قبر کی، قیامت کی روشنی ہے۔پل صراط پرسجدہ کا نشان بیٹری کا کام دے گا، ربِّ (کریم ارشاد) فرماتاہے: ’’ نُوْرُهُمْ یَسْعٰى بَیْنَ اَیْدِیْهِمْ (پ۲۸، التحریم:۸، ترجمہ کنزالایمان: ان کا نور دوڑتا ہوگا ان کے آگے۔ ‘‘ اورممکن ہے کہ ’’صلوٰۃ‘‘ سے مراد درودشریف ہوکہ یہ بھی ہرطرح نورہے۔ (مراٰۃ المناجیح، 1/ 232)\n¥چمکتے چہرے: \nمنقول ہے کہ جب قیامت قائم ہوگی تو نمازیوں کو گروہ در گروہ جنّت کی طرف جانے کا حکم ہوگا، جب پہلا گروہ جنّت میں داخلے کے لئے لایا جائے گا تو اُن کے چہرے ستاروں کی طرح چمکتے دمکتے ہوں گے، فرشتے ان کا استقبال کریں گے اور ان سے پوچھیں گے: تم کون ہو؟ وہ کہیں گے: ہم اُمتِ محمدیہ کے نمازی ہیں۔ پھر پوچھا جائے گا: تمہارے اعمال کا کیا حال تھا؟ وہ کہیں گے : ہم اذان سنتے ہی وُضو کے لئے کھڑے ہوجاتے تھے اور دنیا کی کوئی چیز ہمیں اس سے روک نہیں سکتی تھی۔ فرشتے کہیں گے: تم اسی کے مستحق ہو کہ تمہیں جنّت میں داخل کیا جائے۔ پھر دوسرا گروہ جنّت میں داخلے کے لئے لایا جائے گا جن کا حُسن و جمال پہلے گروہ سے زیادہ ہوگا، ان کے چہرے چاند کی طرح چمکتے ہوں گے، فرشتے ان سے پوچھیں گے: تم کون ہو؟ وہ کہیں گے : ہم نماز پڑھنے والے تھے۔ پھر پوچھیں گے: تمہاری نمازوں کا کیا حال تھا؟ وہ کہیں گے: ہم نماز کے وقت سے پہلے ہی نماز کے لئے وُضو کرلیتے تھےاور اذان سن کر فوراً مسجد میں حاضر ہوجاتے۔ فرشتے کہیں گے: تم اسی کے مستحق ہو۔ پھر تیسرا گروہ جنّت میں داخلے کے لئے لایا جائے گا جن کا مقام و مرتبہ اور حسن و جمال پہلے گروہوں سے کہیں زیادہ ہوگا، اُن کے چہرے آفتاب (سورج) کی طرح روشن ہوں گے، فرشتے ان سے پوچھیں گے: تم اتنے خوب صورت اور اتنے اعلیٰ مقام والے کیوں ہو؟ وہ کہیں گے: ہم پابندی سےنماز پڑھا کرتے تھے۔ فرشتے پوچھیں گے: تمہاری نمازوں کا کیا حال تھا؟ وہ کہیں گے: ہم اذان ہونے سے پہلے ہی مسجد میں موجود ہوتے تھے اور اذان مسجد میں ہی سنتے تھے ، فرشتے کہیں گے : تم اسی کے مستحق ہو۔\n ( قوت القلوب، الفصل الثالث والثلاثون فی ذکر دعائم الاسلام الخمس...الخ، ۲/ ۱۶۸)\n¥’’صدقہ دلیل ہے‘‘ کا معنیٰ ومفہوم:\nحدیث پاک میں ہے:’’ صدقہ دلیل ہے‘‘ اس کا ایک معنیٰ یہ ہے کہ قیامت کے دن جب انسان سے یہ سوال کیا جائے گا کہ مال کہاں خرچ کیا ؟ تو اس کے صَدَقات اس سوال کے جواب پر (دلیل) بن جائیں گے۔ دوسرا معنیٰ یہ ہے کہ مال انسان کو فطرتاً عزیز ہوتا ہے اور جب وہ اللہ پاک کی راہ میں صَدَقہ دیتا ہے تو یہ صدقہ کرنا اس کے دعویٰ ایمان کی صداقت پر دلیل بن جاتا ہے۔(شرح مسلم للنووی، کتاب الطھارة، باب فضل الوضوء، الجزء الثالث، ۳/ ۱۰۱)\n¥محبت الٰہی کی دلیل اور بخشش کا کفیل:\n(صدقہ دلیل ہے) مومن کے ایمان کی کہ منافق اور کافر کو صحیح خیرات کی توفیق نہیں ملتی، یا کل قیامت میں صدقہ محبَّتِ پروردگار کی دلیل اور بخشش کا کفیل بنے گا، کیونکہ اسے ربِّ (کریم)نے قرض فرمایا ہے: ’’ مَنْ ذَا الَّذِیْ یُقْرِضُ اللّٰهَ (پ۲، البقرة: ۲۴۵)‘‘۔ خیال رہے کہ اس صدقہ میں زکوٰۃ،فطرہ وغیرہ تمام فرضی ونفلی خیراتیں داخل ہیں۔(مراٰۃ المناجیح، 1/ 232)\n¥صدقہ کی فضیلت پر مشتمل احادیث مبارکہ:\n حضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ اللہ پاک کے پیارے حبیب صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’مَا نَقَصَتْ صَدَقَۃٌ مِّنْ مَّالٍ یعنی صدقہ مال میں کمی نہیں کرتا۔‘‘\n(مسلم، کتاب البر والصلة والاداب، باب استحباب العفو والتواضع ، ص۱۰۷۱، حدیث:۶۵۹۲)\n حضرت سیِّدُنا رافع بن خدیج رضی اللہ عنہ بیان کرتے ہیں کہ اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: \n’’ اَلصَّدَقَۃُ تَسُدُّ سَبْعِیْنَ بَابًا مِّنَ السُّوْ ءِ یعنی صدقہ بُرائی کے 70 دروازے بند کردیتا ہے۔‘‘ (معجم کبیر، ۴/ ۲۷۴، حدیث:۴۴۰۲)\n اللہ پاک کے پیارے رسول صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بےشک مسلمان کا صدقہ اس کی عمر بڑھاتا اور بری موت کو روکتا ہے۔‘‘ (معجم کبیر، ۱۷/ ۲۲، حدیث:۳۱)\n حضرت سیِّدُنا عقبہ بن عامر رضی اللہ عنہ سے روایت ہے کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بےشک صدقہ کرنے والوں کو صدقہ قبر کی گرمی سے بچاتا ہے اور بلاشبہ مسلمان قیامت کے دن اپنے صدقے کے سائے میں ہوگا۔‘‘ \n(شعب الایمان، باب الثانی والعشرین فی شعب الایمان وھو باب فی الزکاة، التحریض علی الصدقة التطوع، ۳/ ۲۱۲، حدیث:۳۳۴۷)\n¥’’صبر روشنی ہے‘‘ کا معنیٰ ومفہوم:\n’’صبر ضیاء (روشنی) ہے‘‘ اس سے مراد یہ ہے کہ صبر ایک پسندیدہ عمل ہے اور صبر کرنے والا ہمیشہ ترو تازہ اور ہدایت پر مستقیم رہتا ہے۔ حضرت سیِّدُنا ابراہیم خواص رحمۃُ اللہ علیہ فرماتے ہیں: کتاب اور سنت پر ثابت قدم رہنا صبر ہے۔ حضرت سیِّدُنا اِبنِ عطاء رحمۃُ اللہ علیہ فرماتے ہیں: حوصلہ اور برداشت کے ساتھ مصائب کا سامنا کرنا صبر ہے۔ حضرت سیِّدُنا ابو علی دقاق رحمۃُ اللہ علیہ فرماتے ہیں: صبر کی حقیقت یہ ہے کہ تقدیر پر اعتراض نہ کیا جائے، البتہ مصائب کا اظہار کرنا صبر کے منافی نہیں بشرطیکہ یہ اظہار بطورِ شکایت نہ ہو۔ (شرح مسلم للنووی، کتاب الطھارة، باب فضل الوضوء، الجزء الثالث، ۳/ ۱۰۱)\n¥دل اور چہرے کا نور:\nحکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے اس جز ’’صبر ضیاء (روشنی) ہے‘‘ کی شرح میں فرماتے ہیں: صبر کے لغوی معنیٰ ہیں روکنا، یعنی نفس کو گناہوں سے روکنا، یا عبادت پر قائم رکھنا، یا مصیبتوں پر گھبراہٹ سے روکنا۔ (صبر) دل کا یا چہرے کا نور ہے۔ خیال رہے کہ نور ہر روشنی کو کہا جاسکتا ہے ہلکی ہو یا تیز، مگر ضیاءصرف تیز روشنی کو کہتے ہیں۔ربِّ (کریم ارشاد) فرماتاہے: ’’ جَعَلَ الشَّمْسَ ضِیَآءً وَّ الْقَمَرَ نُوْرًا (پ۱۱، یونس:۵، ترجمہ کنزالایمان: سورج کو جگمگاتا بنایا اور چاند چمکتا۔ ‘‘ چونکہ صبرہر عبادت میں ضروری ہے اس لیے نماز کو نور اور اسے ضیاءفرمایا گیا، ہو سکتا ہے کہ صبر سے مراد روزہ ہوچونکہ روزہ صرف اللہ کا ہے اس لئے ضیاء یعنی جگمگاہٹ فرمایا گیا۔(مراٰۃ المناجیح، 1/ 232)\n¥قبر کا اجالا:\n علامہ علی قاری رحمۃُ اللہ علیہ فرماتے ہیں: ایک قول کے مطابق نفس کواس کی خواہشوں سے روکنا، گِراں گزرنے والی عبادات کی طرف اسے مائل کرکے اس راہ میں آنے والی تکالیف کو برداشت کرنا صبر کہلاتا ہے۔ جب بندہ اپنے صبر کے عہد کو پورا کرے تو یہ اس کے لئے ضیاء ( روشنی) ہے کیونکہ اگر صبر کو ترک کیا تو گناہوں کے اندھیرے میں جا گرے گا۔ ضیاء سے مراد قبر کا اُجالا ہے، کیونکہ جب مومن دنیا کی زندگی میں اللہ پاک کی اطاعت، بلاؤں اور گناہوں سے بچنے پر صبر کرتا ہے تو اللہ پاک اس کی تنگ وتاریک قبر کو کشادہ ومنورفرما دیتا ہے۔(مرقاة المفاتیح، کتاب الطھارت، الفصل الاول، ۲/ ۸، تحت الحدیث:۲۸۱)\n¥حکم کے اعتبار سے صبر کی اقسام:\nحضرت سیِّدُنا امام محمد غزالی رحمۃُ اللہ علیہ فرماتے ہیں کہ حکم کے اعتبار سے صبر کی چار قسمیں ہیں: (1)…فرض، (2)…نفل، (3)…مکروہ اور (4)…حرام۔ ممنوعہ کاموں سے صبر کرنا ’’فرض‘‘ ہے (جیساکہ گناہوں سے صبر کرنا)۔ ناپسندیدہ امور پر صبر کرنا ’’نفل‘‘ ہے (یعنی نفس کی ناپسندیدہ باتوں مثلاً: نفلی عبادات صدقہ و خیرات وغیرہ پر صبر کرنا کیو نکہ نیک اعمال نفس پر بہت گراں گزرتے ہیں )۔ شرعی طور پر ممنوع اذیت پر صبر کرنا ممنوع ہے جیسے بلا وجہ کسی شخص یا اس کے بیٹے کا ہاتھ کاٹا جائے اور وہ اس پر صبر کرتے ہوئے خاموشی اختیار کرے۔ اسی طرح اگر کوئی آدمی شہوت کے ساتھ اس کی بیوی کا قَصْد کرے تو اس سے اس کی غیرت جاگ اٹھے لیکن غیرت کے اظہار سے صبر کرے اور اس کی بیوی سے جو سلوک کیا جائے اس پر خاموشی اختیار کرے تو یہ صبر ’’حرام‘‘ ہے اور جو صبر ایسی اذیت پر ہو جو شرعی طور پر مکروہ طریقے سے پہنچے اس پر صبر کرنا مکروہ ہے۔ گویا صبر کی کسوٹی شریعت کا معیار ہے، لہٰذا صبر کے ’’نصف ایمان‘‘ ہونے سے یہ مراد نہیں لینی چاہئے کہ ہر قسم کا صبر محمود (یعنی قابل تعریف)ہے بلکہ اس سے صبر کی مخصوص انواع مراد ہیں۔\n(احیاء علوم الدین، کتاب الصبر والشکر، بیان اقسام الصبر بحسب اختلاف القوة والضعف، ۴/ ۸۵)\n¥مومن کے ایمان کی علامت:\nحضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے انصار صحابَۂ کرام علیہمُ الرّضوان کے پاس تشریف لاکر ارشاد فرمایا: ’’کیا تم مومن ہو؟‘‘ وہ خاموش رہے تو حضرت سیِّدُنا عمر فاروق اعظم رضی اللہ عنہ نے عرض کی: جی ہاں، یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ۔ ارشاد فرمایا: ’’تمہارے ایمان کی علامت کیا ہے؟‘‘ صحابَۂ کرام علیہمُ الرّضوان نے عرض کی: ہم فراخی کی حالت میں شکر کرتے، آزمائش کے وقت صبر کرتے اور اللہ پاک کے فیصلے پر راضی رہتے ہیں۔ آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا:’’ربِّ کعبہ کی قسم! تم مومن ہو۔‘‘ (معجم اوسط، ۶/ ۴۶۷، حدیث:۹۴۲۷۔ معجم کبیر، ۱۱/ ۱۲۳، حدیث:۱۱۳۳۶)\n¥تمہارے حق میں یا تمہارے خلاف:\nامام یحییٰ بن شرف نووی رحمۃُ اللہ علیہ حدیث پاک کے اس جز ’’قرآن تمہارے حق میں یا تمہارے خلاف دلیل ہے‘‘ کی شرح میں فرماتے ہیں: یعنی اگر تم قرآن مجید کی تلاوت اور اس کے احکامات پر عمل کرو گے تو یہ تمہارے حق میں دلیل ہوگا ورنہ تمہارے خلاف دلیل ہوگا۔ (شرح مسلم للنووی، کتاب الطھارة، باب فضل الوضوء، الجزء الثالث، ۳/ ۱۰۲)\n¥جہنم سے آزادی یا ہلاکت:\n متن میں موجود حدیث شریف کے آخری میں فرمایا گیا: ’’ہر شخص جب صبح کرتا ہے تو وہ اپنے آپ کو فروخت کرنے والا ہوتا، پھر یا تو اپنے آپ کو آزاد کروانے والا ہوتا ہے یا ہلاک کرنے والا ہوتا ہے ‘‘ اس کا مطلب یہ ہے کہ ہر انسان عمل کرتا ہے ، بعض انسان اللہ پاک کے احکام مان کر اپنے نفس کواللہ پاک کے حوالے کر دیتے اور اپنے نفس کو جہنم سے آزاد کرالیتے ہیں جبکہ بعض انسان شیطان اور خواہش نفس کی اتباع کر کے خود کو شیطان کے ہاتھوں فروخت کردیتے ہیں اور شیطان انہیں جہنم میں پہنچا کر ہلاک کر دیتا ہے۔ (شرح مسلم للنووی، کتاب الطھارة، باب فضل الوضوء، الجزء الثالث، ۳/ ۱۰۲)\n¥زندگی کی دکان:\n حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے مذکورہ جز کے تحت فرماتے ہیں: یعنی روزانہ صبح کے وقت ہرشخص اپنی زندگی کی دُکان کھولتا ہے، سانسیں صَرف کرکے اعمال کماتا ہے، اگراچھے اعمال میں سانسیں گزریں تو سودانفع کارہا، نفس جہنم سے بچ گیا اور اگر برے کام کئے تو سودا گھاٹے کا رہا، نفس کو ہلاک کر دیا۔ نفس سے مراد ذات دل اور سانسیں سب کچھ ہوسکتے ہیں۔ سُبْحٰنَ اللہ! اس اَفْصَحُ الْفُصَحَآءعرب (سب سے بڑے فصیح) کے قربان جاؤں کیسے جامع کلمات ارشاد فرمائے۔ خیال رہے کہ ہم جیسے گنہگاروں کی دکانِ زندگی صبح کھل کرسوتے وقت بند ہوجاتی ہے، بعض وہ خوش نصیب بھی ہیں جن کی دکان کبھی بند ہی نہیں ہوتی اور ان کا بازارکبھی سُونا ہی نہیں ہوتا، سوتے میں بھی دکانداری کرتے ہیں،کیونکہ ان کا دل جاگتا ہے بلکہ بعد وفات بھی ان کے میلے لگے ہوئے ہیں۔ (مراٰۃ المناجیح، 1/ 232)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6889, "bookId": 13, "volNo": "1", "hadithNo": 24, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "شانِ خداوندی اور ظلم کی حرمت", "arabic": "عَنْ اَبِيْ ذَرٍّ رَضيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِيْمَا رَوٰی عَنِ اللهِ عَزَّ وَجَلَّ اَنَّهٗ قَالَ: ’’يَا عِبَادِيْ اِنِّيْ حَرَّمْتُ الظُّلْمَ عَلٰى نَفْسِيْ وَجَعَلْتُهٗ بَيْنَكُمْ مُحَرَّمًا فَلَا تَظَالَمُوْا. يَا عِبَادِيْ كُلُّكُمْ ضَالٌّ اِلَّا مَنْ هَدَيْتُهٗ فَاسْتَهْدُوْنِيْ اَهْدِكُمْ. يَا عِبَادِيْ كُلُّكُمْ جَآئِعٌ اِلَّامَنْ اَطْعَمْتُهٗ فَاسْتَطْعِمُوْنِيْ اُطْعِمْكُمْ. يَا عِبَادِيْ كُلُّكُمْ عَارٍ اِلَّا مَنْ كَسَوْتُهٗ فَاسْتَكْسُوْنِيْ اَكْسُكُمْ. يَا عِبَادِيْ اِنَّكُمْ تُخْطِئُوْنَ بِاللَّيْلِ وَالنَّهَارِ وَاَنَا اَغْفِرُ الذُّنُوْبَ جَمِيْعًا فَاسْتَغْفِرُوْنِيْ اَغْفِرْ لَكُمْ. يَا عِبَادِيْ اِنَّكُمْ لَنْ تَبْلُغُوْا ضُرِّيْ فَتَضُرُّوْنِيْ وَلَنْ تَبْلُغُوْا نَفْعِيْ فَتَنْفَعُوْنِيْ. يَا عِبَادِيْ لَوْ اَنَّ اَوَّلَكُمْ وَاٰخِرَكُمْ وَاِنْسَكُمْ وَجِنَّكُمْ كَانُوْا عَلٰى اَتْقَى قَلْبِ رَجُلٍ وَّاحِدٍ مِّنْكُمْ مَا زَادَ ذٰلِكَ فِيْ مُلْكِيْ شَيْئًا. يَا عِبَادِيْ لَوْ اَنَّ اَوَّلَكُمْ وَاٰخِرَكُمْ وَاِنْسَكُمْ وَجِنَّكُمْ كَانُوْا عَلٰى اَفْجَرِ قَلْبِ رَجُلٍ وَّاحِدٍ مِّنْكُمْ مَا نَقَصَ ذٰلِكَ مِنْ مُلْكِيْ شَيْئًا. يَا عِبَادِيْ لَوْ انَّ اَوَّلَكُمْ وَاٰخِرَكُمْ وَاِنْسَكُمْ وَجِنَّكُمْ قَامُوْا فِيْ صَعِيْدٍ وَّاحِدٍ فَسَاَلُوْنِيْ فَاَعْطَيْتُ كُلّ اِنْسَانٍ مَّسْاَلَتَهٗ مَا نَقَصَ ذٰلِكَ مِمَّا عِنْدِيْ اِلَّاكَمَا يَنْقُصُ الْمِخْيَطُ اِذَا اُدْخِلَ الْبَحْرَ. يَا عِبَادِيْ اِنَّمَا هِيَ اَعْمَالُكُمْ اُحْصِيْهَا لَكُمْ ثُمَّ اُوَفِّيْكُمْ اِيَّاهَا فَمَنْ وَّجَدَ خَيْرًا فَلْيَحْمَدِ اللهَ وَمَنْ وَّجَدَ غَيْرَ ذٰلِكَ فَلَا يَلُوْمَنَّ اِلَّا نَفْسَهٗ.‘‘(رَوَاہُ مُسْلِم)", "urdu": "حضرت سیِّدُنا ابوذر رضی اللہ عنہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم سے ایک حدیث قدسی روایت کرتے ہیں کہ اللہ پاک نےارشاد فرمایا:\n اےمیرے بندو! میں نے ظلم کو اپنےآپ پر حرام کیا ہے اور تمہارے آپس میں بھی ظلم کو حرام فرمادیا، لہٰذاایک دوسرے پر ظلم نہ کرو۔\n اے میرے بندو! تم سب راستےسے بھٹکے ہوئے ہو، سوائے اس کے جس کو میں ہدایت دوں، لہٰذا مجھ سے ہدایت مانگو، میں تمہیں ہدایت دوں گا۔\n اےمیرے بندو! تم سب کے سب بھوکے ہو، سوائے اس کے جسے میں کھلاؤں، لہٰذا مجھ سے کھانا مانگو، میں تمہیں کھلاؤں گا۔\n اےمیرے بندو! تم سب کے سب برہنہ ہو، سوائے اس کے جس کو میں لباس پہناؤں، لہٰذا مجھ سے لباس مانگو میں تمہیں لباس دوں گا۔\n اےمیرے بندو! تم دن رات گناہ کرتے ہو اور میں ہی سب کے سب گناہ معاف کرتا ہوں، لہٰذا مجھ سےبخشش مانگو میں تمہیں بخش دوں گا۔\n اے میرے بندو! تم میرے نقصان کو نہیں پہنچ سکتے کہ مجھے نقصان پہنچادو اور نہ میرے نفع تک تمہاری رسائی ہے کہ مجھے نفع دو۔\n اےمیرے بندو! اگر تمہارے اگلے پچھلے انسان اور جن تمہارے سب سےبڑے پرہیزگارشخص کے دل جیسے ہو جائیں تب بھی میری بادشاہت میں کچھ بڑھا نہیں سکتے۔\n اےمیرے بندو! اگر تمہارے اگلے پچھلے انسان اور جن تم میں سے سب سے بڑے بدکار کے دل جیسے ہو جائیں تو بھی میری بادشاہت میں کچھ کمی نہیں کر سکتے۔\n اے میرے بندو! اگر تمہارے اگلے پچھلے انسان اور جن ایک میدان میں کھڑے ہوکر مجھ سے سوال کریں اور میں ہر انسان کا سوال پورا کردوں تو بھی میرے خزانوں میں کچھ کمی نہ ہوگی مگر اتنا ہی جتنا سوئی کو سمندر میں ڈال کر نکالا جائے (یعنی کچھ بھی کم نہ ہو گا)۔\n اے میرے بندو! تمہارے اعمال میرے شمار میں ہیں، میں تمہیں ان کا پورا پورا بدلہ دوں گا لہٰذا جوبھلائی پائے وہ اللہ پاک کا شکر ادا کرےاور جو اس کے علاوہ پائے تو وہ اپنے آپ ہی کو ملامت کرے۔\n( مسلم، كتاب البر والصلة والاداب، باب تحريم الظلم، ص۱۰۶۸، حدیث:۶۵۷۲)", "roman": "Hazrat Sayyiduna Abu Zar RadiyAllahu Anhu Huzoor Nabi-e-Kareem Sallallahu Alayhi wa Sallam se ek Hadees-e-Qudsi Riwayat karte hain ke Allah Paak ne irshad farmaya:\nAe Mere bando! Main ne zulm ko apne aap par Haram kiya hai aur tumhare aapas mein bhi zulm ko Haram farma diya, lihaza ek doosre par zulm na karo.\nAe Mere bando! Tum sab raaste se bhatke hue ho, siwaye us ke jis ko Main hidayat doon, lihaza Mujh se hidayat maango, Main tumhein hidayat doonga.\nAe Mere bando! Tum sab ke sab bhooke ho, siwaye us ke jise Main khilaoon, lihaza Mujh se khana maango, Main tumhein khilaoon ga.\nAe Mere bando! Tum sab ke sab barhana ho, siwaye us ke jis ko Main Libaas pehnaoon, lihaza Mujh se Libaas maango Main tumhein Libaas doonga.\nAe Mere bando! Tum din raat gunah karte ho aur Main hi sab ke sab gunah maaf karta hoon, lihaza Mujh se bakhshish maango Main tumhein bakhsh doonga.\nAe Mere bando! Tum Mere nuqsan ko nahin pohanch sakte ke Mujhe nuqsan pohancha do aur na Mere nafa tak tumhari rasaai hai ke Mujhe nafa do.\nAe Mere bando! Agar tumhare agle pichhle insaan aur jinn tumhare sab se bade parhezgaar Shakhs ke dil jaise ho jayein tab bhi Meri badshahat mein kuch barha nahin sakte.\nAe Mere bando! Agar tumhare agle pichhle insaan aur jinn tum mein se sab se bade badkaar ke dil jaise ho jayein to bhi Meri badshahat mein kuch kami nahin kar sakte.\nAe Mere bando! Agar tumhare agle pichhle insaan aur jinn ek maidan mein khade hokar Mujh se Sawaal karein aur Main har insaan ka Sawaal poora kar doon to bhi Mere khazano mein kuch kami na hogi magar itna hi jitna sui ko samandar mein daal kar nikala jaye (ya'ni kuch bhi kam na hoga).\nAe Mere bando! Tumhare a'maal Mere shumar mein hain, Main tumhein un ka poora poora badla doonga lihaza jo bhalai paaye woh Allah Paak ka shukr ada kare aur jo is ke ilawah paaye to woh apne aap hi ko malamat kare.\n(Muslim, Kitab-ul-Birr was-Silah wal-Aadab, Baab Tahreem-iz-Zulm, Safha 1068, Hadees: 6572)", "explanation": "¥اَہْلِ شام کے نزدیک شرف والی حدیث:\nسیِّدُنا امام احمد بن حنبل رحمۃُ اللہ علیہ فرماتے ہیں: اہل شام کے لئے اس سے زیادہ شرف والی اور کوئی حدیث نہیں۔\n(ریاض الصالحین، باب المجاھدة، ص ۴۱، تحت الحدیث:۱۱۱)\nحضرت سیِّدُنا سعید بن عبدالعزيز رحمۃُ اللہ علیہ فرماتے ہیں: ’’حضرت سیِّدُنا ابو ادریس خولانی رحمۃُ اللہ علیہ جب یہ حدیث پاک بیان کرتے تو گھٹنوں کے بل جھک جاتے تھے۔‘‘ ( مسلم، كتاب البر والصلة والاداب، باب تحريم الظلم، ص۱۰۶۹، تحت الحدیث:۶۵۷۲) \n¥حدیث قدسی اور حدیث نبوی کی تعریف:\n حضور نبی کریم صلّی اللہ علیہ وسلّم کے قول، فعل اور تقریر کو حدیث کہتے ہیں۔ تقریر کا مطلب یہ ہے کہ آپ کے سامنے کوئی کام کیا گیا اور آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے اس سے منع نہیں فرمایا یا صحابَۂ کرام علیہمُ الرّضوان میں سے کسی نے کوئی بات کہی اور حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے اسے رد نہیں کیا بلکہ خاموش رہے اور عملاً اسے ثابت فرما دیا۔ (المقدمةفی اصول الحدیث، ص۱۹) جبکہ حدیث قدسی وہ حدیث جس کے راوی سرکار صلّی اللہ علیہ واٰلہٖ وسلّم ہوں اور نسبت اللہ پاک کی طرف ہو۔\n (نصاب اصول حدیث مع الافادات الرضویہ، ص32) \n¥قرآنِ کریم اور حدیث قدسی میں فرق:\n قرآنِ مجید اور حدیث قدسی میں فرق یہ ہے کہ قرآنِ کریم کے الفاظ ومعانی دونوں اللہ پاک کی طرف سے ہوتے ہیں جبکہ حدیث قدسی کے معانی اللہ پاک کی جانب سے اور الفاظ رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم کی طرف سے ہوتے ہیں اور احادیث قدسیہ کی تعداد 100 سے زائد ہے۔ (دلیل الفالحین، باب فی الصبر، الجزء الاول، ۱/ ۱۷۲، تحت الحدیث:۳۲، ملخصًا)\n¥ظلم کی تعریف:\n ظلم کا لغوی معنیٰ ’’کسی چیز کو اس کے غیر محل میں استعمال کرنا‘‘ جبکہ شرعی معنیٰ ’’کسی اور کے حق میں ناحق تصرف کرنا اور حد سے تجاوز کرنا‘‘ ظلم کہلاتا ہے۔(دلیل الفالحین، باب فی المجاھدة، الجزء الثانی، ۱/ ۳۳۱، تحت الحدیث:۱۱۱)\n حضرت سیِّدُنا علامہ سیِّد میر شریف جُرجانی رحمۃُ اللہ علیہ ظلم کی لغوی تعریف بیان کرتے ہوئے فرماتے ہیں: کسی چیز کو غیر محل میں رکھنا ظلم کہلاتا ہے۔ (التعریفات للجرجانی، ص۱۰۲)\n¥اللہ پاک کی ذات ظلم سے پاک ہے:\n مذکورہ حدیث شریف کے شروع میں ارشاد ہوا کہ ’’میں نے ظلم کو اپنے آپ پر حرام کیا ہے‘‘ اس کی شرح کرتے ہوئے مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں: یہاں حرمت سے مراد شرعی حرمت نہیں کیونکہ حق تعالیٰ پر نہ کوئی حاکم ہے اور نہ اس پر شرعی احکام جاری ہیں بلکہ اس سے مراد ہے برتر ہونا، منزہ ہونا،پاک ہونارب تعالیٰ کے لیے کوئی شے ظلم ہوسکتی ہی نہیں کیونکہ ظلم کے معنیٰ ہیں دوسرے کی مِلک میں زیادتی کرنا یا کسی چیز کو بے محل استعمال کرنا ان دونوں سے پروردگار پاک ہے کیونکہ ہر چیز اس کی ملک ہے اور(وہ) جس کے استعمال کے لیے جو جگہ مقرر فرمادے وہی اس کا صحیح مصرف ہے اس کے افعال یا عدل ہیں یا فضل۔ اس کے معنیٰ یہ ہیں کہ میں ظلم سے منزہ اور پاک ہوں میرا کوئی کام ظلم نہیں ہو سکتا۔(مراٰۃ المناجیح، 3/ 354)\n حضرت سیِّدُنا علامہ ابو زکریا یحییٰ بن شرف نووی رحمۃُ اللہ علیہ حدیث پاک کے مذکورہ جز کی شرح میں بیان کرتے ہیں کہ علمائے کرام رحمۃُ اللہ علیہم فرماتے ہیں: اس کا معنیٰ ہے کہ میں ظلم سے پاک اور برتر ہوں۔ ظلم کا لفظ اللہ پاک کے حق میں استعمال کرنا محال ہے۔ ربِّ کریم کی ذات اس سے پاک ہے کیونکہ ظلم کا معنیٰ ہے حد سے تجاوز کرنا اور اللہ پاک حد سے تجاوز کر ہی نہیں سکتا کیونکہ اس پر کوئی حاکم نہیں جو اس کے لئے حدود قائم کرے وہ سب کا حاکم ہےاور ظلم کا معنیٰ ہے کسی اور کی مِلک میں تصرف کرنا اور اللہ پاک کسی کی مِلک میں تصرف کیسے کرسکتا ہے کیونکہ ہر چیز اسی کی ملکیت میں ہے وہ سارے جہان کا مالک ہے۔ (شرح مسلم للنووی ، کتاب البر و الصلة...الخ ، باب تحریم الظلم، الجزء السادس عشر، ۱۶‏/ ۱۳۲، ماخوذًا)\n¥ایک دوسرے پر ظلم نہ کرو :\n حدیث شریف کے جز ’’میں نے تمہارے آپس میں بھی ظلم کو حرام کیا ہے، لہٰذا ایک دوسرے پر ظلم نہ کرو ‘‘ کی شرح کرتے ہوئے مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں: یعنی تم کسی پر جانی مالی یا آبرو ریزی کا ظلم نہ کرو یہ تمام جرموں سے بڑا جرم ہے کہ یہ حَقُّ العباد ہے توبہ سے بھی معاف نہیں ہوتا(جب تک صاحب حق سے معاف نہ کروا لیا جائے)۔\n(مراٰۃ المناجیح، 3/ 354)\n¥ظالم سے مظلوم کا بدلہ اللہ پاک لےگا:\nلوگوں کو ایک دوسرے پر ظلم کرنے سے منع کرنے کی ایک بڑی وجہ یہ ہے کہ اللہ پاک خود ظالم سے مظلوم کا بدلہ لے گا۔ چنانچہ حضرت سیِّدُنا علامہ ملّا علی قاری رحمۃُ اللہ علیہ فرماتے ہیں: ایک دوسرے پر ظلم نہ کرو یعنی کوئی کسی پر ظلم نہ کرے ۔ کیونکہ میں مظلوم کے ظلم کا اُس ظالم سے خود بدلہ لوں گا۔ جیسا کہ ایک حدیثِ قدسی میں ہے: ’’میں مظلوم کی مدد ضرور کرتا ہوں اگر چہ کچھ وقت کے بعد (یعنی وہ انہیں چھوڑنے والا نہیں بلکہ انہیں ڈھیل دیتا ہے)۔‘‘ چنانچہ قرآنِ مجید میں ہے:\nوَ لَا تَحْسَبَنَّ اللّٰهَ غَافِلًا عَمَّا یَعْمَلُ الظّٰلِمُوْنَ۬ؕ -اِنَّمَا یُؤَخِّرُهُمْ لِیَوْمٍ تَشْخَصُ فِیْهِ الْاَبْصَارُۙ(۴۲) (پ ۱۳، ابراھیم:۴۲)\nترجمہ کنزالایمان: اور ہرگز اللہ کو بےخبر نہ جاننا ظالموں کے کام سے انھیں ڈھیل نہیں دے رہا ہے مگر ایسے دن کے لیے جس میں آنکھیں کھلی کی کھلی رہ جائیں گی۔\n(مرقاة المفاتیح، کتاب الدعوات، باب الاستغفار والتوبة، ۵/ ۱۵۵، تحت الحدیث:۲۳۲۶، ملتقطًا)\n¥ظلم کی حرمت پر تمام مذاہب کا اجماع ہے:\n حضرت سیِّدُنا علامہ محمد بن علّان شافعی رحمۃُ اللہ علیہ فرماتے ہیں: ظلم کی حرمت پر تمام مذاہب کا اجماع ہے کیوں کہ جانوں کی حفاظت پر سب کا اتفاق ہے۔ ظلم کبھی نسب میں ہوتا ہے تو کبھی آبرو میں، کبھی مال میں تو کبھی عقل میں، کبھی ان سب میں اور کبھی ان میں سے بعض میں۔ (دلیل الفالحین، باب فی المجاھدة، الجزء الثانی، ۱/ ۳۳۲، تحت الحدیث:۱۱۱)\n¥سب سے بڑا ظلم کیا ہے؟ \n یاد رکھئے! سب سے بڑا ظلم شرک ہے۔ اللہ پاک قرآن مجید میں ارشاد فرماتا ہے:\nاِنَّ الشِّرْكَ لَظُلْمٌ عَظِیْمٌ(۱۳) (پ ۲۱، لقمٰن:۱۳)\nترجمہ کنزالایمان: بےشک شرک بڑا ظلم ہے۔\n اکثر آیات میں ظلم سے یہی معنیٰ یعنی شرک ہی مراد ہے البتہ بعض آیات میں گناہوں کی مختلف انواع کو بھی ظلم سے تعبیر کیا گیا ہے۔ (دلیل الفالحین، باب فی المجاھدة، الجزء الثانی، ۱/ ۳۳۲، تحت الحدیث:۱۱۱)\n¥ظلم کی ممانعت پر مشتمل احادیث مبارکہ:\nحضرت سیِّدُنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ظلم قیامت کے دن تاریکیاں ہیں۔‘‘ (بخاری، کتاب المظالم والغضب، باب الظلم ظلمات یوم القیامة، ۲/ ۱۲۷، حدیث:۲۴۴۷)\n سیِّدُنا ابن عباس رضی اللہ عنہما سے مروی ہے کہ رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’مظلوم کی بددعا سے بچو کہ اس کے اور اللہ پاک مابین کوئی پردہ نہیں۔‘‘ (بخاری، کتاب المظالم والغضب، باب الاتقاء والحذر من دعوة المظلوم، ۲/ ۱۲۸، حدیث:۲۴۴۸)\n¥گمراہیت وہدایت:\nمفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ مذکورہ حدیث شریف کے جز ’’ تم سب گمراہ ہو سوائے اُس کے جسے میں ہدایت دوں‘‘ کی شرح میں فرماتے ہیں: اس کا مطلب یہ ہے کہ ہماری پیدائش تاریکی میں ہوئی پھر ہم پر نور کا چھینٹا دیا گیا اگر ہم کو ہمارے نفسوں پر چھوڑ دیا جائے تو ہم عقیدتًا عملًا بدی ہی کریں گے،اگر وہ اپنا فضل کرے تو ہم نیکی کریں ،ہم ببول کا درخت ہیں ، ہمارے پاس سوائے گناہوں کے کانٹوں کے اور کیا ہے، ہماری صفت ہے: اِنَّهٗ كَانَ ظَلُوْمًا جَهُوْلًاۙ(۷۲) (پ ۲۲، احزاب:۷۲، ترجمہ کنز الایمان:بےشک وہ اپنی جان کو مشقت میں ڈالنے والا بڑا نادان ہے)۔ لہٰذا یہ حدیث اس کے خلاف نہیں کہ بچہ فطرت یعنی توحید پر پیدا ہوتا ہے کہ وہاں دنیا میں آنے کا ذکر ہے اور یہاں ہماری اصل پیدائش کا۔خیال رہے کہ حضرات انبیاءواولیاءبھی رب تعالیٰ ہی کی ہدایت سے ہدایت یافتہ ہیں مگر وہ ہمارے لیے ہدایت کا مرکز ہیں کہ ہم ان سے ہی ہدایت لے سکتے ہیں جیسے سورج کو نور رب تعالیٰ نے دیا ہے مگر چاند تارے اور زمین اس سے ہی نور لیتے ہیں۔ ربّ تعالیٰ فرماتا ہے: اِنَّكَ لَتَهْدِیْۤ اِلٰى صِرَاطٍ مُّسْتَقِیْمٍۙ(۵۲) (پ۲۵، الشورٰی:۵۲، ترجمہ کنز الایمان:بےشک تم ضرور سیدھی راہ بتاتے ہو)۔ (مراٰۃ المناجیح، 3/ 354)\nحدیث پاک کے جز ’’تم سب گمراہ ہو سوائے اُس کے جسے میں ہدایت دوں‘‘ کی شرح کرتے ہوئے امام یحییٰ بن شرف نووی رحمۃُ اللہ علیہ فرماتے ہیں کہ حضرت سیِّدُنا امام مازری رحمۃُ اللہ علیہ کا قول ہے: اس سے یہ ظاہر ہوتا ہے کہ تمام لوگ گمراہی پر پیدا ہوئے ہیں سوائے اس کے جسے اللہ پاک ہدایت دےجبکہ مشہور حدیث میں ہے کہ ہر بچہ فطرت یعنی دیْنِ اسلام پر پیدا ہوتا ہے (تو اس کا کیا جواب ہے؟)۔ اس کا جواب یہ ہے کہ پہلی حدیث میں لوگوں کو اس گمراہی سے مُتَّصِفْ کیا گیا ہے جس پر رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم کو بھیجنے سے پہلے وہ لوگ تھے، اگر اللہ پاک اُنہیں اُن کے حال پر چھوڑ دیتا اور وہ لوگ اُسی شہوت پرستی، راحت اور توحید میں غور وخوض سے غفلت میں رہتے تو گمراہ ہوجاتے۔ \n(شرح مسلم للنووی، کتاب البر و الصلة...الخ، باب تحریم الظلم، الجزء السادس عشر، ۱۶/ ۱۳۲)\n¥گمراہ ہونے کے دو معنیٰ اور ان کی وضاحت:\n حضرت سیِّدُنا علامہ محمد بن علان شافعی رحمۃُ اللہ علیہ نے گمراہ ہونے کے دو معنیٰ بیان فرمائے ہیں: (1)…تم رسولوں کی بعثت سے پہلے شریعت سے غافل تھے۔ (2)…اگر اللہ پاک تمہیں تمہارے حال پہ چھوڑ دیتا تو تم حق سے بھٹک جاتے۔ اب پہلے معنیٰ کا اعتبار کریں تو مطلب یہ ہوگا کہ ’’تم سب رسولوں کی بعثت سے پہلے شریعت سے غافل تھے سوائے ان لوگوں کے جنہیں اللہ پاک نےاُس پر ایمان لانے کی توفیق دےدی جو کچھ رسول لے کر آئے۔‘‘ دوسرے معنیٰ کا اعتبار کریں تو مطلب یہ ہوگا کہ ’’ اگر اللہ پاک تمہیں تمہارے حال پہ چھوڑ دیتا تو تم سب حق سے بھٹک جاتے سوائے ان لوگوں کے جنہیں اللہ پاک اپنی معرفت تک لے جانے والے امور میں غورو فکر اور جو احکامات اس کے پاس سے آئےاس پر عمل کی توفیق دےدے۔‘‘ دونوں صورتوں میں یہ حدیث اس مشہور حدیث کے منافی نہیں جس میں فرمایا گیا کہ ’’ہر بچہ فطرت (یعنی دیْنِ اسلام) پر پیدا ہوتا ہے۔‘‘ کیونکہ اس گمراہی سے مراد وہ گمراہی ہے جو بعد میں اس فطرت پر حاوی ہوجاتی ہے۔جیسا کہ مندرجہ ذیل حدیث شریف سے بھی پتا چلتا ہے۔ چنانچہ اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشادفرمایا: ’’اللہ پاک نے مخلوق کو اپنی معرفت (یعنی فطرتِ اسلام) پر پیدا کیا، پھر شیطان نے انہیں بہکا دیا۔‘‘\n(دلیل الفالحین، باب فی المجاھدة، الجزء الثانی، ۱/ ۳۳۲، تحت الحدیث:۱۱۱)\n¥ہدایت طلب کرنے کی حکمت:\n اللہ پاک سے ہدایت طلب کرنے کی حکمت یہ ہے کہ اس بات کا اِظہار ہو کہ بندہ اللہ پاک کا محتاج ہے اور اس بات کو تسلیم کرتے ہوئے اس کا اعلان کرے کیونکہ اگر اللہ پاک بندے کو بغیر طلب کئے ہدایت عطا فرمادے تو بسا اوقات بندہ کہہ دیتا ہے: ’’یہ ہدایت تو مجھے میرے پاس موجود علم کی بدولت ملی ہے۔‘‘ اور پھر وہ اسی وجہ سے گمراہ ہوجاتا ہے۔ لہٰذا جب اُس نے اللہ پاک سے ہدایت کا سوال کرلیا تو گویا اس نے اپنی عَبُودِیَّت یعنی اللہ پاک کا بندہ ہونےاور اللہ پاک کی رَبُوبِیَّت یعنی اس کے ربّ ہونے کا اعتراف کرلیا۔ یہ وہ عزت والا مقام ہے جسے وہی لوگ سمجھ سکتے ہیں جن کو توفیق ملتی ہے۔\n(دلیل الفالحین، باب فی المجاھدة، الجزء الثانی، ۱/ ۳۳۳، تحت الحدیث:۱۱۱)\n¥دنیاوی نعمتیں بھی ربِّ کریم سے مانگو :\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ مذکورہ حدیث پاک کے جز ’’مجھ سے کھانا مانگو، میں تمہیں کھلاؤں گا، مجھ سے لباس مانگو میں تمہیں لباس دوں گا‘‘ کی شرح میں فرماتے ہیں: یعنی تم روحانی و جسمانی غذاؤں میں میرے محتاج ہو اسی طرح قلب قالب،روح کے لباس میں میرے حاجت مند ہو، غذا کا ہر حیوان حاجت مند ہے اور لباس کا صرف انسان۔خیال رہے کہ تمام انبیاء،اولیاء اور بادشاہ رب تعالیٰ کے حاجت مند ہیں،رب تعالیٰ فرماتا ہے: اللّٰهُ الْغَنِیُّ وَ اَنْتُمُ الْفُقَرَآءُۚ (پ۲۶، محمد:۳۸، ترجمہ کنز الایمان:اللہ بےنیاز ہے اور تم سب محتاج)۔ مگر اس کے محبوب بندے مخلوق کے حاجت روا ہیں باذن پروردگار،ربّ تعالیٰ فرماتا ہے: اَغْنٰىهُمُ اللّٰهُ وَ رَسُوْلُهٗ مِنْ فَضْلِهٖۚ (پ۱۰، التوبة:۷۴، ترجمہ کنز الایمان:اللہ ورسول نے انھیں اپنے فضل سے غنی کر دیا)۔ بادل بھی ربّ کا محتاج اور زمین بھی مگر بادل زمین کا محتاج الیہ ہے کہ ہر وقت زمین کو بادل کی ضرورت ہے۔(مراٰۃ المناجیح، 3/ 354)\n¥ایک اعتراض اور اس کا جواب:\n مذکورہ حدیث شریف میں اللہ پاک نے اوّلاً ایک اُخْرَوی نعمت یعنی ہدایت کا ذکر فرمایا، اس کے بعد دو اہم ترین دُنیوی نعمتوں یعنی کھانے اور لباس کا ذکر فرمایا، پینے اور رہائش کا ذکر نہ فرمایاجبکہ کھانے کے ساتھ پانی اور لباس کے ساتھ رہائش بھی ضروری ہے ان کا ذکر نہیں فرمایا کیوں؟ سیِّدُنا علامہ علی قاری رحمۃُ اللہ علیہ اس کی وجہ بیان کرتے ہوئے فرماتے ہیں: اللہ پاک نے بھوک کا ذکر کیا اور پیاس کا ذکر چھوڑ دیا کیونکہ عموماً کھانے کے ساتھ پینا بھی ہوتا ہے اس ‏لیے فقط بھوک کا ذکر فرمایا پیاس کا ذکر نہ فرمایا۔ اسی طرح پہننے کا ذکر کیا اور رہائش کا ذکر چھوڑ دیا کیونکہ عموماً لباس کے ساتھ گھر بھی شامل ہوتا ہے کہ لباس سِتر چھپانے کے لئے ہوتا ہے اور گھر بھی اپنے آپ کو چھپانے کے لئے ہوتا ہے اس لئے فقط لباس کا ذکر فرمایا گھر یعنی رہائش کا ذکر نہ فرمایا۔(مرقاة المفاتیح، کتاب الدعوات، باب الاستغفار والتوبة، الفصل الاول، ۵/ ۱۵۵، تحت الحدیث:۲۳۲۶، ماخوذًا)\n¥خطا کا معنیٰ ومفہوم:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ مذکورہ حدیث پاک کے جز ’’تم دن رات گناہ (خطا) کرتے ہو ‘‘ کی شرح میں فرماتے ہیں: خطا کے معنیٰ ہیں غلط راستہ پر چلنا بھول کر ہو یا جان بوجھ کر لہٰذا اس میں خطائیں،بھول چوک،عمدًا گناہ سب داخل ہیں۔حافظ ابن حجر ( رحمۃُ اللہ علیہ ) نے فرمایا کہ یہاں روئےسخن(یعنی خطاب) عام بندوں سے ہے معصومین حضرات جیسے فرشتے،انبیاء اس حکم سے خارج ہیں۔(مراٰۃ المناجیح، 3/ 355)\n¥کیا کوئی ربِّ کریم کو نفع ونقصان پہنچا سکتا ہے؟\n مذکورہ حدیث شریف میں ہے کہ ’’ اے میرے بندو! تم میرے نقصان کو نہیں پہنچ سکتے کہ مجھے نقصان پہنچادو اور نہ میرے نفع تک تمہاری رسائی ہے کہ مجھے نفع دو۔ ‘‘ اللہ پاک کو کوئی نفع ونقصان کیسے پہنچا سکتا ہے؟ یہ توممکن ہی نہیں۔ پھر اس سے کیا مردا ہے؟ چنانچہ علامہ علی قاری رحمۃُ اللہ علیہ فرماتے ہیں:مراد یہ ہے کہ تم میرے نفع و نقصان کے مالک نہیں ہو، لہٰذا اگر تم سب سے جس قدر ممکن ہوسکے میری عبادت کروتو میری سلطنت کو کوئی فائدہ نہیں پہنچاسکتے اور اگر تم سب سے جس قدر ممکن ہوسکے میری نافرمانی کرو تو مجھے کچھ نقصان نہیں پہنچا سکتے۔ بلکہ اگر تم نیکی کروگے تواپنا ہی بھلا کروگے اوراگر بُرائی کرو گے تو اپنے لیے ہی بُرا کروگے۔ (مرقاة المفاتیح، کتاب الدعوات، باب الاستغفار والتوبة، الفصل الاول، ۵/ ۱۵۶، تحت الحدیث:۲۳۲۶، ملخصًا)\n¥عبادت کا نفع اور گناہ کا نقصان کس کے لئے؟\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’ اگر سب لوگ متقی بن جائیں تو اللہ پاک کو کچھ نفع نہیں پہنچا سکتے اور اگر سب نافرمان ہو جائیں تو اسے کچھ نقصان نہیں پہنچا سکتے ‘‘کی شرح میں فرماتے ہیں: تمہاری عبادتوں سے میرا نفع نہیں اور تمہارے گناہوں سے میرا نقصان نہیں بلکہ ان میں نفع نقصان خودتمہارا ہے۔ دنیا کے کسی بڑے پرہیز گار کو لے لو پھر سوچو کہ اگر تمام جہان کا دل اس پرہیزگار کا سا ہوجائے اور ساری دنیا اس نیک و صالح کی طرح نیکیاں ہمیشہ کیا کرے۔ (تو اس میں ربِّ کریم کا کیا فائدہ؟ فائدہ تو ان تمام لوگوں کا ہے جو یہ نیکیاں کریں ۔) اس ترجمے سے یہ جملہ بالکل واضح ہوگیا، اس پر کوئی اعتراض نہ رہا۔لہٰذا کوئی شخص یہ سمجھ کر عبادت نہ کرے کہ میری عبادت سے ربّ تعالیٰ کے خزانے بڑھ جائیں گے بلکہ اس کا احسان مانے کہ اس نے اپنے آستانے پر بلالیا۔ (سب کے نافرمان ہونے سے ربّ کریم کا کوئی نقصان نہیں ۔) اس کا مطلب بھی وہ ہی ہے جو پہلے جملے میں عرض کیا گیا کہ دنیا کے بادشاہوں کا رعایا کے بگڑ جانے سے نقصان ہوتا ہے، آمدنی میں کمی ہو جاتی ہے، خزانہ خالی رہ جاتا ہے۔ مگر ربّ تعالیٰ وہ بےنیاز ہے کہ ساری خلق کی بدکاری سے اس کا کوئی نقصان نہیں ۔ خیال رہے کہ یہ مضمون (یعنی تمام لوگوں کا نافرمان ہوجانا) ایسا ہی ہے جیسے ربّ تعالیٰ (حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم کا قول نقل کرتے ہوئے ارشاد) فرماتا ہے : ’’اگر ربّ تعالیٰ کے اولاد ہوتی تو پہلے میں ہی اُسے پوجتا۔‘‘ نہ ربّ تعالیٰ کے اولاد ممکن ہے، نہ حضور انو ر صلّی اللہ علیہ واٰلہٖ وسلّم کا اسے پوجنا ممکن ۔ایسے ہی تمام بندوں کا گنہگارہوجانا غیر ممکن ہے، فرشتے، انبیاء معصومین (کہ ان سے گناہ ہوہی نہیں سکتا) اور اولیاء محفوظین بِفَضْلِہٖ تَعَالٰی (یعنی اولیائے کرام ربِّ کریم کے فضل وکرم سے محفوظ ہیں کہ) گناہ کرتے ہی نہیں۔ ربّ تعالیٰ فرماتا ہے: اِنَّ عِبَادِیْ لَیْسَ لَكَ عَلَیْهِمْ سُلْطٰنٌ (پ۱۴، الحجر:۴۲، ترجمہ کنز الایمان: بےشک میرے بندوں پر تیرا کچھ قابو نہیں)۔غرضیکہ اس جملے سے عصمت انبیاء کے خلاف دلیل نہیں پکڑی جاسکتی (یعنی یہ نہیں کہا جا سکتا کہ انبیائے کرام بھی گناہ کرسکتےہیں)۔ (مراٰۃ المناجیح، 3/ 355)\n¥کیا ربِّ کریم کے خزانوں میں کمی ممکن ہے؟\n حدیث پاک میں ہے ’’ اے میرے بندو! اگر تمہارے اگلے پچھلے انسان اور جن ایک میدان میں کھڑے ہوکر مجھ سے سوال کریں اور میں ہر انسان کا سوال پورا کردوں تو بھی میرے خزانوں میں کچھ کمی نہ ہوگی مگر اتنا ہی جتنا سوئی کو سمندر میں ڈال کر نکالا جائے (یعنی کچھ بھی کم نہ ہو گا)‘‘ اس سے کیا مراد ہے؟ کیا اللہ پاک کے خزانے میں کمی ہو سکتی ہے؟ چنانچہ حضرت سیِّدُنا علامہ محمد بن علان شافعی رحمۃُ اللہ علیہ اس کی شرح میں فرماتے ہیں: دریا وسمندر میں جب سوئی داخل کر کے نکالی جائے تو بظاہر دیکھنے میں اس میں کوئی کمی نہیں ہوتی، اسی طرح اللہ پاک کے خزانے میں سے ساری دنیا کو دینے سے بھی کوئی کمی واقع نہیں ہوتی کیوں کہ یہ اس کی رحمت اور کرم ہے اور یہ دونوں قدیم صفات ہیں اور ان کی کوئی حد نہیں اور جو غیر متناہی ہوتا ہے اس میں کمی ہونا محال ہے برخلاف اُس شے کے جو متناہی ہو ، کیونکہ اس میں کمی واقع ہوسکتی ہے جیسے سمندرکہ یہ زمین کی چیزوں میں سے سب سے بڑی شے ہے۔ بسا اوقات متناہی شے کا کثیر حصہ لے لینے سے بھی اس میں کمی واقع نہیں ہوتی جیسے آگ اور علم۔ ان کو لینے سے کمی نہیں آتی بلکہ علم تو دینے سے اور بڑھتا ہے، لہٰذا یہ واضح ہوگیا کہ سوئی کی مثال کیوں دی گئی اس کا مطلب یہ نہیں کہ حقیقت میں کمی واقع ہوتی ہے بلکہ یہ مخلوق کو سمجھانے کے لئے بطورِ مثال کہا گیا ہے تاکہ یہ بات سمجھ میں آجائے کہ اس قدر دینے سے بھی اللہ پاک کے خزانے میں اتنی سی بھی کمی نہیں آتی۔\n(دلیل الفالحین، باب فی المجاھدة، الجزء الثانی، ۱/ ۳۳۶، تحت الحدیث:۱۱۱، ملخصًا)\n¥خزانَۂ الٰہی میں کمی کا سوال ہی پیدا نہیں ہوتا:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’ سوئی کی تری جب دریا میں ڈبوئی جائے‘‘کی شرح کرتے ہوئے فرماتے ہیں: اس کا یہ مطلب ہرگز نہیں کہ میری یہ عطاء میرے خزانوں میں سوئی کی تری کی بقدر کم کردیں گے وہاں کمی کا سوال ہی پیدا نہیں ہوتا،سورج ہزار ہا سال سے دنیا کو روشنی دے رہا ہے مگر اس کی روشنی میں مطلقًا کمی نہ ہوئی،جب ربّ تعالیٰ کی تجلیوں کا یہ حال ہے تو اس کے خزانو ں کا کیا حال ہوگا اور یہ نسبت بھی فقط سمجھانے کے لیے ہے۔(مراٰۃ المناجیح، 3/ 356)\n¥عدل فضل کے خلاف نہیں:\n حدیث پاک کے جز ’’میں تمہیں اعمال کا پورا پورا بدلہ دوں گا‘‘ کی شرح کرتے ہوئے مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں: اس طرح کہ نیک کار کی جزاء میں کمی نہ کروں گا اور بدکار کی سزا میں زیادتی نہ کروں گا۔ اس کا مطلب یہ نہیں کہ نیک کار کو زیادہ نہ دوں اور گنہگار کو معاف نہ کروں۔یہاں عدل کا ذکر ہے عدل، فضل کے خلاف نہیں۔(مراٰۃ المناجیح، 3/ 356)\n¥خیر اور شر سے مراد:\n حدیث شریف کے آخر میں ہے’’جوبھلائی پائے وہ اللہ پاک کا شکر ادا کرےاور جو اس کے علاوہ پائے تو وہ اپنے آپ ہی کو ملامت کرے‘‘ علامہ ابن علان شافعی رحمۃُ اللہ علیہ اس کی شرح میں فرماتے ہیں: جو خیر کو پائے یعنی ثواب اور نعمتیں یا خوش باش حیاتِ طیبہ تو اُسے چاہئے کہ اللہ پاک کی حمد بجالائے اِس بات پر کہ ربِّ کریم نے اسے نیکیاں کرنے کی توفیق بخشی جن پر یہ ثواب مرتب ہوا اور یہ اس کا فضل اور رحمت ہے اور جو اس کے علاوہ کوئی چیز پائے یعنی شر، اللہ پاک نے اس لفظ کو ذکر نہیں فرمایا، ہمیں یہ بات سکھانے کے لئے کہ ادب کا تقاضا یہ ہے بُرے الفاظ زبان سے نہ نکالے جائیں، اسی طرح جو الفاظ اس کے مشابہ ہوں جنہیں بُرا سمجھا جاتا ہو یا بولنے سے حیا کی جاتی ہو انہیں بھی زبان سے نہ نکالا جائے۔ نیز اس بات کی طرف بھی اشارہ ہے کہ جس لفظ کو اللہ پاک بولنے سے اجتناب فرمارہا ہے اس میں پڑنا اللہ پاک کو کتنا ناپسند ہوگا۔ نیز اس طرف بھی اشارہ ہے کہ اللہ پاک حَیّ یعنی زندہ ہے، کریم یعنی کرم فرمانے والا ہے، وہ پردہ پوشی کو پسند فرماتا اور گناہوں کو بخشتا ہے، وہ کسی کی گرفت کرنے میں جلدی نہیں فرماتا اور نہ ہی کسی کا پردہ فاش فرماتا ہے۔پس ارشاد ہوا ’’جو بھلائی کے علاوہ کچھ اور پائے تو وہ اپنے آپ ہی کو ملامت کرے‘‘ کیوں کہ اس نے رضائے الٰہی پر اپنی خواہشات اور لذات کو توجیح دی توعدل کے تقاضے کے مطابق وہ اسی چیز کا مستحق ہےکہ اللہ پاک کے فضل وکرم سے محروم رہے۔ (دلیل الفالحین، باب فی المجاھدة، الجزء الثانی، ۱/ ۳۳۷، تحت الحدیث:۱۱۱، ملتقطًا)\n¥نیکیاں توفیق الٰہی اور گناہ شامت نفس سے ہے:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ مذکورہ جز کی شرح میں فرماتے ہیں: خلاصہ یہ ہے کہ بندہ نیکیوں کو ربّ تعالیٰ کی توفیق سے سمجھے اور گناہوں کو اپنی شامت نفس سے جانے بلکہ ہرنقص کو اپنی طرف منسوب کرے اور کمال کو ربّ تعالیٰ کی طرف،(حضرت سیِّدُنا)ابراہیم علیہ السّلام نے فرمایاتھا: وَ اِذَا مَرِضْتُ فَهُوَ یَشْفِیْنِﭪ(۸۰) (پ۱۹، الشعرآء:۸۰، ترجمہ کنز الایمان: اور جب میں بیمار ہوں تو وہی مجھے شِفا دیتا ہے)۔ ورنہ ہر خیر وشر کا خالق ومالک ربّ تعالیٰ ہی ہے۔ (مراٰۃ المناجیح، 3/ 356)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6890, "bookId": 13, "volNo": "1", "hadithNo": 25, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "صدقے کی آسان صورتیں", "arabic": "عَنْ اَبِيْ ذَرٍّ رَضيَ اللهُ عَنْهُ اَيْضًا اَنَّ نَاسًا مِّنْ اَصْحَابِ رَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالُوْا لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَا رَسُوْلَ اللهِ! ذَهَبَ اَهْلُ الدُّثُـوْرِ بِالْاُجُوْرِ يُصَلُّوْنَ كَمَا نُصَلِّیْ وَيَصُوْمُوْنَ كَمَا نَصُوْمُ وَيَتَصَدَّقُوْنَ بفُضُوْلِ اَمْوَالِهِمْ. قَالَ: ’’ اَوَ لَيْسَ قَدْ جَعَلَ اللهُ لَكُمْ مَا تَصَّدَّقُوْنَ؟ اِنَّ بِكُلِّ تَسْبِيْحَةٍ صَدَقَةً وَّكُلِّ تَكْبِيْرَةٍ صَدَقَةً وَّكُلِّ تَحْمِيْدَةٍ صَدَقَةً وَّكُلِّ تَهْلِيْلَةٍ صَدَقَةً وَّاَمْرٌ بِالْمَعْرُوْفِ صَدَقَةٌ وَّنَهْيٌ عَنْ مُّنْكَرٍ صَدَقَةٌ وَّفِيْ بُضْعِ اَحَدِكُمْ صَدَقَةٌ.‘‘ قَالُوا: يَا رَسُوْلَ اللهِ! اَ يَاْتِيْ اَحَدُنَا شَهْوَتَهٗ وَيَكُوْنُ لَهٗ فِيْهَا اَجْرٌ؟ قَالَ: ’’ اَرَاَيْتُمْ لَوْ وَضَعَهَا فِيْ حَرَامٍ اَكَانَ عَلَيْهِ وِزْرٌ؟ فَكَذٰلِكَ اِذَا وَضَعَهَا فِي الْحَلالِ كَانَ لَهٗ اَجْرٌ.‘‘ (رَوَاہُ مُسْلِم)", "urdu": "حضرت سیِّدُنا ابوذر غفاری رضی اللہ عنہ سے ہی روایت ہے کہ بعض صحابَۂ کرام علیہمُ الرّضوان نے بارگاہِ رسالت میں عرض کی: یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! مال دار لوگ اجر و ثواب میں بڑھ گئے، وہ ہماری طرح نماز پڑھتے ہیں، ہماری طرح روزے رکھتے ہیں اور اپنے زائد مال سے صدقہ دیتے ہیں (جبکہ ہمارے پاس ضرورت سے زائد مال نہیں ہے جس سے ہم صدقہ کریں)۔ اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’کیا اللہ پاک نے تمہارے لئے وہ اعمال نہیں بنائے جن کے ذریعے تم صدقہ کرو؟ بے شک ہر تسبیح (سُبْحٰنَ اللہ کہنا) صدقہ ہے، ہر تکبیر (اللہ اَکْبَر کہنا) صدقہ ہے، ہر تحمید (اَلْحَمْدُلِلّٰہ کہنا) صدقہ ہے، ہر تہلیل (لَااِلٰہَ اِلَّااللہ کہنا) صدقہ ہے، نیکی کا حکم دینا صدقہ ہے، بُرائی سے منع کرنا صدقہ ہے اور تمہاری شرم گاہ میں بھی صدقہ ہے۔‘‘ صحابَۂ کرام علیہمُ الرّضوان نے عرض کی: یارسول اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! ہم میں سے کوئی شخص اپنی خواہش پوری کرے تو کیا اس میں بھی اس کے لئے اجر ہے؟ ارشاد فرمایا: ’’مجھے بتاؤ کہ اگر وہ حرام جگہ اپنی خواہش پوری کرتا تو اس پر گناہ نہ ملتا؟ اسی طرح جب وہ حلال جگہ خواہش پوری کرے گا تو اس کے لئے ثواب ہوگا۔‘‘( مسلم، كتاب الزكاة، باب بيان ان اسم الصدقة يقع على كل نوع من المعروف، ص۳۹۰، حدیث:۲۳۲۹)", "roman": "Hazrat Sayyiduna Abu Zar Ghifari Radiyallahu Anhu se hi riwayat hai ke ba'az Sahaba-e-Kiram Alaihimur Ridwan ne bargah-e-Risalat mein arz ki: Ya Rasoolullah Sallallahu Alaihi wa Sallam! Maal daar log ajr-o-sawab mein barh gaye, woh hamari tarah Namaz parhte hain, hamari tarah Roza rakhte hain aur apne zaid Maal se Sadaqah dete hain (jabke hamare paas zaroorat se zaid Maal nahi hai jis se hum Sadaqah karein). Allah Paak ke aakhri Nabi Sallallahu Alaihi wa Sallam ne irshad farmaya: 'Kya Allah Paak ne tumhare liye woh a'maal nahi banaye jin ke zariye tum Sadaqah karo? Beshak har Tasbeeh (SubhanAllah kehna) Sadaqah hai, har Takbeer (Allah Akbar kehna) Sadaqah hai, har Tahmeed (Alhamdulillah kehna) Sadaqah hai, har Tahleel (La ilaha illallah kehna) Sadaqah hai, neki ka Hukm dena Sadaqah hai, burai se mana karna Sadaqah hai aur tumhari Sharm-gah mein bhi Sadaqah hai.' Sahaba-e-Kiram Alaihimur Ridwan ne arz ki: Ya Rasoolullah Sallallahu Alaihi wa Sallam! Hum mein se koi Shakhs apni khwahish poori kare to kya is mein bhi us ke liye ajr hai? Irshad farmaya: 'Mujhe batao ke agar woh Haram jagah apni khwahish poori karta to is par gunah na milta? Isi tarah jab woh Halal jagah khwahish poori karega to is ke liye sawab hoga.' (Muslim, Kitaab-uz-Zakat, Baab bayan an ism-us-Sadaqah yaqa'u ala kulli nau'in min-al-Ma'Roof, safa 390, Hadees: 2329)", "explanation": "¥مال دار لوگ اجر و ثواب میں بڑھ گئے:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کےجز ’’مال دار لوگ اجر وثواب میں بڑھ گئے‘‘ یعنی ہمارے مقابل درجات میں بڑھ گئے اور جنت کی اعلیٰ نعمتوں کے مستحق ہوگئے، اس میں نہ تو ربِّ (کریم) کی شکایت ہے اور نہ مالداروں پر حسد بلکہ ان پر رَشک ہے، دینی چیزوں میں رشک جائز ہے یعنی دوسروں کی سی نعمت اپنے لیے بھی چاہنا، حسد حرام ہے یعنی دوسروں کی نعمت کے زوال کی خواہش۔ (مراٰۃ المناجیح، 2/ 119)\n¥ذکر واذکار کو صدقے کا نام دینے کی وجہ:\nحضرت سیِّدُنا علامہ ابو زکریا یحییٰ بن شرف نووی رحمۃُ اللہ علیہ فرماتے ہیں: ان تمام امور (اذکار) کو صدقے کا نام دیا گیا ہے۔ اس میں ایک صورت تو یہ ہے کہ اِن اُمور میں حقیقتاً صدقہ کرنے کا ثواب ہے اور بطورِ مقابلہ انہیں صدقے کانام دیا گیا ہے۔ ایک احتمال یہ ہے کہ یہ امور نفس پر صدقہ ہیں۔(شرح مسلم للنووی، کتاب الزکٰوة، باب بیان ان اسم الصدقة یقع...الخ، الجزء السابع، ۴/ ۹۱) \n¥اذکار کا اجر وثواب:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث شریف میں مذکور اذکار کی شرح میں فرماتے ہیں: اس فرمانِ عالی شان سے معلوم ہوا کہ جو کوئی سُبْحٰنَ اللہ یا اللہ اَکْبَر یا اَلْحَمْدُ لِلّٰہ یا لَا اِلٰہَ اِلَّا اللہکسی طرح بھی کہے صدقہ نفلی کا ثواب پائے گا خواہ ذِکْرُ اللہ کی نیت سے کہے یا کسی حاجت کے لیے بطور وظیفہ یہ الفاظ پڑھے یا عجیب بات سن کر سُبْحٰنَ اللہ وغیرہ کہے یا خوشخبری پا کر اَلْحَمْدُ لِلّٰہ پڑھے۔بہرحال ثواب ملے گا کیونکہ اللہ (پاک) کا نام لینا بہرحال عبادت ہے۔ اگر کوئی شخص ٹھنڈک کے لیے اَعضائے وضو دھوئے تب بھی وضو ہوجائے گا کہ اس سے نمازجائز ہوگی۔اللہ(پاک)کانام زبان کاوضو ہے۔(مراٰۃ المناجیح، 3/98)\nنیکی کی دعوت دینے اور برائی سے منع کرنے کا ثواب:\n حضرت امام ابو زکریا یحییٰ بن شرف نووی رحمۃُ اللہ علیہ مذکورہ حدیث پاک کی شرح میں فرماتے ہیں: نیکی کاحکم دینا اور برائی سے منع کرنا بھی صدقہ ہے۔ اسی طرح سُبْحٰنَ اللہ،اَلْحَمْدُ لِلّٰہِ،اللہ اَکْبَرُاورلَا اِلٰہَ اِلَّا اللہ کہنا بھی صدقہ ہے۔ اَذکارِمذکورہ کے مقابلے میں’’اَمْرٌ بِالْمَعْرُوْف وَنَھْیٌ عَنِ الْمُنْکَرْیعنی نیکی کی دعوت دینے اور بُرائی سےمنع کرنے‘‘ کا ثواب زیادہ ہےکیونکہ یہ فرضِ کفایہ ہے۔ جبکہ تسبیح ،تحمیداور تہلیل کا شمار نوافل میں ہوتا ہے۔ یہ بات بالکل واضح ہے کہ فرض کاثواب نفل سے زیادہ ہے۔ جیسا کہ حدیثِ قدسی ہےکہ ”میرا بندہ کسی چیزکےذریعےبھی میرا اتنا قرب حاصل نہیں کرتا جتنا فرائض کے ذریعے حاصل کرتا ہے۔“ اسی طرح حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ سے مَروی ہےکہ ’’فرض کا ثواب نوافل سے70گنازیادہ ہے۔‘‘ (شرح مسلم للنووی، کتاب الزکٰوة، باب بیان ان اسم الصدقة یقع...الخ، الجزء السابع، ۴/ ۹۲)\n¥نیکی کا حکم دینا صدقہ ہے:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’نیکی کا حکم دینا اور برائی سے منع کرنا صدقہ ہے‘‘ کے تحت فرماتے ہیں: ہر تبلیغ میں خیرات کا ثواب ہے۔ بلکہ اس کا ثواب پہلے ثوابوں سے زیادہ کہ اس میں ذِکْرُ اللہبھی ہے اور لوگوں کو فیض پہنچانا بھی۔قلمی تبلیغ صدقَۂ جاریہ ہے کہ جب تک لوگ اس کی کتاب سے دینی فائدہ اٹھائیں گے، تب تک اسے ثواب ملتا رہے گا۔ یہ ایک کلمہ بہت جامع ہے۔ (مراٰۃ المناجیح،3/98)\n¥فی نفسہٖ قضائے شہوت پر اَجر نہیں:\n حضرت علامہ علی قاری رحمۃُ اللہ علیہ حدیث پاک کے جز ’’تمہاری شرم گاہ میں بھی صدقہ ہے‘‘ کی شرح میں فرماتے ہیں: فی نفسہ قضائے شہوت (یعنی محض شہوت پوری کرنے)پر اَجر نہیں بلکہ اجر اسی وقت ہے جب جائز طریقے سےہو۔ جیساکہ عید کے دن جلدی کھانا اورسحری کا کھانا۔ اسی طرح دیگر خواہشات جو اُمورِشرعیَّہ کے موافق ہوں۔اسی ‏لئے کہا گیا ہے کہ جب خواہش ہدایت کے موافق ہو جائے تو اس طرح ہے جیسے مکھن شہد کے ساتھ مل جائے اور اس کی طرف اس فرمان باری تعالیٰ سے بھی اشارہ ملتا ہے: وَ مَنْ اَضَلُّ مِمَّنِ اتَّبَعَ هَوٰىهُ بِغَیْرِ هُدًى مِّنَ اللّٰهِؕ (پ۲۰، القصص:۵۰، ترجمہ کنز الایمان: اور اس سے بڑھ کر گمراہ کون جواپنی خواہش کی پیروی کرے اللہ کی ہدایت سے جدا)۔(مرقاة المفاتیح، کتاب الزکاة، باب فضل الصدقة، ۴/ ۴۰۰، تحت الحدیث:۱۸۹۸)\nمباح عمل اچھی نیت سے عبادت بن جاتا ہے:\nامام نووی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’تمہاری شرم گاہ میں بھی صدقہ ہے‘‘کی شرح میں فرماتے ہیں: یعنی اپنی زوجہ سےصحبت کرنا بھی صدقہ ہے۔اس میں اس بات پر دلیل ہے کہ مباح اعمال بھی اچھی نیت سے عبادت بن جاتی ہیں۔ لہٰذا حَقِّ زوجیت کی ادا ئیگی،اچھےسلو ک،نیک اولادکی طلب،خوداپنی یا زوجہ کی پاک دامنی ،حرام اشیاء کی طرف نظر اوران میں غور وفکر سے بچنےیا اور کسی نیک کام کی نیت سےاپنی زوجہ سے صحبت کرنا بھی ثواب ہے۔\n(شرح مسلم للنووی، کتاب الزکٰوة، باب بیان ان اسم الصدقة یقع...الخ، الجزء السابع، ۴/ ۹۲)\n¥عبادات پر مشتمل عمل:\nمفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’تمہاری شرم گاہ میں بھی صدقہ ہے‘‘کی شرح میں فرماتے ہیں: یہاں مراد صحبت حلال ہے۔ یہاں ’’ فِی‘‘ ارشاد فرما کر اس جانب اشارہ فرمایا گیا کہ صحبت بذاتِ خود ثواب نہیں بلکہ چونکہ اس کے ضمن میں زوجین کی عفت (پاک دامنی)، حَقِّ زوجیت کی ادا، نیک اولاد کی طلب ہے اور یہ ساری چیزیں عبادت ہیں اس لیے صحبت عبادات پر شامل ہے۔ اس سیِّدُ الفصحاء صلّی اللہ علیہ واٰلہٖ وسلّم کی فصاحت دیکھو کہ پہلی چیزوں میں ’’ب‘‘ ارشاد ہوا تھا اور یہاں ’’فِی‘‘ تاکہ پتہ لگے کہ وہ چیزیں بذات خود عبادت تھیں اور یہ صحبت عبادات پر مشتمل ہے۔(لمعات)، صاحب مرقات نے یہاں فرمایا ظاہر حدیث سے معلوم ہوتا ہے کہ حلال صحبت مطلقاً صدقہ ہے خواہ ان چیزوں کی نیت سے ہو یا نہ ہو۔ (مزید فرماتے ہیں:) بذات خود صحبت ثواب نہیں بلکہ شہوت کو حلال میں خرچ کرنا ثواب ہے۔ جیسے عید کے دن یا رمضان کی سحریوں میں کھانا پینا بذات خود ثواب نہیں بلکہ ان وقتوں میں کھانا عبادت ہے۔ صوفیائے کرام ( رحمۃُ اللہ علیہم ) فرماتے ہیں کہ جب ’’ہَوا ہُدٰی‘‘ سے مل جائےتو زہد بن جاتی ہے اسی جانب قرآن کریم اشارہ فرما رہا ہے:’’ وَ مَنْ اَضَلُّ مِمَّنِ اتَّبَعَ هَوٰىهُ بِغَیْرِ هُدًى مِّنَ اللّٰهِؕ (پ۲۰، القصص:۵۰، ترجمہ کنز الایمان: اور اس سے بڑھ کر گمراہ کون جو اپنی خواہش کی پیروی کرے اللہ کی ہدایت سے جدا) ۔ سُبْحٰنَ اللہ! ’’ہَوا ہُدٰی‘‘ سے مل کر ایسی ہوتی ہے جیسے مکھن شہد سے مل کر۔ (از مرقات) لہٰذا حدیث پر اعتراض نہیں کہ بغیر نیت ثواب کیسا کہ نیت کی شرط عبادت محضہ میں ہے۔(مراٰۃ المناجیح،3/98)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6891, "bookId": 13, "volNo": "1", "hadithNo": 26, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "صدقے کی مختلف صورتیں", "arabic": "عَنْ اَبِيْ هُرَيْرَةَ رَضيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : ’’كُلُّ سَلَامٰى مِنَ النَّاسِ عَلَيْهِ صَدَقَةٌ كُلَّ يَوْمٍ تَطْلُعُ فِيْهِ الشَّمْسُ یَعْدِلُ بَيْنَ اثْنَيْنِ صَدَقَةٌ وَّیُعِيْنُ الرَّجُلَ فِيْ دَابَّتِهٖ فَیَحْمِلُهٗ عَلَيْهَا اَوْ یَرْفَعُ لَهٗ عَلَيْهَا مَتَاعَهٗ صَدَقَةٌ وَّالْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ وَّبِكُلِّ خُطْوَةٍ یَّمْشِيْهَا اِلَى الصَّلَاةِ صَدَقَةٌ وَّیُمِيْطُ الْاَذٰى عَنِ الطَّرِيْقِ صَدَقَةٌ.‘‘(رَوَاهُ الْبُخَارِیُّ وَمُسْلِمٌ)", "urdu": "حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسُوْلُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ہر وہ دن جس میں سورج طلوع ہو(یعنی روزانہ) انسان کے ہر جوڑ پر صدقہ ہے،دو آدمیوں کے درمیان انصاف کرنا صدقہ ہے، آدمی کو اس کی سواری پر سوار کرانے یا اس کا سامان رکھوانے پر مدد کرنا صدقہ ہے، اچھی گفتگو صدقہ ہے، نماز کی طرف اٹھنےوالا ہر قدم صدقہ ہے اور راستے سے تکلیف دہ چیز دور کرنا صدقہ ہے۔‘‘ \n (مسلم، كتاب الزکاة، باب بیان ان اسم الصدقة یقع...الخ، ص۳۹۱، حدیث:۲۳۳۵۔ بخاری، کتاب الجھاد، باب فضل من حمل متاع صاحبہ فی السفر، ۲/ ۲۷۹، حدیث:۲۸۹۱، بتغیر قلیل)", "roman": "Hazrat Sayyiduna Abu Hurairah Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alaihi wa Sallam ne irshad farmaya: 'Har woh din jis mein sooraj tulu ho (yani rozana) insaan ke har jor par Sadaqah hai, do aadmiyon ke darmiyan insaaf karna Sadaqah hai, aadmi ko us ki sawari par sawar karane ya us ka Maal rakhwane par madad karna Sadaqah hai, achi guftagu Sadaqah hai, Namaz ki taraf uthne wala har qadam Sadaqah hai aur raaste se takleef deh cheez door karna Sadaqah hai.' (Muslim, Kitaab-uz-Zakat, Baab bayan an ism-us-Sadaqah yaqa'u... al-kh, safa 391, Hadees: 2335. Bukhari, Kitaab-ul-Jihad, Baab fazl man hamala mata'a sahibihi fis-safar, 2/279, Hadees: 2891, bataghayyur-e-qaleel)", "explanation": "¥کیا ہر انسان پرصدقہ کرنا واجب ہے؟\n حضرت سیِّدُنا علامہ ابو زکریا یحییٰ بن شرف نووی رحمۃُ اللہ علیہ بیان کرتے ہیں کہ علمائے کرام رحمۃُ اللہ علیہم فرماتے ہیں: انسان پر صدقہ کرنا واجب یا لازم نہیں بلکہ مستحب ہے اور یہ فرمانِ عالی ترغیب کے لئے ہے۔ \n(شرح مسلم للنووی، کتاب الزکٰوة، باب بیان ان اسم الصدقة یقع...الخ، الجزء السابع، ۴/ ۹۵)\n¥انسان کے بدن میں 360¥ جوڑ ہیں:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’ہر وہ دن جس میں سورج طلوع ہو(یعنی روزانہ) انسان کے ہر جوڑ پر صدقہ ہے ‘‘ کی شرح میں فرماتے ہیں: انسان کے بدن میں 360 جوڑ ہیں۔ اگرچہ ہمارا ہر رونگٹا اللہ پاک کی نعمت ہے لیکن ہر جوڑ اس کی بے شمار نعمتوں کا مظہر ہے اس لیے خصوصیت سے اس کا شکریہ ضروری ہوا۔صدقہ سے مراد نیک عمل ہے۔ مطلب یہ ہے کہ ہر شخص پر اخلاقًا دیانۃً لازم ہے کہ روزانہ ہر جوڑ کے عوض (بدلے) کم از کم ایک نفل نیکی کیا کرے اس حساب سے روزانہ 360 نیکیاں کرنی چاہئیں تاکہ ا س دن جوڑوں کا شکریہ ادا ہو، سورج چمکنے کا ذکر اس لیے فرمایا کہ سورج تو ہرشخص پر چمکتا ہے تو شکریہ بھی ہرشخص پر ہے۔ (مراٰۃ المناجیح،3/97، ملخصاً)¥\nانسان کی قید کیوں لگائی؟\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں: انسان کی اس لیے قید لگائی تاکہ اس سے فرشتے اور جنات نکل جائیں کہ نہ ان کے جسموں میں اتنے جوڑ ہیں نہ ان کے یہ احکام۔ ہمارے یہ جوڑ، انگلی کے پوروں سے لے کر پاؤں کے ناخنوں تک ہیں اگر ان میں سے ایک جوڑ خراب ہوجائے تو زندگی دشوار ہوجائے۔ قدرت نے ہڈی کو ہڈی میں اس طرح پیوست کیا ہے کہ کواڑ کی چول کی طرح ہڈی گھومتی، ہلتی ہے اس کے باوجود نہ گھستی ہے نہ خراب ہوتی ہے۔(مراٰۃ المناجیح،3/97)¥\nہر ہر نعمت کا شکر ادا کرو:\n علامہ بدر الدین عینی رحمۃُ اللہ علیہ حدیث پاک کی شرح میں فرماتے ہیں: حدیث کا معنیٰ یہ ہے کہ انسان کے جوڑ اس کے وجود کی اصل ہیں اور ان سے منافع حاصل ہوتے ہیں کیونکہ انہیں کے ذریعے انسان حرکت کرتا ہے ۔ یہ انسان پر اللہ پاک کی عظیم نعمتیں ہیں، لہٰذا جسے نعمت ملے اس پر لازم ہے کہ ہر ہر نعمت کا شکرادا کرےاور صدقہ دے۔ اللہ پاک نے اپنے بندوں پر لطف و کرم فرمایا کہ لوگوں کے درمیان عدل کرنے کو صدقہ قرار دیا۔ \n(عمدة القاری، کتاب الصلح، باب فضل الاصلاح بین الناس والعدل بینھم، ۹/ ۶۰۲، تحت الحدیث:۲۷۰۷)\n¥اللہ پاک کی نصیحت:\n لوگوں کے درمیان عدل وانصاف کرنے کا حکم قرآن مجید میں بھی دیا گیا ہے۔ چنانچہ ارشاد باری تعالیٰ ہے:\nوَ اِذَا حَكَمْتُمْ بَیْنَ النَّاسِ اَنْ تَحْكُمُوْا بِالْعَدْلِؕ-اِنَّ اللّٰهَ نِعِمَّا یَعِظُكُمْ بِهٖؕ (پ ۵، النسآء:۵۸)\nترجمہ کنزالایمان: اور یہ کہ جب تم لوگوں میں فیصلہ کرو تو انصاف کے ساتھ فیصلہ کرو بےشک اللہ تمہیں کیا ہی خوب نصیحت فرماتا ہے۔\n¥عدل وانصاف کرنے کا انعام:\n لوگوں کے درمیان عدل وانصاف کرنے سے تقویٰ کی دولت نصیب ہوتی ہے۔ چنانچہ اللہ پاک قرآن مجید میں ارشاد فرماتا ہے:\nیٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا كُوْنُوْا قَوّٰمِیْنَ لِلّٰهِ شُهَدَآءَ بِالْقِسْطِ٘-وَ لَا یَجْرِمَنَّكُمْ شَنَاٰنُ قَوْمٍ عَلٰۤى اَلَّا تَعْدِلُوْاؕ-اِعْدِلُوْا- هُوَ اَقْرَبُ لِلتَّقْوٰى٘ (پ ۶، المآئدة:۸)\nترجمہ کنزالایمان: اے ایمان والو اللہ کے حکم پر خوب قائم ہو جاؤ انصاف کے ساتھ گواہی دیتے اور تم کو کسی قوم کی عداوت (دشمنی) اس پر نہ ابھارے کہ انصاف نہ کرو انصاف کرو وہ پرہیزگاری سے زیادہ قریب ہے۔\n¥ہر ہر کام رضائے الٰہی کے لئے ہو:\n مشہور شارح حدیث، حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’دو آدمیوں کے درمیان انصاف کرنا صدقہ ہے، آدمی کو اس کی سواری پر سوار کرانے یا اس کا سامان رکھوانے پر مدد کرنا صدقہ ہے ‘‘ کی شرح میں فرماتے ہیں: تہذیْبِ اَخلاق، تدبیرِ منزل، سیاسَتِ مدنی، لوگوں سے اچھے برتاؤ (کرنا)صدقہ ہیں بشرطیکہ رضائے الٰہی کے ‏لیے ہوں ۔ہر معمولی سے معمولی کام جب ادائے سنت کی نیت سے کیا جائے گا تو وہ بڑا ہوجائے گا، کیونکہ منسوب اگرچہ چھوٹا ہے مگر منسوب الیہ جن کی طرف نسبت ہے (یعنی حضور نبی کریم) صلّی اللہ علیہ واٰلہٖ وسلّم وہ تو بڑے ہیں۔\n(مراٰۃ المناجیح،3/97)\n¥اچھی گفتگو صدقہ ہے:\n حافظ ابن بطّال رحمۃُ اللہ علیہ حدیث پاک کے جز ’’اچھی گفتگو صدقہ ہے‘‘ کی شرح میں فرماتے ہیں: اچھی گفتگو نیکی کے عظیم کاموں میں سے ہے۔ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے اچھی گفتگو کو مالی صدقہ کی مثل قرار دیا ہے۔ کیونکہ جس طرح مالی صدقہ کرنے سے جس پرصدقہ کیا گیا ہو اس کادل خوش ہوتا ہے اسی طرح اچھی گفتگو کرنے سے بھی مومن کا دل خوش ہوتا ہے۔(شرح بخاری لابن بطال، کتاب ، باب ، ۹/ ۲۲۵)\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ ایک حدیث پاک کی شرح میں فرماتے ہیں: صدقہ صرف مال ہی سے نہیں ہوتا بلکہ ہر معمولی نیکی اگر اخلاص سے کی جائے تو اس پر صدقہ کا ثواب ملتا ہے حتّٰی کہ مسلمان بھائی سے میٹھی اور نرم باتیں کرنا بھی صدقہ ہے۔اب کوئی فقیر بھی یہ نہیں کہہ سکتا کہ میں صدقہ پر قادر نہیں۔(مراٰۃ المناجیح،3/95)\n¥باقی رہنے والی اچھی باتیں:\nحضرت سیِّدُنا قاسم بن ولید رحمۃُ اللہ علیہ سے مروی ہے کہ حضرت سیِّدُنا قتادہ بن دعامہ رحمۃُ اللہ علیہ نے اس فرمان باری تعالیٰ: وَ الْبٰقِیٰتُ الصّٰلِحٰتُ (پ۱۵، الکھف:۴۶)ترجمہ کنزالایمان: اور باقی رہنے والی اچھی باتیں۔ کی تفسیر میں فرمایا: ’’ہر وہ نیک عمل جس کے ذریعے رضائے الٰہی کا اراد کیا جائے وہ باقی رہنے والی اچھی باتوں میں سے ہے۔‘‘(در منثور، پ۱۵، الکھف، تحت الایة:۴۶، ۵/ ۳۹۹)\n¥بہترین بندہ کون؟\n مروی ہے کہ کسی نے حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم سے پوچھا کہ بہترین بندہ کون ہے ؟ تو آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اللہ پاک سے ڈرنے والا، صِلَہ رِحمی (یعنی رشتے داروں کے ساتھ اچھا سلوک) کرنے والا، اچھی باتیں بتانے والا اور برائیوں سے روکنے والا۔‘‘(الزھد الکبیر للبیھقی، ص۳۲۷، حدیث:۸۷۷)\n¥نیکی کے لئے اٹھنے والا ہر قدم صدقہ ہے:\n حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’نماز کی طرف اٹھنےوالا ہر قدم صدقہ ہے ‘‘ کی شرح میں فرماتے ہیں: نماز کا ذکر مثالاً ہے ورنہ طواف، بیمار پُرسی، جنازہ میں شرکت، علم دین کی طلب غرضکہ ہر نیکی کے ‏لیے قدم ڈالنا صدقہ ہے۔(مراٰۃ المناجیح،3/97)\n¥ہر ہر قدم پر نیکی:\n حدیث میں ہے کہ ’’جو شخص اچھی طرح طہارت (وضو) کرے پھر مسجد کو جائے تو جو قدم چلتا ہے، ہر قدم کے بدلے اللہ پاک نیکی لکھتا، درجہ بلند کرتا اور گناہ مٹا دیتا ہے۔‘‘\n(مسلم، کتاب المساجد ومواضع الصلاة، باب صلاة الجماعة من سنن الھدی، ص۲۵۷، حدیث:۱۴۸۸)\n حضرت سیِّدُنا عبد اللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں کہ میں نے رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم کو ارشاد فرماتے سنا: ’’جس نے گِن کر طواف کے سات پھیرے کئے اور پھر دو رکعتیں ادا کیں یہ ایک غلام آزاد کرنے کے برابر ہے اور طواف کرتے ہوئے آدمی کے ہر قدم کے بدلے اس کے لئے 10نیکیاں لکھی جاتیں، 10 گناہ مٹا دیئے جاتے اور 10درجات بلند کر دیئے جاتے ہیں۔‘‘ (مسند احمد، ۲/ ۲۰۲، حدیث:۴۴۶۲)\n ایک روایت میں ہے: ’’جو جمعہ کے دن نہائے، جلدی آئے، شروع خطبہ میں شریک ہو اور پیدل آئے، امام سے قریب ہو اور کان لگا کر خطبہ سنے، کوئی لغو کام نہ کرے تو اس کے لئے ہر قدم کے بدلے سال بھر کے عمل اور ایک سال کے دنوں کے روزوں اور راتوں کے قیام کا اجر ہے۔‘‘ (مسند احمد، حدیث اوس بن ابی اوس الثقفی، ۵/ ۴۶۵، حدیث:۱۶۱۷۳)\n حضرت سیِّدُنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ ہمارے گھر مسجد سے دور تھے، ہم نے اپنے گھروں کو فروخت کرنے کا ارادہ کیا تاکہ مسجد کے قریب ہوجائیں تو رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ہمیں منع فرما دیا اور ارشاد فرمایا: ’’تمہارے لئے ہرقدم کے بدلے ایک درجہ ہے۔‘‘(مسلم، کتاب المساجد ومواضع الصلاة ، باب فضل کثرة الخطا الی المساجد، ص۲۶۲، حدیث:۱۵۱۸)\n¥لوگوں کو تکلیف دہ چیز سے بچانا بھی صدقہ ہے:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’راستے سے تکلیف دہ چیز دور کرنا بھی صدقہ ہے‘‘ کی شرح میں فرماتے ہیں: راستہ سے کانٹا، ہڈی، اینٹ، پتھر، گندگی غرض جس سے کسی مسلمان راہ گیر کو تکلیف پہنچنے کا اندیشہ ہو اس کو ہٹا دینا بھی نیکی ہے جس پر صدقہ کا ثواب اور جوڑ کا شکریہ ہے۔ (مراٰۃ المناجیح،3/97)\n¥راستے سے تکلیف دہ چیز دور کرنے کا اجر:\n حضرت سیِّدُنا ابو عبیدہ بن جراح رضی اللہ عنہ سے مروی ہے کہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو کسی مریض کی عیادت کرے، اپنے اہل وعیال پر خرچ کرے یا راستے سے کوئی تکلیف دہ چیز دور کرے تو اسے 10 گنا اجر ملے گا۔‘‘(مصنف ابن ابی شیبة، کتاب الادب، باب فی تنحیة الاذی عن الطریق، ۱۳/ ۴۲۸، حدیث:۲۶۸۷۲)\n حضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’میں نے جنت میں ایک شخص کو ٹہلتے دیکھا جس نے دنیا میں مسلمانوں کے راستے سے اس درخت کو کاٹ دیا تھا جو ان کی تکلیف کا باعث تھا۔‘‘(مسلم، کتاب البر والصلة، باب فضل ازالة الاذی عن الطریق، ص۱۰۸۱، حدیث:۶۶۷۱)\n حضرت سیِّدُنا ابو برزہ رضی اللہ عنہ نے ایک مرتبہ بارگاہِ رسالت میں عرض کی: یارسول اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! مجھے کوئی ایسی بات بتائیے جس سے میں نفع اٹھاؤں۔ تو آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’مسلمانوں کے راستے سے تکلیف دہ چیز ہٹا دو۔‘‘ (مسلم، کتاب البر والصلة، باب فضل ازالة الاذی عن الطریق، ص۱۰۸۲، حدیث:۶۶۷۳) \n حضرت سیِّدُنا ابو درداء رضی اللہ عنہ سے روایت ہے کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو مسلمانوں کے راستے سے کوئی تکلیف دہ چیز دور کرتا ہے تو اللہ پاک اس کے بدلے میں اس شخص کے لئے ایک نیکی لکھتا ہے اور جس کے لئے اللہ پاک ایک نیکی لکھ دے تو اس کے لئے اس نیکی کی وجہ سے جنت واجب فرما دیتا ہے۔‘‘\n(مسند احمد، حدیث ابی الدرداء، ۱۰/ ۴۱۵، حدیث:۲۷۵۴۹)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6892, "bookId": 13, "volNo": "1", "hadithNo": 27, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "نیکی اور گناہ کی پہچان", "arabic": "عَنِ النَّوَّاسِ بْنِ سَمْعَانَ رَضيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيهِ وَسَلَّمَ قَالَ: ’’اَلْبِرُّ حُسْنُ الْخُلُقِ وَالْاِثْمُ مَا حَاكَ فِيْ نَفْسِكَ وَكَرِهْتَ اَنْ يَّطَّلِعَ عَلَيْهِ النَّاسُ.‘‘ (رَوَاهُ مُسْلِم)\nوَعَنْ وَابِصَةَ بْنِ مَعْبَدٍرَضِىَ اللهُ عَنْهُ قَالَ: اَتَيْتُ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: ’’جِئْتَ تَسْاَلُ عَنِ الْبِرِّ؟‘‘ قُلْتُ: نَعَمْ. قَالَ: ’’اِسْتَفْتِ قَلْبَكَ، اَلْبِرُّ مَا اطْمَاَنَّتْ اِلَيْهِ النَّفْسُ وَاطْمَاَنَّ اِلَيْهِ الْقَلْبُ وَالْاِثْمُ مَا حَاكَ فِيْ النَّفْسِ وَتَرَدَّدَ فِيْ الصَّدْرِ وَاِنْ اَفْتَاكَ النَّاسُ وَافْتَوْكَ.‘‘ (حَدِيْثٌ حَسَنٌ، رَوَيْنَاهٗ فِیْ مُسْنَدَیَ الْاِمَامَيْنِ اَحْمَدَ ابْنِ حَنْبَلٍ وَّالدَّارَمِیِّ رَحِمَھُمَا اللّٰہ تعالٰی بِاِسْنَادٍ حَسَنٍ)", "urdu": "حضرت سیِّدُنا نواس بن سمعان رضی اللہ عنہ سے مروی ہے کہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’نیکی حسن اخلاق کا نام ہے اور گناہ وہ ہے جو تیرے دل میں کھٹکے اور تجھے اس پر لوگوں کا مطلع ہونا (اِطلاع پانا) ناپسند ہو۔‘‘ \n( مسلم، كتاب البر والصلة والاداب، باب تفسير البر والاثم، ص۱۰۶۱، حدیث:۶۵۱۷)\n حضرت سیِّدُنا وابصہ بن معبد رضی اللہ عنہ بیان کر تے ہیں کہ میں بارگاہِ رسالت میں حاضر ہوا تو آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا:’’تم نیکی کے بارے میں پوچھنے آئے ہو؟ میں نے عرض کی: جی ہاں۔ ارشاد فرمایا: اپنے دل سے پوچھو، نیکی وہ ہے جس پر تمہارا نفس مطمئن ہو اور اطمینان قلبی حاصل ہو اور گناہ وہ ہے جو تمہارے نفس میں کھٹکے اور دل میں شک پیدا کرے ، اگرچہ لوگ تمہیں کچھ بھی فتویٰ دیں، اگرچہ لوگ تمہیں فتویٰ دیں ۔‘‘ (مسند احمد، مسند الشامیین، حدیث وابصة بن معبد اسدی، ۶/ ۲۹۲، حدیث:۱۸۹۲۳، بتغیر قلیل۔ دارمی، کتاب البیوع، باب دع مایریبک الی ما لا یریبک، ۲/ ۳۲۰، حدیث:۲۵۳۳)\n (یہ حدیث حسن ہے۔ اسے حضرت سیِّدُنا امام حمد بن محمد بن حنبل اور حضرت سیِّدُنا حافظ ابو محمد عبد اللہ بن عبدالرحمٰن بن فضل بن بہرام دارمی رحمۃ اللہ علیہما نے اپنی اپنی مسند (مسند احمد اور سنن دارمی) میں حسن سند کے ساتھ روایت کیا ہے۔)", "roman": "Hazrat Sayyiduna Nawwas bin Sam'an Radiyallahu Anhu se Marwi hai ke Huzoor Nabi-e-Kareem Sallallahu Alaihi wa Sallam ne irshad farmaya: 'Neki Hasan akhlaq ka naam hai aur gunah woh hai jo tere dil mein khatke aur tujhe is par logon ka muttali' hona (ittila' paana) na-pasand ho.' (Muslim, Kitaab-ul-Birri was-Silati wal-Adab, Baab tafseer-ul-birri wal-ism, safa 1061, Hadees: 6517). Hazrat Sayyiduna Wabsa bin Ma'bad Radiyallahu Anhu bayan karte hain ke main bargah-e-Risalat mein hazir hua to Aap Sallallahu Alaihi wa Sallam ne irshad farmaya: 'Tum neki ke baare mein poochne aaye ho?' Main ne arz ki: Ji haan. Irshad farmaya: 'Apne dil se poocho, neki woh hai jis par tumhara nafs mutma'in ho aur itminan-e-qalbi hasil ho aur gunah woh hai jo tumhare nafs mein khatke aur dil mein shak paida kare, agarche log tumhein kuch bhi Fatwa dein, agarche log tumhein Fatwa dein.' (Musnad-e-Ahmed, Musnad-ush-Shaamiyeen, Hadees Wabsa bin Ma'bad Asadi, 6/292, Hadees: 18923, bataghayyur-e-qaleel. Sunan Darimi, Kitaab-ul-Buyu', Baab da' ma yaribuka ila ma la yaribuka, 2/320, Hadees: 2533). (Yeh Hadees Hasan hai. Ise Hazrat Sayyiduna Imam Muhammad bin Muhammad bin Hanbal aur Hazrat Sayyiduna Hafiz Abu Muhammad Abdullah bin Abdur-Rahman bin Fazl bin Bahram Darimi Rahmatullah Alayhima ne apni apni Musnad (Musnad-e-Ahmed aur Sunan Darimi) mein Hasan Sanad ke saath riwayat kiya hai.)", "explanation": "¥نیکی اور گناہ کیا ہے؟\nعلامہ محمد بن علان شافعی رحمۃُ اللہ علیہ حدیث پاک کی شرح میں فرماتے ہیں: نیکیوں کا بڑا حصہ حسْنِ اخلاق پر مشتمل ہے۔ اچھے اخلاق سے مراد خندہ پیشانی سے ملاقات، ایذا نہ دینا، سخاوت، دوسروں کے لئے وہی پسند کرنا جو اپنے لئے پسند ہو۔ بعض نے فرمایا: احکام ومعاملات میں عدل وانصاف، بحث وتکرار میں نرمی، خوشحالی میں احسان وسخاوت اور تنگدستی میں ایثار جیسی اچھی صفات کا نام حسْنِ اخلاق ہے۔ ’’گناہ وہ ہے جو تیرے دل میں کھٹکے‘‘ اس سے مراد یہ ہے کہ کسی چیز کے بارے میں ایسی بےچینی، بےقراری اور نفرت وکراہیت ہو کہ اطمینان حاصل نہ ہو۔ اس لئے تو اس پر کسی کا اطلاع پانا ناپسند ہوتا ہے۔خیال رہے یہاں پختہ ناپسندیدگی مراد ہے عارضی نہیں جیسے کوئی پیدل چلنے والوں کے درمیان بطورِ عاجزی سوار ہونا ناپسند کرے تو ایسی ناپسندیدگی گناہ نہیں۔ (دلیل الفالحین، باب فی الورع وترک الشبھات، ۳/ ۳۲، تحت الحدیث:۵۸۹، ملخصًا)\n¥نیکی حُسْنِ اَخلاق کا نام ہے:\n حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حضرت سیِّدُنا نواس بن سمعان رضی اللہ عنہ سے مروی حدیث پاک کے جز ’’نیکی حسن اخلاق کا نام ہے‘‘ کی شرح کرتے ہوئے فرماتے ہیں: ’’اچھی عادت (حسْنِ اخلاق) عام ہے مخلوق کے ساتھ برتاوا اور خالق سے معاملات سب ہی کو شامل ہے نماز روزہ کی پابندی اچھی عادت ہے گناہوں سے بچنا اچھی عادت ہے وغیرہ ۔‘‘ اور حدیث شریف کے جز ’’ گناہ وہ ہے جو تیرے دل میں کھٹکے اور تجھے اس پر لوگوں کا مطلع ہونا (اِطلاع پانا) ناپسند ہو‘‘ کی شرح میں فرماتے ہیں: یہ فرمان کامل مسلمانوں کے لیے ہے جیسے ہم کو مکھی ہضم نہیں ہوتی فوراً قے ہو جاتی ہے یوں ہی صالحین کو گناہ ہضم نہیں ہوتا فوراً انہیں دلی قبض روحانی تکلیف محسوس ہوتی ہے عام لوگوں کا یہ حال نہیں۔بعض تو گناہ پر خوش ہوکر اعلان کرتے ہیں حضور صلّی اللہ علیہ واٰلہٖ وسلّم حکیْمِ مطلق ہیں ہر شخص کو اس کے مطابق دواء عطا فرماتے ہیں،یوں ہی ’’اَلنَّاس‘‘ سے مراد مقبول بندے ہیں۔ (مراٰۃ المناجیح، 6/ 638، 639)\n¥حُسْنِ اَخلاق کی فضیلت:\nحضرت سیِّدُنا ابو دردا رضی اللہ عنہ سے مروی ہے کہ حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’میزانِ عمل میں حُسنِ اخلاق سے زیادہ وزنی کوئی چیز نہیں۔‘‘ (ابوداود، کتاب الادب، باب فی حسن الخلق، ۴/ ۳۳۲، حدیث:۴۷۹۹)\n¥حُسْنِ اَخلاق اور گناہ سے مراد:\nحسن اخلاق سے مراد ہے معاملہ میں انصاف کرنا، گفتگو میں نرمی کرنا، بھلائی کے کاموں میں خرچ کرنا وغیرہ اور گناہ وہ چیزہے جو دل میں نفرت پیدا کرے اور یہ وہ اصول ہے جس کے ذریعے سے نیکی اور گناہ کی پہچان ہوتی ہے۔ \n(شرح اربعین لابن دقیق العید، ص۶۸، ۶۹ تحت الحدیث:۲۷)\n¥حضور علیہِ السّلام ¥قلبی خیالات سے بھی واقف ہیں:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حضرت سیِّدُنا وابصہ بن معبد رضی اللہ عنہ سے مروی حدیث شریف کے جز ’’تم نیکی اور گناہ کے متعلق پوچھنے آئے ہو‘‘ کی شرح میں فرماتے ہیں: یہ غیبی خبر ہے کہ حضرت وابصہ ( رضی اللہ عنہ )جو سوال دل میں لے کر آئے تھے حضور صلی اللہ علیہ واٰلہٖ وسلّم نے ان کے بغیر عرض کئے ہوئے ارشا دفرمادیا (کہ تم نیکی اور گناہ کے متعلق پوچھنے آئے ہو)۔ معلوم ہوتا ہے کہ اللہ تعالیٰ نے انہیں دلوں کے حال پر مطلع فرمایا ہے کیوں نہ ہو انہیں تو پتھروں کے دلوں پر اطلاع ہے کہ فرماتے ہیں احد پہاڑ ہم سے محبت کرتا ہے۔ (چنانچہ آپ صلی اللہ علیہ واٰلہٖ وسلّم نے اپنی انگلیاں جمع کرکے ان کے سینے پر لگائیں تین بار فرمایا: اپنے دل سے فتویٰ لیا کرو)اس کے تحت فرماتے ہیں: حضور صلی اللہ علیہ و سلّم نے حضرت وابصہ( رضی اللہ عنہ )کے سینہ پر ہاتھ رکھ کر ان کے قلب (دل) کو فیض دیا جس سے ان کا نفس بجائے امارہ کے مطمئنہ ہوگیا اور دل خطرات شیطانی وسوسوں سے پاک و صاف ہوگیا ۔صوفیاء کرام جو مریدوں کے سینے پر ہاتھ مار کر یا توجہ ڈال کر انہیں فیض دیتے ہیں ان کی اصل یہ حدیث بھی ہے۔\n¥نیکی وہ ہے جس پر نفس مطمئن ہو:\n اور حدیث پاک کے جز ’’نیکی وہ ہے جس پر تمہارا نفس مطمئن ہو اور اطمینانِ قلبی حاصل ہو‘‘ کے تحت فرماتے ہیں: اے وابصہ! گناہ اور نیکی کی پہچان یہ ہے کہ جس پر تمہارا دل ونفس مطمئنہ جمے وہ نیکی ہوگی اور جسے تمہارا دل ونفْسِ مطمئنہ قبول نہ کرے وہ گناہ ہوگا۔ یہ حکم حضرت وابصہ کے لئے آج سے ہو گیا یہ حضور (صلی اللہ علیہ واٰلہٖ وسلّم) کے ہاتھ شریف کا اثر ہوا، ہم جیسے لوگوں کو یہ حکم نہیں۔ یہاں (صاحب) مرقات نے فرمایا کہ غیر مجتہد یعنی مقلد تو اپنے امام سے فتویٰ لے اور مجتہد اپنے دل سے۔ \n¥گناہ وہ جو دل میں شک پیدا کرے:\n اور حدیث شریف کے جز ’’ گناہ وہ ہے جو تمہارے نفس میں کھٹکے اور دل میں شک پیدا کرے ، اگرچہ لوگ تمہیں فتویٰ دیں ‘‘ یعنی عام لوگوں کے فتوے کا تم اعتبار نہ کرنا کیونکہ اُن کے دلوں پر ہمارا ہاتھ نہیں پہنچا،اپنے دل و نفس کا فتویٰ قبول کرنا کہ تمہارے دل کا فتویٰ ہمارا فیصلہ ہوگا کہ ہمارا ہاتھ تمہارے دل پر ہے۔ (مراٰۃ المناجیح، 4/ 235)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6893, "bookId": 13, "volNo": "1", "hadithNo": 28, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "سنت کی اہمیت", "arabic": "عَنْ اَبِيْ نَجِيْحِ الْعِرْبَاضِ بْنِ سَارِيَةَ رَضيَ اللهُ عَنْهُ قَالَ: وَعَظَنَا رَسُوْلُ اللهِ صلّی اللهِ علیہ وسلّم مَوْعِظَةً وَّجِلَتْ مِنهَا الْقُلُوْبُ وَذَرَفَتْ مِنهَا الْعُيُوْنُ. فَقُلْنَا: يَا رَسُوْلَ اللهِ صلّی اللهِ علیہ وسلّم ! كَاَنَّهَا مَوْعِظَةُ مُوَدِّعٍ فَاَوْصِنَا. قَالَ: ’’اُوْصِيْكُمْ بِتَقْوَى اللهِ وَالسَّمعِ وَالطَّاعَةِ وَاِنْ تَاَمَّرَ عَلَيْكُمْ عَبْدٌ، فَاِنَّهٗ مَنْ يَّـعِشْ مِنْكُمْ فَسَيَرٰى اِخْتِلَافًا كَثِيْرًا، فَعَلَيْكُمْ بِسُنَّتِيْ وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِيْنَ الْمَهْدِيِّـيْنَ عَضُّوْا عَلَيْهَا بِالنَّوَاجِذِ وَاِيَّاكُمْ وَمُحْدَثَاتِ الْاُمُوْرِ فَاِنَّ كُلَّ بِدْعَةٍ ضَلَالَةٌ.‘‘ \n(رَوَاهُ اَبُوْ دَاؤُدَ وَالتِّرْمَذِیُّ وَقَالَ: حَدِيْثٌ حَسَنٌ صَحِيْحٌ)", "urdu": "ترجمہ:حضرت سیِّدُنا ابونجیح عِرباض بن ساریہ رضی اللہ عنہ فرماتے ہیں کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ہمیں ایک ایسی نصیحت فرمائی جس سے دل دہل گئے اور آنسو بہنے لگے۔ ہم نے عرض کی: یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! ایسا لگ رہا ہے کہ یہ الوداعی نصیحت ہے، لہٰذا ہمیں کچھ وصیت فرمادیں۔ ارشاد فرمایا: ’’میں تمہیں اللہ پاک سے ڈرنے، حاکم کی بات سننے اور فرماں برداری کرنے کی نصیحت کرتا ہوں اگرچہ کوئی غلام ہی تم پر حاکم ہو کیونکہ تم میں سے جو زندہ رہے گا عنقریب وہ بہت اختلافات دیکھے گا۔ لہٰذا تم پر میری سنت اور ہدایت یافتہ خلفائے راشدین کا طریقہ اختیار کرنا لازم ہے، اسے مضبوطی سے تھام لو اور نئے کاموں سے بچو کہ ہربدعت گمراہی ہے۔‘‘(ترمذی، کتاب العلم، باب ماجاء فی الاخذ فی السنة...الخ، ۴/ ۳۰۸، حدیث:۲۶۸۵، بتغیر قلیل ۔ ابوداود، كتاب السنة، باب فی لزوم السنة، ۴/ ۲۶۷، حدیث:۴۶۰۷)\n(اس حدیث کو حضرت سیِّدُنا امام ابو داود سلیمان بن اشعث ازدی سجستانی اور حضرت سیِّدُنا امام ابو عیسیٰ محمد بن عیسیٰ ترمذی رحمۃ اللہ علیہما نے (سنن ابو داود اور جامع ترمذی میں) روایت کیا ہے اور حضرت سیِّدُنا امام ترمذی رحمۃ اللہ علیہ نے فرمایا: یہ حدیث حسن صحیح ہے۔)", "roman": "Tarjuma: Hazrat Sayyiduna Abu Najeeh Irbaaz bin Sariyah Radiyallahu Anhu farmate hain ke Huzoor Nabi-e-Paak Sallallahu Alaihi wa Sallam ne hamein ek aisi naseehat farmayi jis se dil dehal gaye aur aansoo behne lage. Hum ne arz ki: Ya Rasoolullah Sallallahu Alaihi wa Sallam! Aisa lag raha hai ke yeh alwida'i naseehat hai, lihaza hamein kuch Wasiyat farmadein. Irshad farmaya: 'Main tumhein Allah Paak se darne, Imam ki baat sunne aur farmanbardari karne ki naseehat karta hoon agarche koi ghulam hi tum par Imam ho kyunke tum mein se jo zinda rahega anqareeb woh bohat ikhtilafat dekhega. Lihaza tum par meri Sunnat aur hidayat yafta Khulafa-e-Rashideen ka Tareeqa ikhtiyar karna laazim hai, ise mazbooti se thaam lo aur naye kaamon se bacho ke har Bid'at Gumraah hai.' (Tirmizi, Kitaab-ul-Ilm, Baab ma ja'a fil-akhzi fis-Sunnati... al-kh, 4/308, Hadees: 2685, bataghayyur-e-qaleel. Abu Dawood, Kitaab-us-Sunnah, Baab fi luzoom-is-Sunnah, 4/267, Hadees: 4607). (Is Hadees ko Hazrat Sayyiduna Imam Abu Dawood Sulaiman bin Ash'as Azdi Sajistani aur Hazrat Sayyiduna Imam Abu Isa Muhammad bin Isa Tirmizi Rahmatullah Alayhima ne (Sunan Abu Dawood aur Jami' Tirmizi mein) riwayat kiya hai aur Hazrat Sayyiduna Imam Tirmizi Rahmatullah Alayh ne farmaya: Yeh Hadees Hasan Saheeh hai.)", "explanation": "¥دل دہل گئے اور آنکھیں بہنے لگیں:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’ایک ایسی نصیحت فرمائی جس سے دل دہل گئے اور آنسو بہنے لگے‘‘ کے تحت فرماتے ہیں: یوں توحضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کے تمام وعظ ہی مؤثر (اثر کرنے والے) ہوتے تھے لیکن خصوصیت سے یہ وعظ بہت پُرتاثیرتھا۔جس میں عِشقِ خدا، خوفِ ذاتِ کبریا کا دریا موجیں مار رہا تھا۔ عشق سے آنسو بہے اورخوف سے دل ڈرے۔ (مراٰۃ المناجیح، 1/ 165)\n امام شرف الدین طیبی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’آنکھیں بہنے لگیں‘‘ کی شرح میں فرماتے ہیں: (حالانکہ آنکھیں نہیں بلکہ آنکھوں سے آنسو بہتے ہیں) یہ رونے میں مبالغہ ہے کہ اس قدر روئے گویا آنکھیں بہنے لگیں۔ نیز صحابَۂ کرام علیہم الرضوان نے اسے الوداعی وعظ کہا کیونکہ وصیت کرنے والا بوقْتِ رُخصت بہت اہم اور ضروری باتیں بیان کرتا ہے۔\n(شرح الطیبی، کتاب الایمان، باب الاعتصام بالکتاب والسنة، ۱/ ۳۶۱، تحت الحدیث: ۱۶۵)\n¥الوداعی نصیحت:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’ایسا لگ رہا ہے کہ یہ الوداعی نصیحت ہے‘‘ کے تحت فرماتے ہیں: یعنی حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کی وفات قریب ہے اور آپ ایسی باتیں فرما رہے ہیں جیسی رخصت ہوتے وقت کی جاتی ہیں گویا آپ اپنی امت کو چھوڑ کر جارہے ہیں اور آخری نصیحتیں کر رہے ہیں۔ سُبْحٰنَ اللہ!صحابَۂ کرام (علیہمُ الرّضوان) کی ذکاوت کے قربان۔ معلوم ہوتا ہے کہ واقعی حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کی وفات قریب تھی اس لیے ان کے کلام کی تردید نہ فرمائی گئی بلکہ خواہش پوری کردی گئی۔ پتا لگا کہ حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) اپنے وقْتِ وفات کو جانتے ہیں اور یہ ایسا جامع کلام ہے کہ سارے اَحکام اس میں آگئے۔ (مراٰۃ المناجیح، 1/ 165)\n¥الوداعی نصیحت کی کیفیت:\nعارِف باللہ حضرت سیِّدُنا علامہ عبد الغنی نابُلسی رحمۃُ اللہ علیہ فرماتے ہیں:حضورنبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے الوداع کہنے والے کی طرح نصیحت فرمائی یعنی ایسے شخص کی طرح وصیت کی جو اپنی قوم کو چھوڑ کر جارہاہواوراُنہیں ضروری باتوں کی وصیت کرے تو ایسا شخص نصیحت کرتا، خوف دلاتا، زجر وتوبیخ کرتا اوراپنی مخالفت سے ڈراتا ہے اور ایسا صرف اُن کی بھلائی کی اِنتہائی چاہت کے سبب کرتا ہے کہ کہیں وہ اِس کے بعدگمراہ نہ ہوجائیں ۔ حدیثِ مذکورمیں اس طرف اشارہ ہے کہ مبلغ بیان کرتے وقت حاضرین کونصیحت کرنے میں پوری کوشش کرے اور کوئی ایسی فائدہ مند بات ترک نہ کرے جس کے متعلق جانتاہوکہ حاضرین اس کے‏لئے دوسری مجلس کے محتاج ہوں گے کیونکہ دوسری مجلس تک زندہ رہنے کاکوئی بھروسا نہیں۔ نیز مبلغ کو چاہیے کہ بغیرمشقت اٹھائے حَسبِ موقع حاضرین کو ( عذاب سے) ڈرائے اور زجر وتوبیخ کرے۔ البتہ !اس کی عادت نہ بنائے جیسا کہ حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم کامبارک عمل تھاکہ کبھی ڈراتے اورکبھی نہ ڈراتے ۔(حدیقة ندیة، ۱/ ۹۵)\n¥اللہ پاک سے ڈرو:\nحدیث پاک میں ہے: رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے نصیحت فرمائی کہ ’’میں تمہیں اللہ پاک سے ڈرنے، حاکم کی بات سننے اور فرمانبرداری کرنے کی نصیحت کرتا ہوں۔‘‘ مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں: یہ ایسا جامع کلام ہے کہ سارے احکام اس میں آگئے۔ تَقْوَی اللہ میں سارے دینی اَحکام اور سلطان کی اطاعت میں سارے سیاسی احکام شامل ہیں۔ (مراٰۃ المناجیح، 1/ 165) \n¥تقویٰ کا معنیٰ ومفہوم:\n تفسیر صراط الجنان، جلد1، صفحہ 62 پر ’’تفسیر مدارک اور تفسیر خازن‘‘ کے حوالے سے ہے کہ تقویٰ کا معنیٰ ہے: ’’نفس کو خوف کی چیز سے بچانا۔‘‘ اور شریعت کی اِصطلاح میں تقویٰ کا معنیٰ یہ ہے کہ نفس کو ہر اس کام سے بچانا جسے کرنے یا نہ کرنے سے کوئی شخص عذاب کا مستحق ہو۔ جیسے کفر و شرک، کبیرہ گناہوں، بےحیائی کے کاموں سے اپنے آپ کو بچانا، حرام چیزوں کو چھوڑدینا اور فرائض کو ادا کرنا وغیرہ اور بزرگانِ دین نے یہ بھی فرمایا ہے کہ تقویٰ یہ ہے کہ ’’تیرا خدا تجھے وہاں نہ پائے جہاں اس نے منع فرمایا ہے۔‘‘ (مدارک، البقرة، تحت الاٰیة:۲، ص۱۹۔ خازن، البقرة، تحت الاٰیة:۲، ۱/ ۲۲، ملتقطًا)\n¥متقی اور تقویٰ کی تعریف:\n حضرت ابنِ عباس رضی اللہ عنہما نے فرمایا: متقی وہ ہے جو شرک و کبائر و فواحش سے بچے۔ بعضوں نے کہا متقی وہ ہے جو اپنے آپ کو دوسروں سے بہتر نہ سمجھے۔ بعض کا قول ہے تقویٰ حرام چیزوں کا ترک اور فرائض کا ادا کرنا ہے۔ بعض کے نزدیک معصیت پر اصرار اور طاعت پر غرور کا ترک (یعنی گناہوں سے باز رہنے اور عبادت پر نازاں ہونے کو چھوڑ دینے کانام) تقویٰ ہے۔ بعض نے کہا تقویٰ یہ ہے کہ تیرا مولیٰ تجھے وہاں نہ پائے جہاں اس نے منع فرمایا۔ ایک قول یہ ہے کہ تقویٰ حضور علیہِ الصّلوٰۃُوالسّلام اور صحابہ رضی اللہ تعالیٰ عنہم کی پیروی کا نام ہے (خازن)۔یہ تمام معنیٰ باہم مناسبت رکھتے ہیں اور مآل (یعنی اصل) کے اعتبار سے ان میں کچھ مخالفت نہیں۔(خزائن العرفان، پ1، سورۂ بقرہ، تحت الآیہ: 2)\n¥تقویٰ کے مراتب:\n تقویٰ کے مراتب بہت ہیں: عوام کا تقویٰ ایمان لا کر کُفر سے بچنا، متوسطین کا (تقویٰ) اوامر و نواہی کی اطاعت(یعنی احکامات پر عمل کرنا اور ممنوعات سے بچنا)، خواص کا (تقویٰ) ہر ایسی چیز کو چھوڑنا جو اللہ تعالیٰ سے غافل کرے(جمل)۔\n(خزائن العرفان، پ1، سورۂ بقرہ، تحت الآیہ: 2)\n¥تقویٰ کے ارکان اور اعلیٰ رکن:\n مراٰۃ المناجیح میں ہے: تقویٰ کے دو رکن ہیں: اچھے کام کرنا،برے کاموں سے بچنا۔ مگر اس کا رکْنِ اعلیٰ بُرے کاموں سے بچنا ہے۔ عبادات آسان ہیں مگر محرمات سے پرہیز، بُرے معاملات سے بچنا بہت ہی مشکل ہے۔بعض کے نزدیک ورع اور تقویٰ ایک ہی چیز ہے،بعض کے نزدیک محرمات سے بچنا تقویٰ ہے اور شبہ کی چیز سے بچنا ورع یا فرائض پر عمل تقویٰ ہے،سنت و مستحب پر عمل ورع۔خیال رہے نیکیاں گویا روحانی دوائیں ہیں گناہوں سے بچنا گویا روحانی پرہیز، دوا بغیر پرہیز مفید نہیں ہوتی۔ (مراٰۃ المناجیح، 6/ 634)\n¥تقویٰ کی عظمت:\nتقویٰ عظیم عبادت، تمام نیکیوں کی اصل اور بےشمار فضائل کا حامل ہے۔ چنانچہ تقویٰ: اللہ پاک کےدوستوں یعنی ولیوں کی پہچان ہے ۔ قرآن مجید میں ارشاد ہوتا ہے:\nاَلَاۤ اِنَّ اَوْلِیَآءَ اللّٰهِ لَا خَوْفٌ عَلَیْهِمْ وَ لَا هُمْ یَحْزَنُوْنَۚۖ(۶۲) الَّذِیْنَ اٰمَنُوْا وَ كَانُوْا یَتَّقُوْنَؕ(۶۳) (پ ۱۱، یونس:۶۲، ۶۳)\nترجمہ کنزالایمان: سن لو بےشک اللہ کے ولیوں پر نہ کچھ خوف ہے نہ کچھ غم وہ جو ایمان لائے اور پرہیزگاری کرتے ہیں۔\nمتقی: کا مرتبہ اللہ پاک کی بارگاہ میں سب سے بلند ہے۔ فرمانِ باری تعالیٰ ہے:\nاِنَّ اَكْرَمَكُمْ عِنْدَ اللّٰهِ اَتْقٰىكُمْؕ (پ ۲۶، الحجرات:۱۳)\nترجمہ کنزالایمان: بےشک اللہ کے یہاں تم میں زیادہ عزت والا وہ جو تم میں زیادہ پرہیزگار ہے۔\nمتقی: اللہ پاک کے اور اللہ پاک متقیوں کا دوست ہے۔ ارشادِ باری تعالیٰ ہے:\nوَ اللّٰهُ وَلِیُّ الْمُتَّقِیْنَ(۱۹) (پ ۲۵، الجاثیة:۱۹)\nترجمہ کنزالایمان: اور ڈر والوں کا دوست اللہ۔\nمتقی: اللہ پاک کے محبوب ہیں۔ قرآنِ کریم میں ہے:\nاِنَّ اللّٰهَ یُحِبُّ الْمُتَّقِیْنَ(۷) (پ ۱۰، التوبة:۷)\nترجمہ کنزالایمان: بےشک پرہیزگار اللہ کو خوش آتے ہیں۔\nتقویٰ:سفر آخرت کے لئے بہترین زادِ راہ ہے۔ فرمانِ باری تعالیٰ ہے:\nفَاِنَّ خَیْرَ الزَّادِ التَّقْوٰى٘ (پ ۲، البقرة:۱۹۷)\nترجمہ کنزالایمان: کہ سب سے بہتر توشہ پرہیزگاری ہے۔\nتقویٰ:انسان کے لئے بہترین لباس ہے جو ایمان، نیک عمل، شرم وحیا اور اچھے اخلاق کے ساتھ انسان کے باطنی وروحانی وجود کی شیطان سے حفاظت کرتا اور اس کے اخلاقی وجود کو زینت بخشتا ہے۔ ارشاد باری تعالیٰ ہے:\nوَ لِبَاسُ التَّقْوٰىۙ-ذٰلِكَ خَیْرٌؕ (پ ۸، الاعراف:۲۶)\nترجمہ کنزالایمان: اور پرہیزگاری کا لباس وہ سب سے بھلا۔\nمتقی:کو ربِّ کریم حق وباطل میں فرق کرنے والا نور عطا فرماتا ہے، اس کی خطائیں معاف ہوتیں اور اسے بخشش سے نوازا جاتا ہے۔ فرمانِ باری تعالیٰ ہے:\nیٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْۤا اِنْ تَتَّقُوا اللّٰهَ یَجْعَلْ لَّكُمْ فُرْقَانًا وَّ یُكَفِّرْ عَنْكُمْ سَیِّاٰتِكُمْ وَ یَغْفِرْ لَكُمْؕ-وَ اللّٰهُ ذُو الْفَضْلِ الْعَظِیْمِ(۲۹) (پ ۹، الانفال:۲۹)\nترجمہ کنزالایمان: اے ایمان والو اگر اللہ سے ڈرو گے تو تمہیں وہ دے گا جس سے حق کو باطل سے جدا کر لو اور تمہاری برائیاں اتار دے گا اور تمہیں بخش دے گا اور اللہ بڑے فضل والا ہے۔\nمتقی:کے لئے اللہ پاک مشکلات میں راہِ نجات پیدا کر دیتا اور اسے وہاں سے عالی شان رزق عطا فرماتا ہے جہاں سےاس کا گمان بھی نہیں ہوتا۔ قرآنِ مجید میں ارشاد ہوتا ہے:\nوَ مَنْ یَّتَّقِ اللّٰهَ یَجْعَلْ لَّهٗ مَخْرَجًاۙ(۲) وَّ یَرْزُقْهُ مِنْ حَیْثُ لَا یَحْتَسِبُؕ (پ ۲۸، الطلاق:۲، ۳)\nترجمہ کنزالایمان: اور جو اللہ سے ڈرے اللہ اس کے لیے نجات کی راہ نکال دے گا اور اسے وہاں سے روزی دے گا جہاں اس کا گمان نہ ہو۔\n¥مندرجہ بالا آیت طیبہ کا شانِ نزول:\nصدر الافاضل حضرت علامہ مولانا سیِّد محمد نعیم الدین مراد آبادی رحمۃُ اللہ علیہ تفسیر خزائن العرفان میں مذکورہ بالا آیت مقدسہ کے تحت فرماتے ہیں: سیّدِ عالَم صلّی اللہ علیہ واٰلہٖ وسلّم سے مروی ہے کہ جو شخص اس آیت کو پڑھے اللہ تعالیٰ اس کےلئے شبہاتِ دنیا، غمراتِ موت و شدائدِ روزِ قیامت سے خلاص کی راہ نکالے گا۔ اور اس آیت کی نسبت سیّدِ عالَم صلّی اللہ علیہ واٰلہٖ وسلّم نے یہ بھی فرمایا کہ میرے علم میں ایک ایسی آیت ہے جسے لوگ محفوظ کرلیں توان کی ہر ضرورت و حاجت کےلئے کافی ہے ۔ شانِ نزول: عوف بن مالک کے فرزند کو مشرکین نے قید کرلیا تو عوف نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم کی خدمت میں حاضر ہوئے اور انہوں نے یہ بھی عرض کیا کہ میرا بیٹا مشرکین نے قید کرلیا ہے اور اسی کے ساتھ اپنی محتاجی و ناداری کی شکایت کی، سیّدِ عالَم صلّی اللہ علیہ واٰلہٖ وسلّم نے فرمایا کہ اللہ تعالیٰ کا ڈر رکھو اور صبر کرو اور کثرت سےلَاحَوْلَ وَلَا قُوَّۃَ اِلَّا بِاللّٰہ الْعَلِیِّ الْعَظِیْم پڑھتے رہو عوف نے گھرآکر اپنی بی بی سے یہ کہا اور دونوں نے پڑھنا شروع کیا وہ پڑھ ہی رہے تھے کہ بیٹے نے دروازہ کھٹکھٹایا دشمن غافل ہوگیا تھا اس نے موقع پایا قید سے نکل بھاگا اور چلتے ہوئے چار ہزار بکریاں بھی دشمن کی ساتھ لے آیا، عوف نے خدمتِ اقدس میں حاضر ہو کر دریافت کیا کہ یہ بکریاں ان کے لئے حلال ہیں؟ حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) نے اجازت دی اور یہ آیت نازل ہوئی ۔(خزائن العرفان،پ28، سورۂ طلاق، تحت الآیہ:2)\n¥تقویٰ کی اقسام:\nسیِّد محمد نعیم الدین مراد آبادی رحمۃُ اللہ علیہ سورۂ بقرہ، آیت:2 کے تحت’’تفسیر خزائن العرفان‘‘ میں نقل فرماتے ہیں: حضرت مترجم(یعنی ترجمہ قرآن کنزالایمان کے مترجم سیِّدی اعلیٰ حضرت مولانا شاہ امام احمد رضا خان) قُدِّسَ سِرُّہٗ نے فرمایا کہ تقویٰ سات قسم کا ہے: (1)...کُفر سے بچنا اللہ پاک کے فضل سے یہ ہر مسلمان کو حاصل ہے۔ (2)...بدمذہبی سے بچنا یہ ہر سنی کو نصیب ہے۔ (3)...ہر کبیرہ (یعنی بڑے گناہ) سے بچنا۔ (4)... صغائر (یعنی چھوٹے گناہوں) سے بھی بچنا۔ (5)... شبہات سے احتراز (یعنی جن کے حلال وجائز ہونے میں شک ہو ان سے بچنا)۔ (6)...شہوات (یعنی نفسانی خواہشات)سے بچنا اور (7)...غیر کی طرف التفات (یعنی اللہ پاک کے علاوہ کسی اور کی طرف متوجہ ہونے) سے بچنا۔ یہ اَخَصُّ الْخَواص کا منصب ہے اور قرآنِ عظیم ساتوں مرتبوں کا ہادی(یعنی راہ نما) ہے۔(ملخص از خزائن العرفان،پ1، سورۂ بقرہ، تحت الآیہ:2)\n¥مذکورہ اقسام کی تفصیل:\nپہلی قسم کفر سے بچنا:رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا کہ ’’جس شخص میں تین خصلتیں ہوں گی وہ ایمان کی مٹھاس پالے گا: (1)...اللہ پاک اور اس کا رسول اسے باقی تمام چیزوں سے زیادہ محبوب ہوں۔ (2)...جس شخص سے بھی اس کو محبت ہو وہ محض اللہ پاک کی وجہ سے ہو اور (3)...کفر سے نجات کے بعد کفر میں جانے کو اس طرح ناپسند کرتا ہو جیسے آگ میں پھینکے جانے کو ناپسند کرتا ہے۔‘‘ (بخاری، کتاب الایمان، باب حلاوة الایمان، ۱/ ۱۷، حدیث:۱۶)\nدوسری قسم گمراہی وبدمذہبی سے بچنا:رَسُوْلُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا کہ ’’آخری زمانہ میں جھوٹے دجال ہوں گے، وہ تم کو ایسی احادیث سنائیں گے جن کو نہ تم نے سنا ہوگا ، نہ تمہارے باپ دادا نے ، تو تم ان سے دور رہنا ، کہیں وہ تمہیں گمراہ نہ کر دیں کہیں وہ تمہیں فتنہ میں مبتلا نہ کر دیں۔‘‘ \n(مسلم، مقدمة المؤلف، باب النھی فی الروایة عن الضعفاء والاحتیاط فی تحملھا، ص۱۷، حدیث:۱۶)\nتیسری قسم کبیرہ گناہوں سے بچنا:حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا کہ ’’اِتَّقِ الْمَحَارِمَ تَكُنْ اَعْبَدَ النَّاس‘‘ یعنی حرام کاموں سے بچو سب سے بڑے عبادت گزار بن جاؤ گے۔‘‘ (ترمذی، کتاب الزھد، باب من التقی المحارم فھو اعبد الناس ، ۴/ ۱۳۷، حدیث:۲۳۱۲) اور قرآنِ مجید میں فرمایا گیا:\nاِنْ تَجْتَنِبُوْا كَبَآىٕرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَیِّاٰتِكُمْ وَ نُدْخِلْكُمْ مُّدْخَلًا كَرِیْمًا(۳۱) (پ ۵، النسآء:۳۱)\nترجمہ کنزالایمان: اگر بچتے رہو کبیرہ گناہوں سے جن کی تمہیں ممانعت ہے تو تمہارے اور گناہ ہم بخش دیں گے اور تمہیں عزت کی جگہ داخل کریں گے۔\nچوتھی قسم صغیرہ گناہوں سے بچنا:حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا کہ ’’اِنَّ الْمُؤْمِنَ اِذَا اَذْنَبَ كَانَتْ نُكْتَةٌ سَوْدَآءٌ فِيْ قَلْبِهٖیعنی بےشک بندۂ مومن جب گناہ کرتا ہے تو اس کے دل پر ایک سیاہ نکتہ لگ جاتا ہے۔‘‘ \n(ابن ماجة، کتاب الزھد، باب ذکر الذنوب، ۴/ ۸۸، حدیث:۴۲۴۴)\nپانچویں قسم ان چیزوں سے بچنا جن کے جائز وحلال ہونے میں شبہ ہو:رسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا کہ ’’حلال واضح ہے اور حرام بھی بالکل واضح ہے اور ان کے درمیان کچھ شبہ والی چیزیں ہیں جن کا بہت سے لوگوں کو علم نہیں ہے ، تو جو شخص شبہات سے بچا اس نے اپنے دین اور اپنی عزت کو محفوظ کر لیا اور جو شبہ والی چیزوں میں پڑا تو وہ حرام ہی میں جاپڑےگا ، جیسے کوئی شخص کسی ممنوعہ چراگاہ کے آس پاس جانور چرائے تو قریب ہے کہ وہ جانور ممنوعہ چراگاہ میں بھی داخل ہو جائیں۔‘‘ (بخاری، کتاب الایمان، باب فضل فی استبرأ لدینہ، ۱/ ۳۳، حدیث:۵۲)\nچھٹی قسم شہوات وخواہشاتِ نفس سے بچنا: اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا کہ ’’تین باتیں مہلکات میں شامل ہیں: (1)...وہ طمع و لالچ جس کی پیروی کی جائے۔ (2)...وہ خواہِشِ نفس جس کے پیچھے چلا جائے اور (3)...بندے کا خودپسندی میں مبتلا ہونا۔ (معجم اوسط، ۴/ ۱۲۹، حدیث:۵۴۵۲) اور قرآنِ کریم میں ارشاد باری تعالیٰ ہے:\nوَ اَمَّا مَنْ خَافَ مَقَامَ رَبِّهٖ وَ نَهَى النَّفْسَ عَنِ الْهَوٰىۙ (۴۰) فَاِنَّ الْجَنَّةَ هِیَ الْمَاْوٰىؕ (۴۱) (پ ۳۰، النّٰزعٰت:۴۰، ۴۱)\nترجمہ کنزالایمان: اور وہ جو اپنے رب کے حضور کھڑے ہونے سے ڈرا اور نفس کو خواہش سے روکا تو بےشک جنت ہی ٹھکانہ ہے۔\nساتویں قسم غیر کی طرف التفات سے بچنا:یہ اَخَص الْخَواص مقربِینِ بارگاہِ الٰہی کا نصیب ہے کہ اپنا جینا مرنا سب اللہ پاک کے لئے کر دیتے، اپنی جان مولائے کریم کو بیچ دیتے اور اس کی یاد ومحبت میں ڈوب کر سب سے ٹوٹ کر اسی کے ہوجاتے ہیں۔ غیر کو ظاہراً دیکھنے میں بھی تجلیاتِ الٰہیہ کے مشاہدہ و مطالعہ میں یا حکْمِ الٰہی کی پیروی میں ہوتے ہیں۔ قرآنِ پاک میں ارشاد ہوتا ہے:\nقُلْ اِنَّ صَلَاتِیْ وَ نُسُكِیْ وَ مَحْیَایَ وَ مَمَاتِیْ لِلّٰهِ رَبِّ الْعٰلَمِیْنَۙ(۱۶۲) (پ ۸، الانعام:۱۶۲)\nترجمہ کنزالایمان: تم فرماؤ بےشک میری نماز اور میری قربانیاں اور میرا جینا اور میرا مرنا سب اللہ کے لئے ہےجو رب سارے جہان کا۔\nایک مقام پر ارشاد ہوا:\nوَ مِنَ النَّاسِ مَنْ یَّشْرِیْ نَفْسَهُ ابْتِغَآءَ مَرْضَاتِ اللّٰهِؕ (پ ۲، البقرة:۲۰۷)\nترجمہ کنزالایمان: اور کوئی آدمی اپنی جان بیچتا ہے اللہ کی مرضی چاہنے میں۔\nایک اور جگہ ارشاد ہوا:\nوَ اذْكُرِ اسْمَ رَبِّكَ وَ تَبَتَّلْ اِلَیْهِ تَبْتِیْلًاؕ(۸) (پ ۲۹، المزمل:۸)\nترجمہ کنزالایمان: اور اپنے رب کا نام یاد کرو اور سب سے ٹوٹ کر اسی کے ہو رہو۔\n¥ابدی عذاب سے نجات کا سبب:\nحضرت سیِّدُنا علامہ علی قاری رحمۃُ اللہ علیہ حدیث شریف کے جز ’’میں تقویٰ (یعنی اللہ پاک سے ڈرنے) کی نصیحت کرتا ہوں‘‘ کے تحت فرماتے ہیں: حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم کا یہ فرمان جوامع الکلم سے ہے کیونکہ تقویٰ نام ہے تمام احکامات بجا لانے اور ممنوعات سے اجتناب کرنے کا۔ نیز تقویٰ ہی ہے جو ابدی عذاب سے نجات دیتا، خوشی والے گھر (یعنی جنت) تک پہنچاتا اور ربِّ کریم کے درِ رحمت پر لے جاتا ہے۔(مرقاة المفاتیح، کتاب الایمان، باب الاعتصام بالکتاب والسنة، ۱/ ۴۰۷، تحت الحدیث:۱۶۵)\n¥حکمرانوں کی اطاعت وفرمانبرداری کا حکم:\nحدیث شریف کے جز ’’میں تمہیں حکمرانوں کی اطاعت وفرمانبرداری کی نصیحت کرتا ہوں اگرچہ کوئی غلام ہی ہو‘‘ کے تحت فرماتے ہیں: جب تک وہ خلاف شرع حکم نہ دے اس کا حکم مانو خواہ وہ عادل ہو یا ظالم۔ ہاں!خلافِ شرع حکم دے تو نہ مانو کیونکہ اللہ پاک کی نافرمانی میں کسی کی اطاعت جائز نہیں۔ البتہ اُس سے جنگ کرنا جائز نہیں ۔ اگرچہ وہ حاکم جسے خلیفَۂ وقت نے تم پر مقرر کیا ہے حبشی غلام ہی کیوں نہ ہو ، پس اس کی اطاعت کرو اور اس کے نسب کی طرف مت دیکھو بلکہ اُس کے مقام ومرتبے کی طرف نظر کرو۔(مرقاة المفاتیح، کتاب الایمان، باب الاعتصام بالکتاب والسنة، ۱/ ۴۰۸، تحت الحدیث:۱۶۵)\n¥امیر کی اطاعت کرو اگرچہ حبشی غلام ہی ہو:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’اگرچہ حبشی غلام ہی ہو‘‘ کے تحت فرماتے ہیں: یعنی اگر تمہارا امیر کالا حبشی غلام ہو تب بھی اس کی اطاعت کرو اس کا نسب و شکل نہ دیکھو اس کا حکم سنو۔ خیال رہے کہ خلافت قریش سے خاص ہے مگر امارت (بادشاہت) ہر مسلمان کو مل سکتی ہے، لہٰذا یہ حدیث اس حدیث کے خلاف نہیں ’’اَلْخِلَافَۃُ لِلْقُرَیْش‘‘ (یعنی خلافت قریش کے لئے ہے) نیز امیر کی اطاعت انہی احکام میں ہوگی جو خلافِ شرع نہ ہوں۔ نیز اس کی اطاعت امیر بن جانے کے بعد ہوگی۔ یزید امیر بنا ہی نہ تھا،حضرت حسین رضی اللہ عنہ نے اسے حاکم مانا ہی نہیں۔ لہٰذا آپ ( رضی اللہ عنہ )کا عمل اس حدیث کے خلاف نہیں،امیر بنانا اور ہے اور امیر بن چکنے کے بعد اطاعت کرنا کچھ اور۔ (مراٰۃ المناجیح، 1/ 166)\n¥کیا غلام حاکم وامیر بن سکتا ہے؟\nحضرت سیِّدُناشیخ عبدالحق مُحَدِّث دہلوی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’امیر کی اطاعت کرو اگرچہ غلام ہی کیوں نہ ہو‘‘ کے تحت فرماتے ہیں: حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم کےاِس ارشاد سے امیر کی اطاعت میں مبالغہ مقصود ہے ورنہ غلام حاکم و امیر بننے کا اہل نہیں کیونکہ حاکم و امیر کے‏لئے آزاد ہونا شرط ہے۔ یہ کلام بالکل اُس حدیث کی طرح ہے جس میں فرمایا گیا کہ ’’جس نےمسجد بنائی اگرچہ چڑیا کے گھونسلے جتنی ہو اُس کے‏لئے جنت میں گھر بنایا جائے گا۔“ظاہر ہے چڑیا کے گھونسلے جتنی مسجد نہیں ہو سکتی بلکہ اس سے مقصود چھوٹی مسجد کی شان بطورِ مبالغہ بیان کرنا ہے۔البتہ یہ ممکن ہے کہ حبشی غلام سلطانِ کبیر کانائب ہوتواس صورت میں سلطان کے حکم کی وجہ سےاُس غلام کی اطاعت بھی ضروری ہو گی۔\n(اشعة اللمعات، کتاب الایمان،باب الاعتصام بالکتاب والسنة، ۱/ ۱۵۰)\n¥کیا ہر معاملے میں حکمران کی اطاعت کی جائے گی؟\n یاد رکھئے! حکمرانوں کی اطاعت نیکی کے کاموں میں ہے گناہوں کے معاملے میں ان کی اطاعت ہرگز جائز نہیں کہ حدیث پاک میں ہے،اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’لَاطَاعَۃَ فِیْ مَعْصِیَۃٍ اِنَّمَا الطَّاعَۃُ فِی الْمَعْرُوْفِ یعنی نافرمانی وگناہ کے معاملے میں کوئی اطاعت نہیں بےشک اطاعت تو نیکی کے کام میں ہی ہے۔‘‘ \n(بخاری، کتاب اخبار الاحاد، باب ما جاء فی اجازة خبر الواحد...الخ، ۴/ ۴۹۳، حدیث:۷۲۵۷)\n خیال رہے!اطاعت و فرنبرداری میں سب سے پہلے حق اللہ پاک کا ہے، کائنات کے تمام بادشاہ اسی کے قبضہ میں ہیں لہذا اللہ پاک کی نافرمانی میں نہ کسی کے پیچھے چلنا ہے نہ کسی کا حکم ماننا ہے۔ چنانچہ حضرت سیِّدُنا ابودرداء رضی اللہ عنہ سے مروی ایک حدیث شریف میں ہے، رسولِ خدا صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا کہ اللہ پاک ارشاد فرماتا ہے: ’’میں اللہ ہوں، میرے سوا کوئی معبود نہیں، میں بادشاہوں کا مالک اور بادشاہوں کا بادشاہ ہوں، باد شاہوں کے دل میرے قبضہ میں ہیں، جب لوگ میری اطاعت کریں تو میں ان (بادشاہوں ) کے دلوں کو رحمت اور نرمی کرنے کی طرف پھیر دیتا ہوں اور جب لوگ میری نافرمانی کریں تو میں اُن (بادشاہوں) کے دلوں کو سختی اور سزا کی طرف پھیر دیتا ہوں پھر وہ لوگوں کو سخت ایذائیں دیتے ہیں تو تم اپنے آپ کو بادشاہوں کو بدعا دینے میں مشغول نہ کرو بلکہ ذکر اور عاجزی میں مصروف رہو میں تمہارے بادشاہوں کی طرف سے تمہیں کافی ہوں گا۔‘‘ (معجم اوسط، ۶/ ۳۳۵، حدیث:۸۹۶۲)\n¥جو زندہ رہے گا وہ بہت اختلاف دیکھے گا:\nمفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’تم میں جو زندہ رہے گا عنقریب وہ بہت اختلافات دیکھے گا‘‘ کے تحت فرماتے ہیں: سیاسی اختلاف بھی اور مذہبی بھی۔ چنانچہ خلافَتِ عثمانیہ کے آخر میں لوگوں میں سیاسی اختلاف پیدا ہوگیا اور خلافَتِ حیدری میں سیاسی اختلاف کے ساتھ مذہبی اختلاف بھی رونما ہوگیا کہ جبریہ،قدریہ،رافضی،خارجی پیدا ہوگئے۔خیال رہے کہ خدا کے فضل سے صحابہ (کرام علیہمُ الرّضوان) میں دینی اختلاف نہ ہوا،سارے صحابہ (علیہمُ الرّضوان) حق پر رہے،حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کا یہ کلمہ بہت جامع ہے اور آپ کی یہ پیشن گوئی ہو بہو صحیح ہوئی۔ (مراۃ المناجیح، 1/166)\n¥رسولِ کریم صلّی اللہ علیہ وسلّم ¥کا علْمِ غیب:\nحضرت سیِّدُنا علامہ محمد بن علان شافعی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’تم میں سے جو زندہ رہے گا عنقریب وہ بہت اختلافات دیکھے گا‘‘کی شرح میں فرماتے ہیں: یہ فرمانِ عالیٰ رسولِ پاک صلی اللہ علیہ واٰلہٖ وسلّم کے معجزوں میں سے ایک معجزہ ہے کہ آپ کے بعد جو کثیراختلافات واقع ہوں گےپہلے ہی سے ان کی خبر دے دی ۔ بےشک! آپ صلّی اللہ علیہ واٰلہٖ وسلّم (مستقبل میں وقوع پذیر ہونے والے) واقعات کو اِجمالی و تفصیلی طور پر جانتے ہیں کیونکہ یہ بات اَحادیث صحیحہ سے ثابت ہے کہ آپ کو جنتیوں اور جہنمیوں کے ٹھکانے دکھا دیئے گئے لیکن آپ صلّی اللہ علیہ واٰلہٖ وسلّم عموما ًہر کسی کو اس بارے میں بتانے سے احتیاط فرماتے ، کسی کسی کو بتاتےجیسا کہ حضرت سیِّدُنَا حذیفہ اور حضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہما وغیرہ۔ پھر فرمایا: جب تم کثیر اختلاف دیکھو توتم پر لازم ہے کہ اس وقت میری سنت وسیرت اوراَحکامِ اعتقادیہ، عملیہ، واجبہ، مستحبہ پر عمل کرنا اور میرے ہدایت یافتہ خلفائے راشدین کی سنت پر عمل کرنااور وہ ابو بکرصدیق، عمر فاروق، عثمان غنی، علی المرتضیٰ اور حسن بن علی رضی اللہ عنہم ہیں۔ (دلیل الفالحین، باب فی الامر بالمحافظةعلی السنة، ۱/ ۴۱۷، تحت الحدیث:۱۵۸)\n¥وِصال ظاہری کے بعداختلافات:\nعارف باللہ حضرت سیِّدُنا علامہ عبد الغنی نابُلُسی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’تم میں سے جو زندہ رہے گا وہ کثیر اختلافات دیکھے گا‘‘ کی شرح کرتے ہوئے فرماتے ہیں: یہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم کے وصالِ ظاہری کے بعد وقوع پذیر ہونے والے اُمور کے بارے میں غیبی خبر ہے۔ چنانچہ سب سے پہلا اِختلاف خِلافت کے معاملے میں حضرت سیِّدُنا علی المرتضیٰ اور حضرت سیِّدُنا امیر معاویہ رضی اللہ عنہما کے مابین ہوا اور اس معاملے میں حضرات صحابَۂ کرام علیہمُ الرّضوان کی اِجتہادی آراء بھی مختلف تھیں اوربےشک وہ اپنے اجتہاد میں ثواب کے حق دار ہیں۔ اگرچہ بعض(جیسے وہ صحابَۂ کرام علیہم الرضوان جو سیِّدُنا علی رضی اللہ عنہ کے مقابل ان) سے اجتہادی خطا بھی ہوئی مگر اُن کا اِختلاف محض اپنی ذات کے لئے نہ تھا بلکہ دین کے لئے تھا۔ نیز یہ غیبی خبر اُن جنگوں اور کثیر اِختلافات کو بھی شامل ہے جو مسلمان بادشاہوں اور اُمَرا کے درمیان ہوئے اور اُس وقت سے آج تک جاری ہیں۔ نیز اُمورِ دین میں بھی علمائے کرام رحمۃُ اللہ علیہم کے مابین اختلافات ہوئے اور اُن سے منقول اَقوال، اَعمال اور اِعتقادات مختلف ہوگئے اور وہ اُصول وفُروع میں بہت سے مذاہب میں تقسیم ہوئے۔ حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم کی مذکورہ غیبی خبرمیں اِن تمام اِختلافات کی طرف اِشارہ موجود ہے۔ \n(حدیقة ندیة، الباب الاول من الابواب الثلاثة، والدلیل علی الاعتصام بالسنة...الخ، ۱/ ۹۷)\n¥ہر سنت لائق اتباع ہے:\nمشہور شارحِ حدیث، حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’تم پر میری سنت اور ہدایت یافتہ خلفائے راشدین کا طریقہ اختیار کرنا لازم ہے، اسے مضبوطی سے تھام لو‘‘ کے تحت فرماتے ہیں: ہر سنت لائق اتباع ہے مگر ہر حدیث لائق اتباع نہیں۔ حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کے خصوصیات، منسوخ اَحکام و اَعمال حدیث ہیں مگر سنت نہیں، اسی ‏لیے یہاں حدیث کو پکڑنے کا حکم نہیں دیا گیا بلکہ سنت کو (پکڑنے کا حکم دیا گیا ہے)۔ اَلحَمْدُلِلّٰہ! ہم اہل سنت ہیں، دنیا میں اہْل حدیث (یعنی ہر حدیث پر عمل کرنے والا) کوئی نہیں ہو سکتا۔ صحابَۂ کرام (علیہمُ الرّضوان)کے اَعمال و اَفعال بھی لغوی معنیٰ سے سنت ہیں یعنی دین کا اچھا طریقہ اگرچہ اُن کی اِیجادات بدعت حسنہ ہیں۔ (حضرت سیِّدُنا) عمر فاروق ( رضی اللہ عنہ ) نے جماعت کی باقاعدہ تراویح کو جو آپ نے جاری کی تھی بدعت فرمایا کہ کہا: ’’نِعْمَتِ الْبِدْعَۃُ ھٰذِہٖ‘‘ (یعنی یہ کیا ہی اچھی بدعت ہے) ۔ خیال رہے کہ تمام صحابہ ( رضی اللہ عنہم ) ہدایت کے تارے ہیں، خصوصا ً خلفائے راشدین۔ لہٰذا یہ حدیث اس کے خلاف نہیں کہ ’’اَصْحَابِیْ کَالنُّجُوْمِ‘‘ (یعنی میرے صحابہ ستاروں کی مانند ہیں)۔ تمام صحابہ ( رضی اللہ عنہم )کی پیروی باعِثِ نجات ہے۔\n (مراٰۃ المناجیح، 1/ 166، ملتقطاً)\n¥ہر سنت حدیث ہے لیکن ہرحدیث سنت نہیں:\nسنت سے مراد حضور صلّی اللہ علیہ واٰلہٖ وسلّم کے سارے فرمان اور وہ افعال اور اَحوال ہیں جو مسلمانوں کے لیے قابل عمل ہیں۔ حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کے یہ افعال شریعت کہلاتے ہیں اور احوال شریف طریقت۔صوفیاء کے نزدیک حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کے جسم شریف کے حالات شریعت ہیں،قلب کے حالات طریقت،روح کے احوال حقیقت، اور سر کے حالات معرفت،سنت ان سب کو شامل ہے۔ خیال رہے کہ حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کی خصوصیات سنت نہیں، لہٰذا نو بیویاں نکاح میں رکھنا، اُونٹ پر طواف کرنا، منبر پر نماز پڑھانا وغیرہ اگرچہ حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کے افعالِ کریمہ ہیں،لیکن ہمارے واسطے ناقابل عمل۔ ہر سنت حدیث ہے ہر حدیث سنت نہیں (اسی لئے حدیث شریف میں سنت پر عمل کرنے اور اسے لازم پکڑنے کا فرمایا گیا)، اور نبی (کریم صلّی اللہ علیہ واٰلہٖ وسلّم ) نے ’’عَلَیْکُمْ بِسُنَّتِیْ‘‘ فرمایا ’’عَلَیْکُمْ بِحَدِیْثیْ‘‘ نہ فرمایا۔ ہمارا نام بحمدہٖ تعالیٰ اہْلِ سنت ہے یعنی ساری سنتوں پر عامل، اہْلِ حدیث نہیں، کیونکہ ساری حدیثوں پر کوئی عمل نہیں کرسکتا کہ خود کو اہْل حدیث (ہر حدیث پر عمل کرنے والا) کہہ سکے۔ (مراٰۃ المناجیح، 1/ 145، ملخصاً)\n¥سنت کی اہمیت وفضیلت:\nقرآنِ مجید میں اللہ پاک نے ارشاد فرمایا:\nوَ مَاۤ اٰتٰىكُمُ الرَّسُوْلُ فَخُذُوْهُۗ-وَ مَا نَهٰىكُمْ عَنْهُ فَانْتَهُوْاۚ (پ ۲۸، الحشر:۷)\nترجمہ کنزالایمان: اور جو کچھ تمہیں رسول عطا فرمائیں وہ لو اور جس سے منع فرمائیں باز رہو۔\nنیز حدیث مبارک میں ہے کہ حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جس نے میری سنت سے مَحَبَّت کی اُس نے مجھ سے مَحَبَّت کی اور جس نے مجھ سے مَحَبَّت کی وہ جنت میں میرے ساتھ ہو گا۔‘‘ (ابن عساکر، ۹/ ۳۴۳)\n¥ہدایت یافتہ خلفائے راشدین سے مراد:\n حدیث پاک کے جز ’’ہدایت یافتہ خلفائے راشدین‘‘ سے مراد حضرت سیِّدُنا ابوبکر صدیق، حضرت سیِّدُنا عمرفاروق اعظم، حضرت سیِّدُنا عثمان غنی اور حضرت سیِّدُنا علی المرتضیٰ رضی اللہ عنہم ہیں۔ (شرح اربعین للنووی،ص۱۰۳)\n¥نئے کاموں سے بچو کہ ہربدعت گمراہی ہے:\nمفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’نئے کاموں سے بچو کہ ہر بدعت (نیا کام) گمراہی ہے‘‘ کے تحت فرماتے ہیں: یہاں نئی چیز سے مرادنئے عقیدے ہیں جو اسلام میں حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کے بعد ایجاد کیے جائیں، اس ‏لیے کہ یہاں اسے گمراہی کہا گیا۔ گمراہی عقیدہ میں ہوتی ہے نہ کہ اعمال میں، لہٰذایہ حدیث اپنے عموم پر ہے۔ چنانچہ قادیانی، چکڑالوی، رفض وخروج یہ تمام بدعات اور گمراہی ہیں اوراگر اس سے نئے اعمال مراد ‏لیے جائیں تو یہ حدیث عام مَخصُوص مِنہُ الْبَعْض ہے یعنی ہر بُری بدعت گمراہی ہے۔ بدعَتِ حسنہ کبھی مباح کبھی مستحب کبھی واجب اور کبھی فرض بھی ہوتی ہے۔ حدیث کی کتب اور قرآن کے پارے بدعت ہیں مگر اچھے ہیں۔(مراٰۃ المناجیح، 1/ 166)\n(نوٹ: بدعت کے متعلق تفصیلی کلام ’’حدیث نمبر05 ‘‘کے تحت ملاحظہ فرمائیں۔ )\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6894, "bookId": 13, "volNo": "1", "hadithNo": 29, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "بھلائی کے دروازے", "arabic": "عَنْ مُعَاذِ بْنِ جَبَلٍ رَضيَ اللهُ عَنْهُ قَالَ: قُلْتُ يَا رَسُوْلَ اللهِ صلّی اللہ علیہ وسلّم ! اَخْبِرْنِيْ بِعَمَلٍ يُّدْخِلُنِيَ الْجَنَّةَ وَيُبَاعِدُنِيْ مِنَ النَّارِ. قَالَ: ’’لَقَدْ سَاَلْتَ عَنْ عَظِيْـمٍ وَّاِنَّهٗ لَيَسِيْرٌ عَلٰى مَنْ يَسَّرَهُ اللهُ تَعَالٰى عَلَيْهِ؛ تَعْبُدُ اللهَ لَا تُشْرِكُ بِهٖ شَيْئًا وَّتُقِيْمُ الصَّلَاةَ وَتُؤْتِيَ الزَّكَاةَ وَتَصُوْمُ رَمَضَانَ وَتَحُجُّ الْبَـيْتَ.‘‘ ثُمَّ قَالَ: ’’اَلَااَدُلُّكَ عَلٰى اَبْوَابِ الْخَيْرِ؛ اَلصَّوْمُ جُنَّةٌ وَّالصَّدَقَةُ تُطْفِئُ الْخَطِيْئَةَ كَمَا يُطْفِئُ الْمَآءُ النَّارَ وَصَلَاةُ الرَّجُلِ مِنْ جَوْفِ اللَّيْلِ.‘‘ ثُمَّ تَلَا: ’’ تَتَجَافٰى جُنُوْبُهُمْ عَنِ الْمَضَاجِعِ ‘‘ حَتّٰی بَلَغَ ’’ یَعْمَلُوْنَ ‘‘. ثُمَّ قَالَ: ’’اَلَا اُخْبِرُكَ بِرَاْسِ الْاَمْرِ وَعَمُوْدِهٖ وَذِرْوَةِ سَنَامِهٖ؟‘‘ قُلْتُ: بَلٰى يَا رَسُوْلَ اللهِ صلّی اللہ علیہ وسلّم ! قَالَ: ’’رَاْسُ الْاَمْرِ اَلْاِسْلَامُ وَعَمُوْدُهٗ اَلصَّلَاةُ وَذِرْوَةُ سَنَامِهٖ اَلْجِهَادُ.‘‘ ثُمَّ قَالَ: ’’اَلَا اُخْبِرُكَ بِمِلَاكِ ذٰلِكَ كُلِّهٖ؟‘‘ قُلْتُ:بَلٰى يَا رَسُوْلَ اللهِ صلّی اللہ علیہ وسلّم !. فَاَخَذَ بِلِسَانِهٖ. ثُمَّ قَالَ: ’’ كُفَّ عَلَيْكَ هٰذَا.‘‘ قُلْتُ :يَا نَبِيَّ اللهِ! وَاِنَّا لَمُؤَاخَذُوْنَ بِمَا نَتَكَلَّمُ بِهٖ؟ فَقَالَ: ’’ثَكِلَتْكَ اُمُّكَ؛ وَهَلْ يَكُبُّ النَّاسَ فِيْ النَّارِ عَلٰى وُجُوهِهِمْ. اَوْ قَالَ: عَلٰى مَنَاخِرِهِمْ اِلَّا حَصَائِدُ اَلْسِنَتِهِمْ.‘‘\n(رَوَاهُ التِّرْمِذِیُّ وَقَالَ: حَدِيْثٌ حَسَنٌ صَحِيْحٌ)", "urdu": "حضرت سیِّدُنا معاذ بن جبل رضی اللہ عنہ بیان کرتے ہیں کہ میں نے بارگاہِ رسالت میں عرض کی: یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! مجھے ایسے عمل کے بارے میں بتائیے جو مجھے جنت میں داخل کردے اور آگ (جہنم) سے دور کردے۔ اللہ پاک کے آخری نبی صلّی اللہ علیہ والہ وسلّم نے ارشاد فرمایا:’’تم نے بہت بڑی بات کے بارے میں پوچھا ہے بےشک وہ اسی پر آسان ہے جس کے لئے اللہ پاک آسان فرمادے۔ (وہ یہ ہے)تم اللہ پاک کی عبادت اس طرح کرو کہ کسی کو بھی اس کا شریک نہ ٹھہراؤ ، نماز قائم کرو، زکوٰۃ ادا کرو، رمضان کے روزے رکھو اور بَیْتُ اللہ کا حج کرو۔‘‘ پھر ارشاد فرمایا: ’’کیا میں بھلائی کے دروازوں کی طرف تمہاری راہ نمائی نہ کروں؟ روزہ ڈھال ہے اور صدقہ خطاؤں کو ایسے مٹادیتا ہے جیسے پانی آگ کو بجھا دیتا ہے اور بندے کا رات کے درمیانی حصہ میں نماز پڑھنا۔‘‘ پھر آپ صلّی اللہ علیہ والہ وسلّم نے یہ آیات مبارکہ تلاوت فرمائیں:\nتَتَجَافٰى جُنُوْبُهُمْ عَنِ الْمَضَاجِعِ یَدْعُوْنَ رَبَّهُمْ خَوْفًا وَّ طَمَعًا٘-وَّ مِمَّا رَزَقْنٰهُمْ یُنْفِقُوْنَ(۱۶) فَلَا تَعْلَمُ نَفْسٌ مَّاۤ اُخْفِیَ لَهُمْ مِّنْ قُرَّةِ اَعْیُنٍۚ-جَزَآءًۢ بِمَا كَانُوْا یَعْمَلُوْنَ(۱۷) (پ ۲۱، السجدة:۱۶، ۱۷)\nترجمہ کنزالایمان: ان کی کروٹیں جدا ہوتی ہیں خواب گاہوں سے اور اپنے رب کو پکارتے ہیں ڈرتے اور امید کرتے اور ہمارے دیئے ہوئے میں سے کچھ خیرات کرتے ہیں تو کسی جی کو نہیں معلوم جو آنکھ کی ٹھنڈک ان کے لئے چھپا رکھی ہے صلہ اُن کے کاموں کا۔\n پھر ارشاد فرمایا: ’’کیا میں تمہیں معاملے (یعنی دین)کی اصل، اس کے ستون اور اس کی بلندی کے بارے میں نہ بتاؤں؟‘‘ میں نے عرض کی: یارسولَ اللہ صلّی اللہ علیہ والہ وسلّم! کیوں نہیں (ضرور بتائیے)۔ ارشادفرمایا: ’’معاملے کی اصل اسلام، اس کا ستون نماز اور اس کی بلندی جہاد ہے۔‘‘ پھر ارشاد فرمایا: ’’کیا میں تمہیں ان سب کی اصل کے بارے میں نہ بتاؤں؟‘‘ میں نے عرض کی: یارسولَ اللہ صلّی اللہ علیہ والہ وسلّم! کیوں نہیں۔ آپ نے اپنی زبان مبارک پکڑ کر ارشاد فرمایا: ’’اسے قابو میں رکھو۔‘‘ میں نے عرض کی: یارسولَ اللہ صلّی اللہ علیہ والہ وسلّم! کیا گفتگو پر بھی ہماری پکڑ ہوگی؟ ارشاد فرمایا: ’’اے معاذ! تیری ماں تجھے روئے! لوگوں کو ان کے منہ کے بل یا فرمایا ان کے نتھنوں کے بل ان کی زبانوں کی کھیتی ہی جہنم میں گرائے گی۔‘‘ (ترمذی، كتاب الايمان عن رسول الله ، باب ما جاء فی حرمة الصلاة، ۴/۲۸۰، حدیث: ۲۶۲۵)\n (اس حدیث کو حضرت سیِّدُنا امام محمد بن عیسیٰ ترمذی رحمۃ اللہ علیہنے (جامع ترمذی میں) روایت کیا اور فرمایا: یہ حدیث حسن صحیح ہے۔)", "roman": "Hazrat Sayyiduna Mu'az bin Jabal Radiyallahu Anhu bayan karte hain ke main ne bargah-e-Risalat mein arz ki: Ya Rasoolullah Sallallahu Alaihi wa Sallam! Mujhe aise a'mal ke baare mein bataiye jo mujhe Jannat mein dakhil karde aur aag (Jahannam) se door karde. Allah Paak ke aakhri Nabi Sallallahu Alaihi wa Sallam ne irshad farmaya: 'Tum ne bohat bari baat ke baare mein poocha hai beshak woh isi par aasaan hai jis ke liye Allah Paak aasaan farmade. (Woh yeh hai) tum Allah Paak ki ibadat is tarah karo ke kisi ko bhi is ka shareek na thahrao, Namaz qaim karo, Zakat ada karo, Ramazan ke Roza rakho aur Baitullah ka Hajj karo.' Phir irshad farmaya: 'Kya main bhalai ke darwazon ki taraf tumhari rahnumai na karoon? Roza dhaal hai aur Sadaqah khataon ko aise mita deta hai jaise paani aag ko bujha deta hai aur bande ka raat ke darmiyani hissa mein Namaz parhna.' Phir Aap Sallallahu Alaihi wa Sallam ne yeh aayat-e-mubaraka tilawat farmayin: 'Tatajafa junubuhum anil-madaji'i yad'oona Rabbahum khaufan wa tama'an wa mimma razaqnahum yunfiqun. Fala ta'lamu nafsun ma ukhfiya lahum min qurrati a'yunin jaza'an bima kanu ya'malun.' (P 21, As-Sajdah: 16, 17). Tarjuma Kanz-ul-Iman: Un ki karwatein juda hoti hain khwab-gahon se aur apne Rabb ko pukarte hain darte aur umeed karte aur hamare diye hue mein se kuch khairat karte hain to kisi jee ko nahi maloom jo aankh ki thandak un ke liye chupa rakhi hai sila un ke kaamon ka. Phir irshad farmaya: 'Kya main tumhein mu'amle (yani Deen) ki asal, is ke sutoon aur is ki bulandi ke baare mein na bataoon?' Main ne arz ki: Ya Rasoolullah Sallallahu Alaihi wa Sallam! Kyun nahi (zaroor bataiye). Irshad farmaya: 'Mu'amle ki asal Islam, is ka sutoon Namaz aur is ki bulandi Jihad hai.' Phir irshad farmaya: 'Kya main tumhein in sab ki asal ke baare mein na bataoon?' Main ne arz ki: Ya Rasoolullah Sallallahu Alaihi wa Sallam! Kyun nahi. Aap ne apni zaban-e-mubarak pakar kar irshad farmaya: 'Ise qaboo mein rakho.' Main ne arz ki: Ya Rasoolullah Sallallahu Alaihi wa Sallam! Kya guftagu par bhi hamari pakar hogi? Irshad farmaya: 'Ae Mu'az! Teri maa tujhe roye! Logon ko un ke munh ke bal ya farmaya un ke nathnon ke bal un ki zabanon ki kheti hi Jahannam mein giraye gi.' (Tirmizi, Kitaab-ul-Iman an Rasoolillah, Baab ma ja'a fi hurmati-s-Salah, 4/280, Hadees: 2625). (Is Hadees ko Hazrat Sayyiduna Imam Muhammad bin Isa Tirmizi Rahmatullah Alayh ne (Jami' Tirmizi mein) riwayat kiya aur farmaya: Yeh Hadees Hasan Saheeh hai.)", "explanation": "¥مراٰۃ المناجیح سے حدیث شریف کی شرح:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کی شرح کرتے ہوئے فرماتے ہیں: ’’ایسے عمل کے بارے میں بتائیے جو جنت میں داخل اور جہنم سے دور کر دے‘‘یہ اسناد مجازی ہے جنت دینا، دوزخ سے بچانا رب (کریم) کا کام ہے۔چونکہ عمل اس کا ذریعہ ہے اس لیے اسے فاعل قرار دیا گیا، لہٰذا یہ کہہ سکتے ہیں کہ حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) جنت دیتے ہیں،دوزخ سے بچاتے ہیں،ہمارے اعمال سے حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کا توسل (وسیلہ) زیادہ قوی ذریعہ ہے (جنت میں داخلے کا)۔ ’’تم نے بڑی چیز کے بارے میں پوچھا ہے‘‘کیونکہ آگ (جہنم) سے بچنا جنت میں پہنچنا بڑی نعمتیں ہیں تو ان کا ذریعہ بھی بڑا ہی ہوگا۔ ’’یہ اسی پر آسان ہے جس پر اللہ پاک آسان کر دے‘‘ (یعنی) یہ ذریعہ بتانا مجھ کو آسان ہے کہ رب (کریم) نے مجھ کو ہر شے پر مطلع کیا ہے یا وہ اعمال اسی پر آسان ہوں گے جس پر اللہ (پاک) کرم کرے۔ ڈھیلا خود نیچے گرتا ہے کسی کے اٹھائے سے اوپر ہوتا ہے،ہماری پیدائش مٹی سے ہے ہمارا بھی یہی حال ہے۔ ’’ تم اللہ پاک کی عبادت کرو‘‘یعنی اسلام لاؤ جو ساری عبادتوں کی جڑ ہے کیونکہ عبادات کا ذکر تو آگے آرہا ہے۔ ’’ کسی کو بھی اس کا شریک نہ ٹھہراؤ ، نماز قائم کرو، زکوٰۃ ادا کرو، رمضان کے روزے رکھو اور بَیْتُ اللہ کا حج کرو ‘‘ اس طرح کہ نماز روزانہ پانچ وقت،روزہ ہرسال رمضان میں،زکوٰۃ ہر سال اگر مال ہو، حج عمر میں ایک مرتبہ۔ظاہر یہ ہے کہ یہاں صرف فرائض مراد ہیں جن پر جنتی ہونا موقوف ہے۔ ’’ کیا میں بھلائی کے دروازوں کی طرف تمہاری راہ نمائی نہ کروں؟ ‘‘ کی شرح میں فرماتے ہیں: یعنی وہ نیک اعمال جو بہت سی نیکیوں کا ذریعہ ہیں جیسے روزہ نفس توڑنے کا ذریعہ ہے نفس ٹوٹ جانے پر انسان بہت سی نیکیاں کرسکتا ہے۔کیونکہ روکنے والا نفس ہی ہے۔ ’’روزہ ڈھال ہے‘‘جس کی برکت سے روزہ دار تک گناہوں کا تیر نہیں پہنچتا اور شیطان کا راستہ بند ہوجاتا ہے۔ ’’ صدقہ خطاؤں کو ایسے مٹادیتا ہے جیسے پانی آگ کو بجھا دیتا ہے ‘‘ چونکہ خیرات میں اللہ (پاک) کی عبادت بھی ہے اور بندوں کا نفع بھی،غریبوں کی حاجت روائی بھی،اس لئے کہ یہ گناہوں کو مٹانے میں اکسیر ہے،جو بندوں پر مہربان ہو رب (کریم) اس پر مہربان ہوتا ہے۔ ’’بندے کا رات کے درمیانی حصہ میں نماز پڑھنا ‘‘ یعنی نماز تہجد،نمازپنجگانہ کے بعد یہ نماز بہت اعلیٰ ہے اور نمازوں میں اطاعت غالب ہے اس نماز میں عشق،نیز یہ نماز رب (کریم) نے خاص حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کے لیے بھیجی،حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کے طفیل سے ہمیں ملی۔ (اللہ پاک قرآنِ مجید میں ارشاد)فرماتا ہے: فَتَهَجَّدْ بِهٖ نَافِلَةً لَّكَ (پ۱۵، بنی اسرائیل:۷۹، ترجمہ کنز الایمان: تہجد کرو یہ خاص تمہارے لئے زیادہ ہے) ۔ ’’ ان کی کروٹیں جدا ہوتی ہیں خواب گاہوں سے ‘‘یعنی عشاء کے بعد کچھ سولیتے ہیں،پھر اٹھ کر تہجد پڑھتے ہیں،تہجد کے لیے پہلے سولینا شرط ہے ورنہ بستروں کا ذکر نہ ہوتا،بعدِ تہجد بھی سونا سنت ہے،یہ بھی اسی آیت سے ثابت ہے یعنی بستر بچھے ہوتے ہیں مگر وہ مصلے پر ہوتے ہیں۔ ’’ معاملے (یعنی دین)کی اصل، اس کے ستون اور اس کی بلندی کے بارے میں نہ بتاؤں؟ ‘‘یہاں دین کو اونٹ سے تشبیہ دی گئی،پھر اس کے لیے سر پاؤں اور کوہان ثابت کیا گیا جیسا استعارہ بالکنایہ اور تخلیل میں ہوتا ہے۔ ’’عرض کی: یارسولَ اللہ صلّی اللہ علیہ والہ وسلّم! کیوں نہیں (ضرور بتائیے) ‘‘ یہ سوال جواب سائل کو شوق دلانے کے لئے ہیں کیونکہ انتظار کے بعد جو شے حاصل ہو خوب یاد رہتی ہے۔ ’’معاملے کی اصل اسلام، اس کا ستون نمازاور بلندی جہادہے ‘‘چیز سے مراد دین ہے۔دینداری اسلام کے بغیر نہیں قائم رہ سکتی،جیسے سر کے بغیر زندگی اور نماز سے دین کو قوت و بلندی ہے،جیسے ستون سے چھت کی۔ جہاد چونکہ دشوار ہے اور جہاد ہی سے دین کی زینت و رونق ہے،جیسے کوہان سے اونٹ کی زینت اور کوہان تک پہنچنا کچھ مشکل بھی ہوتا ہے۔جہاد بمعنی مشقت ہے یہ لِسان، سنان، اقلام (یعنی زبان، تلوار، قلم) سبھی سے ہوتا ہے،کافروں پر جہا د سہل (یعنی کافروں سے لڑنا آسان)ہے مگر اپنے نفس پر مشکل یہ کلمہ سب جہادوں کو شامل ہے۔ ’’کیا میں تمہیں ان سب کی اصل کے بارے میں نہ بتاؤں؟ ‘‘ملاک (اصل) وہ ہے جس سے کسی چیز کا نظام اور قوام قائم ہو،یعنی اصْلِ اصول۔ ’’ اپنی زبان مبارک پکڑ کر فرمایا:اسے قابو میں رکھو ‘‘ کہ پہلے تو لو بعد میں بولو،زبان کو لگام دو،رب (کریم) نے چھونے کے لیے دو ہاتھ،چلنے کے لیے دو پاؤں،دیکھنے کے لیے دو آنکھیں،سننے کے لیے دو کان دیئے،مگر بولنے کے لیے زبان صرف ایک ہی دی کہ کلام کم کرو کام زیادہ۔ ’’ کیا گفتگو پر بھی ہماری پکڑ ہوگی؟ ‘‘یعنی بات تو معمولی چیز ہے۔اس پر کیا پکڑ چوری،زنا،قتل وغیرہ جرم قابل گرفت ہیں مگر وہ زبان سے نہیں ہوتے۔ ’’ اے معاذ! تیری ماں تجھے روئے! ‘‘عرب میں یہ لفظ(ماں روئے)محبت و پیار میں بھی کہا جاتا ہے۔جیسے بچوں سے مائیں پیار میں کہتی ہیں:اے رُڑجانئیں،اڈپڈ جانئیں اردو میں مارے ہتیارے،ارے مٹ گئے وغیرہ یعنی توگم جائے یا مرجائے اور ماں تجھے رو رو کر ڈھونڈ ے یا یاد کرے۔ ’’ لوگوں کو ان کے منہ کے بل یا فرمایا ان کے نتھنوں کے بل ان کی زبانوں کی کھیتی ہی جہنم میں گرائے گی ‘‘کیونکہ ہاتھ پاؤں سے اکثر گناہ ہی ہوتے ہیں۔مگر زبان سے کفر، شرک، غیبت، چغلی، بہتان سب کچھ ہوتے ہیں جو دوزخ میں ذلت و خواری کے ساتھ پھینکے جانے کا ذریعہ ہیں۔ حصائد وہ جگہ ہے جہاں کھیت کا ٹ کر رکھا جاتا ہے یعنی کھلیان یا کٹوتی انسان کا ہر لفظ نامَۂ اعمال میں لکھا جاتا ہے۔وہ دفتر گویا اس کا کھلیان ہے۔ (مراٰۃ المناجیح، 1/51 تا 53)¥\nخیال رہے! مذکورہ حدیث شریف کے بعض اجزا (جیسے نماز، روزہ، زکوٰۃ، حج وغیرہ) کی تفصیلاً شرح ما قبل میں مختلف احادیث کی شرح میں گزر چکی ہے۔ جبکہ بعض اجزا (جیسےشرک، جہاد اور صلاۃ اللیل یعنی نفل نماز وغیرہ)کی شرح نہیں ہوئی، لہٰذا ان کی کچھ تفصیل ووضاحت یہاں کی جاتی ہے۔ چنانچہ\nحدیث پاک میں جنت میں داخلے اور جہنم سے بچنے کا سبب یہ بیان ہوا کہ ’’اللہ پاک کی عبادت اس طرح کرو کہ کسی کو اس کا شریک نہ ٹھہراؤ‘‘ یعنی شرک سے بچو۔ \n¥شرک کی تعریف ووضاحت:\nشرک کی تعریف یہ ہے کہ اللہ پاک کے سوا کسی غیر کو واجِبُ الْوُجُود (یعنی ایسی ذات سمجھنا جو خود سے ہو کسی دوسرے نے اس کو بنایا نہ ہو ، اور اس کی وجہ سے باقی سب ہوں، ) یا اللہ پاک کے کے سوا کسی دوسرے کو لائِقِ عبادت سمجھا جائے۔ حضرت سیِّدُنا علامہ سعْدُ الدین تفتازانی رحمۃُ اللہ علیہ نے شرک کی حقیقت ان الفاظ میں بیان فرمائی ہے: ’’اَلْاِشْترَاکُ ھُوَاِثْبَاتُ الشَّرِیْکِ فِی الْاُلُوْہِیَّۃِ بِمَعْنٰی وُجُوْبِ الْوُجُوْدِکَمَا لِلْمَجُوْسِ اَوْ بِمَعْنَی اِسْتِحْقَاقِ الْعِبَادَۃِ کَمَا لِعَبَدَۃِ الْاَصْنَامِیعنی شرک یہ ہے کہ خدا کی اُلُوہیت (یعنی معبود ہونے) میں کسی کو شریک کرنا اس طرح کہ کسی کو واجِبُ الوجود مان لینا جیسا کہ مجوسیوں کا عقیدہ ہے یا خدا کے سوا کسی کو عبادت کا حق دار مان لینا جیسا کہ بت پرستوں کا خیا ل ہے۔‘‘( شرح عقائد نسفیہ، اللّٰہ تعالٰی خالق لافعال العباد، ص ۲۰۳)\n سیِّدِی اعلیٰ حضرت امام اہل سنت مولانا شاہ امام احمد رضا خان فاضل بریلوی رحمۃُ اللہ علیہ فرماتے ہیں: ’’آدمی حقیقۃً کسی بات سے مشرک نہیں ہوتا جب تک غیْرِخدا کو معبود یا مستقل بالذّات و واجِبُ الْوُجُود نہ جانے ۔‘‘ (فتاوی رضویہ، 21/ 131)\n¥کفر کی سب سے بدترین قسم:\n بہارِ شریعت میں ہے کہ شرک کا معنیٰ ہے: اللہ پاک کے سوا کسی کو واجِبُ الْوُجُود یا مستحق عبادت (کسی کو عبادت کے لائق )جاننا یعنی اُلُوْہِیَّت میں دوسرے کو شریک کرنا اور یہ کفر کی سب سے بدترین قسم ہے۔ اس کے سوا کوئی بات کیسی ہی شدید کفر ہو حقیقۃً شرک نہیں۔ (بہار شریعت، حصہ1، 1/ 183، ملخصاً)\n¥شرک کیا ہے؟\nشرک اَکْبَرُ الکبائر یعنی تمام بڑے بڑے گناہوں میں سب سے زیادہ بڑا گناہ ہے۔ اِس کے بارے میں اللہ پاک نے قرآن مجید میں ارشاد فرمایا:\nاِنَّ اللّٰهَ لَا یَغْفِرُ اَنْ یُّشْرَكَ بِهٖ وَ یَغْفِرُ مَا دُوْنَ ذٰلِكَ لِمَنْ یَّشَآءُۚ-وَ مَنْ یُّشْرِكْ بِاللّٰهِ فَقَدِ افْتَرٰۤى اِثْمًا عَظِیْمًا(۴۸) (پ ۵، النسآء:۴۸)\nترجمہ کنزالایمان: بےشک اللہ اسے نہیں بخشتا کہ اس کے ساتھ کفر کیا جائے اور کفر سے نیچے جو کچھ ہے جسے چاہے معاف فرما دیتا ہے اور جس نے خدا کا شریک ٹھہرایا اس نے بڑے گناہ کا طوفان باندھا۔\nاسی طرح دوسری آیت میں ارشاد فرمایا :\nاِنَّ اللّٰهَ لَا یَغْفِرُ اَنْ یُّشْرَكَ بِهٖ وَ یَغْفِرُ مَا دُوْنَ ذٰلِكَ لِمَنْ یَّشَآءُؕ-وَ مَنْ یُّشْرِكْ بِاللّٰهِ فَقَدْ ضَلَّ ضَلٰلًۢا بَعِیْدًا(۱۱۶) (پ ۵، النسآء:۱۱۶)\nترجمہ کنزالایمان: اللہ اسے نہیں بخشتا کہ اس کا کوئی شریک ٹھہرایا جائے اور اس سے نیچے جو کچھ ہے جسے چاہے معاف فرما دیتا ہے اور جو اللہ کا شریک ٹھہرائے وہ دور کی گمراہی میں پڑا ۔\n شرک (وکفر)کے بارے میں ا للہ پاک کا اعلان ہے کہ وہ اِس گناہ کو کبھی بھی نہ بخشے گا۔ باقی شرک وکفر کے سوا دوسرے تمام گناہوں کو جس کے لئے چاہے گا بخش دے گا اور مشرک ہمیشہ ہمیشہ کے لئے ضرور جہنم میں جائے گا۔ مشرک کی کوئی عبادت مقبول نہیں۔ بلکہ عمر بھر کی عبادت شرک کرنے سے غارت و برباد ہو جاتی ہے۔ چنانچہ قرآن مجید میں ارشاد ہوتا ہے:\nلَىٕنْ اَشْرَكْتَ لَیَحْبَطَنَّ عَمَلُكَ (پ ۲۴، الزمر:۶۵)\nترجمہ کنزالایمان: کہ اے سننے والے اگر تو نے اللہ کا شریک کیا تو ضرور تیرا سب کیا دھرا اکارت جائے گا۔\n¥سب سے بڑا گناہ:\nسیِّدُنا ابن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ ایک شخص نے بارگاہِ رسالت میں عرض کی: کون سا گناہ اللہ پاک کے نزدیک سب سے زیادہ بڑا ہے؟ تو حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا : ’’یہ کہ تم اللہ پاک کے لئے کوئی شریک ٹھہراؤ حالانکہ ا ُسی نے تم کو پیدا کیا ہے۔‘‘ (بخاری، کتاب التوحید، باب قول اللّٰہ :یاایھاالرسول...الخ، ۴/ ۵۸۸، حدیث:۷۵۳۲)\n اِن کے علاوہ دو سری بہت سی آیات اور حدیثیں بھی شرک کی ممانعت میں وارد ہوئی ہیں، لہٰذا جہنم کے عذا ب سے بچنے کے لئے شرک سے بچنا انتہائی ضروری ہے۔\n¥شرک کی دو ہی صورتیں ہیں:\nحضرت سیِّدُنا علامہ سعْدُ الدین تفتازانی رحمۃُ اللہ علیہ نے شرک کی جو تعریف بیان فرمائی ہے اس میں فیصلہ کر دیا کہ شرک کی دوہی صورتیں ہیں: ایک یہ کہ اللہ پاک کے سوا کسی کو واجِبُ الْوُجُود مانا جائے۔ دوسری یہ کہ اللہ پاک کے سوا کسی کو عبادت کے لائق مان لیا جائے۔\nآئیے شرک کی مذکورہ تعریف کو پیش نظر رکھ کر مندرجہ ذیل چیزوں اور کاموں کو دیکھتے ہیں جنہیں بعض لوگ شرک کا نام دیتے ہیں حالانکہ یہ کسی بھی طرح شرک نہیں ہیں۔ چنانچہ\n¥کون کون سی چیزیں شرک نہیں:\n(1)...انبیائے کرام علیہمُ السّلام اور اولیائے عظام رحمۃُ اللہ علیہم کو محبت سے پکارنا یعنی یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ، یا غوث رحمۃُ اللہ علیہ کہنا۔(2)... بزرگوں سے مدد طلب کرنا ۔(3)... بزرگوں کے مزاروں پر چادر اور پھول وغیرہ ڈالنا۔ (4)... فاتحہ پڑھنا اور ایصال ثواب کرنا۔(5)...بزرگوں کو اللہ پاک کی بارگاہ میں وسیلہ بنا نا۔ (6)... بزرگوں کے مزاروں کے سامنے مراقبہ کرنا۔(7)... بزرگوں کے مزاروں کا ادب کرنا۔(8)... بزرگوں کی فاتحہ کے کھانوں اور مٹھائیوں کو تبرک سمجھ کر کھانا،جو نہ صرف ہندوستان بلکہ دنیا بھر میں سُنّی مسلمانوں کا دستور و طریقہ ہے۔\n یہ ہرگز ہر گز شرک نہیں کیوں کہ کوئی مسلمان بھی انبیائے کرام علیہمُ السّلام، اولیائے عظام رحمۃُ اللہ علیہم اور دوسرے بزرگوں کو واجِبُ الْوُجُود یا لائق عبادت نہیں مانتا ہے،بلکہ تمام مسلمان اِن بزرگوں کو اللہ پاک کا بندہ مان کر اِن کی تعظیم کرتے ہیں تا کہ اللہ پاک اپنے محبوبوں کی تعظیم سے خوش ہو جائے، لہٰذا سنیوں کے یہ اعمال ہر گز ہر گز شرک نہیں ہو سکتے۔ البتہ! جو جاہل لوگ قبروں کو سجدہ کرتے ہیں اگر وہ لوگ اِن بزرگوں کو قابلِ عبادت سمجھ کر سجدہ کریں تو یہ کھلا شرک ہو گا اور اگر اِن بزرگوں کی تعظیم کے لئے سجدہ کریں تویہ اگرچہ شرک نہیں ہوگا مگر ناجائز و حرام اور بہت سخت گناہ ہوگا، لہٰذا مسلمان کو قبروں کے سجدہ سے خود بھی بچنا چاہیے اور دوسروں کو بھی روکنا چاہیے۔خاص کر خانقاہوں کے سجادہ نشین اور مزاروں کے مجاورین حضرات کا فرض ہے کہ وہ قبروں پر سجدہ کرنے والے جاہل زائرین کو قبروں کو سجدہ کرنے سے روکیں اور خلافِ شرع حرکت کرنے والے زائرین جو باز نہیں آتے ان کو خانقاہوں اور مزاروں سے باہر کر دیں۔ ورنہ استطاعت ہونے کے باوجود نہ روکنے پر وہ بھی گنہگار ہوں گے اور قہر قہار و غضب جبار میں گرفتار ہو کر عذاب نار کے حق دار ٹھہریں گے ۔(جہنم کے خطرات، ص22 تا25، ملخصاً)\n¥صلاۃُ اللیل (رات کی نماز)¥کے فضائل:\nوَ الَّذِیْنَ یَبِیْتُوْنَ لِرَبِّهِمْ سُجَّدًا وَّ قِیَامًا(۶۴) (پ ۱۹، الفرقان:۶۴)\nترجمہ کنزالایمان: اور وہ جو رات کاٹتے ہیں اپنے رب کے لیے سجدے اور قیام میں۔\n حضرت سیِّدُنا ابو مالک اشعری رضی اللہ عنہ سے روایت ہے کہ رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بےشک جنت میں کچھ ایسے محلات ہیں جن میں آرپار (اندر کا منظر باہر سے اور باہر کا اندر سے) نظر آتاہے، اللہ پاک نے وہ محلات ان لوگوں کے لئے تیار کئے ہیں جو (محتاجوں کو) کھانا کھلاتے، سلام کو عام کرتے اور رات کو جب لوگ سورہے ہوں تو نماز پڑھتے ہیں۔‘‘ (ابن حبا ن، کتا ب البر والاحسان، ۱/ ۳۶۳، حدیث:۵۰۹)\n سیِّدُنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے بارگاہِ رسالت میں عرض کی: مجھے کوئی ایسا کام ارشاد فرمائیے جسے میں اختیار کرو ں تو جنت میں داخل ہو جاؤں ۔ آپ نےارشاد فرمایا: ’’سلام کو عام کرو، کھانا کھلاؤ، رشتہ داروں سے نیک سلوک کرو، رات میں نماز پڑھو جب لوگ سوتے ہوں توسلامتی کے ساتھ جنت میں داخل ہو جاؤ گے۔‘‘\n( مستدرک، کتاب الاطعمة، فضیلة اطعام الطعام، ۵ / ۱۷۹، حدیث: ۷۲۵۶)\nحضرت سیِّدَتُنا اسماء بنت یزید رضی اللہ عنہا سے روایت ہے کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’قیامت کے دن تمام لوگ ایک ہی جگہ اکٹھے ہوں گے پھر ایک منادی ندا کرے گا کہ کہاں ہیں وہ لوگ جن کے پہلوبستروں سے جد ا رہتے تھے؟ پھر وہ لوگ کھڑے ہوں گے اوروہ تعداد میں بہت کم ہوں گے اور بغیر حساب جنت میں داخل ہوجائیں گے، پھرتمام لوگوں سے حساب شروع ہوگا۔‘‘ (الترغیب والترھیب، کتاب النوافل، باب الترغیب فی قیام اللیل، ۱/ ۲۴۰، حدیث:۹)\n¥نماز ِتہجد کے چند شرعی مسائل:\nتفسیر صراط الجنان، جلد5، صفحہ498 پرہے: (1) صَلَاۃُ اللَّیْل کی ایک قسم تہجد ہے کہ عشا کی نماز کے بعد رات میں سو کر اُٹھیں اور نوافل پڑھیں ، سونے سے قبل جو کچھ پڑھیں وہ تہجد نہیں ۔ (2) تہجد نفل کا نام ہے اگر کوئی عشا کے بعد سو گیا پھر اٹھ کر قضا نماز پڑھی تو اُس کو تہجد نہ کہیں گے۔ (3) کم سے کم تہجد کی دو رکعتیں ہیں اور حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم سے(عموماً) آٹھ تک ثابت ہیں۔ (4) جو شخص تہجد کا عادی ہو بلا عذر اُسے تہجد چھوڑنا مکروہ ہے کہ بخاری شریف کی حدیث میں ہے، حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے حضرت عبداللّٰہ بن عَمْرو رضی اللہ عنہما سے ارشاد فرمایا: ’’اے عبداللّٰہ! تو فلاں کی طرح نہ ہونا کہ رات میں اُٹھا کرتا تھا پھر چھوڑ دیا۔‘‘ ( بخاری، کتاب التھجد، باب ما یکرہ من ترک قیام اللیل لمن کان یقومہ، ۱/ ۳۹۰، حدیث:۱۱۵۲)\n¥جہاد کی تعریف اور مفہوم:\n جہاد کے لغوی معنیٰ: مشقت اٹھانے کے ہیں۔ اور شرعی معنیٰ : اعلاء کلمۃ اللہ (یعنی دین کی سربلندی) کےلئے کفار کے ساتھ قتال (جنگ)کی مشقت اٹھانے کے ہیں۔ نیز کبھی کبھی جہاد کے معنی ٰیہ بھی آتے ہیں کہ آدمی اللہ پاک کی رضا کے لئے اعمالِ شاقہ (مشکل اعمال) کرے اور نفس کو اس کی مرضی کے خلاف اعمالِ خیر (بھلائی کے کاموں) میں لگائے اور اسے ذلیل کرے۔\n(نزہۃ القاری،کتاب الجھاد، 4/41 )\n¥جہاد کا حکم،شرائط اور اقسام:\n جہاد فرض ہے، بلاوجہ جہاد نہ کرنے والا ایسا ہی گنہگار ہوگا جیسے نماز چھوڑنے والا بلکہ کئی صورتوں میں اِس سے بھی بڑھ کر ہے۔ البتہ یہ خیا ل رہے کہ جہاد کی فرضیت کی کچھ شرائط ہیں جن میں ایک اہم شرط اِستِطاعت یعنی جنگ کی طاقت ہونا بھی ہے۔ جہاد یہ نہیں ہے کہ طاقت ہو نہیں اور چند مسلمانوں کو لڑائی میں جھونک کر مروا دیا جائے۔ جہاد کبھی فرضِ عین ہوتا ہے اور کبھی فرضِ کِفایہ۔ (صراط الجنان، 2/ 251)\n¥اعلیٰ قسم کا جہاد:\n جہاد کی بہت سی قسمیں ہیں جن میں سے اعلیٰ قسم کا جہاد یہ ہے کہ مجاہد اپنی جان و مال سب کچھ راہ خدا میں خرچ کر کے جہاد کرے کیونکہ یہ جہاد نفس پر بہت گراں ہے۔خیال رہے کہ یہ افضلیت اضافی ہے۔ یعنی ایک اعتبار سے یہ جہاد افضل ہے اور ایک اعتبار سے خصوصی حالات میں ظالم حاکم کے سامنے حق بات کہہ دینی افضل ہے۔(مراٰۃ المناجیح، 5/ 440، ملخصاً)\n¥جہاد کی صورتیں:\n جہاد کی تین صورتیں ہیں: (1)...فقط جان سے جہاد کرنا۔ جیسے مَساکین کرتے تھے۔ (2)...فقط مال سے جہاد کرنا۔ جیسا کہ معذور مالدار مومن کا عمل کہ غازی کو گھوڑا وغیرہ دے دیتے تھے۔ (3)...جان و مال دونوں سے جہاد کرنا۔ جیساکہ غنی قادر مسلمان جو کہ دوسرے مسکین غازیوں کو سامان بھی دیتے اور خود بھی میدا ن میں جاتے تھے اور ان کے اپنے جانے پر بھی خرچہ ہوتا تھا۔ (صراط الجنان، 4/ 82)\n¥جن پر جہاد فرض نہیں:\nصراط الجنان، جلد4، صفحہ 205 پر موجود کلام کا خلاصہ ہے:جن پر سے جہاد کی فرضیت ساقط ہے، ان کے چند طبقے ہیں:پہلا طبقہ: ضعیف جیسے کہ بوڑھے،بچے، عورتیں اور وہ شخص بھی انہیں میں داخل ہے جو پیدائشی کمزور ضعیف ونحیف ہو۔دوسرا طبقہ: بیمار، اس میں اندھے ،لنگڑے، اپاہج بھی داخل ہیں۔ تیسرا طبقہ: وہ لوگ جنہیں خرچ کرنے کی قدرت نہ ہو اور سامانِ جہاد نہ کرسکیں یہ لوگ رہ جائیں تو ان پر کوئی گناہ نہیں۔ (تفسیرکبیر، التوبة، تحت الآیة: ۹۱، ۶/ ۱۲۱) \n¥افضل کون؟\n حضرت سیِّدُنا ابوسعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ بارگاہِ رسالت میں عرض کی گئی: کون شخص افضل ہے؟ آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’وہ مومن جو اللہ پاک کی راہ میں اپنی جان اور مال کے ساتھ جہاد کرے۔‘‘\n (بخاری، کتاب الجھاد، باب افضل الناس مؤمن یجاھد...الخ ، ۲/ ۲۴۹، حدیث:۲۷۸۶)\n¥حقیقی مجاہد کون؟\n مجاہد وہ ہے جس نے اطاعَتِ خداوندی کے معاملے میں اپنے نفس کے ساتھ جہاد کیا۔‘‘(مستدرک، کتاب الایمان، تعریف اکمل المؤمنین، ۱/ ۱۵۸، حدیث:۲۴) اور حضرت سیِّدُنا فضالہ بن عُبَیْد رضی اللہ عنہ سے مروی روایت میں ہے کہ اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’مجاہد وہ ہے جو اللہ پاک کی فرمانبرداری میں اپنے نفس سے لڑتا ہے۔‘‘ ( مسند احمد، مسند فضالة بن عبید الانصاری، ۹ / ۲۴۹، حدیث: ۲۴۰۱۳)نیز حدیث پاک میں اسی کو سب سے بڑا جہاد کہا گیا ہے۔ چنانچہ \n¥افضل اور بڑا جہاد:\n حضرت سیِّدُنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ کچھ لوگ جہاد سے واپسی پر بارگاہِ رسالت میں حاضر ہوئے تو آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’تم آگئے، خوش آمدید! اور تم چھوٹے جہاد سے بڑے جہاد کی طرف آئے ہو۔‘‘انہوں نے عرض کی:بڑا جہاد کیا ہے؟ارشاد فرمایا: ’’بندے کا اپنی خواہشوں سے جہاد کرنا۔‘‘ \n(الزھد الکبیر للبیھقی، فصل فی ترک الدنیا ومخالفة النفس والھوی، ص۱۶۵، حدیث: ۳۷۳)\nحضرت سیِّدَتُنا اُمّ انس رضی اللہ عنہا بیان کرتی ہیں کہ میں نے بارگاہِ رسالت میں عرض کی: یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! مجھے کوئی نصیحت فرمائیے۔ آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشادفرمایا: ’’گناہوں کو چھوڑدو کہ یہ سب سے افضل ہجر ت ہے اور فرائض کی پابندی کیا کرو کہ یہ سب سے افضل جہاد ہے۔‘‘ (معجم کبیر، ۲۵/ ۱۲۹، حدیث:۳۱۳)\nنیز صحابَۂ کرام علیہمُ الرّضوان جب جہاد سے واپس آتے تو کہتے: ہم جہادِ اَصغر سے جہادِ اَکبر (یعنی چھوٹے جہاد سے بڑے جہاد) کی طرف لوٹ آئے ہیں۔ صحابَۂ کرام علیہمُ الرّضوان نے نفس، شیطان اور خواہشات سے جہاد کو کفار کے ساتھ جہاد کرنے سے بڑا اور عظیم جہاد اس لئے کہا کہ نفس سے جہاد ہمیشہ جاری رہتا ہے جبکہ کفار کے ساتھ کبھی کبھی ہوتا ہے۔ \n(مکاشفۃ القلوب، ص20)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6895, "bookId": 13, "volNo": "1", "hadithNo": 30, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "شرعی حدود کی پابندی کرو", "arabic": "عَنْ اَبِيْ ثَعْلَبَةَ الْخُشَنِيِّ جُرْثُوْمِ بْنِ نَاشِرٍ رَضيَ اللهُ عَنْهُ عَنْ رَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’اِنَّ اللهَ فَرَضَ فَرَائِضَ فَلَا تُضَيِّعُوْهَا وَحَدَّ حُدُوْدًا فَلَا تَعْتَدُوْهَا وَحَرَّمَ اَشْيَآءَ فَلا تَنْتَهِكُوْهَا وَسَكَتَ عَنْ اَشْيَاءَ رَحْمَةً لَّكُمْ غَيْرَ نِسْيَانٍ فَلَا تَبْحَثُوْا عَنْهَا.‘‘ (حَدِيْثٌ حَسَنٌ رَوَاهُ الدَّارَقُطْنِیُّ وَغَيْرُہٗ)", "urdu": "حضرت سیِّدُنا ابوثعلبہ خشنی جُرثوم بن ناشر رضی اللہ عنہ سے مروی ہے کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بےشک اللہ پاک نےکچھ چیزیں فرض فرمائی ہیں انہیں ضائع نہ کرو، کچھ حدود مقرر کی ہیں ان سے آگے نہ بڑھو، بعض چیزوں کو حرام کیا ہے ان کی حرمت کو پامال نہ کرو اور کچھ چیزوں کے بارے میں بغیر بھولے محض تم پر رحمت کرتے ہوئےخاموشی برتی ہے، لہٰذا ان کے بارے میں بحث نہ کرو۔‘‘ (دارقطنی، كتاب الرضاع، ۴/ ۲۱۷، حدیث:۴۳۵۰)\n(یہ حدیث حسن صحیح ہے اسے حضرت سیِّدُنا امام علی بن عمر دار قطنی رحمۃ اللہ علیہاور دیگر محدثین نے روایت کیا ہے۔)", "roman": "Hazrat Sayyiduna Abu Sa'laba Khushni Jurthum bin Nashir Radiyallahu Anhu se Marwi hai ke Rasoolullah Sallallahu Alaihi wa Sallam ne irshad farmaya: 'Beshak Allah Paak ne kuch cheezein Farz farmayi hain unhein zaya na karo, kuch hudood muqarrar ki hain un se aage na barho, ba'az cheezon ko Haram kiya hai un ki hurmat ko paamal na karo aur kuch cheezon ke baare mein baghair bhoole mahaz tum par Rahmat karte hue khamoshi barti hai, lihaza un ke baare mein behas na karo.' (Daraqutni, Kitaab-ur-Riza', 4/217, Hadees: 4350). (Yeh Hadees Hasan Saheeh hai ise Hazrat Sayyiduna Imam Ali bin Umar Daraqutni Rahmatullah Alayh aur deegar Muhaddiseen ne riwayat kiya hai.)", "explanation": "حكيم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’بےشک اللہ پاک نےکچھ چیزیں فرض فرمائی ہیں انہیں ضائع نہ کرو ‘‘ کے تحت فرماتے ہیں: فرض اعمال قرآن سے ثابت ہوں یا حدیث سے ان پر ضرور پابندی کرو، نیز اخلاص سے ادا کرو ۔ (مراٰۃ المناجیح، 1/ 185)¥\nفرائض پر عمل کرنے کی فضیلت:\nفرائض پر عمل کرنا دنیا وآخرت میں بےشمار فضائل وکمالات کا باعث ہے۔ چنانچہ حدیْثِ قُدسی ہے کہ اللہ پاک ارشاد فرماتا ہے: ’’میرا بندہ فرائض کی اَدائیگی کے ذریعے جتنا میرا قرب حاصل کرتا ہے اس کی مثل کسی دوسرے عمل سے حاصل نہیں کرتااورمیرا بندہ نوافل(کی کثرت) سے میرے قریب ہوتا رہتا ہے یہاں تک کہ میں اسے اپنا محبوب بنالیتا ہوں اورجب میں اسے محبوب بنالیتاہوں تو میں اس کےکان بن جاتا ہوں جن سے وہ سنتا ہے،اس کی آنکھیں ہوجاتا ہوں جن سے وہ دیکھتا ہے،اس کے ہاتھ بن جاتا ہوں جن سے وہ پکڑتا ہے،اس کے پاؤں ہو جاتا ہوں جن سے وہ چلتا ہے ۔ اگروہ مجھ سے مانگے تو میں اسے ضروردیتا ہوں اور اگر وہ مجھ سے پناہ طلب کرے تو میں اسے پناہ دیتا ہوں۔‘‘ \n(بخاری،کتاب الرقاق،باب التواضع، ۴/ ۲۴۸، حدیث:۶۵۰۲)\n ایک روایت میں ہے کہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے حضرت سیِّدَتُنا اُمِّ سلیم رضی اللہ عنہا سے ارشاد فرمایا: ’’فرائض کی پابندی کرو کیونکہ یہ سب سے افضل جہاد ہے۔‘‘ (معجم کبیر، ۲۵/ ۱۲۹، حدیث:۳۱۳)\n مسلمانوں کے تیسرے خلیفہ حضرت سیِّدُنا عثمانِ غنی رضی اللہ عنہ فرماتے ہیں کہ میں نے عبادت کی لذّت چار اَشیاء میں پائی: (1)... اللہ پاک کے فرائض کی ادائیگی میں۔ (2)... اللہ پاک کی حرام کی ہوئی چیزوں سے بچنے میں۔ (3)...اللہ پاک کی رِضا کے حُصول کی غرض سے نیکی کا حکم دینے میں اور (4)... اللہ پاک کے غَضَب سے محفوظ رہنے کے لئے بُرائی سے منع کرنے میں۔ (المنبّھات، ص۳۷)\n مروی ہے کہ ایک شخص نے حضرت سیِّدُنا حسن بصری رحمۃُ اللہ علیہ سے پوچھا: اے ابوسعید! ایمان کیا ہے؟ آپ نے فرمایا: ’’صبر اور سخاوت۔‘‘ اس نے عرض کی: صبر اور سخاوت کیا ہے؟ فرمایا: ’’ اللہ پاک کی نافرمانی سے باز رہنا صبر اور پابندی کے ساتھ فرائض پر عمل پیرا ہونا سخاوت ہے۔‘‘ (المجالسة وجواھر العلم، الجزء الثامن، ۱/ ۴۴۱، حدیث:۱۱۵۵)\nحضرت سیِّدُنا سہل بن عبد اللہ رحمۃُ اللہ علیہ فرماتے ہیں: اَلنَّجَاۃُ فِیْ ثَلَاثَۃٍ اَکْلُ الْحَلَالِ وَاَدَآءُ الْفَرَآئِض وَالْاِقْتِدَآءُ بِالنَّبِیِّ یعنی نجات تین چیزوں میں ہے: حلال کھانے، فرائض کی ادائیگی اور حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم کی پیروی کرنے میں۔(تفسیرقرطبی، البقرة، تحت الٓایة:۱۶۸، الجز الثانی، ۱/ ۱۵۹)\n یاد رہے جس طرح فرائض پر عمل کرنا دنیا وآخرت میں اجر وثواب کا باعث ہے وہیں فرائض کو ضائع کرنا دنیا وآخرت میں خسارے کا باعث ہے۔ چنانچہ حضرت سیِّدُنا عبد اللہ بن عبّاس رضی اللہ عنہما سے مَروی ہے کہ جس نے اللہ پاک کے فرائض کو ضائع کیا وہ اللہ پاک کی امان سے نکل گیا۔ (قوت القلوب، الفصل السابع والثلاثون فی تفصیل الاسلام...الخ، ۲/ ۲۱۴)\n حضرت یحییٰ بن معاذ رحمۃُ اللہ علیہ فرماتے ہیں: ”مجھے فرض کو چھوڑ کر فضائل کے درپے ہونے والے پر حیرانگی ہے کیونکہ جس کے ذمے کوئی قرض ہو وہ قرض خواہ کو اس کے قرض کے برابر بھی تحفہ دے ڈالے تو مدت پوری ہونے پر قرض خواہ قرض کی ادئیگی کے مطالبے میں حق بجانب ہوگا۔“(منھاج العارفین،ص۳۹)\n¥مقرر کردہ حدوں کو نہ توڑو:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’ کچھ حدود مقرر کی ہیں ان سے آگے نہ بڑھو، بعض چیزوں کو حرام کیا ہے ان کی حرمت کو پامال نہ کرو ‘‘ کے تحت فرماتے ہیں: اس طرح کے حرام کے قریب بھی نہ جاؤ کرنا تو کجا۔ حلال وحرام کی حدوں کو نہ توڑو، نمازیں پانچ فرض ہیں، چار یا چھ نہ مانو۔ زکوٰۃ مال کا (۴۰) چالیسواں حصہ فرض ہے، کم وبیش پر عقیدہ مت رکھو۔ چار عورتوں تک کا نکاح جائز پانچویں کو حلال چوتھی کو حرام نہ سمجھو وغیرہ۔ (مراٰۃ المناجیح، 1/ 185)\n¥حدود کی پاسداری کرو:\n حضرت سیِّدُنا علامہ ابن حجر ہیتمی رحمۃُ اللہ علیہ فرماتے ہیں: ’’اللہ پاک نے ہمارے لئے کچھ حدود مقرر کیں اور ہمیں ان سے تجاوز کرنے سے منع فرمایا تو ہم پر لازم ہے کہ ہم ان حدود کی پاسداری کریں اورانہیں اپنی رائے اور عقل کے ترازو میں نہ پرکھیں بلکہ ان کو ہر صورت میں قبول کر لیں خواہ ہماری عقل میں آئيں یا نہ آئيں کیونکہ یہی عبودیت وبندگی کا مرتبہ اور شان ہے کمزور وناتواں اور فہم و فراست سے قاصر بندے پر لازم ہے کہ اپنے مالک حقیقی کے احکام کے سامنے سر تسلیم خم کر دے کیونکہ جب بھی اس نے اپنی عقل کے مطابق فیصلہ کیا اور اپنے مالک کے حکم سے روگردانی کی تو اس نے اپنے شدید عذاب سے اس کو ہلاکت و بربادی کے عمیق گڑھے میں پھینک دیا۔ چنانچہ اللہ پاک ارشاد فرماتا ہے:’’ اِنَّ بَطْشَ رَبِّكَ لَشَدِیْدٌؕ(۱۲) (پ۳۰، البروج:۱۲)ترجمہ کنزالایمان:بے شک تیرے رب کی گرفت بہت سخت ہے۔ \n(الزواجر عن اقتراف الکبائر، کتاب البیع،۱/ ۴۸۶ملخصا) \n¥افضل اعمال:\nمسلمانوں کے دوسرے خلیفہ حضرت سیِّدُنا عمر فاروق اعظم رضی اللہ عنہ فرماتے ہیں کہ سب سے افضل اعمال فرائض ادا کرنا، اللہ پاک کی حرام کردہ اشیاء سے بچنا اور اللہ پاک کی بارگاہ میں نیتوں کو درست کرنا ہے۔\n(اتحاف السادة المتقین، کتاب النیةوالاخلاص والصدق، ۱۳/ ۱۹)\n حضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اللہ پاک غیور ہے اور مومن بھی غیرت مند ہے ، اللہ پاک کی غیرت اس بات پر ہے کہ بندۂ مومن اس کے حرام کردہ عمل میں پڑے۔‘‘ ( مسلم، کتاب التوبة، باب غیرة الله تعالٰی وتحریم الفواحش، ص۱۱۳۲، حدیث:۶۹۹۵)\n¥حرام کردہ چیزوں سے بچنے کی فضیلت:\nحضرت سیِّدنا اَنَس بن مالک رضی اللہ عنہ روایت کرتے ہیں کہ رسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشادفرمایا: ’’اللہ پاک کی حرام کردہ چیزوں سے بچنے اور اس کے احکامات پر عمل کرنے والے نوجوان سے ربِّ کریم ارشاد فرماتا ہے: تیرے لئے 70 صدِیقوں کے برابر ثواب ہے۔‘‘ (الترغیب فی فضائل الاعمال،باب فضل عبادة الشاب... الخ،ص۲۴۲ ،مختصراً)\n¥جن سے خاموشی برتی ان کے متعلق بحث نہ کرو:\nمفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’کچھ چیزوں کے بارے میں بغیر بھولے محض تم پر رحم کرتے ہوئےخاموشی برتی ہے، لہٰذا ان کے بارے میں بحث نہ کرو ‘‘ کے تحت فرماتے ہیں: یعنی بعض چیزوں کی حلت وحرمت صراحتاً قرآن یا حدیث میں مذکور نہیں ان کی بحث میں نہ پڑو وہ مباح ہیں عمل کئے جاؤ ان کے بارے میں رب فرماتا ہے: ’’ عَفَا اللّٰهُ عَنْهَاؕ ‘‘(پ۷، المآئدة:۱۰۱،ترجمہ کنزالایمان: اللہ انہیں معاف فرما چکا ہے۔) حضور (نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم ) فرماتے ہیں: جس سے خاموشی ہو وہ معاف ہے۔ (مراٰۃ المناجیح، 1/ 185)\n¥جن سے خاموشی فرمائی وہ معاف ہیں:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ اسی کی مثل مروی ایک حدیث شریف کے جز ’’اور جن سے خاموشی فرمائی وہ معاف ہیں‘‘ کے تحت فرماتے ہیں: خلاصہ یہ ہے کہ چیزیں تین قسم کی ہیں: وہ جن کا حلال ہونا قرآن یا حدیث میں صراحۃً مذکور ہے، وہ جن کا حرام ہونا قرآن یا حدیث میں صراحۃً مذکور ہے، وہ جن کا ذکر نہ قرآن میں ہے نہ حدیث میں،پہلی قسم حلالِ قطعی ہے، دوسری قسم حرام قطعی، تیسری قسم معاف یعنی وہ بھی حلال ہے۔اس حدیث سے معلوم ہوا کہ تمام چیزوں میں اصل اباحت ہے کہ جن سے سکوت یعنی خاموشی ہے وہ مباح ہے،(یہ) ا سلام کا کلیہ قانون ہے جس سے لاکھوں چیزوں کے حال معلوم ہوسکتے ہیں۔آم مالٹا وغیرہ کیوں حلال ہیں اس لیے کہ شریعت میں ان کی ممانعت نہیں آئی۔ خیال رہے کہ انسانی نباتات بھی کھانا ہے جیسے سبزیاں،دانے،کبھی جمادات بھی جیسے موتی عنبر،مشک وغیرہ حیوانات بھی۔نباتات و حیوانات کے لیے قاعدہ یہ ہے کہ جو سبزیاں یا دانہ صحت کو مضر ہو وہ حرام، جو مضر نہ ہو وہ حلال حتی کہ سنکھیا بھی مارکر کھایا جائے تو حلال۔حیوانات بعض حرام ہیں،بعض حلال،قرآن کریم نے حرام بعینہ صرف ایک جانور کا ذکر کیا یعنی سؤر کا وہ بھی اس کے گوشت کا ذکر فرمایا،باقی حرام لغیرہ میں آٹھ جانوروں کا ذکر فرمایا میتۃ منخنقۃ وغیرہ،باقی تمام حرام جانوروں کو حدیث پاک نے بیان فرمایا،کتا،بلی،ریچھ،ہاتھی،گدھا وغیرہ حضور انور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) نے ہی حرام کیے،سؤر کا صرف گوشت قرآن پاک نے حرام کیا،باقی اس کے کلیجی گردے،چربی حدیث نے حرام کی،پھر ان حرام جانوروں کی حرمت بعد ِ ہجرت قرآن پاک میں آئی۔مدنی سورتوں میں ہی حرام عورتوں،حرام غذاؤں کا ذکر ہے مگر حضور انور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) نے قبل ہجرت ہی ان سب سے مسلمانوں کو منع فرمادیا تھا،مسلمانوں کو کبھی ماں بہن سے نکاح اور سؤر کتا بلی کھانے کی اجازت نہ دی۔معلوم ہوا کہ حرام و حلال فرمانے والے حضور نبی کریم صلّی اللہ علیہ وسلّم ہیں۔ (مراٰۃ المناجیح، 5/ 681)\n¥ہرچیز میں اصل اباحت ہے:\n ہر چیز مباح اور جائز ہے جب تک اس کے عدم جواز یا تحریم پر کوئی دوسرا حکم نہ ہو۔ حدیث شریف میں ہے: ”اَلْحَلَالُ مَا اَحَلَّ اللہ فِیْ کِتَابِہٖ وَالْحَرَامُ مَاحَرَّمَ اللہ فِیْ کِتَابِہٖ وَمَاسَکَتَ عَنْہُ فَھُوَ مِمَّا عَفَا عَنْہُ“ (ترمذی، کتاب اللباس، باب ماجاء فی لبس الفراء، ۳/ ۲۸۰، حدیث:۱۷۳۲)یعنی حلال وہ ہے جو اللہ پاک نے اپنی کتاب میں حلال فرمادیا اور حرام وہ ہے جو اللہ پاک نے اپنی کتاب میں حرام فرمادیا اور جن چیزوں سے سکوت اختیار فرمایا وہ معاف ہیں اور مباح۔ لہٰذا ہر وہ چیز جس سے اللہ پاک نے سکوت اختیار فرمایا وہ جائز و مباح ہے۔قرآن مجید میں ارشاد باری تعالیٰ ہے: یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا لَا تَسْــٴَـلُوْا عَنْ اَشْیَآءَ اِنْ تُبْدَ لَكُمْ تَسُؤْكُمْۚ ( پ۷، المآئدة:۱۰۱)’’اے ایمان والو! تم ایسی چیزوں کے بارے میں سوال نہ کرو جن کا حکم نازل نہیں کیا گیاکہ اگر ان کا حکم ظاہر کردیا جائے تو تمہیں تکلیف پہنچے۔‘‘ اسی لئے حضور علیہِ الصّلوٰۃُوالسّلام نے شرعی احکام میں کثرتِ سوال سے منع فرمایا کہ اس سے شریعت کے احکام کے سخت ہونے کا اندیشہ ہے،لہٰذا جن چیزوں کے بارے میں کوئی حکم نازل نہیں ہوا وہ عفو میں داخل ہیں۔ (بہار شریعت، حصہ19، 3/ 1071، ملخصاً)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6896, "bookId": 13, "volNo": "1", "hadithNo": 31, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "خالق اور مخلوق کی محبت کا سبب", "arabic": "عَنْ اَبِی الْعَبَّاسِ سَهْلِ بْنِ سَعْدِ السَّاعِدِیِّ رَضِیَ اللهُ عَنْهُ قَالَ: جَآءَ رَجُلٌ اِلَى النَّبِیِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُوْلَ اللهِ! دُلَّنِیْ عَلٰى عَمَلٍ اِذَا عَمَلْتُهٗ اَحَبَّنِیَ اللهُ وَاَحَبَّنِیَ النَّاسُ؟ فَقَالَ: ’’اِزْهَدْ فِي الدُّنْيَا يُحِبُّكَ اللهُ وَازْهَدْ فِيْمَا عِنْدَ النَّاسِ يُحِبُّكَ النَّاسُ.‘‘ (حَدِيْثٌ حَسَنٌ رَوَاهُ ابْنُ مَاجَة وَغَيْرُهٗ بِاَسَانِيْدَ حَسَنَةً)", "urdu": "حضرت سیِّدُنا ابوالعباس سہل بن سعد ساعِدی رضی اللہ عنہ بیان کرتے ہیں کہ ایک شخص نے بارگاہِ رسالت میں حاضر ہو کر عرض کی: یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! مجھے ایسا عمل بتائیے کہ جب میں اسے کروں تو اللہ پاک مجھ سے محبت فرمائے اور لوگ بھی مجھ سے محبت کرنے لگیں۔ ارشاد فرمایا: ’’دنیا سے بےرغبت ہوجاؤاللہ پاک تم سے محبت فرمائے گا اور لوگوں کے پاس جو کچھ ہےاس سے کنارہ کشی اختیار کر لو تو لوگ بھی تم سے محبت کریں گے۔‘‘ \n(ابن ماجہ، كتاب الزهد، باب الزهد فی الدنيا، ۴/ ۴۲۲، حدیث:۴۱۰۲)\n (یہ حدیث حسن ہے اسے حضرت سیِّدُنا امام ابو عبد اللہ محمد بن یزید بن ماجہ رحمۃ اللہ علیہاور دیگر محدثین نے حسن سندوں کے ساتھ روایت کیا ہے۔)", "roman": "Hazrat Sayyiduna Abul Abbas Sahl bin Sa'ad Sa'idi Radiyallahu Anhu bayan karte hain ke ek Shakhs ne bargah-e-Risalat mein hazir ho kar arz ki: Ya Rasoolullah Sallallahu Alayhi wa Sallam! Mujhe aisa amal bataiye ke jab main ise karoon to Allah Paak mujh se Mohabbat farmaye aur log bhi mujh se Mohabbat karne lagen. Irshad farmaya: 'Duniya se beraghabat ho jao Allah Paak tum se Mohabbat farmaye ga aur logon ke paas jo kuch hai us se kinara kashi ikhtiyar kar lo to log bhi tum se Mohabbat karenge.' (Ibn-e-Majah, Kitaab-uz-Zuhd, Baab-uz-Zuhd fid-Dunya, 4/422, Hadees: 4102) (Yeh Hadees Hasan hai ise Hazrat Sayyiduna Imam Abu Abdullah Muhammad bin Yazeed bin Majah Rahmatullah Alayh aur deegar Muhaddiseen ne Hasan Sanadon ke sath Riwayat kiya hai.)", "explanation": "¥محبَّتِ خالق کی علامت:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’مجھے ایسا عمل بتائیے کہ جب میں اسے کروں تو اللہ پاک مجھ سے محبت فرمائے اور لوگ بھی مجھ سے محبت کرنے لگیں ‘‘ کے تحت فرماتے ہیں: معلوم ہوا کہ اللہ (پاک) کے بندوں کی محبت جو قدرتی طور سے ہو اللہ (پاک) کی رحمت ہے، محبَّتِ خلق محبَّتِ خالق کی علامت ہے، لہٰذا لوگوں کی محبت حاصل کرنے کی کوشش کرنا ممنوع نہیں ، حضرت ابراہیم علیہِ السّلام نے دعا کی تھی کہ مولیٰ: وَ اجْعَلْ لِّیْ لِسَانَ صِدْقٍ فِی الْاٰخِرِیْنَۙ(۸۴) (پ۱۹، الشعرآء: ۸۴ ) آئندہ نسلوں میں میرا ذکر خیر جاری فرما۔ لہٰذا ان صاحب کا یہ سوال بالکل برحق ہے ۔(مراٰ ۃ المناجیح، 7/ 24،ملتقطاً)\n¥دنیا سے بےرغبتی کے ارکان:\n اور حدیث پاک کے جز ’’دنیا سے بےرغبت ہوجاؤاللہ پاک تم سے محبت فرمائے گا‘‘ کے تحت فرماتےہیں کہ دنیا سے بے رغبتی کے رکن تین ہیں : محبَّتِ دنیا سے علیحدگی، زائد دنیا سے پرہیز، آخرت کی تیاری۔ ایسے شخص سے اللہتعالیٰ محبت اس لیے کرتا ہے کہ وہ اللہ کے دُشمن سے محبت نہیں کرتا دُشمن کا دُشمن بھی دوست ہوتا ہے۔ نیز جو دنیا سے بے رغبت ہوگا وہ گناہ کم کرے گا نیکیاں زیادہ اور ایسا بندہ ضرور اللہ تعالیٰ کو پیارا ہے۔ (مراٰ ۃ المناجیح، 7/ 24،ملتقطاً)\n¥محبَّتِ الٰہی کا سبب:\n حضرت سیِّدُنا امام شرف الدین حسین بن محمد طیبی رحمۃُ اللہ علیہ فرماتے ہیں: زہد سے اللہ پاک کی محبت پیدا ہوتی ہے یہ اس بات پر دلیل ہے کہ زہد بہت اعلیٰ اور افضل عمل ہے کیونکہ اسے اللہ پاک کی محبت کا سبب بنایا گیا ہے اور دنیا کی محبت اللہ پاک کی ناراضی کا سبب ہے۔ (شرح الطیبی، کتاب الرقاق، الفصل الثانی، ۹/ ۳۵۱، تحت الحدیث:۵۱۸۷)\n¥محبَّتِ خالق کی علامت:\n مشہور شارح حدیث، حکیم الامتمفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’لوگوں کے پاس جو کچھ ہےاس سے کنارہ کشی اختیار کر لو تو لوگ بھی تم سے محبت کریں گے ‘‘ کے تحت فرماتے ہیں: دنیا کا دستور ہے کہ جو اس کی طرف دوڑتا ہے تو وہ اس سے بھاگتی ہے اور جو اس سے بے نیاز ہوتا ہے تو وہ اس کی طرف آتی ہے ۔ جو شخص لوگوں سے تمنا رکھے گا تو خواہ مخواہ ان کی خوشامد کرے گا اور لوگ اس سے نفرت کریں گے اور جو لوگوں سے بے نیاز ہوگا تو لوگ خواہ مخواہ اس کی طرف آئیں گے۔ (مراٰ ۃ المناجیح، 7/ 24)\n¥لوگوں کے ا موال سے بے رغبتی میں عزت کیوں؟\nحضرت سیِّدُنا علامہ محمد عبد الرءوف مُناوی رحمۃُ اللہ علیہ فرماتے ہیں: لوگوں کے دلوں میں دنیا کی محبت فطری طورپر رکھی گئی ہے اور یہ محبت ان کے دلوں پر نقش ہوگئی ہے تو جو کوئی انسان سے اس کی پسندیدہ چیز میں جھگڑتا ہے تو انسان اس سے نفرت کرتا اور اسے چھوڑ دیتا ہے اور جو انسان کی پسندیدہ چیز میں اس سے نہیں جھگڑتا تو انسان اس سے محبت کرتا اور عزت دیتا ہے۔ اسی لئے مشہور تابعی بزرگ حضرت سیِّدُنا حسن بصری رحمۃُ اللہ علیہ نے فرمایا: ’’لوگ آدمی کی عزت کرتے رہتے ہیں یہاں تک کہ جب وہ ان کی دنیا کا خواہشمند ہوتا ہے تو وہ اُسے حقیر سمجھتے ہیں اور اس کی بات کو بھی ناپسند کرتے ہیں۔‘‘ منقول ہے کہ اہْلِ بصرہ میں سے کسی سے پوچھا گیا: تمہارا سردار کون ہے؟ اس نے جواب دیا: ’’حضرت سیِّدُنا حسن بصری رحمۃُ اللہ علیہ ۔‘‘ پوچھنے والے نے کہا: انہیں تمہارے نزدیک یہ مقام و مرتبہ کیوں حاصل ہے؟ اس نے کہا: ’’ہم ان کے علم سے دلیل پکڑتے ہیں اور وہ ہماری دنیا سے بے نیاز ہیں۔‘‘ (فیض القدیر، حرف الھمزة، ۱/ ۶۱۵، تحت الحدیث:۹۶۰)\n¥مال سے محبت کی جائز ومحمود صورت:\n حضرت سیِّدُنا علامہ محمد بن علّان شافعی رحمۃُ اللہ علیہ فرماتے ہیں: مال ودولت اور دنیا کی ایسی محبت مذموم ہے جو شہواتِ نفسانی کی تکمیل کے لئے ہو کیونکہ ایسی محبت انسان کو اللہ پاک کی یاد سے غافل کر دیتی ہے۔ بہرحال بھلائی کے کام کرنے، محتاج کی حاجت روائی کرنے، ستم رسیدہ کی مدد کرنے، تنگدست کو کھانا کھلانے کے لئے مال سے محبت کرنا عبادت ہے کہ حدیث پاک میں ہے: ’’اچھا ( یعنی حلال) مال نیک مرد کے لئے بہت ہی اچھا ہے کہ وہ اس مال کے ذریعے صلہ رحمی اور حُسْنِ سُلُوک کرتا ہے۔‘‘(دلیل الفالحین، باب فی فضل الزھد فی الدنیا...الخ، ۲/ ۴۰۲، تحت الحدیث:۴۷۱)\n¥زہد کی تعریف اور مفہوم:\n اپنی رغبت اور ارادے کو ایک چیز سے ہٹاکر دوسری چیز کی طرف پھیر دینا جو اس پہلی چیز سے بہتر ہو زہد کہلاتا ہے۔ ہر وہ شخص جو ایک چیز کو چھوڑ کر کسی مُعاوَضے یا سودے کے سبب دوسری چیز کواختیار کرتا ہے وہ پہلی چیز کو بے رغبتی کے سبب چھوڑتا اور دوسری چیز کو اس میں رغبت اور پسندیدگی کے سبب اختیار کرتا ہے۔جس چیز سے اس نے اعراض کیا اس کی نسبت سے اس کے حال کو زہد جبکہ جس کی طرف یہ مائل ہوا اس کی نسبت سے رغبت ومحبت کہا جاتا ہے۔\n¥زاہد کی تعریف:\n زہد کے لئے دو چیزیں ضروری ہیں: (1)...وہ چیز جس سے بے رغبتی اختیار کی جائے اور (2)... وہ جس میں رغبت کی جائےاور وہ پہلی چیز سے بہتر ہو۔نیز جس چیز سےبے رغبتی کی جائے اس کا بھی کسی نہ کسی اعتبار سے مرغوب ومطلوب ہونا ضروری ہے۔جو شخص ایسی چیز کو ترک کرے جو کسی بھی طرح مطلوب نہ ہو اسے زاہد نہیں کہا جائے گاکیونکہ مٹی،پتھر اور اس قسم کی دیگر بے وَقْعَت اشیاء کو ترک کرنے والا زاہد نہیں کہلاتابلکہ زاہد اس شخص کو کہتے ہیں جو درہم ودینار وغیرہ کو ٹھکرائے جبکہ مٹی اورپتھر وغیرہ تو اس قابل ہی نہیں کہ ان میں رغبت کی جائے۔جس چیز میں رغبت کی جائے اس کے لئے یہ شرط ہےکہ وہ اس شخص کےنزدیک دوسری چیز سے بہتر ہو تاکہ اس چیز کی رغبت دوسری چیز کی رغبت پر غالب ہوجائے۔\n(احیاء العلوم، کتاب الفقر والزھد، بیان حقیقة الزھد ،۴/ ۲۶۷، ملخصًا)\n¥زُہْد کے دَرَجات:\nزہد کے درج ذیل درجات ہیں: (1)...جو شخص اللہ پاک کے سوا ہر چیز سے حتّٰی کہ جنَّتُ الفردوس سے بھی بےرغبتی اختیار کرے، صرف اللہ پاک سے ہی محبت کرے وہ ’’زاہِدِ مطلق‘‘ ہے جو کہ زہد کا اعلیٰ ترین درجہ ہے۔ (2)...جو شخص تمام دنیوی لذات سے بے رغبت ہولیکن اُخروی نعمتوں مثلاً:جنتی حوروں،مَحلات وباغات، نہروں اور پھلوں وغیرہ کی لالچ کرے وہ بھی زاہد ہے لیکن اس کا مرتبہ’’زاہدِ مطلق‘‘سے کم ہے۔ (3)...جو شخص دنیوی لذات میں سے بعض کو ترک کرے اور بعض کو نہیں مثلاً مال ودولت کو ترک کرے، مرتبے اور شہرت کو نہیں یا کھانے پینے میں وسعت کو ترک کرے زینت وآرائش کو نہیں اس کو مطلقاً زاہد نہیں کہا جاسکتا۔ زاہدین میں ایسے شخص کا وہی مرتبہ ہے جیسے توبہ کرنے والوں میں اس شخص کا جو بعض گناہوں سے توبہ کرے اور بعض سے نہ کرے،جس طرح ایسے تائب کی توبہ صحیح ہے کہ ممنوعہ چیزوں کو ترک کرنے کا نام توبہ ہے تو ایسے ہی اس زاہد کا زہد بھی صحیح ہےکہ مباح لذّتوں کا ترک کرنا زہد کہلاتا ہے اورجس طرح یہ ممکن ہے کہ کوئی شخص بعض ممنوعات کو ترک کرپاتاہو اور بعض کونہیں اسی طرح جائز چیزوں میں بھی یہ ہوسکتاہے۔\n(احیاء العلوم، کتاب الفقر والزھد، بیان حقیقة الزھد ،۴/ ۲۸۲)\n¥زہد کا کم سے کم درجہ:\n بہرحال ظاہری اور باطِنی دونوں اِعتبارات سے زہد کے درجات کی کوئی حد نہیں۔ زہد کا کم سے کم درجہ یہ ہے کہ ہر ممنوعہ اور مُشْتَبَہ چیز سے بے رغبتی اختیار کی جائے۔ بعض بزرگانِ دین رحمۃُ اللہ علیہم فرماتے ہیں: ’’زہد صرف حلال میں ہے، حرام اور مشتبہ چیزوں میں نہ تو زہد ہے اور نہ ہی ان سے بے رغبتی اختیار کرنا زہد کا کوئی درجہ ہے۔‘‘\n(احیاء العلوم، کتاب الفقر والزھد، بیان درجات الزھد ،۴/ ۲۸۲)\n¥دولت کی موجودگی میں زہد:\n مَرْوِی ہے کہ حضرت سیِّدُنا سُفیان بن عُیَیْنہ اور حضرت سیِّدُنا سُفْیَان ثَوری رحمۃُ اللہ علیہم ا سے عَرْض کی گئی: جس کے پاس مال ودولت ہو کیا وہ زاہد ہو سکتا ہے؟ تو انہوں نے فرمایا: ہاں! مگر شَرْط یہ ہے کہ جب اس پر کوئی آزمائش آئے تو صبر کرے اور جب کسی اِنعام سے نوازا جائے تو شکر کرے۔ حضرت سیِّدُنا ابن ابی حَواری رحمۃُ اللہ علیہ فرماتے ہیں کہ میں نے حضرت سیِّدُنا سُفْیَان بن عُیَینہ رحمۃُ اللہ علیہ سے عَرْض کی: اے ابو محمد! جس نے اِنْعَام پر شکر ادا کیا، مصیبت پر صَبْر کیا اور نِعْمَت کو روکے رکھا وہ کیسے زاہِد ہو سکتا ہے؟ یہ سن کر آپ نے اپنے ہاتھ سے مجھے ٹھوکتے ہوئے فرمایا: خاموش رہو! جس کو نعمتیں شکر سے اور مصیبتیں صبر سے نہ روکیں تو وہ زاہِد ہی ہے۔ (قوت القلوب، الفصل الثانی والثلاثون: شرح مقامات الیقین...الخ، ۱/ ۴۴۸)\n¥زہد کی فضیلت پر تین آیات مبارکہ:\n(1)...\nمَنْ كَانَ یُرِیْدُ حَرْثَ الْاٰخِرَةِ نَزِدْ لَهٗ فِیْ حَرْثِهٖۚ-وَ مَنْ كَانَ یُرِیْدُ حَرْثَ الدُّنْیَا نُؤْتِهٖ مِنْهَا وَ مَا لَهٗ فِی الْاٰخِرَةِ مِنْ نَّصِیْبٍ(۲۰) (پ ۲۵، الشورٰی:۲۰)\nترجمہ کنزالایمان: جو آخرت کی کھیتی چاہے ہم اس کے ليے اس کی کھیتی بڑھائیں اور جو دنیا کی کھیتی چاہے ہم اسے اس میں سے کچھ دیں گے اور آخرت میں اُس کا کچھ حصّہ نہیں۔\n(2)...\nبَلْ تُؤْثِرُوْنَ الْحَیٰوةَ الدُّنْیَا٘ۖ(۱۶) وَ الْاٰخِرَةُ خَیْرٌ وَّ اَبْقٰىؕ(۱۷) (پ ۳۰، الاعلٰی:۱۶، ۱۷)\nترجمہ کنزالایمان: بلکہ تم جیتی دنیا کو ترجیح دیتے ہو اور آخرت بہتر اور باقی رہنے والی۔\n(3)...\nقُلْ مَتَاعُ الدُّنْیَا قَلِیْلٌۚ-وَ الْاٰخِرَةُ خَیْرٌ لِّمَنِ اتَّقٰى (پ ۵، النسآء:۷۷)\nترجمہ کنزالایمان: تم فرما دو کہ دنیا کا برتنا تھوڑا ہے اور ڈر والوں کے لیے آخرت اچھی۔\n¥زہد کی فضیلت پر تین احادیْثِ مبارکہ:\nحضرت سیِّدُنا ابو ذر رضی اللہ عنہ سے روایت ہے کہ رسولِ خدا صلّی اللہ علیہ واٰلہٖ وسلَم نے ارشاد فرمایا: ’’دنیا سے بے رغبتی مال کو ضائع کردینے اور حلال کو حرام کردینے کا نام نہیں،بلکہ دنیاسے کنارہ کشی تویہ ہے کہ جوکچھ تیرے ہاتھ میں ہے وہ اس سے زیادہ قابِل اعتماد نہ ہو جو کچھ اللہ پاک کے پاس ہے۔‘‘(ترمذی، کتاب الزھد، باب ماجآء فی الزھادة فی الدنیا، ۴/ ۱۵۲، حدیث:۲۳۴۷)\n حضرت سیِّدُنا سہل بن سعد رضی اللہ عنہ روایت کرتے ہیں کہ رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اگر اللہ پاک کے نزدیک دنیا کی حیثیت مچھرکے پَر کے برابر بھی ہوتی تووہ اس دنیاسے کسی کافر کو پانی کا ایک گھونٹ بھی پینے کونہ دیتا۔‘‘ (ترمذی ، کتاب الزھد، باب ماجاء فی ھوان الدنیاعلی اللّٰہ، ۴/ ۱۴۳، حدیث:۲۳۲۷)\n حضرت سیِّدُنا صفوان بن سلیم رضی اللہ عنہ بیان کرتے ہیں کہ رسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو شخص دنیا سے بےرغبتی اختیار کرتا ہے اللہ پاک اس کے دل میں حکمت ڈال کر اس کی زبان پر جاری فرمادیتا، اسے دنیا کی بیماری اور اس کے علاج کی پہچان عطا فرمادیتا اور اسے دنیا سے صحیح سلامت نکال کر سلامتی والے گھر (یعنی جنت کی طرف) لے جاتا ہے۔‘‘ (شعب الایمان، باب فی الزھد وقصر الامل، ۷/ ۳۴۶، حدیث:۱۰۵۳۱)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6897, "bookId": 13, "volNo": "1", "hadithNo": 32, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "کسی کو بھی نقصان نہ پہنچاؤ", "arabic": "عَنْ اَبِيْ سَعِيْدٍ سَعْدِ بْنِ مَالِكِ بْنِ سِنَانِ الْخُدَرِيِّ رَضيَ اللهُ عَنْهُ اَنَّ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’لَاضَرَرَ وَلَا ضِرَارَ.‘‘\n(حَدِيْثٌ حَسَنٌ رَوَاهُ ابْنُ مَاجَه، وَالدَّارُقُطْنِیُّ وَغَيْرُهُمَا مُسْنَدًا وَرَوَاهُ مَالِكٌ رَحِمَہُمُ اللّٰہ تعالٰی فِی الْمُوَطَّا عَنْ عَمْرِو بْنِ يَحْيٰى عَنْ اَبِيْهٖ عَنِ النَّبِیِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُرْسَلًا فَاَسْقَطَ اَبَا سَعِيْدٍ وَّلَهٗ طُرُقٌ يُّقَوِّیْ بَعْضُهَا بَعْضًا)", "urdu": "حضرت سیِّدُنا ابوسعید سعد بن مالک بن سنان خدری رضی اللہ عنہ سے روایت ہے کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’نہ خود نقصان اٹھاؤ اور نہ ہی (دوسروں کو) نقصان پہنچاؤ۔‘‘ \n(ابن ماجہ، كتاب الاحكام، باب من بنى فی حقہ ما يضر بجاره، ۳/ ۱۰۶، حدیث:۲۳۴۰ ۔ دار قطنی، کتاب الاقضیة والاحکام، ۴/ ۲۶۹، حدیث:۴۴۹۵)\n(یہ حدیث حسن ہے اسے حضرت سیِّدُنا امام ابو عبد اللہ محمد بن یزید بن ماجہ اور حضرت سیِّدُنا امام علی بن عمر دار قطنی رحمۃ اللہ علیہما اور دیگر محدثین نے سند کے ساتھ روایت کیا ہے۔ جبکہ حضرت سیِّدُنا امام مالک رحمۃ اللہ علیہ نے موطا میں حضرت سیِّدُنا عمرو بن یحییٰ سے، انہوں نے اپنے والد حضرت سیِّدُنا یحییٰ رحمۃ اللہ علیہما کی سند سے حضور نبی پاک صلّی اللہ علیہ والہ وسلّم سے (آخری روای کو ذکر کئے بغیر) مرسلاً روایت کیا ہے کہ حضرت سیِّدُنا ابو سعید رضی اللہ عنہ کو ذکر نہیں کیا۔ اس روایت کی اور بھی سندیں ہیں جو ایک دوسرے کو تقویت دیتی ہیں۔)", "roman": "Hazrat Sayyiduna Abu Saeed Sa'ad bin Maalik bin Sinaan Khudri Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne irshad farmaya: 'Na khud nuqsan uthao aur na hi (dusron ko) nuqsan pahunchao.' (Ibn-e-Majah, Kitaab-ul-Ahkaam, Baab man bana fi haqqihi ma yadurru bi-jarihi, 3/106, Hadees: 2340. Darqutni, Kitaab-ul-Aqziya wal-Ahkaam, 4/269, Hadees: 4495) (Yeh Hadees Hasan hai ise Hazrat Sayyiduna Imam Abu Abdullah Muhammad bin Yazeed bin Majah aur Hazrat Sayyiduna Imam Ali bin Umar Darqutni Rahmatullah Alayhima aur deegar Muhaddiseen ne Sanad ke sath Riwayat kiya hai. Jabke Hazrat Sayyiduna Imam Malik Rahmatullah Alayh ne Mu'atta mein Hazrat Sayyiduna Amr bin Yahya se, unhon ne apne walid Hazrat Sayyiduna Yahya Rahmatullah Alayhima ki Sanad se Huzoor Nabi Paak Sallallahu Alayhi wa Sallam se (aakhri rawi ko zikr kiye baghair) Mursal-an Riwayat kiya hai ke Hazrat Sayyiduna Abu Saeed Radiyallahu Anhu ko zikr nahi kiya. Is Riwayat ki aur bhi Sanadein hain jo ek dusre ko taqwiyat deti hain.)", "explanation": "¥’’لَاضَرَرَ وَلَاضِرَار¥‘‘ کا معنیٰ ومفہوم:\n’’لَاضَرَرَ‘‘ کا معنیٰ ہے:کوئی کسی کو نقصان نہ پہنچائے اور ’’لَاضِرار‘‘ کا معنیٰ ہے: اگر کسی سے کوئی نقصان پہنچے تو بدلے میں اسے نقصان نہ پہنچائے بلکہ عفو ودرگزر سے کام لے کہ یہ تقویٰ کے زیادہ قریب ہے۔ اس کے اور بھی کئی معانی بیان کئے گئے ہیں۔ (الجواھراللؤلؤیة للدمیاطی، ص۴۷۰، تحت الحدیث:۳۲)\nحضرت سیِّدُنا علامہ ابو زکریا یحییٰ بن شرف نووی رحمۃُ اللہ علیہ حدیث پاک کی شرح میں فرماتے ہیں: تم اسے نقصان نہ پہنچاؤ جو تمہیں نقصان دے اور تم اسے گالی نہ دو جو تمہیں گالی دے، اگر کوئی تمہیں مارے تو تم اسے نہ مارو بلکہ تم بغیر گالی دیے اپنا حق حاکم کے پاس جا کر طلب کرو۔ (شرح اربعین للنووی، ص۱۱۰)¥\nبلاوجہ کسی کو نقصان پہنچانا حرام ہے:\nیہ حدیث پاک اس بات پر دلالت کررہی ہے کہ بلاوجہ دوسروں کو تھوڑا یا زیادہ کسی بھی قسم کا نقصان پہنچانا حرام ہے، لہٰذا اے میرے بھائی! تو کسی کو بھی تکلیف دینے سے بچ کہ نہ تو اسے تکلیف دے، نہ اس کے گھر والوں کو، نہ اس کے مال میں اور نہ ہی اس کی عزت کے معاملے میں اسے تکلیف پہنچا کیو نکہ یہ ظلم ہے اور اللہ پاک ظلم کے بارے میں ارشاد فرماتا ہے:\nوَ قَدْ خَابَ مَنْ حَمَلَ ظُلْمًا(۱۱۱) (پ ۱۶، طٰہٰ:۱۱۱)\nترجمہ کنزالایمان: اور بےشک نامراد رہا جس نے ظلم کا بوجھ لیا۔\n(الجواھراللؤلؤیة للدمیاطی، ص۴۷۱، تحت الحدیث:۳۲)\n نیز احادیث مبارکہ میں بھی مسلمان کی عزت وحرمت کی حفاظت اور اسے نقصان پہنچانے اور تکلیف سے بچانے کی تاکید فرمائی گئی ہے۔ چنانچہ \n¥بندۂ مومن کی شان وعظمت:\n حضرت سیِّدُنا عبد اللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں: میں نے دیکھا کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم کَعْبَۃُ اللہ الْمُشَرَّفَہ کا طواف کر رہے ہیں اور بَیْتُ اللہ سے خطاب کرتے ہوئے ارشاد فرما رہے ہیں: ’’تو کتنا پاکیزہ ہے اور تیری خوشبو کس قدر مہک رہی ہے، تیری شان وعظمت کیسی ہے اور تیری حرمت کتنی عظیم ہے لیکن اس ذات کی قسم جس کے قبضَۂ قدرت میں محمد کی جان ہے! مومن کے مال اور اس کے خون کی عزت وحرمت اللہ پاک کے نزدیک تیری عزت وحرمت سے زیادہ عظیم ہے اور ہم اس سے خیر وبھلائی کی امید ہی رکھتے ہیں۔‘‘ (ابن ماجة، کتاب الفتن، باب حرمة دم المؤمن ومالہ،۴/ ۳۱۹، حدیث:۳۹۳۲)\n حضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ہرمسلمان کی جان، مال اور عزت دوسرے مسلمان پر حرام ہے۔‘‘ (ابن ماجة، کتاب الفتن، باب حرمة دم المؤمن ومالہ،۴/ ۳۲۰، حدیث:۳۹۳۳)\n¥مسلمان کی امتیازی شان:\n دوسروں کو تکلیف نہ دینا تو مسلمان کی امتیازی شان اور وصف ہے۔ چنانچہ حضرت سیِّدُنا عبد اللہ بن عَمْرو رضی اللہ عنہما سے مروی ہے کہ اللہ پاک کے آخری نبی محمد عربی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’مسلمان وہ ہے جس کے ہاتھ اور زبان سے دوسرے مسلمان محفوظ رہیں۔‘‘(بخا ری،کتاب الایمان، باب المسلم من سلم المسلمون من لسانہ ویدہ، ۱/ ۱۵، حدیث:۱۰)\n پھر زندہ تو زندہ دیْنِ اسلام تو مُردوں کو بھی ایذا وتکلیف دینے سے منع کرتا ہے۔ چنانچہ حضرت سیِّدُنا عمارہ بن حزم رضی اللہ عنہ بیان کرتے ہیں: میں ایک قبر پر بیٹھا تھا کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے مجھے دیکھ کر ارشاد فرمایا: قبر سے اتر جاؤ، قبر والے کو تکلیف نہ دو۔‘‘ (مرقاة المفاتیح، کتاب الجنائز، باب دفن المیت، الفصل الاول، ۴/ ۱۷۸، تحت الحدیث:۱۶۹۷)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6898, "bookId": 13, "volNo": "1", "hadithNo": 33, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "اسلام میں فیصلے کی بنیاد اور اصول", "arabic": "عَنِ ابْنِ عَبَّاسٍ رَضیَ اللهُ عَنْہُمَا مَا اَنَّ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’لَوْ يُعْطَى النَّاسُ بِدَعْوَاهُمْ لَادَّعٰى رِجَالٌ اَمْوَالَ قَومٍ وَدِمَآءَهُمْ لٰكِنِ الْبَيِّنَةُ عَلَى الْمُدَّعِيْ وَالْيَمِيْنُ عَلٰى مَنْ اَنكَرَ.‘‘ (حَدِيْثٌ حَسَنٌ رَوَاهُ الْبَيْهَقِیُّ وَغَيْرُهٗ هٰكَذَا وَبَعْضُهٗ فِی الصَّحِيْحَيْن)", "urdu": "حضرت سیِّدُنا عبد اللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اگر لوگوں کو ان کے دعوے کے مطابق دے دیا جائے تو لوگ دوسروں کی جان و مال کا دعویٰ کرنے لگیں گے، لیکن دعویٰ کرنے والے کے ذمہ گواہ ہے اور قسم انکار کرنے والے پر ہے۔‘‘\n(سنن الکبری للبيهقی، كتاب الدعوى والبينات، باب البينة على المدعی...الخ، ۱۰/۴۲۷، حدیث: ۲۱۲۰۱ ۔ ابن ماجة، کتاب الاحکام، باب البینة علی المدعی...الخ، ۳/ ۹۶، حدیث:۲۳۲۱ ۔ بخاری، تفسیر سورة ال عمران، باب قولہ تعالی: ان الذین یشترون بعھداللّٰہ، ۴/ ۱۹۰، حدیث: ۴۵۵۲ ۔ مسلم، کتاب الاقضیة، باب الیمین علی مدعی علیہ، ص۹۴۱، حدیث:۱۷۱۱)\n(یہ حدیث حسن ہے اسے حضرت سیِّدُنا امام ابو بکر احمد بن حسین بن علی بیہقی رحمۃ اللہ علیہ اور دیگر محدثین نے اسی طرح روایت کیا ہے۔ اس کا کچھ حصہ بخاری ومسلم میں بھی ہے۔)", "roman": "Hazrat Sayyiduna Abdullah bin Abbas Radiyallahu Anhuma se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne irshad farmaya: 'Agar logon ko un ke da'we ke mutabiq de diya jaye to log dusron ki jaan o Maal ka da'wa karne lagen ge, lekin da'wa karne wale ke zimma Gawah hai aur qasam inkar karne wale par hai.' (Sunan-ul-Kubra lil-Baihaqi, Kitaab-ud-Da'wa wal-Bayyinaat, Baab-ul-Bayyinatu alal-mudda'i... al-kh, 10/427, Hadees: 21201. Ibn-e-Majah, Kitaab-ul-Ahkaam, Baab-ul-Bayyinatu alal-mudda'i... al-kh, 3/96, Hadees: 2321. Bukhari, Tafseer-e-Surah Al-Imran, Baab qawlihi Ta'ala: Innal-lazina yashtaruna bi-ahdillahi, 4/190, Hadees: 4552. Muslim, Kitaab-ul-Aqziya, Baab-ul-Yameeni ala mudda'a alayhi, s 941, Hadees: 1711) (Yeh Hadees Hasan hai ise Hazrat Sayyiduna Imam Abu Bakr Ahmad bin Hussain bin Ali Baihaqi Rahmatullah Alayh aur deegar Muhaddiseen ne isi tarah Riwayat kiya hai. Is ka kuch hissa Bukhari o Muslim mein bhi hai.)", "explanation": "¥حدیث پاک کی اہمیت:\n حضرت سیِّدُنا علامہ ابو زکریا یحییٰ بن شرف نووی رحمۃُ اللہ علیہ فرماتے ہیں: یہ حدیث شریف احکامِ شرع کے قواعد میں سے ایک بہت بڑے قاعدے پر مشتمل ہے کہ بندہ جو دعویٰ کر رہا محض اس کے دعوے کی وجہ سے اس کی بات کو قبول نہیں کیا جائے گا بلکہ گواہ یا مُدَّعٰی عَلَیْہ (جس پر دعویٰ کیا گیا ہے اس) کی تصدیق سے فیصلہ کیا جائے گا۔(گواہ نہ ہونے کی صورت میں) اگر مُدَّعٰی عَلَیْہ سے قسم طلب کی گئی تو اس پر قسم لازم ہوگی۔\n(شرح النووی علی المسلم، کتاب الاقضیة، باب الیمین علی المدعی علیہ، الجزء الثانی عشر، ۱۲/ ۳)\n¥فقط دعوے پر فیصلہ نہ کرنے کی حکمت: \n امام نووی رحمۃُ اللہ علیہ فرماتے ہیں کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے فقط مدعی کے دعوے پر فیصلہ نہ کرنے کی حکمت بیان کرتے ہوئے ارشاد فرمایا: ’’اگر صرف دعوے کی بنیاد پر ہی لوگوں کی بات قبول کر لی جائے تو پھر کچھ لوگ دوسروں کی جان ومال کا دعویٰ کرنے لگیں گے۔‘‘ تو یوں مُدَّعٰی عَلَیْہ کے لئے اپنے مال اور خون کی حفاظت ممکن نہیں رہے گی اور جہاں تک مُدَّعِی (دعویٰ کرنے والے)کی بات ہے تو اس کے لئے ممکن ہے کہ وہ گواہ کے ذریعے اپنی جان اور مال کو محفوظ کر لے۔\n(شرح النووی علی المسلم، کتاب الاقضیة، باب الیمین علی المدعی علیہ، الجزء الثانی عشر، ۱۲/ ۳)\n¥مدعی پر گواہی اور قسم مدعی علیہ پر ہے:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث شریف کی شرح کرتے ہوئے فرماتے ہیں: ’’اگر لوگوں کو ان کے دعوے کے مطابق دے دیا جائے‘‘ (یعنی) اگر بفرضِ محال قانونِ اسلام یہ ہو جائے کہ ہرایک کے دعوے پر بغیر گواہی اور بغیر اقرار مدعی علیہ (یعنی گواہی اور جس پر دعویٰ کیا گیا ہے اس کے اقرار کے بغیر)فیصلہ ہو جائے ’’تو کچھ لوگ انسانوں کی جان و مال کا دعویٰ کرنے لگیں گے‘‘ یعنی ہر ایک کہہ دیا کرے کہ فلاں پر میرا اتنا قرض ہے اور فلاں نے میرے عزیز کو قتل کردیا ہے اس کاقصاص یا دیت دلوائی جائے اس پر ملک کا نظام ہی بگڑ جائے ’’لیکن دعویٰ کرنے والے کے ذمہ گواہ ہے اور قسم انکار کرنے والے پر ہے‘‘ مقصد یہ ہے کہ اگرمدعی کے پاس گواہی موجود نہ ہو اور مدعی علیہ اس کے دعویٰ کا اقراری نہ ہو انکاری ہو اور مدعی اس سے قسم کا مطالبہ کرے تو قسم مدعیٰ علیہ پر ہے،یہ تینوں قیدیں خیال میں رہنی چاہئیں۔خیال رہے کہ مدعی کے ذمہ گواہی اور مدعیٰ علیہ پر قسم ہونا عظیم الشان قاعدہ ہے اور یہ حدیث معنیً متواتر ہے جیسے حدیث ’’اِنَّمَا الْاَعْمَالُ بِالنِّیَّات (یعنی اعمال کا دارومدار نیتوں پر ہے)متواتر ہے،مدعی پر قسم نہیں مدعیٰ علیہ پر گواہی نہیں۔ (مراٰ ۃ المناجیح، 5/ 392، ملخصاً)\n¥’’بَیِّنَہ¥ (گواہی)¥‘‘ کا معنیٰ ومفہوم:\n مراٰۃ المناجیح میں حدیث شریف کے جز ’’لیکن گواہ مدعی پر ہے اور قسم انکاری پر‘‘ کی شرح میں ہے: خیال رہے ’’بَیِّنَۃ‘‘ یا تو بنا ہے ’’بَیْنُوْنَۃ‘‘ بمعنیٰ جدائی سے یا ’’بیان‘‘ سے بمعنیٰ ظہور، گواہی شرعی، حق وباطل کو جدا جدا کر دیتی ہے یا اس سے چھپی چیز ظاہر ہو جاتی ہےاس لئے اسے ’’بَیِّنَۃ‘‘ کہتے ہیں۔(مراٰ ۃ المناجیح، 5/ 392)\n¥گواہی کی اقسام، شرائط، رکن، حکم اور نصاب: \nشہادت کی تعریف:کسی حق کے ثابت کرنے کے لیے مجلِسِ قاضی میں لفْظِ شہادت کے ساتھ سچی خبر دینے کو شہادت یا گواہی کہتے ہیں۔(بہارشریعت، حصہ12، 2/ 930) شہادت کی اقسام:شہادت فرضِ کفایہ ہے بعض نے کر لیا تو باقی لوگوں سے ساقط اور دو ہی شخص ہوں تو فرضِ عین ہے۔ خواہ تحمل ہو یا ادا یعنی گواہ بنانے کے لیے بلائے گئے یا گواہی دینے کے لیے دونوں صورتوں میں جانا ضروری ہے۔ شہادت کی شرائط:شہادت کے لیے دو قسم کی شرطیں ہیں: شرائط تحمل و شرائط ادا۔ تحمل یعنی معاملہ کے گواہ بننے کے لیے تین شرطیں ہیں: (1)...بوقْتِ تحمل عاقل ہونا، (2)...انکھیارا ہونا(یعنی دیکھ سکتا ہو)۔ (3)...جس چیز کا گواہ بنے اُس کا مشاہدہ کرنا۔ لہٰذا مجنوں یا لا یعقل بچہ(یعنی نا سمجھ بچے) یا اندھے کی گواہی درست نہیں۔ یوہیں جس چیز کا مشاہدہ نہ کیا ہو محض سنی سنائی بات کی گواہی دینا جائز نہیں۔ تحمل کے لیے بلوغ، حریت، اسلام، عدالت شرط نہیں یعنی اگر وقت تحمل(یعنی جس وقت گواہ بن رہا تھا)بچہ یا غلام یا کافر یا فاسق تھا مگر ادا کے وقت بچہ بالغ ہو گیا ہے غلام آزاد ہو چکا ہے کافر مسلمان ہو چکا ہے فاسق تائب ہو چکا ہے تو گواہی مقبول ہے۔(بہارشریعت، حصہ12، 2/ 931)شہادت کا رکن: یہ ہے کہ بوقْتِ ادا گواہ یہ لفظ کہے کہ میں گواہی دیتا ہوں اس لفظ کا یہ مطلب ہے کہ میں خدا کی قسم کھا کر کہتا ہوں کہ میں اس بات پر مطلع ہوا اور اب اس کی خبر دیتا ہوں۔ اگر گواہی میں یہ لفظ کہہ دیا کہ میرے علم میں یہ ہے یامیرا گمان یہ ہے تو گواہی مقبول نہیں۔ شہادت کا حکم: یہ ہے کہ گواہوں کا جب تزکیہ ہو جائے (یعنی جب قاضی گواہوں کے متعلق یہ تحقیق کرلے کہ وہ عادل اور معتبر ہیں یا نہیں) اُس کے موافق حکم کر نا واجب ہے اور جب تمام شرائط پائے گئے اور قاضی نے گواہی کے موافق فیصلہ نہ کیا گنہگار ہوا اورمستحق عزل وتعزیرہے (یعنی وہ قاضی اس بات کا مستحق ہے کہ اسے معزول کر کے تادیباً سزا دی جائے)۔ (بہارشریعت، حصہ12، 2/ 932) \n(نوٹ: گواہی سے متعلق تفصیلی معلومات کے لئے ’’بہارشریعت، حصہ12، جلد2 ‘‘ سے گواہی کے بیان کا مطالعہ کیجئے۔)\n¥قسم کی تعریف، اقسام اور احکام:\n قسم کی تعریف:قسم اس عقد (معاہدے) کو کہتے ہیں جس کے ذریعے قسم کھانے والا کسی کام کے کرنے یا نہ کرنے کا پختہ ارادہ کرتا ہے۔ (فتاوی ھندیة، کتاب الایمان، الباب الاول فی تفسیرھا شرعا...الخ ،۲/ ۵۱) قسم کی اقسام: قسم کی تین قسمیں ہیں: (1)غموس، (2)لغو اور (3)منعقدہ۔اگر کسی ایسی چیز کے متعلق قسم کھائی جو ہوچکی ہے یا اب ہے یا نہیں ہوئی ہے یا اب نہیں ہے مگروہ قسم جھوٹی ہے مثلاً قسم کھائی فلاں شخص آیا اور وہ اب تک نہیں آیا ہے یا قسم کھائی کہ نہیں آیا اور وہ آگیا ہے یا قسم کھائی کہ فلاں شخص یہ کام کر رہا ہے اور حقیقۃً وہ اس وقت نہیں کر رہا ہے یا قسم کھائی کہ یہ پتھر ہے اور واقع میں وہ پتھر نہیں، غرض یہ کہ اس طرح جھوٹی قسم کی دوصورتیں ہیں جان بوجھ کر جھوٹی قسم کھائی یعنی مثلاً جس کے آنے کی نسبت جھوٹی قسم کھائی تھی یہ خود بھی جانتا ہے کہ نہیں آیاہے تو ایسی قسم کو غموس کہتے ہیں اور اگر اپنے خیال سے تو اوس نے سچی قسم کھائی تھی مگر حقیقت میں وہ جھوٹی ہے مثلاً جانتاتھا کہ نہیں آیا اور قسم کھائی کہ نہیں آیا اور حقیقت میں وہ آگیا ہے تو ایسی قسم کو لغو کہتے ہیں اور اگر آئندہ کے لیے قسم کھائی مثلاً خداکی قسم میں یہ کام کروں گا یا نہ کروں گا تو اس کو منعقدہ کہتے ہیں۔ قسم کا حکم: غموس میں سخت گنہگار ہوا استغفار و توبہ فرض ہے مگر کفارہ لازم نہیں اور لغو میں گناہ بھی نہیں اور منعقدہ میں اگر قسم توڑے گا کفارہ دینا پڑے گا اور بعض صورتوں میں گنہگار بھی ہوگا۔ (بہارشریعت، حصہ9، 2/ 298 تا 299)\n¥خلاصہ:\nغموس کی تعریف:گزرے ہوئے زمانے یا موجودہ زمانے کے بارےمیں جانتے ہوئے جھوٹی قسم کھانا۔ اس کا حکم: قسم کھانے والا سخت گنہگار ہے اس پر توبہ و استغفار فرض ہے اور کفارہ لازم نہیں۔ لغو کی تعریف: گزرے ہوئے زمانے یا موجودہ زمانے کے بارےمیں اپنے خیال میں سچی قسم کھانا لیکن حقیقت میں وہ جھوٹی ہو۔ اس کا حکم: قسم کھانے والا گناہ گار نہیں۔منعقدہ کی تعریف: اگر آئندہ (یعنی مستقبل) کے لئے قسم کھائی تو اسے منعقدہ کہتے ہیں۔ اس کا حکم:قسم کھانے والا اگر قسم توڑے گا تو کفارہ دینا پڑے گااور بعض صورتوں میں گناہ گار بھی ہوگا۔ \n¥قسم توڑ نے کا کفارہ:\n قسم کا کفارہ غلام آزاد کرنا یا دس مسکینوں کو کھانا کھلانا یا اون کو کپڑے پہنانا ہے یعنی یہ اختیار ہے کہ ان تین باتوں میں سے جو چاہے کرے۔(بہارشریعت، حصہ9، 2/ 305)کفارہ ادا ہونے کے لئے نیت شرط ہے بغیر نیت ادا نہ ہوگا۔(بہارشریعت، حصہ9، 2/ 307) اگر غلام آزاد کرنے یا دس مسکین کو کھانا دینے یا ان کو کپڑے دینے پر قادر نہ ہو تو پے در پے (لگاتار) تین روزے رکھے۔ ایک ساتھ تین روزے نہ رکھے یعنی درمیان میں فاصلہ کر دیا تو کفارہ ادا نہ ہوا اگرچہ کسی مجبوری کے سب ناغہ ہوا ہو۔ (بہارشریعت، حصہ9، 2/ 308، ملتقطاً)روزوں سے کفارہ ادا ہونے کے لیے یہ بھی شرط ہے کہ ختم (یعنی تین روزے پورے ہونے) تک مال پر قدرت نہ ہو۔ (بہارشریعت، حصہ9، 2/ 309)\n (نوٹ: قسم سے متعلق تفصیلی معلومات کے لئے ’’بہارشریعت، حصہ9، جلد2 ‘‘ سے قسم کا بیان اور مکتبۃ المدینہ کا 44 صفحات پر مشتمل مطبوعہ رسالہ ’’قسم کے بارے میں مدنی پھول‘‘کا مطالعہ کیجئے۔)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6899, "bookId": 13, "volNo": "1", "hadithNo": 34, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "برائی کو ختم کرنے کے مراتب", "arabic": "عَنْ اَبِيْ سَعِيْدِ الْخُدَرِيِّ رَضيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُوْلُ: ’’مَنْ رَاٰى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهٖ فَاِنْ لَّمْ يَسْتَطِعْ فَبِلِسَانِهٖ فَاِنْ لَّمْ يَسْتَطِعْ فَبِقَلْبِهٖ وَذٰلِكَ اَضْعَفُ الْاِيْمَانِ.‘‘ (رَوَاهُ مُسْلِمٌ)", "urdu": "حضرت سیِّدُنا ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم کو ارشاد فرماتے سنا: ’’تم میں سے جو کوئی برا کام دیکھے تو اسے چاہیے کہ اپنےہاتھ سے روک دے، اگر اس کی طاقت نہیں رکھتا تو زبان سے، اگر اس کی بھی طاقت نہیں رکھتا تو دل سے (بُرا جانے) اور یہ ایمان کا کمزور ترین درجہ ہے۔‘‘\n( مسلم، كتاب الايمان، باب بيان کون النھی عن المنكر من الايمان…الخ، ص۴۹، حدیث:۱۷۷)", "roman": "Hazrat Sayyiduna Abu Saeed Khudri Radiyallahu Anhu bayan karte hain ke main ne Rasoolullah Sallallahu Alayhi wa Sallam ko irshad farmate suna: 'Tum mein se jo koi bura kaam dekhe to use chahiye ke apne haath se rok de, agar is ki taqat nahi rakhta to zabaan se, agar is ki bhi taqat nahi rakhta to dil se (bura jaane) aur yeh Imaan ka kamzor tareen darja hai.' (Muslim, Kitaab-ul-Imaan, Baab bayan kawnin-nahyi anil-munkari minal-Imaan... al-kh, s 49, Hadees: 177)", "explanation": "¥بُرائی کسے کہتے ہیں؟\nبُرائی سے مراد ہروہ بات ہے جس کی شریعت نے مذمت بیان کی ہو، اسے حرام ٹھہرایا ہو اور اسے ناپسند کیا ہو۔ برائی سے کبھی قول کے ذریعے منع کیا جاتا ہے جیسے شراب نوشی سے منع کرنا۔ کبھی صرف فعل کے ذریعے جیسے شراب کو بہا دینا۔ جب بُرائی سے قول کے ذریعے منع کیاجائے تواسے نَہْیٌ عَنِ الْمُنْکَر (یعنی بُرائی سے منع کرنا) کہتے ہیں اور جب فعل کے ذریعے منع کیا جائے تو اسے تَغْیِیْرٌ لِّلْمُنْکَر(یعنی بُرائی کو بدلنا) کہتے ہیں۔ \n(شعب الایمان للصاغرجی، الامر با لمعروف و النھی عن المنکر، ۴ /۱۹۲) \n¥بُرائی کو روکنا کس پر لازم ہے؟\nعلامہ محمد بن علّان شافعی رحمۃُ اللہ علیہ فرماتے ہیں: تم میں سےجوبرائی دیکھےیعنی اسے کسی برائی کے بارے میں علم ہوجائے تو اُس برائی کو روکے، کیونکہ نہی عن المنکر کے واجب ہونے کےلئےآنکھوں سے دیکھنا شرط نہیں بلکہ بُرائی سے منع کرنے کا دارومدار علم پر ہے۔اب چاہے آنکھوں سےوہ برائی ہوتےہوئے دیکھے یانہ دیکھے۔ نیز حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم کے ارشاد: ”تم میں سے جو برا کام دیکھے۔“سے مراد مکلَّف اور قدرت رکھنے والے مسلمان ہیں، لہٰذا یہ خطاب ساری اُمت کے لئے ہے، حاضرین کےلئے بالمشافہ اور غائبین کے لیے بالتبع۔\n(دلیل الفالحین، باب فی الامر بالمعروف والنھی عن المنکر، ۱/ ۴۶۶، تحت الحدیث:۱۸۵) \n¥بُرائی کو ہاتھ سے روکنے کا طریقہ:\nعلامہ ملّاعلی قاری رحمۃُ اللہ علیہ فرماتے ہیں: جو کوئی ایسا کام ہوتے ہوئے دیکھے جس سے شریعت نے منع کیا ہے تو اسے چاہیے کہ اسے اپنے ہاتھ سے روک دے۔ اس طرح کہ اس شخص کو اس فعل سے منع کرے، اس گناہ کے آلات کو توڑ دے، شراب وغیرہ کو بہا کر ضائع کردے اور اگر وہ چھینی ہوئی چیز ہے تو اس کے مالک تک پہنچادے۔\n(مرقاة، کتاب الاٰداب، باب الامر بالمعروف، ۸/ ۸۶۱، تحت الحدیث:۵۱۳۷)\n¥بُرائی کو زبان سےر وکنے کا طریقہ:\nعلامہ محمد بن علان شافعی رحمۃُ اللہ علیہ فرماتے ہیں: اگر اپنی جان کو ضررپہنچنے یا مال چھن جانے کے خدشے کی وجہ سے بُرائی کو ہاتھ سے روکنے کی طاقت نہ ہو تو زبان سےاُسے روکے جس کے رُک جانے کی امیدہو۔ روکنے کا طریقہ یہ ہے کہ اسے زور سے آواز دے، ڈانٹ ڈپٹ کرے، اللہ پاک کا خوف دلائے، اس کے عذاب سے ڈرائے، الغرض نرمی اورسختی میں سےجو مفید ہو اس پر عمل کرے۔(دلیل الفالحین، باب فی الامر بالمعروف والنھی عن المنکر، ۱/ ۴۶۷، تحت الحدیث:۱۸۵)\nعلامہ ملّاعلی قاری رحمۃُ اللہ علیہ فرماتے ہیں: بُرائی کو زبان سے اس طرح روکے کہ اللہ پاک نے اس گناہ پر جو وعیدیں نازل فرمائی ہیں انہیں بیان کرے اور بُرائی کرنے والے کو اعمالِ بد کے نتائج سے باخبر کرے، گناہوں کے انجام سے ڈرائے اور نصیحت کرے۔(مرقاة، کتاب الاٰداب، باب الامر بالمعروف، ۸/ ۸۶۱، تحت الحدیث:۵۱۳۷)\n¥بُرائی کو دل میں بُرا جاننے کا طریقہ:\n علامہ محمد بن علان شافعی رحمۃُ اللہ علیہ فرماتے ہیں: دل میں بُرا جاننے کا طریقہ یہ ہے کہ اسے ناپسند کرے اور اس بات کا پختہ عزم کرےکہ جب کبھی ہاتھ یازبان سے اس بُرائی کو ختم کرنے پر قدرت حاصل ہوگی تو ضروراس گناہ کو ختم کروں گا۔کیونکہ گناہ سے نفرت کرنا واجب ہے اور گناہ پر رضا مندرہنا ایسا ہے جیسے گناہ کرنے والے کے ساتھ گناہ میں شریک ہونا۔\n(دلیل الفالحین، باب فی الامر بالمعروف والنھی عن المنکر، ۱/ ۴۶۸، تحت الحدیث:۱۸۵، ملتقطًا)\n¥ہر شخص اپنے منصب کے مطابق برائی سے روکے:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کی شرح کرتے ہوئے فرماتے ہیں: بُرائی کو بدلنے کے لیے ہر طبقے کو اس کی طاقت کے مطابق ذمہ داری سونپی گئی کیونکہ اسلام میں کسی بھی انسان کو اس کی طاقت سے زیادہ تکلیف نہیں دی جاتی۔ اربابِ اِقتدار،اَساتذہ،والدین وغیرہ جو اپنے ماتحتوں کو کنٹرول کرسکتے ہیں وہ قانون پر سختی سے عمل کرا کے اور مخالفت کی صورت میں سزا دے کر بُرائی کا خاتمہ کرسکتے ہیں۔ مبلغیْنِ اسلام، علماء و مشائخ، اَدیب و صحافی اور دیگر ذرائع اَبلاغ مثلًا ریڈیو اور ٹی وی وغیرہ سے سبھی لوگ اپنی تقریروں تحریروں بلکہ شعراء اپنی نظموں کے ذریعے بُرائی کا قلع قمع کریں اور نیکی کوفروغ دیں۔ بِلِسَانِہٖ (زبان سے روکنے) کے تحت یہ تمام صورتیں آتی ہیں اور عام مسلمان جسے اِقتدار کی کوئی صورت بھی حاصل نہیں اور نہ ہی وہ تحریر و تقریر کے ذریعے بُرائی کا خاتمہ کرسکتا ہے وہ دل سے اس بُرائی کو برا سمجھے، اگرچہ یہ ایمان کا کمزور ترین مرتبہ ہے۔ کیونکہ کوشش کرکے زبان سے روکنا چاہیے لیکن دل سے جب برا سمجھے گا تو یقیناً خود بُرائی کے قریب نہیں جائے گا اور اس طرح معاشرے کے بے شمار افراد خودبخود راہِ راست پرآجائیں گے۔ حدیث شریف سے یہ بات بھی واضح ہوجاتی ہے کہ جو آدمی برائی کو دل سے بھی برا نہ جانے اسے اپنے آپ کو مؤمنین میں شمارکرنے کا کوئی حق نہیں کیونکہ دل سے بُرا سمجھنے میں تو کسی کا ڈر نہیں، پھر بھی بُرا نہیں سمجھتا تو معلوم ہوا وہ اس پر راضی ہے۔ (مراٰۃ المناجیح، 6 /503، مکتبہ اسلامیہ)\n¥نیکی کی دعوت ترک کرنے کی صورت:\n علامہ ابوبکر بن علی رازی جَصَّاص رحمۃُ اللہ علیہ فرماتے ہیں: جب کوئی بُرائی کو ہاتھ اور زبان سے مِٹا نہ سکے تو اُس وقت اُس پر لازم ہے کہ اُس بُرائی کو دل میں بُراجانےاور اب اُس کے لئے خاموشی اختیار کرنا جائز ہے۔ اللہ پاک قرآنِ مجید میں ارشاد فرماتا ہے:\nعَلَیْكُمْ اَنْفُسَكُمْۚ-لَا یَضُرُّكُمْ مَّنْ ضَلَّ اِذَا اهْتَدَیْتُمْؕ (پ ۷، المآئدة:۱۰۵)\nترجمہ کنزالایمان: تم اپنی فکر رکھو تمہارا کچھ نہ بگاڑے گا جو گمراہ ہوا جب کہ تم راہ پر ہو۔\n اس آیتِ مبارکہ کی تفسیرمیں حضرت سیِّدُنا عبداللہ بن مسعود رضی اللہ عنہ فرماتے ہیں: ’’جب تک تمہاری بات کو قبول کیاجائےتم نیکی کا حکم دو اور بُرائی سے منع کرو اور جب تمہاری بات کو قبول نہ کیا جائے تو تم اپنی جان کی فکر کرو۔‘‘ اسی طرح حضرت سیِّدُناابوثعلبہ خشنی رضی اللہ عنہ نے بیان کیا ہےکہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشادفرمایا: ’’نیکی کا حکم دیتے اور برائی سے منع کرتے رہوحتّٰی کہ جب تم دیکھوکہ بخل کی اطاعت کی جارہی ہے، خواہش کی پیروی کی جارہی ہے ، دنیا کو ترجیح دی جارہی ہےاور ہرشخص اپنی رائے پر اترا رہا ہےتو پھر تم اپنی جان کی فکر کرواور لوگوں کی فکر کرناچھوڑ دو۔‘‘ اس حدیث کا مطلب یہ ہے کہ جب لوگ امربالمعروف ونہی عن المنکر کو قبول نہ کریں اور اپنی خواہشات وآراء کی اتباع کریں تو پھر تمہارےلیے اُن کو چھوڑ نے کی گنجائش ہےاور تم اپنی فکر کرواور لوگوں کو اُن کے حال پر چھوڑ دواور اس صورت میں تمہارے لئے بالقول نہی عن المنکر کو تر ک کرنامباح ہے۔\n(احکام القران للجصاص، سورة اٰل عمران، باب فرض الامربالمعروف والنھی عن المنکر، ۲/ ۴۱)\n¥بُرائی سے روکنے کی مختلف صورتیں:\n¥ صدرُالشریعہ، بدرُ الطریقہ حضرت علامہ مولانا مفتی محمد امجدعلی اعظمی رحمۃُ اللہ علیہ فرماتے ہیں کہ امر بالمعروف کی کئی صورتیں ہیں: (1)...اگر غالب گمان یہ ہے کہ یہ ان سے کہے گا تو وہ اس کی بات مان لیں گے اور بُری بات سے باز آجائیں گے، تو امر بالمعروف واجب ہے اس کا باز رہنا (یعنی بُرائی سے منع نہ کرنا)جائز نہیں۔ (2)... اگرگمان غالب یہ ہے کہ وہ طرح طرح کی تہمت باندھیں گے اور گالیاں دیں گے تو ترک کرنا (یعنی بُرائی سے منع نہ کرنا) افضل ہے۔ (3)...اگر یہ معلوم ہے کہ وہ اسے ماریں گے اور یہ صبر نہ کرسکے گا یا اس کی وجہ سے فتنہ وفساد پیدا ہوگا، آپس میں لڑائی ٹھن جائے گی جب بھی چھوڑنا (یعنی بُرائی سے منع نہ کرنا)افضل ہے۔ (4)...اگرمعلوم ہے کہ وہ اگر اسے ماریں گے تو صبر کرلے گا تو ان لوگوں کو بُرے کام سے منع کرے اور یہ شخص مجاہد ہے اور (5)...اگر معلوم ہے کہ وہ مانیں گے نہیں مگر نہ ماریں گے اور نہ گالیاں دیں گے تو اسے (بُرائی سے منع کرنے یا نہ کرنے کا)اختیار ہے اور افضل یہ ہے کہ امر کرے (یعنی بُرائی سے روکے)۔ (بہارشریعت،حصہ16، 3/ 615)\n¥برائی سے منع کرنے کی فضیلت:\n اللہ پاک قرآنِ مجید میں ارشاد فرماتا ہے:\nوَ لْتَكُنْ مِّنْكُمْ اُمَّةٌ یَّدْعُوْنَ اِلَى الْخَیْرِ وَ یَاْمُرُوْنَ بِالْمَعْرُوْفِ وَ یَنْهَوْنَ عَنِ الْمُنْكَرِؕ-وَ اُولٰٓىٕكَ هُمُ الْمُفْلِحُوْنَ(۱۰۴) (پ ۴، اٰل عمران:۱۰۴)\nترجمہ کنزالایمان: اور تم میں ایک گروہ ایسا ہونا چاہیے کہ بھلائی کی طرف بلائیں اور اچھی بات کا حکم دیں اور بُری سے منع کریں اور یہی لوگ مراد کو پہنچے۔\n حضرت سیِّدُنا لقمان حکیم رحمۃُ اللہ علیہ نے اپنے بیٹے کو نصیحت کی جسے قرآن مجید میں ان الفاظ میں بیان کیا گیا۔ چنانچہ ارشاد ہوا:\nیٰبُنَیَّ اَقِمِ الصَّلٰوةَ وَ اْمُرْ بِالْمَعْرُوْفِ وَ انْهَ عَنِ الْمُنْكَرِ وَ اصْبِرْ عَلٰى مَاۤ اَصَابَكَؕ-اِنَّ ذٰلِكَ مِنْ عَزْمِ الْاُمُوْرِۚ(۱۷) (پ ۲۱، لقمٰن:۱۷)\nترجمہ کنزالایمان: اے میرے بیٹے نماز برپا رکھ اور چھی بات کا حکم دے اور بُری بات سے منع کر اور جو افتاد (مصیبت) تجھ پر پڑے اس پر صبر کر بےشک یہ ہمت کے کام ہیں۔\nحضرت سیِّدَتُنا درہ بنت ابی لہب رضی اللہ عنہا بیان کرتی ہیں: حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم ایک مرتبہ منبر اقدس پر جلوہ فرما تھے کہ ایک صحابی رضی اللہ عنہ نے عرض کی: یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! لوگوں میں سے سب سے اچھا کون ہے؟ ارشاد فرمایا: ’’لوگوں میں وہ شخص سب سے اچھا ہے جو کثرت سے قرآنِ مجید کی تلاوت کرے، زیادہ متقی ہو، سب سے زیادہ نیکی کا حکم دینے اور برائی سے منع کرنے والا ہو اور سب سے زیادہ صلَہ رحمی کرنے والا ہو۔‘‘\n(مسند احمد، مسند القبائل، حدیث درة بنت ابی لھب، ۱۰/ ۴۰۲، حدیث:۲۷۵۰۴)\nحضرت سیِّدُنا کعب الاحبار رحمۃُ اللہ علیہ سے مروی طویل روایت میں ہے کہ اللہ پاک نے حضرت سیِّدُنا موسیٰ کَلِیْمُ اللہ علیہِ السّلام کی طرف وَحی فرمائی کہ ’’جس نے بھلائی کا حکم دیاور بُرائی سے منع کیا اور لوگوں کو میری اِطاعت کی طرف بلایا تو دنیا اور قبر میں میری رحمت اس کے شامل حال ہوگی اور قیامت کے دن وہ میرے عرش کے سائے میں ہو گا۔‘‘\n(حلیة الاولیاء وطبقات الاصفیاء، ۶/ ۳۶، رقم:۷۷۱۶)\nحضرت سیِّدُنا اامام محمد بن محمد بن محمد غزالی رحمۃُ اللہ علیہ نقل فرماتے ہیں کہ حضرت سیِّدُنا موسیٰ کَلِیْمُ اللہ علیہِ السّلام نے بارگاہِ الٰہی میں عرض کی: اے اللہ پاک! جو اپنے بھائی کو بلائے، اسے نیکی کا حکم دے اور بُرائی سے منع کرے تو اس کی جزا کیا ہے؟ اللہ پاک نے ارشاد فرمایا: ’’میں اس کی ہر بات پر ایک سال کی عبادت کا ثواب لکھتاہوں اور اسے جہنم کی سزا دینے میں مجھے حیا آتی ہے۔‘‘ (مکاشفة القلوب، ص۴۸)\n¥بُرائی سے منع نہ کرنے پر وعید:\n اللہ پاک نے بنی اسرائیل کے کافروں کے مستحق لعنت ہونے کی وجہ بیان کرتے ہوئے ارشاد فرمایا:\nلُعِنَ الَّذِیْنَ كَفَرُوْا مِنْۢ بَنِیْۤ اِسْرَآءِیْلَ عَلٰى لِسَانِ دَاوٗدَ وَ عِیْسَى ابْنِ مَرْیَمَؕ-ذٰلِكَ بِمَا عَصَوْا وَّ كَانُوْا یَعْتَدُوْنَ(۷۸) كَانُوْا لَا یَتَنَاهَوْنَ عَنْ مُّنْكَرٍ فَعَلُوْهُؕ-لَبِئْسَ مَا كَانُوْا یَفْعَلُوْنَ(۷۹) \n(پ۶، المآئدة:۷۸، ۷۹)\nترجمہ کنزالایمان: لعنت کئے گئے وہ جنہوں نے کفر کیا بنی اسرائیل میں داؤد اور عیسیٰ بن مریم کی زبان پر یہ بدلہ ان کی نافرمانی اور سرکشی کا جو بُری بات کرتے آپس میں ایک دوسرے کو نہ روکتے ضرور بہت ہی بُرے کام کرتے تھے۔\n حضرت سیِّدُنا حذیفہ بن یمان رضی اللہ عنہ سے مروی ہےکہ اللہ پاک کے آخری نبی، محمد عربی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اس ذات کی قسم!جس کے قبضَۂ قدرت میں میری جان ہے! تم ضرورنیکی کی دعوت دیتے اوربرائی سے منع کرتے رہنا (اگرتم نے ایسا نہ کیا تو)قریب ہے کہ اللہ پاک تم پر اپنا عذاب نازل فرمائے،پھرتم اس سے دعامانگتے رہو گے لیکن قبول نہ ہوگی۔‘‘ (ترمذی، کتاب الفتن، باب ماجآء فی الامر بالمعروف...الخ، ۴/ ۶۹، حدیث:۲۱۷۶)\n حضرت سیِّدُنا جریربن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے حضورنبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم کو ارشاد فرماتے سنا: ’’جس قوم میں گناہ ہوتے ہوں اور وہاں ایسے لوگ موجودہوں جو انہیں بدلنے پر قادر ہوں اورپھربھی نہ بدلیں تواُن کی موت سے پہلے اللہ پاک اُن پراپنا عذاب نازل فرمائے گا۔‘‘(ابو داود، کتاب الفتن والملاحم، باب الامر والنھی، ۴/ ۱۶۴، حدیث:۴۳۳۹)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6900, "bookId": 13, "volNo": "1", "hadithNo": 35, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "اسلامی بھائی چارہ اور مسلمان کی صفات", "arabic": "عَنْ اَبِيْ هُرَيْرَةَ رَضيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : ’’لَاتَحَاسَدُوْا وَلَاتَنَاجَشُوْا وَلَاتَبَاغَضُوْا وَلَاتَدَابَرُوْا وَلَايَبِعْ بَعْضُكُمْ عَلٰى بَيْعِ بَعْضٍ وَكُوْنُوْا عِبَادَ اللهِ اِخْوَانًا، اَلْمُسْلِمُ اَخُو الْمُسْلِـمِ، لَايَظْلِمُهٗ وَلَايَخْذُلُهٗ وَلَايَكْذِبُهٗ وَلَايَحْقِرُهٗ، اَلتَّقْوٰى هٰهُنَا.‘‘ وَيُشِيْرُ اِلٰى صَدْرِهٖ ثَلَاثَ مَرَّاتٍ. ’’بِحَسْبِ امْرِئٍ مِّنَ الشَّرِ اَن يَّحْقِرَ اَخَاهُ الْمُسْلِمَ، كُلُّ الْمُسْلِـمِ عَلَى الْمُسْلِـمِ حَرَامٌ دَمُهٗ وَمَالُهٗ وَعِرْضُهٗ.‘‘(رَوَاهُ مُسْلِم)", "urdu": "حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلم نے ارشاد فرمایا: ایک دوسرے سے حسد نہ کرو، صرف قیمت بڑھانے کے لیے بولی نہ لگاؤ، آپس میں بغض نہ رکھو، قطع تعلقی نہ کرو، تم میں سے کوئی دوسرے کے سودے پر سودا نہ کرے، اللہ کے بندو بھائی بھائی ہوجاؤ، ایک مسلمان دوسرے مسلمان کا بھائی ہے کہ نہ اس پر ظلم کرتا ہے، نہ اسے رسواکرتا ہے، نہ اس سے جھوٹ بولتا ہے اور نہ ہی اسے حقیر جانتا ہے۔آپ نے اپنے سینہ مبارک کی طرف اشارہ کرتے ہوئے تین مرتبہ ارشاد فرمایا:تقوی یہاں ہے،کسی شخص کے برا ہونے کے لیے اتنا کافی ہے کہ وہ اپنے مسلمان بھائی کو حقیر سمجھے، ہر مسلمان پر دوسرے مسلمان کا خون، مال اور عزت حرام ہے۔\n(مسلم، كتاب البر والصلة والاٰداب، باب تحريم ظلم المسلم وخذلہ واحتقاره...الخ، ص۱۰۶۴، حدیث:۶۵۴۱)", "roman": "Hazrat Sayyiduna Abu Hurairah Radiyallahu Anhu bayan karte hain ke Rasoolullah Sallallahu Alayhi wa Sallam ne irshad farmaya: Ek dusre se hasad na karo, Sarf qeemat barhane ke liye boli na lagao, aapas mein bughz na rakho, qata-e-ta'alluqi na karo, tum mein se koi dusre ke saude par sauda na kare, Allah ke bando bhai bhai ho jao, ek Musalman dusre Musalman ka bhai hai ke na is par zulm karta hai, na ise ruswa karta hai, na is se jhoot bolta hai aur na hi ise haqeer janta hai. Aap ne apne seena-e-mubarak ki taraf ishara karte hue teen martaba irshad farmaya: Taqwa yahan hai, kisi Shakhs ke bura hone ke liye itna kaafi hai ke woh apne Musalman bhai ko haqeer samjhe, har Musalman par dusre Musalman ka khoon, Maal aur izzat Haram hai. (Muslim, Kitaab-ul-Birri was-Silati wal-Aadaab, Baab tahreemi zulmil-Muslimi wa khazlihi wahtiqarihi... al-kh, s 1064, Hadees: 6541)", "explanation": "مذکورہ حدیث پاک میں بعض ظاہری وباطنی بیماریوں سے بچنے کی تعلیم دی گئی ہے۔ چنانچہ سب سے پہلے ایک مہلک مرض حسد سے بچنے کا حکم ارشاد ہوا کہ ’’ایک دوسرے سے حسد نہ کرو‘‘ آئیے حسد کے بارے میں کچھ پڑھتے سنتے ہیں۔\n¥حسد کی تعریف:\n کسی کی دینی یا دنیاوی نعمت کے زوال (یعنی چھن جانے) کی تمنا کرنا یا یہ خواہش کرنا کہ فلاں شخص کو یہ نعمت نہ ملے، اس کا نام حسد ہے۔ (حدیقة ندیة، الخلق الخامس عشر من الاخلاق ا لستین المذمومة...الخ، ۱/ ۶۰۰)\n¥قرآن وحدیث میں حسد کی مذمت:\n قرآن وحدیث میں حسد کی شدید مذمت بیان فرمائی گئی ہے۔ چنانچہ اللہ پاک ارشاد فرماتا ہے:\nاَمْ یَحْسُدُوْنَ النَّاسَ عَلٰى مَاۤ اٰتٰىهُمُ اللّٰهُ مِنْ فَضْلِهٖۚ-فَقَدْ اٰتَیْنَاۤ اٰلَ اِبْرٰهِیْمَ الْكِتٰبَ وَ الْحِكْمَةَ وَ اٰتَیْنٰهُمْ مُّلْكًا عَظِیْمًا(۵۴) (پ۵، النسآء:۵۴)\nترجمہ کنزالایمان: یا لوگوں سے حسد کرتے ہیں اس پر جو اللہ نے انہیں اپنے فضل سے دیا تو ہم نے تو ابراہیم کی اولاد کو کتاب اور حکمت عطا فرمائی اور انہیں بڑا ملک دیا۔\nسیِّدُنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ حضور نبی کریم صلّی اللہ علیہ وسلّم نے ارشاد فرمایا: ’’حسد سے بچو کہ حسد نیکیوں کو اس طرح کھاجاتا ہے جس طرح آگ خشک لکڑی کو کھا جاتی ہے۔ ‘‘(ابوداود، کتاب الادب، باب فی الحسد، ۴ / ۳۶۰ ، حدیث: ۴۹۰۳)\nحضرت سیِّدُنا معاویہ بن حیدہ رضی اللہ عنہ سے مروی ہے کہ اللہ پاک کے آخری نبی، محمد عربی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’حسد ایما ن کو اس طرح خراب کردیتاہے جس طرح ایلوا (یعنی ایک کڑوے درخت کا جما ہوا رَس) شہد کو خراب کر دیتا ہے۔‘‘ (کنزالعمال، کتاب الاخلاق، ۲/ ۱۸۶، حدیث:۷۴۳۷)\n¥حسد کا حکم:\nاگر اپنے اختیار وارادے سے بندے کے دل میں حسد کا خیال آئے اور یہ اس پر عمل بھی کرتا ہے یا بعض اَعضاء سے اس کااظہار کرتا ہے تو یہ حرام اور جہنم میں لے جانے والا کام ہے۔(حدیقة ندیة، الخلق الخامس عشر من الاخلاق ا لستین المذمومة...الخ، ۱/ ۶۰۱)\n¥خلاصہ:\nواضح رہے کہ حسد ایک موذی بیماری ہے ، اس کے نقصانات شمار سے باہر ہیں ، جب یہ بیماری کسی کو لگ جائے تو وہ کہیں کا نہیں رہتا ، اس کا نامہ اعمال نیکیوں سے بالکل خالی ہوجاتا ہے ، مسلمانوں کے درمیان نفرت کا ایک بہت بڑا سبب حسد ہے، حسد بہت سے گناہوں کا باعث ہے، حسد بندے کو بدگمانی میں مبتلا کردیتا ہے، حسد صلہ رحمی کو ختم کردیتا ہے ، حسد سے رزق میں برکت ختم ہوجاتی ہے۔ الغرض! حسد میں کوئی بھلائی اور اچھائی نہیں ہے ، حسد میں نقصان ہی نقصان ہے۔ بہت خوش نصیب ہیں وہ لوگ جو حسد کی بیماری سے پاک وصاف ہیں بلکہ رشک اور شکر جیسی دولت سے مالا مال ہیں ، کسی کے پاس نعمت دیکھ کر حسد مت کیجئے بلکہ اس کے حق میں دعا کردیجئے، اِنْ شَآءَ اللہآپ کو بھی وہ نعمت نصیب ہوجائے گی۔\nحدیث شریف میں حسد کے بعد ’’نجش‘‘ سے بچنے کا حکم دیا گیا۔ چنانچہ ارشاد ہوا \n(صرف قیمت بڑھانے کے لئے بولی نہ لگاؤ)\n¥نجش کی تعریف اور مفہوم:\nچیز بیچنے کے لئے بازار میں بولی لگائی جا رہی ہو اور کوئی شخص دوسروں کو دھوکا دینے کے لئے قیمت میں اضافہ کرے حالانکہ وہ خریدنا نہیں چاہتا تو یہ نجش ہے اور نجش حرام ہے۔ چنانچہ صدرُالشریعہ، بدرُالطریقہ حضرت علامہ مولانا مفتی محمد امجد علی اعظمی رحمۃُ اللہ علیہ فرماتے ہیں: نجش مکروہ ہے حضور اَقدس صلّی اللہ علیہ واٰلہٖ وسلّم نے اِس سے منع فرمایا۔نجش یہ ہے کہ مبیع (یعنی فروخت کی جانے والی شے)کی قیمت بڑھائے اورخود خریدنے کااِرادہ نہ رکھتا ہو۔ اس سے مقصود یہ ہوتا ہے کہ دوسرے گاہک کو رغبت پیدا ہواور قیمت سے زیادہ دے کر خریدلے اور یہ حقیقۃً خریدار کو دھوکا دینا ہے جیسا کہ بعض دُکانداروں کے یہاں اس قسم کے آدمی لگے رہتے ہیں، گاہک کو دیکھ کر چیز کے خریدار بن کر دام بڑھا دیا کرتے ہیں اور اُن کی اِس حرکت سے گاہک دھوکا کھا جاتے ہیں۔ گاہک کے سامنے مبیع کی تعریف کرنا اور اُس کے ایسے اَوصاف بیان کرنا جونہ ہوں تاکہ خریدار دھوکا کھاجائے یہ بھی نجش ہے۔ (بہار شریعت ، حصہ11، 2/ 723)\nپھر ارشاد ہوا( آپس میں بغض نہ رکھو)\n¥بغض کی تعریف اور اُس کی مذمت:\nبغض یہ ہے کہ انسان اپنے دل میں کسی کو بوجھ جانے ، اس سے غیر شرعی دشمنی رکھے ،نفرت کرے اور یہ کیفیت ہمیشہ باقی رہے۔ (احیاء العلوم، کتاب ذم الغضب والحقد والحسد، القول فی معنی الحقد...الخ، ۳/ ۲۲۳)\n قرآن وحدیث میں بغض کی شدید مذمت بیان فرمائی گئی ہے۔ چنانچہ قرآنِ پاک میں ارشاد ہوتا ہے:\nاِنَّمَا یُرِیْدُ الشَّیْطٰنُ اَنْ یُّوْقِعَ بَیْنَكُمُ الْعَدَاوَةَ وَ الْبَغْضَآءَ فِی الْخَمْرِ وَ الْمَیْسِرِ وَ یَصُدَّكُمْ عَنْ ذِكْرِ اللّٰهِ وَ عَنِ الصَّلٰوةِۚ-فَهَلْ اَنْتُمْ مُّنْتَهُوْنَ(۹۱) (پ۷، المآئدة:۹۱)\nترجمہ کنزالایمان: شیطان یہی چاہتا ہے کہ تم میں بیر اور دشمنی ڈلوا دے شراب اور جوئے میں اور تمہیں اللہ کی یاد اور نماز سے روکے تو کیا تم باز آئے۔\nامُّ المؤمنین حضرت سیِّدَتُنا عائشہ صدیقہ رضی اللہ عنہا سے مروی حدیث شریف میں ہےکہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اللہ پاک شعبان کی پندرہویں رات اپنے بندوں پر (اپنی قدرت کے شایان شان) تجلّی فرماتاہے اور مغفرت چاہنے والوں کی مغفرت فرما دیتا ہے اور رحم طلب کرنے والوں پر رحم فرماتاہے، جبکہ بغض و کینہ رکھنے والوں کو اُن کی حالت پر چھوڑ دیتا ہے۔‘‘ (شعب الایمان، باب فی الصیام، ماجاء فی لیلة...الخ،۳/۳۸۳، حدیث:۳۸۳۵ )\nحضرت سیِّدُنا ابو درداء رضی اللہ عنہ سے روایت ہے کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بغض رکھنے والوں سے بچو کیونکہ بغض دِین کو مُونڈ ڈالتا (یعنی تباہ کردیتا) ہے۔‘‘( موسوعة ابن ابی الدنیا، کتاب مدارة الناس، ۷/ ۵۴۵، حدیث:۱۴۹)\n¥بغض وکینہ کا حکم:\nکسی بھی مسلمان کے متعلق بلا وجہ شرعی اپنے دل میں بغض وکینہ رکھنا ناجائز وگناہ ہے۔ حضرت سیِّدُنا علامہ عبد الغنی نابلسی رحمۃُ اللہ علیہ فرماتے ہیں : ’’حق بات بتانے یا عدل و اِنصاف کرنے والے سے بغض و کینہ رکھنا حرام ہے۔ ‘‘\n(حدیقة ندیة، السادس العاشر من الاخلاق الستین المذمومة، ۱/ ۶۲۹)\n¥خلاصہ:\nبلا وجہ شرعی مسلمانوں سے بغض وکینہ رکھنے والوں کی کل بروزِقیامت بہت سخت پکڑ ہوگی، بلکہ بسا اوقات تو دنیا میں ہی لوگوں کو مسلمانوں سےبغض وکینہ رکھنے والوں کا عبرت ناک انجام دکھادیا جاتا ہے۔ چنانچہ حضرت سیِّدُنا عبد اللہ بن عباس رضی اللہ عنہما کی خدمت میں کچھ لوگ گھبرائے ہوئے حاضر ہوئے اور عرض کی: ہم حج کی سعادت پانے کے لئے نکلےتھے،ہمارے ساتھ ایک آدمی تھا،جب ہم ذَا الصِّفَاحْ کے مقام پر پہنچے تو اُس کا انتقال ہو گیا۔ ہم نے اُس کے غسل و کفن کا انتظام کیاپھر اُس کے لئےقبر کھودی اور اُسے دفن کرنے لگے تو دیکھا کہ اچانک اس کی قبر کالے سانپوں سے بھر گئی ہے۔ہم نے وہ جگہ چھوڑکر دوسری قبر کھودی تو دیکھتے ہی دیکھتے وہ بھی کالے سانپوں سے بھر گئی، بالآخر ہم اسے وہیں چھوڑ کر آپ کی بارگاہ میں حاضر ہوگئے ہیں۔یہ واقعہ سن کر حضرت سیِّدُنا ابنِ عباس رضی اللہ عنہما نے فرمایا:یہ اس کاکینہ ہے جووہ اپنے دل میں مسلمانوں کے متعلق رکھا کرتا تھا۔جاؤ!اور اسے وہیں دفن کردو۔(موسوعة ابن ابی الدنیا،کتاب القبور،۶/۸۳، رقم: ۱۲۸)\nپھر ارشاد ہوا( قطع تعلقی نہ کرو)\n¥قطع تعلقی سے بچنے اور صلہ رحمی کرنے کی فضیلت:\nحضرت سیِّدُنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جسے یہ پسند ہو کہ اس کی عمر میں اضافہ اور رزق میں کشادگی ہو تو اسے چاہیے کہ وہ اپنے رشتہ داروں سے تعلق جوڑے۔‘‘\n(مسلم ،کتاب البر والصلة، با ب صلة الرحم وتحریم قطیعتھا، ص۱۰۶۲، حدیث:۶۵۲۴)\nمسلمانوں کے چوتھے خلیفہ حضرت سیِّدُنا علی المرتضیٰ رضی اللہ عنہ سے روایت ہے کہ رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشادفرمایا: ’’جو اپنی عمرمیں اضافہ، رزق میں کشادگی اور بری موت سے تحفّظ چاہتا ہے وہ اللہ پاك سے ڈرے اور صلہ رحمی کرے۔‘‘ (مسند احمد، ۱/ ۳۰۲، حدیث:۱۲۱۲)\nپھر حدیث پاک میں ارشاد ہوا( تم میں سے کوئی دوسرے کے سودے پر سودا نہ کرے )\n اس سے مراد یہ ے کہ جب دو لوگ آپس میں کوئی سودا طے کر چکے ہوں تو کسی تیسرے کو بلاوجہ شرعی ان کے سودے کو ختم کروانے کی اجازت نہیں، حدیث شریف میں اسی سے منع فرمایا گیا ہے۔ چنانچہ حضرت علّامہ مولانامفتی محمد امجد علی اعظمی رحمۃُ اللہ علیہ لکھتے ہیں: ایک شخص کے د ام چکالینے کے بعد دوسرے کو دام چکا نا ممنوع ہے اس کی صورت یہ ہے کہ بائع ومشتری(یعنی خریدنے اور بیچنے والا) ایک ثَمن (قیمت) پر راضی ہوگئے صرف اِیجاب وقبول ہی یامَبِیع (یعنی بِکنے والی چیز) کو اُٹھاکر دام (قیمت) دیدینا ہی باقی رہ گیا ہے دوسرا شخص دام بڑھاکر لیناچاہتا ہے یا دام اُتنا ہی دیگا مگر دُکاندار سے اسکامَیْل (تعلق) ہے یا یہ ذِی وَجاہت (مقام ومرتبے والا)شخص ہے دُکانداراسے چھوڑ کر پہلے شخص کو نہیں دے گا (تو ان تمام صورتوں میں دوسرا سودا کرنا منع ہے) اور اگر اب تک دام طے نہیں ہوا ، ایک ثمن (قیمت)پر دونوں کی رضامندی نہیں ہوئی ہے تو دوسرے کو دام چُکا نا (یعنی قیمت طے کرنا)منع نہیں۔ (یاد رکھیئے!) جس طرح بیع میں اس کی ممانعت ہے اِجارہ (ملازمت)میں بھی ممنوع ہے مثلاً کسی مزدور سے مزدوری طے ہونے کے بعد یا ملازِم سے تنخواہ طے ہونے کے بعد دوسرے شخص کا مزدوری یا تنخواہ بڑھا کر یا اُتنی ہی دیکر مقرر کرنا (یہ بھی منع ہے)۔ جس طرح خریدار کے لئے یہ صورت ممنوع ہے بائع (بیچنے والے)کے لیے بھی ممانعت ہے مثلاً ایک دُکاندار سے دام طے ہوگئے دوسرا کہتا ہے میں اس سے کم میں دونگا یا وہ اس کا ملاقاتی ہے کہتا ہے: میرے یہاں سے لومیں بھی اتنے ہی میں دونگا، یا اجارہ میں ایک مزدور سے اُجرت طے ہونے کے بعد دوسرا کہتا ہے: میں کم مزدوری لوں گا یا میں بھی اتنی ہی لونگا، یہ سب ممنوع ہیں۔ (بہار شریعت، حصہ11، 2/723)\n¥اللہ کے بندو! بھائی بھائی ہوجاؤ:\nحکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’اللہ کے بندو بھائی بھائی ہوجاؤ ‘‘ کی شرح میں فرماتے ہیں: یعنی بدگمانی، حسد بغض وغیرہ وہ چیزیں ہیں جن سے محبت ٹوٹتی ہے اور اسلامی بھائی چارہ محبت چاہتا ہے لہٰذا یہ عیوب چھوڑو تاکہ بھائی بھائی بن جاؤ۔ (مراٰۃ المناجیح، 6/608) مراد یہ ہے کہ ایسی چیزیں اختیار کرو جن کے ذریعے بھائی چارہ قائم ہو جیساکہ حسن معاشرت، دلوں کو قریب کرنے اور دوریاں مٹانے والے کام کرو۔(الجواھر اللؤلؤیةللدمیاطی، ص۵۰۰، تحت الحدیث:۳۵) امام قرطبی رحمۃُ اللہ علیہ فرماتے ہیں: مراد یہ ہے کہ شفقت، رحمت، محبت، غمخواری، معاونت اور نصیحت کرنے میں ا یک دوسرے کے لئے نسبی بھائی کی طرح ہو جاؤ۔(المفھم لما اشکل من تلخیص کتاب مسلم، ۶/ ۵۳۲)\n¥آپس میں محبت اور بھائی چارہ قائم کرنے کا نسخہ:\n سیِّدُنا عبد اللہ بن زبیر رضی اللہ عنہ سے مروی روایت میں ہے کہ اللہ پاک کے آخری نبی صلّی اللہ علیہ وسلّم نے ارشاد فرمایا: ’’اس ذات کی قسم جس کے قبضہ میں میری جان ہے! تم اس وقت تک جنت میں داخل نہیں ہوسکتے جب تک مومن نہ ہو جاؤ اور اس وقت تک( کامل) مومن نہيں ہو سکتے جب تک آپس میں محبت نہ کرو، کیامیں تمہیں ایسی چیز نہ بتاؤں کہ جب تم اس پر عمل کرو تو آپس میں محبت کرنے لگو؟ آپس میں سلام عام کرو۔‘‘(ترمذی، کتاب صفة القیامة، ۴/ ۲۲۸، حدیث:۲۵۱۸)\n¥مسلمان مسلمان کا بھائی ہے:\nحدیث پاک میں ارشاد ہوا ’’ایک مسلمان دوسرے مسلمان کا بھائی ہے‘‘شارحین نے اس کی کئی وجوہات بیان فرمائی ہیں ، چند وجوہات درج ذیل ہیں:\n(1)... حضرت سیِّدُنا علامہ محمد بن علّان شافعی رحمۃُ اللہ علیہ فرماتے ہیں کہ دائرہ اسلام میں آنے کی وجہ سے دونوں بھائی بھائی ہوگئے، جس طرح والدین کی اولاد یا دونوں میں سے کسی ایک میں شریک اولادباہم بھائی بھائی ہوتے ہیں۔ \n(دلیل الفالحین، باب فی قضاء حوائج المسلمین، ۲/ ۳۶، تحت الحدیث:۲۴۵)\n(2)...حضرت سیِّدُنا علامہ بدرُ الدین عینی رحمۃُ اللہ علیہ فرماتے ہیں: مراد یہ ہے کہ دیْنِ اسلام میں ہونے کی وجہ سے وہ اس کا بھائی ہےاور ایسے دوافراد جن کے درمیان اتفاق پایا جائےان دونوں پر بھائی کا اطلاق ہوتاہے۔ \n(عمدةالقاری، کتاب المظالم والغضب، باب لا یظلم المسلم ولا یسلمہ، ۹/ ۱۸۸، حدیث:۲۴۴۲)\n(3)...حضرت سیِّدُنا علامہ عبد الرؤف مناوی رحمۃُ اللہ علیہ فرماتے ہیں: مسلمان مسلمان کا بھائی اس لئے ہے کہ اِن دونوں کو ایک دِین نے جمع کردیا ہے اور دینی بھائی ہونا تو حقیقی بھائی ہونے سے بھی افضل ہےکیونکہ حقیقی بھائی ہونا دُنیوی پھل جبکہ دِینی بھائی ہونا اُخروی پھل ہے۔ (التیسیر، حرف المیم، ۲/ ۴۵۶، مکتبةالامام الشافعی)\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں:مسلمان مسلمان کا دینی واسلامی بھائی ہے یا مسلمان مسلمان کے لئے سگے بھائی کی طرح ہے بلکہ اس سے بھی اہم کہ نسبی بھائی کو ماں باپ نے بھائی بنایا اور مسلمان کو حضور صلّی اللہ علیہ وسلّم نے بھائی بنایا۔ حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) سے رشتہ غلامی قوی ہے ، ماں باپ سے رشتہ نسبی ہے۔ اس سے معلوم ہواکہ حضور( صلّی اللہ علیہ واٰلہٖ وسلّم ) مسلمانوں کے بھائی نہیں ، حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) تو مثل والد کے ہیں ، اس لئے حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کی بیویاں مسلمانوں کی مائیں ہیں، بھاوج نہیں ۔ یہ بھی معلوم ہواکہ مومن و مسلم ہم معنیٰ ہیں کہ قرآنِ کریم نے مومنوں کو بھائی قرار دیا ’’ اِنَّمَا الْمُؤْمِنُوْنَ اِخْوَةٌ (پ۲۶، الحجرات:۱۰)‘‘ اور حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) نے یہاں مسلمانوں کو ۔ خیال رہے کہ یہاں بھائی ہونا رحمت و شفقت کے لحاظ سے ہے نہ کہ اَحکام کے اعتبار سے۔ (مراٰۃ المناجیح، 6/551)\n علمائے کرام فرماتے ہیں: دینی بھائی چارہ نسبی بھائی چارے سے بڑھ کر ہے، کیونکہ دینی بھائی چارے کا نفع اخروی ہے جوکہ باقی رہنے والا ہے جبکہ نسبی بھائی چارے کا نفع دنیوی ہے جوکہ فانی(یعنی ختم ہونے والا) ہے۔\n(الجواھر اللؤلؤیةللدمیاطی، ص۵۰۰، تحت الحدیث:۳۵)\n حدیث پاک میں ارشاد ہوا’’ مسلمان مسلمان کا بھائی ہے کہ نہ اس پر ظلم کرتا ہے، نہ اسے رسواکرتا ہے، نہ اس سے جھوٹ بولتا ہے اور نہ ہی اسے حقیر جانتا ہے‘‘ یعنی مسلمان میں یہ عیب نہیں ہوتے کہ یہ چیزیں دنیا و آخرت میں خسارے کا باعث ہیں۔ چنانچہ\n¥مسلمان مسلمان پر ظلم نہیں کرتا:\n حضرت سیِّدُنا محمد بن عبد اللہ دمیاطی شافعی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’مسلمان مسلمان پر ظلم نہیں کرتا‘‘ کی شرح میں فرماتے ہیں: مراد یہ ہے کہ مسلمان مسلمان کا نقصان نہیں چاہتا، نہ اس کی ذات میں، نہ اس کے دین میں، نہ اس کی عزت میں اور نہ ہی اس کے مال میں کیونکہ یہ اسلامی بھائی چارے کے منافی ہے۔نیز کہا گیا ہے کہ ظلم برکت کو ختم کردیتا ہے۔(الجواھر اللؤلؤیةللدمیاطی، ص۵۰۰، ۵۰۱، تحت الحدیث:۳۵)\n¥ظلم کی مذمت:\nحضرت سیِّدُنا عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ظلم سے بچو بلاشبہ ظلم قیامت کے دن اندھیریاں ہوگا۔‘‘ (بخاری، کتاب المظالم والغضب، باب الظلم ظلمات یوم القیامة، ۲/ ۱۲۷، حدیث:۲۴۴۷)\n حضرت سیِّدُنا ابو بکرہ رضی اللہ عنہ بیان کرتے ہیں کہ حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ ظلم وزیادتی اور قطع رحمی کے علاوہ کوئی گناہ ایسا نہیں جس کے مرتکب کو اللہ پاک آخرت میں سزا دینے کے ساتھ ساتھ دنیا میں بھی سزا دینے میں جلدی فرماتا ہو ۔‘‘ (ترمذی، کتاب صفة القیامة، باب ۵۷، ۴/ ۲۲۹، حدیث:۲۵۱۹)\n¥مسلمان مسلمان کو رسوا نہیں کرتا:\n سیِّدُنا محمد بن عبد اللہ دمیاطی شافعی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’مسلمان مسلمان کو رسوا نہیں کرتا‘‘ کے تحت فرماتے ہیں: مراد یہ ہے کہ اس کی مدد کرنا اور اسے نصیحت کرنا نہیں چھوڑتا۔(الجواھر اللؤلؤیةللدمیاطی، ص۵۰۲، تحت الحدیث:۳۵) \n نیز حضرت سیِّدُنا انس بن مالک رضی اللہ عنہ سے مروی حدیث شریف میں ہے کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اپنے بھائی کی مدد کرو چاہے وہ ظالم ہو یا مظلوم۔‘‘ عرض کی گئی: ظالم ہوتے ہوئے اس کی مدد کیسے کی جائے؟ ارشاد فرمایا: ’’اسے(ظلم سے) روکو کہ یہ بھی اس کی مدد ہے۔‘‘ (بخاری، کتاب الاکراہ، باب یمین الرجل لصاحبہ...الخ، ۴/ ۳۸۹، حدیث:۶۹۵۲)\n¥مسلمان مسلمان سے جھوٹ نہیں بولتا:\n حضرت سیِّدُنا محمد بن عبد اللہ دمیاطی شافعی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’مسلمان مسلمان سے جھوٹ نہیں بولتا‘‘ کے تحت فرماتے ہیں: مراد یہ ہے کہ اسے کسی خلاف واقع بات کے بارے میں نہیں بتاتا کیونکہ یہ دھوکا اور خیانت ہے۔ (الجواھر اللؤلؤیةللدمیاطی، ص۵۰۳، تحت الحدیث:۳۵)\n حضرت سیِّدُنا عبد اللہ بن عمر رضی اللہ عنہما سے مروی روایت میں ہے کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بندہ جب جھوٹ بولتا ہے تو اس کی بدبو سے فرشتہ اس سے ایک میل دور ہو جاتا ہے۔‘‘\n(ترمذی، کتاب البر والصلة، باب ماجآء فی الصدق والکذب، ۳/ ۳۹۲، حدیث:۱۹۷۹) \n¥مسلمان کو حقیر نہ جانو:\nحضرت سیِّدُنا محمد بن عبد اللہ دمیاطی شافعی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’مسلمان مسلمان کو حقیر نہیں جانتا‘‘ کے تحت فرماتے ہیں: مراد یہ ہے کہ نہ تو اس کی شان اور مرتبے کو کمتر سمجھے اور نہ ہی اس کی طرف حقارت کی نظر سے دیکھے کیونکہ ہوسکتا ہے اللہ پاک کی بارگاہ میں وہ بہتر وافضل مقام ومرتبے میں ہو۔ نیز مشائخ فرماتے ہیں کہ ’’جو اپنے بھائی کو حقارت کی نظر سے دیکھتا ہے اس کا انجام ذلت ورسوائی ہوتا ہے۔‘‘ (الجواھر اللؤلؤیةللدمیاطی، ص۵۰۵، تحت الحدیث:۳۵)\n حضرت سیِّدُنا علامہ محمد بن علّان شافعی رحمۃُ اللہ علیہ مذکورہ جز کے تحت فرماتے ہیں: حقیر نہ جاننے سے مراد یہ ہے کہ اسے چھوٹا نہ سمجھے اور اس کی قدر ومنزلت کو نہ گھٹائے کیونکہ جب ربّ کریم نے اسے پیدا فرمایا تَو اس کی تحقیر نہ فرمائی بلکہ اسے رِفعت وبلندی عطا فرمائی، اس سے خطاب فرمایا اور اسے اَحکامِ شرعیہ کا مکلف بنایا، لہٰذا اب جو بھی اُس کی تحقیر کرے گا گویا وہ ربِّ کریم کی حد بندی سے تجاوز کرے گا اور اللہ پاک کی حَد سے تجاوز کرناایک بہت بڑا گناہ اور بُرائی ہے۔ اسی وجہ سے یہ فرمایا گیا کہ’’کسی شخص کے برا ہونے کے لئے یہی کافی ہے کہ وہ اپنے مسلمان بھائی کو حقیر جانے۔‘‘\n(دلیل الفالحین، باب فی تعظیم حرمات المسلمین...الخ، ۲/ ۲۴، تحت الحدیث:۲۳۶)\n حضرت سیِّدُنا علامہ علی قاری رحمۃُ اللہ علیہ مذکورہ جز کی شرح کرتے ہوئے فرماتے ہیں: کسی بھی مسلمان کو حقیر نہ جاننے سے مراد یہ ہے کہ اُس کے عیبوں کا ذکر نہ کرے، اُس کے بُرے بُرے نام نہ رکھے، اُس کے ساتھ مذاق نہ کرے، جب اُسے مفلوکُ الحال دیکھے یا کسی بیماری میں مبتلا دیکھے یا اُسے بات کرنا نہ آتی ہو تو اُس پر طنز کے طور پر نہ ہنسے، کیونکہ ہوسکتا ہے کہ اُس کا ضمیر زیادہ مخلص ہو اور وہ قلبی طور پر زیادہ متقی ہوایسے شخص سے جس میں اِس کے برعکس صفات پائی جاتی ہوں، لہٰذاجسے اللہ پاک نے تقویٰ دے کر عزت بخشی ہے اُس کی تحقیر کرکے بندہ اپنے آپ پر ہی ظلم کرے گا۔\n(مرقاةالمفاتیح، کتاب الاٰداب، باب الرحمة والشفقة علی الخلق، ۸/ ۶۹۰، تحت الحدیث:۴۹۵۹)\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں: یعنی مسلمان کو نہ تو دل میں حقیر جانو نہ اسے حقارت کے الفاظ سے پکارو یا بُرے لقب سے یاد کرو نہ اس کا مذاق بناؤ آج ہم میں یہ عیب بہت ہے۔پیشوں،نسبوں،یا غربت و افلاس کی وجہ سے مسلمان بھائی کو حقیر جانتے ہیں حتی کہ صوبہ جاتی تعصب ہم میں بہت ہوگیا کہ وہ پنجابی ہے،وہ بنگالی، وہ سندھی،وہ سرحدی،اسلام نے یہ سارے فرق مٹادیئے۔شہد کی مکھی مختلف پھولوں کے رس چوس لیتی ہے تو ان کا نام شہد ہوجاتا ہے، مختلف لکڑیوں کو آگ جلادے تو اس کا نام راکھ ہوجاتا ہے،آم،جامن،ببول کا فرق مٹ جاتا ہے یوں ہی جب حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کا دامن پکڑ لیا تو سب مسلمان ایک ہوگئے حبشی ہو یا رومی۔ (مراٰۃ المناجیح، 6/552)\n¥تقویٰ وپرہیزگاری کا مرکز:\n ’’ آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے اپنے سینہ مبارک کی طرف اشارہ کرتے ہوئے تین مرتبہ فرمایا:تقوی یہاں ہے ‘‘: یعنی اسلام میں عزت تقویٰ و پرہیزگاری سے ہے اور تقویٰ کا اصلی ٹھکانہ دل ہے۔تمہیں کیا خبر کہ جس مسکین مسلمان کو تم حقیر سمجھتے ہو اس کا دل تقویٰ کی شمع سے روشن ہو اور وہ اللہ (پاک) کا پیارا ہو تم سے اچھا ہو۔ صوفیاء کرام اِس جملہ کے معنیٰ یہ کرتے ہیں کہ حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) نے اپنے سینے کی طرف اِشارہ کرکے فرمایا کہ تقویٰ و پرہیزگاری یہاں ہے یعنی تقویٰ کی کان اور پرہیزگاری کا مرکز میرا سینہ ہے۔ میرے سینے سے تمام اولیاء و علماءکے دلوں کی طرف تقویٰ کے دریا بہتے ہیں۔ پھر اُن کے سینوں سے عوام کے سینوں کی طرف تقویٰ کی نہریں نکلیں۔ حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کا سینہ کشف غیوب (یعنی پوشیدہ باتوں کے ظاہر ہونے) کا آئینہ ہے ، کونین یعنی سارے عالَم میں حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) کی عطائیں بہتی ہیں۔\n(مراٰۃ المناجیح، 6/552 تا 553، ملتقطاً)\n¥تقویٰ کی جگہ دل کیوں ہے؟\n حضرت سیِّدُنا علامہ محمد بن علّان شافعی رحمۃُ اللہ علیہ فرماتے ہیں: حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے تقویٰ کی جگہ دل بتائی کیونکہ تقویٰ خوف سے حاصل ہوتا ہے اور خوف دل میں ہی ہوتا ہے۔ نیز آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بےشک اللہ پاک تمہارے جسموں اور تمہاری صورتوں کی طرف نہیں بلکہ وہ تو تمہارے دِلوں کی طرف دیکھتا ہے۔‘‘\n(دلیل الفالحین، باب فی تعظیم حرمات المسلمین، ۲/ ۲۴، تحت الحدیث:۲۳۶)\n¥متقی وپرہیزگارشخص کسی کی تحقیر نہیں کرتا:\n مرقاۃ المفاتیح میں ہے: جو مسلمان اپنے آپ کو شرک اور گناہ سے بچائے تو اس کی تحقیر کرنا جائز نہیں اور تقویٰ کا محل دل ہے اور جس چیز کا محل دل ہو ، وہ لوگوں کی نظروں سے پوشیدہ ہوتی ہے تو جب تقویٰ نظروں سے پوشیدہ ہے تواب کسی کے لئے یہ جائز نہیں کہ وہ کسی مسلمان میں تقویٰ نہ ہونے کا حکم لگائے اور اس کی تحقیر کرے۔ اس جملے کا ایک معنیٰ یہ بھی بیان کیا گیاہے کہ جس کے دل میں تقویٰ ہوتو وہ کسی مسلمان کی تحقیر نہیں کرسکتا کیونکہ متقی شخص کبھی کسی مسلمان کی تحقیر نہیں کر تا۔(مرقاةالمفاتیح، کتاب الاٰداب، باب الرحمة والشفقة علی الخلق، ۸/ ۶۹۰، تحت الحدیث:۴۹۵۹)\n¥تقویٰ کیا ہے؟\n تقویٰ کیا ہے؟ اس کے بارے میں علمائے کرام رحمۃُ اللہ علیہم نے مختلف اَقوال بیان فرمائے ہیں۔ چنانچہ حضرت سیِّدُنا علامہ محمد بن علّان شافعی رحمۃُ اللہ علیہ فرماتے ہیں: اللہ پاک نے جن کاموں کو کرنے کا حکم دیا ہے اُن کو کرکے اور جن سے منع فرمایا ہے اُن کو نہ کرکے اپنے آپ کو اس کے عذاب سے بچانے کا نام تقویٰ ہے۔‘‘\n(دلیل الفالحین، باب فی تعظیم حرمات المسلمین...الخ، ۲/ ۲۴، تحت الحدیث:۲۳۶)\n حضرت سیِّدُنا علامہ ابو القاسم عبد الکریم بن ہوازن قشیری رحمۃُ اللہ علیہ فرماتے ہیں: ’’تقویٰ تمام نیکیوں کا مجموعہ ہے، تقویٰ کی حقیقت یہ ہے کہ آدمی اللہ پاک کی اطاعت کے ساتھ اس کے عذاب سے بچے۔ تقویٰ کی اصل شرک سے بچنا ، پھر گناہوں اور بُرائیوں سے بچنا ، اس کے بعد شبہات سے بچنا اور پھر فضول باتوں کو ترک کرنا ہے۔ حضرت سیِّدُنا ابو علی دقاق رحمۃُ اللہ علیہ فرماتے ہیں: تقویٰ کی ہر قسم کا الگ باب ہے اور قرآن پاک میں جو یہ فرمایا گیا کہ ’’اللہ سے ڈرو جیسا اس سے ڈرنے کا حق ہے‘‘ اس کی تفسیر میں یہ بھی آیا ہے کہ اللہ پاک کی اطاعت کی جائے ، اُس کی نافرمانی نہ کی جائے ، اُسے یاد رکھا جائے، بھلایا نہ جائے ، اُس کا شکر ادا کیا جائے، ناشکری نہ کی جائے۔ (الرسالةالقشیریة، باب التقوی، ص۱۴۲)\n¥انسان کے برا ہونے کی علامت:\n ’’کسی شخص کے برا ہونے کے لیے اتنا کافی ہے کہ وہ اپنے مسلمان بھائی کو حقیر سمجھے، ہر مسلمان پر دوسرے مسلمان کا خون، مال اور عزت حرام ہے‘‘یعنی کوئی مسلمان کسی مسلمان کا مال بغیر اس کی اجازت نہ لے،کسی کی آبروریزی نہ کرے،کسی مسلمان کو ناحق اور ظلمًا قتل نہ کرے کہ یہ سب سخت جرم ہیں۔ (مراٰۃ المناجیح، 6/ 553)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6901, "bookId": 13, "volNo": "1", "hadithNo": 36, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "حاجت روائی اور حصول علم کی فضیلت", "arabic": "عَنْ اَبِيْ هُرَيْرَةَ رَضيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’مَنْ نَفَّسَ عَنْ مُّؤمِنٍ كُرْبَةً مِّنْ كُرَبِ الدُّنيَا نَفَّسَ اللهُ عَنْهُ كُرْبَةً مِّنْ كُرَبِ يَوْمِ الْقِيَامَةِ وَمَنْ يَّسَّرَ عَلٰى مُعْسَرٍ يَّسَّرَ اللهُ عَلَيهِ فِي الدُّنْيَا وَالْاٰخِرَةِ وَمَنْ سَتَـرَ مُسلِمًا سَتَـرَهُ اللهُ فِيْ الدُّنْيَا وَالْاٰخِرَةِ وَاللهُ فِيْ عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِيْ عَوْنِ اَخِيْهِ وَمَنْ سَلَكَ طَرِيْقًا يَّلْتَمِسُ فِيْهٖ عِلْمًا سَهَّلَ اللهُ لَهٗ بِهٖ طَرِيْقًا اِلَى الْجَنَّةِ وَمَا اجْتَمَعَ قَوْمٌ فِيْ بَيْتٍ مِّنْ بُيُوْتِ اللهِ يَتْلُوْنَ كِتَابَ اللهِ وَيَتَدَارَسُوْنَهٗ بَيْنَهُمْ اِلَّا نَـزَلَتْ عَلَيْهِمُ السَّكِيْنَةُ وَغَشِيَتْهُمُ الرَّحْمَةُ وَحَفَتْهُمُ الْمَلَآئِكَةُ وَذَكَرَهُمُ اللهُ فِيْمَنْ عِنْدَهٗ وَمَنْ بَطَّاَ بِهٖ عَمَلُهٗ لَمْ يُسْرِعْ بِهٖ نَسَبُهٗ.‘‘(رَوَاهُ مُسْلِمٌ بِهٰذَا اللّفْظ)", "urdu": "حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جس نے کسی مومن سے دنیا کی کوئی پریشانی دور کی تو اللہ پاک قیامت کے دن کی پریشانیوں میں سےاس کی ایک پریشانی دور فرمائے گااورجس نے کسی تنگ دست پر آسانی کی تو اللہ پاک اس پردنیا و آخرت میں آسانی فرمائے گا اور جس نے کسی مسلمان کی پردہ پوشی کی تو اللہ پاک دنیا و آخرت میں اس کی پردہ پوشی فرمائے گا۔ اللہ پاک اپنے بندے کی مدد فرماتا رہتا ہے جب تک بندہ اپنے بھائی کی مدد کرتا رہتا ہے اور جو شخص علم کی تلاش میں کسی راستے پر چلتا ہے تو اللہ پاک اس کے سبب اس کے لئے جنت کا راستہ آسان فرمادیتا ہے اور جو لوگ اللہ پاک کے گھروں میں سے کسی گھر (یعنی مسجد)میں جمع ہو کر قرآنِ پاک کی تلاوت کرتے اور پڑھتے پڑھاتے ہیں تو ان پر سکینہ نازل ہوتا ہے، رحمت انہیں ڈھانپ لیتی ہے اور فرشتے انہیں گھیرلیتے ہیں اور اللہ پاک اپنی بارگاہ میں موجود فرشتوں کے سامنے ان کا تذکرہ فرماتا ہےاور جس کا عمل اسے پیچھے کردے تو اُس کا نسب اسے آگے نہیں بڑھا سکتا۔‘‘\n( مسلم، كتاب الذكر والدعاء والتوبة...الخ، باب فضل الاجتماع على تلاوة القراٰن وعلى الذكر، ص۱۱۱۰، حدیث:۶۸۵۳)", "roman": "Hazrat Sayyiduna Abu Hurairah Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne irshad farmaya: 'Jis ne kisi Momin se duniya ki koi pareshani door ki to Allah Paak Qayamat ke din ki pareshaniyon mein se us ki ek pareshani door farmaye ga aur jis ne kisi tang dast par aasani ki to Allah Paak us par duniya o Aakhirat mein aasani farmaye ga aur jis ne kisi Musalman ki Pardah poshi ki to Allah Paak duniya o Aakhirat mein us ki Pardah poshi farmaye ga. Allah Paak apne bande ki madad farmata rehta hai jab tak banda apne bhai ki madad karta rehta hai aur jo Shakhs Ilm ki talash mein kisi raaste par chalta hai to Allah Paak us ke sabab us ke liye Jannat ka raasta aasaan farma deta hai aur jo log Allah Paak ke gharon mein se kisi ghar (yani Masjid) mein jama ho kar Quraan-e-Paak ki tilawat karte aur parhte parhate hain to un par Saki na nazil hota hai, Rahmat unhein dhanp leti hai aur farishtay unhein gher lete hain aur Allah Paak apni bargah mein majood farishton ke samne un ka tazkira farmata hai aur jis ka amal use peeche kar de to us ka Nasab use aage nahi barha sakta.' (Muslim, Kitaab-uz-Zikri wad-Du'a wat-Tawbati... al-kh, Baab fazlil-ijtima'i ala tilawatil-Quraani wa ala-Zikr, s 1110, Hadees: 6853)", "explanation": "¥عظيم كام:\n حضرت سیِّدُنا علامہ محمد بن علّان شافعی رحمۃُ اللہ علیہ مذکورہ حدیث شریف کی شرح میں فرماتے ہیں: اِس حدیث پاک میں مسلمانوں کی حاجت روائی ، اپنے علم ، مال ، مَقام ومَرتبے ، نصیحت ، اچھے کام کی طرف رہنمائی ، خود مدد کرنے یا کسی کے ذریعے مدد کرنے یا کسی کی مدد کی سفارش کرنے یا مدد کا وسیلہ بننے یا اس کے لئے مدد کی دعا کردینے کی عظیم فضیلت کا بیان ہے۔ کسی بھی تنگدست مسلمان پر کشادگی سے مراد یہ ہے کہ یا تو اسے کوئی چیز ہبہ کرکے اُس پر کشادگی کرے یا اس پر صدقہ کرکے کشادگی کرے یا قرض دار ہونے کی صورت میں اُس کو مزید مہلت دے کر اس پر کشادگی کرے۔ اسی طرح اپنے مسلمان بھائی کی مدد کرنے سے مراد یہ ہے کہ اس کی قلبی یا بدنی یامالی طور پر مدد کرے۔ جب بندہ اپنے کسی مسلمان بھائی کی مدد کرنے کا ارادہ کرلے تو اسے چاہیے کہ اب وہ اپنے ارادے کو عملی جامہ پہنانے، حق بات کا اقرار کرنے اور اس مدد کو ہمیشہ قائم رکھنے میں کسی بزدلی کا مظاہرہ نہ کرے۔ مزید فرماتے ہیں: ایک بار حضرت سیِّدُنا حسن بصری رحمۃُ اللہ علیہ نے حضرت سیِّدُنا ثابت بنانی رحمۃُ اللہ علیہ سے کسی حاجت کے لئے ساتھ چلنے کا کہاتو انہوں نے کہا: میں تو معتکف ہوں۔ اس پر حضرت سیِّدُنا حسن رحمۃُ اللہ علیہ نے فرمایا: ’’کیاتم نہیں جانتے کہ تمہارا کسی مسلمان کی حاجت روائی کے لیے چلنا تمہارے لئے بار بارحج کرنے سے بھی افضل ہے۔‘‘ حصولِ علم کے لیے کسی راستے پر چلنے میں تمام مَعنوی اُمور یعنی علم کو حفظ کرنا ، علمی مذاکرے کرنا ، علم کے لئے مطالعہ کرنا، اس کو سمجھنا اور ہر وہ کام جو علم کے حُصول کا ذریعہ ہو وہ سب اس میں شامل ہے۔\n(دلیل الفالحین، باب فی قضاء حوائج المسلمین...الخ، ۲/ ۳۷، تحت الحدیث:۲۳۶)\n¥مختلف علوم، قواعد اور آداب کا مجموعہ:\n حضرت سیِّدُنا علامہ ابو زکریا یحییٰ بن شرف نووی رحمۃُ اللہ علیہ فرماتے ہیں:یہ بہت عظیم حدیث پاک ہے ، مختلف علوم ، قواعد اور آداب کا مجموعہ ہے۔اِس میں مسلمانوں کی حاجت روائی کرنے اور اُنہیں اپنے علم، مال، مدد، مصلحت یا نصیحت وغیرہ کے ذریعے نفع پہنچانے کی فضیلت بیان کی گئی ہے۔ نیز اِس میں مسلمانوں کی ستر پوشی ، تنگدستوں پر کشادگی اور علم حاصل کرنے کی طلب میں کسی راستے پر چلنے کی فضیلت بھی بیان کی گئی ہے۔ یہاں عِلمِ شرعی کے حُصول میں مَشغولیت اِس شرط کے ساتھ مقید ہے کہ اس سے فقط اللہ پاک کی رضا مقصود ہو، اگرچہ یہ شرط ہرعبادت کے لئے ہے لیکن علم کے ساتھ خاص طور پر اسے ذکر کرنے کی وجہ یہ ہے کہ بعض لوگ اس میں سُستی کرتے ہیں اور بعض ابتدائی طور پر علم حاصل کرنے والے اس مقصد سے غافل ہوتے ہیں۔ نیز مسجد میں اجتماعی طور پر تلاوتِ قرآن کی فضیلت بھی بیان کی گئی ہےاور یہ جو فرمایا گیا کہ جس کا عمل اسے پیچھے رکھے اس کا نسب اسے آگے نہیں پہنچا سکتا اس سے مراد یہ ہے کہ جس کے اَعمال ناقص ہوں تو وہ نیک اعمال کرنے والوں کے مَراتب تک نہیں پہنچ سکتا ، لہذا ایسے شخص کو چاہیے کہ وہ فقط اپنے نسب اور آباء واجداد کی فضیلت پر بھروسا نہ کرے اور نہ ہی عمل میں کوئی کوتاہی کرے۔ \n(شرح مسلم، کتاب الذکر والدعا...الخ، باب فضل الاجتماع علی تلاوةالقراٰن...الخ، الجزء السابع عشر، ۹/ ۲۱، ۲۳، ملتقطًا)\n¥مومن کی دنیاوی پریشانی دور کرنا:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’جس نے کسی مومن سے دنیا کی کوئی پریشانی دور کی تو اللہ پاک قیامت کے دن کی پریشانیوں میں سےاس کی ایک پریشانی دور فرمائے گا‘‘ کی شرح میں فرماتے ہیں:یعنی تم کسی کی فانی مصیبت دفع کرو اللہ (پاک) تم سے باقی مصیبت دفع فرمائے گا، تم مومن کو فانی دنیوی آرام پہنچاؤ اللہ (پاک) تمہیں باقی اُخروی آرام دے گا، کیونکہ بدلہ احسان کا احسان ہے۔ یہ حدیث بہت جامع ہے۔ کسی مسلمان کے پاؤں سے کانٹا نکالنا بھی ضائع نہیں جاتا،حدیث کا مطلب یہ نہیں ہے کہ صرف قیامت ہی میں بدلہ ملے گا بلکہ قیامت میں بدلہ ضرور ملے گا اگرچہ کبھی دنیا میں بھی مل جائے۔ (مراٰۃ المناجیح، 1/189)\n حضرت سیِّدُنا علامہ ملّا علی قاری رحمۃُ اللہ علیہ فرماتے ہیں: مومن اگرچہ فاسق ہو اس کے ایمان کی رعایت کرتے ہوئے فانی دنیا کی کوئی پریشانی، غم یا سختی دور کی اگرچہ چھوٹی سی ہو (تو اللہ پاک قیامت کی پریشانیوں میں سے اس کی ایک پریشانی دور فرمائے گا)۔(مرقاةالمفاتیح، کتاب العلم، الفصل الاول ، ۱/ ۴۵۴، تحت الحدیث:۲۰۴)\n¥تنگدست پر آسانی کرنے کی فضیلت:\nحضرت سیِّدُنا بریدہ رضی اللہ عنہ سے مروی ہے کہ اللہ پاک کے سب سے آخری نبی، محمد عربی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جس نے قر ض کی ادا ئیگی کے وقت سے پہلے تنگدست کو مہلت دی اسے رو زانہ اتنامال صدقہ کرنے کا ثواب ملے گا اور جس نے وقْتِ ادائیگی کے بعد مہلت دی تو اسے روزانہ اس سے دُگنا مال صدقہ کرنے کا ثوا ب ملے گا۔‘‘\n(مجمع الزوائد، کتاب البیوع، با ب فی من فر ج عن معسر...الخ، ۴/ ۲۴۲، حدیث:۶۶۷۶)\nحضرت سیِّدُنا عبد اللہ بن عمر رضی اللہ عنہما سے مروی ہے کہ اللہ پاک کے پیارے رسول صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جواس بات کو پسند کرتا ہے کہ اس کی دعائیں قبول ہوں اور پر یشا نیاں دور ہوں تو اسے چاہیے کہ تنگدست کومہلت دیاکرے۔‘‘ (مجمع الزوائد، کتا ب البیوع ،با ب فی من فرج عن معسر...الخ ، ۴/ ۲۳۹، حدیث:۶۶۶۴)\n¥مسلمان کی پردہ پوشی کرنا:\nمفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’جس نے کسی مسلمان کی پردہ پوشی کی تو اللہ پاک دنیا و آخرت میں اس کی پردہ پوشی فرمائے گا‘‘ کی شرح میں فرماتے ہیں: اس طرح کہ ننگے (بےلباس) کو کپڑے پہنائے یا ایسے کہ اس کے چھپے ہوئے عیب ظاہر نہ کرے بشرطیکہ اس ظاہر نہ کرنے سے دین یا قوم کا نقصان نہ ہو ورنہ ضرور ظاہرکردے، کفار کے جاسوسوں کو پکڑوائے،خفیہ سازش کرنے والوں کے رازکو طشت ازبام (فاش) کرے، ظلمًا قتل کی تدبیرکرنے کی مظلوم کو خبر دے دے، اخلاق اورہیں معاملات اورسیاسیات کچھ اور۔(مراٰۃ المناجیح، 1/189)\n¥پردہ پوشی کی فضیلت:\nحضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ اللہ پاک کے آخری نبی، محمد عربی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو بندہ دنیا میں کسی بندے کی پردہ پوشی کرےگا اللہ پاک قیا مت کے دن اس بندے کی پردہ پوشی فرمائے گا۔‘‘\n(مسلم، کتاب البروالصلة والاٰداب،باب بشارة فی ستر اللّٰہ تعالٰی عیبہ، ص۱۰۷۲، حدیث:۶۵۹۵)\n حضرت سیِّدُنا عبد اللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو اپنے بھائی کی پردہ پوشی کرےگا اللہ پاک قیامت کے دن اس کی پردہ پوشی فرمائے گا اور جو اپنے بھائی کے راز کھو لے گا اللہ پاک اس کا راز ظاہر کردے گا یہا ں تک کہ وہ اپنے گھر ہی میں رُسوا ہوجائے گا۔‘‘\n(ابن ماجہ، کتاب الحدود ،باب الستر علی المومن...الخ، ۳/ ۲۱۹، حدیث:۲۵۴۶)\n¥اللہ پاک کی مدد شامِلِ حال رہے:\n’’اللہ پاک اپنے بندے کی مدد فرماتا رہتا ہے جب تک بندہ اپنے بھائی کی مدد کرتا رہتا ہے‘‘یہ الفاظ بہت جامع ہیں جس میں دین ودنیا کی ساری اِمدادیں شامل ہیں، اِمداد بدن سے ہویاعلم یا مال وغیرہ سے۔(مراٰۃ المناجیح، 1/189)\n¥مسلمان کی مدد کرنے کی فضیلت:\nحضرت سیِّدُنا عبد اللہ بن عمر رضی اللہ عنہما سے مروی ہے کہ رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بندہ جب تک اپنے بھائی کی حاجت پوری کرنے میں رہتاہے اللہ پاک اس کی حاجت پوری فرماتارہتا ہے۔‘‘\n(بخاری، کتاب المظالم والغضب، باب لایظلم المسلم المسلم ولا یسلمہ، ۲/ ۱۲۶، حدیث:۲۴۴۲)\nحضرت عبد اللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اللہ پاک کی مخلوق میں سے چند لوگ ايسے ہيں جنہیں اس نے لوگوں کی حاجت روائی کے لئے پیدا فرمایا ہے لوگ اپنی حاجتوں میں ان کا سہارا لیتے ہیں، بےشک وہی لوگ عذاب سے امن والے ہیں۔‘‘ (معجم کبیر، ۱۲/ ۲۷۴، حدیث:۱۳۳۳۴)\n¥علم کی جستجو میں رہنے والا:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’ جو شخص علم کی تلاش میں کسی راستے پر چلتا ہے تو اللہ پاک اس کے سبب اس کے لئے جنت کا راستہ آسان فرمادیتا ہے‘‘ کی شرح میں فرماتے ہیں: یعنی جو عِلمِ دین سیکھنے یا دینی فتویٰ حاصل کرنے کے لیے عالِم کے گھر جائے سفرکر کے یا چند قدم تو اس کی برکت سے اللہ (پاک) دنیا میں اس پر جنت کے کام آسان کرے گا،مرتے وقت ایمان نصیب کرے گا،قبرو حشر کے حساب میں کامیابی اور پل صراط پر آسانی عطا فرمائے گا، جنت کے راستے میں سب چیزیں داخل ہیں۔اس سے معلوم ہوا کہ علم کے لئے سفر کرنا بہت ثواب ہے۔ (حضرت سیِّدُنا)موسیٰ علیہ السّلام طلب علم کے لئے (حضرت سیِّدُنا)خضر علیہ السّلام کے پاس سفر کرکے گئے۔ حضرت جابر ( رضی اللہ عنہ ) ایک حدیث کے لئے ایک ماہ کا سفر طے کرکے (حضرت سیِّدُنا) عبداللہ ابن قیس ( رضی اللہ عنہ ) کے پاس پہنچے۔(مراٰۃ المناجیح، 1/189)\n¥علم اور عالِم دین کی فضیلت:\n قرآن وحدیث میں عالم دین کے بڑے فضائل بیان ہوئے۔ چنانچہ اللہ پاک ارشاد فرماتا ہے:\nیَرْفَعِ اللّٰهُ الَّذِیْنَ اٰمَنُوْا مِنْكُمْۙ-وَ الَّذِیْنَ اُوْتُوا الْعِلْمَ دَرَجٰتٍؕ (پ۲۸، المجادلة:۱۱)\nترجمہ کنزالایمان: اللہ تمہارے ایمان والوں کے اور ان کے جن کو علم دیا گیا درجے بلند فرمائے گا۔\nحضرت سیِّدُنا ابواُمَامَہ باہلی رضی اللہ عنہ سے مروی روایت میں ہے کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’عالِم کی فضیلت عابد پر ایسی ہے جیسی میری فضیلت تمہارے ادنیٰ پر۔‘‘\n(ترمذی ، کتاب العلم، باب ماجاء فی فضل الفقہ...الخ، ۴/ ۳۱۳، حدیث:۲۶۹۴)\nحضرت سیِّدُنا حذیفہ بن یمان رضی اللہ عنہ بیان کرتے ہیں کہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے مجھ سے ارشاد فرمایا: ’’علم کی فضیلت عبادت کی فضیلت سے بڑھ کر ہے اور تمہارے دین کا بہترین عمل پرہیزگاری ہے۔‘‘\n(معجم اوسط، من اسمہ علی، ۳/ ۹۲، حدیث:۳۹۶۰)\nحضرت سیِّدُنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو شخص علم کی طلب میں نکلا تو لوٹ آنے تک وہ اللہ پاک کی راہ میں ہے۔‘‘\n(ترمذی ، کتاب العلم، باب ماجاء فی فضل طلب العلم، ۴/ ۲۹۴، حدیث:۲۶۵۶)\nحضرت سیِّدُنا سخبرہ رضی اللہ عنہ سے مروی ہے کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو شخص علم حاصل کرتا ہے تو یہ اس کے پچھلے گناہوں کا کفارہ ہو جاتا ہے۔‘‘(ترمذی ، کتاب العلم، باب ماجاء فی فضل طلب العلم، ۴/ ۲۹۵، حدیث:۲۶۵۷)\n حضرت سیِّدُنا صفوان بن عسال مرادی رضی اللہ عنہ سے مروی ہے کہ رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو شخص علم کی طلب میں گھر سے نکلتا ہے تو فرشتے اس کے اس عمل سے خوش ہو کر اس کے لئے اپنے پَر بچھا دیتے ہیں۔‘‘\n(ابن ماجة، کتاب السنة، باب فضل العلماء...الخ ، ۱/ ۱۴۸، حدیث:۲۲۶)\nحضرت سیِّدُنا عبد اللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ایک فقیہ شیطان پر (غیر عالِم)ہزار عبادت گزاروں سے زیادہ سخت ہے۔‘‘\n(ترمذی ، کتاب العلم، باب ماجاء فی فضل الفقہ...الخ ، ۴/ ۳۱۲، حدیث:۲۶۹۰)\nحضرت سیِّدُنا جابر بن عبد اللہ رضی اللہ عنہ فرماتے ہیں کہ سرکار مدینہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’قیامت کے دن عالِم اور عبادت گزار کواٹھایا جائے گا تو عابد سے کہا جائے گا کہ جنت میں داخل ہوجاؤ جبکہ عالِم سے کہا جائے گا کہ جب تک لوگوں کی شفاعت نہ کرلو ٹھہرے رہو۔‘‘(شعب الایمان، باب فی طلب العلم، ۲/ ۲۶۸، حدیث:۱۷۱۷)\n¥قرآن پڑھنے پڑھانے کے لئے جمع ہونا:\n’’جو لوگ اللہ پاک کے گھروں میں سے کسی گھر (یعنی مسجد)میں جمع ہو کر قرآنِ پاک کی تلاوت کرتے اور پڑھتے پڑھاتے ہیں‘‘ کی شرح میں ہے: یہاں اللہ کے گھر سے مراد مسجدیں، دینی مدرسے اورصوفیاء کی خانقاہیں ہیں، جو اللہ کے ذکر کے لئے وقف ہیں۔ یہود ونصاریٰ کے عبادت خانے اس سے خارج ہیں کہ وہاں تو مسلمان کو بلاضرورت جانا ہی منع ہے۔ درسِ قرآن سے مراد قرآن شریف کی تلاوت،تجوید، احکام سیکھنا ہیں لہٰذا اس میں صَرف، نحو، فقہ، حدیث، تفسیر وغیرہ کے درس شامل ہیں۔جیساکہ مرقاۃ وغیرہ میں ہے،اسی لئے تلاوت کے بعد درس کا علیحدہ ذکر فرمایا۔(مراٰۃ المناجیح، 1/190)\n¥محبوب ترین جگہیں اور بدترین مقامات:\nحضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اللہ پاک کے نزدیک تمام آبادیوں میں محبوب ترین جگہیں اس کی مسجد یں ہیں اور بدترین مقامات بازار ہیں۔‘‘\n(مسلم، کتاب المساجد ومواضع الصلاة، باب فضل الجلوس...الخ، ص۲۶۴، حدیث:۱۵۲۸)\nحضرت سیِّدُنا ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ اللہ پاک کے سب سے آخری نبی، محمد عربی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو مسجد سے محبت رکھتا ہے اللہ پاک اس سے محبت فرماتا ہے۔‘‘(معجم اوسط، ۴/ ۴۰۰، حدیث:۶۳۸۳) \n¥مسجد میں اجتماع ذکر ونعت:\nحضرت سیِّدُنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ اللہ پاک آخری نبی، محمد عربی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جب تمہارا گزر جنت کی کیاریوں پرسے ہوتو اس میں سے کچھ نہ کچھ چن لیا کرو۔‘‘ صحابَۂ کرام علیہم الرضوان نے عرض کی: جنت کی کیاریاں کیا ہیں ؟ ارشاد فرمایا: ’’ذکر کے حلقے۔‘‘ (ترمذی ، کتاب الدعوات، ۵/ ۳۰۴، حدیث:۳۵۲۱)\nسیِّدُنا سعید بن مسیب رحمۃُ اللہ علیہ فرماتے ہیں: ’’جو مسجد میں بیٹھتا ہے وہ اپنے ربّ کریم کے حضور بیٹھتا ہے۔‘‘ سیِّدُنا محمد بن مسلم رحمۃُ اللہ علیہ نے فرمایا: تو پھراسے اچھی بات ہی کرنی چاہئے۔(زھد لابن المبارک، باب فضل المشی الی الصلاة…الخ، ص۱۴۰، رقم:۴۱۶) \n¥تلاوتِ قرآن کی فضیلت:\nحضرت سیِّدُنا عبد اللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو شخص کتاب اللہ میں سے ایک حرف پڑھے تو اسے ہر حرف کے بدلے ایک نیکی ملے گی ا ور ہر نیکی 10 نیکیوں کے برابر ہوگی۔ میں نہیں کہتا کہ المّ ایک حرف ہے بلکہ الف ایک حرف ہے، لام ایک حرف اور میم ایک حرف۔‘‘\n(ترمذی ، کتاب فضائل القراٰن عن رسول اللّٰہ، باب ماجآء فیمن قرا حرفا من القراٰن...الخ، ۴/ ۴۱۷، حدیث:۲۹۱۹)\nمسلمانوں کے تیسرے خلیفہ حضرت سیِّدُنا عثمان غنی رضی اللہ عنہ بیان کرتے ہیں کہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’تم میں بہترین شخص وہ ہے جس نے قرآن سیکھا اور دوسروں کو سکھایا۔‘‘\n(بخار ی، کتاب فضائل القراٰن، باب خیرکم من تعلم القراٰن...الخ، ۳/ ۴۱۰، حدیث:۵۰۲۷)\nحضر ت سیِّدُنا معا ذ جُہَنی رضی اللہ عنہ روایت کرتے ہیں کہ حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو شخص قرآن پڑھے اور اس پر عمل کرے تو قیامت کے دن اس کے ماں باپ کو ایسا تاج پہنایا جائے گا کہ اس کی روشنی دُنیا کے سورج کی روشنی سے بڑھ کرہوگی جب کہ سورج کو اتنا قریب فرض کر لیا جائے کہ گویا تمہارے گھروں میں اتر آیا ہے پھر تم سمجھ سکتے ہو کہ جب ماں باپ کا یہ مر تبہ ہوگا تو اس شخص کا کیا درجہ ہوگا جس نے قرآن کریم پر عمل کیا ہوگا۔‘‘\n(ابو داود، کتاب الوتر، باب فی ثواب قراء ة القراٰن، ۲/ ۱۰۰، حدیث:۱۴۵۳)\nحضرت سیِّدُنا عبد اللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جس شخص نے قرآنِ پاک سیکھا اور سکھایا اور جو کچھ قرآن شریف میں ہے اس پر عمل کیا تو قرآنِ کریم اس کی شفاعت کرے گا اور جنّت میں لے جائے گا۔‘‘(تاریخ مدینہ دمشق، ۴۱/ ۳)\nسیِّدُنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ رسولِ کریم صلّی اللہ علیہ وسلّم نے ارشاد فرمایا: ’’جس نے قراٰنِ عظیم کی ایک آیت سکھائی جب اس آیت کی تلاوت کی جائے گی تو سیکھانے والے کو ثواب ہوگا۔‘‘ (جمع الجوامع، ۷/ ۲۰۹، حدیث: ۲۲۴۵۶)\n¥سکینہ کیا ہے؟\nمفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں: سکینہ کے لفظی معنیٰ ہیں سکونِ قلب اور دلی اطمینان،اصطلاح میں سکینہ وہ فرشتوں کی جماعت ہے جو مؤمنوں پر مصیبت کے وقت اترتی ہے، ان کے دل ہاتھ میں لے لیتی ہے جس سے ان کے دل ٹھہر جاتے ہیں گھبراتے نہیں۔ رب (کریم ارشاد) فرماتا ہے: ’’ هُوَ الَّذِیْۤ اَنْزَلَ السَّكِیْنَةَ فِیْ قُلُوْبِ الْمُؤْمِنِیْنَ (پ۲۶، الفتح:۴، ترجمہ کنز الایمان:وہی ہے جس نے ایمان والوں کے دلوں میں اطمینان اتارا)۔‘‘ اور فرماتا ہے: ’’ اَنْزَلَ اللّٰهُ سَكِیْنَتَهٗ عَلٰى رَسُوْلِهٖ وَ عَلَى الْمُؤْمِنِیْنَ (پ۱۰، التوبة:۲۶، ترجمہ کنز الایمان: اللہ نے اپنی تسکین اتاری اپنے رسول پر اور مسلمانوں پر)۔‘‘یہاں دونوں معنیٰ بن سکتے ہیں۔ (مراٰۃ المناجیح، 8/367) ایک اور مقام پر مفتی صاحب سکینہ کی وضاحت کرتے ہوئے فرماتے ہیں: سکینہ اللہ (پاک) کی ایک مخلوق ہے جس کے اترنے سے دلوں کوچین نصیب ہوتا ہے، کبھی ابرکی شکل میں نمودار ہوتی ہے اور دیکھی بھی جاتی ہے،اس کی برکت سے دل سےغیْرِ خدا کا خوف جاتارہتا ہے۔ رحمت سے خالص رحمت مراد ہے جو بوقْتِ ذکر ذاکر (ذکر کرنے والے) کو ہرطرف سےگھیرتی ہے۔ فرشتوں سے سیّاحین (سیر وسیاحت کرنے والے) فرشتے مراد ہیں جو ذکر کی مجلسیں ڈھونڈتے پھرتے ہیں ورنہ اعمال لکھنے والے اورحفاظت کرنے والے فرشتے ہر وقت انسان کے ساتھ رہتے ہیں۔مقصد یہ ہے کہ جہاں مجمع کے ساتھ ذِکْرُاللہ ہورہا ہو وہاں یہ تین رحمتیں اترتی ہیں۔ اس سے معلوم ہوا کہ تنہا ذکر سے جماعت کا مِل کر ذکر کرنا افضل ہے، جماعت کی نماز کا درجہ زیادہ کہ اگر ایک کی قبول سب کی قبول۔(مراٰۃ المناجیح، 1/190)\n حضرت سیِّدُنا علامہ محمد بن علّان شافعی رحمۃُ اللہ علیہ فرماتے ہیں: اللہ پاک کے گھر میں جمع ہو کر تلاوتِ قرآن اور درس وتدریس کرنے والوں پر جو سکینہ نازل ہوتا ہے اس سے مراد وہ حالت اور کیفیت ہے جس سے دل مطمئن ہوجائے۔ اس سکینہ کا ذکر قرآنِ پاک میں بھی۔ چنانچہ اللہ پاک ارشاد فرماتا ہے:\nهُوَ الَّذِیْۤ اَنْزَلَ السَّكِیْنَةَ فِیْ قُلُوْبِ الْمُؤْمِنِیْنَ (پ۲۶، الفتح:۴)\nترجمہ کنزالایمان: وہی ہے جس نے ایمان والوں کے دلوں میں اطمینان اتارا۔\n تو جسے اِس بات کا علم اور یقین ہو کہ ساری کائنات کو اللہ پاک کی قدرت محیط ہے تو اس کا دل پُرسکون ہوتا ہے اور اسے اللہ پاک کی طرف سے ملنے والے اَجر کی قوی امید ہونے کی وجہ سے اطمینان حاصل ہوتا ہے۔ یہ بھی کہاگیا ہے کہ سکینہ سے مراد ایک فرشتہ ہے جو مومن کے دل پر نازل ہوتا اور اسے بھلائی کا حکم دیتا ہے۔ ایک قول یہ بھی ہے کہ سکینہ سے مراد رحمت، وقار، سکون اور خشیت ہے۔(دلیل الفالحین ، باب فی قضاءحوائج المسلمین...الخ ، ۲ / ۳۹ ، تحت الحدیث : ۲۴۶)\n¥اعلیٰ علیین میں تذکرہ:\nمفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’اللہ پاک اپنی بارگاہ میں جماعت کے سامنے ان کا تذکرہ فرماتا ہے‘‘ کی شرح میں فرماتے ہیں:یعنی فرشتوں کی جماعت (کے سامنے)۔ اس کی شرح و ہ حدیث ہے کہ فرمایا نبی صلّی اللہ علیہ وسلّم نے جو ربّ (کریم) کو اکیلے یاد کرے ربّ (کریم) بھی اسے ایسے ہی یاد کرتا ہے، جو جماعت میں یاد کرے ربّ (کریم) اسے فرشتوں میں یاد کرتا ہے۔ قرآن کریم( میں اللہ پاک) فرماتا ہے:’’ فَاذْكُرُوْنِیْۤ اَذْكُرْكُمْ (پ۲، البقرة:۱۵۲، ترجمہ کنز الایمان:تو میری یاد کرو میں تمہارا چرچا کروں گا)۔‘‘ اس ربّ (کریم) کی یاد کا اثر یہ پڑتا ہے کہ مخلوق اس بندے کو یاد کرنے لگتی ہے، بزرگوں کے مزارات پر زائرین کا ہجوم وہاں ذِکْرُ اللہ کی دھوم اسی یاد کا نتیجہ ہے۔(مراٰۃ المناجیح، 1/190)\n¥محض اعلیٰ نسب ہونا کافی نہیں عمل بھی ضروری ہے:\n ’’جس کا عمل اسے پیچھے کردے تو اُس کا نسب اسے آگے نہیں بڑھا سکتا‘‘کی شرح میں ہے: یعنی نسب کی شرافت عمل کی کمی کو پورا نہ کرے گی۔ کیا تمہیں خبر نہیں کہ (حضرت سیِّدُنا)نوح علیہِ السّلام کی کشتی میں کتے بلّوں کو جگہ تھی مگر ان کے کافر بیٹے کنعان کے لئے جگہ نہ تھی۔ مقصد یہ کہ شریْفُ النَّسب (لوگ) اعمال سے لاپروا نہ ہوجائیں، یہ منشاء نہیں کہ شرافَتِ نسب کوئی چیز نہیں۔ مؤمن کو نَسبُ الرسول ضرور فائدہ دے گا۔ تمام دنیا کی عورتیں حضرت فاطمہ زہرا ( رضی اللہ عنہا ) کے قدمِ پاک کو نہیں پہنچ سکتیں۔ربّ (کریم) نے بنی اسرائیل سے فرمایا: ’’ اَنِّیْ فَضَّلْتُكُمْ عَلَى الْعٰلَمِیْنَ(۴۷) (پ۱، البقرة:۴۷، ترجمہ کنز الایمان: اور یہ کہ اس سارے زمانہ پر تمہیں بڑائی دی)۔‘‘ بنی اسرائیل کے (اپنے زمانے کے)تمام عالَم پر افضل ہونے کی یہی وجہ تھی کہ وہ اولادِ انبیاءہیں لہٰذا یہ حدیث کسی آیت کے خلاف نہیں۔ (مراٰۃ المناجیح، 1/190)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6902, "bookId": 13, "volNo": "1", "hadithNo": 37, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "بندوں پر اللہ پاک کا عظیم لطف وکرم", "arabic": "عَن ابْنِ عَبَّاسٍ رَضیَ اللهُ عَنْہُمَا مَا عَنِ رَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِيْمَا يَرْوِيْهِ عَنْ رَبِّهٖ تَبَارَكَ وَتَعَالٰى قَالَ:’’اِنَّ اللهَ كَتَبَ الْحَسَنَاتِ وَالسَّيِّئَاتِ ثُمَّ بَيَّنَ ذٰلِكَ؛ فَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كَتَـبَهَا اللهُ عِنْدَهٗ حَسَنَةً كَامِلَةً وَّاِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَـبَهَا اللهُ عِنْدَهٗ عَشْرَ حَسَنَاتٍ اِلٰى سَبْعِمائَةِ ضِعْفٍ اِلٰى اَضْعَافٍ كَثِيْرَةٍ وَاِنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا كَتَـبَهَا اللهُ عِنْدَهٗ حَسَنَةً كَامِلَةً وَّاِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَـبَهَا اللهُ سَيِّئَةً وَّاحِدَةً.‘‘ (رَوَاهُ الْبُخَارِیُّ وَمُسْلِمٌ فِیْ صَحِيْحَيْهِمَا بِهٰذِهِ الحُرُوْف)", "urdu": "حضرت سیِّدُنا عبد اللہ بن عباس رضی اللہ عنہما حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم سے روایت کرتے ہیں اور یہ ان روایات میں سےہے جو آپ صلّی اللہ علیہ واٰلہٖ وسلّم اپنے رب سے روایت کرتے ہیں (یعنی حدیث قدسی ہے)، ارشاد فرمایا: ’’بے شک اللہ پاک نے اچھائیاں اور برائیاں لکھ دیں اور انہیں واضح فرما دیا، لہٰذا جو شخص کسی بھلائی کا ارادہ کرے لیکن عمل نہ کر پائے تو اللہ پاک اس کے لئے اپنے پاس ایک کامل نیکی کا ثواب لکھ دیتا ہے اور اگروہ کسی نیکی کاارادہ کرے اور عمل بھی کر لے تو اللہ کریم اپنے پاس اس نیکی کا ثواب 10سے 700 گنا بلکہ اس سے بھی زیادہ تک لکھ دیتا ہے اور اگر بندہ کسی گناہ کا ارادہ کرے مگر گناہ نہ کرے تو اللہ پاک اس کےلئے اپنے پاس ایک کامل نیکی کاثواب لکھ دیتا ہےاور اگر وہ گناہ کا ارادہ کر کے اسے کر گزرے تو اللہ پاک اس کے لئے صرف ایک گناہ لکھتا ہے۔‘‘(بخاری، كتاب الرقاق، باب من همّ بحسنة او بسيئة، ۴/ ۲۴۴، حدیث:۶۴۹۱۔ مسلم، کتاب الایمان، باب اذا ھم العبد بحسنة کتبت...الخ، ۷۴، حدیث:۳۳۸)\n (اس حدیث کو حضرت سیِّدُنا امام ابو عبداللہ محمد بن اسماعیل بخاری اور حضرت سیِّدُنا ابوحسین امام مسلم بن حجاج رحمۃ اللہ علیہما نے اپنی اپنی صحیح (بخاری ومسلم) میں انہی الفاظ میں روایت کیا ہے۔)", "roman": "Hazrat Sayyiduna Abdullah Bin Abbas Radiyallahu Anhuma, Rasoolullah Sallallahu Alaihi Wasallam se riwayat karte hain aur yeh un riwayaat mein se hai jo Aap Sallallahu Alaihi Wasallam apne Rabb se riwayat karte hain (yaani Hadees-e-Qudsi hai), irshad farmaya: ''Beshak Allah Paak ne achhaiyan aur buraiyan likh di aur unhein wazeh farma diya, lehaza jo Shakhs kisi bhalai ka irada kare lekin amal na kar paye toh Allah Paak us ke liye apne paas ek kaamil neki ka sawab likh deta hai aur agar woh kisi neki ka irada kare aur amal bhi kar le toh Allah Kareem apne paas us neki ka sawab 10 se 700 guna balkay us se bhi zyada tak likh deta hai aur agar banda kisi gunah ka irada kare magar gunah na kare toh Allah Paak us ke liye apne paas ek kaamil neki ka sawab likh deta hai aur agar woh gunah ka irada kar ke usay kar guzre toh Allah Paak us ke liye sirf ek gunah likhta hai.'' (Bukhari, Kitaab-ur-Riqaq, Baab Man Hamma Bi-Hasanatin Aw Bi-Sayyi'atin, 4/244, Hadees: 6491. Muslim, Kitaab-ul-Imaan, Baab Iza Hammal Abdu Bi-Hasanatin Kutibat... Al-Kh, 74, Hadees: 338). (Is Hadees ko Hazrat Sayyiduna Imam Abu Abdullah Muhammad Bin Ismail Bukhari aur Hazrat Sayyiduna Abu Hussain Imam Muslim Bin Hajjaj Rahmatullah Alayhima ne apni apni Saheeh (Bukhari-o-Muslim) mein inhi alfaaz mein riwayat kiya hai.)", "explanation": "¥اللہ پاک کا بندوں پر خاص کرم:\nحافظ ابن بطّال رحمۃُ اللہ علیہ اس حدیث شریف کے تحت فرماتے ہیں: اگر اللہ پاک کا یہ کرم نہ ہوتا تو کوئی بھی جنت میں داخل نہ ہوتا کیونکہ بندوں کے گناہ ان کی نیکیوں سے زیادہ ہوتے ہیں اور یہ اللہ پاک کا اپنے بندوں پر خاص فضل وکرم ہے کہ وہ ان کی نیکیوں کو بڑھا کر دُگنا ( بلکہ کئی گنا) کردیتا ہے اور ان کے گناہوں کو نہیں بڑھاتا اور اس نے نیکی کے ارادے کو بھی نیکی بنادیا ہے کیونکہ نیکی کا ارادہ کرنا یہ دل کا ایک فعل ہے جوکہ نیکی ہے۔ اگر یہ اعتراض کیا جائے کہ جس طرح نیکی کا ارادہ دل کا فعل ہے اسی طرح گناہ کا ارادہ بھی تو دل کا فعل ہے لیکن گناہ کے ارادے پر گناہ نہیں ملتا اس کی کیا وجہ ہے؟ اس کا جواب یہ ہے کہ جو گناہ کے کام سے رُک گیا تو اس نے اپنے گناہ کے ارادے کونیکی کے ارادے سے منسوخ کردیا اور برائی کی خواہش کرنے والے ارادے کی نفی کی تو یہ عمل اس کے دل کے نیک عمل میں سے ہوگیا اور اسی نیک عمل پر اس کے لئے ایک نیکی لکھ دی جاتی ہے اور یہ حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم کے اس فرمانِ عالیشان کی طرح ہے کہ ’’ ہر مسلمان پر صدقہ ہے۔‘‘ عرض کی گئی: یارسول اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! اگر مسلمان نیکی نہ کر سکے تو؟‘‘ ارشاد فرمایا: ’’ گناہ سے باز رہنا بھی صدقہ ہے۔‘‘ (شرح بخاری لابن بطال، كتاب الرقاق، باب من همّ بحسنة او بسيئة، ۱۰/ ۲۰۰)\n¥رضائے الٰہی ضروری ہے:\nحضرت سیِّدُنا علامہ بدر الدین عینی رحمۃُ اللہ علیہ فرماتے ہیں: جس نے کسی گناہ کا ارادہ کیا اور پھر اللہ پاک کی رضا کی خاطر اسے چھوڑ دیا تو اس کے لئے نیکی لکھی جائے گی اور جس نے مجبوراً گناہ چھوڑا یعنی اس کے اور گناہ کے درمیان کوئی رکاوٹ آگئی ہو تو ایسی صورت میں اس کے لئے نیکی نہیں لکھی جائے گی۔ \n(عمدةالقاری، كتاب الرقاق، باب من همّ بحسنة او بسيئة، ۱۵/ ۵۶۴، حدیث:۶۴۹۱)\n¥نیک نیت پر ملنے والی نیکی بھی کامل ہوتی ہے:\nحضرت سیِّدُنا علامہ حافظ ابن حجر عسقلانی رحمۃُ اللہ علیہ فرماتے ہیں: مذکورہ حدیث پاک کے ان الفاظ ’’عِنْدَہٗ کَامِلَۃٌ‘‘ میں ’’عِنْدَہٗ‘‘ سے نیکی کی عظمت وشان کی طرف اشارہ ہے جبکہ ’’کَامِلَۃٌ‘‘ سے اس بات کی طرف اشارہ ہے کہ نیک ارادے پر ملنے والی نیکی بھی کامل نیکی ہوگی اور اس میں کسی قسم کی کوئی کمی نہیں کی جائے گی۔ حضرت سیِّدُنا امام نووی رحمۃُ اللہ علیہ فرماتے ہیں: حدیث شریف کے لفظ ’’کَامِلَۃٌ‘‘ سے اس نیکی کی عظمت اور اس کے حکم کی تاکید کی طرف اشارہ ہے جبکہ\n ’’سَیِّئَۃٌ‘‘ کے ساتھ ’’کَامِلَۃٌ‘‘ نہیں بلکہ ’’وَاحِدَۃٌ‘‘ ذکر کیا گیا یعنی برائی کے کام میں صرف ایک ہی برائی لکھی جائے گی زیادہ نہیں۔ اور حدیث پاک کے جز ’’کَتَـبَہَا اللہ‘‘ سے مراد یہ ہے کہ اللہ پاک فرشتے کو نیکی لکھنے کا حکم دیتا ہے تو وہ نیکی لکھ دیتا ہے۔ اس کی دلیل یہ حدیث قدسی ہے: ’’اِذَا اَرَادَ عَبْدِیْ اَنْ یَّعْمَلَ سَیِّئَۃً فَلَاتَکْتَـبُوْہَا عَلَیْہِا حَتّٰی یَعْمَلَہَا یعنی اللہ پاک ارشاد فرماتا ہے کہ جب میرا بندہ کسی گناہ کا ارادہ کرے تو اسے نہ لکھو جب تک کہ وہ گناہ کر نہ لے۔‘‘ اس میں اس بات پر بھی دلیل ہے کہ فرشتہ بندے کے دل کو جان لیتا ہے۔ اب یہ جاننا دو طرح سے ہوسکتا ہے یا تو اللہ پاک اسے مطلع فرما دیتا ہے یا پھر اسے ایسی طاقت عطا فرمادیتا ہے جس سے وہ دل کے ارادے کو جان لیتا ہے۔ پہلے قول کی تائید اس حدیث پاک سے ہوتی ہے کہ ’’ ایک فرشتے کو یہ ندا کی جاتی ہے کہ فلاں کے لئے اتنی اتنی نیکی لکھو۔‘‘ فرشتہ عرض کرتا ہے: یارب! اس نے تو یہ عمل کیا ہی نہیں؟ ارشاد ہوتا ہے: ’’اس نے نیکی کی نیت کی تھی۔‘‘ (ایک قول یہ ہے کہ) بندے کے برے ارادے پر فرشتے کو بدبو محسوس ہوتی ہے جبکہ اچھے ارادے پر فرشتے کو خوشبو محسوس ہوتی ہے (تو یوں وہ اچھی بری نیت کو پہچان لیتا ہے)۔ (فتح الباری، كتاب الرقاق، باب من همّ بحسنة او بسيئة، ۱۲/ ۲۷۶، حدیث:۶۴۹۱)\n¥نیکیاں اور برائیاں لکھنے سے مراد:\nمفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’بے شک اللہ پاک نے اچھائیاں اور برائیاں لکھ دیں اور انہیں واضح فرما دیا ‘‘ کی شرح میں فرماتے ہیں: اس طرح کہ ربّ (کریم) کے حکم سے فرشتوں نے لوحِ محفوظ میں یا بندے کی تقدیر میں تحریر فرمادیں یا نامہ اعمال لکھنے والا فرشتہ لکھتا رہتا ہے۔ (مراٰۃ المناجیح، 3/384)\n¥نیکی و گناہ کی تعریف:\nخیال رہے کہ نیکی ہر وہ عمل ہے جو ثواب کا باعث ہو اور گناہ ہر وہ عمل ہے جو عذاب کا سبب ہے۔ لہٰذا ممنوعہ وقتوں میں نماز پڑھنا گناہ ہے اور حضور ( صلّی اللہ علیہ واٰلہٖ وسلّم ) پر نمازیں یا جان فدا کر دینا ثواب ہے۔کبھی قضا نیکی ہوجاتی ہے اور ادا گناہ۔\n(مراٰۃ المناجیح، 3/384)\n¥جان اور نماز آرامِ رسول پر قربان:\nمسلمانوں کے پہلے خلیفہ یارِ غار، یارِ مزار، عاشق اکبر حضرت سیِّدُنا ابو بکر صدیق رضی اللہ عنہ نے ہجرت کے موقع پر غارِ ثور میں خود کو سانپ سے کٹوا کر اپنی جان حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم پر قربان کر دی۔ (خازن، پ۱۰، التوبة، تحت الایة:۴۰، ۲/ ۲۴۰) اور مسلمانوں کے چوتھے خلیفہ مولائے کائنات، مولیٰ مشکل کشا علی المرتضیٰ، شیر خدا رضی اللہ عنہ نے خیبر سے واپسی پر مقام صہبا پر اپنی عصر کی نماز حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم کے آرام پر قربان کر دی۔ (معجم کبیر، ۲۴/ ۱۴۴، حدیث:۳۸۲)\nسیِّدِی اعلیٰ حضرت، امام اہلسنت، مولانا شاہ امام احمد رضا خان فاضل بریلوی رحمۃُ اللہ علیہ نے ان دونوں واقعات کو اشعار کی صورت میں یوں بیان فرمایا ہے:\nمولیٰ علی نے واری تِری نیند پر نماز اور وہ بھی عصر سب سے جو اعلیٰ خطر کی ہے\nصدیق بلکہ غار میں جان اُس پہ دے چکے اور حفظِ جان تو جان فُروضِ غُرر کی ہے\nہاں تو نے اُن کو جان اُنہیں پھیر دی نماز پر وہ تو کر چکے تھے جو کرنی بشر کی ہے\nثابت ہوا کہ جملہ فرائض فُروع ہیں اصْلُ الاصول بندگی اُس تاجور کی ہے\n (حدائق بخشش، ص203)\n¥ایک ہی نیکی پر مختلف ثواب کیوں؟\n سوال :کبھی ایک نیکی پر 10کا ثواب، کبھی سات اور کبھی اس سے بھی زیادہ، اس کی کیا وجہ ہے؟ جواب :اس کی ایک توجیہ یہ ہے کہ ثواب میں یہ فرق عمل کرنے والے کی نیت اورعمل کے موقع ومحل کی وجہ سے ہے۔ جس کے عمل میں جتنا اخلاص زیادہ ہو گا اسے اتنا ہی زیادہ اَجر وثواب ملے گا۔ صحابَۂ کرام علیہمُ الرّضوان کا سوا سیر جو خیرات کرنا ہمارے پہاڑوں برابر سونا خیرات کرنے سے افضل ہے کیونکہ ان کا اخلاص بہت اعلیٰ درجے کا تھا۔ انہیں رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم کی قُربت کی عظیم سعادت حاصل تھی۔ حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے صحابَۂ کرام علیہمُ الرّضوان کے مقام ومرتبے اور شان کو بیان کرتے ہوئے ارشاد فرمایا: ’’میرے صحابہ کو بُرا نہ کہو کیونکہ اگر تم میں سے کوئی احد (پہاڑ) جتنا سونا خیرات کرے تو نہ ان (صحابَۂ کرام علیہمُ الرّضوان)کے ایک مُد (ماپنے کاپیمانہ) کو پہنچے، نہ آدھے کو۔‘‘\n (بخاری، كتاب فضائل اصحاب النبی، باب قول النبی: لو کنت متخذا خلیلا، ۲/ ۵۲۲، حدیث:۳۶۷۳)\n¥نیکی کا ثواب 10¥ سے 700¥ گنا:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں: نیکی کرنے والے مسلمان کو ایک کا دس تو قانونًا وَعدلًا دیا جائے گا اور اس کے علاوہ فضل و کرم سے بطورِ انعام عطا ہوگا جو ہمارے گمان و وہم سے وراء (باہر) ہے۔ خیال رہے کہ ایک کا دس گنا عام حالات میں ہے رب تعالیٰ فرماتاہے: ’’ مَنْ جَآءَ بِالْحَسَنَةِ فَلَهٗ عَشْرُ اَمْثَالِهَاۚ (پ۸، الانعام:۱۶۰، ترجمہ کنز الایمان: جو ایک نیکی لائے تو اس کے لئے اس جیسی دس ہیں)۔‘‘ اور کبھی زمانہ یا جگہ کی خصوصیت سے ایک نیکی کا عوض سات سو یا پچاس ہزار بلکہ ایک لاکھ تک ہے۔ رب تعالیٰ فرماتا ہے: ’’ كَمَثَلِ حَبَّةٍ اَنْۢبَتَتْ سَبْعَ سَنَابِلَ فِیْ كُلِّ سُنْۢبُلَةٍ مِّائَةُ حَبَّةٍؕ-وَ اللّٰهُ یُضٰعِفُ لِمَنْ یَّشَآءُؕ (پ۳، البقرة:۲۶۱، ترجمہ کنز الایمان: اس دانہ کی طرح جس نے اوگائیں سات بالیں ہر بال میں سو دانے اور اللہ اس سے بھی زیادہ بڑھائے جس کے لیے چاہے)۔‘‘ یہ صرف نیکی کا عوض نہیں بلکہ اس و قت یا جگہ کی خصوصیت بھی ہے لہٰذا نہ تو گذشتہ مذکورہ آیتیں آپس میں متعارض ہیں اور نہ یہ حدیث دوسری احادیث کے خلاف جن میں فرمایا گیا کہ مدینہ پاک کی ایک نیکی کا ثواب پچاس ہزار ہے یا مکہ مکرمہ کی ایک نیکی کا ثواب ایک لاکھ۔ (مراٰۃ المناجیح، 3/307)\n نیز جس طرح اخلاص کے ساتھ کئے جانے والے عمل کا اجر بڑھ جاتا ہے اسی طرح بعض مقامات اوراوقات بھی ایسے ہیں کہ ان میں کئے گئے نیک اعمال کا وزن بڑھ جاتا ہے۔ چنانچہ\n¥مقامات اور اوقات کے اعتبار سے عمل کا ثواب:\nرسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’مسجد حرام میں ایک نماز پڑھنا ایک لاکھ نمازیں پڑھنے سے افضل ہے۔‘‘ \n(مسند احمد، ۵/ ۴۵۲، حدیث:۱۶۱۱۷)\nرسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’میری اس مسجد (یعنی مسجد نبوی)میں نماز پڑھنا مسجد حرام کے علاوہ دیگر مساجد میں ایک ہزار نماز یں پڑھنے سے افضل ہے اور میری اس مسجد میں جمعہ ادا کرنا مسجد حرام کے علاوہ دیگر مساجد میں ایک ہزار جمعے ادا کرنے سے افضل ہے اورمیری اس مسجد میں رمضان کا ایک مہینہ گزارنا مسجد حرام کے علاوہ دیگر مساجد میں ہزار ماہ رمضان گزارنے سے افضل ہے۔‘‘ (شعب الایمان، الخامس والعشرین وھو باب فی مناسک الحج، فضل الحج والعمرة، ۳/ ۴۸۶، حدیث:۴۱۴۷)\nایک روایت میں ہے کہ ’’آدمی کا اپنے گھر میں نماز پڑھنا ایک نماز کے برابر ہے اور محلے کی مسجد میں نماز پڑھنا 25 نمازوں کے برابر ہے اورجامع مسجد میں نَماز پڑھنا 500 نماز وں کے برابر ہے اور مسجد اقصیٰ اور میری مسجد(یعنی بیت المقدس اور مسجد ِ نبوی)میں نماز پڑھنا 50 ہزارنمازوں کے برابر ہے اور مسجد حرام میں نمازپڑھنا ایک لاکھ نمازوں کے برابر ہے۔‘‘ \n(ابن ماجة، کتاب اقامة الصلاة والسنة فیھا، باب ماجآء فی الصلاة فی المسجد الجامع، ۲/ ۱۷۶، حدیث:۱۴۱۳)\n¥خیالات کی اقسام اور ان کی تعریفات:\n یاد رکھئے! انسان کو مختلف قسم کے خیالات آتے ہیں، پھرکبھی تویہ خود بخود فوراًہی ختم ہوجاتے، کبھی کچھ وقت کے بعد کسی وجہ سے ختم ہوتے اورکبھی ایسے پختہ ہوتے ہیں کہ انہیں عملی جامہ پہنا دیا جاتا ہے۔تو ان اچھے برے خیالات پر عذاب وثواب ہونے یا نہ ہونے کے اعتبار سے علمائے کرام رحمۃُ اللہ علیہم نے خیالات کی پانچ قسمیں بیان فرمائی ہیں۔ چنانچہ\n حضرت سیِّدُنا علامہ احمد صاوی رحمۃُ اللہ علیہ فرماتے ہیں کہ خیالات پانچ قِسم کے ہیں: (1)... ہاجِس: دل میں اچانک کسی چیز کا خیال آ جانا۔ (2)... خاطر: دل میں کسی چیز کا بار بار خیال آنا۔ (3)...حدیث نفس: چیز کا خیال دل میں آیا ذہن اس کی طرف راغب ہو اور اس کے حصول کے لئے منصوبہ بنائے۔ (4)...ہَمّ: دل میں کسی چیز کا خیال آیا غالب جانب اسے حاصل کرنے کی ہو اورضَرَر ونقصان کے خوف کی وجہ سے مغلوب سا خیال اسے نہ کرنے کا ہو اور (5)...عزم: جب مغلوب جانب بھی زائل ہوجائے اور اپنے نفس کو اس کے حصول پر آمادہ کر کے اس چیز کے حصول کا پختہ ارادہ کر لے تو یہ عزم ہے۔ ’’ہاجس، خاطر، حدیث نفس اور ہَمّ‘‘ اگر گناہ کا ہو تو مواخذہ نہیں، ہاں نیکی کے ’’ہَمّ‘‘ میں اجر ہے اور ’’عزم‘‘اگر گناہ کا ہے تواس پر مواخذہ ہے اگرچہ گناہ نہ کر سکے۔اسی طرح نیکی کے ’’عزم‘‘ پر ثواب ہے اگرچہ کسی وجہ سے نیکی نہ کر سکے۔(حاشیة الصاوی، پ۳، البقرة، تحت الایة:۲۸۵، ۱/ ۲۴۳، ملخصًا)\n اِن پانچ مراتب کو اس مثال سے سمجھئے۔ مثلاً: کسی کے ذہن میں یہ خیال آیا کہ وہ چوری کرے تو یہ خیال ’’ہاجِس‘‘ ہے، اگر یہ خیال بار بار آئے تو ’’خاطر‘‘ ہے، جب اس کا ذہن چوری کی طرف مائل ہو جائے اور وہ یہ منصوبہ بنائے کہ فلاں مکان میں چوری کرنی ہے، اس کی فلاں دیوار توڑنی ہے، فلاں راستے سے واپس آنا ہے وغیرہ تو یہ ’’حدیث نفس‘‘ ہے اور جب وہ چوری کا اِرادہ کر لے اور غالب جانب چوری کرنے کی ہو لیکن مغلوب گمان یہ ہو کہ کہیں پکڑا نہ جاؤں لہٰذا چوری نہ کرنا ہی بہتر ہے، تو یہ ’’ہَمّ‘‘ ہے اور جب یہ مغلوب جانب بھی زائل ہوجائے اور وہ پختہ ارادہ کر لے کہ چوری ضرور کروں گا چاہے پکڑا ہی کیوں نہ جاؤں تو یہ ’’عزم‘‘ ہے۔ پہلے چار مرتبوں پر مواخذہ نہیں جبکہ پانچویں مرتبے یعنی ’’عزم‘‘ پر مواخذہ ہے اگرچہ وہ اپنے ’’عزم‘‘ پر کسی وجہ سے عمل نہ کر سکے۔ مثلاً: چوری کے ’’عزم‘‘ سے وہ کسی مکان میں داخل ہوا تو معلوم ہوا کہ یہاں تو کچھ ہے ہی نہیں، لہٰذا واپس آگیا تو اب اسے چوری کا گناہ ملے گاکیونکہ یہ چوری کا پختہ ارادہ کر چکا تھا اگر یہاں مال ہوتا تو ضرور چوری کرتا۔\n¥گناہ کا ارادہ:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ ایک مقام پرفرماتے ہیں: ”ھَم“ سے مراد ہے خیالِ گناہ اس پر پکڑ نہیں، عزم کے معنیٰ ہیں گنا ہ کا پورا ارادہ اس پر پکڑ ہے ،کسی کے قتل یا چوری کی تاک میں رہا مگر کرنہ سکا تو گنہگار ہوگیا ہاں خیالِ گناہ گناہ نہیں ہے بلکہ اس سے باز آجانا توبہ کرلینا نیکی ہے۔ (مراٰۃ المناجیح، 8/152)ایک اور مقام پر فرماتے ہیں: بغیر ارادہ گناہ صادر ہوجانا گناہ نہیں گناہ میں قصد و ارادہ عذاب کا باعث ہے اسی لیے حضور صلّی اللہ علیہ وسلّم نے عمل اور ارادہ دونوں کا ذکر فرمایا۔ (مراٰۃ المناجیح، 3/385)\n صدر الشریعہ، بدر الطریقہ حضرت علامہ مولانا مفتی محمد امجد علی اعظمی رحمۃُ اللہ علیہ نقل فرماتے ہیں: معصیت (گناہ)کا ارادہ کیا مگر اس کو کیا نہیں تو گناہ نہیں بلکہ اس میں بھی ایک قسم کا ثواب ہے، جبکہ یہ سمجھ کر باز رہا کہ یہ گناہ کا کام ہے، نہیں کرنا چاہیے۔ احادیث سے ایسا ہی ثابت ہے اور اگر گناہ کے کام کا بالکل پکا ارادہ کرلیا جس کو عزم کہتے ہیں تو یہ بھی ایک گناہ ہے اگرچہ جس گناہ کا عزم کیا تھا اسے نہ کیا ہو۔ (بہار شریعت، حصہ16، 3/614)\nحکایت: اچھی اور بُری نیت کا اثر\n منقول ہے کہ دو بھائی تھے، ایک عبادت گزار، دوسرا فاسق۔ عبادت گزار کی آرزو تھی کہ وہ شیطان کو دیکھے۔ چنانچہ ایک دن شیطان اس کے پاس انسانی شکل میں آیا اور کہا: ’’افسوس! تو نے اپنی عمر کے 40 قیمتی سال نفس کو قید اور بدن کومشقت میں ڈال کر ضائع کر دیئے ہیں۔ اب کچھ عیش وعشرت کی زندگی گزار، اپنی نفسانی خواہشیں پوری کرکے کیف وسرور حاصل کر کیونکہ ابھی تیری آدھی عمر باقی ہے بعد میں توبہ کرکے عبادت وریاضت اختیار کر لینا، بےشک اللہ پاک بخشنے والا، مہربان ہے۔‘‘ یہ سن کر عبادت گزار نے عزم( پختہ ارادہ)کر لیا کہ ’’میں نیچے جاکر اپنے بھائی کے پاس 20 سال عیش وعشرت سے گزاروں گا پھر توبہ کرکے اپنی عمر کے بقیہ 20 سال خوب عبادت کروں گا۔‘‘ چنانچہ وہ نچلی منزل پر آنے لگا ۔ ادھر اس کے گنہگاربھائی نے اپنے نفس سے کہا: ’’تو نے اپنی عمر کو نافرمانی میں ضائع کر دیا ہے، تیرا بھائی جنت میں جبکہ تو جہنم میں جائے گا۔ اللہ پاک کی قسم! میں ضرور توبہ کروں گا اور اپنے بھا ئی کے پاس جاکر بقیہ عمر عبادت میں گزاروں گا، شاید! اللہ پاک مجھے بخش دے۔‘‘ چنانچہ یہ توبہ کی نیت(یعنی پختہ ارادے) سے اوپر کی منزل پرچڑھنے لگا راستے میں دونوں کی ملاقات ہوئی اچانک ایک کا پاؤں پھسلا دونوں ایک دوسرے پر گرے اور فوراً ہی دونوں کا انتقال ہوگیا۔ بروزِ قیامت اس عابد کا حشر نافرمانی کی نیت پر ہو گا جبکہ گنہگار کا حشر توبہ کی نیت پر۔ (الروض الفائق، ص۱۶)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6903, "bookId": 13, "volNo": "1", "hadithNo": 38, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "اللہ پاک کے ولی کی شان", "arabic": "عَنْ اَبِيْ هُرَيْرَةَ رَضيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : اِنَّ اللهَ تَعَالٰى قَالَ: ’’مَنْ عَادَى لِيْ وَلِيًّا فَقَدْ اٰذَنْتُهٗ بِالْحَرْبِ. وَمَا تَقَرَّبَ اِلَيَّ عَبْدِيْ بِشَيْءٍ اَحَبَّ اِلَيَّ مِمَّا افْتَرَضْتُ عَلَيْهِ. وَمَا يَزَالُ عَبْدِيْ يَتَقَرَّبُ اِلَيَّ بِالنَّوَافِلِ حَتّٰى اُحِبَّهٗ، فَاِذَا اَحْبَبْتُهٗ كُنْتُ سَمْعَهُ الَّذِيْ يَسْمَعُ بِهٖ وَبَصَرَهُ الَّذِيْ يُبْصِرُ بِهٖ وَيَدَهُ الَّتِيْ يَبْطِشُ بِهَا وَرِجْلَهُ الَّتِيْ يَمْشِيْ بِهَا. وَاِنْ سَاَلَنِيْ اَعْطَیْتُہٗ وَلَئِنِ اسْتَعَاذَنِيْ لَاُعِيْذَنَّهٗ.‘‘ (رَوَاهُ الْبُخَارِیُّ)", "urdu": "حضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں: حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا کہ اللہ پاک کا فرمان ہے: ’’جس نے میرے کسی ولی سے دشمنی کی تو میں اس کے ساتھ جنگ کا اعلان کرتا ہوں۔ میرا بندہ جن چیزوں سے میرا قُرب حاصل کرتا ہے ان میں فرائض مجھے سب سے زیادہ محبوب ہیں اور نوافل کے ذریعہ بندہ میرے قریب ہوتا رہتا ہے یہاں تک کہ میں اسے اپنا محبوب بنا لیتا ہوں تو جب میں اسے اپنا محبوب بنا لیتا ہوں تو اس کے کان ہو جاتا ہوں جن سے وہ سنتا ہے، اس کی آنکھ ہو جاتا ہوں جن سے وہ دیکھتا ہے، اس کے ہاتھ ہو جاتا ہوں جن سے وہ پکڑتا ہے، اس کے پاؤں ہو جاتا ہوں جن سے وہ چلتا ہے، اگروہ مجھ سے مانگے تو ضرور اسے دوں گا اور اگر وہ مجھ سے پناہ طلب کرے تو میں ضرور اسے پناہ دوں گا۔‘‘ ( بخاری، كتاب الرقاق، باب التواضع، ۴/ ۲۴۸، حدیث:۶۵۰۲)", "roman": "Hazrat Sayyiduna Abu Hurairah Radiyallahu Anhu bayan karte hain: Rasoolullah Sallallahu Alaihi Wasallam ne irshad farmaya ke Allah Paak ka farman hai: ''Jis ne mere kisi Wali se dushmani ki toh main us ke saath jang ka elaan karta hoon. Mera banda jin cheezon se mera qurb hasil karta hai un mein faraiz mujhe sab se zyada mehboob hain aur nawafil ke zariye banda mere qareeb hota rehta hai yahan tak ke main usay apna mehboob bana leta hoon toh jab main usay apna mehboob bana leta hoon toh us ke kaan ho jata hoon jin se woh sunta hai, us ki aankh ho jata hoon jin se woh dekhta hai, us ke haath ho jata hoon jin se woh pakarta hai, us ke paon ho jata hoon jin se woh chalta hai, agar woh mujh se mange toh zaroor usay doon ga aur agar woh mujh se panah talab kare toh main zaroor usay panah doon ga.'' (Bukhari, Kitaab-ur-Riqaq, Baab-ut-Tawazu, 4/248, Hadees: 6502)", "explanation": "¥ولی کی تعریف:\nقرآن مجید میں اللہ پاک نے اپنے اولیا کی صفات ان کلمات سے بیان فرمائی ہے:\nاَلَاۤ اِنَّ اَوْلِیَآءَ اللّٰهِ لَا خَوْفٌ عَلَیْهِمْ وَ لَا هُمْ یَحْزَنُوْنَۚۖ(۶۲) الَّذِیْنَ اٰمَنُوْا وَ كَانُوْا یَتَّقُوْنَؕ(۶۳) (پ۱۱، یونس:۶۲، ۶۳)\nترجمہ کنزالایمان: سن لو بےشک اللہ کے ولیوں پر نہ کچھ خوف ہے نہ کچھ غم وہ جو ایمان لائے اور پرہیزگاری کرتے ہیں۔\n حضرت سیِّدُنا علامہ سعد الدین تفتازانی رحمۃُ اللہ علیہ فرماتے ہیں: ولی وہ ہے جو ممکنہ حدتک اللہ پاک اور اس کی صفات کا عارف ہو، ہمیشہ اُس کی عبادت کرتا ہواور ہرقسم کے گناہوں، لذات اورشہوات میں مشغولیت سے بچتا ہو۔\n(شرح العقائد، کرامات الاولیاء حق، ص۳۱۶)\nحضرت سیِّدُنا علامہ بدر الدین عینی رحمۃُ اللہ علیہ فرماتے ہیں: وَلِیُّ اللہ وہ شخص ہوتا ہے جو اللہ پاک (کی ذات و صِفات) کا عالِم ہو، ہمیشہ اللہ پاک کی اطاعت و فرمانبرداری کرے اور اللہ پاک کی عبادت میں مخلص ہو۔\n(عمدة القاری، کتاب الرقاق، باب التواضع ، ۱۵/ ۵۷۶، تحت الحدیث:۶۵۰۲)\n حضرت سیِّدُنا علّامہ علی قاری رحمۃُ اللہ علیہ فرماتے ہیں: وَلِیُّ اللہ وہ بندہ ہے جس کا اللہ پاک والی (مدد گار ودوست) ہو گیا کہ ایک لمحے کے لئے بھی اسے اس کے نفس کے حوالے نہیں کرتا بلکہ خود اس سے نیک کام لیتا ہے اور وہ بندہ ہے جو خود ربِّ کریم کی عبادت اور مسلسل اطاعت و فرمانبرداری کا متولّی ہوجائے گُناہوں سے محفوظ رہے۔ پہلی قسم کے ولی کا نام مجذوب یا مُراد ہے اور دوسرے کا نام سالِک یا مُرید ہے۔ (مرقاة المفاتیح، کتاب الدعوات، باب ذکر اللّٰہ والتقرب الیہ، ۵/ ۴۰، تحت الحدیث:۲۲۶۶)\n فقیہ اعظم ہند حضرت علامہ مولانا مفتی شریف الحق امجدی رحمۃُ اللہ علیہ فرماتے ہیں: ولی وہ مومن عارف باللہ ہے جو طاعات کو پوری پابندی کے ساتھ ادا کرتا رہے اور مُحَرَّمات سے بچتا رہے وہ بھی اللہ کی رضا کے لیے نہ کہ عزت وشہرت حاصل کرنے کے لیے اور دکھاوے کے لیے، اس لیے جو شریعت کا پابند نہیں وہ ولی نہیں ہوسکتا اگرچہ ہوا میں اڑے۔ جوگی جے پال حالَتِ کفر میں قادر تھے کہ اپنے حریف پر پتھر برسائیں ، آگ برسائیں ، خود ہوا میں اڑیں ، کیا اس وقت وہ ولی تھے؟ (ہرگز نہیں، اللہ پاک کا) ارشاد ہے: ’’ اِنْ اَوْلِیَآؤُهٗۤ اِلَّا الْمُتَّقُوْنَ (پ۹، الانفال: ۳۴) اللہ کے ولی وہ لوگ ہیں جو متقی ہیں۔‘‘\n( نزہۃ القاری، 5/ 669)\n¥ولی سے دشمنی رکھنا:\n شارح بخاری حضرت علامہ غلام رسول رضوی رحمۃُ اللہ علیہ فرماتے ہیں: (اللہ پاک ارشاد فرماتا ہے:)جو کوئی ولی سے عداوت (دشمنی) اس لیے کرتا ہے کہ وہ میرا ولی (دوست) ہے، میں اس سے جنگ کرتا ہوں اور اس کو ہلاک کرتا ہوں اور اس پر ایسے لوگ مسلط کرتا ہوں جو اس کو اذیت پہنچاتے رہیں ۔اُس شخص کی یہ رسوائی دنیا میں ہےآخرت کی خرابی اس کے علاوہ ہے۔ اللہ تعالیٰ مسلمانوں کو ایسی ذلت و رُسوائی سے پناہ دے۔ (تفہیم البخاری، 9/ 796)\n¥ولی سے عدا وت کا وبال:\nخیال رہے! دو قسم کے گناہ گاروں سے ربِّ کریم نے اعلانِ جنگ فرمایا ہے: (1)... اولیا کے دشمن سے (جیساکہ مذکورہ حدیث میں ارشاد ہوا’’مَنْ عَادَى لِيْ وَلِيًّا فَقَدْ اٰذَنْتُهٗ بِالْحَرْبِ یعنی جس نے میرے کسی ولی سے دشمنی کی تو میں اس کے ساتھ جنگ کا اعلان کرتا ہوں‘ ‘)۔ (2)...سود خور سے جیساکہ قرآنِ مجید میں ہے۔ چنانچہ ارشاد باری تعالیٰ ہے:\nیٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوا اتَّقُوا اللّٰهَ وَ ذَرُوْا مَا بَقِیَ مِنَ الرِّبٰۤوا اِنْ كُنْتُمْ مُّؤْمِنِیْنَ(۲۷۸) فَاِنْ لَّمْ تَفْعَلُوْا فَاْذَنُوْا بِحَرْبٍ مِّنَ اللّٰهِ وَ رَسُوْلِهٖۚ (پ۳، البقرة:۲۷۸، ۲۷۹)\nترجمہ کنزالایمان: اے ایمان والو اللہ سے ڈرو اور چھوڑ دو جو باقی رہ گیا ہے سود اگر مسلمان ہو پھر اگر ایسا نہ کرو تو یقین کرلو اللہ اور اللہ کے رسول سے لڑائی کا۔\n صرف انہی دو اعمال پر ایسی سخت وعید اس بات پر دلالت کرتی ہے کہ یہ دونوں عمل بہت خطرناک ہیں کیونکہ جب اللہ پاک کسی بندے سے جنگ فرمائے گا تو اس کا خاتمہ برا ہوگا کہ اللہ پاک سے جنگ کرنے والا کبھی کامیاب نہیں ہوسکتا۔\n (مرقاة المفاتیح، کتاب الدعوات، باب ذکر اللّٰہ والتقرب الیہ، ۵/ ۴۱، تحت الحدیث:۲۲۶۶)\n¥ولی سے دشمنی کا حکم:\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں: وَلِیُّ اللہ سے اس لئے عداوت وعناد (دشمنی وبغض رکھنا) کہ وَلِیُّ اللہ ہے یہ تو کفر ہے، اسی کا یہاں (حدیث شریف میں) ذکر ہے اور ایک ہے کسی ولی سے اختلافِ رائے یہ نہ کفر ہے نہ فسق۔ (مراٰۃ المناجیح، 3/ 308)\n¥فرائض پر عمل:\n’’فرائض مجھے سب سے زیادہ محبوب ہیں ‘‘کی شرح میں ہے: یعنی مجھ تک پہنچنے کے بہت ذریعے ہیں،مگر ان تمام ذرائع سے زیادہ محبوب ذریعہ ادائے فرائض ہے اسی لیے صوفیاء فرماتے ہیں کہ فرائض کے بغیر نوافل قبول نہیں ہوتے ان کا ماخذ یہ حدیث ہے افسوس ان لوگوں پر جو فرض عبادات میں سستی کریں اور نوافل پر زور دیں اور ہزار افسوس ان پر جو بھنگ،چرس حرام گانے بجانے کو خدا رسی کا ذریعہ سمجھے نماز روزے کے قریب نہ جائیں۔ (مراٰۃ المناجیح، 3/ 308)\n فقیہ اعظیم ہند حضرت علامہ مفتی شریف الحق امجدی رحمۃُ اللہ علیہ مذکورہ حدیث شریف کی شرح میں فرماتے ہیں: فرائض کی پابندی اور ادائیگی بہ نسبت نوافل کے افضل ہے اور یہ بالکل ظاہر ہے کہ فرائض اداکرنے میں ثواب کی امید ہے اور ترک میں عذاب کا استحقاق اور نوافل کی ادائیگی میں ثواب کی امید اور ترک پر کوئی گناہ نہیں۔ نیز فرائض مَامُوْربِہٖ ہیں (یعنی ان کے کرنے کا حکم دیا گیاہے) ان کا کرنے والا تابع فرمان ہے۔ اس میں آمر (یعنی حکم دینے والے) کی عظمت ظاہر ہے، اس میں عبودیت کا تذلل بھی ہے۔ نیز فرائض اصل ہیں اور نوافل فرع۔حتّٰی کہ حدیث میں فرمایا گیا کہ جو(شخص)فرائض ترک کیے(ہوئے) ہواور نوافل ادا کرے تو اس کے سارے نوافل زمین وآسمان کے درمیان مُعَلَّق رہیں گے مقبول نہ ہوں گے۔ اسی لیے علماء نے فرمایا:جس کے فرائض قضا ہوگئے ہوں وہ بجائے نوافل کے فرائض کی قضاکرے۔ (نزہۃ القاری، 5/ 669)\n¥فرائض کے ساتھ نوافل کی کثرت: \n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’نوافل کے ذریعہ بندہ میرے قریب ہوتا رہتا ہے یہاں تک کہ میں اسے اپنا محبوب بنا لیتا ہوں‘‘ کے تحت فرماتے ہیں: یعنی بندۂ مسلمان فرض عبادات کے ساتھ نوافل بھی ادا کرتا رہتا ہے حتّٰی کہ وہ میرا پیارا ہوجاتا ہے کیونکہ وہ فرائض و نوافل کا جامع ہوتا ہے۔(مرقات) اس کا مطلب یہ نہیں کہ فرائض چھوڑ کر نوافل ادا کرے محبت سے مراد کامل محبت ہے۔ (مراٰۃ المناجیح، 3/ 308)\n فقیہ اعظیم ہند حضرت علامہ مفتی شریف الحق امجدی رحمۃُ اللہ علیہ حدیث پاک کے جز ’’نوافل کے ذریعہ بندہ میرے قریب ہوتا رہتا ہے یہاں تک کہ میں اسے اپنا محبوب بنا لیتا ہوں‘‘ کی وضاحت کرتے ہوئے فرماتے ہیں: اس سے مراد یہ ہے کہ فرائض کی کَمَا حَقُّہُ ادائیگی کے بعد نوافل کی ادائیگی کرتا ہے۔یہ مطلب نہیں کہ فرائض چھوڑے اور نوافل ادا کرے پھر بھی محبوب ہوگا۔ اس لیے جو فرائض چھوڑے گا فاسق ہو گا وہ محبوب کیسے ہو گا؟ نوافل چونکہ بندہ اپنی طرف سے بخوشی ادا کرتا ہے اس ‏لیے نوافل ادا کرنے والا محبت کا مستحق ہوا۔ اس کی مثال یہ ہے کہ جیسے ایک شخص خدمت پر نوکر ہے جس کی تنخواہ لیتا ہےاورمتعلقہ خدمت کے سوا کچھ انجام نہیں دیتا وہ مشاہرے کا ضرورمستحق ہے اور وہ ایک اچھا نوکر بھی کہلائے گا مگر دوسرا نوکرمتعلقہ خدمات کے علاوہ مزید اپنی خوشی سے دوسری خدمات بھی انجام دیتا ہے یقیناً مالک اس دوسرے نوکر سے پہلے کی بہ نسبت زیادہ محبت کرے گا۔(نزہۃ القاری، 5/ 669)\n¥ جب بنده اللہ پاک کا محبوب بن جائے تو۔۔۔!\n امام نووی رحمۃُ اللہ علیہ فرماتے ہیں: جب اللہ پاک اپنے بندے سے محبت فرماتا ہے تو اسے اپنے ذکر اور فرمانبرداری میں مشغول کرکے شیطان کے شر سے محفوظ فرمادیتا ہے، اس کے سب اعضاء کو نیکیوں میں لگا دیتا ہے ۔قرآنِ پاک کی سماعت اور ذکرِ الٰہی کو اس کا محبوب ترین مشغلہ بنا دیتا ہے۔ گانے باجے اور دیگر لَغْویَات کو اس کے نزدیک بہت نا پسندیدہ کر دیتا ہے، پھروہ جاہلوں سے اعراض اور فحش کلامی سے اجتناب کرتا اور اپنی نظروں کو حرام اشیاء سے بچاتا ہے۔ پس اس کا دیکھنا غور وفکر اور عبرت پر مبنی ہوتا ہے، وہ مخلوق کودیکھ کر خالق کی قدرت پر دلیل پکڑتا ہے۔ حضرت سیِّدُنا علی المرتضیٰ شیر خدا رضی اللہ عنہ فرماتے ہیں: ’’میں کسی بھی چیز کو دیکھنے سے پہلے اپنے ربِّ کریم کی طرف متوجہ ہوتا ہوں۔‘‘ مخلوق کو دیکھ کر خالق کی قدرت کی طرف متوجہ ہونے کا مطلب یہ ہے کہ مخلوق کو دیکھ کر ان کے خالق کی تسبیح و تقدیس بیان کرے اور اس کی عظمت کا اقرار کرے، اپنے ہاتھ، پاؤں صرف اللہ پاک کے حکم کے مطابق استعمال کرے، کسی فضول کام کی طرف نہ چلے، اپنے ہاتھوں سے کوئی بےکار کام نہ کرے، اس کی حرکات وسَکَنات اللہ پاک کے لئے ہوں۔ جب بندے کی یہ حالت ہو جائے تو اسے اس کی تمام حرکات وسَکَنَا ت اور افعال پر ثواب دیا جاتا ہے۔ (شرح الاربعین النوویة، ص۱۲۹)\n حضرت سیِّدُنا امام شرفُ الدین حسین بن محمد طیبی رحمۃُ اللہ علیہ فرماتے ہیں: اللہ پاک کا بندے سے محبت کرنا یہ ہے کہ بندہ ہمیشہ مختلف عبادات کے ذریعےاس کاقرب حاصل کرنے کی کوشش کرتا رہتا ہے اور مختلف مجاہدات کے ذریعے ایک درجے سے دوسرے درجے کی طرف منتقل ہوتا رہتا ہے یہاں تک کہ اللہ پاک اس سے محبت کرنے لگتا ہے، پھروہ اللہ پاک کے جلوؤں میں اس طرح گُم ہوجاتاہے کہ جس طرف دیکھتا ہے اسے اللہ پاک کا ہی جلوہ نظر آتا ہے۔ یہ سالکین کا آخری اور واصلین کا پہلادرجہ ہے۔(شرح الطیبی، کتاب الدعوات، باب ذکر اللّٰہ والتقرب الیہ، ۴/ ۳۹۶، تحت الحدیث:۲۲۶۶)\n¥کان، آنکھ، ہاتھ اور پاؤں بن جانے سے مراد:\n حدیث پاک میں ارشاد ہوا کہ ’’اس کے کان ہو جاتا ہوں جن سے وہ سنتا ہے، اس کی آنکھ ہو جاتا ہوں جن سے وہ دیکھتا ہے، اس کے ہاتھ ہو جاتا ہوں جن سے وہ پکڑتا ہے، اس کے پاؤں ہو جاتا ہوں جن سے وہ چلتا ہے‘‘ علمائے کرام اور شارحین نے اس کے کئی معنیٰ بیان فرمائے ہیں۔ چنانچہ\n حضرت سیِّدُنا علامہ ابو زکریا یحییٰ بن شرف نووی رحمۃُ اللہ علیہ فرماتے ہیں کہ اس کے دو معنیٰ ہیں: (1)...میں اس کے کان، آنکھ،ہاتھ اور پاؤں کو شیطان کے شر سے محفوظ رکھتا ہوں ۔ (2)...جب وہ اپنے ہاتھ، کان یا پاؤں سے کوئی عمل کرتا ہے تو میری یاد اس کے دل میں بسی ہوتی ہے جب وہ میری طرف متوجہ ہوتا ہے تو غیر کے لئے کوئی کام نہیں کرتا (مراد یہ ہے کہ اس کے سب کام میری رضا کے لئے ہوتے ہیں)۔ (شرح الاربعین النوویة، ص۱۳۰)\n فقیہ اعظیم ہند حضرت علامہ مفتی شریف الحق امجدی رحمۃُ اللہ علیہ بیان کرتے ہیں کہ حضرت سیِّدُنا امام فخر الدِّین رَازی رحمۃُ اللہ علیہ نے سورۂ کہف کی تفسیر میں تحریر فرمایا کہ اللہ تعالیٰ اس کی قوتِ سماعت اتنی قوی کردیتا ہے کہ وہ بلند و پست، نزدیک و دور کی آواز یں سنتا ہےاور اس کی آنکھ میں اتنی نورانیت پیدا فرمادیتا ہے کہ قریب و بعید کی سب چیزیں دیکھتا ہے اور اس کے ہاتھ میں اتنی قوت پیدا فرمادیتا ہے کہ نرم اور سخت، ہمواراور پہاڑ اور دُور و نزدیک میں تصرف کرتا ہے۔\n(نزہۃ القاری، 5/ 670) \n سیِّدُنا علامہ بدر الدین عینی حنفی رحمۃُ اللہ علیہ فرماتے ہیں: یہ حدیث شریف اپنے مجازی معنیٰ پر محمول ہے اور اس سے مراد یہ ہے کہ اللہ پاک اپنے نیک بندے کی اس طرح حفاظت فرماتا ہے جیسے بندہ اپنے اعضاء کی خودحفاظت کرتا اور انہیں ہلاکت سے بچاتا ہے۔ حضرت سیِّدُنا امام خطّابی رحمۃُ اللہ علیہ فرماتے ہیں: اِس حدیث پاک میں سمجھانے کے لئے اِس طرح مثال دی گئی ہے اور معنیٰ یہ ہیں کہ اللہ پاک اپنے نیک بندے کو اِن چار اعضاء ( یعنی ہاتھ، زبان، کان اور پاؤں ) سے ہونے والے نیک اُمور کی پہچان کرا دیتا ہے۔پھر اِن نیک اَعمال کی محبت اِس کے دل میں ڈال کر اِنہیں اِس پرآسان کر دیتا ہے اوراِن اعضاءکو اپنی ناراضی والے کاموں مثلاً بُری باتیں سننا، ممنوع اشیاء کی طرف نظر کرنا ، حرام اشیاء کو پکڑنا، ناجائز اُمور کی طرف چلنا وغیرہ سے محفوظ کر دیتا ہے۔ یا پھر اِس پراِس طرح آسانی فرماتا ہے کہ اِس کی دعائیں اور حاجتیں جلدپوری فرماتا ہے۔\n(عمدة القاری، کتاب الرقاق ، باب التواضع، ۱۵/ ۵۷۷، تحت الحدیث:۶۵۰۲)\n¥شانِ باری تعالیٰ:\nمفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ فرماتے ہیں: اس عبارت کا یہ مطلب نہیں کہ خدا تعالیٰ ولی میں حلول کرجاتا ہے جیسے کوئلہ میں آگ یا پھول میں رنگ و بو کہ خدا تعالیٰ حلول سے پاک ہے اور یہ عقیدہ کُفْر ہے بلکہ اس کے چند مطلب ہیں: ایک یہ کہ وَلِیُّ اللہ کے یہ اعضاء گناہ کے لائق نہیں رہتے ہمیشہ ان سے نیک کام ہی سرزد ہوتے ہیں اس پر عبادات آسان ہوتی ہیں گویا ساری عبادتیں اس سے میں کرارہا ہوں یا یہ کہ پھر وہ بندہ ان اعضاء کو دنیا کے لئے استعمال نہیں کرتا، صرف میرے لئے استعمال کرتا ہے ہر چیز میں مجھے دیکھتا ہے ہر آواز میں میری آواز سنتا ہے، یا یہ کہ وہ بندہ فَنَا فِی اللہ ہوجاتا ہے جس سے خُدائی طاقتیں اس کے اعضاء میں کام کرتی ہیں اور وہ ایسے کام کرلیتا ہے جو عقل سے وراء ہیں حضرت یعقوب علیہِ السّلام نے کنعان میں بیٹھے ہوئے مِصْر سے چلی ہوئی قمیْصِ یوسفی کی خوشبو سونگھ لی، حضرت سلیمان علیہِ السّلام نے تین میل کے فاصلہ سے چیونٹی کی آواز سن لی حضرت آصف برخیانے پلک جھپکنے سے پہلے یمن سے تختِ بلقیس لاکر شام میں حاضِر کردیا۔ حضرت عمر نے مدینَۂ منوّرہ سے خطبہ پڑھتے ہوئے نہاوند تک اپنی آواز پہنچادی۔ حضورِ انور صلّی اللہ علیہ وسلّم نے قِیامت تک کے واقعات بچشم ملاحظہ فرمالئے۔ یہ سب اسی طاقت کے کرشمے ہیں۔ آج نار کی طاقت سے ریڈیو تار، وائرلیس، ٹیلی ویژن عجیب کرشمے دکھا رہے ہیں تو نور کی طاقت کا کیا پوچھنا۔ اس حدیث سے وہ لوگ عبرت پکڑیں جو طاقتِ اولیا کے منکر ہیں۔(مراٰۃ المناجیح، 3/ 308)\n¥مقبولیت کے درجے پر فائز:\nمفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’اگروہ مجھ سے مانگے تو ضرور اسے دوں گا اور اگر وہ مجھ سے پناہ طلب کرے تو میں ضرور اسے پناہ دوں گا‘‘ کے تحت فرماتے ہیں: یعنی (فرائض کی پابندی اور نوافل کی کثرت کرکے) وہ بندہ مقبول الدعاء بن جاتا ہے کہ مجھ سے خیر مانگے یا شر سے پناہ میں اس کی ضرور سنتا ہوں۔ معلوم ہوا کہ اولیاء ربّ تعالیٰ کی پناہ میں رہتے ہیں تو جو شخص ان سے دعا کرائے اس کی قبول ہوگی اور جو ان کی پناہ میں آئے وہ ربّ (کریم) کی پناہ میں آجائے گا۔\n (مراٰۃ المناجیح، 3/ 309)\n ¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6904, "bookId": 13, "volNo": "1", "hadithNo": 39, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "اللہ پاک کا اس امت پر ایک احسان", "arabic": "عَنِ ابْنِ عَبَّاسٍ رَضيَ اللهُ عَنْهُ مَا اَنَّ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَال: ’’اِنَّ اللهَ تَجَاوَزَ لِيْ عَنْ اُمَّتِيْ اَلْخَطَاَ وَالنِّسْيَانَ وَمَا اسْتُكْرِهُوْا عَلَيْهِ.‘‘ (حَدِيْثٌ حَسَنٌ رَوَاهُ ابْنُ مَاجَه والْبَيْهَقِیُّ وَغَيْرُهُمَا)", "urdu": "حضرت سیِّدُنا عبد اللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ اللہ پاک کے آخری نبی، محمد عربی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اللہ پاک نے میری وجہ سے میری امت کی غلطی، بھول اور جس پر وہ مجبور کئے جائیں ان گناہوں کو معاف فرمادیا ہے۔‘‘(ابن ماجہ، كتاب الطلاق، باب طلاق المكره والناسی، ۲/ ۵۱۳، حدیث:۲۰۴۵۔ سنن الکبری للبیھقی، کتاب الخلع والطلاق، باب ماجاء فی طلاق المکرہ...الخ، ۷/ ۵۸۴، حدیث:۱۵۰۹۶، ’’ان اللّٰہ تجاوز لی‘‘ بدلہ ’’وضع اللّٰہ‘‘)\n (یہ حدیث حسن ہے اسے حضرت سیِّدُنا امام ابن ماجہ، حضرت سیِّدُنا امام بیہقی رحمۃ اللہ علیہما اور دیگر محدثین نے روایت کیا ہے۔)", "roman": "Hazrat Sayyiduna Abdullah Bin Abbas Radiyallahu Anhuma se riwayat hai ke Allah Paak ke aakhri Nabi, Muhammad Arabi Sallallahu Alaihi Wasallam ne irshad farmaya: ''Allah Paak ne meri wajah se meri ummat ki ghalti, bhool aur jis par woh majboor kiye jayen un gunahon ko maaf farma diya hai.'' (Ibn Majah, Kitaab-ut-Talaq, Baab Talaq-ul-Mukrah wan-Naasi, 2/513, Hadees: 2045. Sunan-ul-Kubra lil-Baihaqi, Kitaab-ul-Khula wat-Talaq, Baab Ma Ja'a Fi Talaq-il-Mukrah... Al-Kh, 7/584, Hadees: 15096, ''Innallaha tajawaza li'' badla ''Wada'allahu''). (Yeh Hadees Hasan hai, isay Hazrat Sayyiduna Imam Ibn Majah, Hazrat Sayyiduna Imam Baihaqi Rahmatullah Alayhima aur deegar Muhaddiseen ne riwayat kiya hai.)", "explanation": "¥خطا اور نسیان کا معنیٰ ومفہوم:\n خطا یعنی غلطی کا مطلب ہے کہ انسان کام کا ارادہ نہیں کرتا مگر اس سے ہو جاتا ہےجیسے روزہ دار کلی کرے اور اسے معلوم ہے کہ میں روزے سے ہوں مگر پانی حلق سے اتر جائے تو یہ خطا ہے۔ نسیان یعنی بھول،اس میں بندہ کام تو ارادے سے کرتا ہے مگر یہ بھول جاتا ہے کہ ابھی یہ کام کرنا جائز نہ تھا جیسے روزہ دار کو اپنا روزہ دار ہونا یاد نہ ہو اور وہ کھا پی لے تو یہ بھول ہے۔اس حدیث کا مقصد یہ ہے کہ الله تعالیٰ نے میری امت پر یہ کرم فرمایا کہ ان کی بھول چوک معاف فرما دی، اس میں ان پر نہ گناہ ہوگا نہ پکڑ، ہاں بعض صورتوں میں شریعت کے احکام ضرور لاگو ہوں گے جیسے نماز میں بھول کر بات کرنے سے نماز ٹوٹ جاتی ہے یا قتل خطاء میں کفارہ یا دیت لازم ہوجاتے ہیں،نماز کا واجب بھول جانے سے سجدہ سہو واجب ہوجاتا ہے۔(مراٰۃ المناجیح، 8/ 596، ملخصاً)\n¥مجبوری میں کئے گئے گناہ:\n یعنی مسلمان جو برا کام مجبورًا کرلے تو وہ گنہگار نہ ہوگا لہذا مجبورًا منہ سے کفریہ بات بول دینے والا کافر نہ ہوگا، مجبورًا شراب پلائے جانے والا گنہگار نہ ہوگا۔یہاں بھی مذکورہ بالا معاملہ ہے کہ مجبوری کی صورت میں وہ گناہ گار نہیں ہو گا البتہ شریعت کے احکام جاری ہوں گے لہذا مجبور کی طلاق واقع ہوجاتی ہے یہی احناف کا مذہب ہے۔خیال رہے کہ ہر جرم کی مجبوری علیحدہ ہے کفر بکنے یا شراب پینے پر جان جانے کا خطرہ ہو تو یہ مجبوری ہے۔ (مراٰۃ المناجیح، 8/ 596، ملخصاً)\n¥اکراہِ شرعی کی تعریف:\n اکراہِ شرعی (یعنی شرعی مجبوری یا جسے مجبور کیا گیاوہ) یہ ہے کہ کوئی شخص کسی کوصحیح دھمکی دے کہ اگر توفلاں کام نہ کرے گا تومیں تجھے مار ڈالوں گا یا ہاتھ پاؤں توڑدوں گایاناک ،کان وغیرہ کوئی عضوکاٹ ڈالوں گایاسخت مارماروں گااوروہ یہ سمجھتاہوکہ یہ کہنے والاجوکچھ کہتاہے کرگزرے گا،تویہ اکراہِ شرعی ہے۔ (ماخوذازبہارشریعت، حصہ15، 3/ 189)\n¥امت محمدیہ پر خصوصی کرم:\nحضرت سیِّدُنا علامہ محمد بن عبد اللہ دمیاطی شافعی رحمۃُ اللہ علیہ فرماتے ہیں: اس حدیث شریف سے یہ ظاہر ہوا کہ خطا اور نسیان (یعنی غلطی اور بھول) کی صورت میں گناہ کی معافی اس امت کے ساتھ خاص ہے، حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم کے شرف کی وجہ سے (اس امت کو یہ خصوصیت حاصل ہوئی)۔ اسی لئے ہمیں حکم دیا گیا ہے کہ ہم کثرت سے یہ دعا مانگا کریں:\nرَبَّنَا لَا تُؤَاخِذْنَاۤ اِنْ نَّسِیْنَاۤ اَوْ اَخْطَاْنَاۚ (پ۳، البقرة:۲۸۶)\nترجمہ کنزالایمان: اے رب ہمارے ہمیں نہ پکڑ اگر ہم بھولیں یا چوکیں۔\n¥ اس طلب کے ساتھ کہ یہ عظیم نعمت ہمیشہ حاصل رہے۔\n نیز مروی ہے کہ ’’بنی اسرائیل کو جس چیز کا حکم دیا جاتا اگر وہ اسے بھول جاتے یا غلطی کرتے تو جلد انہیں سزا دے دی جاتی کہ اس گناہ کی وجہ سے کھانے پینے کی بعض حلال چیزیں بھی ان پر حرام کر دی جاتیں۔‘‘\n(الجواھر اللؤلؤیة للدمیاطی ، ص۵۴۳، تحت الحدیث:۳۹)¥\nبھولی ہوئی چیز یاد آجائے:\n سیِّدُنا انس رضی اللہ عنہ سے مرفوعاً مروی ہے کہ (نبی کریم صلّی اللہ علیہ وسلّم نے ارشاد فرمایا:) ’’اِذَا نَسِیْتُمْ شَیْئًا فَصَلُّوْا عَلَیَّ تَذْکُرُوْہُ اِنْ شَآءَ اللہ تَعَالٰی یعنی جب تم کسی چیز کو بھول جاؤ تو مجھ پر درودِ پاک پڑھو اللہ پاک نے چاہا تو وہ چیز تمہیں یاد آ جائے گی۔‘‘ \n(الجواھر اللؤلؤیة للدمیاطی، ص۵۴۴، تحت الحدیث:۳۹)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6905, "bookId": 13, "volNo": "1", "hadithNo": 40, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "دنیا میں مسافر یا راہ گزر کی طرح رہو", "arabic": "عَنِ ابْنِ عُمَرَ رَضيَ اللهُ عَنْهُ مَا قَالَ: اَخَذَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمنْكَبيَّ. فَقَالَ: ’’ كُنْ فِي الدُّنْيَا كَاَنَّكَ غَرِيْبٌ اَوْ عَابِرُ سَبِيْلٍ.‘‘ وَكَانَ ابْنُ عُمَرَ رَضيَ اللهُ عَنْهُ مَا يَقُوْلُ: اِذَا اَمْسَيْتَ فَلَاتَنْتَظِرِ الصَّبَاحَ وَاِذَا اَصْبَحْتَ فَلَاتَنْتَظِرِ الْمَسَاءَ. وَخُذْ مِنْ صِحَّتِكَ لِمَرَضِكَ وَمِنْ حَيَاتِكَ لِمَوْتِكَ. (رَوَاهُ الْبُخَارِیُّ)", "urdu": "حضرت سیِّدُنا عبد اللہ بن عُمَر رضی اللہ عنہما بیان کرتے ہیں کہ ایک مرتبہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے میرے دونوں کاندھوں کو ہاتھوں میں لے کر ارشاد فرمایا: ’’دنیا میں پر دیسی یا راہ گزر (یعنی آبائی وطن سے دور رہنے والے یامسافر)کی طرح رہو۔‘‘ حضرت سیِّدُنا عبد اللہ بن عُمَر رضی اللہ عنہما فرمایا کرتے تھے: جب تم شام کرو تو صبح کا انتظار مت کرو اور جب صبح کرو تو شام کا انتظار مت کرو، اپنی تندرستی میں بیماری کا حصہ لے لو اور اپنی زندگی میں موت کی تیاری کر لو۔\n( بخاری، كتاب الرقاق، باب قول النبی: كن فی الدنيا كانك غريب...الخ، ۴/ ۲۲۳، حدیث:۶۴۱۶)", "roman": "Hazrat Sayyiduna Abdullah Bin Umar Radiyallahu Anhuma bayan karte hain ke ek martaba Rasoolullah Sallallahu Alaihi Wasallam ne mere dono kandhon ko hathon mein le kar irshad farmaya: ''Duniya mein pardesi ya raah-guzar (yaani aabai watan se door rehne wale ya musafir) ki tarah raho.'' Hazrat Sayyiduna Abdullah Bin Umar Radiyallahu Anhuma farmaya karte thay: Jab tum shaam karo toh subah ka intezar mat karo aur jab subah karo toh shaam ka intezar mat karo, apni tandurusti mein bimari ka hissa le lo aur apni Zindagi mein maut ki tayyari kar lo. (Bukhari, Kitaab-ur-Riqaq, Baab Qaul-in-Nabi: Kun Fid-Dunya Ka'annaka Ghareeb... Al-Kh, 4/223, Hadees: 6416)", "explanation": "¥مذکورہ حدیث شریف کا معنیٰ ومفہوم:\n سیِّدُنا علامہ ابو زکریا یحییٰ بن شرف نووی رحمۃُ اللہ علیہ بیان کرتے ہیں کہ محدثین کرام رحمۃُ اللہ علیہم مذکورہ حدیث کی شرح میں فرماتے ہیں: مطلب یہ ہے کہ دنیا کی طرف مائل نہ ہو، دنیا کو وطن نہ بناؤ، نفس کو لمبی زندگی کی امید نہ دلاؤ اور دنیا کی طرف متوجہ نہ ہو، دنیا سے صرف اتنا تعلق رکھو جتنا گھر کی طرف لوٹنے والا مسافر دوسرے وطن سے رکھتا ہے۔\n (ریاض الصالحین، باب فضل الزھدفی الدنیا والحث...الخ، ص۱۴۹، تحت الحدیث:۴۷۱)\n¥کاندھا کیوں پکڑا؟\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’میرا کاندھا پکڑ کر فرمایا‘‘ کی شرح کرتے ہوئے فرماتے ہیں: کندھا پکڑنا قلبی فیض دینے کے لیے تھا قلبی فیض کے بغیر نصیحت اثر نہیں کرتی۔ (مرقات)زبان سے قال دیاجاتا ہے نگاہ سے حال عطا کیا جاتا ہے صرف قال بغیر حال مفید نہیں۔(مراٰۃ المناجیح، 7/ 90)\n¥مسافر و راہ گیر کا معنیٰ ومفہوم:\n مفتی صاحب حدیث پاک کے جز ’’دنیا میں مسافر یا راہ گیر کی طرح رہو‘‘ کی شرح میں فرماتے ہیں: غریب کہتے ہیں غریب الوطن مسافر کو (یعنی جو اپنا آبائی علاقہ چھوڑ کر دوسری جگہ ٹھہرے) اگرچہ وہ کسی جگہ چند دن ٹھہر جائے۔ مگر راہ گیر وہ ہے جو کسی جگہ دوپہری گزارنے کے لیے بیٹھ جائے۔ یہ دونوں سفر اور جنگل میں دل نہیں لگاتے تم بھی دنیا میں دل نہ لگاؤ، مسافروں کی طرح اگلی منزل کے لیے تیار رہو، دنیا منزل ہے آخرت وطن ، منزل پر کچھ دیر آرام کرلو مگر غافل ہو کر سو نہ جاؤ سفر کا سامان باندھے تیار رہو ، جب موت کی ریل آئے تمہیں تیار پائے ہر وقت اس کے منتظر رہو۔ (مراٰۃ المناجیح، 7/ 90، ملخصاً)\n¥مومن کا اصلی اور روحانی وطن:\n مفتی صاحب مزید فرماتے ہیں: جیسے مسافر منزل اور وہاں کی زیب و زینت سے دل نہیں لگاتاکیونکہ اسے آگے جانا ہوتاہے ایسے ہی تم یہاں کے انسان اور سامان سے دل نہ لگاؤ ، ورنہ مرتے وقت ان کے چھوٹنے سے بہت تکلیف ہوگی۔ صوفیاء جو فرماتے ہیں کہ ’’حُبُّ الْوَطَنِ مِنَ الْاِیْمَان یعنی وطن کی محبت ایمان کا رکن ہے۔‘‘ وہاں وطن سے مراد جنت ہے یعنی اصلی وطن یا مدینہ منورہ کہ وہ مومن کا روحانی وطن ہے۔ (مراٰۃ المناجیح، 2/ 438)\n¥مسافر کی زندگی:\n حضرت سیِّدُنا علامہ بدر الدین عینی رحمۃُ اللہ علیہ فرماتے ہیں: حدیث شریف میں مسافر کی طرح زندگی گزارنے کا حکم دیا گیا ہے مسافر کی چونکہ لوگوں سے جان پہچان بہت کم ہوتی ہے اسی وجہ سے اس میں حسد، عداوت، کینہ، نفاق اور مخالفت کم ہوتی ہے اور یہ تمام رذائل لوگوں سے میل جول رکھنے کی بنا پر ہی پیدا ہوتے ہیں۔ اسی طرح مسافر کے پاس وہ چیزیں بھی کم ہوتیں جو اسے اللہ پاک کی یاد سے غافل کریں جیسے مال، مکانات، باغات، کھیتی اور اہل و عیال وغیرہ ۔ اسی وجہ سے حدیث پاک میں مسافر کی طرح زندگی گزارنے کا کہا گیا ہے کہ نہ وہ خود بُری صفات کا حامل ہوتا ہے اور نہ اس کے پاس وہ چیزیں ہوتی ہیں جو اسےاللہ پاک کی یاد سے غافل کریں ۔\n(عمدة القاری، کتاب الرقاق، باب قول النبی: کن فی الدنیاکانک...الخ، ۱۵/ ۵۰۰، تحت الحدیث:۶۴۱۶، ملخصًا)\n¥شام کو صبح اور صبح کو شام کا انتظار مت کرو:\n حضرت ابن عمر ( رضی اللہ عنہما ) یہ اپنے نفس سے خطاب کرتے تھے کہ زندگی کی لمبی امیدیں نہ باندھو ہرنماز آخری نمازسمجھ کر پڑھو،تندرستی اور زندگی کو غنیمت جانو جس قدر ہوسکے اس میں نیکیاں کمالو،ورنہ بیماری میں اورموت کے بعد کچھ بن نہ پڑے گا۔ (کسی نے کیا خوب کہا ہے)شعر:\nکر جوانی میں عبادت کاہلی اچھی نہیں جب بڑھاپا آگیا پھربات بن پڑتی نہیں\nہے بڑھاپابھی غنیمت جب جوانی ہوچکی یہ بڑھاپابھی نہ ہوگا موت جس دم آگئی\n(مراٰۃ المناجیح، 2/ 438) \n¥پانچ کو پانچ سے پہلے غنیمت جانو:\n حضرت سیِّدُنا عبد اللہ بن عُمَر رضی اللہ عنہما نے جو اپنے نفس سے خطاب فرمایا کہ ’’ جب تم شام کرو تو صبح کا انتظار مت کرو اور جب صبح کرو تو شام کا انتظار مت کرو، اپنی تندرستی میں بیماری کا حصہ لے لو اور اپنی زندگی میں موت کی تیاری کر لو‘‘ یہی مفہوم ایک حدیث شریف میں بھی مذکور ہے۔ چنانچہ حضرت سیِّدُنا عمرو بن میمون اودی رضی اللہ عنہ بیان کرتے ہیں: رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ایک شخص کو نصیحت کرتے ہوئے ارشاد فرمایا کہ ’’پانچ چیزوں کو پانچ چیزوں سے پہلے غنیمت جانو: بڑھاپے سے پہلے جوانی کو، بیماری سے پہلے تندرستی کو، فقیری سے پہلے غنا کو، مصروفیت سے پہلے فرصت کو اور موت سے پہلے زندگی کو۔‘‘ (مشکاة المصابیح، کتاب الرقاق، الفصل الثانی، ۲/ ۲۴۵، حدیث:۵۱۷۴)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6906, "bookId": 13, "volNo": "1", "hadithNo": 41, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "اتباعِ رسول میں ہی نجات ہے", "arabic": "عَنْ اَبِيْ مُحَمَّدٍ عَبْدِ اللهِ بِنِ عمْرِو بْنِ الْعَاصِ رَضيَ اللهُ عَنْهُ مَا قَالَ: قَالَ رَسُولُ اللهِ: ’’لَا يُؤْمِنُ اَحَدُكُمْ حَتّٰى يَكُوْنَ هَوَاهُ تَبَعًا لِّمَا جِئْتُ بِهٖ.‘‘ (حَدِيْثٌ صَحِيْحٌ رَوَيْنَاهُ فِیْ كِتَابِ الْحُجَّةِ بِاِسْنَادٍ صَحِيْحٍ)", "urdu": "حضرت سیِّدُنا ابو محمد عبداللہ بن عَمْرو بن عاص رضی اللہ عنہما بیان کرتے ہیں کہ حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’تم میں سے کوئی شخص اس وقت تک کامل مومن نہيں ہوسکتا جب تک اس کی خواہشات میرے لائے ہوئے احکامات کے تابع نہ ہوجائیں۔‘‘ (نوادر الاصول فی احاديث الرسول، الاصل الثامن والسبعون والمائتان، ۶/ ۴۵۳)\n (یہ حدیث صحیح ہے اسے (حضرت سیِّدُنا امام محمد بن طاہر مقدسی رحمۃ اللہ علیہ نے) کتاب الحجۃ میں صحیح سند کے ساتھ روایت کیا ہے۔)", "roman": "Hazrat Sayyiduna Abu Muhammad Abdullah Bin Amr Bin Aas Radiyallahu Anhuma bayan karte hain ke Rasoolullah Sallallahu Alaihi Wasallam ne irshad farmaya: ''Tum mein se koi Shakhs us waqt tak kaamil momin nahin ho sakta jab tak us ki khwahishat mere laye hue ahkamaat ke tabe na ho jayen.'' (Nawadir-ul-Usool Fi Ahadis-ir-Rasool, Al-Asl-us-Samin-wal-Sab'oon wal-Mi'atain, 6/453). (Yeh Hadees Saheeh hai, isay (Hazrat Sayyiduna Imam Muhammad Bin Tahir Maqdisi Rahmatullah Alayh ne) Kitaab-ul-Hujjah mein Saheeh Sanad ke saath riwayat kiya hai.)", "explanation": "¥’’ہَویٰ‘‘کا معنیٰ ومفہوم:\nتفسیر روح البیان میں ہے: لفظ ’’ہَویٰ‘‘ کا استعمال اکثر نفسانی خواہشات اورممنوعہ لذات میں ہوتا ہے۔ اسی لیےنفسانی خواہشات کی پیروی کرنے والے کو بدعتی کہا جاتا ہے کیونکہ وہ دین کے معاملے میں اپنی خواہش کی طرف مائل ہوتا ہے۔پس ہَویٰ ایک مخصوص ومذموم میلان ہے۔ (روح البیان، پ۲۷، النجم، تحت الایة:۳، ۹/ ۲۱۲)¥\nکوئی مومن نہیں ہو سکتا جب تک۔۔۔!\n مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث شریف کی شرح کرتے ہوئے فرماتے ہیں: مؤمن وہ ہے کہ جس کا عمل میرے احکام کو پسند کرے اور اس کے علاوہ کو ناپسند۔لائے ہوئے میں حدیث و قرآن کے سارے احکام داخل ہیں کیونکہ یہ سب ربّ (کریم)کی طرف سے آئے اور ایمان سے مراد اصْلِ ایمان ہے اور واقعی جو کوئی کسی دینی چیز کو بُرا جانے وہ کافر ہے اور اس صورت میں حدیث پر نہ کوئی اعتراض ہے اور نہ کسی تاویل کی ضرورت، کوئی گنہگار، فاسق، بدکار گناہوں کو اچھا اور نیکیوں کو بُرا نہیں سمجھتا، اسی وجہ سے وہ مؤمن رہتا ہے اگرچہ فاسق ہو۔ (مراٰۃ المناجیح، 1/ 167)\n¥خواہشات شریعت کے تابع رہیں:\n حضرت سیِّدُنا علامہ عبد الغنی نابلسی رحمۃُ اللہ علیہم ذکورہ حدیث پاک کی شرح میں فرماتے ہیں: اس کا مطلب یہ ہے کہ تم میں سے ہرایک خواہ مرد ہو یا عورت کا میری لائی ہوئی شریعت اوراحکام جومیں اللہ پاک کی طرف سے لایاہوں، اس کی تصدیق واعتراف کرنا اس وقت تک کامل نہیں ہوسکتاجب تک اس کی خواہش یعنی میلان ، رغبت اورمحبت میری شریعت کے تابع نہ ہو جائے۔ یوں کہ اپنی رائے اورعقل سے کسی بھی حکم شرعی میں زیادتی اور کمی کواچھا نہ سمجھے اور اپنی نظر وفکرکے سبب کسی شے کوبرانہ جانے جس سے کسی حکْمِ شرعی کی مخالفت لازم آئے، بلکہ اس کی رائے ، عقل اور نظریہ، حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم کے فرامین کے ماتحت رہے۔ اس معاملے میں شریعت کے بیان کردہ حکم کو اختیارکرے نہ کہ اسی معاملے کو شریعت کا بیان کردہ حکم بتائے۔ (حدیقة ندیة، الباب الاول، النوع الثانی: الاعتصام بالسنة، الحدیث الحادی عشر، ۱/ ۲۷۰)\n¥خواہشات کی پیروی کی مذمت و ممانعت:\n قرآن مجید میں خواہشات کی پیروی سے منع کیا گیا اور خواہشات کی پیروی کرنے والوں کی مذمت بیان فرمائی گئی ہے۔ چنانچہ اللہ پاک ارشاد فرماتا ہے:\nوَ لَا تَتَّبِـعِ الْهَوٰى فَیُضِلَّكَ عَنْ سَبِیْلِ اللّٰهِؕ-اِنَّ الَّذِیْنَ یَضِلُّوْنَ عَنْ سَبِیْلِ اللّٰهِ لَهُمْ عَذَابٌ شَدِیْدٌۢ بِمَا نَسُوْا یَوْمَ الْحِسَابِ۠(۲۶) (پ۲۳، صٓ:۲۶)\nترجمہ کنزالایمان: اور خواہش کے پیچھے نہ جانا کہ تجھے اللہ کی راہ سے بہکا دے گی بےشک وہ جو اللہ کی راہ سے بہکتے ہیں ان کے لیے سخت عذاب ہے اس پر کہ وہ حساب کے دن کو بھول بیٹھے۔\n احادیث مبارکہ میں بھی خواہشات کی پیروی کی ممانعت بیان فرمائی گئی ہے۔ چنانچہ\n حضرت سیِّدُناشَدّادبن اَوس رضی اللہ عنہ روایت کرتے ہیں کہ رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا : ’’دانا وعقل مند وہ ہے جو اپنے نفس کو مُطِیع وتابعداربنائے اور موت کے بعد کے لئے عمل کرے اور عاجز وبے بس وہ ہے جونفسانی خواہش کی پیروی کرے اورپھراللہ پاک کی رحمت پرامیدبھی رکھے۔‘‘ (ترمذی، کتاب صفة القیامة، باب۲۵، ۴/ ۲۰۸، حدیث:۲۴۶۷)\n حضرت سیِّدُنا عبد اللہ بن عُمَر رضی اللہ عنہما بیان کرتےہیں: حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا کہ ’’تین چیزیں ہلاکت میں ڈال دیتی ہیں: (1)...بخل جس کی اطاعت کی جائے، (2)...خواہشات جن کی پیروی کی جائے اور (3)...بندے کا خود کو اچھا جاننا۔‘‘ (معجم اوسط، ۴/ ۲۱۲، حدیث:۵۷۵۴)\n¥خواہشات کی مخالفت کرنے کی فضیلت:\n قرآن وحدیث میں جس طرح خواہشات سے بچنے کا حکم دیا گیا اور ان کی پیروی کی مذمت بیان کی گئی ہے اسی طرح خواہشات کی مخالفت کرنے کی فضیلت بھی بیان ہوئی ہے۔ چنانچہ اللہ پاک ارشاد فرماتا ہے:\nوَ اَمَّا مَنْ خَافَ مَقَامَ رَبِّهٖ وَ نَهَى النَّفْسَ عَنِ الْهَوٰىۙ(۴۰) فَاِنَّ الْجَنَّةَ هِیَ الْمَاْوٰىؕ(۴۱) (پ۳۰، النٰزعٰت:۴۰، ۴۱)\nترجمہ کنزالایمان: اور وہ جو اپنے رب کے حضور کھڑے ہونے سے ڈرا اور نفس کو خواہش سے روکا تو بےشک جنت ہی ٹھکانا ہے۔\nحضرت سیِّدُنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ کچھ لوگ جہاد سے واپسی پر بارگاہِ رسالت میں حاضر ہوئے تو حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’تم آگئے، خوش آمدید! اور تم چھوٹے جہاد سے بڑے جہاد کی طرف آئے ہو۔‘‘ انہوں نے عرض کی:بڑا جہاد کیا ہے؟ارشاد فرمایا: ’’بندے کا اپنی خواہشوں سے جہاد کرنا۔‘‘\n( الزھد الکبیر للبیھقی، فصل فی ترک الدنیا ومخالفة النفس، ص۱۶۵، حدیث:۳۷۳)\nحضرت سیِّدُنا فضالہ بن عبید رضی اللہ عنہ سے روایت ہے کہ اللہ پاک کے آخری نبی، محمد عربی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’مجاہد وہ ہے جو اللہ پاک کی فرمانبرداری میں اپنے نفس سے لڑتا ہے۔‘‘\n(مسند احمد، مسند فضالة بن عبید الانصاری، ۹/ ۲۴۹، حدیث:۲۴۰۱۳)\n حضرت سیِّدُنا یحییٰ بن معاذ رازی رحمۃُ اللہ علیہ فرماتے ہیں کہ انسان کے دشمن تین ہیں: (1)...اس کی دنیا، (2)...شیطان اور (3)...نفس۔ لہٰذا دنیا سے بے رغبتی اختیار کر کے اس سے بچو، شیطان کی مخالفت کر کے ا س سے محفوظ رہو اور خواہشات کو چھوڑ دینے کے ذریعے نفس سے حفاظت میں رہو۔\n( احیاء علوم الدین، کتاب ریاضة النفس وتھذیب الاخلاق، بیان شواھد النقل من ارباب البصائر...الخ، ۳/ ۸۱)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}, {"id": 6907, "bookId": 13, "volNo": "1", "hadithNo": 42, "chapter": "", "subChapter": "", "narrator": "", "hadeesName": "رحمَتِ الٰہی کی وسعت", "arabic": "عَنْ اَنَسٍ رَضيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: قَالَ اللهُ تَعَالٰی: ’’يَا ابْنَ اٰدَمَ اِنَّكَ مَا دَعَوْتَنِيْ وَرَجَوْتَنِيْ غَفَرْتُ لَكَ عَلٰى مَا كَانَ مِنْكَ وَلَا اُبَالِيْ. يَا ابْنَ اٰدَمَ لَوْ بَلَغَتْ ذُنُوْبُكَ عَنَانَ السَّمَآءِ ثُمَّ اسْتَغْفَرْتَنِيْ غَفَرْتُ لَكَ. يَا ابْنَ اٰدَمَ اِنَّكَ لَوْ اَتَيْتَنِيْ بِقِرَابِ الْاَرْضِ خَطَايَا ثُمَّ لَقِيْتَنِيْ لَاتُشْرِكُ بِيْ شَيْئًا لَّاَتَيْتُكَ بِقِرَابِهَا مَغفِرَةً.‘‘\n(رَوَاهُ التِّرْمَذِیُّ وَقَالَ: حَدِيْثٌ حَسَنٌ)", "urdu": "حضرت سیِّدُنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: میں نے رَسُولُ الله صلّی اللہ علیہ واٰلہٖ وسلّم كو ارشاد فرماتے سنا کہ الله پاک ارشاد فرماتا ہے: ’’اے ابن آدم! تو مجھ سے جو بھی دعا مانگتا ہے اورمجھ سے امید بھی رکھتا ہے تو میں تیری نافرمانیوں کے باجود تجھے بخش دیتا ہوں اور مجھے اس کی کوئی پرواہ نہیں۔ اے ابن آدم! اگر تیرے گناہ آسمان کی بلندیوں کو پہنچ جائیں پھرتو مجھ سے بخشش طلب کرے تو میں تجھے بخش دوں گا۔ اے ابن آدم! اگرتو میرے پاس زمین بھر خطائیں لے کرآئے مگر مجھ سے اس حال میں ملے کہ تو نے کسی کو میرا شریک نہ ٹھہرایا ہو تو میں تجھے زمین بھر بخشش عطا کروں گا۔‘‘ \n(ترمذی، كتاب الدعوات عن رسول الله صلى الله عليہ وسلم، باب فی فضل التوبة والاستغفار...الخ، ۵/ ۳۱۹، حدیث:۳۵۵۱)\n (اس حدیث کو حضرت سیِّدُنا امام ابو عیسیٰ محمد بن عیسیٰ ترمذی رحمۃ اللہ علیہ نے روایت کیا اور فرمایا: یہ حدیث حسن ہے۔)", "roman": "Hazrat Sayyiduna Anas Bin Malik Radiyallahu Anhu bayan karte hain: Main ne Rasoolullah Sallallahu Alaihi Wasallam ko irshad farmate suna ke Allah Paak irshad farmata hai: ''Aye Ibn-e-Aadam! Tu mujh se jo bhi Dua mangta hai aur mujh se umeed bhi rakhta hai toh main teri nafarmaniyon ke bawajood tujhe bakhsh deta hoon aur mujhe is ki koi parwah nahin. Aye Ibn-e-Aadam! Agar tere gunah aasman ki bulandiyon ko pahunch jayen phir tu mujh se bakhshish talab kare toh main tujhe bakhsh doon ga. Aye Ibn-e-Aadam! Agar tu mere paas Zameen bhar khatayen le kar aaye magar mujh se is haal mein mile ke tu ne kisi ko mera shareek na thehraya ho toh main tujhe Zameen bhar bakhshish ata karoon ga.'' (Tirmidhi, Kitaab-ud-Da'waat An Rasoolillah Sallallahu Alaihi Wasallam, Baab Fi Fazl-it-Tawbati wal-Istighfaar... Al-Kh, 5/319, Hadees: 3551). (Is Hadees ko Hazrat Sayyiduna Imam Abu Isa Muhammad Bin Isa Tirmidhi Rahmatullah Alayh ne riwayat kiya aur farmaya: Yeh Hadees Hasan hai.)", "explanation": "¥کفر وشرک کے سوا تمام گناہوں کی معافی ہے:\n مذکورہ حدیث شریف میں اللہ پاک نے اپنے بندوں کو اپنی ذات سے حددرجے کے حسن ظن کی تعلیم ارشاد فرمائی ہے کہ اے میرے بندو ! تمہارے گناہوں سے اگر زمین وآسمان بھی بھرجائیں اور تم مجھ سے ان گناہوں کی معافی طلب کرو تو میں ان تمام گناہوں کو معاف کردوں گا۔ واضح رہے کہ اللہ پاک ہر گناہ کو معاف فرمادے گا مگر کفر وشرک کی حالت میں مرنے والے کو ہرگز معاف نہ فرمائے گا۔ یہ حدیث پاک قرآنِ مجید کی اس آیت مبارکہ کی تفسیر ہے۔\n چنانچہ اللہ پاک ارشاد فرماتا ہے: \nاِنَّ اللّٰهَ لَا یَغْفِرُ اَنْ یُّشْرَكَ بِهٖ وَ یَغْفِرُ مَا دُوْنَ ذٰلِكَ لِمَنْ یَّشَآءُۚ (پ۵، النسآء:۴۸)\nترجمہ کنزالایمان: بےشک اللہ اسے نہیں بخشتا کہ اس کے ساتھ کفر کیا جائے اور کفر سے نیچے جو کچھ ہے جسے چاہے معاف فرما دیتا ہے۔\n¥اللہ پاک کی رحمت اس کے غضب پر حاوی ہے:\n حضرت سیِّدُنا علامہ علی قاری رحمۃُ اللہ علیہ فرماتے ہیں کہ اللہ پاک بندے سے ارشاد فرماتاہے: تو کتنا ہی بڑا گناہ گار ہو تیرے گناہوں کو بخشنا میرے لئے کوئی بڑی بات نہیں کیونکہ میری رحمت میرے غضب پر غالب ہے۔ ابن آدم جنس ہے اور اس سے تمام اولاد آدم مراد ہے۔) مرقاة المفاتیح، کتاب الدعوات، باب الاستغفاروالتوبة، ۵/ ۱۶۹، تحت الحدیث:۲۳۳۶)\n¥اطاعت کی قبولیت اور گناہ کی معافی ایمان پر موقوف ہے:\n حضرت سیِّدُنا علامہ محمد بن علان شافعی رحمۃُ اللہ علیہ اس حدیث شریف کی شرح میں فرماتے ہیں: مراد یہ ہے کہ میں تیرے تمام گناہوں کومٹادوں گا جیسے کفر ہے تو اسے ایمان لانے کے ساتھ اورجو اس کے علاوہ گناہ ہیں انہیں توبہ واستغفار کے ذریعے مٹادوں گااورمجھے اس بات کی کوئی پرواہ نہیں کہ تیرے گناہ چھوٹے ہوں یا بڑے۔ اے ابن آدم ! اگر تیرے گناہ آسمان کے کناروں تک پہنچ جائیں یعنی آسمان اور زمین کے درمیانی خلا کو بھر دیں پھر تو مجھ سے مغفرت کاسوال کرے گا تو میں تجھے بخش دوں گاکیونکہ اللہ پاک کریم ہے، لغزشوں کومعاف فرماتا اورنیکیوں کوقبول کرتاہے۔ یہ مثال اللہ پاک کے کرم، فضل اور اس کی رحمت پر دلالت کرتی ہے جس کی کوئی انتہانہیں۔ (بڑے سے بڑے گناہ کی معافی ہے بشرطیکہ)تومجھ سے اس حال میں ملے کہ میرے ساتھ کسی کو شریک نہ ٹھہرائے۔ یعنی گناہوں کی معافی اس وقت ہوگی جب اللہ پاک پر ایمان لائے گاکیونکہ اطاعت کو قبول کرنا اورگناہوں کومعاف کرنا ایمان پرموقوف ہے۔\n(دلیل الفالحین، باب فضل الرجاء، ۲/ ۳۵۵، تحت الحدیث:۴۴۲)\n¥گناہ کے مطابق بخشش :\n مشہور شارح حدیث، حکیم الامت مفتی احمد یار خان نعیمی رحمۃُ اللہ علیہ حدیث شریف کے جز ’’اے ابن آدم! تو مجھ سے جو بھی دعا مانگتا ہے اورمجھ سے امید بھی رکھتا ہے تو میں تیری نافرمانیوں کے باجود تجھے بخش دیتا ہوں‘‘کی شرح میں فرماتے ہیں: یعنی تیرے کیسے ہی گناہ ہوں میں بخش دوں گا ، میں آنے والے کونہیں دیکھتا بلکہ اپنے دروازے کو دیکھتا ہوں کہ کس دروازے پر آیا ہے اورصوفیائے کرام اس کے معنیٰ کرتے ہیں مطابق یعنی تجھے تیرے گناہ کے مطابق بخشوں گا، چھوٹے گناہ کی چھوٹی بخشش، بڑے گناہ کی بڑی بخشش، لاکھوں گناہو ں کی لاکھوں بخششیں بلکہ حقیقت تو یہ ہے۔ شعر\nگنہ رضا کا حساب کیا وہ اگرچہ لاکھوں سے ہیں سوا مگر اے کریم تیرے عفو کا نہ حساب ہے نہ شمار ہے\n¥ہر طرف تیرے گناہ ہوں بیچ میں تو۔۔۔!\n اور حدیث پاک کے جز ’’اے ابن آدم! اگر تیرے گناہ آسمان کی بلندیوں کو پہنچ جائیں‘‘ کی شرح میں فرماتے ہیں: مطلب یہ ہے کہ اگر تو گناہوں میں ایسا گھر جائے جیسے زمین آسمان سے گھری ہوئی ہے کہ ہر طرف تیرے گناہ ہوں، بیچ میں تُو ہو، پھر مجھ سے معافی مانگے، تو میں تیرے سارے گناہ بخش دوں گا، ۔(مراٰۃ المناجیح، 3/ 362)\n¥گناہ گار کی بخشش ہے غدار کی نہیں:\n اور حدیث شریف کے جز ’’میں تجھے زمین بھر بخشش عطا کروں گا‘‘ کی شرح میں فرماتے ہیں: مطلب یہ ہے کہ جیسے رازق ہر مرزوق کو بقدرِ حاجت روٹی دیتا ہے، ہاتھی کو مَن اور چیونٹی کو کَن ( ذَرہ) دیتا ہے، ایسے ہی وہ غفار بقدرِ گناہ مغفرت عطا فرمائے گا مگر شرط یہ ہے کہ گنہگار ہو ، غدار نہ ہو ۔ اسی لیے شرط لگائی گئی کہ میرا شریک نہ ٹھہراتا ہو۔ خیال رہے کہ ایسے مقامات پر شرک بمعنیٰ کفر ہوتا ہے۔ رب تعالیٰ فرماتا ہے:’’ اِنَّ اللّٰهَ لَا یَغْفِرُ اَنْ یُّشْرَكَ بِهٖ (پ۵، النسآء:۴۸، ترجمہ کنز الایمان: بے شک اللہ اسے نہیں بخشتا کہ اس کے ساتھ کفر کیا جائے)اور نبی یا کتاب یا اسلامی احکام میں سے کسی کا انکار در حقیقت رب تعالیٰ کا ہی انکار ہے، لہٰذا حدیث بالکل واضح ہے، اور اس میں کفار کی مغفرت کا وعدہ نہیں، کفر ومغفرت میں تضاد ہے۔\n(مراٰۃ المناجیح، 3/ 363)\n¥دعا: \nاللہ پاک کی بارگاہ میں دعا ہے کہ ہمیں حدیث پاک اور اس کی شرح میں موجود مشمولات پر عمل کرنے کی توفیق\nعطا فرمائے۔اٰمین بِجاہِ النّبیِّ الْاَمین صلّی اللہ علیہ واٰلہٖ وسلّم"}];
